// Rank 0 is the group's unranked entry role ("Guest"). Every group member holds
// some role, so it is neither a ladder rank nor a migration target.
const NON_LADDER_RANKS = new Set([0]);

// The default join role Roblox creates ("Member") sits at rank 1 next to the real
// community tier ("Sweetsiez Supporter"). It must never be treated as a rank owner,
// a promotion target or a demotion target — that produced "Next Promotion: Member".
// The role id is authoritative; the name is a fallback for a recreated role.
const IGNORED_GROUP_ROLE_IDS = new Set(["12884901889"]);
const IGNORED_GROUP_ROLE_NAMES = new Set(["member"]);

function isIgnoredGroupRole(role) {
  if (!role) return false;
  if (role.id !== undefined && role.id !== null && IGNORED_GROUP_ROLE_IDS.has(String(role.id))) {
    return true;
  }
  const name = String(role.name || "").trim().toLowerCase();
  return name !== "" && IGNORED_GROUP_ROLE_NAMES.has(name);
}

// Ranks that disappear. 15/17/18 were never real ranks in this group but are
// still referenced by a few legacy checks.
const RETIRED_RANKS = new Set([6, 7, 10, 11, 15, 16, 17, 18, 20]);

// Old rank -> surviving rank, for the one-time migration.
const RANK_MIGRATION_MAP = Object.freeze({ 6: 5, 7: 5, 10: 9, 11: 9, 16: 13, 20: 19 });

const RANK_LADDER_BY_RANK = new Map(RANK_LADDER.map(entry => [entry.rank, entry]));

function getRankLadderEntry(rank) {
  return RANK_LADDER_BY_RANK.get(Number(rank)) || null;
}

/** The rank a member should end up on after the restructure, or null if unknown. */
function getMigrationTargetRank(rank) {
  const numericRank = Number(rank);
  if (!Number.isFinite(numericRank)) return null;
  if (RANK_MIGRATION_MAP[numericRank] !== undefined) return RANK_MIGRATION_MAP[numericRank];
  return RANK_LADDER_BY_RANK.has(numericRank) ? numericRank : null;
}

function isRetiredRank(rank) {
  return RETIRED_RANKS.has(Number(rank));
}

function rankGrantsAdministration(rank) {
  return Boolean(getRankLadderEntry(rank)?.administration);
}

function isExecutiveDirectorRank(rank) {
  const numericRank = Number(rank || 0);
  // 22 is the Director tier; 16 is accepted while anyone is still on the retired
  // Director rank, so the transition can never strip their powers.
  return numericRank === SWEETSIEZ_STRUCTURE_CONFIG.DIRECTOR_RANK || numericRank === 16;
}

function isLeadershipRank(rank) {
  return Number(rank || 0) >= SWEETSIEZ_STRUCTURE_CONFIG.LEADERSHIP_MIN_RANK;
}

function isExecutiveDirectorOrLeadershipRank(rank) {
  return isExecutiveDirectorRank(rank) || isLeadershipRank(rank);
}

