// ── Trello integration ───────────────────────────────────────────────────────
// Secrets come from .env on the host: TRELLO_KEY, TRELLO_TOKEN, TRELLO_BOARD_ID.
// Lists and labels are matched by NAME (searching for the rank word), so emoji prefixes and
// later renames do not break the sync.
const TRELLO_CONFIG = {
  BOARD_ID: process.env.TRELLO_BOARD_ID || "QLzXEsuL",
  KEY: process.env.TRELLO_KEY || "",
  TOKEN: process.env.TRELLO_TOKEN || "",
  // rank number -> the word to look for in the board's list names
  RANK_LIST_WORDS: {
    9: "Supervisor",
    12: "Manager",
    19: "Developer",
    13: "Executive",
    22: "Director",
    255: "President",
  },
  // department -> the label name to look for. Supervisors and Managers get no department label.
  DEPARTMENT_LABEL_WORDS: {
    operations: "Human Resources",
    engagement: "Public Relations",
    moderation: "Discord Moderation",
  },
  // Ranks that carry a department label.
  DEPARTMENT_LABEL_RANKS: new Set([13, 22]),
};

function isTrelloConfigured() {
  return Boolean(TRELLO_CONFIG.KEY && TRELLO_CONFIG.TOKEN && TRELLO_CONFIG.BOARD_ID);
}

async function trelloApi(method, apiPath, params = {}) {
  if (!isTrelloConfigured()) {
    throw new Error("Trello is not configured. Set TRELLO_KEY, TRELLO_TOKEN and TRELLO_BOARD_ID on the host.");
  }
  const response = await axios({
    method,
    url: `https://api.trello.com/1${apiPath}`,
    params: { key: TRELLO_CONFIG.KEY, token: TRELLO_CONFIG.TOKEN, ...params },
    timeout: 15000,
  });
  return response.data;
}

/** Board lists keyed by the rank number they represent, matched on the rank word. */
async function getTrelloListIdByRank() {
  const lists = await trelloApi("get", `/boards/${TRELLO_CONFIG.BOARD_ID}/lists`);
  const byRank = new Map();
  for (const [rankKey, word] of Object.entries(TRELLO_CONFIG.RANK_LIST_WORDS)) {
    const match = (lists || []).find(list => String(list.name || "").includes(word));
    if (match) byRank.set(Number(rankKey), match.id);
  }
  return { lists: lists || [], byRank };
}

/** Board labels keyed by name, matched on the label word. */
async function getTrelloLabelIds() {
  const labels = await trelloApi("get", `/boards/${TRELLO_CONFIG.BOARD_ID}/labels`);
  const byWord = new Map();
  for (const label of labels || []) {
    if (label.name) byWord.set(label.name.trim().toLowerCase(), label.id);
  }
  const findLabel = word => {
    const exact = byWord.get(word.toLowerCase());
    if (exact) return exact;
    const partial = [...byWord.entries()].find(([labelName]) => labelName.includes(word.toLowerCase()));
    return partial ? partial[1] : null;
  };
  return { findLabel };
}

function formatTrelloDate(date = new Date()) {
  return `${String(date.getMonth() + 1).padStart(2, "0")}/${String(date.getDate()).padStart(2, "0")}/${date.getFullYear()}`;
}

