function getVoteRoleIds(voteConfig) {
  return [...new Set([
    ...(voteConfig?.roleIds || []),
    voteConfig?.roleId,
  ].filter(Boolean))];
}

function formatVoteRoleMentions(voteConfig) {
  const roleIds = getVoteRoleIds(voteConfig);
  return roleIds.length ? roleIds.map(roleId => `<@&${roleId}>`).join(" ") : "";
}

function isVoteCommandTrigger(content) {
  return /^!vote(?:\s|$)/i.test(String(content || "").trim());
}

