async function handleAlliancePostRequestButton(interaction) {
  const [, action, requestId] = interaction.customId.split(":");
  const requestDoc = await AlliancePostRequest.findOne({ requestId });
  if (!requestDoc) {
    return interaction.reply({ content: "That alliance post request could not be found.", flags: MessageFlags.Ephemeral });
  }

  const authority = await getAlliancePostRequestAuthority(interaction);
  if (!authority.canRelationsReview) {
    return interaction.reply({ content: "Only Outreach, Public Relations, Public Relations Lead, or Leadership may manage alliance post requests.", flags: MessageFlags.Ephemeral });
  }

  if (action === "draft") {
    if (isAlliancePostRequestTerminal(requestDoc.status)) {
      return interaction.reply({ content: "That alliance post request is already closed.", flags: MessageFlags.Ephemeral });
    }
    return showAlliancePostDraftModal(interaction, requestDoc);
  }

  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }
  if (isAlliancePostRequestTerminal(requestDoc.status)) {
    return interaction.editReply("That alliance post request is already closed.");
  }

  const now = new Date();
  const update = {
    $set: { updatedAt: now },
    $push: { history: alliancePostRequestHistory(action, interaction.user) },
  };
  let successText = "Alliance post request updated.";
  const pointLogs = [];

  if (action === "claim") {
    if (requestDoc.claimedByDiscordId) return interaction.editReply("That request has already been claimed.");
    update.$set.status = "claimed";
    update.$set.claimedByDiscordId = interaction.user.id;
    update.$set.claimedByTag = interaction.user.tag;
    update.$set.claimedAt = now;
    successText = "Alliance post request claimed.";
  } else if (action === "needs_edits") {
    update.$set.status = "needs_edits";
    successText = "Marked as needing edits from the requesting board.";
  } else if (action === "sent") {
    if (!requestDoc.formalCopy) {
      return interaction.editReply("Add the formal Public Relations copy before marking this sent.");
    }
    const repChannel = await getAllianceRepAnnouncementChannel(interaction.guild);
    if (!repChannel) {
      return interaction.editReply("I could not access the allied representative announcement channel. Please check the configured channel ID.");
    }
    if (requestDoc.proofRequired) {
      const proofChannel = await getAlliancePostProofChannel(interaction.guild);
      if (!proofChannel) return interaction.editReply("I could not access the alliance proof channel. Please check the configured channel ID.");
    }
    update.$set.status = "sent";
    update.$set.sentByDiscordId = interaction.user.id;
    update.$set.sentByTag = interaction.user.tag;
    update.$set.sentAt = now;
    pointLogs.push({
      board: "relations",
      activityType: "alliance_post_request_sent",
      discordId: interaction.user.id,
      sourceType: "alliance_post_request",
      sourceId: `${requestId}:sent`,
      summary: `Marked alliance post request ${requestId} from ${alliancePostBoardLabel(requestDoc.requestingBoard)} as sent to allied representatives.`,
    });
    successText = "Alliance post request marked as sent.";
  } else if (action === "decline") {
    update.$set.status = "declined";
    update.$set.declinedByDiscordId = interaction.user.id;
    update.$set.declinedByTag = interaction.user.tag;
    update.$set.declinedAt = now;
    successText = "Alliance post request declined.";
  } else {
    return interaction.editReply("That alliance post request action is not recognized.");
  }

  const updated = await AlliancePostRequest.findOneAndUpdate({ requestId }, update, { new: true });
  if (!updated) return interaction.editReply("I could not update that alliance post request.");

  if (action === "sent") {
    const repMessage = await sendOrUpdateAlliancePostRepAnnouncement(updated, interaction.guild);
    successText = `Alliance post request sent to allied representatives: ${repMessage.url}`;
  }

  await refreshAlliancePostRequestMessage(updated, interaction.guild);
  for (const pointLog of pointLogs) {
    await logBoardContribution({ ...pointLog, loggedBy: interaction.user }).catch(error =>
      console.warn("Could not log alliance post request contribution:", error.message),
    );
  }

  return interaction.editReply(successText);
}

async function handleAlliancePostRequestModal(interaction) {
  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }
  const [, requestId] = interaction.customId.split(":");
  const requestDoc = await AlliancePostRequest.findOne({ requestId });
  if (!requestDoc) return interaction.editReply("That alliance post request could not be found.");

  const authority = await getAlliancePostRequestAuthority(interaction);
  if (!authority.canRelationsReview) {
    return interaction.editReply("Only Outreach, Public Relations, Public Relations Lead, or Leadership may add formal alliance copy.");
  }
  if (isAlliancePostRequestTerminal(requestDoc.status)) {
    return interaction.editReply("That alliance post request is already closed.");
  }

  const formalCopy = interaction.fields.getTextInputValue("formal_copy").trim();
  const formalNotes = interaction.fields.getTextInputValue("formal_notes")?.trim() || null;
  if (!formalCopy) return interaction.editReply("Formal copy cannot be blank.");

  const now = new Date();
  const firstFormalCopy = !requestDoc.formalizedAt;
  const updated = await AlliancePostRequest.findOneAndUpdate(
    { requestId },
    {
      $set: {
        formalCopy,
        formalCopyNotes: formalNotes,
        formalizedByDiscordId: interaction.user.id,
        formalizedByTag: interaction.user.tag,
        formalizedAt: now,
        status: "draft_ready",
        updatedAt: now,
      },
      $push: { history: alliancePostRequestHistory("formal_copy_added", interaction.user) },
    },
    { new: true },
  );
  if (!updated) return interaction.editReply("I could not save the formal copy.");

  await refreshAlliancePostRequestMessage(updated, interaction.guild);
  if (firstFormalCopy) {
    await logBoardContribution({
      board: "relations",
      activityType: "alliance_post_request_reviewed",
      discordId: interaction.user.id,
      sourceType: "alliance_post_request",
      sourceId: `${requestId}:formal-copy`,
      summary: `Prepared formal alliance representative copy for ${alliancePostBoardLabel(requestDoc.requestingBoard)} request ${requestId}.`,
      loggedBy: interaction.user,
    }).catch(error => console.warn("Could not log alliance post request review:", error.message));
  }

  return interaction.editReply("Formal Public Relations copy saved. Mark Sent will post it to the allied representative announcement channel with proof tracking.");
}

async function canSubmitAlliancePostProof(interaction) {
  const member = interaction.member?.roles?.cache
    ? interaction.member
    : await interaction.guild?.members.fetch(interaction.user.id).catch(() => null);
  if (hasAnyRoleId(member, [ALLIANCE_SYSTEM_CONFIG.AFFILIATE_REPRESENTATIVE_ROLE_ID])) return true;

  const authority = await getAlliancePostRequestAuthority(interaction).catch(() => null);
  return Boolean(authority?.canRelationsReview);
}

