async function handleAlliancePostProofButton(interaction) {
  const [, action, requestId, proofId] = interaction.customId.split(":");
  const requestDoc = await AlliancePostRequest.findOne({ requestId });
  if (!requestDoc) {
    return interaction.reply({ content: "That alliance announcement request could not be found.", flags: MessageFlags.Ephemeral });
  }

  if (action === "submit") {
    if (!requestDoc.proofRequired) {
      return interaction.reply({ content: "This alliance announcement does not require proof.", flags: MessageFlags.Ephemeral });
    }
    if (requestDoc.status !== "sent") {
      return interaction.reply({ content: "Proof can only be submitted after the announcement has been sent to allied representatives.", flags: MessageFlags.Ephemeral });
    }
    const canSubmit = await canSubmitAlliancePostProof(interaction);
    if (!canSubmit) {
      return interaction.reply({ content: "Only allied representatives or Public Relations may submit proof for this announcement.", flags: MessageFlags.Ephemeral });
    }
    return showAlliancePostProofModal(interaction, requestDoc);
  }

  if (!["approve", "reject"].includes(action)) {
    return interaction.reply({ content: "That proof action is not recognized.", flags: MessageFlags.Ephemeral });
  }

  const authority = await getAlliancePostRequestAuthority(interaction);
  if (!authority.canRelationsReview) {
    return interaction.reply({ content: "Only Outreach, Public Relations, Public Relations Lead, or Leadership may review alliance announcement proof.", flags: MessageFlags.Ephemeral });
  }

  const proofEntry = getAlliancePostProofEntries(requestDoc).find(entry => entry.proofId === proofId);
  if (!proofEntry) {
    return interaction.reply({ content: "That proof submission could not be found.", flags: MessageFlags.Ephemeral });
  }
  if (proofEntry.status !== "submitted") {
    return interaction.reply({ content: "That proof submission has already been reviewed.", flags: MessageFlags.Ephemeral });
  }

  return showAlliancePostProofReviewModal(interaction, requestDoc, proofEntry, action);
}

async function handleAlliancePostProofModal(interaction) {
  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }
  const [, requestId] = interaction.customId.split(":");
  const requestDoc = await AlliancePostRequest.findOne({ requestId });
  if (!requestDoc) return interaction.editReply("That alliance announcement request could not be found.");
  if (!requestDoc.proofRequired) return interaction.editReply("This alliance announcement does not require proof.");
  if (requestDoc.status !== "sent") return interaction.editReply("Proof can only be submitted after the announcement has been sent.");

  const canSubmit = await canSubmitAlliancePostProof(interaction);
  if (!canSubmit) {
    return interaction.editReply("Only allied representatives or Public Relations may submit proof for this announcement.");
  }

  let proofChannel = await getAlliancePostProofChannel(interaction.guild);
  if (!proofChannel) return interaction.editReply("I could not access the alliance proof channel. Please check the configured channel ID.");

  const allianceName = interaction.fields.getTextInputValue("alliance_name").trim();
  const proofLink = interaction.fields.getTextInputValue("message_link").trim();
  const notes = interaction.fields.getTextInputValue("notes")?.trim() || "None provided";

  // Proofs belong with the alliance: post into its own forum post in the alliance forum when
  // it has one. If it does not, the configured proof channel (the Engagement head channel)
  // keeps it so the department lead can step in.
  const allianceProofThread = allianceName
    ? await findAllianceThread(interaction.guild, allianceName).catch(() => null)
    : null;
  if (allianceProofThread) proofChannel = allianceProofThread;
  if (!allianceName) return interaction.editReply("Alliance name cannot be blank.");
  if (!isDiscordMessageLink(proofLink)) {
    return interaction.editReply("Please submit a valid Discord message link for the announcement proof.");
  }

  const partner = await findAlliancePartner(interaction.guild, allianceName);
  if (!partner || partner.status !== "active") {
    return interaction.editReply("I could not match that alliance name to an active alliance record. Please use the exact alliance name from your Sweetsiez alliance channel.");
  }
  if (!isAlliancePartnerEligibleForPostProof(requestDoc, partner)) {
    return interaction.editReply(
      `**${partner.groupName}** became an alliance after this announcement request was sent, so proof is not required for this request.`,
    );
  }
  if (hasAcceptedAlliancePostProof(requestDoc, partner)) {
    return interaction.editReply(`Proof for **${partner.groupName}** has already been accepted for this announcement. No additional proof is needed.`);
  }

  const now = new Date();
  const proofEntry = {
    proofId: createOperationalId("PROOF"),
    allianceName: partner.groupName,
    allianceNameLower: partner.groupNameLower || normalizeAllianceKey(partner.groupName),
    allianceId: partner.allianceId,
    allianceChannelId: partner.channelId || null,
    allianceRoleId: partner.roleId || null,
    proofLink,
    notes,
    submittedByDiscordId: interaction.user.id,
    submittedByTag: interaction.user.tag,
    submittedAt: now,
    status: "submitted",
    reviewChannelId: null,
    reviewMessageId: null,
  };

  const reviewMessage = await proofChannel.send({
    content: `<@&${ALLIANCE_SYSTEM_CONFIG.RELATIONS_BOARD_ROLE_ID}>`,
    embeds: [buildAlliancePostProofReviewEmbed(requestDoc, proofEntry)],
    components: buildAlliancePostProofReviewRows(requestDoc, proofEntry),
    allowedMentions: { roles: [ALLIANCE_SYSTEM_CONFIG.RELATIONS_BOARD_ROLE_ID] },
  });

  proofEntry.reviewChannelId = proofChannel.id;
  proofEntry.reviewMessageId = reviewMessage.id;

  const updated = await AlliancePostRequest.findOneAndUpdate(
    { requestId },
    {
      $set: {
        proofReviewChannelId: proofChannel.id,
        updatedAt: now,
      },
      $push: {
        proofEntries: proofEntry,
        history: alliancePostRequestHistory("proof_submitted", interaction.user),
      },
    },
    { new: true },
  );
  if (!updated) return interaction.editReply("I could not save that proof submission.");

  await refreshAlliancePostRequestMessage(updated, interaction.guild);
  return interaction.editReply("Proof submitted. Public Relations will review it shortly.");
}

async function handleAlliancePostProofReviewModal(interaction) {
  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }
  const [, action, requestId, proofId] = interaction.customId.split(":");
  if (!["approve", "reject"].includes(action)) {
    return interaction.editReply("That proof review action is not recognized.");
  }

  const requestDoc = await AlliancePostRequest.findOne({ requestId });
  if (!requestDoc) return interaction.editReply("That alliance announcement request could not be found.");

  const authority = await getAlliancePostRequestAuthority(interaction);
  if (!authority.canRelationsReview) {
    return interaction.editReply("Only Outreach, Public Relations, Public Relations Lead, or Leadership may review alliance announcement proof.");
  }

  const proofEntry = getAlliancePostProofEntries(requestDoc).find(entry => entry.proofId === proofId);
  if (!proofEntry) return interaction.editReply("That proof submission could not be found.");
  if (proofEntry.status !== "submitted") return interaction.editReply("That proof submission has already been reviewed.");

  const partner = await resolveAlliancePartnerForProof(interaction.guild, proofEntry);
  if (!partner || partner.status !== "active") {
    return interaction.editReply("I could not match this proof to an active alliance record, so I cannot notify the alliance channel.");
  }
  const channel = await getAllianceChannel(interaction.guild, partner);
  const role = await getAllianceRole(interaction.guild, partner);
  if (!channel?.isTextBased?.() || !role) {
    return interaction.editReply("That alliance is missing its private channel or role, so I cannot send the proof decision.");
  }
  if (action === "approve" && hasAcceptedAlliancePostProof(requestDoc, partner, proofId)) {
    return interaction.editReply(`Proof for **${partner.groupName}** has already been accepted for this announcement.`);
  }

  const now = new Date();
  const nextStatus = action === "approve" ? "approved" : "rejected";
  const reviewNotes = interaction.fields.getTextInputValue("review_notes")?.trim() || "No additional notes were provided.";

  const updated = await AlliancePostRequest.findOneAndUpdate(
    { requestId, "proofEntries.proofId": proofId },
    {
      $set: {
        "proofEntries.$[proof].status": nextStatus,
        "proofEntries.$[proof].reviewedByDiscordId": interaction.user.id,
        "proofEntries.$[proof].reviewedByTag": interaction.user.tag,
        "proofEntries.$[proof].reviewedAt": now,
        "proofEntries.$[proof].reviewNotes": reviewNotes,
        "proofEntries.$[proof].allianceName": partner.groupName,
        "proofEntries.$[proof].allianceNameLower": partner.groupNameLower || normalizeAllianceKey(partner.groupName),
        "proofEntries.$[proof].allianceId": partner.allianceId,
        "proofEntries.$[proof].allianceChannelId": channel.id,
        "proofEntries.$[proof].allianceRoleId": role.id,
        updatedAt: now,
      },
      $push: { history: alliancePostRequestHistory(`proof_${nextStatus}`, interaction.user) },
    },
    { new: true, arrayFilters: [{ "proof.proofId": proofId }] },
  );
  if (!updated) return interaction.editReply("I could not update that proof submission.");

  const updatedProof = getAlliancePostProofEntries(updated).find(entry => entry.proofId === proofId);
  let notification = null;
  try {
    notification = await sendAlliancePostProofDecisionToAlliance(
      interaction.guild,
      updated,
      updatedProof,
      nextStatus === "approved",
    );
  } catch (error) {
    await refreshAlliancePostProofReviewMessage(updated, updatedProof, interaction.guild);
    await refreshAlliancePostRequestMessage(updated, interaction.guild);
    return interaction.editReply(`Proof was marked as ${alliancePostProofStatusLabel(nextStatus).toLowerCase()}, but I could not notify the alliance channel: ${error.message}`);
  }

  const finalized = await AlliancePostRequest.findOneAndUpdate(
    { requestId, "proofEntries.proofId": proofId },
    {
      $set: {
        "proofEntries.$[proof].notificationChannelId": notification.channel.id,
        "proofEntries.$[proof].notificationMessageId": notification.message.id,
        updatedAt: new Date(),
      },
    },
    { new: true, arrayFilters: [{ "proof.proofId": proofId }] },
  );

  const finalDoc = finalized || updated;
  const finalProof = getAlliancePostProofEntries(finalDoc).find(entry => entry.proofId === proofId) || updatedProof;
  await refreshAlliancePostProofReviewMessage(finalDoc, finalProof, interaction.guild);
  await refreshAlliancePostRequestMessage(finalDoc, interaction.guild);

  return interaction.editReply(
    `Proof marked as ${alliancePostProofStatusLabel(nextStatus).toLowerCase()} and **${partner.groupName}** was notified in <#${channel.id}>.`,
  );
}

async function handleAllianceAnnouncementCommand(interaction) {
  const authority = await getAlliancePostRequestAuthority(interaction);
  if (!authority.canRelationsReview) {
    return interaction.editReply("Only Outreach, Public Relations, Public Relations Lead, or Leadership may send allied representative announcements.");
  }

  const proofRequired = interaction.options.getBoolean("proof_required") ?? true;
  const repChannel = await getAllianceRepAnnouncementChannel(interaction.guild);
  if (!repChannel) {
    return interaction.editReply("I could not access the allied representative announcement channel. Please check the configured channel ID.");
  }
  if (proofRequired) {
    const proofChannel = await getAlliancePostProofChannel(interaction.guild);
    if (!proofChannel) return interaction.editReply("I could not access the alliance proof channel. Please check the configured channel ID.");
  }

  const now = new Date();
  const formalCopy = interaction.options.getString("message").trim();
  const title = interaction.options.getString("title")?.trim() || "Alliance Announcement Request";
  const requestDoc = await AlliancePostRequest.create({
    requestId: createOperationalId("APOST"),
    announcementTitle: title,
    requestingBoard: "relations",
    purpose: "announcement",
    targetAlliances: interaction.options.getString("targets")?.trim() || "All allied representatives",
    requestedMessage: formalCopy,
    linkOrAsset: interaction.options.getString("link")?.trim() || "None provided",
    deadline: interaction.options.getString("deadline")?.trim() || "No deadline provided",
    proofRequired,
    notes: interaction.options.getString("notes")?.trim() || "Manual Public Relations allied representative announcement.",
    status: "sent",
    submittedByDiscordId: interaction.user.id,
    submittedByTag: interaction.user.tag,
    submittedByRobloxUsername: authority.rankInfo?.robloxUsername || verifiedUsers.get(interaction.user.id) || null,
    formalCopy,
    formalizedByDiscordId: interaction.user.id,
    formalizedByTag: interaction.user.tag,
    formalizedAt: now,
    sentByDiscordId: interaction.user.id,
    sentByTag: interaction.user.tag,
    sentAt: now,
    history: [
      alliancePostRequestHistory("manual_allied_announcement_created", interaction.user),
      alliancePostRequestHistory("sent", interaction.user),
    ],
    createdAt: now,
    updatedAt: now,
  });

  const repMessage = await sendOrUpdateAlliancePostRepAnnouncement(requestDoc, interaction.guild);
  const requestChannel = await getAlliancePostRequestChannel(interaction.guild);
  let trackerMessage = null;
  if (requestChannel) {
    trackerMessage = await requestChannel.send({
      embeds: [buildAlliancePostRequestEmbed(requestDoc)],
      components: buildAlliancePostRequestRows(requestDoc),
      allowedMentions: { parse: [] },
    });
    requestDoc.channelId = requestChannel.id;
    requestDoc.messageId = trackerMessage.id;
    requestDoc.updatedAt = new Date();
    await requestDoc.save();
  }

  await logBoardContribution({
    board: "relations",
    activityType: "alliance_post_request_sent",
    discordId: interaction.user.id,
    sourceType: "alliance_post_request",
    sourceId: `${requestDoc.requestId}:manual-sent`,
    summary: `Posted manual allied representative announcement ${requestDoc.requestId}.`,
    loggedBy: interaction.user,
  }).catch(error => console.warn("Could not log manual alliance announcement contribution:", error.message));

  const trackerText = trackerMessage ? `\nProof tracker: ${trackerMessage.url}` : "";
  return interaction.editReply(`Allied representative announcement posted in <#${repChannel.id}>: ${repMessage.url}${trackerText}`);
}

const RELATIONS_REMINDER_TYPE_LABELS = {
  check_in: "Alliance Check-In",
  strike_review: "Strike Review",
  suspension_review: "Suspension Review",
  custom: "Custom Follow-Up",
};

function relationsReminderTypeLabel(type) {
  return RELATIONS_REMINDER_TYPE_LABELS[type] || "Public Relations Reminder";
}

function parseRelationsReminderDueDate(value) {
  const raw = String(value || "").trim();
  let year;
  let month;
  let day;

  const iso = raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  const american = raw.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2}|\d{4})$/);
  if (iso) {
    year = Number(iso[1]);
    month = Number(iso[2]);
    day = Number(iso[3]);
  } else if (american) {
    month = Number(american[1]);
    day = Number(american[2]);
    year = Number(american[3]);
    if (year < 100) year += 2000;
  } else {
    return null;
  }

  const parsed = new Date(year, month - 1, day, 12, 0, 0);
  if (
    parsed.getFullYear() !== year ||
    parsed.getMonth() !== month - 1 ||
    parsed.getDate() !== day
  ) {
    return null;
  }
  return parsed;
}

function getRelationsReminderDayAge(date, now = new Date()) {
  const parsed = new Date(date || now);
  if (Number.isNaN(parsed.getTime())) return 0;
  return Math.max(0, Math.floor((now.getTime() - parsed.getTime()) / (24 * 60 * 60 * 1000)));
}

function formatRelationsReminderList(items, formatter, emptyText, limit = RELATIONS_REMINDER_CONFIG.MAX_LIST_ITEMS) {
  if (!items.length) return emptyText;
  const visible = items.slice(0, limit).map(formatter);
  const hidden = items.length - visible.length;
  return truncateForDiscord(
    hidden > 0
      ? `${visible.join("\n")}\n...and **${hidden}** more.`
      : visible.join("\n"),
    1024,
  );
}

function formatRelationsManualReminderLine(reminder) {
  const dueAt = reminder.dueAt ? new Date(reminder.dueAt) : null;
  const dueText = dueAt && !Number.isNaN(dueAt.getTime())
    ? `${formatDiscordTimestamp(dueAt, "d")} (${formatDiscordTimestamp(dueAt, "R")})`
    : "No due date";
  const notes = reminder.notes && reminder.notes !== "None provided"
    ? ` - ${truncateForDiscord(reminder.notes, 140)}`
    : "";
  return `- **${reminder.groupName}** - ${relationsReminderTypeLabel(reminder.type)} due ${dueText} - \`${reminder.reminderId}\`${notes}`;
}

function formatRelationsAutoCheckInLine(item) {
  return `- **${item.partner.groupName}** - no alliance record update for **${item.daysSinceUpdate} days**`;
}

function formatRelationsInactiveAllianceLine(item) {
  return `- **${item.partner.groupName}** - last record update ${formatDiscordTimestamp(item.lastUpdatedAt, "R")} (${item.daysSinceUpdate} days)`;
}

function formatRelationsMissingRepLine(item) {
  return `- **${item.partner.groupName}** - missing ${item.missing.join(" and ")}`;
}

function formatRelationsPendingEventLine(eventDoc) {
  const owner = eventDoc.relationsLiaisonDiscordId ? ` - rel: <@${eventDoc.relationsLiaisonDiscordId}>` : "";
  return `- **${eventDoc.groupName}** - ${allianceEventStatusLabel(computeAllianceEventStatus(eventDoc))} - ${eventDoc.preferredDate} ${eventDoc.preferredTime} - \`${eventDoc.requestId}\`${owner}`;
}

function formatRelationsProofDeadlineLine(item) {
  const title = truncateForDiscord(
    item.requestDoc.announcementTitle || item.requestDoc.formalCopy || item.requestDoc.requestedMessage || item.requestDoc.requestId,
    90,
  );
  return `- **${item.partner.groupName}** - ${item.proofStatus.label} - ${title} - deadline: ${truncateForDiscord(item.requestDoc.deadline || "No deadline provided", 80)} - \`${item.requestDoc.requestId}\``;
}

async function getRelationsReminderBoardData(guild) {
  const now = new Date();
  const manualLookahead = new Date(now.getTime() + RELATIONS_REMINDER_CONFIG.MANUAL_LOOKAHEAD_DAYS * 24 * 60 * 60 * 1000);
  const proofLookback = new Date(now.getTime() - RELATIONS_REMINDER_CONFIG.PROOF_LOOKBACK_DAYS * 24 * 60 * 60 * 1000);

  const [partners, openReminders, pendingEvents, proofRequests] = await Promise.all([
    AlliancePartner.find({ status: "active" }).sort({ groupNameLower: 1 }).limit(250).lean().catch(() => []),
    AllianceReminder.find({ status: "open", dueAt: { $lte: manualLookahead } }).sort({ dueAt: 1 }).limit(100).lean().catch(() => []),
    AllianceEventRequest.find({
      status: { $in: ["pending_relations", "pending_ops", "needs_info", "approved", "scheduled"] },
    }).sort({ updatedAt: 1 }).limit(50).lean().catch(() => []),
    AlliancePostRequest.find({
      proofRequired: true,
      status: "sent",
      $or: [
        { sentAt: { $gte: proofLookback } },
        { repAnnouncementPostedAt: { $gte: proofLookback } },
        { createdAt: { $gte: proofLookback } },
      ],
    }).sort({ sentAt: -1, repAnnouncementPostedAt: -1, updatedAt: -1 }).limit(40).lean().catch(() => []),
  ]);

  const partnerAges = partners.map(partner => {
    const lastUpdatedAt = new Date(partner.updatedAt || partner.createdAt || now);
    return {
      partner,
      lastUpdatedAt,
      daysSinceUpdate: getRelationsReminderDayAge(lastUpdatedAt, now),
    };
  });
  const manualCheckIns = openReminders.filter(reminder => reminder.type === "check_in");
  const manualCheckInKeys = new Set(manualCheckIns.map(reminder => reminder.groupNameLower));
  const upcomingCheckIns = [
    ...manualCheckIns,
    ...partnerAges.filter(item =>
      item.daysSinceUpdate >= RELATIONS_REMINDER_CONFIG.CHECKIN_DUE_DAYS &&
      item.daysSinceUpdate < RELATIONS_REMINDER_CONFIG.INACTIVE_DAYS &&
      !manualCheckInKeys.has(item.partner.groupNameLower),
    ),
  ];
  const inactiveAllies = partnerAges.filter(item => item.daysSinceUpdate >= RELATIONS_REMINDER_CONFIG.INACTIVE_DAYS);
  const missingReps = partners
    .map(partner => {
      const missing = [];
      if (!(partner.representativeDiscordIds || []).length) missing.push("allied representative");
      if (!(partner.sweetsiezRepresentativeDiscordIds || []).length) missing.push("Sweetsiez representative");
      return { partner, missing };
    })
    .filter(item => item.missing.length);
  const statusReviews = openReminders.filter(reminder =>
    ["strike_review", "suspension_review", "custom"].includes(reminder.type),
  );

  const proofDeadlines = [];
  const unresolvedProofTargets = [];
  for (const requestDoc of proofRequests) {
    const resolved = await resolveAlliancePostTargetPartners(guild, requestDoc);
    unresolvedProofTargets.push(...(resolved.unresolvedTargets || []).map(target => ({
      requestDoc,
      target,
    })));
    for (const partner of resolved.partners || []) {
      const proofStatus = getAlliancePostPartnerProofStatus(requestDoc, partner);
      if (proofStatus.status === "approved") continue;
      proofDeadlines.push({ requestDoc, partner, proofStatus });
      if (proofDeadlines.length >= 75) break;
    }
    if (proofDeadlines.length >= 75) break;
  }

  return {
    now,
    partners,
    openReminders,
    upcomingCheckIns,
    inactiveAllies,
    missingReps,
    pendingEvents,
    statusReviews,
    proofDeadlines,
    unresolvedProofTargets,
  };
}

function buildRelationsReminderBoardEmbed(data, view = "all") {
  const selectedView = view || "all";
  const showAll = selectedView === "all";
  const embed = new EmbedBuilder()
    .setColor(0xffb6c1)
    .setTitle("Public Relations Reminder Board")
    .setDescription([
      `Alliance follow-up dashboard for the Public Relations Department.`,
      `Active Alliances: **${data.partners.length}**`,
      `Check-Ins: **${data.upcomingCheckIns.length}** | Inactive Allies: **${data.inactiveAllies.length}** | Pending Events: **${data.pendingEvents.length}** | Missing Reps: **${data.missingReps.length}** | Proof Items: **${data.proofDeadlines.length}**`,
    ].join("\n"))
    .setFooter({ text: "Use /relationsreminders add to schedule check-ins or status reviews." })
    .setTimestamp(data.now);

  const addField = (key, name, value) => {
    if (showAll || selectedView === key) {
      embed.addFields({ name, value, inline: false });
    }
  };

  addField(
    "checkins",
    `Upcoming Check-Ins (${data.upcomingCheckIns.length})`,
    formatRelationsReminderList(
      data.upcomingCheckIns,
      item => item.reminderId ? formatRelationsManualReminderLine(item) : formatRelationsAutoCheckInLine(item),
      "No alliance check-ins are due soon.",
    ),
  );
  addField(
    "inactive",
    `Inactive / Stale Allies (${data.inactiveAllies.length})`,
    formatRelationsReminderList(data.inactiveAllies, formatRelationsInactiveAllianceLine, "No active alliances are past the inactivity threshold."),
  );
  addField(
    "events",
    `Pending Alliance Events (${data.pendingEvents.length})`,
    formatRelationsReminderList(data.pendingEvents, formatRelationsPendingEventLine, "No alliance event requests need follow-up."),
  );
  addField(
    "reps",
    `Missing Representatives (${data.missingReps.length})`,
    formatRelationsReminderList(data.missingReps, formatRelationsMissingRepLine, "All active alliance records have representatives assigned."),
  );
  addField(
    "reviews",
    `Strike / Suspension / Manual Reviews (${data.statusReviews.length})`,
    formatRelationsReminderList(data.statusReviews, formatRelationsManualReminderLine, "No tracked strike, suspension, or manual review dates are currently open."),
  );
  addField(
    "proof",
    `Proof Deadlines / Reviews (${data.proofDeadlines.length})`,
    formatRelationsReminderList(data.proofDeadlines, formatRelationsProofDeadlineLine, "No proof-required alliance announcements need follow-up."),
  );

  if ((showAll || selectedView === "proof") && data.unresolvedProofTargets.length) {
    embed.addFields({
      name: `Unmatched Proof Targets (${data.unresolvedProofTargets.length})`,
      value: formatRelationsReminderList(
        data.unresolvedProofTargets,
        item => `- **${item.target}** - not matched on \`${item.requestDoc.requestId}\``,
        "No unmatched targets.",
        5,
      ),
      inline: false,
    });
  }

  return embed;
}

async function handleRelationsRemindersCommand(interaction) {
  const context = await requireRelationsCommandAccess(interaction);
  if (!context) return;

  const subcommand = {
    "reminder-view": "view",
    "reminder-add": "add",
    "reminder-complete": "complete",
  }[interaction.options.getSubcommand()] || interaction.options.getSubcommand();
  if (subcommand === "view") {
    const view = interaction.options.getString("category") || "all";
    const data = await getRelationsReminderBoardData(interaction.guild);
    return interaction.editReply({
      embeds: [buildRelationsReminderBoardEmbed(data, view)],
      allowedMentions: { parse: [] },
    });
  }

  if (subcommand === "add") {
    const groupName = normalizeAllianceName(interaction.options.getString("group"));
    const type = interaction.options.getString("type");
    const dueInput = interaction.options.getString("due");
    const notes = interaction.options.getString("notes")?.trim() || "None provided";
    const dueAt = parseRelationsReminderDueDate(dueInput);
    if (!dueAt) {
      return interaction.editReply("Please use a valid due date like `MM/DD/YYYY` or `YYYY-MM-DD`.");
    }
    const todayStart = new Date();
    todayStart.setHours(0, 0, 0, 0);
    if (dueAt < todayStart) {
      return interaction.editReply("That due date is in the past. Please choose today or a future date.");
    }

    const partner = await findAlliancePartner(interaction.guild, groupName);
    if (!partner || partner.status !== "active") {
      return interaction.editReply(`I could not find an active alliance record for **${groupName}**.`);
    }

    const reminder = await AllianceReminder.create({
      reminderId: createOperationalId("AREM"),
      allianceId: partner.allianceId,
      groupName: partner.groupName,
      groupNameLower: partner.groupNameLower || normalizeAllianceKey(partner.groupName),
      type,
      dueAt,
      notes,
      status: "open",
      createdByDiscordId: interaction.user.id,
      createdByTag: interaction.user.tag,
      createdAt: new Date(),
      updatedAt: new Date(),
    });

    await postAllianceForumLog(
      interaction.guild,
      partner,
      `**RELATIONS REMINDER ADDED** | ${formatAllianceDate()}\n**Type:** ${relationsReminderTypeLabel(type)}\n**Due:** ${formatAllianceDate(dueAt)}\n**Notes:** ${notes}\n**Added by:** <@${interaction.user.id}>`,
    );

    return interaction.editReply(
      `Relations reminder created for **${partner.groupName}**: \`${reminder.reminderId}\` due ${formatDiscordTimestamp(dueAt, "d")}.`,
    );
  }

  if (subcommand === "complete") {
    const reminderId = interaction.options.getString("reminder_id").trim();
    const notes = interaction.options.getString("notes")?.trim() || "Handled by Public Relations.";
    const reminder = await AllianceReminder.findOneAndUpdate(
      {
        reminderId: new RegExp(`^${escapeMongoRegex(reminderId)}$`, "i"),
        status: "open",
      },
      {
        $set: {
          status: "completed",
          completedByDiscordId: interaction.user.id,
          completedByTag: interaction.user.tag,
          completedAt: new Date(),
          completionNotes: notes,
          updatedAt: new Date(),
        },
      },
      { new: true },
    );
    if (!reminder) {
      return interaction.editReply("I could not find an open reminder with that ID.");
    }

    const partner = await findAlliancePartner(interaction.guild, reminder.groupName).catch(() => null);
    if (partner) {
      await postAllianceForumLog(
        interaction.guild,
        partner,
        `**RELATIONS REMINDER COMPLETED** | ${formatAllianceDate()}\n**Reminder ID:** ${reminder.reminderId}\n**Type:** ${relationsReminderTypeLabel(reminder.type)}\n**Notes:** ${notes}\n**Completed by:** <@${interaction.user.id}>`,
      );
    }

    return interaction.editReply(`Reminder \`${reminder.reminderId}\` for **${reminder.groupName}** has been marked complete.`);
  }

  return interaction.editReply("That Public Relations reminder action is not recognized.");
}

let mongoReconnectTimer = null;
let mongoConnectInProgress = false;
let persistentDataLoadInProgress = false;
const MAX_NODE_TIMEOUT_MS = 2_147_483_647; // Node.js setTimeout limit, about 24.8 days

function scheduleMongoReconnect(delayMs = 60 * 1000) {
  if (mongoReconnectTimer) return;
  console.warn(`⚠️ MongoDB unavailable. Retrying in ${Math.round(delayMs / 1000)} seconds...`);
  mongoReconnectTimer = setTimeout(() => {
    mongoReconnectTimer = null;
    connectToMongoDB({ retry: true, loadDataOnConnect: true }).catch(err =>
      console.error('MongoDB retry error:', err.message),
    );
  }, delayMs);
}

async function connectToMongoDB(options = {}) {
  const retry = options.retry !== false;
  const loadDataOnConnect = options.loadDataOnConnect === true;

  if (mongoose.connection.readyState === 1) {
    if (loadDataOnConnect) await loadPersistentData('MongoDB already connected');
    return true;
  }

  if (mongoConnectInProgress) {
    return false;
  }

  mongoConnectInProgress = true;
  try {
    await mongoose.connect(MONGODB_URI, {
      serverSelectionTimeoutMS: 10000,
      connectTimeoutMS: 10000,
      socketTimeoutMS: 45000,
      maxPoolSize: 10,
    });
    console.log('✅ Connected to MongoDB');
    if (loadDataOnConnect) await loadPersistentData('MongoDB reconnect');
    return true;
  } catch (error) {
    console.error('❌ MongoDB connection error:', error?.message || error);
    if (error?.cause) console.error('MongoDB connection cause:', error.cause);
    if (retry) scheduleMongoReconnect();
    return false;
  } finally {
    mongoConnectInProgress = false;
  }
}

async function loadPersistentData(reason = 'startup') {
  if (persistentDataLoadInProgress) return false;
  if (mongoose.connection.readyState !== 1) {
    console.warn(`⚠️ Skipping MongoDB-backed data load (${reason}) because MongoDB is not connected.`);
    return false;
  }

  persistentDataLoadInProgress = true;
  try {
    console.log(`📦 Loading persistent bot data (${reason})...`);
    await loadVerifiedUsers();
    await loadWarnings();
    await loadSuspensions();
    await loadActivity();
    await loadTickets();
    await loadResignations();
    await loadInactivityNotices();
    await loadEconomy();
    await loadAchievements();
    await loadShiftPosts();
    await loadTrials();
    await loadQuotaStrikes();
    await loadQuotaExceptions();
    await loadDiscordMessageCounts();
    await loadCountingState();
    await loadGiveaways();
    await runManagerSystemMaintenance("persistent data load");
    // Department membership follows the rank: repair placements that no longer match the
    // member's live rank before quotas and profiles are read this session.
    await reconcileStaleStaffPlacements("startup placement sweep").catch(error =>
      console.error("Stale placement sweep failed:", error?.message || error),
    );
    createShiftPost(client).catch(error =>
      console.error('Shift post creation after MongoDB data load failed:', error?.message || error),
    );
    runTrialInactivityCheck(client).catch(console.error);
    // Persisted /restrict locks: re-apply on every (re)connect so a rejoin or a
    // Discord-side reset never leaves a restricted member with visibility again.
    reapplyAllPersistedChannelRestrictions(client).catch(error =>
      console.warn("[ChannelRestriction] Post-connect re-apply failed:", error?.message || error),
    );
    console.log(`✅ Persistent bot data loaded (${reason}).`);
    return true;
  } catch (error) {
    console.error(`❌ Persistent data load failed (${reason}):`, error?.message || error);
    return false;
  } finally {
    persistentDataLoadInProgress = false;
  }
}

mongoose.connection.on('disconnected', () => {
  if (!mongoConnectInProgress) scheduleMongoReconnect();
});

mongoose.connection.on('error', (error) => {
  console.error('MongoDB connection event error:', error?.message || error);
});

