// Audit log schema — immutable records of sensitive operations
const auditLogSchema = new mongoose.Schema({
  logId: { type: String, required: true, unique: true, index: true },
  operationType: { type: String, required: true, enum: ["resignation", "termination", "demotion", "promotion", "rank_change", "admin_action"], index: true },
  targetDiscordId: { type: String, default: null, index: true },
  targetRobloxUsername: { type: String, default: null, index: true },
  targetRobloxUserId: { type: String, default: null },
  actorDiscordId: { type: String, required: true, index: true },
  actorTag: { type: String, required: true },
  beforeSnapshot: { type: mongoose.Schema.Types.Mixed, default: null },
  afterSnapshot: { type: mongoose.Schema.Types.Mixed, default: null },
  reason: { type: String, default: null },
  evidence: { type: String, default: null },
  approvals: { type: [mongoose.Schema.Types.Mixed], default: [] },
  immutable: { type: Boolean, default: true },
  createdAt: { type: Date, default: Date.now, immutable: true },
}, { collection: 'auditLogs' });

const securityIncidentSchema = new mongoose.Schema({
  incidentId: { type: String, required: true, unique: true, index: true },
  source: { type: String, required: true, enum: ["discord", "roblox_group"], index: true },
  actionType: { type: String, required: true, index: true },
  ruleLabel: { type: String, required: true },
  severity: { type: String, enum: ["low", "medium", "high", "critical"], default: "high", index: true },
  actorDiscordId: { type: String, default: null, index: true },
  actorTag: { type: String, default: null },
  actorRobloxUserId: { type: String, default: null, index: true },
  actorRobloxUsername: { type: String, default: null, index: true },
  guildId: { type: String, default: null, index: true },
  targetId: { type: String, default: null, index: true },
  targetName: { type: String, default: null },
  count: { type: Number, default: 0 },
  threshold: { type: Number, default: 0 },
  windowMs: { type: Number, default: 0 },
  details: { type: mongoose.Schema.Types.Mixed, default: {} },
  status: { type: String, enum: ["open", "acknowledged", "resolved", "false_positive"], default: "open", index: true },
  createdAt: { type: Date, default: Date.now },
  updatedAt: { type: Date, default: Date.now },
});

// Deadline reminder schema — tracks reminders for graphics, announcements, filming, etc.
const deadlineReminderSchema = new mongoose.Schema({
  reminderId: { type: String, required: true, unique: true, index: true },
  requestType: { type: String, required: true, enum: ["graphics", "announcement", "filming", "event"], index: true },
  requestId: { type: String, required: true, index: true },
  deadline: { type: Date, required: true, index: true },
  reminderTimes: { type: [Number], default: [86400000, 3600000] }, // 24h, 1h in ms
  sentReminders: { type: [{ time: Number, sentAt: Date }], default: [] },
  status: { type: String, enum: ["pending", "sent", "overdue", "closed"], default: "pending", index: true },
  createdAt: { type: Date, default: Date.now },
  updatedAt: { type: Date, default: Date.now },
});

// Notification preference schema — lets users control pings
const notificationPreferenceSchema = new mongoose.Schema({
  discordId: { type: String, required: true, unique: true, index: true },
  requestTypePings: { 
    graphics: { type: Boolean, default: true },
    announcements: { type: Boolean, default: true },
    filming: { type: Boolean, default: true },
    events: { type: Boolean, default: true },
  },
  mutedUntil: { type: Date, default: null },
  useDailyDigest: { type: Boolean, default: false },
  digestTime: { type: String, default: "09:00" }, // HH:MM EST
  doNotDisturbStart: { type: String, default: null }, // HH:MM
  doNotDisturbEnd: { type: String, default: null },   // HH:MM
  createdAt: { type: Date, default: Date.now },
  updatedAt: { type: Date, default: Date.now },
});

// Request template schema — reusable templates for common requests
const requestTemplateSchema = new mongoose.Schema({
  templateId: { type: String, required: true, unique: true, index: true },
  createdByDiscordId: { type: String, required: true },
  createdByTag: { type: String, required: true },
  requestType: { type: String, required: true, enum: ["graphics", "announcement", "filming", "event"], index: true },
  name: { type: String, required: true },
  description: { type: String, default: null },
  templateFields: { type: mongoose.Schema.Types.Mixed, required: true },
  isPublic: { type: Boolean, default: false },
  usageCount: { type: Number, default: 0 },
  createdAt: { type: Date, default: Date.now },
  updatedAt: { type: Date, default: Date.now },
});

// Request duplicate detection schema — deduplication for similar requests
const requestDuplicateSchema = new mongoose.Schema({
  duplicateId: { type: String, required: true, unique: true, index: true },
  requestType: { type: String, required: true, enum: ["graphics", "announcement", "filming", "event"], index: true },
  primaryRequestId: { type: String, required: true, index: true },
  similarRequestIds: { type: [String], default: [] },
  matchScore: { type: Number, default: 0 }, // 0-100 similarity
  createdAt: { type: Date, default: Date.now },
});

// Contribution dispute schema — for contesting contributions
const contributionDisputeSchema = new mongoose.Schema({
  disputeId: { type: String, required: true, unique: true, index: true },
  contributionId: { type: String, required: true, index: true },
  disputer: { type: String, required: true, index: true },
  disputerTag: { type: String, required: true },
  reason: { type: String, required: true },
  evidence: { type: String, default: null },
  status: { type: String, enum: ["open", "under_review", "resolved", "dismissed"], default: "open", index: true },
  reviewedBy: { type: String, default: null },
  resolution: { type: String, default: null },
  createdAt: { type: Date, default: Date.now },
  updatedAt: { type: Date, default: Date.now },
});

// Burnout flag schema — detects staff who may need support
const burnoutFlagSchema = new mongoose.Schema({
  flagId: { type: String, required: true, unique: true, index: true },
  discordId: { type: String, required: true, unique: true, index: true },
  robloxUsername: { type: String, required: true },
  robloxUserId: { type: String, required: true },
  flags: {
    noActivityDays: { type: Number, default: 0 },
    quotaMisses: { type: Number, default: 0 },
    overdueItems: { type: Number, default: 0 },
    lastCheckIn: { type: Date, default: null },
  },
  severity: { type: String, enum: ["low", "medium", "high"], default: "low" },
  suggestedActions: { type: [String], default: [] },
  notificationSent: { type: Boolean, default: false },
  createdAt: { type: Date, default: Date.now },
  updatedAt: { type: Date, default: Date.now },
});

// Auto-archive config schema — configures auto-archival rules
const autoArchiveConfigSchema = new mongoose.Schema({
  configId: { type: String, required: true, unique: true },
  requestType: { type: String, required: true, enum: ["graphics", "announcement", "filming", "event"], index: true },
  daysUntilArchive: { type: Number, default: 30 },
  statusesToArchive: { type: [String], default: ["completed", "cancelled"] },
  enabled: { type: Boolean, default: true },
  lastRun: { type: Date, default: null },
  updatedAt: { type: Date, default: Date.now },
});

// Quota recovery window schema — allows catch-up quotas
const quotaRecoveryWindowSchema = new mongoose.Schema({
  recoveryId: { type: String, required: true, unique: true, index: true },
  weekLabel: { type: String, required: true, index: true },
  board: { type: String, required: true, enum: ["marketing", "operations", "relations", "moderation"], index: true },
  discordId: { type: String, required: true, index: true },
  missedQuota: { type: Boolean, default: true },
  recoveryWeekLabel: { type: String, default: null },
  recoveryMultiplier: { type: Number, default: 2 },
  pointsNeeded: { type: Number, default: 0 },
  pointsEarned: { type: Number, default: 0 },
  completed: { type: Boolean, default: false },
  createdAt: { type: Date, default: Date.now },
  updatedAt: { type: Date, default: Date.now },
});

// API failure queue schema — graceful degradation for ROBLOX API
const apiFailureQueueSchema = new mongoose.Schema({
  queueId: { type: String, required: true, unique: true, index: true },
  operationType: { type: String, required: true, enum: ["rank_change", "group_operation"], index: true },
  targetRobloxUserId: { type: String, required: true, index: true },
  payload: { type: mongoose.Schema.Types.Mixed, required: true },
  retryCount: { type: Number, default: 0 },
  maxRetries: { type: Number, default: 5 },
  lastError: { type: String, default: null },
  status: { type: String, enum: ["queued", "retrying", "completed", "failed"], default: "queued", index: true },
  createdAt: { type: Date, default: Date.now },
  updatedAt: { type: Date, default: Date.now },
});

// Bulk operation schema — tracks large administrative operations
const bulkOperationSchema = new mongoose.Schema({
  operationId: { type: String, required: true, unique: true, index: true },
  operationType: { type: String, required: true, enum: ["rank_changes", "archive", "close_requests"], index: true },
  initiatedByDiscordId: { type: String, required: true },
  initiatedByTag: { type: String, required: true },
  targetCount: { type: Number, required: true },
  successCount: { type: Number, default: 0 },
  failureCount: { type: Number, default: 0 },
  items: { type: [mongoose.Schema.Types.Mixed], default: [] },
  status: { type: String, enum: ["pending", "in_progress", "completed", "failed"], default: "pending", index: true },
  progress: { type: Number, default: 0 },
  createdAt: { type: Date, default: Date.now },
  updatedAt: { type: Date, default: Date.now },
});

