function getDeadlineReminderChannelId(requestType) {
  if (process.env.REQUEST_CHANNEL_ID) return process.env.REQUEST_CHANNEL_ID;
  if (requestType === "announcement") {
    return SWEETSIEZ_STRUCTURE_CONFIG.CHANNELS.ANNOUNCEMENTS_MANAGEMENT
      || SWEETSIEZ_STRUCTURE_CONFIG.CHANNELS.ANNOUNCEMENT_REQUESTS;
  }
  if (requestType === "graphics") return SWEETSIEZ_STRUCTURE_CONFIG.CHANNELS.GRAPHICS_REQUESTS;
  if (requestType === "filming") return SWEETSIEZ_STRUCTURE_CONFIG.CHANNELS.FILMING_SESSIONS;
  if (requestType === "event") return SWEETSIEZ_STRUCTURE_CONFIG.CHANNELS.REC_OPS_MANAGEMENT;
  return SWEETSIEZ_STRUCTURE_CONFIG.CHANNELS.REC_OPS_MANAGEMENT;
}

var checkDeadlineReminders = async function checkDeadlineReminders(guild) {
  try {
    if (mongoose.connection.readyState !== 1) return;
    const now = new Date();
    const reminders = await DeadlineReminder.find({ status: "pending" }).limit(100);

    for (const reminder of reminders) {
      const deadline = new Date(reminder.deadline);
      const timeUntilDeadline = deadline.getTime() - now.getTime();
      const sentTimes = new Set((reminder.sentReminders || []).map(item => Number(item.time)));

      for (const reminderTime of reminder.reminderTimes || []) {
        if (sentTimes.has(Number(reminderTime))) continue;
        if (timeUntilDeadline > 0 && timeUntilDeadline <= Number(reminderTime)) {
          const channelId = getDeadlineReminderChannelId(reminder.requestType);
          const channel = guild?.channels
            ? await guild.channels.fetch(channelId).catch(() => null)
            : await client.channels.fetch(channelId).catch(() => null);
          if (channel?.isTextBased?.()) {
            const timeStr = Number(reminderTime) === 86400000
              ? "24 hours"
              : Number(reminderTime) === 3600000
                ? "1 hour"
                : "soon";
            await channel.send({
              content: `Reminder: A ${reminder.requestType} request deadline is in **${timeStr}** (ID: ${reminder.requestId}).`,
              allowedMentions: { parse: [] },
            }).catch(error => console.error("Failed to send deadline reminder:", error.message));
          }
          reminder.sentReminders.push({ time: Number(reminderTime), sentAt: new Date() });
        }
      }

      if (timeUntilDeadline <= 0) {
        reminder.status = "overdue";
      }
      reminder.updatedAt = new Date();
      await reminder.save();
    }
  } catch (err) {
    console.error("❌ Deadline reminder check failed:", err);
  }
};

var getEditDistance = function getEditDistance(s1, s2) {
  const a = String(s1 || "");
  const b = String(s2 || "");
  const costs = [];
  for (let i = 0; i <= a.length; i++) {
    let lastValue = i;
    for (let j = 0; j <= b.length; j++) {
      if (i === 0) {
        costs[j] = j;
      } else if (j > 0) {
        let newValue = costs[j - 1];
        if (a.charAt(i - 1) !== b.charAt(j - 1)) {
          newValue = Math.min(Math.min(newValue, lastValue), costs[j]) + 1;
        }
        costs[j - 1] = lastValue;
        lastValue = newValue;
      }
    }
    if (i > 0) costs[b.length] = lastValue;
  }
  return costs[b.length] || 0;
};

var calculateStringSimilarity = function calculateStringSimilarity(str1, str2) {
  const normalize = value => String(value || "")
    .toLowerCase()
    .replace(/https?:\/\/\S+/g, "")
    .replace(/[^\w\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  const s1 = normalize(str1);
  const s2 = normalize(str2);
  if (!s1 && !s2) return 100;
  if (!s1 || !s2) return 0;
  if (s1 === s2) return 100;

  const t1 = s1.slice(0, 500);
  const t2 = s2.slice(0, 500);
  const longer = t1.length > t2.length ? t1 : t2;
  const shorter = t1.length > t2.length ? t2 : t1;
  const editScore = longer.length
    ? ((longer.length - getEditDistance(shorter, longer)) / longer.length) * 100
    : 0;

  const words1 = new Set(s1.split(" ").filter(word => word.length > 2));
  const words2 = new Set(s2.split(" ").filter(word => word.length > 2));
  const shared = [...words1].filter(word => words2.has(word)).length;
  const union = new Set([...words1, ...words2]).size || 1;
  const tokenScore = (shared / union) * 100;

  return Math.max(0, Math.min(100, (editScore * 0.55) + (tokenScore * 0.45)));
};

function getDuplicateRequestModel(requestType) {
  if (requestType === "graphics") return GraphicsRequest;
  if (requestType === "announcement") return AnnouncementRequest;
  if (requestType === "filming") return FilmingSession;
  if (requestType === "event") return MinorEventPlan;
  return null;
}

function getDuplicateComparableFields(requestType, requestDoc) {
  if (requestType === "announcement") {
    return {
      id: requestDoc.requestId,
      title: requestDoc.title,
      description: requestDoc.message,
    };
  }
  if (requestType === "graphics") {
    return {
      id: requestDoc.requestId || requestDoc.graphicsId,
      title: requestDoc.purpose || requestDoc.title,
      description: requestDoc.textNeeded || requestDoc.description,
    };
  }
  if (requestType === "filming") {
    return {
      id: requestDoc.sessionId || requestDoc.requestId,
      title: requestDoc.title || requestDoc.theme,
      description: requestDoc.shotList || requestDoc.description || requestDoc.theme,
    };
  }
  if (requestType === "event") {
    return {
      id: requestDoc.eventId || requestDoc.planId || requestDoc.requestId,
      title: requestDoc.name || requestDoc.title,
      description: requestDoc.description || requestDoc.activityPrompt,
    };
  }
  return {
    id: requestDoc.requestId || requestDoc.id,
    title: requestDoc.title || requestDoc.name || requestDoc.purpose,
    description: requestDoc.description || requestDoc.message || "",
  };
}

var checkForDuplicateRequests = async function checkForDuplicateRequests(requestType, title, description, threshold = 75, excludeRequestId = null) {
  try {
    if (mongoose.connection.readyState !== 1) return null;
    const model = getDuplicateRequestModel(requestType);
    if (!model) return null;

    const recentRequests = await model
      .find({ createdAt: { $gte: new Date(Date.now() - 14 * 24 * 60 * 60 * 1000) } })
      .sort({ createdAt: -1 })
      .limit(30)
      .lean();

    let strongest = null;
    for (const requestDoc of recentRequests) {
      const fields = getDuplicateComparableFields(requestType, requestDoc);
      if (excludeRequestId && String(fields.id) === String(excludeRequestId)) continue;

      const titleScore = calculateStringSimilarity(title, fields.title);
      const descriptionScore = calculateStringSimilarity(description, fields.description);
      const matchScore = Math.round((titleScore * 0.4) + (descriptionScore * 0.6));
      if (matchScore >= threshold && (!strongest || matchScore > strongest.matchScore)) {
        strongest = {
          matchScore,
          similarId: fields.id || "unknown",
        };
      }
    }

    return strongest;
  } catch (err) {
    console.error("❌ Duplicate check failed:", err);
    return null;
  }
};

async function runQueuedApiOperation(item) {
  const payload = item.payload || {};
  if (item.operationType === "rank_change") {
    const roleId = payload.roleId || payload.targetRoleId || payload.rankRoleId || payload.rankId;
    if (!roleId) throw new Error("Missing roleId/rankId for queued rank change.");
    if (typeof setUserRank !== "function") throw new Error("Rank change helper is unavailable.");
    await setUserRank(item.targetRobloxUserId, roleId);
    return;
  }

  if (item.operationType === "group_operation") {
    const action = String(payload.action || "").toLowerCase();
    const roleId = payload.roleId || payload.targetRoleId || payload.rankRoleId || payload.rankId;
    if ((action === "rank_change" || action === "set_rank") && roleId) {
      if (typeof setUserRank !== "function") throw new Error("Rank change helper is unavailable.");
      await setUserRank(item.targetRobloxUserId, roleId);
      return;
    }
    if (payload.membershipPath && roleId && action === "assign_role" && typeof openCloudAssignRole === "function") {
      await openCloudAssignRole(payload.membershipPath, payload.groupId || config.GROUP_ID, roleId);
      return;
    }
    if (payload.membershipPath && roleId && action === "unassign_role" && typeof openCloudUnassignRole === "function") {
      await openCloudUnassignRole(payload.membershipPath, payload.groupId || config.GROUP_ID, roleId);
      return;
    }
    throw new Error(`Unsupported queued group operation: ${payload.action || "unknown"}.`);
  }

  throw new Error(`Unsupported queued API operation: ${item.operationType}.`);
}

var processApiFailureQueue = async function processApiFailureQueue() {
  try {
    if (mongoose.connection.readyState !== 1) return;
    const queued = await ApiFailureQueue.find({ status: { $in: ["queued", "retrying"] } })
      .sort({ updatedAt: 1 })
      .limit(10);

    for (const item of queued) {
      if (item.retryCount >= item.maxRetries) {
        item.status = "failed";
        item.updatedAt = new Date();
        await item.save();
        continue;
      }

      try {
        item.status = "retrying";
        item.updatedAt = new Date();
        await item.save();
        await runQueuedApiOperation(item);
        item.status = "completed";
        item.updatedAt = new Date();
        await item.save();
      } catch (err) {
        item.retryCount += 1;
        item.lastError = err.message;
        item.status = item.retryCount < item.maxRetries ? "retrying" : "failed";
        item.updatedAt = new Date();
        await item.save();
      }
    }
  } catch (err) {
    console.error("❌ API failure queue processing failed:", err);
  }
};

