// Build the shop embed shown by /shop
function buildShopEmbed(balance) {
  const embed = new EmbedBuilder()
    .setTitle('🛒 Sweetsiez Shop')
    .setDescription(`Your balance: **${balance.toLocaleString()} credits**\n\nBrowse items below and click a button to purchase.`)
    .setColor(0xf9a8d4);

  for (const item of SHOP_ITEMS) {
    embed.addFields({
      name: `${item.name} — ${item.price.toLocaleString()} credits`,
      value: item.description + (item.oneTime ? ' *(one-time)*' : ' *(repeatable)*'),
      inline: false,
    });
  }
  return embed;
}

// Build the button row(s) for /shop (max 5 buttons per row)
function buildShopComponents(purchasedIds) {
  const rows = [];
  let row = new ActionRowBuilder();
  let count = 0;
  for (const item of SHOP_ITEMS) {
    if (count > 0 && count % 5 === 0) {
      rows.push(row);
      row = new ActionRowBuilder();
    }
    const alreadyOwned = item.oneTime && purchasedIds.includes(item.id);
    row.addComponents(
      new ButtonBuilder()
        .setCustomId(`shop_buy_${item.id}`)
        .setLabel(alreadyOwned ? `${item.name} ✅` : item.name)
        .setStyle(alreadyOwned ? ButtonStyle.Secondary : ButtonStyle.Primary)
        .setDisabled(alreadyOwned)
    );
    count++;
  }
  rows.push(row);
  return rows;
}
