function getDevelopmentSubmissionAnswer(message) {
  const parts = [];
  const content = String(message.content || "").trim();
  if (content) parts.push(content);
  if (message.attachments?.size) {
    parts.push(...message.attachments.map(attachment => attachment.url).filter(Boolean));
  }
  return parts.join("\n").trim();
}

function normalizeDevelopmentSubmissionCategory(answer) {
  const trimmed = String(answer || "").trim();
  if (DEVELOPMENT_SUBMISSION_CONFIG.CATEGORIES[trimmed]) {
    return DEVELOPMENT_SUBMISSION_CONFIG.CATEGORIES[trimmed];
  }
  const match = Object.values(DEVELOPMENT_SUBMISSION_CONFIG.CATEGORIES)
    .find(label => label.toLowerCase() === trimmed.toLowerCase());
  return match || null;
}

async function sendDevelopmentSubmissionQuestion(channel, session) {
  const form = DEVELOPMENT_SUBMISSION_FORMS[session.type];
  const question = form.questions[session.step];
  const embed = new EmbedBuilder()
    .setColor(session.type === "bug" ? 0xed4245 : 0xfee75c)
    .setTitle(`Step ${session.step + 1} of ${form.questions.length} - ${question.title}`)
    .setDescription(question.prompt);
  await channel.send({ embeds: [embed] });
}

async function startDevelopmentSubmissionSession(user, channel, type) {
  const form = DEVELOPMENT_SUBMISSION_FORMS[type];
  const robloxUsername = verifiedUsers.get(user.id);
  if (!robloxUsername) {
    await channel.send("You must be verified before submitting a suggestion or bug report.");
    return;
  }

  developmentSubmissionSessions.set(user.id, {
    type,
    step: 0,
    answers: {},
    startedAt: Date.now(),
  });

  await channel.send({
    embeds: [
      new EmbedBuilder()
        .setColor(type === "bug" ? 0xed4245 : 0xfee75c)
        .setTitle(form.introTitle)
        .setDescription(form.introDescription),
    ],
  });
  await sendDevelopmentSubmissionQuestion(channel, developmentSubmissionSessions.get(user.id));
}

function buildDevelopmentSubmissionEmbed(doc, internal = false) {
  const form = DEVELOPMENT_SUBMISSION_FORMS[doc.type] || DEVELOPMENT_SUBMISSION_FORMS.suggestion;
  const statusColour = {
    OPEN: 0xfee75c,
    APPROVED: 0x57f287,
    DENIED: 0xed4245,
    "MORE INFO NEEDED": 0xfaa61a,
    PLANNED: 0x5865f2,
    "IN PROGRESS": 0x5865f2,
    COMPLETED: 0x57f287,
    DUPLICATE: 0x95a5a6,
    CLOSED: 0x95a5a6,
  }[String(doc.status || "OPEN").toUpperCase()] || 0xfee75c;

  const embed = new EmbedBuilder()
    .setColor(statusColour)
    .setTitle(`${form.label}: ${truncateForDiscord(doc.title, 180)}`)
    .setDescription(truncateForDiscord(doc.fields?.body || "No description provided.", 3500))
    .addFields(
      { name: "Category", value: doc.category || "General", inline: true },
      { name: "Status", value: String(doc.status || "OPEN").toUpperCase(), inline: true },
      { name: "Submission ID", value: doc.submissionId, inline: true },
      {
        name: "Submitted By",
        value:
          `<@${doc.submitterDiscordId}> (${doc.submitterTag})\n` +
          `Roblox: **${doc.submitterRobloxUsername || "Not linked"}**`,
        inline: false,
      },
    )
    .setFooter({ text: internal ? "Internal development review" : "Community votes are advisory" })
    .setTimestamp(doc.updatedAt || doc.createdAt || new Date());

  if (doc.type === "suggestion") {
    embed.addFields({ name: "Why It Would Help", value: truncateForDiscord(doc.fields?.impact || "Not provided", 1024), inline: false });
  } else {
    embed.addFields(
      { name: "Steps to Reproduce", value: truncateForDiscord(doc.fields?.steps || "Not provided", 1024), inline: false },
      { name: "Expected Behavior", value: truncateForDiscord(doc.fields?.expected || "Not provided", 1024), inline: false },
      { name: "Actual Behavior", value: truncateForDiscord(doc.fields?.actual || "Not provided", 1024), inline: false },
      { name: "Evidence", value: truncateForDiscord(doc.fields?.evidence || "None", 1024), inline: false },
    );
  }

  if (doc.developerNote) {
    embed.addFields({ name: "Developer / SHR Note", value: truncateForDiscord(doc.developerNote, 1024), inline: false });
  }
  if (internal && doc.reviewerTag) {
    embed.addFields({ name: "Last Reviewed By", value: doc.reviewerTag, inline: true });
  }

  return embed;
}

function buildDevelopmentSubmissionControls(doc) {
  const final = ["APPROVED", "DENIED", "COMPLETED", "CLOSED"].includes(String(doc.status || "").toUpperCase());
  return [
    new ActionRowBuilder().addComponents(
      new ButtonBuilder()
        .setCustomId(`devsub_approve_${doc.submissionId}`)
        .setLabel("Approve")
        .setStyle(ButtonStyle.Success)
        .setDisabled(final),
      new ButtonBuilder()
        .setCustomId(`devsub_deny_${doc.submissionId}`)
        .setLabel("Deny")
        .setStyle(ButtonStyle.Danger)
        .setDisabled(final),
      new ButtonBuilder()
        .setCustomId(`devsub_info_${doc.submissionId}`)
        .setLabel("Request Info")
        .setStyle(ButtonStyle.Secondary)
        .setDisabled(final),
      new ButtonBuilder()
        .setCustomId(`devsub_clarify_${doc.submissionId}`)
        .setLabel("Edit / Clarify")
        .setStyle(ButtonStyle.Primary)
        .setDisabled(final),
      new ButtonBuilder()
        .setCustomId(`devsub_status_${doc.submissionId}`)
        .setLabel("Change Status")
        .setStyle(ButtonStyle.Secondary),
    ),
  ];
}

async function postDevelopmentSubmission(doc) {
  const form = DEVELOPMENT_SUBMISSION_FORMS[doc.type];
  const publicChannel = await client.channels.fetch(form.publicChannelId).catch(() => null);
  const reviewChannel = await client.channels.fetch(DEVELOPMENT_SUBMISSION_CONFIG.MANAGEMENT_CHANNEL_ID).catch(() => null);
  if (!publicChannel?.isTextBased?.()) throw new Error("Public development submission channel is unavailable.");
  if (!reviewChannel?.isTextBased?.()) throw new Error("Development submissions management channel is unavailable.");

  const publicMessage = await publicChannel.send({
    embeds: [buildDevelopmentSubmissionEmbed(doc, false)],
    allowedMentions: { parse: [] },
  });
  await publicMessage.react("✅").catch(() => {});
  await publicMessage.react("❌").catch(() => {});

  let thread = null;
  try {
    thread = await publicMessage.startThread({
      name: `${form.label} - ${doc.title}`.slice(0, 100),
      autoArchiveDuration: 1440,
      reason: `New ${form.noun} community discussion`,
    });
    await thread.send("Use this thread to discuss the submission constructively. Community votes help show interest, but final decisions are made by the Development Team and Director+.");
  } catch (error) {
    console.warn("[DevelopmentSubmission] Could not create public thread:", error.message);
  }

  const reviewMessage = await reviewChannel.send({
    content: `<@&${DEVELOPMENT_SUBMISSION_CONFIG.DEV_TEAM_ROLE_ID}>`,
    embeds: [buildDevelopmentSubmissionEmbed(doc, true)],
    components: buildDevelopmentSubmissionControls(doc),
    allowedMentions: { roles: [DEVELOPMENT_SUBMISSION_CONFIG.DEV_TEAM_ROLE_ID] },
  });

  await DevelopmentSubmission.updateOne(
    { submissionId: doc.submissionId },
    {
      $set: {
        publicChannelId: publicChannel.id,
        publicMessageId: publicMessage.id,
        publicThreadId: thread?.id || null,
        reviewChannelId: reviewChannel.id,
        reviewMessageId: reviewMessage.id,
        updatedAt: new Date(),
      },
    },
  );
}

async function finishDevelopmentSubmissionSession(message, session) {
  const form = DEVELOPMENT_SUBMISSION_FORMS[session.type];
  const submissionId = createOperationalId(session.type === "bug" ? "BUG" : "SUG");
  const robloxUsername = verifiedUsers.get(message.author.id) || null;
  const fields = { ...session.answers };
  const doc = await DevelopmentSubmission.create({
    submissionId,
    type: session.type,
    category: fields.category,
    title: fields.title,
    submitterDiscordId: message.author.id,
    submitterTag: message.author.tag,
    submitterRobloxUsername: robloxUsername,
    status: "OPEN",
    fields,
    history: [{
      status: "OPEN",
      note: "Submission created.",
      by: message.author.id,
      byTag: message.author.tag,
      at: new Date(),
    }],
  });

  await postDevelopmentSubmission(doc.toObject());
  developmentSubmissionSessions.delete(message.author.id);
  await message.channel.send(
    `✅ Submission Posted\nYour ${form.noun} is now public and has been sent to the Development Team and Director+.\n\n` +
    `Submission ID: ${submissionId}\nYou will receive a DM whenever its status changes.`
  );
}

async function handleDevelopmentSubmissionDM(message) {
  const raw = String(message.content || "").trim();
  const lowered = raw.toLowerCase();
  if (lowered === "!devcancel") {
    developmentSubmissionSessions.delete(message.author.id);
    await message.reply("Your development submission has been cancelled.");
    return true;
  }

  const session = developmentSubmissionSessions.get(message.author.id);
  if (!session) return false;

  const form = DEVELOPMENT_SUBMISSION_FORMS[session.type];
  const question = form.questions[session.step];
  const answer = getDevelopmentSubmissionAnswer(message);
  if (!answer) {
    await message.reply("Please send an answer before continuing, or type `!devcancel` to cancel.");
    return true;
  }

  if (question.key === "category") {
    const category = normalizeDevelopmentSubmissionCategory(answer);
    if (!category) {
      await message.reply("Please choose a valid category: 1, 2, 3, 4, or 5.");
      return true;
    }
    session.answers.category = category;
  } else if (question.key === "title") {
    session.answers.title = answer.slice(0, 180);
  } else {
    session.answers[question.key] = answer;
  }

  session.step += 1;
  if (session.step >= form.questions.length) {
    await finishDevelopmentSubmissionSession(message, session);
    return true;
  }

  developmentSubmissionSessions.set(message.author.id, session);
  await sendDevelopmentSubmissionQuestion(message.channel, session);
  return true;
}

async function canReviewDevelopmentSubmission(interaction) {
  if (interaction.member?.roles?.cache?.has(DEVELOPMENT_SUBMISSION_CONFIG.DEV_TEAM_ROLE_ID)) {
    return { ok: true, reason: "Development Team" };
  }
  const rankInfo = await getVerifiedMainRankForDiscord(interaction.user.id).catch(() => null);
  if (isExecutiveDirectorOrLeadershipRank(rankInfo?.rank)) {
    return { ok: true, reason: "Director+" };
  }
  return { ok: false, message: "Only Development Team members or verified Director+ may process submissions." };
}

async function updateDevelopmentSubmissionMessages(doc) {
  const publicChannel = await client.channels.fetch(doc.publicChannelId).catch(() => null);
  if (publicChannel?.isTextBased?.() && doc.publicMessageId) {
    const publicMessage = await publicChannel.messages.fetch(doc.publicMessageId).catch(() => null);
    if (publicMessage) {
      await publicMessage.edit({ embeds: [buildDevelopmentSubmissionEmbed(doc, false)] }).catch(() => {});
    }
  }

  const reviewChannel = await client.channels.fetch(doc.reviewChannelId).catch(() => null);
  if (reviewChannel?.isTextBased?.() && doc.reviewMessageId) {
    const reviewMessage = await reviewChannel.messages.fetch(doc.reviewMessageId).catch(() => null);
    if (reviewMessage) {
      await reviewMessage.edit({
        embeds: [buildDevelopmentSubmissionEmbed(doc, true)],
        components: buildDevelopmentSubmissionControls(doc),
      }).catch(() => {});
    }
  }
}

async function notifyDevelopmentSubmissionSubmitter(doc, note) {
  const user = await client.users.fetch(doc.submitterDiscordId).catch(() => null);
  if (!user) return;
  const form = DEVELOPMENT_SUBMISSION_FORMS[doc.type] || DEVELOPMENT_SUBMISSION_FORMS.suggestion;
  await user.send({
    embeds: [
      new EmbedBuilder()
        .setColor(0x5bc0de)
        .setTitle(`${form.label} Update`)
        .setDescription(`${doc.title}\n\n${note || doc.developerNote || "Your submission has been updated."}`)
        .addFields(
          { name: "Current Status", value: String(doc.status || "OPEN").toUpperCase(), inline: true },
          { name: "Submission ID", value: doc.submissionId, inline: true },
        )
        .setTimestamp(),
    ],
  }).catch(() => {});
}

async function applyDevelopmentSubmissionReview({ interaction, submissionId, status, note }) {
  const permission = await canReviewDevelopmentSubmission(interaction);
  if (!permission.ok) return interaction.editReply(permission.message);

  const update = {
    status,
    reviewerDiscordId: interaction.user.id,
    reviewerTag: interaction.user.tag,
    updatedAt: new Date(),
  };
  if (note !== undefined) update.developerNote = note || null;

  const doc = await DevelopmentSubmission.findOneAndUpdate(
    { submissionId },
    {
      $set: update,
      $push: {
        history: {
          status,
          note: note || null,
          by: interaction.user.id,
          byTag: interaction.user.tag,
          at: new Date(),
        },
      },
    },
    { new: true },
  );
  if (!doc) return interaction.editReply("That submission could not be found.");

  await updateDevelopmentSubmissionMessages(doc.toObject());
  await notifyDevelopmentSubmissionSubmitter(doc.toObject(), note || `The ${permission.reason} review team updated your submission.`);
  return interaction.editReply(`Submission ${submissionId} updated to **${status}**.`);
}

async function handleDevelopmentSubmissionButton(interaction) {
  const parts = interaction.customId.split("_");
  const action = parts[1];
  const submissionId = parts.slice(2).join("_");

  if (["info", "clarify", "status"].includes(action)) {
    const permission = await canReviewDevelopmentSubmission(interaction);
    if (!permission.ok) {
      return interaction.reply({ content: permission.message, flags: MessageFlags.Ephemeral });
    }
    const { ModalBuilder, TextInputBuilder, TextInputStyle } = require("discord.js");
    const modal = new ModalBuilder()
      .setCustomId(`devsub_modal_${action}_${submissionId}`)
      .setTitle(action === "status" ? "Change Submission Status" : action === "info" ? "Request More Info" : "Edit / Clarify");
    if (action === "status") {
      modal.addComponents(
        new ActionRowBuilder().addComponents(
          new TextInputBuilder()
            .setCustomId("status")
            .setLabel("Status")
            .setStyle(TextInputStyle.Short)
            .setRequired(true)
            .setPlaceholder("Planned, In Progress, Completed, Duplicate, Closed"),
        ),
        new ActionRowBuilder().addComponents(
          new TextInputBuilder()
            .setCustomId("note")
            .setLabel("Visible note")
            .setStyle(TextInputStyle.Paragraph)
            .setRequired(false),
        ),
      );
    } else {
      modal.addComponents(
        new ActionRowBuilder().addComponents(
          new TextInputBuilder()
            .setCustomId("note")
            .setLabel(action === "info" ? "What info is needed?" : "Visible clarification")
            .setStyle(TextInputStyle.Paragraph)
            .setRequired(true),
        ),
      );
    }
    return interaction.showModal(modal);
  }

  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }
  if (action === "approve") {
    return applyDevelopmentSubmissionReview({
      interaction,
      submissionId,
      status: "APPROVED",
      note: "The Development Team and Director+ approved your submission.",
    });
  }
  if (action === "deny") {
    return applyDevelopmentSubmissionReview({
      interaction,
      submissionId,
      status: "DENIED",
      note: "The Development Team and Director+ denied your submission.",
    });
  }
  return interaction.editReply("Unknown submission action.");
}

async function handleDevelopmentSubmissionModal(interaction) {
  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }
  const parts = interaction.customId.split("_");
  const action = parts[2];
  const submissionId = parts.slice(3).join("_");
  if (action === "info") {
    return applyDevelopmentSubmissionReview({
      interaction,
      submissionId,
      status: "MORE INFO NEEDED",
      note: interaction.fields.getTextInputValue("note").trim(),
    });
  }
  if (action === "clarify") {
    const current = await DevelopmentSubmission.findOne({ submissionId }).lean();
    return applyDevelopmentSubmissionReview({
      interaction,
      submissionId,
      status: current?.status || "OPEN",
      note: interaction.fields.getTextInputValue("note").trim(),
    });
  }
  if (action === "status") {
    const status = interaction.fields.getTextInputValue("status").trim().toUpperCase();
    const note = interaction.fields.getTextInputValue("note")?.trim() || null;
    return applyDevelopmentSubmissionReview({ interaction, submissionId, status, note });
  }
  return interaction.editReply("Unknown submission update.");
}

function parseDiscordUserIds(value) {
  const ids = new Set();
  const text = String(value || "");
  for (const match of text.matchAll(/<@!?(\d{15,25})>/g)) ids.add(match[1]);
  for (const match of text.matchAll(/\b\d{15,25}\b/g)) ids.add(match[0]);
  return [...ids];
}

function formatDiscordUserList(ids) {
  return ids?.length ? ids.map(id => `<@${id}>`).join(", ") : "None";
}

const TEAM_READINESS_KEYWORDS = {
  recruitment: [
    "shift lead", "staff assistant", "promot", "trial", "mentor", "train",
    "recruit", "candidate", "staff growth", "operations", "policy", "docs",
    "quota", "radar", "applications", "supervise",
    "event", "engage", "community", "activity", "activities", "feedback",
    "poll", "announce", "announcement", "member", "host", "recap",
    "communication", "public", "involvement",
  ],
  "social-media": [
    "social", "media", "video", "film", "filming", "tiktok", "reels",
    "graphics", "graphic", "caption", "content", "marketing", "brand",
    "post", "edit", "newsletter", "awareness",
  ],
  outreach: [
    "outreach", "alliance", "alliances", "affiliate", "affiliation", "relations",
    "partnership", "partner", "visit", "visitation", "representative", "representatives",
    "network", "external", "request", "approval",
  ],
  moderation: [
    "moderation", "moderator", "mod team", "warn", "warning", "ban", "appeal",
    "automod", "auto-mod", "raid", "server safety", "enforce", "rule break",
    "filter", "alt account", "alt accounts", "phishing", "scam",
  ],
};

function getTeamReadinessVoteContext(teamKey) {
  const team = getPlacementConfig("team", teamKey);
  if (!team) return null;
  const board = getPlacementConfig("board", team.boardKey);
  const voteConfig = VOTES_CHANNELS.find(configItem => configItem.boardKey === team.boardKey);
  if (!board || !voteConfig) return null;
  return { team, board, voteConfig };
}

function calculateTeamReadinessRecommendation(responses) {
  const combined = Object.values(responses || {})
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
  const scores = {
    recruitment: 0,
    "social-media": 0,
    outreach: 0,
    moderation: 0,
  };

  for (const [teamKey, keywords] of Object.entries(TEAM_READINESS_KEYWORDS)) {
    for (const keyword of keywords) {
      if (combined.includes(keyword)) scores[teamKey] += keyword.includes(" ") ? 2 : 1;
    }
  }

  const preferred = String(responses?.preferredArea || "").toLowerCase();
  if (preferred.includes("recruit") || preferred.includes("operations") || preferred.includes("engage") || preferred.includes("event") || preferred.includes("communications")) scores.recruitment += 5;
  if (preferred.includes("social") || preferred.includes("media") || preferred.includes("marketing")) scores["social-media"] += 5;
  if (preferred.includes("outreach") || preferred.includes("alliance") || preferred.includes("relations")) scores.outreach += 5;
  if (preferred.includes("moder") || preferred.includes("warn") || preferred.includes("ban") || preferred.includes("safety")) scores.moderation += 5;

  const sorted = Object.entries(scores).sort((a, b) => b[1] - a[1]);
  const [bestTeamKey, bestScore] = sorted[0];
  const secondScore = sorted[1]?.[1] || 0;
  const teamKey = bestScore > 0 ? bestTeamKey : "recruitment";
  const confidence = bestScore === 0
    ? "Low"
    : bestScore - secondScore >= 4
      ? "High"
      : bestScore - secondScore >= 2
        ? "Medium"
        : "Low";

  return { teamKey, scores, confidence };
}

async function openVoteDiscussionForMessage(message, voteConfig, introLabel = "vote submission") {
  if (!message || !voteConfig) return null;
  await message.react("\u2705").catch(() => {});
  await message.react("\u274e").catch(() => {});

  const thread = await message.startThread({
    name: `${voteConfig.threadLabel} - Discussion`,
    autoArchiveDuration: 1440,
    reason: `New ${voteConfig.roleName} ${introLabel}`,
  }).catch(error => {
    console.warn(`Could not create vote discussion thread in ${voteConfig.channelId}:`, error.message);
    return null;
  });
  if (!thread) return null;

  const roleIds = getVoteRoleIds(voteConfig);
  const roleMentions = formatVoteRoleMentions(voteConfig);
  await thread.send({
    content: `${roleMentions}\n\n` +
      `**NEW VOTE SUBMISSION**\n\n` +
      `A new ${introLabel} has been posted in <#${voteConfig.channelId}>. Please review the post above and cast your vote using the approve or deny reactions.\n\n` +
      `**Discussion Guidelines:**\n` +
      `- Keep all discussion respectful and professional.\n` +
      `- Share any relevant context, evidence, or reasoning here.\n` +
      `- A final decision should be noted in this thread once a clear consensus is reached.\n\n` +
      `_Only ${voteConfig.roleName} members should be voting on this submission._`,
    allowedMentions: { roles: roleIds },
  }).catch(error => {
    console.warn(`Could not send vote discussion prompt for ${voteConfig.channelId}:`, error.message);
  });
  return thread;
}

function buildTeamReadinessVoteEmbed(assessmentDoc) {
  const teamContext = getTeamReadinessVoteContext(assessmentDoc.recommendedTeamKey);
  const responses = assessmentDoc.responses || {};
  return new EmbedBuilder()
    .setColor(
      assessmentDoc.recommendedTeamKey === "recruitment" ? 0x2f80ed :
      assessmentDoc.recommendedTeamKey === "outreach" ? 0xf1c40f :
      assessmentDoc.recommendedTeamKey === "moderation" ? 0x4e56c9 :
      0xeb5757,
    )
    .setTitle("Team Readiness Assessment")
    .setDescription(
      `**${assessmentDoc.managerRobloxUsername}** submitted their Manager team readiness assessment.\n\n` +
      `The bot recommends **${assessmentDoc.recommendedTeamLabel}**. This is only a recommendation; leadership should still consider performance, team openings, and what Sweetsiez needs most.`
    )
    .addFields(
      { name: "Assessment ID", value: assessmentDoc.assessmentId, inline: true },
      { name: "Manager", value: `<@${assessmentDoc.managerDiscordId}>`, inline: true },
      { name: "Recommended Board Vote", value: teamContext?.board?.label || assessmentDoc.recommendedBoardLabel || "Unknown", inline: true },
      { name: "Confidence", value: assessmentDoc.confidence || "Unknown", inline: true },
      { name: "Scores", value: Object.entries(assessmentDoc.scores || {}).map(([key, score]) => `${key}: ${score}`).join("\n") || "None", inline: true },
      { name: "Started By", value: `${assessmentDoc.startedByTag} (${assessmentDoc.startedByDiscordId})`, inline: false },
      { name: "Strengths", value: truncateForDiscord(responses.strengths || "Not provided", 1024), inline: false },
      { name: "Interests", value: truncateForDiscord(responses.interests || "Not provided", 1024), inline: false },
      { name: "Leadership Style", value: truncateForDiscord(responses.leadershipStyle || "Not provided", 1024), inline: false },
      { name: "Preferred Team", value: truncateForDiscord(responses.preferredArea || "Not provided", 1024), inline: false },
      { name: "Where They Want To Help", value: truncateForDiscord(responses.needs || "Not provided", 1024), inline: false },
    )
    .setTimestamp(assessmentDoc.submittedAt || new Date());
}

async function handleTeamReadinessCommand(interaction) {
  const subcommand = interaction.options.getSubcommand();
  if (subcommand !== "start") return interaction.editReply("Unknown team readiness action.");

  const issuerRank = await getVerifiedMainRankForDiscord(interaction.user.id);
  if (!issuerRank || issuerRank.rank < SWEETSIEZ_STRUCTURE_CONFIG.EXECUTIVE_BOARD_RANK) {
    return interaction.editReply("You must be verified and Executive+ to start a Team Readiness Assessment.");
  }

  const targetUser = interaction.options.getUser("user", true);
  if (targetUser.bot) return interaction.editReply("Please choose a real staff member, not a bot.");

  const targetRank = await getVerifiedMainRankForDiscord(targetUser.id);
  if (!targetRank) return interaction.editReply("I could not resolve that user's Sweetsiez rank.");
  if (targetRank.rank !== SWEETSIEZ_STRUCTURE_CONFIG.MANAGER_RANK) {
    return interaction.editReply(
      `${targetUser} must currently be **Manager** (rank ${SWEETSIEZ_STRUCTURE_CONFIG.MANAGER_RANK}) to receive this assessment. ` +
      `Their current rank is **${targetRank.rankName || `Rank ${targetRank.rank}`}** (${targetRank.rank}).`
    );
  }

  await TeamReadinessAssessment.updateMany(
    { managerDiscordId: targetUser.id, status: "pending" },
    { $set: { status: "cancelled", updatedAt: new Date() } },
  ).catch(() => {});

  const assessmentDoc = await TeamReadinessAssessment.create({
    assessmentId: createOperationalId("TRD"),
    managerDiscordId: targetUser.id,
    managerTag: targetUser.tag,
    managerRobloxUsername: targetRank.robloxUsername,
    managerRobloxUserId: String(targetRank.robloxUserId || targetRank.robloxId),
    startedByDiscordId: interaction.user.id,
    startedByTag: interaction.user.tag,
  });

  const dmEmbed = new EmbedBuilder()
    .setColor(0xffb6c1)
    .setTitle("Team Readiness Assessment")
    .setDescription(
      "Congratulations on becoming a Manager. Please complete this short assessment so leadership can review which Manager sub-team may fit you best.\n\n" +
      "The result is a recommendation only; leadership will still consider performance, openings, and what Sweetsiez needs most."
    )
    .addFields(
      { name: "Assessment ID", value: assessmentDoc.assessmentId, inline: true },
      { name: "Possible Teams", value: "Human Resources Aspirant\nPublic Relations Aspirant\nPublic Relations Aspirant", inline: false },
    )
    .setTimestamp();
  const row = new ActionRowBuilder().addComponents(
    new ButtonBuilder()
      .setCustomId(`readiness_start_${assessmentDoc.assessmentId}`)
      .setLabel("Open Assessment")
      .setStyle(ButtonStyle.Primary),
  );

  const dm = await targetUser.send({ embeds: [dmEmbed], components: [row] }).catch(() => null);
  if (!dm) {
    return interaction.editReply(
      `Assessment ${assessmentDoc.assessmentId} was created, but I could not DM ${targetUser}. Ask them to open DMs and rerun the command.`
    );
  }

  await logBoardContribution({
    board: "operations",
    activityType: "team_readiness_sent",
    discordId: interaction.user.id,
    sourceType: "team_readiness",
    sourceId: assessmentDoc.assessmentId,
    summary: `Sent a Team Readiness Assessment to ${targetRank.robloxUsername}.`,
    loggedBy: interaction.user,
  }).catch(() => {});

  return interaction.editReply(`Team Readiness Assessment sent to ${targetUser}. Assessment ID: ${assessmentDoc.assessmentId}`);
}

async function handleTeamReadinessButton(interaction) {
  const assessmentId = interaction.customId.replace("readiness_start_", "");
  const replyPayload = content => interaction.reply({
    content,
    ...(interaction.guild ? { flags: MessageFlags.Ephemeral } : {}),
  });
  const assessmentDoc = await TeamReadinessAssessment.findOne({ assessmentId });
  if (!assessmentDoc) return replyPayload("That assessment could not be found.");
  if (assessmentDoc.managerDiscordId !== interaction.user.id) {
    return replyPayload("This assessment belongs to a different Manager.");
  }
  if (assessmentDoc.status !== "pending") {
    return replyPayload("This assessment has already been submitted or closed.");
  }

  const { ModalBuilder, TextInputBuilder, TextInputStyle } = require("discord.js");
  const modal = new ModalBuilder()
    .setCustomId(`readiness_modal_${assessmentId}`)
    .setTitle("Team Readiness Assessment");
  modal.addComponents(
    new ActionRowBuilder().addComponents(
      new TextInputBuilder()
        .setCustomId("strengths")
        .setLabel("Strengths / strongest work areas")
        .setStyle(TextInputStyle.Paragraph)
        .setMinLength(10)
        .setMaxLength(700)
        .setRequired(true),
    ),
    new ActionRowBuilder().addComponents(
      new TextInputBuilder()
        .setCustomId("interests")
        .setLabel("What work sounds most interesting?")
        .setStyle(TextInputStyle.Paragraph)
        .setMinLength(10)
        .setMaxLength(700)
        .setRequired(true),
    ),
    new ActionRowBuilder().addComponents(
      new TextInputBuilder()
        .setCustomId("leadership_style")
        .setLabel("Leadership style")
        .setStyle(TextInputStyle.Paragraph)
        .setMinLength(10)
        .setMaxLength(700)
        .setRequired(true),
    ),
    new ActionRowBuilder().addComponents(
      new TextInputBuilder()
        .setCustomId("preferred_area")
        .setLabel("Preferred team, if any")
        .setStyle(TextInputStyle.Short)
        .setMaxLength(100)
        .setRequired(false)
        .setPlaceholder("Growth, Media, or Outreach"),
    ),
    new ActionRowBuilder().addComponents(
      new TextInputBuilder()
        .setCustomId("needs")
        .setLabel("Where should Sweetsiez use you?")
        .setStyle(TextInputStyle.Paragraph)
        .setMinLength(10)
        .setMaxLength(700)
        .setRequired(true),
    ),
  );
  return interaction.showModal(modal);
}

async function handleTeamReadinessModal(interaction) {
  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply(interaction.guild ? { flags: MessageFlags.Ephemeral } : {}).catch(() => {});
  }

  const assessmentId = interaction.customId.replace("readiness_modal_", "");
  let assessmentDoc = await TeamReadinessAssessment.findOne({ assessmentId });
  if (!assessmentDoc) return interaction.editReply("That assessment could not be found.");
  if (assessmentDoc.managerDiscordId !== interaction.user.id) {
    return interaction.editReply("This assessment belongs to a different Manager.");
  }
  if (assessmentDoc.status !== "pending") {
    return interaction.editReply("This assessment has already been submitted or closed.");
  }

  const responses = {
    strengths: interaction.fields.getTextInputValue("strengths").trim(),
    interests: interaction.fields.getTextInputValue("interests").trim(),
    leadershipStyle: interaction.fields.getTextInputValue("leadership_style").trim(),
    preferredArea: interaction.fields.getTextInputValue("preferred_area")?.trim() || "No preference listed",
    needs: interaction.fields.getTextInputValue("needs").trim(),
  };
  const recommendation = calculateTeamReadinessRecommendation(responses);
  const teamContext = getTeamReadinessVoteContext(recommendation.teamKey);
  if (!teamContext) {
    return interaction.editReply("I could not find the vote channel for that recommended team. Please contact a developer.");
  }

  assessmentDoc = await TeamReadinessAssessment.findOneAndUpdate(
    { assessmentId, status: "pending" },
    {
      $set: {
        status: "submitted",
        responses,
        scores: recommendation.scores,
        recommendedTeamKey: recommendation.teamKey,
        recommendedTeamLabel: teamContext.team.label,
        recommendedBoardKey: teamContext.team.boardKey,
        recommendedBoardLabel: teamContext.board.label,
        confidence: recommendation.confidence,
        submittedAt: new Date(),
        updatedAt: new Date(),
      },
    },
    { new: true },
  );
  if (!assessmentDoc) return interaction.editReply("This assessment was already submitted.");

  const guild = client.guilds.cache.get(SWEETSIEZ_STRUCTURE_CONFIG.GUILD_ID) ||
    client.guilds.cache.get(config.IA_GUILD_ID) ||
    client.guilds.cache.first();
  const voteChannel = guild
    ? await guild.channels.fetch(teamContext.voteConfig.channelId).catch(() => null)
    : null;
  if (!voteChannel?.isTextBased?.()) {
    return interaction.editReply(
      `Assessment submitted and recommendation saved as **${teamContext.team.label}**, but I could not reach the board vote channel.`
    );
  }

  const voteMessage = await voteChannel.send({
    embeds: [buildTeamReadinessVoteEmbed(assessmentDoc)],
    allowedMentions: { parse: [] },
  });
  const voteThread = await openVoteDiscussionForMessage(
    voteMessage,
    teamContext.voteConfig,
    "Team Readiness Assessment",
  );
  assessmentDoc.voteChannelId = voteChannel.id;
  assessmentDoc.voteMessageId = voteMessage.id;
  assessmentDoc.voteThreadId = voteThread?.id || null;
  assessmentDoc.updatedAt = new Date();
  await assessmentDoc.save();

  return interaction.editReply(
    `Assessment submitted. The bot recommends **${teamContext.team.label}** and sent it to **${teamContext.voteConfig.roleName}** for review.`
  );
}

function normalizeBoardDateInput(value) {
  const match = String(value || "").trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{2}|\d{4})$/);
  if (!match) return null;
  const month = Number(match[1]);
  const day = Number(match[2]);
  let year = Number(match[3]);
  if (year < 100) year += 2000;
  const date = new Date(year, month - 1, day);
  if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) return null;
  const mm = String(month).padStart(2, "0");
  const dd = String(day).padStart(2, "0");
  const yyyy = String(year);
  const yy = yyyy.slice(-2);
  return {
    display: `${mm}/${dd}/${yyyy}`,
    short: `${mm}/${dd}/${yy}`,
    date,
  };
}

const ANNOUNCEMENT_TARGETS = {
  announcements: {
    label: "Announcements",
    channelKey: "PUBLIC_ANNOUNCEMENTS",
  },
  events: {
    label: "Events",
    channelKey: "PUBLIC_EVENTS",
  },
  awareness: {
    label: "Awareness",
    channelKey: "PUBLIC_AWARENESS",
  },
  "social-media": {
    label: "Social Media",
    channelKey: "PUBLIC_SOCIAL_MEDIA",
  },
  promotions: {
    label: "Promotions",
    channelKey: "PUBLIC_PROMOTIONS",
  },
};

const ANNOUNCEMENT_TYPE_LABELS = {
  general: "General",
  event: "Event",
  awareness: "Awareness",
  staff: "Staff",
  promotion: "Promotion",
  clarification: "Clarification",
  development: "Development",
  marketing: "Public Relations",
  operations: "Human Resources",
};

const ANNOUNCEMENT_PING_LABELS = {
  none: "No ping",
  here: "@here",
  everyone: "@everyone",
  role: "Role ping",
  role_here: "Role ping + @here",
};

const ANNOUNCEMENT_STATUS_LABELS = {
  submitted: "Pending Review",
  claimed: "Claimed",
  needs_edits: "Needs Edits",
  approved: "Approved",
  scheduled: "Scheduled",
  posted: "Posted",
  denied: "Denied",
  archived: "Archived",
};

function getAnnouncementTargetConfig(target) {
  return ANNOUNCEMENT_TARGETS[target] || ANNOUNCEMENT_TARGETS.announcements;
}

function getAnnouncementTargetChannelId(target, requestDoc = null) {
  if ((requestDoc?.target || target) === "promotions" && Number(requestDoc?.promotionRank || 0) >= SWEETSIEZ_STRUCTURE_CONFIG.CEO_RANK) {
    return SWEETSIEZ_STRUCTURE_CONFIG.CHANNELS.PUBLIC_ANNOUNCEMENTS;
  }
  const targetConfig = getAnnouncementTargetConfig(target);
  return SWEETSIEZ_STRUCTURE_CONFIG.CHANNELS[targetConfig.channelKey] || SWEETSIEZ_STRUCTURE_CONFIG.CHANNELS.PUBLIC_ANNOUNCEMENTS;
}

function parseDiscordRoleIds(value) {
  const ids = new Set();
  const text = String(value || "");
  for (const match of text.matchAll(/<@&(\d{15,25})>/g)) ids.add(match[1]);
  for (const match of text.matchAll(/\b\d{15,25}\b/g)) ids.add(match[0]);
  return [...ids];
}

const ANNOUNCEMENT_FIXED_TARGET_ROLE_PINGS = {
  awareness: SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Awareness Ping"],
  "social-media": SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Social Media Ping"],
};

function getPromotionAnnouncementPingForRank(rank) {
  const numericRank = Number(rank || 0);
  const promotionsRoleId = SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Promotions Ping"];
  if (numericRank >= 8 && numericRank <= 13) {
    return { ok: true, pingRequest: "role", pingText: `<@&${promotionsRoleId}>` };
  }
  if (numericRank === SWEETSIEZ_STRUCTURE_CONFIG.EXECUTIVE_DIRECTOR_RANK) {
    return { ok: true, pingRequest: "role_here", pingText: `<@&${promotionsRoleId}>` };
  }
  if (numericRank >= SWEETSIEZ_STRUCTURE_CONFIG.VICE_PRESIDENT_RANK) {
    return { ok: true, pingRequest: "everyone", pingText: null };
  }
  return {
    ok: false,
    message: "Promotion announcements only support promoted ranks 8-13, Director, or Director+.",
  };
}

function normalizeAnnouncementPingForTarget({ target, pingRequest, pingText, promotionRank }) {
  if (target === "promotions") {
    const numericRank = Number(promotionRank || 0);
    if (!Number.isInteger(numericRank) || numericRank <= 0) {
      return { ok: false, message: "Please include `promotion_rank` when sending a promotion announcement request." };
    }
    return { ...getPromotionAnnouncementPingForRank(numericRank), promotionRank: numericRank };
  }

  const fixedRoleId = ANNOUNCEMENT_FIXED_TARGET_ROLE_PINGS[target];
  if (fixedRoleId) {
    if (pingRequest === "none") return { ok: true, pingRequest, pingText: null, promotionRank: null };
    if (pingRequest !== "role") {
      return {
        ok: false,
        message: `${getAnnouncementTargetConfig(target).label} announcements may only use no ping or <@&${fixedRoleId}>.`,
      };
    }
    const requestedRoleIds = parseDiscordRoleIds(pingText);
    if (requestedRoleIds.length && requestedRoleIds.some(roleId => roleId !== fixedRoleId)) {
      return {
        ok: false,
        message: `${getAnnouncementTargetConfig(target).label} announcements may only ping <@&${fixedRoleId}>.`,
      };
    }
    return { ok: true, pingRequest: "role", pingText: `<@&${fixedRoleId}>`, promotionRank: null };
  }

  if (pingRequest === "role" && parseDiscordRoleIds(pingText).length === 0) {
    return { ok: false, message: "For a role ping request, please put the role mention or role ID in `ping_details`." };
  }
  return { ok: true, pingRequest, pingText, promotionRank: null };
}

function announcementStatusColor(status) {
  if (status === "posted") return 0x57f287;
  if (status === "denied") return 0xed4245;
  if (status === "archived") return 0x95a5a6;
  if (status === "scheduled") return 0x5bc0de;
  if (status === "approved") return 0x57f287;
  if (status === "needs_edits") return 0xf1c40f;
  if (status === "claimed") return 0xbb6bd9;
  return 0xf1c40f;
}

function isFixedAnnouncementRolePing(requestDoc) {
  if ((requestDoc?.pingRequest || "none") !== "role") return false;
  const roleIds = parseDiscordRoleIds(requestDoc.pingText);
  if (roleIds.length !== 1) return false;
  if (requestDoc.target === "promotions") {
    const promotionRank = Number(requestDoc.promotionRank || 0);
    return promotionRank >= 8
      && promotionRank <= 13
      && roleIds[0] === SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Promotions Ping"];
  }
  const fixedRoleId = ANNOUNCEMENT_FIXED_TARGET_ROLE_PINGS[requestDoc.target];
  return Boolean(fixedRoleId && roleIds[0] === fixedRoleId);
}

function announcementRequiresOfficerApproval(requestDoc) {
  if (isFixedAnnouncementRolePing(requestDoc)) return false;
  return ["here", "everyone", "role", "role_here"].includes(requestDoc.pingRequest || "none");
}

function hasAnnouncementOfficerAccess(context) {
  return (
    context.rank >= SWEETSIEZ_STRUCTURE_CONFIG.CEO_RANK ||
    hasAnyRoleId(context.member, [
      SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Head of Marketing"],
    ])
  );
}

function buildAnnouncementHistoryEntry(status, actor, note = null) {
  return {
    status,
    note,
    by: actor?.id || null,
    byTag: actor?.tag || "Sweetsiez Assistant",
    at: new Date(),
  };
}

function formatAnnouncementTarget(requestDoc) {
  const targetConfig = getAnnouncementTargetConfig(requestDoc.target);
  const channelId = getAnnouncementTargetChannelId(requestDoc.target, requestDoc);
  return channelId ? `${targetConfig.label} (<#${channelId}>)` : targetConfig.label;
}

function formatAnnouncementPing(requestDoc) {
  const pingRequest = requestDoc.pingRequest || "none";
  if (pingRequest === "role_here") {
    const roleIds = parseDiscordRoleIds(requestDoc.pingText);
    const roleText = roleIds.length ? roleIds.map(roleId => `<@&${roleId}>`).join(", ") : "Role ping";
    return `${roleText} + @here`;
  }
  if (pingRequest === "role") {
    const roleIds = parseDiscordRoleIds(requestDoc.pingText);
    return roleIds.length ? roleIds.map(roleId => `<@&${roleId}>`).join(", ") : "Role ping requested";
  }
  return ANNOUNCEMENT_PING_LABELS[pingRequest] || "No ping";
}

function buildAnnouncementPublicPayload(requestDoc) {
  const pingRequest = requestDoc.pingRequest || "none";
  const roleIds = pingRequest === "role" ? parseDiscordRoleIds(requestDoc.pingText) : [];
  const roleHereIds = pingRequest === "role_here" ? parseDiscordRoleIds(requestDoc.pingText) : [];
  let content = "";
  const allowedMentions = { parse: [] };

  if (pingRequest === "here") {
    content = "@here";
    allowedMentions.parse = ["everyone"];
  } else if (pingRequest === "everyone") {
    content = "@everyone";
    allowedMentions.parse = ["everyone"];
  } else if (pingRequest === "role" && roleIds.length) {
    content = roleIds.map(roleId => `<@&${roleId}>`).join(" ");
    allowedMentions.roles = roleIds;
  } else if (pingRequest === "role_here" && roleHereIds.length) {
    content = `${roleHereIds.map(roleId => `<@&${roleId}>`).join(" ")} @here`;
    allowedMentions.parse = ["everyone"];
    allowedMentions.roles = roleHereIds;
  }

  return {
    content,
    embeds: [
      new EmbedBuilder()
        .setColor(0x5bc0de)
        .setTitle(requestDoc.title)
        .setDescription(truncateForDiscord(requestDoc.message, 4000))
        .setTimestamp(),
    ],
    components: [buildCommunityFeedbackSourceRow("announcement", requestDoc.requestId)],
    allowedMentions,
  };
}

function parseAnnouncementScheduleInput(value) {
  const match = String(value || "").trim().match(
    /^(\d{1,2})\/(\d{1,2})\/(\d{2,4})\s+(\d{1,2})(?::(\d{2}))?\s*(AM|PM)(?:\s*(?:EST|EDT|ET))?$/i,
  );
  if (!match) return null;
  const month = Number(match[1]);
  const day = Number(match[2]);
  let year = Number(match[3]);
  if (year < 100) year += 2000;
  let hour = Number(match[4]);
  const minute = Number(match[5] || 0);
  const meridiem = match[6].toUpperCase();
  if (hour < 1 || hour > 12 || minute < 0 || minute > 59) return null;
  if (meridiem === "PM" && hour !== 12) hour += 12;
  if (meridiem === "AM" && hour === 12) hour = 0;

  const date = new Date(year, month - 1, day);
  if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) return null;
  return easternLocalToDate({ year, month, day }, hour, minute);
}

function parseEventScheduledAt(dateInfo, timeText) {
  const match = String(timeText || "").trim().match(
    /(\d{1,2})(?::(\d{2}))?\s*(AM|PM)(?:\s*(?:EST|EDT|ET))?/i,
  );
  if (!dateInfo || !match) return null;
  let hour = Number(match[1]);
  const minute = Number(match[2] || 0);
  const meridiem = match[3].toUpperCase();
  if (hour < 1 || hour > 12 || minute < 0 || minute > 59) return null;
  if (meridiem === "PM" && hour !== 12) hour += 12;
  if (meridiem === "AM" && hour === 12) hour = 0;
  return easternLocalToDate(
    {
      year: dateInfo.date.getFullYear(),
      month: dateInfo.date.getMonth() + 1,
      day: dateInfo.date.getDate(),
    },
    hour,
    minute,
  );
}

function generateEventCheckInCode() {
  const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let code = "";
  for (let i = 0; i < 6; i++) {
    code += alphabet[Math.floor(Math.random() * alphabet.length)];
  }
  return code;
}

function getEventVerifiedCheckIns(eventDoc) {
  return (eventDoc.checkIns || [])
    .filter(entry => entry?.discordId && entry.valid !== false);
}

function getEventVerifiedAttendeeIds(eventDoc) {
  return [...new Set(getEventVerifiedCheckIns(eventDoc).map(entry => String(entry.discordId)))];
}

function formatEventStatus(status) {
  const labels = {
    planning: "Planning",
    approved: "Approved",
    active: "Live",
    awaiting_recap: "Awaiting Recap",
    cancelled: "Cancelled",
    completed: "Completed",
  };
  return labels[status] || String(status || "Unknown");
}

function eventStatusColor(status) {
  if (status === "cancelled") return 0xed4245;
  if (status === "completed") return 0x57f287;
  if (status === "active") return 0xf1c40f;
  if (status === "awaiting_recap") return 0xbb6bd9;
  return 0x5bc0de;
}

function formatEventTimeWindow(eventDoc) {
  if (eventDoc.activeStartedAt && eventDoc.activeEndsAt) {
    return `<t:${Math.floor(new Date(eventDoc.activeStartedAt).getTime() / 1000)}:t> - <t:${Math.floor(new Date(eventDoc.activeEndsAt).getTime() / 1000)}:t>`;
  }
  if (eventDoc.scheduledAt) return `<t:${Math.floor(new Date(eventDoc.scheduledAt).getTime() / 1000)}:F>`;
  return `${eventDoc.date} at ${eventDoc.time}`;
}

function buildEventPlanningContent(eventDoc) {
  return [
    `EVENT NAME: ${eventDoc.name}`,
    `HOST(S): ${eventDoc.hosts || "Not set"}`,
    `EVENT DESCRIPTION: ${eventDoc.description}`,
    `TIME: ${eventDoc.time}`,
    `COLLABORATORS: ${eventDoc.collaborators || "None"}`,
    "",
    `Event ID: ${eventDoc.eventId}`,
    `Status: ${eventDoc.status}`,
    `Scheduled At: ${eventDoc.scheduledAt ? eventDoc.scheduledAt.toISOString() : "Not parsed"}`,
  ].join("\n");
}

function buildPublicEventEmbed(eventDoc) {
  const verifiedCount = getEventVerifiedAttendeeIds(eventDoc).length;
  const ratingStats = getEventRatingStats(eventDoc);
  const embed = new EmbedBuilder()
    .setColor(eventStatusColor(eventDoc.status))
    .setTitle(eventDoc.status === "cancelled" ? `Cancelled: ${eventDoc.name}` : eventDoc.name)
    .setDescription(truncateForDiscord(eventDoc.description, 2000))
    .addFields(
      { name: "Type", value: eventDoc.type, inline: true },
      { name: "Date", value: eventDoc.date, inline: true },
      { name: "Time", value: eventDoc.time, inline: true },
      { name: "Status", value: formatEventStatus(eventDoc.status), inline: true },
      { name: "Hosts", value: truncateForDiscord(eventDoc.hosts || "Not set", 1024), inline: false },
      { name: "Collaborators", value: truncateForDiscord(eventDoc.collaborators || "None", 1024), inline: false },
      { name: "RSVPs", value: String(eventDoc.rsvps?.length || 0), inline: true },
      { name: "Verified Attendance", value: String(verifiedCount), inline: true },
      { name: "Quality", value: ratingStats.count ? `${ratingStats.average}/5 (${ratingStats.count})` : "Not rated", inline: true },
      { name: "Event ID", value: eventDoc.eventId, inline: true },
    )
    .setTimestamp(eventDoc.updatedAt || new Date());
  if (eventDoc.scheduledAt) embed.addFields({ name: "Scheduled", value: `<t:${Math.floor(new Date(eventDoc.scheduledAt).getTime() / 1000)}:F>`, inline: false });
  if (eventDoc.status === "active") {
    embed.addFields({
      name: "Live Check-In",
      value:
        `Check-in is open until <t:${Math.floor(new Date(eventDoc.activeEndsAt).getTime() / 1000)}:t>.\n` +
        "Use the event code shared by the host during the event. RSVPs alone do not count as attendance.",
      inline: false,
    });
  }
  if (eventDoc.status === "awaiting_recap") {
    embed.addFields({ name: "Check-In Closed", value: "This event is waiting for an Human Resources recap.", inline: false });
  }
  if (eventDoc.cancelReason) embed.addFields({ name: "Cancel Reason", value: truncateForDiscord(eventDoc.cancelReason, 1024), inline: false });
  if (eventDoc.recap) embed.addFields({ name: "Recap", value: truncateForDiscord(eventDoc.recap, 1024), inline: false });
  return embed;
}

function buildEventRsvpRow(eventDoc) {
  const rsvpDisabled = !["approved"].includes(eventDoc.status);
  const checkInDisabled = eventDoc.status !== "active";
  return new ActionRowBuilder().addComponents(
    new ButtonBuilder()
      .setCustomId(`bevt_rsvp_${eventDoc.eventId}`)
      .setLabel("RSVP")
      .setStyle(ButtonStyle.Success)
      .setDisabled(rsvpDisabled),
    new ButtonBuilder()
      .setCustomId(`bevt_leave_${eventDoc.eventId}`)
      .setLabel("Remove RSVP")
      .setStyle(ButtonStyle.Secondary)
      .setDisabled(rsvpDisabled),
    new ButtonBuilder()
      .setCustomId(`bevt_checkin_${eventDoc.eventId}`)
      .setLabel("Check In")
      .setStyle(ButtonStyle.Primary)
      .setDisabled(checkInDisabled),
    new ButtonBuilder()
      .setCustomId(`cfb_open_event_${eventDoc.eventId}`)
      .setLabel("Send Feedback")
      .setStyle(ButtonStyle.Secondary),
  );
}

function normalizeMinorEventKind(kind) {
  const value = String(kind || "").toLowerCase().replace(/[\s-]+/g, "_");
  if (["daily", "daily_activity", "daily_activities", "activity"].includes(value)) return "daily_activity";
  if (["game", "gamenight", "game_night", "gamenights", "game_nights"].includes(value)) return "gamenight";
  return null;
}

function minorEventKindLabel(kind) {
  return kind === "daily_activity" ? "Daily Activities" : "Gamenights";
}

/**
 * Who may claim weekly daily-activity / gamenight posts: the Public Relations Department
 * and Public Relations Aspirants. Server owner, Discord Administrators and leadership
 * (rank CEO_RANK+) may also claim so the posts can never be locked out.
 */
function hasMinorEventClaimAccess(context) {
  const member = context?.member;
  if (!member) return false;
  if (member.guild?.ownerId && member.guild.ownerId === member.id) return true;
  if (member.permissions?.has?.(PermissionFlagsBits.Administrator)) return true;
  if (Number(context?.rank || 0) >= SWEETSIEZ_STRUCTURE_CONFIG.CEO_RANK) return true;
  return hasAnyRoleId(member, MINOR_EVENT_CONFIG.CLAIM_ROLE_IDS);
}

const MINOR_EVENT_CLAIM_DENIED_MESSAGE =
  "Only the Public Relations Department, Public Relations Aspirants, and Administrators can claim these slots.";

function getMinorEventWeekInfo(referenceDate = new Date(), mode = "current") {
  const quotaWindow = getQuotaWindow(referenceDate, mode);
  return {
    ...quotaWindow,
    weekKey: quotaWindow.weekDates[0],
    weekLabel: quotaWindow.weekLabel,
  };
}

function ymdFromString(dayKey) {
  const [year, month, day] = String(dayKey || "").split("-").map(Number);
  if (!year || !month || !day) return null;
  return { year, month, day };
}

function formatMinorEventShortDate(dayKey) {
  const ymd = ymdFromString(dayKey);
  if (!ymd) return dayKey;
  return `${ymd.month}/${ymd.day}/${String(ymd.year).slice(-2)}`;
}

function getMinorEventWeekDatesFromKey(weekKey) {
  const start = ymdFromString(weekKey);
  if (!start) return [];
  const dates = [];
  for (let i = 0; i < 7; i++) dates.push(formatYmd(addDaysToYmd(start, i)));
  return dates;
}

function getMinorEventDayLabel(dayKey) {
  const ymd = ymdFromString(dayKey);
  if (!ymd) return dayKey;
  const weekday = new Date(Date.UTC(ymd.year, ymd.month - 1, ymd.day)).toLocaleDateString("en-US", {
    weekday: "long",
    timeZone: "UTC",
  });
  return `${weekday} ${formatMinorEventShortDate(dayKey)}`;
}

function parseMinorEventTimeOnDay(dayKey, timeText) {
  const ymd = ymdFromString(dayKey);
  const match = String(timeText || "").trim().match(/(\d{1,2})(?::(\d{2}))?\s*(AM|PM)(?:\s*(?:EST|EDT|ET))?/i);
  if (!ymd || !match) return null;
  let hour = Number(match[1]);
  const minute = Number(match[2] || 0);
  const meridiem = match[3].toUpperCase();
  if (hour < 1 || hour > 12 || minute < 0 || minute > 59) return null;
  if (meridiem === "PM" && hour !== 12) hour += 12;
  if (meridiem === "AM" && hour === 12) hour = 0;
  return easternLocalToDate(ymd, hour, minute);
}

function getMinorEventDailyScheduledAt(dayKey) {
  const ymd = ymdFromString(dayKey);
  if (!ymd) return null;
  return easternLocalToDate(ymd, MINOR_EVENT_CONFIG.DAILY_POST_HOUR, MINOR_EVENT_CONFIG.DAILY_POST_MINUTE);
}

function resolveMinorEventDayKey(planDoc, rawDay) {
  const weekDates = getMinorEventWeekDatesFromKey(planDoc.weekKey);
  const raw = String(rawDay || "").trim().toLowerCase();
  if (!raw) return null;
  const weekdays = weekDates.map(dayKey => ({
    dayKey,
    full: getMinorEventDayLabel(dayKey).split(" ")[0].toLowerCase(),
  }));
  const byName = weekdays.find(item => item.full === raw || item.full.slice(0, 3) === raw.slice(0, 3));
  if (byName) return byName.dayKey;

  const match = raw.match(/^(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?$/);
  if (!match) return null;
  const month = Number(match[1]);
  const day = Number(match[2]);
  const year = match[3]
    ? (Number(match[3]) < 100 ? 2000 + Number(match[3]) : Number(match[3]))
    : ymdFromString(planDoc.weekKey)?.year;
  const key = formatYmd({ year, month, day });
  return weekDates.includes(key) ? key : null;
}

function getDailyActivityEmoji(activityType) {
  const lower = String(activityType || "").toLowerCase();
  if (lower.includes("riddle")) return "🧩";
  if (lower.includes("guess")) return "🔎";
  if (lower.includes("question") || lower.includes("qotd")) return "💬";
  if (lower.includes("poll")) return "📊";
  if (lower.includes("trivia")) return "🎲";
  return "☀️";
}

function getMinorEventPlanningPingRoleIds() {
  // Minor events are an Engagement responsibility, so the weekly planning ping goes to the
  // Public Relations Aspirant (the manager-level placement, formerly Public Relations Aspirant) and the
  // Public Relations Department (formerly Public Relations Department). Both roles were renamed in place, so
  // these keys still hold the current role ids; the literals are a safety net.
  return [
    SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Media Team"] || "1521611459489038418", // Engagement Aspirant
    SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Marketing Board"] || "1521611451679244492", // Engagement Department
  ].filter(Boolean);
}

function buildMinorEventPlanningPingContent(kind) {
  const roleMentions = getMinorEventPlanningPingRoleIds()
    .map(roleId => `<@&${roleId}>`)
    .join(" ");
  return `${roleMentions}\nweekly ${minorEventKindLabel(kind).toLowerCase()} planning is open for this week. please claim your slots below.`;
}

function getMinorEventPublicPingRoleIds() {
  return [MINOR_EVENT_CONFIG.EVENT_PING_ROLE_ID].filter(Boolean);
}

function appendMinorEventPublicPing(content) {
  const roleMentions = getMinorEventPublicPingRoleIds()
    .map(roleId => `<@&${roleId}>`)
    .join(" ");
  return roleMentions ? `${content}\n\n${roleMentions}` : content;
}

function buildMinorEventPublicContent(claimDoc) {
  const publicPingRoleIds = getMinorEventPublicPingRoleIds();
  if (claimDoc.kind === "daily_activity") {
    const activity = String(claimDoc.activityType || "Activity").trim();
    const media = claimDoc.mediaLink ? `\n${claimDoc.mediaLink}` : "";
    return {
      content: appendMinorEventPublicPing(
        `${getDailyActivityEmoji(activity)} **${activity} of The Day**\n\n` +
        `${claimDoc.activityPrompt || activity}${media}\n` +
        `*Share your responses in ${MINOR_EVENT_CONFIG.RESPONSE_CHANNEL_URL}!*`,
      ),
      components: [buildCommunityFeedbackSourceRow("minor", claimDoc.claimId)],
      allowedMentions: { roles: publicPingRoleIds },
    };
  }

  const linkLine = claimDoc.joinLink ? `🔗 **${claimDoc.joinLink}**` : "🔗 **Link will be shared by the host.**";
  const codeLine = claimDoc.lobbyCode ? `\n**Code:** ${claimDoc.lobbyCode}` : "";
  return {
    content: appendMinorEventPublicPing(
      `🎮 **GAMENIGHT**\n\n` +
      `Hello, everyone! I've decided to host an exciting game night! The game we will be playing is **${claimDoc.gameName || "a game"}**! This is a great opportunity to meet new people and create new connections! Our team is excited to see the talent and competitiveness brought out in you. We are thrilled to see you there and good luck participants!\n\n` +
      `${linkLine}${codeLine}`,
    ),
    components: [buildCommunityFeedbackSourceRow("minor", claimDoc.claimId)],
    allowedMentions: { roles: publicPingRoleIds },
  };
}

async function refreshMinorEventPlanMessage(planDoc) {
  if (!planDoc?.planningThreadId) return false;
  const thread = await client.channels.fetch(planDoc.planningThreadId).catch(() => null);
  if (!thread?.isThread?.()) return false;
  if (thread.archived) await thread.setArchived(false).catch(() => {});
  const claims = await MinorEventClaim.find({ planId: planDoc.planId, status: { $ne: "cancelled" } }).sort({ scheduledAt: 1 }).lean();
  let message = null;
  if (planDoc.planningMessageId) {
    message = await thread.messages.fetch(planDoc.planningMessageId).catch(() => null);
  }
  if (!message && typeof thread.fetchStarterMessage === "function") {
    message = await thread.fetchStarterMessage().catch(() => null);
  }
  if (!message) return false;
  if (!planDoc.planningMessageId || planDoc.planningMessageId !== message.id) {
    await MinorEventPlan.updateOne({ planId: planDoc.planId }, { $set: { planningMessageId: message.id, updatedAt: new Date() } }).catch(() => {});
  }
  await message.edit({
    embeds: [buildMinorEventPlanEmbed(planDoc, claims)],
    components: buildMinorEventPlanRows(planDoc, claims),
    allowedMentions: { parse: [] },
  }).catch(() => {});
  return true;
}

function buildMinorEventPlanEmbed(planDoc, claims = []) {
  const kindLabel = minorEventKindLabel(planDoc.kind);
  const embed = new EmbedBuilder()
    .setColor(planDoc.kind === "daily_activity" ? 0xffc766 : 0x7f8cff)
    .setTitle(`${kindLabel} Calendar`)
    .setDescription(
      `Weekly planning post for **${planDoc.weekLabel}**.\n` +
      "Claim a slot below. Posted daily activities and gamenights count toward weekly Human Resources Points.",
    )
    .setFooter({ text: planDoc.status === "archived" ? "This weekly planning post is closed." : "Unclaimed slots remain open to the Public Relations Department and Public Relations Aspirants." })
    .setTimestamp(planDoc.updatedAt || new Date());

  if (planDoc.kind === "daily_activity") {
    const byDay = new Map(claims.map(claim => [claim.dayKey, claim]));
    const lines = getMinorEventWeekDatesFromKey(planDoc.weekKey).map(dayKey => {
      const claim = byDay.get(dayKey);
      if (!claim) return `**${getMinorEventDayLabel(dayKey)}** - Open`;
      const status = claim.status === "posted" ? "Posted" : "Claimed";
      return `**${getMinorEventDayLabel(dayKey)}** - ${status} by <@${claim.claimedByDiscordId}> - ${claim.activityType || "Activity"}`;
    });
    embed.addFields({ name: "Daily Activity Slots", value: lines.join("\n").slice(0, 1024), inline: false });
  } else {
    const lines = claims
      .sort((a, b) => new Date(a.scheduledAt) - new Date(b.scheduledAt))
      .map(claim => {
        const status = claim.status === "posted" ? "Posted" : "Scheduled";
        return `**${formatDiscordTimestamp(claim.scheduledAt, "f")}** - ${status} by <@${claim.claimedByDiscordId}> - ${claim.gameName || "Gamenight"}`;
      });
    embed.addFields({
      name: "Gamenight Slots",
      value: lines.length ? lines.join("\n").slice(0, 1024) : "No gamenights have been claimed yet. Multiple gamenights may happen in one day as long as they are at least 1 hour apart.",
      inline: false,
    });
  }
  return embed;
}

function buildMinorEventPlanRows(planDoc, claims = []) {
  if (planDoc.status === "archived") return [];
  if (planDoc.kind === "gamenight") {
    return [
      new ActionRowBuilder().addComponents(
        new ButtonBuilder()
          .setCustomId(`minor_game_${planDoc.planId}`)
          .setLabel("Claim Gamenight")
          .setStyle(ButtonStyle.Primary),
        new ButtonBuilder()
          .setCustomId(`minor_refresh_${planDoc.planId}`)
          .setLabel("Refresh")
          .setStyle(ButtonStyle.Secondary),
      ),
    ];
  }

  const claimedDays = new Set(claims.filter(claim => claim.status !== "cancelled").map(claim => claim.dayKey));
  const buttons = getMinorEventWeekDatesFromKey(planDoc.weekKey).map(dayKey =>
    new ButtonBuilder()
      .setCustomId(`minor_daily_${planDoc.planId}_${dayKey}`)
      .setLabel(getMinorEventDayLabel(dayKey).replace(/^(\w{3})\w*/, "$1"))
      .setStyle(claimedDays.has(dayKey) ? ButtonStyle.Secondary : ButtonStyle.Primary)
      .setDisabled(claimedDays.has(dayKey)),
  );
  const rows = [];
  for (let i = 0; i < buttons.length; i += 5) {
    rows.push(new ActionRowBuilder().addComponents(...buttons.slice(i, i + 5)));
  }
  rows.push(new ActionRowBuilder().addComponents(
    new ButtonBuilder()
      .setCustomId(`minor_refresh_${planDoc.planId}`)
      .setLabel("Refresh")
      .setStyle(ButtonStyle.Secondary),
  ));
  return rows;
}

async function ensureMinorEventPlanningPingMessage(planDoc, thread) {
  if (!planDoc || !thread?.isThread?.()) return null;
  const roleIds = getMinorEventPlanningPingRoleIds();
  if (!roleIds.length) return null;
  const starter = typeof thread.fetchStarterMessage === "function"
    ? await thread.fetchStarterMessage().catch(() => null)
    : null;
  if (!starter) return null;

  const hasPlanningMentions = roleIds.every(roleId => starter.content?.includes(`<@&${roleId}>`));
  if (!hasPlanningMentions) {
    await starter.edit({
      content: buildMinorEventPlanningPingContent(planDoc.kind),
      allowedMentions: { roles: roleIds },
    }).catch(() => {});
  }
  if (!planDoc.planningMessageId || planDoc.planningMessageId !== starter.id) {
    planDoc.planningMessageId = starter.id;
    planDoc.updatedAt = new Date();
    await planDoc.save().catch(() => {});
  }
  return starter;
}

async function archiveOldMinorEventPlans(guild, kind, activeWeekKey) {
  const oldPlans = await MinorEventPlan.find({ kind, status: "active", weekKey: { $ne: activeWeekKey } }).limit(10);
  for (const planDoc of oldPlans) {
    const thread = planDoc.planningThreadId
      ? await guild.channels.fetch(planDoc.planningThreadId).catch(() => null)
      : null;
    if (thread?.isThread?.()) {
      if (thread.archived) await thread.setArchived(false).catch(() => {});
      await thread.send({
        embeds: [
          new EmbedBuilder()
            .setColor(0x95a5a6)
            .setTitle("Weekly Planning Post Closed")
            .setDescription("This planning week is over. A new weekly planning post has been opened by Sweetsiez Assistant.")
            .setTimestamp(),
        ],
        allowedMentions: { parse: [] },
      }).catch(() => {});
      if (typeof thread.setPinned === "function") await thread.setPinned(false, "Weekly minor event plan closed").catch(() => {});
      await thread.setLocked(true, "Weekly minor event plan closed").catch(() => {});
      await thread.setArchived(true, "Weekly minor event plan closed").catch(() => {});
    }
    planDoc.status = "archived";
    planDoc.archivedAt = new Date();
    planDoc.updatedAt = new Date();
    await planDoc.save().catch(() => {});
  }
}

async function ensureMinorEventWeeklyPlan(guild, kind, actor = null) {
  const normalizedKind = normalizeMinorEventKind(kind);
  if (!normalizedKind) throw new Error("Invalid minor event plan type.");
  const weekInfo = getMinorEventWeekInfo(new Date(), "current");
  let existing = await MinorEventPlan.findOne({ kind: normalizedKind, weekKey: weekInfo.weekKey });
  if (existing?.planningThreadId) {
    const existingThread = await guild.channels.fetch(existing.planningThreadId).catch(() => null);
    if (existingThread?.isThread?.()) {
      await ensureMinorEventPlanningPingMessage(existing, existingThread);
      return { plan: existing, created: false };
    }
    existing.planningThreadId = null;
    existing.planningMessageId = null;
    existing.updatedAt = new Date();
    await existing.save().catch(() => {});
  }

  await archiveOldMinorEventPlans(guild, normalizedKind, weekInfo.weekKey);
  const forum = await fetchForumChannel(guild, MINOR_EVENT_CONFIG.EVENT_PLANNING_FORUM_ID);
  if (!forum) throw new Error("I could not reach the event planning forum.");

  existing = existing || new MinorEventPlan({
    planId: createOperationalId("MEPLAN"),
    kind: normalizedKind,
    weekKey: weekInfo.weekKey,
    weekLabel: weekInfo.weekLabel,
    weekStart: weekInfo.start,
    weekEnd: weekInfo.end,
    createdByDiscordId: actor?.id || null,
    createdByTag: actor?.tag || "Sweetsiez Assistant",
  });

  const tag = findForumTag(forum, minorEventKindLabel(normalizedKind)) || findForumTag(forum, "Event");
  const planningPingRoleIds = getMinorEventPlanningPingRoleIds();
  const thread = await forum.threads.create({
    name: `${minorEventKindLabel(normalizedKind)} | ${formatMinorEventShortDate(weekInfo.weekDates[0])}-${formatMinorEventShortDate(weekInfo.weekDates[6])}`.slice(0, 100),
    appliedTags: tag ? [tag.id] : [],
    message: {
      content: buildMinorEventPlanningPingContent(normalizedKind),
      embeds: [buildMinorEventPlanEmbed(existing, [])],
      components: buildMinorEventPlanRows(existing, []),
      allowedMentions: { roles: planningPingRoleIds },
    },
    reason: `Weekly ${minorEventKindLabel(normalizedKind)} planning post`,
  });
  if (typeof thread.setPinned === "function") await thread.setPinned(true, "Current weekly Human Resources planning post").catch(() => {});
  const starter = typeof thread.fetchStarterMessage === "function" ? await thread.fetchStarterMessage().catch(() => null) : null;
  existing.planningThreadId = thread.id;
  existing.planningMessageId = starter?.id || null;
  existing.status = "active";
  existing.updatedAt = new Date();
  await existing.save();
  await refreshMinorEventPlanMessage(existing);
  return { plan: existing, created: true };
}

