async function postMinorEventClaim(guild, claimDoc, actor = null) {
  if (!claimDoc || claimDoc.status !== "claimed") return null;
  const publicChannel = await fetchTextChannel(guild, MINOR_EVENT_CONFIG.PUBLIC_EVENTS_CHANNEL_ID);
  if (!publicChannel) throw new Error("I could not reach the public events channel.");
  const publicPayload = buildMinorEventPublicContent(claimDoc);
  const message = await publicChannel.send(publicPayload);
  claimDoc.status = "posted";
  claimDoc.publicChannelId = publicChannel.id;
  claimDoc.publicMessageId = message.id;
  claimDoc.postedAt = new Date();
  claimDoc.updatedAt = new Date();
  await claimDoc.save();

  await logBoardContribution({
    board: "operations",
    activityType: claimDoc.kind === "daily_activity" ? "minor_daily_activity_hosted" : "minor_gamenight_hosted",
    discordId: claimDoc.claimedByDiscordId,
    sourceType: "minor_event",
    sourceId: claimDoc.claimId,
    summary: `${claimDoc.kind === "daily_activity" ? "Hosted daily activity" : "Hosted gamenight"} for ${claimDoc.dayLabel}.`,
    loggedBy: actor || { id: claimDoc.claimedByDiscordId, tag: claimDoc.claimedByTag },
  }).catch(() => {});

  const planDoc = await MinorEventPlan.findOne({ planId: claimDoc.planId });
  if (planDoc) await refreshMinorEventPlanMessage(planDoc);
  return message;
}

async function handleMinorEventButton(interaction) {
  const parts = interaction.customId.split("_");
  const action = parts[1];
  const planId = parts[2];
  const planDoc = await MinorEventPlan.findOne({ planId });
  if (!planDoc) return interaction.reply({ content: "That weekly planning post could not be found.", flags: MessageFlags.Ephemeral });

  if (action === "refresh") {
    if (!interaction.deferred && !interaction.replied) {
      await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
    }
    await refreshMinorEventPlanMessage(planDoc);
    return interaction.editReply("Weekly planning post refreshed.");
  }

  const context = await getBoardSystemContext(interaction);
  if (!hasMinorEventClaimAccess(context)) {
    return interaction.reply({ content: MINOR_EVENT_CLAIM_DENIED_MESSAGE, flags: MessageFlags.Ephemeral });
  }

  if (planDoc.status !== "active") {
    return interaction.reply({ content: "That weekly planning post is closed.", flags: MessageFlags.Ephemeral });
  }

  if (action === "daily") {
    const dayKey = parts.slice(3).join("_");
    const existing = await MinorEventClaim.findOne({ planId, kind: "daily_activity", dayKey, status: { $ne: "cancelled" } }).lean();
    if (existing) return interaction.reply({ content: "That daily activity slot is already claimed.", flags: MessageFlags.Ephemeral });
    return showMinorEventDailyModal(interaction, planDoc, dayKey);
  }

  if (action === "game") {
    return showMinorEventGamenightModal(interaction, planDoc);
  }

  return interaction.reply({ content: "Unknown minor event action.", flags: MessageFlags.Ephemeral });
}

async function handleMinorEventModal(interaction) {
  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }
  const parts = interaction.customId.split("_");
  const mode = parts[2];
  const planId = parts[3];
  const planDoc = await MinorEventPlan.findOne({ planId });
  if (!planDoc || planDoc.status !== "active") return interaction.editReply("That weekly planning post is no longer active.");

  const context = await getBoardSystemContext(interaction);
  if (!hasMinorEventClaimAccess(context)) {
    return interaction.editReply(MINOR_EVENT_CLAIM_DENIED_MESSAGE);
  }

  if (mode === "daily") {
    const dayKey = parts.slice(4).join("_");
    const existing = await MinorEventClaim.findOne({ planId, kind: "daily_activity", dayKey, status: { $ne: "cancelled" } }).lean();
    if (existing) return interaction.editReply("That daily activity slot is already claimed.");
    const scheduledAt = getMinorEventDailyScheduledAt(dayKey);
    if (!scheduledAt) return interaction.editReply("That daily activity date could not be read.");
    const claimDoc = await MinorEventClaim.create({
      claimId: createOperationalId("MECLAIM"),
      planId,
      kind: "daily_activity",
      weekKey: planDoc.weekKey,
      dayKey,
      dayLabel: getMinorEventDayLabel(dayKey),
      scheduledAt,
      claimedByDiscordId: interaction.user.id,
      claimedByTag: interaction.user.tag,
      activityType: interaction.fields.getTextInputValue("activity_type").trim(),
      activityPrompt: interaction.fields.getTextInputValue("activity_prompt").trim(),
      mediaLink: interaction.fields.getTextInputValue("media_link")?.trim() || null,
    });
    await refreshMinorEventPlanMessage(planDoc);
    if (claimDoc.scheduledAt.getTime() <= Date.now() + 30_000) {
      await postMinorEventClaim(interaction.guild, claimDoc, interaction.user).catch(error => {
        console.error("[MinorEvents] Immediate daily post failed:", error.message);
      });
    }
    return interaction.editReply(`Daily activity claimed for **${claimDoc.dayLabel}**.`);
  }

  if (mode === "game") {
    const dayKey = resolveMinorEventDayKey(planDoc, interaction.fields.getTextInputValue("day"));
    if (!dayKey) return interaction.editReply("That day is not part of this planning week. Use a weekday name or date from the weekly post.");
    const scheduledAt = parseMinorEventTimeOnDay(dayKey, interaction.fields.getTextInputValue("time"));
    if (!scheduledAt || scheduledAt.getTime() <= Date.now() + 30_000) {
      return interaction.editReply("Please use a future EST time, like `7:00 PM EST`.");
    }
    const cooldownStart = new Date(scheduledAt.getTime() - MINOR_EVENT_CONFIG.GAMENIGHT_COOLDOWN_MS);
    const cooldownEnd = new Date(scheduledAt.getTime() + MINOR_EVENT_CONFIG.GAMENIGHT_COOLDOWN_MS);
    const conflicting = await MinorEventClaim.findOne({
      kind: "gamenight",
      status: { $ne: "cancelled" },
      scheduledAt: { $gt: cooldownStart, $lt: cooldownEnd },
    }).lean();
    if (conflicting) {
      return interaction.editReply(
        `That is too close to another gamenight scheduled for ${formatDiscordTimestamp(conflicting.scheduledAt, "f")}. Please leave at least 1 hour between gamenights.`,
      );
    }
    const claimDoc = await MinorEventClaim.create({
      claimId: createOperationalId("MECLAIM"),
      planId,
      kind: "gamenight",
      weekKey: planDoc.weekKey,
      dayKey,
      dayLabel: getMinorEventDayLabel(dayKey),
      scheduledAt,
      claimedByDiscordId: interaction.user.id,
      claimedByTag: interaction.user.tag,
      gameName: interaction.fields.getTextInputValue("game_name").trim(),
      joinLink: interaction.fields.getTextInputValue("join_link").trim(),
      lobbyCode: interaction.fields.getTextInputValue("lobby_code")?.trim() || null,
    });
    await refreshMinorEventPlanMessage(planDoc);
    return interaction.editReply(`Gamenight claimed for ${formatDiscordTimestamp(claimDoc.scheduledAt, "f")}.`);
  }

  return interaction.editReply("Unknown minor event claim.");
}

async function getMinorEventCreditsForDiscord(discordId, start, end) {
  if (!discordId || !start || !end) return 0;
  return MinorEventClaim.countDocuments({
    claimedByDiscordId: String(discordId),
    status: "posted",
    postedAt: { $gte: start, $lt: end },
  }).catch(() => 0);
}

async function getMinorEventRequirementForDiscord(guild, discordId) {
  const member = await guild?.members.fetch(discordId).catch(() => null);
  if (!member) return 0;
  const roles = member.roles?.cache;
  const hasMinorEventRole =
    roles?.has(SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Growth Team"]) ||
    roles?.has(SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Operations Board"]) ||
    roles?.has(SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Head of Operations"]);
  return hasMinorEventRole ? MINOR_EVENT_CONFIG.WEEKLY_REQUIRED_CREDITS : 0;
}

let minorEventSchedulerStarted = false;

function startMinorEventScheduler(clientRef) {
  if (minorEventSchedulerStarted) return;
  minorEventSchedulerStarted = true;

  const runMinorEventAutomation = async () => {
    if (mongoose.connection.readyState !== 1) return;
    const guild = clientRef.guilds.cache.get(SWEETSIEZ_STRUCTURE_CONFIG.GUILD_ID) || clientRef.guilds.cache.first();
    if (!guild) return;

    await ensureMinorEventWeeklyPlan(guild, "daily_activity").catch(error =>
      console.error("[MinorEvents] Daily activity weekly plan failed:", error.message),
    );
    await ensureMinorEventWeeklyPlan(guild, "gamenight").catch(error =>
      console.error("[MinorEvents] Gamenight weekly plan failed:", error.message),
    );

    const dueClaims = await MinorEventClaim.find({
      status: "claimed",
      scheduledAt: { $lte: new Date() },
    }).sort({ scheduledAt: 1 }).limit(10);
    for (const claimDoc of dueClaims) {
      await postMinorEventClaim(guild, claimDoc).catch(error =>
        console.error(`[MinorEvents] Failed to post ${claimDoc.claimId}:`, error.message),
      );
    }
  };

  setInterval(() => {
    runMinorEventAutomation().catch(error => console.error("[MinorEvents] Scheduler error:", error.message));
  }, 60 * 1000);

  setTimeout(() => {
    runMinorEventAutomation().catch(error => console.error("[MinorEvents] Startup scheduler error:", error.message));
  }, 75 * 1000);

  console.log("Minor event scheduler started.");
}

