function buildAnnouncementRequestEmbed(requestDoc) {
  const fields = [
    { name: "Request ID", value: requestDoc.requestId, inline: true },
    { name: "Status", value: ANNOUNCEMENT_STATUS_LABELS[requestDoc.status] || requestDoc.status, inline: true },
    { name: "Type", value: ANNOUNCEMENT_TYPE_LABELS[requestDoc.type] || requestDoc.type || "General", inline: true },
    { name: "Target", value: formatAnnouncementTarget(requestDoc), inline: true },
    { name: "Ping", value: formatAnnouncementPing(requestDoc), inline: true },
    { name: "Requested Post Time", value: requestDoc.requestedPostAtText || "No preference", inline: true },
    { name: "Requested By", value: `${requestDoc.requestedByTag} (<@${requestDoc.requestedByDiscordId}>)`, inline: false },
  ];

  if (requestDoc.reason) {
    fields.push({ name: "Reason", value: truncateForDiscord(requestDoc.reason, 1024), inline: false });
  }
  if (requestDoc.target === "promotions" && requestDoc.promotionRank) {
    fields.push({ name: "Promoted Rank", value: String(requestDoc.promotionRank), inline: true });
  }
  if (requestDoc.claimedByDiscordId) {
    fields.push({ name: "Claimed By", value: `${requestDoc.claimedByTag || "Unknown"} (<@${requestDoc.claimedByDiscordId}>)`, inline: true });
  }
  if (requestDoc.approvedByDiscordId) {
    fields.push({ name: "Approved By", value: `${requestDoc.approvedByTag || "Unknown"} (<@${requestDoc.approvedByDiscordId}>)`, inline: true });
  }
  if (requestDoc.scheduledAt) {
    fields.push({ name: "Scheduled For", value: `<t:${Math.floor(new Date(requestDoc.scheduledAt).getTime() / 1000)}:F>`, inline: true });
  }
  if (requestDoc.editNote) {
    fields.push({ name: "Requested Edits", value: truncateForDiscord(requestDoc.editNote, 1024), inline: false });
  }
  if (requestDoc.deniedReason) {
    fields.push({ name: "Deny Reason", value: truncateForDiscord(requestDoc.deniedReason, 1024), inline: false });
  }
  if (requestDoc.publicChannelId && requestDoc.publicMessageId) {
    fields.push({
      name: "Public Post",
      value: `https://discord.com/channels/${SWEETSIEZ_STRUCTURE_CONFIG.GUILD_ID}/${requestDoc.publicChannelId}/${requestDoc.publicMessageId}`,
      inline: false,
    });
  }
  if (announcementRequiresOfficerApproval(requestDoc)) {
    fields.push({ name: "Approval Note", value: "This request includes a ping and requires Public Relations Lead or Leadership approval before posting.", inline: false });
  }

  return new EmbedBuilder()
    .setColor(announcementStatusColor(requestDoc.status))
    .setTitle(`Announcement Request: ${requestDoc.title}`)
    .addFields(fields)
    .setTimestamp(requestDoc.updatedAt || new Date());
}

