function getCommunityFeedbackSourceLabel(sourceType) {
  if (sourceType === "announcement") return "Announcement";
  if (sourceType === "event") return "Event";
  if (sourceType === "minor") return "Community Activity";
  return "Public Post";
}

function getCommunityFeedbackSourceUrl(feedbackDoc) {
  if (!feedbackDoc?.sourceChannelId || !feedbackDoc?.sourceMessageId) return null;
  return `https://discord.com/channels/${SWEETSIEZ_STRUCTURE_CONFIG.GUILD_ID}/${feedbackDoc.sourceChannelId}/${feedbackDoc.sourceMessageId}`;
}

async function resolveCommunityFeedbackSource(sourceType, sourceId) {
  const fallback = {
    sourceType,
    sourceId,
    sourceTitle: "Public Post",
    sourceChannelId: null,
    sourceMessageId: null,
  };

  if (sourceType === "announcement") {
    const requestDoc = await AnnouncementRequest.findOne({ requestId: sourceId }).lean();
    if (!requestDoc) return fallback;
    return {
      sourceType,
      sourceId,
      sourceTitle: requestDoc.title || "Announcement",
      sourceChannelId: requestDoc.publicChannelId || null,
      sourceMessageId: requestDoc.publicMessageId || null,
    };
  }

  if (sourceType === "event") {
    const eventDoc = await BoardEvent.findOne({ eventId: sourceId }).lean();
    if (!eventDoc) return fallback;
    return {
      sourceType,
      sourceId,
      sourceTitle: eventDoc.name || "Event",
      sourceChannelId: eventDoc.publicChannelId || null,
      sourceMessageId: eventDoc.publicMessageId || null,
    };
  }

  if (sourceType === "minor") {
    const claimDoc = await MinorEventClaim.findOne({ claimId: sourceId }).lean();
    if (!claimDoc) return fallback;
    const title = claimDoc.kind === "gamenight"
      ? `Gamenight: ${claimDoc.gameName || claimDoc.dayLabel || "Community Event"}`
      : `Daily Activity: ${claimDoc.activityType || claimDoc.dayLabel || "Community Activity"}`;
    return {
      sourceType,
      sourceId,
      sourceTitle: title,
      sourceChannelId: claimDoc.publicChannelId || null,
      sourceMessageId: claimDoc.publicMessageId || null,
    };
  }

  return fallback;
}

function buildCommunityFeedbackSubmissionEmbed(feedbackDoc) {
  const sourceUrl = getCommunityFeedbackSourceUrl(feedbackDoc);
  const sourceLabel = getCommunityFeedbackSourceLabel(feedbackDoc.sourceType);
  const forwardedTargets = (feedbackDoc.forwardedTo || [])
    .map(entry => `${COMMUNITY_FEEDBACK_FORWARD_TARGETS[entry.board]?.label || entry.board} by ${entry.byTag || "Unknown"}`)
    .join("\n");
  const responseLines = (feedbackDoc.responses || [])
    .slice(-3)
    .map(entry => `${entry.byTag || "Public Relations"}: ${truncateForDiscord(entry.text, 160)}`)
    .join("\n");

  const embed = new EmbedBuilder()
    .setColor(feedbackDoc.status === "reviewed" ? 0x95a5a6 : feedbackDoc.status === "responded" ? 0x57f287 : 0x5bc0de)
    .setTitle("Community Feedback")
    .setDescription(truncateForDiscord(feedbackDoc.feedbackText, 3500))
    .addFields(
      { name: "Feedback ID", value: feedbackDoc.feedbackId, inline: true },
      { name: "Status", value: COMMUNITY_FEEDBACK_STATUS_LABELS[feedbackDoc.status] || feedbackDoc.status, inline: true },
      { name: "Source", value: sourceUrl ? `[${sourceLabel}: ${truncateForDiscord(feedbackDoc.sourceTitle, 80)}](${sourceUrl})` : `${sourceLabel}: ${truncateForDiscord(feedbackDoc.sourceTitle, 120)}`, inline: false },
      { name: "Submitted By", value: `${feedbackDoc.submittedByTag} (<@${feedbackDoc.submittedByDiscordId}>)`, inline: false },
    )
    .setTimestamp(feedbackDoc.updatedAt || feedbackDoc.createdAt || new Date());

  if (forwardedTargets) {
    embed.addFields({ name: "Forwarded To", value: truncateForDiscord(forwardedTargets, 1024), inline: false });
  }
  if (responseLines) {
    embed.addFields({ name: "Recent Responses", value: truncateForDiscord(responseLines, 1024), inline: false });
  }
  return embed;
}

