async function refreshCommunityFeedbackReviewMessage(feedbackDoc) {
  if (!feedbackDoc?.reviewChannelId || !feedbackDoc?.reviewMessageId) return false;
  const channel = await client.channels.fetch(feedbackDoc.reviewChannelId).catch(() => null);
  if (!channel?.isTextBased?.()) return false;
  const message = await channel.messages.fetch(feedbackDoc.reviewMessageId).catch(() => null);
  if (!message) return false;
  await message.edit({
    embeds: [buildCommunityFeedbackSubmissionEmbed(feedbackDoc)],
    components: buildCommunityFeedbackManagementRows(feedbackDoc),
  }).catch(() => {});
  return true;
}

