async function submitCommunityFeedback(interaction, sourceType, sourceId) {
  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }
  const feedbackText = interaction.fields.getTextInputValue("feedback_text").trim();
  if (feedbackText.length < 5) return interaction.editReply("Please add a little more detail before submitting feedback.");

  const source = await resolveCommunityFeedbackSource(sourceType, sourceId);
  const feedbackDoc = await CommunityFeedbackSubmission.create({
    feedbackId: createOperationalId("CFB"),
    ...source,
    submittedByDiscordId: interaction.user.id,
    submittedByTag: interaction.user.tag,
    feedbackText,
  });

  const channel = await fetchTextChannel(interaction.guild, SWEETSIEZ_STRUCTURE_CONFIG.CHANNELS.COMMUNITY_FEEDBACK);
  if (!channel) {
    return interaction.editReply("Your feedback was saved, but I could not reach the community feedback channel.");
  }

  const pingRoleId = SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Marketing Board"];
  const reviewMessage = await channel.send({
    content: `<@&${pingRoleId}> new community feedback`,
    embeds: [buildCommunityFeedbackSubmissionEmbed(feedbackDoc)],
    components: buildCommunityFeedbackManagementRows(feedbackDoc),
    allowedMentions: { roles: [pingRoleId] },
  });

  feedbackDoc.reviewChannelId = channel.id;
  feedbackDoc.reviewMessageId = reviewMessage.id;
  feedbackDoc.updatedAt = new Date();
  await feedbackDoc.save();

  return interaction.editReply("Thanks, your feedback was sent to the Public Relations Department.");
}

async function forwardCommunityFeedback(interaction, feedbackDoc, targetKey) {
  const target = COMMUNITY_FEEDBACK_FORWARD_TARGETS[targetKey];
  if (!target) return interaction.editReply("That forwarding target is not configured.");
  if ((feedbackDoc.forwardedTo || []).some(entry => entry.board === targetKey)) {
    return interaction.editReply(`This feedback has already been forwarded to ${target.label}.`);
  }

  const channel = await fetchTextChannel(interaction.guild, target.channelId);
  if (!channel) return interaction.editReply(`I could not reach the ${target.label} channel.`);

  const message = await channel.send({
    content: target.roleId ? `<@&${target.roleId}>` : undefined,
    embeds: [buildCommunityFeedbackForwardEmbed(feedbackDoc, targetKey, interaction.user)],
    allowedMentions: target.roleId ? { roles: [target.roleId] } : { parse: [] },
  });

  const forwardedEntry = {
    board: targetKey,
    channelId: channel.id,
    messageId: message.id,
    by: interaction.user.id,
    byTag: interaction.user.tag,
    at: new Date(),
  };
  const updated = await CommunityFeedbackSubmission.findOneAndUpdate(
    { feedbackId: feedbackDoc.feedbackId },
    {
      $set: { status: "forwarded", updatedAt: new Date() },
      $push: { forwardedTo: forwardedEntry },
    },
    { new: true },
  );
  await logBoardContribution({
    board: "marketing",
    activityType: "feedback_forwarded",
    discordId: interaction.user.id,
    sourceType: "community_feedback",
    sourceId: feedbackDoc.feedbackId,
    summary: `Forwarded community feedback to ${target.label}.`,
    loggedBy: interaction.user,
  }).catch(() => {});
  await refreshCommunityFeedbackReviewMessage(updated);
  return interaction.editReply(`Forwarded to ${target.label}.`);
}

async function postCommunityFeedbackResponse(feedbackDoc, responseText, actor) {
  if (!feedbackDoc.sourceChannelId) return null;
  const channel = await client.channels.fetch(feedbackDoc.sourceChannelId).catch(() => null);
  if (!channel?.isTextBased?.()) return null;

  const payload = {
    embeds: [buildCommunityFeedbackResponseEmbed(feedbackDoc, responseText, actor)],
    allowedMentions: { parse: [] },
  };
  if (feedbackDoc.sourceMessageId) {
    const sourceMessage = await channel.messages.fetch(feedbackDoc.sourceMessageId).catch(() => null);
    if (sourceMessage) {
      const reply = await sourceMessage.reply(payload).catch(() => null);
      if (reply) return reply;
    }
  }
  return channel.send(payload).catch(() => null);
}

function formatMarketingStatus(status) {
  return String(status || "unknown").replaceAll("_", " ");
}

function marketingStatusColor(status) {
  if (status === "posted" || status === "completed") return 0x57f287;
  if (status === "approved" || status === "scheduled" || status === "active") return 0x5bc0de;
  if (status === "archived" || status === "cancelled") return 0x95a5a6;
  if (status === "needs_review" || status === "in_progress") return 0xf1c40f;
  return 0xeb5757;
}

function formatDiscordTimestamp(date, style = "F") {
  if (!date) return "Not scheduled";
  const parsed = new Date(date);
  if (Number.isNaN(parsed.getTime())) return "Not scheduled";
  return `<t:${Math.floor(parsed.getTime() / 1000)}:${style}>`;
}

function buildMarketingContentEmbed(contentDoc) {
  const embed = new EmbedBuilder()
    .setColor(marketingStatusColor(contentDoc.status))
    .setTitle(`Marketing Content: ${contentDoc.title}`)
    .setDescription(truncateForDiscord(contentDoc.description, 2500))
    .addFields(
      { name: "Content ID", value: contentDoc.contentId, inline: true },
      { name: "Platform", value: contentDoc.platform, inline: true },
      { name: "Status", value: formatMarketingStatus(contentDoc.status), inline: true },
      { name: "Submitted By", value: `${contentDoc.submittedByTag} (${contentDoc.submittedByDiscordId})`, inline: false },
    )
    .setTimestamp(contentDoc.updatedAt || new Date());
  if (contentDoc.scheduledAt) embed.addFields({ name: "Scheduled For", value: formatDiscordTimestamp(contentDoc.scheduledAt), inline: true });
  if (contentDoc.campaignId) embed.addFields({ name: "Campaign", value: contentDoc.campaignId, inline: true });
  if (contentDoc.contributors?.length) embed.addFields({ name: "Contributors", value: contentDoc.contributors.map(id => `<@${id}>`).join(", "), inline: false });
  if (contentDoc.caption) embed.addFields({ name: "Caption", value: truncateForDiscord(contentDoc.caption, 1024), inline: false });
  if (contentDoc.assetLink) embed.addFields({ name: "Asset Link", value: truncateForDiscord(contentDoc.assetLink, 1024), inline: false });
  if (contentDoc.publicLink) embed.addFields({ name: "Public Link", value: truncateForDiscord(contentDoc.publicLink, 1024), inline: false });
  if (contentDoc.performance) {
    embed.addFields({
      name: "Performance",
      value: [
        `Views: ${contentDoc.performance.views ?? 0}`,
        `Likes: ${contentDoc.performance.likes ?? 0}`,
        `Comments: ${contentDoc.performance.comments ?? 0}`,
        `Shares: ${contentDoc.performance.shares ?? 0}`,
        `Saves: ${contentDoc.performance.saves ?? 0}`,
        `Clicks: ${contentDoc.performance.clicks ?? 0}`,
        contentDoc.performance.benchmark ? `Benchmark: ${contentDoc.performance.benchmark.label} (score ${contentDoc.performance.benchmark.score}, avg ${contentDoc.performance.benchmark.average})` : null,
      ].filter(Boolean).join(" | "),
      inline: false,
    });
  }
  return embed;
}

