function buildGraphicsRequestEmbed(requestDoc) {
  // Calculate deadline urgency
  let urgencyStatus = "📋 On Schedule";
  let urgencyColor = 0xbb6bd9;
  if (requestDoc.deadline) {
    const deadline = new Date(requestDoc.deadline);
    const now = new Date();
    const daysUntil = Math.ceil((deadline - now) / (1000 * 60 * 60 * 24));
    
    if (daysUntil < 0) {
      urgencyStatus = `🔴 OVERDUE (${Math.abs(daysUntil)} days)`;
      urgencyColor = 0xff0000;
    } else if (daysUntil <= 1) {
      urgencyStatus = `🟡 URGENT (due today)`;
      urgencyColor = 0xff7f00;
    } else if (daysUntil <= 3) {
      urgencyStatus = `🟠 High Priority (${daysUntil} days)`;
      urgencyColor = 0xf1c40f;
    }
  }

  return new EmbedBuilder()
    .setColor(requestDoc.status === "completed" ? 0x57f287 : requestDoc.status === "in_progress" ? urgencyColor : 0xbb6bd9)
    .setTitle(`Graphics Request: ${requestDoc.purpose}`)
    .addFields(
      { name: "Request ID", value: requestDoc.requestId, inline: true },
      { name: "Status", value: requestDoc.status.replaceAll("_", " "), inline: true },
      { name: "Urgency", value: urgencyStatus, inline: true },
      { name: "Deadline", value: requestDoc.deadline, inline: true },
      { name: "Text Needed", value: truncateForDiscord(requestDoc.textNeeded, 1024), inline: false },
      { name: "Size / Platform", value: truncateForDiscord(requestDoc.sizePlatform, 1024), inline: false },
      { name: "Requested By", value: `${requestDoc.requestedByTag} (${requestDoc.requestedByDiscordId})`, inline: false },
      { name: "Assigned To", value: requestDoc.assignedToDiscordId ? `<@${requestDoc.assignedToDiscordId}>` : "Unassigned", inline: true },
    )
    .setTimestamp(requestDoc.updatedAt || new Date());
}

