function summarizeMarketingContentItem(item) {
  const scheduled = item.scheduledAt ? ` - ${formatDiscordTimestamp(item.scheduledAt, "f")}` : "";
  const campaign = item.campaignId ? ` - ${item.campaignId}` : "";
  return `**${item.title}** (${item.contentId}) - ${formatMarketingStatus(item.status)}${scheduled}${campaign}`;
}

