function marketingPerformanceScore(item) {
  const performance = item.performance || {};
  return Number(performance.views || 0)
    + Number(performance.likes || 0) * 5
    + Number(performance.comments || 0) * 8
    + Number(performance.shares || 0) * 10
    + Number(performance.saves || 0) * 8
    + Number(performance.clicks || 0) * 6;
}

async function buildMarketingDashboardEmbed(days = 30) {
  const now = new Date();
  const start = new Date(now.getTime() - Math.max(1, Number(days || 30)) * 24 * 60 * 60 * 1000);
  const content = await MarketingContent.find({
    $or: [
      { createdAt: { $gte: start, $lt: now } },
      { updatedAt: { $gte: start, $lt: now } },
      { scheduledAt: { $gte: start, $lt: now } },
    ],
  }).lean();
  const filming = await FilmingSession.find({ createdAt: { $gte: start, $lt: now } }).lean();
  const graphicsCompleted = await GraphicsRequest.countDocuments({ status: "completed", updatedAt: { $gte: start, $lt: now } });
  const campaigns = await MarketingCampaign.find({ updatedAt: { $gte: start, $lt: now } }).lean();
  const newsletters = await NewsletterDraft.find({ updatedAt: { $gte: start, $lt: now } }).lean();
  const contributions = await BoardContribution.find({ board: "marketing", createdAt: { $gte: start, $lt: now } }).lean();
  const upcoming = await MarketingContent.find({
    status: { $in: ["approved", "scheduled"] },
    scheduledAt: { $gte: now },
  }).sort({ scheduledAt: 1 }).limit(5).lean();

  const statusCounts = {};
  let views = 0;
  let engagements = 0;
  for (const item of content) {
    statusCounts[item.status] = (statusCounts[item.status] || 0) + 1;
    const perf = item.performance || {};
    views += Number(perf.views || 0);
    engagements += Number(perf.likes || 0) + Number(perf.comments || 0) + Number(perf.shares || 0) + Number(perf.saves || 0) + Number(perf.clicks || 0);
  }

  const topPost = content
    .filter(item => item.performance)
    .sort((a, b) => marketingPerformanceScore(b) - marketingPerformanceScore(a))[0];

  return new EmbedBuilder()
    .setColor(0xff7f6e)
    .setTitle("Public Relations Dashboard")
    .setDescription(`Content, graphics, filming, and campaign summary for the last **${days} day${Number(days) === 1 ? "" : "s"}**.`)
    .addFields(
      { name: "Content Pipeline", value: [
        `Tracked Content: **${content.length}**`,
        `Posts Logged: **${content.filter(item => item.status === "posted").length}**`,
        `Upcoming Scheduled: **${upcoming.length}**`,
        `Status Breakdown: ${Object.entries(statusCounts).length ? Object.entries(statusCounts).map(([status, count]) => `${formatMarketingStatus(status)} ${count}`).join(", ") : "none"}`,
      ].join("\n"), inline: false },
      { name: "Production Work", value: [
        `Filming Sessions: **${filming.length}**`,
        `Graphics Completed: **${graphicsCompleted}**`,
        `Campaigns Updated: **${campaigns.length}**`,
        `Newsletter Drafts Updated: **${newsletters.length}**`,
      ].join("\n"), inline: true },
      { name: "Performance", value: [
        `Views Logged: **${views}**`,
        `Engagements Logged: **${engagements}**`,
        `Top Post: ${topPost ? `**${topPost.title}** (${topPost.contentId})` : "No post stats yet."}`,
      ].join("\n"), inline: true },
      { name: "Top Contributors", value: formatTopContributors(contributions), inline: false },
      { name: "Upcoming Content", value: upcoming.length ? truncateForDiscord(upcoming.map(summarizeMarketingContentItem).join("\n"), 2000) : "No upcoming content scheduled.", inline: false },
    )
    .setTimestamp();
}

async function buildSocialMediaRadarEmbed(guild, days = 30) {
  const now = new Date();
  const start = new Date(now.getTime() - Math.max(1, Number(days || 30)) * 24 * 60 * 60 * 1000);
  await guild.members.fetch().catch(() => null);

  const socialMediaRoleId = SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Media Team"];
  const marketingBoardRoleId = SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Marketing Board"];
  const socialMediaMembers = guild.members.cache.filter(member =>
    member.roles.cache.has(socialMediaRoleId) && !member.roles.cache.has(marketingBoardRoleId),
  );
  const contributions = await BoardContribution.find({
    board: "marketing",
    createdAt: { $gte: start, $lt: now },
  }).lean();

  const weights = {
    content_submitted: 2,
    content_claimed: 1,
    filming_session_created: 3,
    filming_attended: 2,
    graphics_completed: 3,
    campaign_item_completed: 3,
    newsletter_drafted: 2,
  };
  const stats = new Map();
  function ensure(discordId) {
    const id = String(discordId);
    if (!stats.has(id)) stats.set(id, { score: 0, content: 0, filming: 0, graphics: 0, campaigns: 0, newsletter: 0 });
    return stats.get(id);
  }

  for (const contribution of contributions) {
    const item = ensure(contribution.discordId);
    item.score += Number(weights[contribution.activityType] || 1) * Number(contribution.amount || 1);
    if (contribution.activityType.startsWith("content_")) item.content += 1;
    if (contribution.activityType.startsWith("filming_")) item.filming += 1;
    if (contribution.activityType.startsWith("graphics_")) item.graphics += 1;
    if (contribution.activityType.startsWith("campaign_")) item.campaigns += 1;
    if (contribution.activityType.startsWith("newsletter_")) item.newsletter += 1;
  }

  const rows = [...socialMediaMembers.values()].map(member => {
    const item = stats.get(member.id) || { score: 0, content: 0, filming: 0, graphics: 0, campaigns: 0, newsletter: 0 };
    return { member, ...item };
  }).sort((a, b) => b.score - a.score || a.member.displayName.localeCompare(b.member.displayName)).slice(0, 10);

  return new EmbedBuilder()
    .setColor(0xff7f6e)
    .setTitle("Media Radar")
    .setDescription(`Public Relations Aspirant activity snapshot for the last **${days} day${Number(days) === 1 ? "" : "s"}**. This supports Public Relations Department readiness discussions; it is not an automatic promotion.`)
    .addFields({
      name: "Top Social Media Members",
      value: rows.length
        ? rows.map((row, index) =>
            `${index + 1}. ${row.member} - **${row.score} pts** ` +
            `(Content ${row.content}, Filming ${row.filming}, Graphics ${row.graphics}, Campaigns ${row.campaigns}, Newsletter ${row.newsletter})`
          ).join("\n")
        : "No Public Relations Aspirant activity found in this window.",
      inline: false,
    })
    .setTimestamp();
}

async function logBoardContribution({ board, activityType, discordId, sourceType, sourceId, summary, amount = 1, loggedBy }) {
  const robloxUsername = verifiedUsers.get(discordId) || null;
  const pointValue = getBoardContributionPointValue({ board, activityType, amount });
  const contributionDoc = await BoardContribution.create({
    contributionId: createOperationalId("CONTRIB"),
    board,
    activityType,
    discordId,
    robloxUsername,
    sourceType,
    sourceId,
    summary,
    amount,
    loggedByDiscordId: loggedBy.id,
    loggedByTag: loggedBy.tag,
  }).catch(error => console.error("Failed to save board contribution:", error.message));
  if (!contributionDoc) return null;

  if (!robloxUsername) return { contributionDoc, profileThread: null };
  const robloxUserId = await getRobloxUserId(robloxUsername).catch(() => null);
  const rankInfo = robloxUserId ? await getUserRankInGroup(robloxUserId).catch(() => null) : null;
  if (!robloxUserId || !rankInfo || !isStaffProfileRank(rankInfo.rank)) return { contributionDoc, profileThread: null };

  const profileData = await getOrCreateStaffProfileThread({
    discordId,
    robloxUsername,
    robloxUserId,
    rank: rankInfo.rank,
    rankName: rankInfo.name || `Rank ${rankInfo.rank}`,
  }).catch(() => null);
  if (!profileData?.thread) return { contributionDoc, profileThread: null };

  await profileData.thread.send({
    embeds: [
      new EmbedBuilder()
        .setColor(board === "marketing" ? 0xeb5757 : board === "operations" ? 0x27ae60 : board === "relations" ? 0xff9ac8 : board === "moderation" ? 0x4e56c9 : 0x2f80ed)
        .setTitle("Board Contribution Logged")
        .addFields(
          { name: "Board", value: board, inline: true },
          { name: "Type", value: activityType.replaceAll("_", " "), inline: true },
          { name: "Source", value: `${sourceType} ${sourceId}`, inline: true },
          { name: "Quota Points", value: `${formatPointNumber(pointValue)} point${pointValue === 1 ? "" : "s"}`, inline: true },
          { name: "Summary", value: truncateForDiscord(summary, 1024), inline: false },
          { name: "Logged By", value: `${loggedBy.tag} (${loggedBy.id})`, inline: true },
        )
        .setTimestamp(),
    ],
    allowedMentions: { parse: [] },
  }).catch(() => {});
  return { contributionDoc, profileThread: profileData.thread };
}

async function handleManualQuotaPointsCommand(interaction) {
  const issuerRank = await getVerifiedMainRankForDiscord(interaction.user.id).catch(error => {
    console.error("Manual quota permission lookup failed:", error.message);
    return null;
  });
  if (!issuerRank) {
    return interaction.editReply("<:cross:1308261058510721076> You must be verified to use this command.");
  }
  if (Number(issuerRank.rank || 0) < SWEETSIEZ_STRUCTURE_CONFIG.CEO_RANK) {
    return interaction.editReply("<:cross:1308261058510721076> You do not have permission to use this command. (Requires Leadership)");
  }

  const action = interaction.options.getString("action");
  const targetUser = interaction.options.getUser("user");
  const board = interaction.options.getString("board");
  const rawPoints = Number(interaction.options.getNumber("points"));
  const reason = interaction.options.getString("reason")?.trim() || "Manual quota adjustment";
  const boardConfig = getBoardQuotaConfig(board);

  if (!["add", "remove"].includes(action)) {
    return interaction.editReply("<:cross:1308261058510721076> Please choose whether to add or remove points.");
  }
  if (!targetUser || targetUser.bot) {
    return interaction.editReply("<:cross:1308261058510721076> Please choose a real staff member.");
  }
  if (!boardConfig) {
    return interaction.editReply("<:cross:1308261058510721076> That board is not configured for quota points.");
  }
  if (!Number.isFinite(rawPoints) || rawPoints <= 0) {
    return interaction.editReply("<:cross:1308261058510721076> Points must be greater than 0.");
  }

  const signedPoints = action === "remove" ? -Math.abs(rawPoints) : Math.abs(rawPoints);
  const pointLabel = `${formatPointNumber(Math.abs(signedPoints))} point${Math.abs(signedPoints) === 1 ? "" : "s"}`;
  const summary = `${action === "remove" ? "Removed" : "Added"} ${pointLabel} for ${boardConfig.shortLabel} quota. Reason: ${reason}`;
  const logResult = await logBoardContribution({
    board,
    activityType: "manual_quota_adjustment",
    discordId: targetUser.id,
    sourceType: "manual_quota_adjustment",
    sourceId: `manual-${Date.now()}-${targetUser.id}`,
    summary,
    amount: signedPoints,
    loggedBy: interaction.user,
  });

  if (!logResult?.contributionDoc) {
    return interaction.editReply("<:cross:1308261058510721076> I could not save that quota adjustment.");
  }

  const quotaWindow = getQuotaWindow(new Date(), "current");
  const progress = await getBoardQuotaPointsForDiscord(
    targetUser.id,
    board,
    quotaWindow.start,
    quotaWindow.end,
  );
  const robloxUsername = verifiedUsers.get(targetUser.id) || "Not verified";
  const adjustmentText = `${signedPoints > 0 ? "+" : "-"}${formatPointNumber(Math.abs(signedPoints))}`;

  const embed = new EmbedBuilder()
    .setTitle(action === "remove" ? "Quota Points Removed" : "Quota Points Added")
    .setColor(action === "remove" ? 0xff9900 : 0x57f287)
    .addFields(
      { name: "Staff Member", value: `${targetUser} (${robloxUsername})`, inline: false },
      { name: "Board", value: boardConfig.label, inline: true },
      { name: "Adjustment", value: `${adjustmentText} point${Math.abs(signedPoints) === 1 ? "" : "s"}`, inline: true },
      { name: "Current Week Total", value: `${formatPointNumber(progress.points)} / ${formatPointNumber(BOARD_QUOTA_CONFIG.WEEKLY_REQUIRED_POINTS)} points`, inline: true },
      { name: "Reason", value: truncateForDiscord(reason, 1024), inline: false },
      { name: "Record ID", value: logResult.contributionDoc.contributionId, inline: true },
      { name: "Week", value: quotaWindow.weekLabel, inline: true },
    )
    .setFooter({ text: `Logged by ${interaction.user.tag}` })
    .setTimestamp();

  return interaction.editReply({ embeds: [embed] });
}

async function handleOperationsPointLogCommand(interaction) {
  const activityType = interaction.options.getString("type", true);
  const typeConfig = OPERATIONS_POINT_LOG_TYPES[activityType];
  if (!typeConfig) {
    return interaction.editReply("That Human Resources Point type is not configured.");
  }

  const authority = await getShiftCertificationAuthorityContext(
    interaction.guild,
    interaction.user.id,
    interaction.member,
  ).catch(error => {
    console.error("Human Resources point log permission lookup failed:", error.message);
    return { ok: false, reason: "I could not verify your Human Resources permissions." };
  });
  if (!authority.ok) {
    return interaction.editReply("Only Human Resources Aspirant Managers, Human Resources Department members, Human Resources Lead, the Human Resources Director, or the President may log Human Resources Points.");
  }
  if (!typeConfig.allowedLevels.includes(authority.level)) {
    const label = typeConfig.allowedLevels.includes("recruitment")
      ? "eligible Human Resources-track members"
      : "Human Resources Department member+, Human Resources Lead, the Human Resources Director, or the President";
    return interaction.editReply(`${typeConfig.label} may only be logged by ${label}.`);
  }

  const targetUser = interaction.options.getUser("user") || interaction.user;
  if (targetUser.bot) return interaction.editReply("Bots cannot receive Human Resources Points.");
  if (
    targetUser.id !== interaction.user.id &&
    !["operations", "operations_head", "operations_overseer", "president"].includes(authority.level)
  ) {
    return interaction.editReply("Only Human Resources Department member+, Human Resources Lead, the Human Resources Director, or the President may log Human Resources Points for another staff member.");
  }

  const targetRank = targetUser.id === interaction.user.id
    ? authority.rankInfo
    : await getVerifiedMainRankForDiscord(targetUser.id).catch(() => null);
  if (!targetRank) {
    return interaction.editReply("That staff member must be verified before Human Resources Points can be logged.");
  }

  const targetAssignment = await getBoardQuotaAssignmentForDiscord(interaction.guild, targetUser.id, targetRank.rank);
  if (targetAssignment?.boardKey !== "operations") {
    return interaction.editReply("That staff member is not currently assigned to the Human Resources Points track.");
  }

  const summary = interaction.options.getString("summary", true).trim();
  const evidence = interaction.options.getString("evidence", true).trim();
  const fullSummary = `${typeConfig.label}: ${summary}\nEvidence: ${evidence}`;

  const logResult = await logBoardContribution({
    board: "operations",
    activityType,
    discordId: targetUser.id,
    sourceType: "opslog",
    sourceId: `opslog:${activityType}:${interaction.id}:${targetUser.id}`,
    summary: fullSummary,
    loggedBy: interaction.user,
  });

  if (!logResult?.contributionDoc) {
    return interaction.editReply("I could not save that Human Resources Point log.");
  }

  const pointValue = getBoardContributionPointValue(logResult.contributionDoc);
  const quotaWindow = getQuotaWindow(new Date(), "current");
  const progress = await getBoardQuotaPointsForDiscord(
    targetUser.id,
    "operations",
    quotaWindow.start,
    quotaWindow.end,
  );
  const robloxUsername = verifiedUsers.get(targetUser.id) || "Not verified";

  const embed = new EmbedBuilder()
    .setTitle("Human Resources Point Logged")
    .setColor(0x2f80ed)
    .addFields(
      { name: "Staff Member", value: `${targetUser} (${robloxUsername})`, inline: false },
      { name: "Type", value: typeConfig.label, inline: true },
      { name: "Points", value: `${formatPointNumber(pointValue)} point${pointValue === 1 ? "" : "s"}`, inline: true },
      { name: "Current Week Total", value: `${formatPointNumber(progress.points)} / ${formatPointNumber(BOARD_QUOTA_CONFIG.WEEKLY_REQUIRED_POINTS)} points`, inline: true },
      { name: "Summary", value: truncateForDiscord(summary, 1024), inline: false },
      { name: "Evidence", value: truncateForDiscord(evidence, 1024), inline: false },
      { name: "Record ID", value: logResult.contributionDoc.contributionId, inline: true },
      { name: "Week", value: quotaWindow.weekLabel, inline: true },
    )
    .setFooter({ text: `Logged by ${interaction.user.tag}` })
    .setTimestamp();

  return interaction.editReply({ embeds: [embed] });
}

async function editStoredMessage(channelId, messageId, payload) {
  if (!channelId || !messageId) return false;
  const channel = await client.channels.fetch(channelId).catch(() => null);
  if (!channel?.isTextBased?.()) return false;
  const message = await channel.messages.fetch(messageId).catch(() => null);
  if (!message) return false;
  await message.edit(payload).catch(() => {});
  return true;
}

async function handleBoardEventButton(interaction) {
  const parts = interaction.customId.split("_");
  const action = parts[1];
  const eventId = parts.slice(2).join("_");
  const eventDoc = await BoardEvent.findOne({ eventId });
  if (!eventDoc) {
    return interaction.reply({ content: "That event could not be found.", flags: MessageFlags.Ephemeral });
  }

  if (action === "checkin") {
    if (eventDoc.status !== "active") {
      return interaction.reply({ content: "Check-in is not currently open for this event.", flags: MessageFlags.Ephemeral });
    }
    const now = Date.now();
    if (!eventDoc.activeEndsAt || now > new Date(eventDoc.activeEndsAt).getTime()) {
      return interaction.reply({ content: "The check-in window for this event has closed.", flags: MessageFlags.Ephemeral });
    }
    if (getEventVerifiedAttendeeIds(eventDoc).includes(interaction.user.id)) {
      return interaction.reply({ content: "You are already checked in for this event.", flags: MessageFlags.Ephemeral });
    }

    const { ModalBuilder, TextInputBuilder, TextInputStyle } = require("discord.js");
    const modal = new ModalBuilder()
      .setCustomId(`bevt_checkin_modal_${eventId}`)
      .setTitle("Event Check-In");
    modal.addComponents(
      new ActionRowBuilder().addComponents(
        new TextInputBuilder()
          .setCustomId("checkin_code")
          .setLabel("Event code")
          .setStyle(TextInputStyle.Short)
          .setRequired(true)
          .setMaxLength(20),
      ),
    );
    return interaction.showModal(modal);
  }

  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }
  if (!["approved"].includes(eventDoc.status)) {
    return interaction.editReply("This event is not accepting RSVP changes.");
  }

  const update = action === "rsvp"
    ? { $addToSet: { rsvps: interaction.user.id } }
    : { $pull: { rsvps: interaction.user.id } };
  update.$set = { updatedAt: new Date() };
  const updated = await BoardEvent.findOneAndUpdate({ eventId }, update, { new: true });
  await interaction.message.edit({
    embeds: [buildPublicEventEmbed(updated)],
    components: [buildEventRsvpRow(updated)],
  }).catch(() => {});
  return interaction.editReply(action === "rsvp" ? "RSVP saved." : "RSVP removed.");
}

async function handleBoardEventCheckInModal(interaction) {
  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }
  const eventId = interaction.customId.replace("bevt_checkin_modal_", "");
  const submittedCode = interaction.fields.getTextInputValue("checkin_code").trim().toUpperCase().replace(/\s+/g, "");
  const eventDoc = await BoardEvent.findOne({ eventId });
  if (!eventDoc) return interaction.editReply("That event could not be found.");
  if (eventDoc.status !== "active") return interaction.editReply("Check-in is not currently open for this event.");
  if (!eventDoc.activeEndsAt || Date.now() > new Date(eventDoc.activeEndsAt).getTime()) {
    return interaction.editReply("The check-in window for this event has closed.");
  }
  if (String(eventDoc.checkInCode || "").toUpperCase() !== submittedCode) {
    return interaction.editReply("That event code is not correct. Ask the host for the live check-in code.");
  }
  if (getEventVerifiedAttendeeIds(eventDoc).includes(interaction.user.id)) {
    return interaction.editReply("You are already checked in for this event.");
  }

  const checkInEntry = {
    discordId: interaction.user.id,
    tag: interaction.user.tag,
    checkedInAt: new Date(),
    rsvped: (eventDoc.rsvps || []).includes(interaction.user.id),
    method: "live_code",
    valid: true,
  };

  const updated = await BoardEvent.findOneAndUpdate(
    { eventId },
    {
      $addToSet: { attendees: interaction.user.id },
      $push: { checkIns: checkInEntry },
      $set: { updatedAt: new Date() },
    },
    { new: true },
  );

  await editStoredMessage(updated.publicChannelId, updated.publicMessageId, {
    embeds: [buildPublicEventEmbed(updated)],
    components: [buildEventRsvpRow(updated)],
  });
  await sendToPlanningThread(updated.planningThreadId, {
    content: `Verified check-in recorded for <@${interaction.user.id}>.`,
    allowedMentions: { users: [interaction.user.id] },
  });
  return interaction.editReply("You are checked in. This will count as verified event attendance.");
}

async function handleEventIdeaButton(interaction) {
  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }
  const context = await getBoardSystemContext(interaction);
  if (!hasOperationsAccess(context, "approve")) {
    return interaction.editReply("Only Human Resources Department member+ may review event ideas.");
  }

  const parts = interaction.customId.split("_");
  const status = parts.pop();
  const maybeLater = interaction.customId.endsWith("_maybe_later");
  const ideaId = maybeLater ? parts.slice(2, -1).join("_") : parts.slice(2).join("_");
  const finalStatus = maybeLater ? "maybe_later" : status;
  const ideaDoc = await EventIdea.findOneAndUpdate(
    { ideaId },
    {
      $set: {
        status: finalStatus,
        reviewedByDiscordId: interaction.user.id,
        reviewedByTag: interaction.user.tag,
        reviewedAt: new Date(),
        updatedAt: new Date(),
      },
    },
    { new: true },
  );
  if (!ideaDoc) return interaction.editReply("That event idea could not be found.");
  await interaction.message.edit({
    embeds: [buildEventIdeaEmbed(ideaDoc)],
    components: finalStatus === "archived" ? [] : [buildEventIdeaRow(ideaId)],
  }).catch(() => {});
  await logBoardContribution({
    board: "operations",
    activityType: "event_idea_reviewed",
    discordId: interaction.user.id,
    sourceType: "event_idea",
    sourceId: ideaId,
    summary: `Reviewed event idea as ${finalStatus}.`,
    loggedBy: interaction.user,
  }).catch(() => {});
  return interaction.editReply(`Event idea marked as ${finalStatus.replaceAll("_", " ")}.`);
}

function parseAnnouncementRequestButtonId(customId) {
  const parts = String(customId || "").split("_");
  if (parts[1] === "set") {
    const legacyAction = parts.pop();
    const requestId = parts.slice(2).join("_");
    return {
      action: legacyAction === "post" ? "post" : legacyAction === "deny" ? "deny" : "archive",
      requestId,
    };
  }
  return {
    action: parts[1],
    requestId: parts.slice(2).join("_"),
  };
}

function showAnnouncementRequestModal(interaction, action, requestId) {
  const { ModalBuilder, TextInputBuilder, TextInputStyle } = require("discord.js");
  const modal = new ModalBuilder()
    .setCustomId(`areq_modal_${action}_${requestId}`);

  if (action === "edits") {
    modal.setTitle("Request Announcement Edits");
    modal.addComponents(
      new ActionRowBuilder().addComponents(
        new TextInputBuilder()
          .setCustomId("note")
          .setLabel("What needs to be edited?")
          .setStyle(TextInputStyle.Paragraph)
          .setRequired(true)
          .setMaxLength(1000),
      ),
    );
  } else if (action === "schedule") {
    modal.setTitle("Schedule Announcement");
    modal.addComponents(
      new ActionRowBuilder().addComponents(
        new TextInputBuilder()
          .setCustomId("scheduled_time")
          .setLabel("Post time, EST")
          .setStyle(TextInputStyle.Short)
          .setRequired(true)
          .setPlaceholder("MM/DD/YYYY 7:30 PM EST")
          .setMaxLength(40),
      ),
    );
  } else if (action === "deny") {
    modal.setTitle("Deny Announcement Request");
    modal.addComponents(
      new ActionRowBuilder().addComponents(
        new TextInputBuilder()
          .setCustomId("reason")
          .setLabel("Reason for denial")
          .setStyle(TextInputStyle.Paragraph)
          .setRequired(true)
          .setMaxLength(1000),
      ),
    );
  } else {
    return interaction.reply({ content: "Unknown announcement action.", flags: MessageFlags.Ephemeral });
  }

  return interaction.showModal(modal);
}

async function refreshAnnouncementRequestMessages(requestDoc) {
  const reviewPayload = {
    embeds: [buildAnnouncementRequestEmbed(requestDoc), buildAnnouncementPublicPreviewEmbed(requestDoc)],
    components: buildAnnouncementRequestRows(requestDoc),
    allowedMentions: { parse: [] },
  };
  const intakePayload = {
    embeds: [buildAnnouncementRequestEmbed(requestDoc)],
    components: [],
    allowedMentions: { parse: [] },
  };

  await editStoredMessage(requestDoc.reviewChannelId, requestDoc.reviewMessageId, reviewPayload);
  await editStoredMessage(requestDoc.intakeChannelId, requestDoc.intakeMessageId, intakePayload);
}

async function notifyAnnouncementRequester(requestDoc, title, description) {
  const user = await client.users.fetch(requestDoc.requestedByDiscordId).catch(() => null);
  if (!user) return;
  await user.send({
    embeds: [
      new EmbedBuilder()
        .setColor(announcementStatusColor(requestDoc.status))
        .setTitle(title)
        .setDescription(description)
        .addFields(
          { name: "Request", value: `${requestDoc.title} (${requestDoc.requestId})`, inline: false },
          { name: "Status", value: ANNOUNCEMENT_STATUS_LABELS[requestDoc.status] || requestDoc.status, inline: true },
        )
        .setTimestamp(),
    ],
  }).catch(() => {});
}

async function postAnnouncementRequest(clientRef, guild, requestDoc, actor) {
  if (!requestDoc || ["posted", "denied", "archived"].includes(requestDoc.status)) {
    return { ok: false, message: "This announcement request is already closed." };
  }

  const targetChannelId = getAnnouncementTargetChannelId(requestDoc.target, requestDoc);
  const targetChannel = guild
    ? await guild.channels.fetch(targetChannelId).catch(() => null)
    : await clientRef.channels.fetch(targetChannelId).catch(() => null);
  if (!targetChannel?.isTextBased?.()) {
    return { ok: false, message: "I could not reach the target announcement channel." };
  }

  const publicMessage = await targetChannel.send(buildAnnouncementPublicPayload(requestDoc));
  const now = new Date();
  const updated = await AnnouncementRequest.findOneAndUpdate(
    { requestId: requestDoc.requestId },
    {
      $set: {
        status: "posted",
        publicChannelId: targetChannel.id,
        publicMessageId: publicMessage.id,
        reviewedByDiscordId: actor?.id || requestDoc.reviewedByDiscordId || null,
        reviewedByTag: actor?.tag || requestDoc.reviewedByTag || "Sweetsiez Assistant",
        reviewedAt: now,
        updatedAt: now,
      },
      $push: {
        history: buildAnnouncementHistoryEntry("posted", actor, `Posted in #${targetChannel.name || targetChannel.id}.`),
      },
    },
    { new: true },
  );

  if (actor?.id && /^\d+$/.test(actor.id)) {
    await logBoardContribution({
      board: "marketing",
      activityType: "announcement_posted",
      discordId: actor.id,
      sourceType: "announcement_request",
      sourceId: requestDoc.requestId,
      summary: `Posted announcement request to ${requestDoc.target}.`,
      loggedBy: actor,
    }).catch(() => {});
  }

  await refreshAnnouncementRequestMessages(updated);
  await notifyAnnouncementRequester(
    updated,
    "Announcement Posted",
    `Your announcement request has been posted in <#${targetChannel.id}>.`,
  );
  return { ok: true, requestDoc: updated, publicMessage };
}

async function handleAnnouncementRequestButton(interaction) {
  const { action, requestId } = parseAnnouncementRequestButtonId(interaction.customId);
  if (["edits", "schedule", "deny"].includes(action)) {
    return showAnnouncementRequestModal(interaction, action, requestId);
  }

  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }
  const context = await getBoardSystemContext(interaction);
  if (!hasMarketingAccess(context, "approve")) {
    return interaction.editReply("Only Public Relations Department+ may process announcement requests.");
  }

  let requestDoc = await AnnouncementRequest.findOne({ requestId });
  if (!requestDoc) return interaction.editReply("That announcement request could not be found.");
  if (["posted", "denied", "archived"].includes(requestDoc.status)) {
    return interaction.editReply(`This announcement request is already ${ANNOUNCEMENT_STATUS_LABELS[requestDoc.status] || requestDoc.status}.`);
  }

  if (["approve", "post"].includes(action) && announcementRequiresOfficerApproval(requestDoc) && !hasAnnouncementOfficerAccess(context)) {
    return interaction.editReply("This request includes a ping, so it needs Public Relations Lead or Leadership approval before it can be approved or posted.");
  }

  const now = new Date();
  if (action === "claim") {
    requestDoc = await AnnouncementRequest.findOneAndUpdate(
      { requestId },
      {
        $set: {
          status: requestDoc.status === "submitted" ? "claimed" : requestDoc.status,
          claimedByDiscordId: interaction.user.id,
          claimedByTag: interaction.user.tag,
          claimedAt: now,
          updatedAt: now,
        },
        $push: { history: buildAnnouncementHistoryEntry("claimed", interaction.user) },
      },
      { new: true },
    );
    await refreshAnnouncementRequestMessages(requestDoc);
    return interaction.editReply("Announcement request claimed.");
  }

  if (action === "approve") {
    requestDoc = await AnnouncementRequest.findOneAndUpdate(
      { requestId },
      {
        $set: {
          status: "approved",
          approvedByDiscordId: interaction.user.id,
          approvedByTag: interaction.user.tag,
          approvedAt: now,
          reviewedByDiscordId: interaction.user.id,
          reviewedByTag: interaction.user.tag,
          reviewedAt: now,
          updatedAt: now,
        },
        $push: { history: buildAnnouncementHistoryEntry("approved", interaction.user) },
      },
      { new: true },
    );
    await refreshAnnouncementRequestMessages(requestDoc);
    await notifyAnnouncementRequester(requestDoc, "Announcement Approved", "Your announcement request has been approved by Public Relations.");
    return interaction.editReply("Announcement request approved.");
  }

  if (action === "post") {
    const result = await postAnnouncementRequest(interaction.client, interaction.guild, requestDoc, interaction.user);
    return interaction.editReply(result.ok ? `Announcement posted: ${result.publicMessage.url}` : result.message);
  }

  if (action === "archive") {
    requestDoc = await AnnouncementRequest.findOneAndUpdate(
      { requestId },
      {
        $set: {
          status: "archived",
          reviewedByDiscordId: interaction.user.id,
          reviewedByTag: interaction.user.tag,
          reviewedAt: now,
          updatedAt: now,
        },
        $push: { history: buildAnnouncementHistoryEntry("archived", interaction.user) },
      },
      { new: true },
    );
    await refreshAnnouncementRequestMessages(requestDoc);
    return interaction.editReply("Announcement request archived.");
  }

  return interaction.editReply("Unknown announcement action.");
}

async function handleAnnouncementRequestModal(interaction) {
  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }
  const parts = interaction.customId.split("_");
  const action = parts[2];
  const requestId = parts.slice(3).join("_");

  const context = await getBoardSystemContext(interaction);
  if (!hasMarketingAccess(context, "approve")) {
    return interaction.editReply("Only Public Relations Department+ may process announcement requests.");
  }

  let requestDoc = await AnnouncementRequest.findOne({ requestId });
  if (!requestDoc) return interaction.editReply("That announcement request could not be found.");
  if (["posted", "denied", "archived"].includes(requestDoc.status)) {
    return interaction.editReply(`This announcement request is already ${ANNOUNCEMENT_STATUS_LABELS[requestDoc.status] || requestDoc.status}.`);
  }

  const now = new Date();
  if (action === "edits") {
    const note = interaction.fields.getTextInputValue("note").trim();
    requestDoc = await AnnouncementRequest.findOneAndUpdate(
      { requestId },
      {
        $set: {
          status: "needs_edits",
          editNote: note,
          reviewedByDiscordId: interaction.user.id,
          reviewedByTag: interaction.user.tag,
          reviewedAt: now,
          updatedAt: now,
        },
        $push: { history: buildAnnouncementHistoryEntry("needs_edits", interaction.user, note) },
      },
      { new: true },
    );
    await refreshAnnouncementRequestMessages(requestDoc);
    await notifyAnnouncementRequester(requestDoc, "Announcement Edits Requested", note);
    return interaction.editReply("Edits requested and the requester was notified.");
  }

  if (action === "schedule") {
    if (announcementRequiresOfficerApproval(requestDoc) && !hasAnnouncementOfficerAccess(context)) {
      return interaction.editReply("This request includes a ping, so it needs Public Relations Lead or Leadership approval before it can be scheduled.");
    }
    const rawTime = interaction.fields.getTextInputValue("scheduled_time").trim();
    const scheduledAt = parseAnnouncementScheduleInput(rawTime);
    if (!scheduledAt || scheduledAt.getTime() <= Date.now() + 30_000) {
      return interaction.editReply("Please use a future EST time like `07/15/2026 7:30 PM EST`.");
    }
    requestDoc = await AnnouncementRequest.findOneAndUpdate(
      { requestId },
      {
        $set: {
          status: "scheduled",
          scheduledAt,
          scheduledByDiscordId: interaction.user.id,
          scheduledByTag: interaction.user.tag,
          approvedByDiscordId: requestDoc.approvedByDiscordId || interaction.user.id,
          approvedByTag: requestDoc.approvedByTag || interaction.user.tag,
          approvedAt: requestDoc.approvedAt || now,
          reviewedByDiscordId: interaction.user.id,
          reviewedByTag: interaction.user.tag,
          reviewedAt: now,
          updatedAt: now,
        },
        $push: { history: buildAnnouncementHistoryEntry("scheduled", interaction.user, rawTime) },
      },
      { new: true },
    );
    await refreshAnnouncementRequestMessages(requestDoc);
    await notifyAnnouncementRequester(
      requestDoc,
      "Announcement Scheduled",
      `Your announcement request has been scheduled for <t:${Math.floor(scheduledAt.getTime() / 1000)}:F>.`,
    );
    return interaction.editReply(`Announcement scheduled for <t:${Math.floor(scheduledAt.getTime() / 1000)}:F>.`);
  }

  if (action === "deny") {
    const reason = interaction.fields.getTextInputValue("reason").trim();
    requestDoc = await AnnouncementRequest.findOneAndUpdate(
      { requestId },
      {
        $set: {
          status: "denied",
          deniedReason: reason,
          reviewedByDiscordId: interaction.user.id,
          reviewedByTag: interaction.user.tag,
          reviewedAt: now,
          updatedAt: now,
        },
        $push: { history: buildAnnouncementHistoryEntry("denied", interaction.user, reason) },
      },
      { new: true },
    );
    await refreshAnnouncementRequestMessages(requestDoc);
    await notifyAnnouncementRequester(requestDoc, "Announcement Denied", reason);
    return interaction.editReply("Announcement request denied and the requester was notified.");
  }

  return interaction.editReply("Unknown announcement action.");
}

let announcementRequestSchedulerStarted = false;

function startAnnouncementRequestScheduler(clientRef) {
  if (announcementRequestSchedulerStarted) return;
  announcementRequestSchedulerStarted = true;

  const runDueAnnouncements = async () => {
    if (mongoose.connection.readyState !== 1) return;
    const dueRequests = await AnnouncementRequest.find({
      status: "scheduled",
      scheduledAt: { $lte: new Date() },
    }).sort({ scheduledAt: 1 }).limit(5);

    if (!dueRequests.length) return;
    const guild = clientRef.guilds.cache.get(SWEETSIEZ_STRUCTURE_CONFIG.GUILD_ID) || clientRef.guilds.cache.first();
    for (const requestDoc of dueRequests) {
      const actor = {
        id: requestDoc.scheduledByDiscordId || requestDoc.approvedByDiscordId || null,
        tag: requestDoc.scheduledByTag || requestDoc.approvedByTag || "Scheduled Announcement",
      };
      const result = await postAnnouncementRequest(clientRef, guild, requestDoc, actor).catch(error => ({
        ok: false,
        message: error.message,
      }));
      if (!result.ok) {
        await AnnouncementRequest.updateOne(
          { requestId: requestDoc.requestId, status: "scheduled" },
          {
            $set: { updatedAt: new Date() },
            $push: { history: buildAnnouncementHistoryEntry("scheduled", actor, `Scheduled post failed: ${result.message}`) },
          },
        ).catch(() => {});
        console.error(`[AnnouncementRequests] Scheduled post failed for ${requestDoc.requestId}: ${result.message}`);
      }
    }
  };

  setInterval(() => {
    runDueAnnouncements().catch(error => console.error("[AnnouncementRequests] Scheduler error:", error.message));
  }, 60 * 1000);

  setTimeout(() => {
    runDueAnnouncements().catch(error => console.error("[AnnouncementRequests] Startup scheduler error:", error.message));
  }, 45 * 1000);

  console.log("Announcement request scheduler started.");
}

let operationsEventSchedulerStarted = false;

function startOperationsEventScheduler(clientRef) {
  if (operationsEventSchedulerStarted) return;
  operationsEventSchedulerStarted = true;

  const runEventAutomation = async () => {
    if (mongoose.connection.readyState !== 1) return;
    const now = new Date();

    const upcoming = await BoardEvent.find({
      status: "approved",
      scheduledAt: { $gte: now, $lte: new Date(now.getTime() + 24 * 60 * 60 * 1000) },
    });

    for (const eventDoc of upcoming) {
      const scheduledAt = new Date(eventDoc.scheduledAt);
      const minutesUntil = Math.round((scheduledAt.getTime() - now.getTime()) / 60000);
      const reminderKey = minutesUntil <= 60 ? "1h" : "24h";
      if ((eventDoc.reminderKeys || []).includes(reminderKey)) continue;

      await sendToPlanningThread(eventDoc.planningThreadId, {
        embeds: [
          new EmbedBuilder()
            .setColor(0x5bc0de)
            .setTitle(reminderKey === "1h" ? "Event Starts Soon" : "Event Reminder")
            .setDescription(
              `**${eventDoc.name}** is scheduled for <t:${Math.floor(scheduledAt.getTime() / 1000)}:F>.\n\n` +
              "Before the event starts, use `/event start` to open live check-in and generate the event code.",
            )
            .addFields({ name: "Event ID", value: eventDoc.eventId, inline: true })
            .setTimestamp(),
        ],
      });
      eventDoc.reminderKeys = [...new Set([...(eventDoc.reminderKeys || []), reminderKey])];
      eventDoc.updatedAt = new Date();
      await eventDoc.save().catch(() => {});
    }

    const expiredActiveEvents = await BoardEvent.find({
      status: "active",
      activeEndsAt: { $lte: now },
    });

    for (const eventDoc of expiredActiveEvents) {
      eventDoc.status = "awaiting_recap";
      eventDoc.checkInClosedAt = now;
      eventDoc.updatedAt = now;
      await eventDoc.save().catch(() => {});
      await editStoredMessage(eventDoc.publicChannelId, eventDoc.publicMessageId, {
        embeds: [buildPublicEventEmbed(eventDoc)],
        components: [buildEventRsvpRow(eventDoc)],
      });
      await sendToPlanningThread(eventDoc.planningThreadId, {
        embeds: [
          new EmbedBuilder()
            .setColor(0xbb6bd9)
            .setTitle("Event Check-In Auto-Closed")
            .setDescription("The live check-in window has ended. Please complete the event recap.")
            .addFields(
              { name: "Event ID", value: eventDoc.eventId, inline: true },
              { name: "Verified Attendance", value: String(getEventVerifiedAttendeeIds(eventDoc).length), inline: true },
            )
            .setTimestamp(),
        ],
      });
    }

    const recapReminders = await BoardEvent.find({
      status: "awaiting_recap",
      activeEndsAt: { $lte: new Date(now.getTime() - 12 * 60 * 60 * 1000) },
      reminderKeys: { $ne: "recap_due" },
    }).limit(10);

    for (const eventDoc of recapReminders) {
      await sendToPlanningThread(eventDoc.planningThreadId, {
        embeds: [
          new EmbedBuilder()
            .setColor(0xf1c40f)
            .setTitle("Event Recap Needed")
            .setDescription(`**${eventDoc.name}** is still awaiting a recap. Use \`/event recap\` to complete the event record.`)
            .addFields({ name: "Event ID", value: eventDoc.eventId, inline: true })
            .setTimestamp(),
        ],
      });
      eventDoc.reminderKeys = [...new Set([...(eventDoc.reminderKeys || []), "recap_due"])];
      eventDoc.updatedAt = new Date();
      await eventDoc.save().catch(() => {});
    }
  };

  setInterval(() => {
    runEventAutomation().catch(error => console.error("[OperationsEvents] Scheduler error:", error.message));
  }, 60 * 1000);

  setTimeout(() => {
    runEventAutomation().catch(error => console.error("[OperationsEvents] Startup scheduler error:", error.message));
  }, 60 * 1000);

  console.log("Human Resources event scheduler started.");
}

async function handleCommunityFeedbackPollButton(interaction) {
  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }
  const parts = interaction.customId.split("_");
  const optionIndex = Number(parts.pop());
  const pollId = parts.slice(2).join("_");
  const pollDoc = await CommunityFeedbackPoll.findOne({ pollId });
  if (!pollDoc) return interaction.editReply("That poll could not be found.");
  if (pollDoc.status === "closed") return interaction.editReply("That poll is closed.");
  if (!Number.isInteger(optionIndex) || optionIndex < 0 || optionIndex >= pollDoc.options.length) {
    return interaction.editReply("That poll option is invalid.");
  }

  const options = (pollDoc.options || []).map((option, index) => {
    const voters = new Set(option.voters || []);
    voters.delete(interaction.user.id);
    if (index === optionIndex) voters.add(interaction.user.id);
    return { ...option, voters: [...voters] };
  });
  pollDoc.options = options;
  pollDoc.updatedAt = new Date();
  await pollDoc.save();
  await interaction.message.edit({
    embeds: [buildCommunityFeedbackPollEmbed(pollDoc)],
    components: [buildCommunityFeedbackPollRow(pollDoc)],
  }).catch(() => {});
  return interaction.editReply("Vote saved.");
}

async function handleCommunityFeedbackButton(interaction) {
  const parts = interaction.customId.split("_");
  const action = parts[1];

  if (action === "open") {
    const sourceType = parts[2];
    const sourceId = parts.slice(3).join("_");
    return showCommunityFeedbackModal(interaction, sourceType, sourceId);
  }

  if (action === "response") {
    const feedbackId = parts.slice(2).join("_");
    return showCommunityFeedbackResponseModal(interaction, feedbackId);
  }

  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }
  const context = await getBoardSystemContext(interaction);
  if (!hasMarketingAccess(context, "approve")) {
    return interaction.editReply("Only Public Relations Department+ may manage community feedback.");
  }

  if (action === "fwd") {
    const targetKey = parts[2];
    const feedbackId = parts.slice(3).join("_");
    const feedbackDoc = await CommunityFeedbackSubmission.findOne({ feedbackId });
    if (!feedbackDoc) return interaction.editReply("That feedback submission could not be found.");
    return forwardCommunityFeedback(interaction, feedbackDoc, targetKey);
  }

  if (action === "reviewed") {
    const feedbackId = parts.slice(2).join("_");
    const updated = await CommunityFeedbackSubmission.findOneAndUpdate(
      { feedbackId },
      { $set: { status: "reviewed", updatedAt: new Date() } },
      { new: true },
    );
    if (!updated) return interaction.editReply("That feedback submission could not be found.");
    await logBoardContribution({
      board: "marketing",
      activityType: "feedback_reviewed",
      discordId: interaction.user.id,
      sourceType: "community_feedback",
      sourceId: feedbackId,
      summary: "Marked community feedback reviewed.",
      loggedBy: interaction.user,
    }).catch(() => {});
    await refreshCommunityFeedbackReviewMessage(updated);
    return interaction.editReply("Feedback marked reviewed.");
  }

  return interaction.editReply("Unknown community feedback action.");
}

async function handleCommunityFeedbackModal(interaction) {
  if (interaction.customId.startsWith("cfb_response_modal_")) {
    if (!interaction.deferred && !interaction.replied) {
      await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
    }
    const context = await getBoardSystemContext(interaction);
    if (!hasMarketingAccess(context, "approve")) {
      return interaction.editReply("Only Public Relations Department+ may make official feedback responses.");
    }

    const feedbackId = interaction.customId.replace("cfb_response_modal_", "");
    const responseText = interaction.fields.getTextInputValue("response_text").trim();
    const feedbackDoc = await CommunityFeedbackSubmission.findOne({ feedbackId });
    if (!feedbackDoc) return interaction.editReply("That feedback submission could not be found.");

    const publicMessage = await postCommunityFeedbackResponse(feedbackDoc, responseText, interaction.user);
    if (!publicMessage) {
      return interaction.editReply("I could not reach the original public post to publish that response.");
    }

    const responseEntry = {
      text: responseText,
      by: interaction.user.id,
      byTag: interaction.user.tag,
      at: new Date(),
      publicChannelId: publicMessage.channelId,
      publicMessageId: publicMessage.id,
    };
    const updated = await CommunityFeedbackSubmission.findOneAndUpdate(
      { feedbackId },
      {
        $set: { status: "responded", updatedAt: new Date() },
        $push: { responses: responseEntry },
      },
      { new: true },
    );
    await logBoardContribution({
      board: "marketing",
      activityType: "feedback_responded",
      discordId: interaction.user.id,
      sourceType: "community_feedback",
      sourceId: feedbackId,
      summary: "Posted an official response to community feedback.",
      loggedBy: interaction.user,
    }).catch(() => {});
    await refreshCommunityFeedbackReviewMessage(updated);
    return interaction.editReply(`Response posted: ${publicMessage.url}`);
  }

  if (interaction.customId.startsWith("cfb_modal_")) {
    const rest = interaction.customId.replace("cfb_modal_", "");
    const [sourceType, ...sourceIdParts] = rest.split("_");
    const sourceId = sourceIdParts.join("_");
    return submitCommunityFeedback(interaction, sourceType, sourceId);
  }

  return interaction.reply({ content: "Unknown community feedback form.", flags: MessageFlags.Ephemeral });
}

