async function handleSocialMediaSubmissionButton(interaction) {
  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }
  const context = await getBoardSystemContext(interaction);
  if (!hasMarketingAccess(context, "approve")) {
    return interaction.editReply("Only Public Relations Department+ may manage community social media submissions.");
  }

  const remainder = interaction.customId.slice("smsub_set_".length);
  let finalStatus = remainder.split("_").pop();
  let submissionId = remainder.slice(0, -(finalStatus.length + 1));
  if (remainder.endsWith("_needs_credit")) {
    finalStatus = "needs_credit";
    submissionId = remainder.slice(0, -"_needs_credit".length);
  } else if (remainder.endsWith("_needs_editing")) {
    finalStatus = "needs_editing";
    submissionId = remainder.slice(0, -"_needs_editing".length);
  }

  const submissionDoc = await SocialMediaSubmission.findOneAndUpdate(
    { submissionId },
    {
      $set: {
        status: finalStatus,
        reviewedByDiscordId: interaction.user.id,
        reviewedByTag: interaction.user.tag,
        reviewedAt: new Date(),
        updatedAt: new Date(),
      },
      $push: {
        history: {
          status: finalStatus,
          by: interaction.user.id,
          byTag: interaction.user.tag,
          at: new Date(),
        },
      },
    },
    { new: true },
  );
  if (!submissionDoc) return interaction.editReply("That community submission could not be found.");

  await interaction.message.edit({
    embeds: [buildSocialMediaSubmissionEmbed(submissionDoc)],
    components: ["posted", "archived", "rejected"].includes(finalStatus) ? [] : [buildSocialMediaSubmissionRow(submissionId)],
  }).catch(() => {});

  const submitter = await interaction.client.users.fetch(submissionDoc.submittedByDiscordId).catch(() => null);
  if (submitter) {
    await submitter.send({
      embeds: [
        new EmbedBuilder()
          .setColor(marketingStatusColor(finalStatus))
          .setTitle("Social Media Submission Update")
          .setDescription(`Your submission for **${submissionDoc.platform}** is now **${formatMarketingStatus(finalStatus)}**.`)
          .addFields({ name: "Submission ID", value: submissionId, inline: true })
          .setTimestamp(),
      ],
    }).catch(() => {});
  }

  if (finalStatus === "posted") {
    await logBoardContribution({
      board: "marketing",
      activityType: "community_submission_posted",
      discordId: interaction.user.id,
      sourceType: "social_media_submission",
      sourceId: submissionId,
      summary: `Posted community submission for ${submissionDoc.platform}.`,
      loggedBy: interaction.user,
    }).catch(() => {});
  }

  return interaction.editReply(`Community submission ${submissionId} marked as ${formatMarketingStatus(finalStatus)}.`);
}

async function fetchTextChannel(guild, channelId) {
  const channel = await guild.channels.fetch(channelId).catch(() => null);
  return channel?.isTextBased?.() ? channel : null;
}

async function fetchForumChannel(guild, channelId) {
  const channel = await guild.channels.fetch(channelId).catch(() => null);
  return channel?.type === ChannelType.GuildForum ? channel : null;
}

async function sendToPlanningThread(threadId, payload) {
  if (!threadId) return false;
  const thread = await client.channels.fetch(threadId).catch(() => null);
  if (!thread?.isThread?.()) return false;
  if (thread.archived) await thread.setArchived(false).catch(() => {});
  await thread.send(payload).catch(() => {});
  return true;
}

function eventActivityDate(eventDoc) {
  return eventDoc.activeStartedAt || eventDoc.scheduledAt || eventDoc.createdAt || new Date(0);
}

function isEventInsideWindow(eventDoc, start, end) {
  const date = new Date(eventActivityDate(eventDoc));
  return date >= start && date < end;
}

function addCount(map, key, amount = 1) {
  if (!key) return;
  const id = String(key);
  map.set(id, (map.get(id) || 0) + amount);
}

function formatTopDiscordCounts(map, limit = 5) {
  const rows = [...map.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, limit);
  return rows.length
    ? rows.map(([discordId, count], index) => `${index + 1}. <@${discordId}> - **${count}**`).join("\n")
    : "No data yet.";
}

function getEventRatingStats(eventDoc) {
  const ratings = (eventDoc.ratings || []).filter(item => Number(item.rating) >= 1 && Number(item.rating) <= 5);
  const average = ratings.length
    ? Math.round((ratings.reduce((total, item) => total + Number(item.rating), 0) / ratings.length) * 10) / 10
    : 0;
  return { count: ratings.length, average, ratings };
}

function getKeywordSummary(textValues, limit = 6) {
  const stopWords = new Set(["the", "and", "for", "that", "with", "this", "was", "were", "you", "your", "our", "are", "but", "not", "have", "has", "event", "events", "sweetsiez"]);
  const counts = new Map();
  for (const value of textValues) {
    const words = String(value || "").toLowerCase().match(/[a-z0-9]{4,}/g) || [];
    for (const word of words) {
      if (stopWords.has(word)) continue;
      counts.set(word, (counts.get(word) || 0) + 1);
    }
  }
  const rows = [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, limit);
  return rows.length ? rows.map(([word, count]) => `${word} (${count})`).join(", ") : "No strong themes yet.";
}

async function buildCommunityPulseEmbed(days = 30) {
  const now = new Date();
  const start = new Date(now.getTime() - Math.max(1, Number(days || 30)) * 24 * 60 * 60 * 1000);
  const events = await BoardEvent.find({
    $or: [
      { createdAt: { $gte: start, $lt: now } },
      { scheduledAt: { $gte: start, $lt: now } },
      { activeStartedAt: { $gte: start, $lt: now } },
    ],
  }).lean();
  const postedAnnouncements = await AnnouncementRequest.find({ status: "posted", updatedAt: { $gte: start, $lt: now } }).lean();
  const allAnnouncementRequests = await AnnouncementRequest.find({ createdAt: { $gte: start, $lt: now } }).lean();
  const eventIdeas = await EventIdea.find({ createdAt: { $gte: start, $lt: now } }).lean();
  const polls = await CommunityFeedbackPoll.find({ createdAt: { $gte: start, $lt: now } }).lean();
  const feedbackSubmissions = await CommunityFeedbackSubmission.find({ createdAt: { $gte: start, $lt: now } }).lean();

  const attendeeCounts = new Map();
  const helperCounts = new Map();
  let verifiedAttendance = 0;
  let ratedEvents = 0;
  let ratingTotal = 0;
  let ratingCount = 0;
  const commentValues = [];
  for (const eventDoc of events) {
    const attendees = getEventVerifiedAttendeeIds(eventDoc);
    verifiedAttendance += attendees.length;
    for (const discordId of attendees) addCount(attendeeCounts, discordId);
    for (const helperId of eventDoc.helpers || []) addCount(helperCounts, helperId);
    const stats = getEventRatingStats(eventDoc);
    if (stats.count) {
      ratedEvents += 1;
      ratingTotal += stats.average;
      ratingCount += 1;
      for (const rating of stats.ratings) commentValues.push(rating.comment);
    }
  }

  const avgAttendance = events.length ? Math.round((verifiedAttendance / events.length) * 10) / 10 : 0;
  const avgQuality = ratingCount ? Math.round((ratingTotal / ratingCount) * 10) / 10 : 0;
  const pendingAnnouncements = allAnnouncementRequests.filter(item => !["posted", "denied", "archived"].includes(item.status)).length;

  return new EmbedBuilder()
    .setColor(0x27ae60)
    .setTitle("Community Pulse Report")
    .setDescription(`Community snapshot for the last **${days} day${Number(days) === 1 ? "" : "s"}**.`)
    .addFields(
      { name: "Events", value: [
        `Tracked: **${events.length}**`,
        `Verified Attendance: **${verifiedAttendance}**`,
        `Average Attendance: **${avgAttendance}**`,
        `Rated Events: **${ratedEvents}**`,
        `Average Quality: **${avgQuality || "N/A"}**`,
      ].join("\n"), inline: true },
      { name: "Public Communication", value: [
        `Announcement Requests: **${allAnnouncementRequests.length}**`,
        `Posted: **${postedAnnouncements.length}**`,
        `Pending/Scheduled: **${pendingAnnouncements}**`,
        `Feedback Submissions: **${feedbackSubmissions.length}**`,
        `Feedback Polls: **${polls.length}**`,
        `Event Ideas: **${eventIdeas.length}**`,
      ].join("\n"), inline: true },
      { name: "Community Themes", value: getKeywordSummary([
        ...commentValues,
        ...feedbackSubmissions.map(item => item.feedbackText),
        ...eventIdeas.map(item => `${item.title} ${item.description}`),
        ...polls.map(item => item.question),
      ]), inline: false },
      { name: "Top Attendees", value: formatTopDiscordCounts(attendeeCounts), inline: false },
      { name: "Top Event Helpers", value: formatTopDiscordCounts(helperCounts), inline: false },
    )
    .setTimestamp();
}

async function buildCommunityMilestonesEmbed(days = 90) {
  const now = new Date();
  const start = new Date(now.getTime() - Math.max(1, Number(days || 90)) * 24 * 60 * 60 * 1000);
  const events = await BoardEvent.find({
    $or: [
      { activeStartedAt: { $gte: start, $lt: now } },
      { scheduledAt: { $gte: start, $lt: now } },
      { createdAt: { $gte: start, $lt: now } },
    ],
  }).lean();
  const counts = new Map();
  for (const eventDoc of events) {
    for (const discordId of getEventVerifiedAttendeeIds(eventDoc)) addCount(counts, discordId);
  }
  const rows = [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, 12);
  const labelForCount = count => {
    if (count >= 20) return "Community Legend";
    if (count >= 10) return "Event Regular";
    if (count >= 5) return "Community Star";
    if (count >= 3) return "RSVP Champion";
    return "Getting Started";
  };

  return new EmbedBuilder()
    .setColor(0x5bc0de)
    .setTitle("Community Public Relations Milestones")
    .setDescription(`Verified event attendance milestones for the last **${days} day${Number(days) === 1 ? "" : "s"}**. These are recognition signals for Operations and Marketing, not automatic role awards.`)
    .addFields({
      name: "Milestone Leaders",
      value: rows.length
        ? rows.map(([discordId, count], index) => `${index + 1}. <@${discordId}> - **${count}** check-ins - ${labelForCount(count)}`).join("\n")
        : "No verified attendance in this window.",
      inline: false,
    })
    .setTimestamp();
}

async function buildOperationsDashboardEmbed(days = 30) {
  const now = new Date();
  const start = new Date(now.getTime() - Math.max(1, Number(days || 30)) * 24 * 60 * 60 * 1000);
  const events = await BoardEvent.find({
    $or: [
      { createdAt: { $gte: start, $lt: now } },
      { scheduledAt: { $gte: start, $lt: now } },
      { activeStartedAt: { $gte: start, $lt: now } },
    ],
  }).lean();

  const upcoming = await BoardEvent.find({
    status: { $in: ["planning", "approved"] },
    scheduledAt: { $gte: now },
  }).sort({ scheduledAt: 1 }).limit(5).lean();

  const missingRecaps = await BoardEvent.find({
    status: "awaiting_recap",
  }).sort({ activeEndsAt: 1 }).limit(5).lean();

  const eventIdeasReviewed = await EventIdea.countDocuments({
    reviewedAt: { $gte: start, $lt: now },
  });
  const feedbackPolls = await CommunityFeedbackPoll.countDocuments({
    createdAt: { $gte: start, $lt: now },
  });
  const feedbackSubmissions = await CommunityFeedbackSubmission.countDocuments({
    createdAt: { $gte: start, $lt: now },
  });
  const openFeedbackSubmissions = await CommunityFeedbackSubmission.countDocuments({
    createdAt: { $gte: start, $lt: now },
    status: { $in: ["new", "forwarded"] },
  });
  const announcements = await AnnouncementRequest.countDocuments({
    status: "posted",
    updatedAt: { $gte: start, $lt: now },
  });

  const statusCounts = {};
  const attendeeCounts = new Map();
  const helperCounts = new Map();
  let totalVerifiedAttendance = 0;
  let completedEvents = 0;
  for (const eventDoc of events) {
    statusCounts[eventDoc.status] = (statusCounts[eventDoc.status] || 0) + 1;
    const verifiedAttendees = getEventVerifiedAttendeeIds(eventDoc);
    if (verifiedAttendees.length) {
      completedEvents += 1;
      totalVerifiedAttendance += verifiedAttendees.length;
    }
    for (const discordId of verifiedAttendees) addCount(attendeeCounts, discordId);
    for (const discordId of eventDoc.helpers || []) addCount(helperCounts, discordId);
  }

  const averageAttendance = completedEvents
    ? Math.round((totalVerifiedAttendance / completedEvents) * 10) / 10
    : 0;

  return new EmbedBuilder()
    .setColor(0x27ae60)
    .setTitle("Human Resources Dashboard")
    .setDescription(`Event and community activity summary for the last **${days} day${Number(days) === 1 ? "" : "s"}**.`)
    .addFields(
      { name: "Events", value: [
        `Created/Tracked: **${events.length}**`,
        `Live/Completed With Attendance: **${completedEvents}**`,
        `Average Verified Attendance: **${averageAttendance}**`,
        `Awaiting Recap: **${missingRecaps.length}**`,
      ].join("\n"), inline: true },
      { name: "Community Work", value: [
        `Announcements Posted: **${announcements}**`,
        `Feedback Submissions: **${feedbackSubmissions}**`,
        `Open Feedback Items: **${openFeedbackSubmissions}**`,
        `Feedback Polls Created: **${feedbackPolls}**`,
        `Event Ideas Reviewed: **${eventIdeasReviewed}**`,
      ].join("\n"), inline: true },
      { name: "Status Breakdown", value: Object.entries(statusCounts).length
        ? Object.entries(statusCounts).map(([status, count]) => `${formatEventStatus(status)}: **${count}**`).join("\n")
        : "No events in this window.", inline: true },
      { name: "Top Verified Attendees", value: formatTopDiscordCounts(attendeeCounts), inline: false },
      { name: "Top Helpers", value: formatTopDiscordCounts(helperCounts), inline: false },
      { name: "Upcoming Events", value: upcoming.length
        ? upcoming.map(eventDoc => `**${eventDoc.name}** - ${eventDoc.scheduledAt ? `<t:${Math.floor(new Date(eventDoc.scheduledAt).getTime() / 1000)}:F>` : `${eventDoc.date} ${eventDoc.time}`} (${eventDoc.eventId})`).join("\n")
        : "No upcoming scheduled events.", inline: false },
      { name: "Missing Recaps", value: missingRecaps.length
        ? missingRecaps.map(eventDoc => `**${eventDoc.name}** (${eventDoc.eventId}) - ended ${eventDoc.activeEndsAt ? `<t:${Math.floor(new Date(eventDoc.activeEndsAt).getTime() / 1000)}:R>` : "recently"}`).join("\n")
        : "No missing recaps.", inline: false },
    )
    .setTimestamp();
}

