async function handleCampaignCommand(interaction) {
  const subcommand = interaction.options.getSubcommand();
  const context = await getBoardSystemContext(interaction);
  if (!hasMarketingAccess(context, "approve")) {
    return interaction.editReply("Only Public Relations Department+ may manage campaigns.");
  }

  if (subcommand === "create") {
    const campaignDoc = await MarketingCampaign.create({
      campaignId: createOperationalId("CAMP"),
      createdByDiscordId: interaction.user.id,
      createdByTag: interaction.user.tag,
      title: interaction.options.getString("title", true),
      goal: interaction.options.getString("goal", true),
      audience: interaction.options.getString("audience") || "General community",
      platforms: interaction.options.getString("platforms") || "Discord / social media",
      assetsNeeded: interaction.options.getString("assets_needed") || "Not specified",
      ownerDiscordId: interaction.options.getUser("owner")?.id || null,
      brief: interaction.options.getString("brief") || null,
      startDate: interaction.options.getString("start_date", true),
      endDate: interaction.options.getString("end_date") || "Not set",
    });
    const channel = await fetchTextChannel(interaction.guild, SWEETSIEZ_STRUCTURE_CONFIG.CHANNELS.MARKETING_PLANNING);
    if (!channel) return interaction.editReply("Campaign saved, but I could not reach the marketing planning channel.");
    const message = await channel.send({
      embeds: [buildMarketingCampaignEmbed(campaignDoc)],
      allowedMentions: { parse: [] },
    });
    campaignDoc.channelId = channel.id;
    campaignDoc.messageId = message.id;
    await campaignDoc.save();
    await logBoardContribution({
      board: "marketing",
      activityType: "campaign_created",
      discordId: interaction.user.id,
      sourceType: "marketing_campaign",
      sourceId: campaignDoc.campaignId,
      summary: `Created campaign: ${campaignDoc.title}.`,
      loggedBy: interaction.user,
    }).catch(() => {});
    return interaction.editReply(`Marketing campaign created. Campaign ID: ${campaignDoc.campaignId}`);
  }

  const campaignId = interaction.options.getString("campaign_id", true);
  let campaignDoc = await MarketingCampaign.findOne({ campaignId });
  if (!campaignDoc) return interaction.editReply("That marketing campaign could not be found.");

  if (subcommand === "item") {
    const owner = interaction.options.getUser("owner");
    const item = {
      itemId: createOperationalId("CITEM"),
      label: interaction.options.getString("label", true),
      type: interaction.options.getString("type", true),
      dueDate: interaction.options.getString("due_date") || null,
      ownerDiscordId: owner?.id || null,
      status: "planned",
      createdByDiscordId: interaction.user.id,
      createdAt: new Date(),
    };
    campaignDoc = await MarketingCampaign.findOneAndUpdate(
      { campaignId },
      { $push: { items: item }, $set: { updatedAt: new Date() } },
      { new: true },
    );
    if (owner) {
      await logBoardContribution({
        board: "marketing",
        activityType: "campaign_item_assigned",
        discordId: owner.id,
        sourceType: "marketing_campaign",
        sourceId: campaignId,
        summary: `Assigned campaign item "${item.label}" for ${campaignDoc.title}.`,
        loggedBy: interaction.user,
      }).catch(() => {});
    }
  } else if (subcommand === "itemstatus") {
    const index = interaction.options.getInteger("item_number", true) - 1;
    const status = interaction.options.getString("status", true);
    if (!campaignDoc.items?.[index]) return interaction.editReply("That campaign item number does not exist.");
    campaignDoc.items[index].status = status;
    campaignDoc.items[index].updatedByDiscordId = interaction.user.id;
    campaignDoc.items[index].updatedAt = new Date();
    campaignDoc.markModified("items");
    campaignDoc.updatedAt = new Date();
    await campaignDoc.save();
    const ownerId = campaignDoc.items[index].ownerDiscordId || interaction.user.id;
    if (status === "completed") {
      await logBoardContribution({
        board: "marketing",
        activityType: "campaign_item_completed",
        discordId: ownerId,
        sourceType: "marketing_campaign",
        sourceId: campaignId,
        summary: `Completed campaign item "${campaignDoc.items[index].label}" for ${campaignDoc.title}.`,
        loggedBy: interaction.user,
      }).catch(() => {});
    }
  } else if (subcommand === "status") {
    campaignDoc.status = interaction.options.getString("status", true);
    campaignDoc.recap = interaction.options.getString("recap") || campaignDoc.recap;
    campaignDoc.updatedAt = new Date();
    await campaignDoc.save();
    await logBoardContribution({
      board: "marketing",
      activityType: "campaign_status_updated",
      discordId: interaction.user.id,
      sourceType: "marketing_campaign",
      sourceId: campaignId,
      summary: `Updated campaign ${campaignDoc.title} to ${campaignDoc.status}.`,
      loggedBy: interaction.user,
    }).catch(() => {});
  } else if (subcommand !== "summary") {
    return interaction.editReply("Unknown campaign action.");
  }

  await editStoredMessage(campaignDoc.channelId, campaignDoc.messageId, {
    embeds: [buildMarketingCampaignEmbed(campaignDoc)],
  });
  return interaction.editReply({ content: `Campaign ${campaignId} updated.`, embeds: [buildMarketingCampaignEmbed(campaignDoc)] });
}

