async function handleMarketingLibraryCommand(interaction) {
  const subcommand = interaction.options.getSubcommand();
  const context = await getBoardSystemContext(interaction);
  if (!hasMarketingAccess(context, "approve")) {
    return interaction.editReply("Only Public Relations Department+ may manage the Public Relations library.");
  }

  if (subcommand === "add") {
    const tags = String(interaction.options.getString("tags") || "")
      .split(",")
      .map(tag => tag.trim().toLowerCase())
      .filter(Boolean)
      .slice(0, 10);
    const item = await MarketingLibraryItem.create({
      libraryId: createOperationalId("LIB"),
      title: interaction.options.getString("title", true),
      category: interaction.options.getString("category", true),
      content: interaction.options.getString("content", true),
      tags,
      sourceLink: interaction.options.getString("source_link") || null,
      createdByDiscordId: interaction.user.id,
      createdByTag: interaction.user.tag,
    });
    await logBoardContribution({
      board: "marketing",
      activityType: "library_item_added",
      discordId: interaction.user.id,
      sourceType: "marketing_library",
      sourceId: item.libraryId,
      summary: `Added Marketing library item: ${item.title}.`,
      loggedBy: interaction.user,
    }).catch(() => {});
    return interaction.editReply({ content: `Marketing library item added. Library ID: ${item.libraryId}`, embeds: [buildMarketingLibraryEmbed(item)] });
  }

  if (subcommand === "archive") {
    const libraryId = interaction.options.getString("library_id", true);
    const item = await MarketingLibraryItem.findOneAndUpdate(
      { libraryId },
      { $set: { status: "archived", updatedAt: new Date() } },
      { new: true },
    );
    if (!item) return interaction.editReply("That Public Relations library item could not be found.");
    return interaction.editReply({ content: `Marketing library item ${libraryId} archived.`, embeds: [buildMarketingLibraryEmbed(item)] });
  }

  const query = interaction.options.getString("query") || "";
  const category = interaction.options.getString("category");
  const mongoQuery = { status: "active" };
  if (category) mongoQuery.category = category;
  if (query) {
    mongoQuery.$or = [
      { title: { $regex: query, $options: "i" } },
      { content: { $regex: query, $options: "i" } },
      { tags: { $regex: query.toLowerCase(), $options: "i" } },
    ];
  }
  const items = await MarketingLibraryItem.find(mongoQuery).sort({ updatedAt: -1 }).limit(10).lean();
  return interaction.editReply({
    embeds: [
      new EmbedBuilder()
        .setColor(0xff7f6e)
        .setTitle("Public Relations Library")
        .setDescription(items.length
          ? items.map(item => `**${item.title}** (${item.libraryId}) - ${formatMarketingStatus(item.category)} - ${(item.tags || []).join(", ") || "no tags"}`).join("\n")
          : "No active library items found.")
        .setTimestamp(),
    ],
  });
}

async function handleRepurposeCommand(interaction) {
  const subcommand = interaction.options.getSubcommand();
  const context = await getBoardSystemContext(interaction);
  const allowed = hasMarketingAccess(context, "approve") || hasOperationsAccess(context, "approve");
  if (!allowed) return interaction.editReply("Only Public Relations Department+ or Human Resources Department member+ may create repurposing pipelines.");

  if (subcommand === "event") {
    const eventId = interaction.options.getString("event_id", true);
    const eventDoc = await BoardEvent.findOne({ eventId });
    if (!eventDoc) return interaction.editReply("That event could not be found.");
    const created = await createMarketingPipelineFromEvent({
      guild: interaction.guild,
      eventDoc,
      actor: interaction.user,
    });
    return interaction.editReply(created.length
      ? `Event repurposing pipeline created: ${created.join(", ")}.`
      : "I could not post any Public Relations pipeline items.");
  }

  return interaction.editReply("Unknown repurposing action.");
}

function getMonthlyRecapWindow(rawMonth) {
  const now = new Date();
  let month = now.getMonth() + 1;
  let year = now.getFullYear();
  if (rawMonth) {
    const match = String(rawMonth).trim().match(/^(\d{1,2})\/(\d{4})$/);
    if (!match) return null;
    month = Number(match[1]);
    year = Number(match[2]);
    if (month < 1 || month > 12) return null;
  }
  return {
    start: new Date(year, month - 1, 1),
    end: new Date(year, month, 1),
    label: `${String(month).padStart(2, "0")}/${year}`,
  };
}

function formatTopContributors(contributions) {
  const counts = new Map();
  for (const item of contributions) {
    counts.set(item.discordId, (counts.get(item.discordId) || 0) + Number(item.amount || 1));
  }
  const leaders = [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 5);
  return leaders.length ? leaders.map(([id, count]) => `<@${id}> - ${count}`).join("\n") : "No tracked contributions.";
}

async function handleBoardRecapCommand(interaction) {
  const board = interaction.options.getString("board", true);
  const context = await getBoardSystemContext(interaction);
  const allowed = board === "operations"
    ? hasOperationsAccess(context, "approve")
    : board === "moderation"
      ? hasModerationAccess(context, "approve")
      : hasMarketingAccess(context, "approve");
  if (!allowed) return interaction.editReply("You do not have access to generate that board recap.");

  const window = getMonthlyRecapWindow(interaction.options.getString("month"));
  if (!window) return interaction.editReply("Use month as MM/YYYY, like 07/2026.");

  const contributions = await BoardContribution.find({
    board,
    createdAt: { $gte: window.start, $lt: window.end },
  }).lean();

  const embed = new EmbedBuilder()
    .setColor(board === "operations" ? 0x27ae60 : board === "moderation" ? 0x4e56c9 : 0xeb5757)
    .setTitle(`${board === "operations" ? "Human Resources" : board === "moderation" ? "Discord Moderation" : "Public Relations"} Recap - ${window.label}`)
    .addFields(
      { name: "Top Contributors", value: formatTopContributors(contributions), inline: false },
      { name: "Tracked Contributions", value: String(contributions.length), inline: true },
    )
    .setTimestamp();

  if (board === "operations") {
    const events = await BoardEvent.find({ createdAt: { $gte: window.start, $lt: window.end } }).lean();
    const completed = events.filter(event => event.status === "completed");
    const avgAttendance = completed.length
      ? Math.round(completed.reduce((total, event) => total + (event.attendees?.length || 0), 0) / completed.length)
      : 0;
    const ideas = await EventIdea.countDocuments({ createdAt: { $gte: window.start, $lt: window.end } });
    embed.addFields(
      { name: "Events Created", value: String(events.length), inline: true },
      { name: "Events Completed", value: String(completed.length), inline: true },
      { name: "Average Attendance", value: String(avgAttendance), inline: true },
      { name: "Event Ideas Submitted", value: String(ideas), inline: true },
    );
  } else {
    const announcements = await AnnouncementRequest.countDocuments({ status: "posted", createdAt: { $gte: window.start, $lt: window.end } });
    const polls = await CommunityFeedbackPoll.countDocuments({ createdAt: { $gte: window.start, $lt: window.end } });
    const content = await MarketingContent.find({ createdAt: { $gte: window.start, $lt: window.end } }).lean();
    const posted = content.filter(item => item.status === "posted");
    const filming = await FilmingSession.find({ createdAt: { $gte: window.start, $lt: window.end } }).lean();
    const graphicsCompleted = await GraphicsRequest.countDocuments({ status: "completed", updatedAt: { $gte: window.start, $lt: window.end } });
    const campaigns = await MarketingCampaign.countDocuments({ updatedAt: { $gte: window.start, $lt: window.end } });
    const newsletters = await NewsletterDraft.countDocuments({ updatedAt: { $gte: window.start, $lt: window.end } });
    const views = posted.reduce((total, item) => total + Number(item.performance?.views || 0), 0);
    const engagements = posted.reduce((total, item) =>
      total
      + Number(item.performance?.likes || 0)
      + Number(item.performance?.comments || 0)
      + Number(item.performance?.shares || 0)
      + Number(item.performance?.saves || 0)
      + Number(item.performance?.clicks || 0), 0);
    embed.addFields(
      { name: "Content Items", value: String(content.length), inline: true },
      { name: "Posts Logged", value: String(posted.length), inline: true },
      { name: "Filming Sessions", value: String(filming.length), inline: true },
      { name: "Graphics Completed", value: String(graphicsCompleted), inline: true },
      { name: "Campaigns Updated", value: String(campaigns), inline: true },
      { name: "Newsletter Drafts", value: String(newsletters), inline: true },
      { name: "Views Logged", value: String(views), inline: true },
      { name: "Engagements Logged", value: String(engagements), inline: true },
      { name: "Announcements Posted", value: String(announcements), inline: true },
      { name: "Feedback Polls", value: String(polls), inline: true },
    );
  }

  return interaction.editReply({ embeds: [embed] });
}

async function setStaffProfileInactivityTag(discordId, active) {
  const profile = await StaffProfile.findOne({ discordId }).lean().catch(() => null);
  if (profile) {
    const forumChannel = await getManagerSystemForum(profile.forumChannelId);
    const thread = forumChannel
      ? await fetchForumThread(forumChannel, profile.threadId)
      : null;
    if (forumChannel && thread) {
      if (active) {
        await ensureForumTag(forumChannel, STAFF_PROFILE_CONFIG.INACTIVITY_TAG);
        await mergeForumThreadTags(thread, forumChannel, [STAFF_PROFILE_CONFIG.INACTIVITY_TAG]);
      } else {
        await removeForumThreadTags(thread, forumChannel, [STAFF_PROFILE_CONFIG.INACTIVITY_TAG]);
      }
      return true;
    }
  }

  const managerProfile = await ManagerProfile.findOne({ discordId }).lean().catch(() => null);
  if (managerProfile) {
    const forumChannel = await getManagerSystemForum(STAFF_PROFILE_CONFIG.SHIFT_LEAD_FORUM_ID);
    const thread = forumChannel
      ? await fetchForumThread(forumChannel, managerProfile.threadId)
      : null;
    if (forumChannel && thread) {
      if (active) {
        await mergeForumThreadTags(thread, forumChannel, [STAFF_PROFILE_CONFIG.INACTIVITY_TAG]);
      } else {
        await removeForumThreadTags(thread, forumChannel, [STAFF_PROFILE_CONFIG.INACTIVITY_TAG]);
      }
      return true;
    }
  }
  return false;
}

function getRankDisplayNameFromBind(rank) {
  const roles = ROLE_BINDS[Number(rank)] || [];
  return roles.find(roleName => !STAFF_DEPARTURE_GENERIC_ROLE_NAMES.has(roleName)) || `Rank ${rank}`;
}

function inferStaffRankFromDiscordRoles(member) {
  if (!member?.roles?.cache) return null;
  let best = null;
  for (const [rankValue, roleNames] of Object.entries(ROLE_BINDS)) {
    // Retired ranks share their role names with the ranks they merged into (16 Executive is the
    // same role as 13 Executive), and the highest match used to win — so Executives resolved to
    // the retired 16 and Developers to 20. Resolve to the live rank first.
    const declaredRank = Number(rankValue);
    const rank = getMigrationTargetRank(declaredRank) ?? declaredRank;
    if (rank < MANAGER_SYSTEM_CONFIG.SHIFT_LEAD_RANK) continue;
    const rankRoleName = roleNames.find(roleName => !STAFF_DEPARTURE_GENERIC_ROLE_NAMES.has(roleName));
    if (!rankRoleName) continue;
    const hasRankRole = member.roles.cache.some(role => role.name === rankRoleName);
    if (hasRankRole && (!best || rank > best.rank)) {
      best = { rank, rankName: rankRoleName, source: "discord_roles" };
    }
  }
  return best;
}

async function getStaffDepartureContext(discordId, member = null) {
  const [staffProfile, managerProfile] = await Promise.all([
    StaffProfile.findOne({ discordId }).lean().catch(() => null),
    ManagerProfile.findOne({ discordId }).lean().catch(() => null),
  ]);

  const roleContext = inferStaffRankFromDiscordRoles(member);
  if (roleContext) {
    const alreadyClosed = roleContext.rank === MANAGER_SYSTEM_CONFIG.SHIFT_LEAD_RANK
      ? Boolean(managerProfile && managerProfile.status !== "active")
      : Boolean(staffProfile && staffProfile.status !== "employed");
    return { ...roleContext, staffProfile, managerProfile, alreadyClosed };
  }

  if (staffProfile?.status === "employed" && Number(staffProfile.rankEmployedAs) >= MANAGER_SYSTEM_CONFIG.SHIFT_LEAD_RANK) {
    return {
      rank: Number(staffProfile.rankEmployedAs),
      rankName: staffProfile.rankNameEmployedAs || getRankDisplayNameFromBind(staffProfile.rankEmployedAs),
      source: "staff_profile",
      staffProfile,
      managerProfile,
      alreadyClosed: false,
    };
  }

  if (managerProfile?.status === "active") {
    return {
      rank: MANAGER_SYSTEM_CONFIG.SHIFT_LEAD_RANK,
      rankName: "Shift Lead",
      source: "manager_profile",
      staffProfile,
      managerProfile,
      alreadyClosed: false,
    };
  }

  return {
    rank: 0,
    rankName: "Unknown",
    source: "none",
    staffProfile,
    managerProfile,
    alreadyClosed: Boolean(
      staffProfile && staffProfile.status !== "employed" ||
      managerProfile && managerProfile.status !== "active"
    ),
  };
}

async function logAutomaticStaffDeparture({
  discordId,
  robloxUsername,
  robloxUserId,
  oldRank,
  oldRankName,
  newRankName,
  trigger,
  reason,
  evidence,
}) {
  const threadData = await getOrCreatePersonnelThread(robloxUsername, robloxUserId, oldRank).catch(error => {
    console.error(`Could not access staff profile for automatic departure (${robloxUsername}):`, error.message);
    return null;
  });
  if (!threadData?.thread) return null;

  const { thread, forumChannel } = threadData;
  if (thread.archived) await thread.setArchived(false).catch(() => {});
  if (thread.locked) await thread.setLocked(false).catch(() => {});

  const embed = new EmbedBuilder()
    .setColor(0xff0000)
    .setTitle("Automatic Staff Termination")
    .setDescription(reason)
    .addFields(
      { name: "Staff Member", value: `<@${discordId}> (${discordId})`, inline: true },
      { name: "Roblox Username", value: `${robloxUsername} (${robloxUserId})`, inline: true },
      { name: "Trigger", value: trigger, inline: true },
      { name: "Old Rank", value: `${oldRankName || getRankDisplayNameFromBind(oldRank)} (${oldRank})`, inline: true },
      { name: "New Rank", value: newRankName || "N/A", inline: true },
      { name: "Evidence / Detection", value: truncateForDiscord(evidence || "Automatic departure monitor"), inline: false },
      { name: "Processed By", value: `${client.user?.tag || "Sweetsiez Assistant"} (Automatic)`, inline: true },
    )
    .setTimestamp();

  await thread.send({ embeds: [embed], allowedMentions: { users: [discordId] } });

  if (forumChannel) {
    const terminatedTag = await ensureForumTag(forumChannel, "Terminated");
    if (terminatedTag) await thread.setAppliedTags([terminatedTag.id]).catch(() => {});
  }

  await Promise.all([
    StaffProfile.updateOne(
      { discordId },
      { $set: { status: "terminated", updatedAt: new Date() } },
    ).catch(() => {}),
    ManagerProfile.updateOne(
      { discordId },
      { $set: { status: "terminated", updatedAt: new Date() } },
    ).catch(() => {}),
  ]);

  await thread.setLocked(true, "Automatic staff termination").catch(() => {});
  await thread.setArchived(true, "Automatic staff termination").catch(() => {});
  return thread;
}

async function rankRobloxUserToSupporter(userId) {
  const supporterRole = await resolveGroupRoleByRank(1);
  if (!supporterRole) {
    return { ok: false, role: null, reason: "Sweetsiez Supporter rank could not be found." };
  }
  const result = await applyRobloxRank({ userId, roleId: supporterRole.id });
  return { ok: result.ok, role: supporterRole, reason: result.ok ? null : (result.error || "Roblox rank update failed.") };
}

async function handleVerifiedStaffLeftRobloxGroup({ member, discordId, robloxUsername, robloxUserId, departureContext }) {
  if (!departureContext || Number(departureContext.rank || 0) < MANAGER_SYSTEM_CONFIG.SHIFT_LEAD_RANK) {
    return { processed: false, reason: "not_staff" };
  }
  if (departureContext.alreadyClosed) {
    return { processed: false, reason: "profile_already_closed" };
  }

  const thread = await logAutomaticStaffDeparture({
    discordId,
    robloxUsername,
    robloxUserId,
    oldRank: departureContext.rank,
    oldRankName: departureContext.rankName,
    newRankName: "Not in Roblox group",
    trigger: "Left Roblox Group",
    reason: "This staff member was automatically terminated because they left the Sweetsiez Roblox group while still linked in Discord.",
    evidence: `Detected during /updateall. Roblox membership lookup returned no Sweetsiez group membership. Source: ${departureContext.source}.`,
  });

  await sendEventLog(member.guild, "Automatic Staff Termination", 0xff0000, [
    { name: "Staff Member", value: `${member.user.tag} (${discordId})`, inline: true },
    { name: "Roblox Username", value: `${robloxUsername} (${robloxUserId})`, inline: true },
    { name: "Trigger", value: "Left Roblox Group", inline: true },
    { name: "Old Rank", value: `${departureContext.rankName} (${departureContext.rank})`, inline: true },
    { name: "Profile Log", value: thread ? `${thread}` : "Could not access profile thread", inline: false },
  ]).catch(() => {});

  return { processed: true, thread };
}

async function handleStaffLeftDiscord(member, executor = null) {
  if (!member || member.user?.bot) return { processed: false, reason: "invalid_member" };
  const robloxUsername = verifiedUsers.get(member.id);
  if (!robloxUsername) return { processed: false, reason: "not_verified" };

  const robloxUserId = await getRobloxUserId(robloxUsername).catch(() => null);
  if (!robloxUserId) return { processed: false, reason: "roblox_not_found" };

  const membership = await getMainGroupMembershipStatus(robloxUserId);
  if (!membership.ok) {
    await sendEventLog(member.guild, "Automatic Staff Departure Check Skipped", 0xffa500, [
      { name: "Member", value: `${member.user.tag} (${member.id})`, inline: true },
      { name: "Roblox Username", value: `${robloxUsername} (${robloxUserId})`, inline: true },
      { name: "Reason", value: "Roblox membership lookup failed, so no automatic rank change was made.", inline: false },
    ]).catch(() => {});
    return { processed: false, reason: "membership_check_failed" };
  }

  if (!membership.inGroup || Number(membership.rank || 0) < MANAGER_SYSTEM_CONFIG.SHIFT_LEAD_RANK) {
    return { processed: false, reason: "not_staff_in_group" };
  }

  const rankResult = await rankRobloxUserToSupporter(robloxUserId);
  if (!rankResult.ok) {
    await sendEventLog(member.guild, "Automatic Staff Rank Removal Failed", 0xff0000, [
      { name: "Member", value: `${member.user.tag} (${member.id})`, inline: true },
      { name: "Roblox Username", value: `${robloxUsername} (${robloxUserId})`, inline: true },
      { name: "Current Rank", value: `${membership.name} (${membership.rank})`, inline: true },
      { name: "Reason", value: rankResult.reason || "Unknown failure", inline: false },
    ]).catch(() => {});
    return { processed: false, reason: "rank_failed" };
  }

  const departureContext = await getStaffDepartureContext(member.id, member);
  let thread = null;
  if (!departureContext.alreadyClosed) {
    thread = await logAutomaticStaffDeparture({
      discordId: member.id,
      robloxUsername,
      robloxUserId,
      oldRank: membership.rank,
      oldRankName: membership.name,
      newRankName: `${rankResult.role.name} (${rankResult.role.rank})`,
      trigger: executor ? "Removed from Discord Server" : "Left Discord Server",
      reason: executor
        ? "This staff member was automatically terminated because they were removed from the Discord server while holding a staff rank in the Roblox group."
        : "This staff member was automatically terminated because they left the Discord server while holding a staff rank in the Roblox group.",
      evidence: executor
        ? `Detected by guildMemberRemove. Kicked/removed by ${executor.tag} (${executor.id}).`
        : "Detected by guildMemberRemove. No kick executor was found, so this appears to be a voluntary leave.",
    });
  }

  await sendEventLog(member.guild, "Automatic Staff Rank Removal", 0xff0000, [
    { name: "Member", value: `${member.user.tag} (${member.id})`, inline: true },
    { name: "Roblox Username", value: `${robloxUsername} (${robloxUserId})`, inline: true },
    { name: "Trigger", value: executor ? `Removed by ${executor.tag}` : "Left Discord", inline: true },
    { name: "Old Rank", value: `${membership.name} (${membership.rank})`, inline: true },
    { name: "New Rank", value: `${rankResult.role.name} (${rankResult.role.rank})`, inline: true },
    { name: "Profile Log", value: thread ? `${thread}` : (departureContext.alreadyClosed ? "Profile was already closed" : "Could not access profile thread"), inline: false },
  ]).catch(() => {});

  return { processed: true, thread };
}

async function getManagerPermission(discordId) {
  return withTimeout((async () => {
    const robloxUsername = verifiedUsers.get(discordId);
    if (!robloxUsername) {
      return { ok: false, rank: 0, robloxUsername: null, reason: "You must be verified to use Manager systems." };
    }
    const robloxUserId = await getRobloxUserId(robloxUsername).catch(() => null);
    const rankInfo = robloxUserId ? await getUserRankInGroup(robloxUserId).catch(() => null) : null;
    const rank = Number(rankInfo?.rank || 0);
    return {
      ok: rank >= MANAGER_SYSTEM_CONFIG.MANAGER_MIN_RANK,
      rank,
      rankInfo,
      robloxUsername,
      robloxUserId,
      reason: `Manager rank (${MANAGER_SYSTEM_CONFIG.MANAGER_MIN_RANK}) or higher is required.`,
    };
  })(), 12000, "Manager permission check");
}

async function getOrCreateManagerProfileThread({ discordId, robloxUsername, robloxUserId }) {
  const forumChannel = await getManagerSystemForum(MANAGER_SYSTEM_CONFIG.MANAGER_HUB_CHANNEL_ID);
  if (!forumChannel) {
    console.error("❌ Manager Hub forum is unavailable or is not a forum channel.");
    return null;
  }

  let profile = await ManagerProfile.findOne({ discordId }).catch(() => null);
  let thread = profile ? await fetchForumThread(forumChannel, profile.threadId) : null;
  if (!thread) thread = await findForumThreadByUsername(forumChannel, robloxUsername);
  const employedAt = profile?.createdAt || new Date();
  const discordUser = await client.users.fetch(discordId).catch(() => null);
  const discordIdentity = discordUser
    ? `${discordUser.tag} (<@${discordId}>)`
    : `<@${discordId}>`;
  const shiftLeadTag = await ensureForumTag(forumChannel, "Shift Lead");
  const employedTag = await ensureForumTag(
    forumChannel,
    STAFF_PROFILE_CONFIG.CURRENTLY_EMPLOYED_TAG,
  );
  if (!employedTag) {
    throw new Error(`The "${STAFF_PROFILE_CONFIG.CURRENTLY_EMPLOYED_TAG}" tag is required in Manager Hub.`);
  }
  const profileEmbed = new EmbedBuilder()
    .setColor(0xffb6c1)
    .setTitle("Staff Profile")
    .setDescription(
      [
        `**ROBLOX USERNAME:** ${robloxUsername}`,
        `**DISCORD USERNAME:** ${discordIdentity}`,
        `**DATE EMPLOYED:** ${formatAmericanDate(employedAt)}`,
        "**RANK EMPLOYED AS:** Shift Lead",
        "",
        "This is the official Manager Hub profile. Recommendations, observations, coaching notes, " +
          "inactivity notices, resignations, promotions, demotions, and other administrative records belong here.",
      ].join("\n"),
    )
    .setFooter({ text: "Use /hrlog to add official entries. Do not create duplicate profiles." })
    .setTimestamp();

  if (!thread) {
    thread = await forumChannel.threads.create({
      name: `${robloxUsername} | ${formatAmericanDate(employedAt)}`.slice(0, 100),
      appliedTags: [shiftLeadTag?.id, employedTag.id].filter(Boolean),
      message: {
        embeds: [profileEmbed],
        allowedMentions: { users: [discordId] },
      },
      reason: `Official Shift Lead profile for ${robloxUsername}`,
    });
  } else {
    if (thread.archived) await thread.setArchived(false).catch(() => {});
    if (thread.locked) await thread.setLocked(false).catch(() => {});
    const expectedName = `${robloxUsername} | ${formatAmericanDate(employedAt)}`.slice(0, 100);
    if (thread.name !== expectedName) await thread.setName(expectedName).catch(() => {});
    const starterMessage = await thread.fetchStarterMessage().catch(() => null);
    if (starterMessage) {
      await starterMessage.edit({
        content: null,
        embeds: [profileEmbed],
        allowedMentions: { users: [discordId] },
      }).catch(() => {});
    }
  }

  profile = await ManagerProfile.findOneAndUpdate(
    { discordId },
    {
      $set: {
        robloxUsername,
        robloxUsernameLower: robloxUsername.toLowerCase(),
        robloxUserId: String(robloxUserId),
        threadId: thread.id,
        status: "active",
        updatedAt: new Date(),
      },
      $setOnInsert: { createdAt: new Date() },
    },
    { upsert: true, new: true },
  );

  await mergeForumThreadTags(
    thread,
    forumChannel,
    ["Shift Lead", STAFF_PROFILE_CONFIG.CURRENTLY_EMPLOYED_TAG],
  );
  return { thread, forumChannel, profile };
}

