async function addManagerHubEntry({
  targetDiscordId,
  robloxUsername,
  robloxUserId,
  entryType,
  details,
  evidence,
  authorDiscordId,
  authorRobloxUsername,
}) {
  const entryConfig = MANAGER_LOG_TYPE_CONFIG[entryType];
  if (!entryConfig) throw new Error("Invalid Manager Hub entry type.");

  const threadData = await getOrCreateManagerProfileThread({
    discordId: targetDiscordId,
    robloxUsername,
    robloxUserId,
  });
  if (!threadData) throw new Error("Manager Hub profile could not be accessed.");

  const embed = new EmbedBuilder()
    .setColor(entryConfig.color)
    .setTitle(entryConfig.label)
    .setDescription(String(details).slice(0, 4000))
    .addFields(
      { name: "Shift Lead", value: `<@${targetDiscordId}> (${robloxUsername})`, inline: true },
      { name: "Logged By", value: `<@${authorDiscordId}> (${authorRobloxUsername})`, inline: true },
    )
    .setTimestamp();
  if (evidence) embed.addFields({ name: "Evidence / Reference", value: String(evidence).slice(0, 1024), inline: false });

  await threadData.thread.send({ embeds: [embed] });
  if (entryConfig.closeStatus) {
    await setForumThreadTags(threadData.thread, threadData.forumChannel, entryConfig.tags);
  } else {
    await mergeForumThreadTags(threadData.thread, threadData.forumChannel, entryConfig.tags);
  }

  if (entryConfig.closeStatus) {
    await ManagerProfile.updateOne(
      { discordId: targetDiscordId },
      { $set: { status: entryConfig.closeStatus, updatedAt: new Date() } },
    );
    await threadData.thread.setLocked(true).catch(() => {});
    await threadData.thread.setArchived(true).catch(() => {});
  }
  return threadData;
}

function addDaysToDateString(dateString, days) {
  const date = new Date(`${dateString}T12:00:00Z`);
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

function parseAmericanDateStrict(value) {
  const match = String(value || "").match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (!match) return null;
  const month = Number(match[1]);
  const day = Number(match[2]);
  const year = Number(match[3]);
  const date = new Date(year, month - 1, day);
  if (
    date.getFullYear() !== year ||
    date.getMonth() !== month - 1 ||
    date.getDate() !== day
  ) {
    return null;
  }
  return date;
}

function getRadarQualificationWindow(activity) {
  if (!activity?.dailyActivity) return null;
  const today = getEasternDateString();

  // Check a streak ending today first, then yesterday so a qualifying streak
  // is not lost when the scanner runs shortly after midnight.
  for (const endOffset of [0, -1]) {
    const endDate = addDaysToDateString(today, endOffset);
    const dates = [];
    const minutes = [];
    let qualifies = true;

    for (let offset = -(MANAGER_SYSTEM_CONFIG.RADAR_CONSECUTIVE_DAYS - 1); offset <= 0; offset++) {
      const date = addDaysToDateString(endDate, offset);
      const dayMinutes = Number(activity.dailyActivity[date] || 0);
      dates.push(date);
      minutes.push(dayMinutes);
      if (dayMinutes < MANAGER_SYSTEM_CONFIG.RADAR_MIN_DAILY_MINUTES) qualifies = false;
    }

    if (qualifies) return { dates, minutes };
  }
  return null;
}

function buildRadarControlRow(caseData) {
  const closed = ["not_ready", "promoted", "closed"].includes(caseData.status);
  const snoozed = caseData.status === "snoozed";
  return new ActionRowBuilder().addComponents(
    new ButtonBuilder()
      .setCustomId(`radar_observe_${caseData.discordId}`)
      .setLabel("Add Observation")
      .setStyle(ButtonStyle.Primary)
      .setDisabled(closed || snoozed),
    new ButtonBuilder()
      .setCustomId(`radar_recommend_${caseData.discordId}`)
      .setLabel("Recommend for Shift Lead")
      .setStyle(ButtonStyle.Success)
      .setDisabled(closed || snoozed || !!caseData.recommendedAt),
    new ButtonBuilder()
      .setCustomId(`radar_snooze_${caseData.discordId}`)
      .setLabel("Snooze for 14 Days")
      .setStyle(ButtonStyle.Secondary)
      .setDisabled(closed || snoozed || !!caseData.recommendedAt),
  );
}

async function updateRadarStarterControls(caseData, thread) {
  if (!thread) return;
  let starterMessage = null;
  if (caseData.starterMessageId) {
    starterMessage = await thread.messages.fetch(caseData.starterMessageId).catch(() => null);
  }
  if (!starterMessage) starterMessage = await thread.fetchStarterMessage().catch(() => null);
  if (!starterMessage) return;
  await starterMessage.edit({ components: [buildRadarControlRow(caseData)] }).catch(() => {});
  if (!caseData.starterMessageId) {
    caseData.starterMessageId = starterMessage.id;
    await caseData.save();
  }
}

async function getRadarThread(caseData) {
  const forumChannel = await getManagerSystemForum(MANAGER_SYSTEM_CONFIG.HSJ_RADAR_CHANNEL_ID);
  if (!forumChannel) return { forumChannel: null, thread: null };
  const thread = await fetchForumThread(forumChannel, caseData.threadId);
  return { forumChannel, thread };
}

function getDistinctRadarObserverIds(caseData) {
  return new Set(
    (caseData.observations || [])
      .filter(observation => observation.managerDiscordId !== caseData.recommendedByDiscordId)
      .map(observation => observation.managerDiscordId),
  );
}

async function maybeAnnounceRadarReady(caseData, thread) {
  if (!caseData.recommendedAt || caseData.readinessAnnouncedAt || !thread) return false;
  const distinctObservers = getDistinctRadarObserverIds(caseData);
  const observationReadyAt =
    new Date(caseData.recommendedAt).getTime() +
    MANAGER_SYSTEM_CONFIG.RADAR_OBSERVATION_DAYS * 24 * 60 * 60 * 1000;

  if (
    Date.now() < observationReadyAt ||
    distinctObservers.size < MANAGER_SYSTEM_CONFIG.RADAR_REQUIRED_DISTINCT_OBSERVERS
  ) {
    return false;
  }

  await thread.send({
    content: `<@&${MANAGER_SYSTEM_CONFIG.MANAGER_ROLE_ID}>`,
    embeds: [
      new EmbedBuilder()
        .setColor(0x2ecc71)
        .setTitle("Candidate Eligible for Vote Review")
        .setDescription(
          `**${caseData.robloxUsername}** has completed the five-day observation period and has observations from ` +
          `**${distinctObservers.size} different Managers**.\n\n` +
          "This does not automatically approve a promotion. Managers should review the full case before beginning a formal vote."
        )
        .setTimestamp(),
    ],
    allowedMentions: { roles: [MANAGER_SYSTEM_CONFIG.MANAGER_ROLE_ID] },
  });

  caseData.readinessAnnouncedAt = new Date();
  caseData.updatedAt = new Date();
  await caseData.save();
  return true;
}

async function createRadarCase({ discordId, robloxUsername, robloxUserId, qualification }) {
  const forumChannel = await getManagerSystemForum(MANAGER_SYSTEM_CONFIG.HSJ_RADAR_CHANNEL_ID);
  if (!forumChannel) throw new Error("HSJ Radar forum is unavailable or is not a forum channel.");

  const activityLines = qualification.dates
    .map((date, index) => `• **${date}:** ${qualification.minutes[index]} minutes`)
    .join("\n");
  const draftCase = {
    discordId,
    status: "watching",
    recommendedAt: null,
  };
  const radarTag = findForumTag(forumChannel, "Radar");
  const watchingTag = findForumTag(forumChannel, "Watching");

  const thread = await forumChannel.threads.create({
    name: `${robloxUsername} | HSJ Radar`.slice(0, 100),
    appliedTags: [radarTag?.id, watchingTag?.id].filter(Boolean),
    message: {
      content: `<@&${MANAGER_SYSTEM_CONFIG.MANAGER_ROLE_ID}>`,
      embeds: [
        new EmbedBuilder()
          .setColor(0xf1c40f)
          .setTitle(`Head Soda Jerk Radar — ${robloxUsername}`)
          .setDescription(
            "This candidate reached the activity threshold for scouting. This is only a signal and is not an automatic recommendation."
          )
          .addFields(
            { name: "Candidate", value: `<@${discordId}>`, inline: true },
            { name: "Roblox Username", value: robloxUsername, inline: true },
            { name: "Roblox User ID", value: `\`${robloxUserId}\``, inline: true },
            { name: "Qualifying Activity", value: activityLines, inline: false },
            {
              name: "Manager Review",
              value:
                "Evaluate professionalism, maturity, customer service, café knowledge, initiative, leadership ability, " +
                "conduct under pressure, and willingness to assist other staff.",
              inline: false,
            },
          )
          .setFooter({ text: "Two observations from different Managers are required before voting." })
          .setTimestamp(),
      ],
      components: [buildRadarControlRow(draftCase)],
      allowedMentions: { roles: [MANAGER_SYSTEM_CONFIG.MANAGER_ROLE_ID] },
    },
    reason: `HSJ Radar qualification for ${robloxUsername}`,
  });

  const starterMessage = await thread.fetchStarterMessage().catch(() => null);
  return HsjRadarCase.create({
    discordId,
    robloxUsername,
    robloxUsernameLower: robloxUsername.toLowerCase(),
    robloxUserId: String(robloxUserId),
    threadId: thread.id,
    starterMessageId: starterMessage?.id || null,
    status: "watching",
    qualifyingDates: qualification.dates,
    qualifyingMinutes: qualification.minutes,
  });
}

async function resumeSnoozedRadarCase(caseData, qualification) {
  const { forumChannel, thread } = await getRadarThread(caseData);
  if (!thread || !forumChannel) return false;
  if (thread.archived) await thread.setArchived(false).catch(() => {});
  if (thread.locked) await thread.setLocked(false).catch(() => {});

  caseData.status = caseData.recommendedAt ? "observing" : "watching";
  caseData.snoozedUntil = null;
  caseData.qualifyingDates = qualification.dates;
  caseData.qualifyingMinutes = qualification.minutes;
  caseData.updatedAt = new Date();
  await caseData.save();

  await setForumThreadTags(
    thread,
    forumChannel,
    caseData.recommendedAt ? ["Radar", "Recommended", "Observing"] : ["Radar", "Watching"],
  );
  await thread.send({
    embeds: [
      new EmbedBuilder()
        .setColor(0x3498db)
        .setTitle("Radar Case Resumed")
        .setDescription("The 14-day snooze period has ended and this candidate again meets the radar activity threshold.")
        .setTimestamp(),
    ],
  });
  await updateRadarStarterControls(caseData, thread);
  return true;
}

async function closeRadarCaseForRankChange(caseData, newRank) {
  if (["promoted", "not_ready", "closed"].includes(caseData.status)) return false;
  const { forumChannel, thread } = await getRadarThread(caseData);
  if (!thread || !forumChannel) return false;

  const promoted = newRank >= MANAGER_SYSTEM_CONFIG.SHIFT_LEAD_RANK;
  caseData.status = promoted ? "promoted" : "not_ready";
  caseData.updatedAt = new Date();
  await caseData.save();

  if (thread.archived) await thread.setArchived(false).catch(() => {});
  await thread.send({
    embeds: [
      new EmbedBuilder()
        .setColor(promoted ? 0x2ecc71 : 0xe67e22)
        .setTitle(promoted ? "Candidate Promoted" : "Candidate No Longer Eligible")
        .setDescription(
          promoted
            ? `**${caseData.robloxUsername}** is no longer a Head Soda Jerk and has advanced to rank ${newRank}. This radar case is now closed.`
            : `**${caseData.robloxUsername}** is no longer a Head Soda Jerk and is currently rank ${newRank}. This radar case is now closed.`
        )
        .setTimestamp(),
    ],
  });
  await setForumThreadTags(
    thread,
    forumChannel,
    promoted ? ["Promoted", "Closed"] : ["Not Ready", "Closed"],
  );
  await updateRadarStarterControls(caseData, thread);
  await thread.setLocked(true).catch(() => {});
  await thread.setArchived(true).catch(() => {});
  return true;
}

let hsjRadarScanRunning = false;
async function runHsjRadarScan(triggeredBy = "automatic") {
  if (hsjRadarScanRunning || mongoose.connection.readyState !== 1) {
    return { created: 0, resumed: 0, closed: 0, checked: 0, skipped: true };
  }
  hsjRadarScanRunning = true;
  const summary = { created: 0, resumed: 0, closed: 0, checked: 0, capped: 0, skipped: false };
  // The radar used to watch ~17 Head Soda Jerks; it now watches the whole Soda Jerk
  // rank (~95 members), so cap how many new cases one scan can open. Successive scans
  // (every 6h maintenance) work through the rest.
  const RADAR_MAX_NEW_CASES_PER_SCAN = 5;
  const canOpenRadarCase = () => summary.created < RADAR_MAX_NEW_CASES_PER_SCAN;

  try {
    for (const [usernameLower, activity] of activityData.entries()) {
      const qualification = getRadarQualificationWindow(activity);
      if (!qualification) continue;
      const discordId = findVerifiedDiscordIdByRobloxUsername(usernameLower);
      if (!discordId) continue;
      summary.checked++;

      const robloxUsername = verifiedUsers.get(discordId);
      const robloxUserId = await getRobloxUserId(robloxUsername).catch(() => null);
      const rankInfo = robloxUserId ? await getUserRankInGroup(robloxUserId).catch(() => null) : null;
      if (!rankInfo || rankInfo.rank !== MANAGER_SYSTEM_CONFIG.HEAD_SODA_JERK_RANK) continue;

      let caseData = await HsjRadarCase.findOne({ discordId });
      if (!caseData) {
        if (!canOpenRadarCase()) { summary.capped++; continue; }
        await createRadarCase({ discordId, robloxUsername, robloxUserId, qualification });
        summary.created++;
        continue;
      }

      if (["promoted", "not_ready", "closed"].includes(caseData.status)) {
        await HsjRadarCase.deleteOne({ _id: caseData._id });
        if (!canOpenRadarCase()) { summary.capped++; continue; }
        await createRadarCase({ discordId, robloxUsername, robloxUserId, qualification });
        summary.created++;
        continue;
      }

      if (
        caseData.robloxUsername !== robloxUsername ||
        String(caseData.robloxUserId) !== String(robloxUserId)
      ) {
        caseData.robloxUsername = robloxUsername;
        caseData.robloxUsernameLower = robloxUsername.toLowerCase();
        caseData.robloxUserId = String(robloxUserId);
        caseData.updatedAt = new Date();
        await caseData.save();
        const { thread } = await getRadarThread(caseData);
        if (thread) await thread.setName(`${robloxUsername} | HSJ Radar`.slice(0, 100)).catch(() => {});
      }

      const existingThreadData = await getRadarThread(caseData);
      if (!existingThreadData.thread && !["promoted", "not_ready", "closed"].includes(caseData.status)) {
        await HsjRadarCase.deleteOne({ _id: caseData._id });
        if (!canOpenRadarCase()) { summary.capped++; continue; }
        await createRadarCase({ discordId, robloxUsername, robloxUserId, qualification });
        summary.created++;
        continue;
      }

      if (
        caseData.status === "snoozed" &&
        caseData.snoozedUntil &&
        new Date(caseData.snoozedUntil).getTime() <= Date.now()
      ) {
        if (await resumeSnoozedRadarCase(caseData, qualification)) summary.resumed++;
      } else if (caseData.status === "observing") {
        const { thread } = await getRadarThread(caseData);
        await maybeAnnounceRadarReady(caseData, thread);
      }
    }

    const openCases = await HsjRadarCase.find({
      status: { $in: ["watching", "observing", "snoozed"] },
    });
    for (const caseData of openCases) {
      const rankInfo = await getUserRankInGroup(caseData.robloxUserId).catch(() => null);
      if (!rankInfo || rankInfo.rank === MANAGER_SYSTEM_CONFIG.HEAD_SODA_JERK_RANK) {
        if (caseData.status === "observing") {
          const { thread } = await getRadarThread(caseData);
          await maybeAnnounceRadarReady(caseData, thread);
        }
        continue;
      }
      if (await closeRadarCaseForRankChange(caseData, rankInfo.rank)) summary.closed++;
    }

    console.log(
      `✅ HSJ Radar scan (${triggeredBy}): ${summary.created} created, ${summary.resumed} resumed, ` +
      `${summary.closed} closed, ${summary.checked} qualifying activity records checked.`,
    );
    return summary;
  } catch (error) {
    console.error(`❌ HSJ Radar scan failed (${triggeredBy}):`, error);
    throw error;
  } finally {
    hsjRadarScanRunning = false;
  }
}

async function syncManagerHubProfiles(triggeredBy = "automatic") {
  if (mongoose.connection.readyState !== 1) return { createdOrUpdated: 0, skipped: true };
  const guild = client.guilds.cache.get(config.IA_GUILD_ID) || client.guilds.cache.first();
  if (!guild) return { createdOrUpdated: 0, skipped: true };

  await guild.members.fetch().catch(() => {});
  const shiftLeadRole = guild.roles.cache.find(role => role.name.toLowerCase() === "shift lead");
  if (!shiftLeadRole) {
    console.warn("⚠️ Manager Hub sync skipped: Shift Lead Discord role was not found.");
    return { createdOrUpdated: 0, skipped: true };
  }

  let createdOrUpdated = 0;
  for (const member of shiftLeadRole.members.values()) {
    const robloxUsername = verifiedUsers.get(member.id);
    if (!robloxUsername) continue;
    const robloxUserId = await getRobloxUserId(robloxUsername).catch(() => null);
    if (!robloxUserId) continue;
    await getOrCreateManagerProfileThread({
      discordId: member.id,
      robloxUsername,
      robloxUserId,
    });
    createdOrUpdated++;
  }
  console.log(`✅ Manager Hub sync (${triggeredBy}): ${createdOrUpdated} Shift Lead profile(s) checked.`);
  return { createdOrUpdated, skipped: false };
}

let managerMaintenanceRunning = false;
async function runManagerSystemMaintenance(triggeredBy = "automatic") {
  if (managerMaintenanceRunning || mongoose.connection.readyState !== 1) return;
  managerMaintenanceRunning = true;
  try {
    await syncManagerHubProfiles(triggeredBy);
    await runHsjRadarScan(triggeredBy);
  } catch (error) {
    console.error(`Manager system maintenance failed (${triggeredBy}):`, error);
  } finally {
    managerMaintenanceRunning = false;
  }
}

async function handleRadarButton(interaction) {
  const permission = await getManagerPermission(interaction.user.id);
  if (!permission.ok) {
    return interaction.reply({ content: `❌ ${permission.reason}`, flags: MessageFlags.Ephemeral });
  }

  const parts = interaction.customId.split("_");
  const action = parts[1];
  const targetDiscordId = parts[2];
  const caseData = await HsjRadarCase.findOne({ discordId: targetDiscordId });
  if (!caseData) {
    return interaction.reply({ content: "❌ This radar case could not be found.", flags: MessageFlags.Ephemeral });
  }
  if (["not_ready", "promoted", "closed"].includes(caseData.status)) {
    return interaction.reply({ content: "❌ This radar case is closed.", flags: MessageFlags.Ephemeral });
  }
  if (caseData.status === "snoozed" && action !== "snooze") {
    return interaction.reply({ content: "❌ This radar case is currently snoozed.", flags: MessageFlags.Ephemeral });
  }

  if (action === "observe" || action === "recommend") {
    const { ModalBuilder, TextInputBuilder, TextInputStyle } = require("discord.js");
    const modal = new ModalBuilder()
      .setCustomId(`radar_${action}_modal_${targetDiscordId}`)
      .setTitle(action === "observe" ? "Add Candidate Observation" : "Recommend for Shift Lead");
    modal.addComponents(
      new ActionRowBuilder().addComponents(
        new TextInputBuilder()
          .setCustomId(action === "observe" ? "observation" : "recommendation_reason")
          .setLabel(action === "observe" ? "Observation" : "Reason for recommendation")
          .setStyle(TextInputStyle.Paragraph)
          .setMinLength(20)
          .setMaxLength(1000)
          .setRequired(true),
      ),
    );
    return interaction.showModal(modal);
  }

  if (action === "snooze") {
    if (!interaction.deferred && !interaction.replied) {
      await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
    }
    caseData.status = "snoozed";
    caseData.snoozedUntil = new Date(
      Date.now() + MANAGER_SYSTEM_CONFIG.RADAR_SNOOZE_DAYS * 24 * 60 * 60 * 1000,
    );
    caseData.updatedAt = new Date();
    await caseData.save();

    const { forumChannel, thread } = await getRadarThread(caseData);
    if (thread && forumChannel) {
      await thread.send({
        embeds: [
          new EmbedBuilder()
            .setColor(0x95a5a6)
            .setTitle("Radar Case Snoozed")
            .setDescription(
              `This case was snoozed for 14 days by <@${interaction.user.id}>. It may automatically resume after ` +
              `<t:${Math.floor(caseData.snoozedUntil.getTime() / 1000)}:F> if the candidate still qualifies.`
            )
            .setTimestamp(),
        ],
      });
      await setForumThreadTags(thread, forumChannel, ["Radar", "Snoozed"]);
      await updateRadarStarterControls(caseData, thread);
      await thread.setArchived(true).catch(() => {});
    }
    return interaction.editReply("✅ This radar case has been snoozed for 14 days.");
  }
}

async function handleRadarModal(interaction) {
  const permission = await getManagerPermission(interaction.user.id);
  if (!permission.ok) {
    return interaction.reply({ content: `❌ ${permission.reason}`, flags: MessageFlags.Ephemeral });
  }

  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }
  const parts = interaction.customId.split("_");
  const action = parts[1];
  const targetDiscordId = parts[3];
  const caseData = await HsjRadarCase.findOne({ discordId: targetDiscordId });
  if (!caseData) return interaction.editReply("❌ This radar case could not be found.");

  const { forumChannel, thread } = await getRadarThread(caseData);
  if (!thread || !forumChannel) return interaction.editReply("❌ The radar thread could not be accessed.");
  if (thread.archived) await thread.setArchived(false).catch(() => {});

  if (action === "observe") {
    if (caseData.recommendedByDiscordId === interaction.user.id) {
      return interaction.editReply(
        "❌ The Manager who submitted the formal recommendation cannot also submit an observation for this candidate.",
      );
    }

    const text = interaction.fields.getTextInputValue("observation").trim();
    caseData.observations.push({
      managerDiscordId: interaction.user.id,
      managerRobloxUsername: permission.robloxUsername,
      text,
      createdAt: new Date(),
    });
    caseData.markModified("observations");
    caseData.updatedAt = new Date();
    await caseData.save();

    const distinctObserverCount = getDistinctRadarObserverIds(caseData).size;
    await thread.send({
      embeds: [
        new EmbedBuilder()
          .setColor(0x3498db)
          .setTitle("Candidate Observation")
          .setDescription(text)
          .addFields(
            { name: "Observer", value: `<@${interaction.user.id}> (${permission.robloxUsername})`, inline: true },
            {
              name: "Distinct Managers",
              value: `${distinctObserverCount}/${MANAGER_SYSTEM_CONFIG.RADAR_REQUIRED_DISTINCT_OBSERVERS}`,
              inline: true,
            },
          )
          .setTimestamp(),
      ],
    });
    await setForumThreadTags(
      thread,
      forumChannel,
      caseData.recommendedAt ? ["Radar", "Recommended", "Observing"] : ["Radar", "Watching"],
    );
    await logBoardContribution({
      board: "operations",
      activityType: "hsj_radar_observation",
      discordId: interaction.user.id,
      sourceType: "hsj_radar",
      sourceId: caseData.caseId || caseData.discordId,
      summary: `Added a candidate observation for ${caseData.robloxUsername}.`,
      loggedBy: interaction.user,
    }).catch(() => {});
    await maybeAnnounceRadarReady(caseData, thread);
    return interaction.editReply("✅ Your observation was added to the candidate's radar case.");
  }

  if (action === "recommend") {
    if (caseData.recommendedAt) {
      return interaction.editReply("❌ This candidate has already been formally recommended.");
    }
    const reason = interaction.fields.getTextInputValue("recommendation_reason").trim();
    caseData.status = "observing";
    caseData.recommendedAt = new Date();
    caseData.recommendedByDiscordId = interaction.user.id;
    caseData.recommendedByRobloxUsername = permission.robloxUsername;
    caseData.recommendationReason = reason;
    caseData.snoozedUntil = null;
    caseData.updatedAt = new Date();
    await caseData.save();

    await thread.send({
      content: `<@&${MANAGER_SYSTEM_CONFIG.MANAGER_ROLE_ID}>`,
      embeds: [
        new EmbedBuilder()
          .setColor(0x2ecc71)
          .setTitle("Formal Shift Lead Recommendation")
          .setDescription(reason)
          .addFields(
            { name: "Recommended By", value: `<@${interaction.user.id}> (${permission.robloxUsername})`, inline: true },
            {
              name: "Observation Period",
              value:
                `Begins now and lasts at least ${MANAGER_SYSTEM_CONFIG.RADAR_OBSERVATION_DAYS} days. ` +
                `${MANAGER_SYSTEM_CONFIG.RADAR_REQUIRED_DISTINCT_OBSERVERS} observations from different Managers are required before voting.`,
              inline: false,
            },
          )
          .setTimestamp(),
      ],
      allowedMentions: { roles: [MANAGER_SYSTEM_CONFIG.MANAGER_ROLE_ID] },
    });
    await setForumThreadTags(thread, forumChannel, ["Radar", "Recommended", "Observing"]);
    await updateRadarStarterControls(caseData, thread);
    await logBoardContribution({
      board: "operations",
      activityType: "hsj_radar_recommendation",
      discordId: interaction.user.id,
      sourceType: "hsj_radar",
      sourceId: caseData.caseId || caseData.discordId,
      summary: `Started a formal Shift Lead recommendation for ${caseData.robloxUsername}.`,
      loggedBy: interaction.user,
    }).catch(() => {});
    return interaction.editReply("✅ The formal five-day observation period has begun.");
  }
}

async function sendBanSystemPanel(channel) {
  if (!channel) {
    console.error('ERROR: Ban system channel is null or undefined.');
    return;
  }
  try {
    const embed = new EmbedBuilder()
      .setColor(0xff0000)
      .setTitle('🔨 Sweetsiez Ban System')
      .setDescription(
        '**Welcome to the centralized ban system.**\n\n' +
        'Use the buttons below to issue different types of bans. Each button will open a form where you can provide details.\n\n' +
        '**Ban Types:**\n' +
        '🚫 **Discord Ban** - Ban from Discord server\n' +
        '🔨 **Permanent Ban** - Permanent ban from a game\n' +
        '⛔ **Blacklist** - Ban from all Sweetsiez Facilities\n\n' +
        '⚠️ All bans are logged.'
      )
      .setFooter({ text: 'Ensure you have valid evidence before issuing any ban' })
      .setTimestamp();

    const row = new ActionRowBuilder()
      .addComponents(
        new ButtonBuilder()
          .setCustomId('ban_discord')
          .setLabel('Discord Ban')
          .setEmoji('🚫')
          .setStyle(ButtonStyle.Danger),
        new ButtonBuilder()
          .setCustomId('ban_permanent')
          .setLabel('Permanent Ban')
          .setEmoji('🔨')
          .setStyle(ButtonStyle.Danger),
        new ButtonBuilder()
          .setCustomId('ban_blacklist')
          .setLabel('Blacklist')
          .setEmoji('⛔')
          .setStyle(ButtonStyle.Danger)
      );

    await channel.send({ embeds: [embed], components: [row] });
    console.log(`✅ Ban system panel sent to #${channel.name}`);
  } catch (error) {
    console.error(`ERROR sending ban system panel to channel ${channel.id}:`, error);
    await sendEventLog(channel.guild, '❌ Send Ban System Panel Error', 0xff0000, [
      { name: 'Channel ID', value: channel.id, inline: false },
      { name: 'Error', value: error.message?.substring(0, 1024) || 'No message', inline: false }
    ]).catch(console.error);
  }
}

function normalizeTicketState(docOrTicket, threadIdOverride = null) {
  const threadId = docOrTicket.threadId || threadIdOverride;
  const createdAt = docOrTicket.createdAt ? new Date(docOrTicket.createdAt) : new Date();
  const lastMessageAt = docOrTicket.lastMessageAt ? new Date(docOrTicket.lastMessageAt) : createdAt;

  return {
    threadId,
    userId: docOrTicket.userId,
    category: docOrTicket.category,
    claimedBy: docOrTicket.claimedBy || null,
    createdAt,
    lastMessageAt,
    warnedForInactivity: !!docOrTicket.warnedForInactivity,
    closed: !!docOrTicket.closed,
  };
}

async function getActiveTicket(threadId) {
  const cached = activeTickets.get(threadId);
  if (cached && !cached.closed) return cached;
  if (mongoose.connection.readyState !== 1) return null;

  const doc = await Ticket.findOne({ threadId, closed: false }).lean().catch(error => {
    console.error('Error loading ticket from MongoDB:', error.message);
    return null;
  });
  if (!doc) return null;

  const ticket = normalizeTicketState(doc);
  activeTickets.set(threadId, ticket);
  return ticket;
}

async function touchTicketActivity(threadId) {
  const ticket = activeTickets.get(threadId);
  if (!ticket || ticket.closed) return;

  const now = new Date();
  ticket.lastMessageAt = now;
  ticket.warnedForInactivity = false;
  activeTickets.set(threadId, ticket);

  if (mongoose.connection.readyState !== 1) return;
  await Ticket.updateOne(
    { threadId, closed: false },
    { $set: { lastMessageAt: now, warnedForInactivity: false } }
  ).catch(error => console.error('Error updating ticket activity:', error.message));
}

async function saveTickets() {
  try {
    const bulkOps = [];
    activeTickets.forEach((ticket, threadId) => {
      const normalized = normalizeTicketState(ticket, threadId);
      bulkOps.push({
        updateOne: {
          filter: { threadId },
          update: {
            $set: {
              threadId,
              userId: normalized.userId,
              category: normalized.category,
              claimedBy: normalized.claimedBy,
              createdAt: normalized.createdAt,
              lastMessageAt: normalized.lastMessageAt,
              warnedForInactivity: normalized.warnedForInactivity,
              closed: normalized.closed,
            },
          },
          upsert: true,
        },
      });
    });
    if (bulkOps.length > 0) await Ticket.bulkWrite(bulkOps);
    console.log(`💾 Saved ${activeTickets.size} active tickets to MongoDB`);
  } catch (error) {
    console.error('Error saving tickets to MongoDB:', error.message);
  }
}


async function loadTickets() {
  try {
    const docs = await Ticket.find({ closed: false }).lean();
    activeTickets.clear();
    docs.forEach(doc => {
      activeTickets.set(doc.threadId, normalizeTicketState(doc));
    });
    console.log(`✅ Loaded ${activeTickets.size} active tickets from MongoDB`);
  } catch (error) {
    console.error('Error loading tickets from MongoDB:', error.message);
  }
}
function clearInactivityNoticeTimeout(notice) {
  if (notice?.startTimeoutId) clearTimeout(notice.startTimeoutId);
  if (notice?.timeoutId) clearTimeout(notice.timeoutId);
}

function clearActiveInactivityNoticeTimeouts() {
  for (const notice of activeInactivityNotices.values()) {
    clearInactivityNoticeTimeout(notice);
  }
}

async function deleteInactivityNotice(discordId) {
  clearInactivityNoticeTimeout(activeInactivityNotices.get(discordId));
  activeInactivityNotices.delete(discordId);
  await setStaffProfileInactivityTag(discordId, false).catch(error =>
    console.warn(`Could not remove inactivity profile tag for ${discordId}:`, error.message),
  );

  if (mongoose.connection.readyState !== 1) return;
  await InactivityNotice.deleteOne({ discordId }).catch(error =>
    console.error('Error deleting inactivity notice from MongoDB:', error.message)
  );
}

async function saveInactivityNotices() {
  try {
    const bulkOps = [];
    for (const [discordId, notice] of activeInactivityNotices.entries()) {
      const endTimestamp = notice.endTimestamp || getInactivityNoticeEndTimestamp(notice);
      bulkOps.push({
        updateOne: {
          filter: { discordId },
          update: {
            discordId,
            startDate: notice.startDate,
            endDate: notice.endDate,
            reason: notice.reason,
            approvedBy: notice.approvedBy,
            approvedAt: notice.approvedAt,
            robloxUsername: notice.robloxUsername,
            rank: notice.rank,
            status: notice.status || getInactivityNoticeComputedStatus(notice),
            startTimestamp: notice.startTimestamp || getInactivityNoticeStartTimestamp(notice),
            endTimestamp,
            startedAt: notice.startedAt || null,
          },
          upsert: true,
        },
      });
    }
    if (bulkOps.length > 0) await InactivityNotice.bulkWrite(bulkOps);
    console.log(`💾 Saved ${activeInactivityNotices.size} active inactivity notices to MongoDB`);
  } catch (error) {
    console.error('Error saving inactivity notices to MongoDB:', error.message);
  }
}

async function loadInactivityNotices() {
  try {
    const docs = await InactivityNotice.find({}).lean().exec();
    clearActiveInactivityNoticeTimeouts();
    activeInactivityNotices.clear();

    if (!docs || docs.length === 0) {
      console.log('✅ Loaded 0 active inactivity notices from MongoDB');
      return;
    }
    const now = Date.now();

    for (const doc of docs) {
      if (doc.status === "pending" || doc.approvedBy === "pending") continue;

      const state = buildInactivityNoticeState(doc, now);
      if (state.status === "expired") {
        if (doc.status === "scheduled") {
          console.log(`🧹 Removing expired scheduled inactivity notice for ${doc.robloxUsername}`);
          await deleteInactivityNotice(doc.discordId);
        } else {
          console.log(`⚡ Processing expired inactivity notice for ${doc.robloxUsername}`);
          await restoreFromInactivity(doc.discordId, state);
        }
        continue;
      }

      const scheduledState = scheduleInactivityNoticeTimers(doc.discordId, state);
      if (scheduledState.status === "active") {
        await activateInactivityNotice(doc.discordId, "startup recovery", false);
        const timeRemaining = scheduledState.endTimestamp - now;
        console.log(`⏰ Rescheduled active inactivity notice restoration for ${doc.robloxUsername} (${Math.round(timeRemaining / 1000 / 60 / 60)} hours remaining)`);
      } else {
        const startsIn = scheduledState.startTimestamp - now;
        console.log(`📅 Loaded scheduled inactivity notice for ${doc.robloxUsername} (starts in ${Math.round(startsIn / 1000 / 60 / 60)} hours)`);
      }
    }

    console.log(`✅ Loaded ${activeInactivityNotices.size} active inactivity notices from MongoDB`);
  } catch (error) {
    console.error('Error loading inactivity notices from MongoDB:', error.message);
  }
}

async function restoreFromInactivity(discordId, notice) {
  try {
    const MAIN_GUILD_ID = "1171617307961851975";
    const mainGuild = client.guilds.cache.get(MAIN_GUILD_ID);

    if (!mainGuild) {
      console.error(`Could not access main server for inactivity restoration of ${discordId}`);
      return;
    }

    const member = await mainGuild.members.fetch(discordId).catch(() => null);
    if (!member) {
      console.log(`Member ${discordId} not found in server, cleaning up inactivity notice`);
      await deleteInactivityNotice(discordId);
      return;
    }

    // Restore nickname
    try {
      await member.setNickname(notice.robloxUsername);
      console.log(`✅ Restored nickname for ${notice.robloxUsername}`);
    } catch (err) {
      console.warn(`Failed to restore nickname for ${member.user.tag}:`, err.message);
    }

    // Send DM notification (formatted embed, consistent with other bot notices)
    try {
      const inactivityTeam =
        Number(notice.rank) === MANAGER_SYSTEM_CONFIG.SHIFT_LEAD_RANK
          ? "Sweetsiez Management Team"
          : "Sweetsiez Corporate Team";
      const inactivityEndEmbed = new EmbedBuilder()
        .setColor(0x00cc66)
        .setDescription(
          `🧁 **INACTIVITY NOTICE ENDED**\n\nGreetings, **${notice.robloxUsername}**. Your inactivity notice has now ended. Please resume your regular duties and ensure you meet your weekly activity requirements going forward.\n\nIf you need further time away, please submit a new notice via the **/inactive** command.\n\nWelcome back!\n\nMuch Regards,\n*${inactivityTeam}*`
        )
        .setTimestamp();
      await member.send({ embeds: [inactivityEndEmbed] });
    } catch (err) {
      console.warn(`Failed to DM ${member.user.tag} about inactivity end:`, err.message);
    }

    // Remove from active notices
    await deleteInactivityNotice(discordId);

    if (Number(notice.rank) === MANAGER_SYSTEM_CONFIG.SHIFT_LEAD_RANK) {
      const robloxUserId = await getRobloxUserId(notice.robloxUsername).catch(() => null);
      if (robloxUserId) {
        const profile = await getOrCreateManagerProfileThread({
          discordId,
          robloxUsername: notice.robloxUsername,
          robloxUserId,
        }).catch(() => null);
        if (profile) {
          await profile.thread.send({
            embeds: [
              new EmbedBuilder()
                .setColor(0x00cc66)
                .setTitle("Inactivity Notice Ended")
                .setDescription(`**${notice.robloxUsername}** has reached the end of their approved inactivity notice.`)
                .setTimestamp(),
            ],
          });
          await removeForumThreadTags(profile.thread, profile.forumChannel, ["Inactivity Notice"]);
        }
      }
    }

    console.log(`✅ Inactivity notice ended for ${notice.robloxUsername}`);

  } catch (error) {
    console.error(`Error restoring from inactivity for ${discordId}:`, error);
  }
}

