async function loadQuotaExceptions() {
  try {
    const docs = await QuotaException.find({ active: true }).lean();
    quotaExceptions.clear();
    docs.forEach(doc => quotaExceptions.set(doc.discordId, doc));
    console.log(`✅ Loaded ${quotaExceptions.size} active quota exception record(s) from MongoDB`);
  } catch (error) {
    console.error('Error loading quota exceptions:', error.message);
  }
}

function getActiveQuotaException(discordId) {
  const record = quotaExceptions.get(discordId);
  return record?.active === false ? null : record || null;
}

function getEffectiveQuotaRequirements(baseRequirements, discordId) {
  const base = {
    mins: getRequiredQuotaValue(baseRequirements, "mins"),
    msgs: getRequiredQuotaValue(baseRequirements, "msgs"),
    shiftAttend: getRequiredQuotaValue(baseRequirements, "shiftAttend"),
    shiftHost: getRequiredQuotaValue(baseRequirements, "shiftHost"),
  };
  const exception = getActiveQuotaException(discordId);
  if (!exception) {
    return {
      ...base,
      baseMsgs: base.msgs,
      discordOnly: false,
      exception: null,
    };
  }

  return {
    mins: 0,
    msgs: base.msgs * 2,
    shiftAttend: 0,
    shiftHost: 0,
    baseMsgs: base.msgs,
    discordOnly: true,
    exception,
  };
}

function formatQuotaExceptionLabel(exception) {
  if (!exception) return "Normal quota";
  const approvedAt = exception.createdAt
    ? `<t:${Math.floor(new Date(exception.createdAt).getTime() / 1000)}:d>`
    : "unknown date";
  return `Discord-only quota exception approved ${approvedAt}`;
}

async function sendQuotaExceptionStaffProfileLog({
  targetUser,
  targetUsername,
  targetRobloxId,
  targetRank,
  action,
  reason,
  proof,
  effectiveReq,
  baseReq,
  issuer,
}) {
  const profileData = await getOrCreateStaffProfileThread({
    discordId: targetUser.id,
    robloxUsername: targetUsername,
    robloxUserId: targetRobloxId,
    rank: targetRank.rank,
    rankName: targetRank.name || `Rank ${targetRank.rank}`,
  });
  const thread = profileData?.thread;
  if (!thread) throw new Error("Could not access the staff profile thread.");
  if (thread.archived) await thread.setArchived(false).catch(() => {});
  if (thread.locked) await thread.setLocked(false).catch(() => {});

  const isRemoval = action === "remove";
  const quotaSummary = isRemoval
    ? [
        "Normal quota restored.",
        `Messages: **${getRequiredQuotaValue(baseReq, "msgs")}/week**`,
        `Minutes: **${getRequiredQuotaValue(baseReq, "mins")}/week**`,
        `Shift attendance: **${getRequiredQuotaValue(baseReq, "shiftAttend")}/week**`,
        `Shift hosting: **${getRequiredQuotaValue(baseReq, "shiftHost")}/week**`,
      ].join("\n")
    : [
        "Discord-only quota approved.",
        `Messages: **${effectiveReq.msgs}/week** (doubled from ${effectiveReq.baseMsgs}/week)`,
        "In-game minutes and shift requirements: **removed**",
      ].join("\n");

  const embed = new EmbedBuilder()
    .setColor(isRemoval ? 0xffa500 : 0x6bcf7f)
    .setTitle(isRemoval ? "Discord-Only Quota Exception Removed" : "Discord-Only Quota Exception Approved")
    .setDescription(
      isRemoval
        ? "The staff member has been restored to normal quota. Their one-time Discord-only exception remains used and cannot be granted again."
        : "The staff member has been placed on Discord-only quota. This uses their one allowed Discord-only quota exception."
    )
    .addFields(
      { name: "Staff Member", value: `${targetUser.tag} (${targetUser.id})`, inline: true },
      { name: "Roblox Account", value: `${targetUsername} (${targetRobloxId})`, inline: true },
      { name: "Rank", value: `${targetRank.name || `Rank ${targetRank.rank}`} (${targetRank.rank})`, inline: true },
      { name: isRemoval ? "Removed By" : "Approved By", value: `${issuer.tag} (${issuer.id})`, inline: true },
      { name: "Quota Status", value: quotaSummary, inline: false },
      { name: "Reason", value: truncateForDiscord(reason), inline: false },
      { name: "Proof / Reference", value: truncateForDiscord(proof || "N/A"), inline: false },
    )
    .setTimestamp();

  await thread.send({
    embeds: [embed],
    allowedMentions: { parse: [] },
  });
  return thread;
}

