function validateGoogleFormSubmissionKey(req, res, next) {
  const authHeader = req.headers["authorization"];
  const formSecret = req.headers["x-form-secret"];
  const expectedFormSecret = process.env.GOOGLE_FORM_SECRET || config.HTTP_API_KEY;
  const validBearer = config.HTTP_API_KEY && authHeader === `Bearer ${config.HTTP_API_KEY}`;
  const validFormSecret = expectedFormSecret && formSecret === expectedFormSecret;

  if (!validBearer && !validFormSecret) {
    return res.status(401).json({
      success: false,
      error: "Unauthorized: Invalid Google Form submission key",
    });
  }

  next();
}

function normalizeFormKind(kind) {
  return String(kind || "").trim().toLowerCase();
}

function coerceFormAnswers(rawAnswers) {
  if (!rawAnswers || typeof rawAnswers !== "object") return {};

  if (Array.isArray(rawAnswers)) {
    return rawAnswers.reduce((answers, item) => {
      if (!item || typeof item !== "object") return answers;
      const question = item.question || item.title || item.name;
      const answer = item.answer || item.value || item.response;
      if (question) answers[String(question)] = normalizeFormAnswer(answer);
      return answers;
    }, {});
  }

  return Object.fromEntries(
    Object.entries(rawAnswers).map(([question, answer]) => [
      question,
      normalizeFormAnswer(answer),
    ]),
  );
}

function normalizeFormAnswer(answer) {
  if (answer === null || answer === undefined || answer === "") return "Not provided";
  if (Array.isArray(answer)) return answer.map(normalizeFormAnswer).join(", ");
  if (typeof answer === "object") return JSON.stringify(answer);
  return String(answer);
}

function truncateForDiscord(value, maxLength = 1024) {
  const text = String(value || "Not provided").trim() || "Not provided";
  if (text.length <= maxLength) return text;
  return `${text.slice(0, maxLength - 3)}...`;
}

function getFirstFormAnswer(answers, possibleQuestions) {
  for (const question of possibleQuestions) {
    if (answers[question]) return answers[question];
  }
  return "";
}

function getAppealType(answers, payload = {}) {
  const summary = payload.summary || {};
  const values = [
    summary.appealType,
    summary.appealArea,
    answers["Where did the moderation action happen?"],
    answers["What Discord action are you appealing?"],
    answers["What are you appealing?"],
    answers["What consequence was issued?"],
    answers["Where did the ban occur?"],
  ].filter(Boolean);

  return values.length ? values.join(" / ") : "Appeal";
}

/**
 * The appeal form asks different questions depending on what the applicant is appealing.
 * "What Discord action are you appealing?" only exists on the Discord branch, so its
 * presence is the reliable signal - the free-text answers are not.
 */
function isDiscordAppealSubmission(answers, payload = {}) {
  if (answers && answers["What Discord action are you appealing?"]) return true;
  const summary = payload.summary || {};
  if (/discord/i.test(String(summary.appealType || ""))) return true;
  if (/discord/i.test(String(summary.appealArea || ""))) return true;
  return false;
}

function buildGoogleFormSubmissionEmbed(payload, answers) {
  const formKind = normalizeFormKind(payload.formKind);
  const isAppeal = formKind === "appeal";
  const embed = new EmbedBuilder()
    .setTitle(isAppeal ? "New Appeal Submission" : "New Giveaway Submission")
    .setColor(isAppeal ? 0xffcc00 : 0x5865f2)
    .setTimestamp();

  const fields = [
    {
      name: "Form",
      value: truncateForDiscord(payload.formTitle || "Google Form", 256),
      inline: false,
    },
  ];

  if (isAppeal) {
    fields.push(
      {
        name: "Roblox Username",
        value: truncateForDiscord(
          getFirstFormAnswer(answers, ["Roblox Username", "Roblox username"]),
          256,
        ),
        inline: true,
      },
      {
        name: "Discord Username",
        value: truncateForDiscord(
          getFirstFormAnswer(answers, ["Discord Username", "Discord username"]),
          256,
        ),
        inline: true,
      },
      {
        name: "Appeal Type",
        value: truncateForDiscord(getAppealType(answers, payload), 256),
        inline: false,
      },
    );
  }

  for (const [question, answer] of Object.entries(answers)) {
    if (!question || fields.length >= 25) break;
    fields.push({
      name: truncateForDiscord(question, 256),
      value: truncateForDiscord(answer),
      inline: false,
    });
  }

  if (payload.editResponseUrl && fields.length < 25) {
    fields.push({
      name: "Response Edit Link",
      value: truncateForDiscord(payload.editResponseUrl),
      inline: false,
    });
  }

  embed.addFields(fields);
  return embed;
}

function buildAppealVotingThreadMessage(appealType) {
  const isDiscordAppeal = /discord/i.test(appealType || "");

  if (isDiscordAppeal) {
    return [
      "**NEW DISCORD BAN / WARNING APPEAL**",
      "",
      "A new Discord ban or warning appeal has been submitted. Please review the submission above and discuss it here.",
      "",
      "**INSTRUCTIONS:**",
      "- Use the \u2705 and \u274e reactions on the message above to cast your vote.",
      "- Review the user's Discord history and the original punishment details before voting.",
      "- Discuss any relevant context, previous warnings, or mitigating factors in this thread.",
      "- Ensure a final decision (approve/deny) is clearly recorded once a consensus is reached.",
      "",
      "_This appeal is handled by the Discord Moderation Department._",
    ].join("\n");
  }

  return [
    "**NEW APPEAL SUBMISSION**",
    "",
    "Please review the submission above and discuss it here.",
    "",
    "**INSTRUCTIONS:**",
    "- Use the \u2705 and \u274e reactions on the message above to cast your vote.",
    "- Discuss the evidence and any previous history in this thread.",
    "- Ensure a final decision is logged once a consensus is reached.",
  ].join("\n");
}

async function addAppealVotingFlow(message, appealType) {
  await message.react("\u2705");
  await message.react("\u274e");

  const isDiscordAppeal = /discord/i.test(appealType || "");
  const thread = await message.startThread({
    name: isDiscordAppeal ? "Discord Appeal Voting" : "Appeal Voting",
    autoArchiveDuration: 1440,
    reason: isDiscordAppeal
      ? "New Discord ban/warning appeal submission for review"
      : "New appeal submission for review",
  });

  await thread.send({
    content: buildAppealVotingThreadMessage(appealType),
  });

  return thread;
}

const APPEAL_DELIVERY_REMINDER_MS = 60 * 60 * 1000; // hourly, per the department's process

function buildAppealDecisionRows(channelId, messageId, disabled = false) {
  return [
    new ActionRowBuilder().addComponents(
      new ButtonBuilder()
        .setCustomId(`appealauto_approve_${channelId}_${messageId}`)
        .setLabel("Approve")
        .setStyle(ButtonStyle.Success)
        .setDisabled(disabled),
      new ButtonBuilder()
        .setCustomId(`appealauto_deny_${channelId}_${messageId}`)
        .setLabel("Deny")
        .setStyle(ButtonStyle.Danger)
        .setDisabled(disabled),
    ),
  ];
}

function getEmbedFieldValue(embed, names) {
  const wanted = new Set(names.map(name => String(name).toLowerCase()));
  const fields = embed?.fields || [];
  const field = fields.find(item => wanted.has(String(item.name || "").toLowerCase()));
  return field?.value && field.value !== "Not provided" ? String(field.value).trim() : "";
}

function getAppealDataFromMessage(message) {
  const embed = message?.embeds?.[0];
  const robloxUsername = getEmbedFieldValue(embed, [
    "Roblox Username",
    "Roblox username",
    "What is your Roblox username?",
  ]);
  const discordUsername = getEmbedFieldValue(embed, [
    "Discord Username",
    "Discord username",
    "What is your Discord username?",
  ]);
  const appealType = getEmbedFieldValue(embed, ["Appeal Type"])
    || [
      getEmbedFieldValue(embed, ["What Discord action are you appealing?"]),
      getEmbedFieldValue(embed, ["What are you appealing?"]),
      getEmbedFieldValue(embed, ["Where did the moderation action happen?"]),
      getEmbedFieldValue(embed, ["What consequence was issued?"]),
    ].filter(Boolean).join(" / ")
    || "Appeal";

  return {
    robloxUsername: robloxUsername || "Not provided",
    discordUsername: discordUsername || "Not provided",
    appealType,
    banIssuedBy: getEmbedFieldValue(embed, ["Who banned you?", "Who issued the consequence?", "BAN ISSUED BY"]) || "Not provided",
    dateOfBan: getEmbedFieldValue(embed, ["When were you banned?", "When was the consequence issued?", "DATE OF BAN"]) || "Not provided",
    reasonForBan: getEmbedFieldValue(embed, ["Why were you banned?", "Why were you punished?", "Reason for ban", "REASON FOR BAN"]) || "Not provided",
    editResponseUrl: getEmbedFieldValue(embed, ["Response Edit Link"]),
  };
}

function parseYesNo(value) {
  return /^(yes|y|true|blacklist|appeal blacklist)$/i.test(String(value || "").trim());
}

function normalizeDiscordName(value) {
  return String(value || "")
    .replace(/[<@!>]/g, "")
    .replace(/^@+/, "")
    .trim()
    .toLowerCase();
}

async function resolveDiscordUserIdForAppeal(guild, data) {
  const raw = String(data.discordUsername || "").trim();
  const idMatch = raw.match(/\b\d{17,20}\b/);
  if (idMatch) return idMatch[0];

  const robloxLower = String(data.robloxUsername || "").trim().toLowerCase();
  if (robloxLower && robloxLower !== "not provided") {
    for (const [discordId, username] of verifiedUsers.entries()) {
      if (String(username || "").toLowerCase() === robloxLower) return discordId;
    }
    const verifiedDoc = await VerifiedUser.findOne({ robloxUsernameLower: robloxLower }).lean().catch(() => null);
    if (verifiedDoc?.discordId) return verifiedDoc.discordId;
  }

  const query = normalizeDiscordName(raw);
  if (!query || !guild?.members?.search) return null;
  const members = await guild.members.search({ query, limit: 5 }).catch(() => null);
  if (!members?.size) return null;
  const exact = members.find(member =>
    normalizeDiscordName(member.user.username) === query ||
    normalizeDiscordName(member.user.tag) === query ||
    normalizeDiscordName(member.displayName) === query,
  );
  return (exact || members.first())?.id || null;
}

function getAppealedConsequenceType(data) {
  const text = `${data.appealType || ""} ${data.reasonForBan || ""}`.toLowerCase();
  if (text.includes("warning")) return "WARNING";
  if (text.includes("discord") && text.includes("ban")) return "DISCORD";
  if (text.includes("permanent")) return "PERMANENT";
  if (text.includes("temporary")) return "TEMPORARY";
  if (text.includes("shadow")) return "SHADOW";
  if (text.includes("quiz")) return "QUIZ";
  if (text.includes("server") && !text.includes("discord")) return "SERVER";
  if (text.includes("in-game") || text.includes("ingame") || text.includes("roblox")) return "PERMANENT";
  return null;
}

async function removeLatestWarningForAppeal(discordId, warningType) {
  if (!discordId) return `No active ${warningType === "staff" ? "staff" : "Discord"} warning was found`;
  const warningDoc = await Warning.findOne({
    discordId,
    type: warningType,
    expired: { $ne: true },
  }).sort({ date: -1 });

  if (!warningDoc) {
    return `No active ${warningType === "staff" ? "staff" : "Discord"} warning was found`;
  }

  await Warning.deleteOne({ _id: warningDoc._id });
  if (warnings.has(discordId)) {
    const stored = warnings.get(discordId) || [];
    stored.pop();
    if (stored.length) warnings.set(discordId, stored);
    else warnings.delete(discordId);
  }
  return `Removed one active ${warningType === "staff" ? "staff" : "Discord"} warning`;
}

async function applyAppealAutomaticActions({ guild, data, outcomeReason, actor }) {
  const actions = [];
  const consequenceType = getAppealedConsequenceType(data);
  const discordId = await resolveDiscordUserIdForAppeal(guild, data).catch(() => null);
  const robloxUserId = data.robloxUserId || (
    data.robloxUsername && data.robloxUsername !== "Not provided"
      ? await getRobloxUserId(data.robloxUsername).catch(() => null)
      : null
  );

  data.discordUserId = discordId || null;
  data.robloxUserId = robloxUserId ? String(robloxUserId) : null;

  if (!consequenceType) return ["No matching consequence type could be determined"];

  if (consequenceType === "WARNING") {
    actions.push(await removeLatestWarningForAppeal(discordId, "discord"));
    actions.push(await removeLatestWarningForAppeal(discordId, "staff"));
    return actions;
  }

  if (consequenceType === "DISCORD") {
    if (!discordId) {
      actions.push("No Discord user ID could be resolved; no Discord ban was lifted");
      return actions;
    }
    const banEntry = await guild.bans.fetch(discordId).catch(() => null);
    if (!banEntry) {
      actions.push("No active Discord ban was found");
    } else {
      await guild.members.unban(discordId, `Appeal approved by ${actor.tag}: ${outcomeReason}`).catch(error => {
        actions.push(`Discord unban failed: ${error.message}`);
      });
      if (!actions.some(item => item.startsWith("Discord unban failed"))) {
        actions.push("Discord ban lifted");
      }
    }
    await BanRecord.findOneAndUpdate(
      { type: "DISCORD", discordUserId: discordId, active: true },
      {
        $set: {
          status: "REVOKED",
          active: false,
          revokedAt: new Date(),
          revokedByDiscordId: actor.id,
          revokedByTag: actor.tag,
          revokeReason: `Appeal approved: ${outcomeReason}`,
          updatedAt: new Date(),
        },
      },
      { sort: { issuedAt: -1 } },
    ).catch(() => {});
    return actions;
  }

  if (!robloxUserId) {
    actions.push("No Roblox user ID could be resolved; no in-game consequence was lifted");
    return actions;
  }

  const query = {
    type: consequenceType,
    active: true,
    $or: [
      { robloxUserId: String(robloxUserId) },
      { robloxUsername: new RegExp(`^${String(data.robloxUsername || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}$`, "i") },
    ],
  };
  const record = await BanRecord.findOne(query).sort({ issuedAt: -1 });
  if (!record) {
    actions.push(`No active ${consequenceType.toLowerCase()} in-game ban was found`);
    return actions;
  }

  const action = await queueGameBanAction({
    recordId: record.recordId,
    type: consequenceType,
    removing: true,
    userId: robloxUserId,
    robloxUsername: data.robloxUsername,
    reason: `Appeal approved: ${outcomeReason}`,
    issuedBy: actor.tag,
    serverJobId: record.serverJobId || null,
  });
  record.status = "REVOKE_PENDING";
  record.active = false;
  record.revokedByDiscordId = actor.id;
  record.revokedByTag = actor.tag;
  record.revokeReason = `Appeal approved: ${outcomeReason}`;
  record.updatedAt = new Date();
  await record.save();
  await appendBanRecordUpdate(
    record,
    `${consequenceType} Ban Appeal Approved`,
    `Unban action queued by **${actor.tag}**.\n**Reason:** ${outcomeReason}\n**Action ID:** ${action.actionId}`,
  ).catch(() => {});
  actions.push(`${consequenceType.toLowerCase()} in-game unban queued (${action.actionId})`);
  return actions;
}

async function upsertAppealBlacklist(outcomeDoc) {
  if (!outcomeDoc.appealBlacklisted) return;
  const clauses = [];
  if (outcomeDoc.robloxUserId) clauses.push({ robloxUserId: outcomeDoc.robloxUserId });
  if (outcomeDoc.discordUserId) clauses.push({ discordUserId: outcomeDoc.discordUserId });
  if (!clauses.length && outcomeDoc.robloxUsername !== "Not provided") clauses.push({ robloxUsername: new RegExp(`^${outcomeDoc.robloxUsername.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}$`, "i") });
  const query = clauses.length ? { $or: clauses } : { sourceOutcomeId: outcomeDoc.outcomeId };

  await AppealBlacklist.findOneAndUpdate(
    query,
    {
      $set: {
        robloxUsername: outcomeDoc.robloxUsername,
        robloxUserId: outcomeDoc.robloxUserId || null,
        discordUsername: outcomeDoc.discordUsername,
        discordUserId: outcomeDoc.discordUserId || null,
        reason: outcomeDoc.outcomeReason,
        sourceOutcomeId: outcomeDoc.outcomeId,
        issuedByDiscordId: outcomeDoc.decidedByDiscordId,
        issuedByTag: outcomeDoc.decidedByTag,
        active: true,
        updatedAt: new Date(),
      },
      $setOnInsert: {
        blacklistId: createOperationalId("APBL"),
        createdAt: new Date(),
      },
    },
    { upsert: true },
  );
}

function buildAppealOutcomePostContent(outcome, proofLine = null) {
  const automaticActions = outcome.automaticActions?.length
    ? outcome.automaticActions.join("; ")
    : "No consequence lifted";
  return [
    `ROBLOX USERNAME & ID: ${outcome.robloxUsername || "Not provided"} & ${outcome.robloxUserId || "Not provided"}`,
    `TYPE OF BAN APPEALED: ${outcome.appealType || "Appeal"}`,
    `OUTCOME: ${outcome.outcome}`,
    `BAN ISSUED BY: ${outcome.banIssuedBy || "Not provided"}`,
    `DATE OF BAN: ${outcome.dateOfBan || "Not provided"}`,
    `REASON FOR BAN: ${outcome.reasonForBan || "Not provided"}`,
    `REASON OF APPEAL OUTCOME: ${outcome.outcomeReason}`,
    `APPEAL BLACKLISTED: ${outcome.appealBlacklisted ? "yes" : "no"}`,
    `PROOF OF MESSAGE DELIVERANCE: ${proofLine || `Screenshot — confirmed by <@${outcome.decidedByDiscordId}>`}`,
    "",
    `AUTOMATIC ACTIONS: ${automaticActions}`,
    "",
    `<@${outcome.decidedByDiscordId}> Send the result to the appellant, then reply in this post with the phrase appeal delivered and attach a screenshot/image as proof.`,
  ].join("\n");
}

/** A Discord ban / warning appeal is the Discord Moderation Department's caseload. */
function isDiscordModerationAppeal(outcome) {
  // Discord appeals are queued in their own channel, so that is authoritative. Anything
  // else (an older submission, or one posted by hand) falls back to the stored appeal type.
  const sourceChannelId = String(outcome?.sourceChannelId || "");
  if (sourceChannelId === SWEETSIEZ_STRUCTURE_CONFIG.CHANNELS.DMD_APPEAL_SUBMISSIONS) return true;
  return /discord/i.test(String(outcome?.appealType || ""));
}

function getModerationAppealConsequenceLabel(outcome) {
  return /warn/i.test(String(outcome?.appealType || "")) ? "Discord Warning" : "Discord Ban";
}

/**
 * The department logs its own way: the consequence, who issued it, and the outcome,
 * with the delivery proof left open until the decider posts it.
 */
function buildModerationAppealOutcomeContent(outcome, proofLine = null) {
  const proof = proofLine
    ? proofLine
    : "Pending — reply in this post with `appeal delivered` and attach a screenshot";
  return [
    `ROBLOX USERNAME & ID: ${outcome.robloxUsername || "Not provided"} & ${outcome.robloxUserId || "Not provided"}`,
    `CONSEQUENCE APPEALED: ${getModerationAppealConsequenceLabel(outcome).toUpperCase()}`,
    `OUTCOME: ${outcome.outcome === "APPROVED" ? "ACCEPTED" : "DECLINED"}`,
    `CONSEQUENCE ISSUED BY: ${outcome.banIssuedBy || "Not provided"}`,
    `DATE OF CONSEQUENCE: ${outcome.dateOfBan || "Not provided"}`,
    `REASON FOR CONSEQUENCE: ${outcome.reasonForBan || "Not provided"}`,
    `REASON OF APPEAL OUTCOME: ${outcome.outcomeReason}`,
    `APPEAL BLACKLISTED: ${outcome.appealBlacklisted ? "yes" : "no"}`,
    `PROOF OF MESSAGE DELIVERANCE: ${proof}`,
    "",
    `<@${outcome.decidedByDiscordId}> Send the result to the appellant, then reply in this post with the phrase appeal delivered and attach a screenshot/image as proof.`,
  ].join("\n");
}

async function postAppealOutcomeLog(outcome) {
  // Discord ban / warning appeals belong to the Discord Moderation Department and are
  // logged in its own outcomes forum, tagged by consequence type. Everything else keeps
  // going to the Human Resources logging forum.
  const isDmd = isDiscordModerationAppeal(outcome);
  const channelId = isDmd
    ? SWEETSIEZ_STRUCTURE_CONFIG.CHANNELS.DMD_APPEAL_OUTCOMES
    : SWEETSIEZ_STRUCTURE_CONFIG.CHANNELS.OPERATIONS_LOGGING;
  const channel = await client.channels.fetch(channelId).catch(() => null);
  if (!channel) {
    throw new Error(isDmd
      ? "Discord Moderation appeal outcomes forum is unavailable."
      : "Human Resources logging channel is unavailable.");
  }
  const title = `${outcome.robloxUsername || "unknown"} | ${outcome.outcome}`.slice(0, 100);
  const content = isDmd
    ? buildModerationAppealOutcomeContent(outcome)
    : buildAppealOutcomePostContent(outcome);

  if (channel.type === ChannelType.GuildForum) {
    // A missing tag must not lose the decision: post untagged instead of throwing.
    const tag = isDmd
      ? await ensureForumTag(channel, getModerationAppealConsequenceLabel(outcome))
      : await ensureForumTag(channel, "Appeals");
    if (!isDmd && !tag?.id) {
      throw new Error('Operations logging forum requires an "Appeals" tag, but it could not be found or created.');
    }
    const thread = await channel.threads.create({
      name: title,
      appliedTags: tag?.id ? [tag.id] : [],
      message: { content, allowedMentions: { users: [outcome.decidedByDiscordId] } },
      reason: `Appeal ${outcome.outcome.toLowerCase()} by ${outcome.decidedByTag}`,
    });
    const starter = typeof thread.fetchStarterMessage === "function"
      ? await thread.fetchStarterMessage().catch(() => null)
      : null;
    return { thread, message: starter };
  }

  if (!channel.isTextBased?.()) {
    throw new Error(isDmd
      ? "Discord Moderation appeal outcomes channel is unavailable."
      : "Human Resources logging channel is unavailable.");
  }
  const message = await channel.send({ content, allowedMentions: { users: [outcome.decidedByDiscordId] } });
  return { thread: null, message };
}

function appealAutomaticActionsDidLift(actions) {
  return (actions || []).some(action => {
    const text = String(action || "").toLowerCase();
    if (!text || text.startsWith("no ") || text.includes("failed") || text.includes("could not")) return false;
    return text.includes("ban lifted")
      || text.includes("removed one active")
      || text.includes("unban queued")
      || text.includes("warning was removed");
  });
}

async function updateAppealSourceMessage(sourceMessage, decisionMessage, outcomeDoc) {
  const sourceUrl = outcomeDoc.outcomeThreadId
    ? `https://discord.com/channels/${SWEETSIEZ_STRUCTURE_CONFIG.GUILD_ID}/${outcomeDoc.outcomeThreadId}`
    : "Outcome post unavailable";
  const disabledRows = buildAppealDecisionRows(outcomeDoc.sourceChannelId, outcomeDoc.sourceMessageId, true);

  if (sourceMessage?.editable && sourceMessage.embeds?.[0]) {
    const embed = EmbedBuilder.from(sourceMessage.embeds[0])
      .setTitle(`Appeal ${outcomeDoc.outcome}`)
      .setColor(outcomeDoc.outcome === "APPROVED" ? 0x57f287 : 0xed4245)
      .addFields(
        { name: "Decision By", value: `<@${outcomeDoc.decidedByDiscordId}>`, inline: true },
        { name: "Outcome Reason", value: truncateForDiscord(outcomeDoc.outcomeReason, 1024), inline: false },
        { name: "Outcome Post", value: sourceUrl, inline: false },
      );
    await sourceMessage.edit({ embeds: [embed], components: disabledRows }).catch(() => {});
  }

  if (decisionMessage && decisionMessage.id !== sourceMessage?.id) {
    await decisionMessage.edit({
      content: `Appeal ${outcomeDoc.outcome.toLowerCase()} by <@${outcomeDoc.decidedByDiscordId}>.`,
      components: disabledRows,
      allowedMentions: { users: [outcomeDoc.decidedByDiscordId] },
    }).catch(() => {});
  }
}

async function ensureAppealDecisionControls(message) {
  if (!message?.channelId || !message?.id) return null;
  const hasControls = message.components?.some(row =>
    row.components?.some(component => String(component.customId || "").startsWith("appealauto_")),
  );
  if (hasControls) return message;

  const rows = buildAppealDecisionRows(message.channelId, message.id);
  if (message.author?.id === client.user?.id && message.editable) {
    return message.edit({ components: rows }).catch(() => null);
  }

  return message.reply({
    content: "Appeal decision controls:",
    components: rows,
    allowedMentions: { parse: [] },
  }).catch(() => null);
}

function showAppealDecisionModal(interaction, action, sourceChannelId, sourceMessageId) {
  const { ModalBuilder, TextInputBuilder, TextInputStyle } = require("discord.js");
  const modal = new ModalBuilder()
    .setCustomId(`appealauto_modal_${action}_${sourceChannelId}_${sourceMessageId}`)
    .setTitle(action === "approve" ? "Approve Appeal" : "Deny Appeal");
  modal.addComponents(
    new ActionRowBuilder().addComponents(
      new TextInputBuilder()
        .setCustomId("outcome_reason")
        .setLabel("Outcome reason")
        .setStyle(TextInputStyle.Paragraph)
        .setRequired(true)
        .setMaxLength(1000),
    ),
    new ActionRowBuilder().addComponents(
      new TextInputBuilder()
        .setCustomId("appeal_blacklisted")
        .setLabel("Appeal blacklisted? yes/no")
        .setStyle(TextInputStyle.Short)
        .setRequired(true)
        .setMaxLength(10)
        .setValue(action === "deny" ? "yes" : "no"),
    ),
    new ActionRowBuilder().addComponents(
      new TextInputBuilder()
        .setCustomId("ban_issued_by")
        .setLabel("Ban/consequence issued by")
        .setStyle(TextInputStyle.Short)
        .setRequired(false)
        .setMaxLength(100),
    ),
    new ActionRowBuilder().addComponents(
      new TextInputBuilder()
        .setCustomId("date_of_ban")
        .setLabel("Date of ban/consequence")
        .setStyle(TextInputStyle.Short)
        .setRequired(false)
        .setMaxLength(80),
    ),
    new ActionRowBuilder().addComponents(
      new TextInputBuilder()
        .setCustomId("manual_note")
        .setLabel("Optional internal note")
        .setStyle(TextInputStyle.Short)
        .setRequired(false)
        .setMaxLength(200),
    ),
  );
  return interaction.showModal(modal);
}

async function canManageAppealDecision(interaction, sourceChannelId = null) {
  const member = interaction.member;
  if (!member) return false;
  if (member.permissions?.has(PermissionFlagsBits.Administrator)) return true;

  // A Discord ban or warning appeal is decided inside the Discord Moderation Department:
  // its Executives and its lead. Aspirant Managers may warn and ban but do not decide.
  const isDiscordAppeal = String(sourceChannelId || "")
    === SWEETSIEZ_STRUCTURE_CONFIG.CHANNELS.DMD_APPEAL_SUBMISSIONS;
  if (isDiscordAppeal) {
    return hasAnyRoleId(member, [
      SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Discord Moderation Department"],
      SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Discord Moderation Lead"],
      SWEETSIEZ_STRUCTURE_CONFIG.ROLES["President"],
    ]);
  }

  // Punishment (staff consequence) appeals stay with the administration.
  const context = await getBoardSystemContext(interaction).catch(() => ({ rank: 0, member }));
  return context.rank >= SWEETSIEZ_STRUCTURE_CONFIG.EXECUTIVE_BOARD_RANK || hasAnyRoleId(context.member, [
    SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Executive Board"],
    SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Head of Operations"],
    SWEETSIEZ_STRUCTURE_CONFIG.ROLES["President"],
    SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Vice President"],
  ]);
}

async function handleAppealAutomationButton(interaction) {
  const parts = interaction.customId.split("_");
  const action = parts[1];
  const sourceChannelId = parts[2];
  const sourceMessageId = parts[3];
  if (!["approve", "deny"].includes(action) || !sourceChannelId || !sourceMessageId) {
    return interaction.reply({ content: "Invalid appeal decision button.", flags: MessageFlags.Ephemeral });
  }
  if (!await canManageAppealDecision(interaction, sourceChannelId)) {
    return interaction.reply({
      content: "Only the Discord Moderation Department may approve or deny Discord appeals.",
      flags: MessageFlags.Ephemeral,
    });
  }
  return showAppealDecisionModal(interaction, action, sourceChannelId, sourceMessageId);
}

async function handleAppealAutomationModal(interaction) {
  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }
  const parts = interaction.customId.split("_");
  const action = parts[2];
  const sourceChannelId = parts[3];
  const sourceMessageId = parts[4];
  if (!await canManageAppealDecision(interaction, sourceChannelId)) {
    return interaction.editReply("Only the Discord Moderation Department may approve or deny Discord appeals.");
  }
  const outcome = action === "approve" ? "APPROVED" : "DENIED";
  const sourceChannel = await client.channels.fetch(sourceChannelId).catch(() => null);
  if (!sourceChannel?.isTextBased?.()) return interaction.editReply("I could not reach the original appeal channel.");
  const sourceMessage = await sourceChannel.messages.fetch(sourceMessageId).catch(() => null);
  if (!sourceMessage) return interaction.editReply("I could not find the original appeal message.");

  const existing = await AppealOutcome.findOne({ sourceMessageId, sourceChannelId }).lean().catch(() => null);
  if (existing) return interaction.editReply(`This appeal already has an outcome logged: ${existing.outcome}.`);

  const data = getAppealDataFromMessage(sourceMessage);
  const outcomeReason = interaction.fields.getTextInputValue("outcome_reason").trim();
  const appealBlacklisted = parseYesNo(interaction.fields.getTextInputValue("appeal_blacklisted"));
  const banIssuedBy = interaction.fields.getTextInputValue("ban_issued_by").trim() || data.banIssuedBy;
  const dateOfBan = interaction.fields.getTextInputValue("date_of_ban").trim() || data.dateOfBan;
  const manualNote = interaction.fields.getTextInputValue("manual_note").trim();
  data.banIssuedBy = banIssuedBy;
  data.dateOfBan = dateOfBan;
  if (!data.robloxUserId && data.robloxUsername && data.robloxUsername !== "Not provided") {
    const resolvedRobloxId = await getRobloxUserId(data.robloxUsername).catch(() => null);
    if (resolvedRobloxId) data.robloxUserId = String(resolvedRobloxId);
  }
  if (!data.discordUserId) {
    data.discordUserId = await resolveDiscordUserIdForAppeal(interaction.guild, data).catch(() => null);
  }

  const automaticActions = outcome === "APPROVED"
    ? await applyAppealAutomaticActions({
        guild: interaction.guild,
        data,
        outcomeReason,
        actor: interaction.user,
      }).catch(error => [`Automatic action failed: ${error.message}`])
    : ["No consequence lifted"];

  const outcomePayload = {
    outcomeId: createOperationalId("APP"),
    sourceChannelId,
    sourceMessageId,
    decisionMessageId: interaction.message?.id || null,
    robloxUsername: data.robloxUsername || "Not provided",
    robloxUserId: data.robloxUserId || null,
    discordUsername: data.discordUsername || "Not provided",
    discordUserId: data.discordUserId || null,
    appealType: data.appealType || "Appeal",
    outcome,
    banIssuedBy,
    dateOfBan,
    reasonForBan: data.reasonForBan || "Not provided",
    outcomeReason: manualNote ? `${outcomeReason}\nNote: ${manualNote}` : outcomeReason,
    appealBlacklisted,
    automaticActions,
    decidedByDiscordId: interaction.user.id,
    decidedByTag: interaction.user.tag,
    lastReminderAt: new Date(),
  };

  const logPost = await postAppealOutcomeLog(outcomePayload);
  const outcomeDoc = await AppealOutcome.create({
    ...outcomePayload,
    outcomeThreadId: logPost.thread?.id || logPost.message?.channelId || null,
    outcomeStarterMessageId: logPost.message?.id || null,
  });
  await upsertAppealBlacklist(outcomeDoc);
  await updateAppealSourceMessage(sourceMessage, interaction.message, outcomeDoc);
  await logBoardContribution({
    board: "moderation",
    activityType: "appeal_decided",
    discordId: interaction.user.id,
    sourceType: "appeal",
    sourceId: outcomeDoc.outcomeId,
    summary: `${outcomeDoc.outcome} appeal for ${outcomeDoc.robloxUsername || "unknown"}: ${outcomeReason}`,
    loggedBy: interaction.user,
  }).catch(error => console.error("Failed to log appeal decision contribution:", error.message));

  if (outcome === "APPROVED" && appealAutomaticActionsDidLift(automaticActions)) {
    await logBoardContribution({
      board: "moderation",
      activityType: "appeal_automatic_action",
      discordId: interaction.user.id,
      sourceType: "appeal",
      sourceId: outcomeDoc.outcomeId,
      summary: `Automatic appeal action completed for ${outcomeDoc.robloxUsername || "unknown"}: ${automaticActions.join("; ")}`,
      loggedBy: interaction.user,
    }).catch(error => console.error("Failed to log appeal automatic action contribution:", error.message));
  }

  return interaction.editReply(
    `Appeal ${outcome.toLowerCase()} and logged. ` +
    (outcomeDoc.outcomeThreadId ? `Outcome post: https://discord.com/channels/${SWEETSIEZ_STRUCTURE_CONFIG.GUILD_ID}/${outcomeDoc.outcomeThreadId}` : ""),
  );
}

async function processAppealDeliveryReminders() {
  try {
    if (mongoose.connection.readyState !== 1) return;
    const now = new Date();
    const pending = await AppealOutcome.find({
      deliveryProofStatus: "pending",
      outcomeThreadId: { $ne: null },
      $or: [
        { lastReminderAt: null },
        { lastReminderAt: { $lte: new Date(now.getTime() - APPEAL_DELIVERY_REMINDER_MS) } },
      ],
    }).limit(20);

    for (const outcome of pending) {
      const thread = await client.channels.fetch(outcome.outcomeThreadId).catch(() => null);
      if (!thread?.isTextBased?.()) continue;
      await thread.send({
        content: `<@${outcome.decidedByDiscordId}> delivery proof is still required. Reply with appeal delivered and attach a screenshot/image.`,
        allowedMentions: { users: [outcome.decidedByDiscordId] },
      }).catch(() => {});
      outcome.lastReminderAt = now;
      outcome.updatedAt = now;
      await outcome.save();
    }
  } catch (error) {
    console.error("❌ Appeal delivery reminder failed:", error);
  }
}

/** Fill in PROOF OF MESSAGE DELIVERANCE on the logged outcome once the proof arrives. */
async function updateAppealOutcomeProofPost(outcome, proofMessage) {
  if (!outcome?.outcomeThreadId || !outcome?.outcomeStarterMessageId) return;
  const thread = await client.channels.fetch(outcome.outcomeThreadId).catch(() => null);
  if (!thread?.isTextBased?.()) return;
  const starter = await thread.messages.fetch(outcome.outcomeStarterMessageId).catch(() => null);
  if (!starter?.editable) return;
  const proofLink = `https://discord.com/channels/${SWEETSIEZ_STRUCTURE_CONFIG.GUILD_ID}/${thread.id}/${proofMessage.id}`;
  const content = isDiscordModerationAppeal(outcome)
    ? buildModerationAppealOutcomeContent(outcome, proofLink)
    : buildAppealOutcomePostContent(outcome, proofLink);
  await starter.edit({ content }).catch(() => {});
}

async function handleAppealDeliveryProofMessage(message) {
  if (message.author?.bot || !message.channel?.isThread?.()) return false;
  if (!/appeal\s+delivered/i.test(message.content || "")) return false;
  const hasImage = message.attachments?.some(attachment =>
    String(attachment.contentType || "").startsWith("image/") ||
    /\.(png|jpe?g|gif|webp)$/i.test(String(attachment.url || "")),
  );
  if (!hasImage) {
    await message.reply("Please attach a screenshot/image with `appeal delivered` so I can stop reminders.").catch(() => {});
    return true;
  }

  const outcome = await AppealOutcome.findOne({
    outcomeThreadId: message.channel.id,
    deliveryProofStatus: "pending",
  }).sort({ createdAt: -1 });
  if (!outcome) return false;

  outcome.deliveryProofStatus = "delivered";
  outcome.deliveredByDiscordId = message.author.id;
  outcome.deliveredByTag = message.author.tag;
  outcome.deliveredAt = new Date();
  outcome.deliveryProofMessageId = message.id;
  outcome.updatedAt = new Date();
  await outcome.save();
  await message.reply("Delivery proof recorded. Reminders have stopped.").catch(() => {});
  await updateAppealOutcomeProofPost(outcome, message).catch(() => {});
  await logBoardContribution({
    board: "moderation",
    activityType: "appeal_delivery_proof",
    discordId: message.author.id,
    sourceType: "appeal_delivery",
    sourceId: outcome.outcomeId,
    summary: `Delivery proof recorded for ${outcome.robloxUsername || "unknown"} (${outcome.outcome}).`,
    loggedBy: message.author,
  }).catch(error => console.error("Failed to log appeal delivery proof contribution:", error.message));
  return true;
}

async function handleGoogleFormSubmission(req, res) {
  try {
    const payload = req.body || {};
    const formKind = normalizeFormKind(payload.formKind || payload.kind || payload.type);

    if (!["appeal", "giveaway"].includes(formKind)) {
      return res.status(400).json({
        success: false,
        error: "formKind must be either 'appeal' or 'giveaway'",
      });
    }

    if (!client?.isReady?.()) {
      return res.status(503).json({
        success: false,
        error: "Discord client is not ready yet",
      });
    }

    const answers = coerceFormAnswers(
      payload.answers || payload.responses || payload.response || {},
    );
    // Discord ban / warning appeals queue in the Discord Moderation Department, giveaway
    // submissions go to the engagement channel, and punishment appeals keep landing in
    // the shared form channel.
    const isDiscordAppeal = formKind === "appeal"
      && isDiscordAppealSubmission(answers, payload);
    const submissionChannelId = isDiscordAppeal
      ? SWEETSIEZ_STRUCTURE_CONFIG.CHANNELS.DMD_APPEAL_SUBMISSIONS
      : formKind === "giveaway"
        ? GIVEAWAY_SUBMISSION_CHANNEL_ID
        : GOOGLE_FORM_SUBMISSION_CHANNEL_ID;
    // The ping follows the destination, so the department that owns the queue is the one
    // that gets woken: DMD for Discord appeals, Public Relations for giveaways.
    const pingRoleId = (isDiscordAppeal
      ? SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Discord Moderation Department"]
      : formKind === "giveaway"
        ? SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Public Relations Department"]
        : null
    ) || GOOGLE_FORM_SUBMISSION_PING_ROLE_ID;
    const channel = await client.channels
      .fetch(submissionChannelId)
      .catch(() => null);

    if (!channel || !channel.isTextBased?.()) {
      return res.status(500).json({
        success: false,
        error: "Google Form submission channel could not be found or is not text-based",
      });
    }

    const pendingMessage = await channel.send({
      content: `<@&${pingRoleId}>`,
      embeds: [
        buildGoogleFormSubmissionEmbed(
          { ...payload, formKind },
          answers,
        ),
      ],
      allowedMentions: {
        roles: [pingRoleId],
      },
    });
    const message = formKind === "appeal"
      ? await pendingMessage.edit({
          components: buildAppealDecisionRows(channel.id, pendingMessage.id),
        }).catch(() => pendingMessage)
      : pendingMessage;

    let thread = null;
    if (formKind === "appeal") {
      thread = await addAppealVotingFlow(message, getAppealType(answers, payload));
    }

    return res.json({
      success: true,
      messageId: message.id,
      threadId: thread?.id || null,
    });
  } catch (error) {
    console.error("Google Form submission error:", error);
    return res.status(500).json({
      success: false,
      error: "Internal server error",
    });
  }
}

