async function postExtremeApprovalMessage(approval) {
  if (!client?.isReady?.()) throw new Error("Discord client is not ready.");
  const channel = await client.channels.fetch(SECOND_APPROVAL_CHANNEL_ID).catch(() => null);
  if (!channel?.isTextBased?.()) throw new Error("Second approval channel is unavailable.");
  const reviewPolicy = await getSecondApprovalPolicyForRequester(approval.requestedByRobloxId);
  const message = await channel.send({
    content: `<@&${reviewPolicy.pingRoleId}> A second ${reviewPolicy.reviewRankLabel} decision is required.`,
    embeds: [buildExtremeApprovalEmbed(approval)],
    components: [buildExtremeApprovalRow(approval)],
    allowedMentions: { roles: [reviewPolicy.pingRoleId] },
  });
  approval.channelId = channel.id;
  approval.messageId = message.id;
  await approval.save();
  return message;
}

async function getSecondApprovalPolicyForRequester(robloxUserId) {
  const rankInfo = await getUserRankInGroup(robloxUserId).catch((error) => {
    console.error("[SecondApproval] Requester rank lookup failed:", error.message);
    return null;
  });
  const requesterRank = Number(rankInfo?.rank || 0);
  if (isExecutiveDirectorOrLeadershipRank(requesterRank)) {
    return {
      requesterRank,
      requesterRankName: rankInfo?.name || `Rank ${requesterRank}`,
      bypass: true,
      reviewMinRank: SECOND_APPROVAL_BYPASS_MIN_RANK,
      reviewRankLabel: "Director+",
      pingRoleId: SECOND_APPROVAL_ED_PING_ROLE_ID,
      rankInfo,
    };
  }
  if (requesterRank === SWEETSIEZ_STRUCTURE_CONFIG.EXECUTIVE_BOARD_RANK) {
    return {
      requesterRank,
      requesterRankName: rankInfo?.name || "Executive",
      bypass: false,
      reviewMinRank: SECOND_APPROVAL_EXECUTIVE_REQUEST_REVIEW_MIN_RANK,
      reviewRankLabel: "Director+",
      pingRoleId: SECOND_APPROVAL_ED_PING_ROLE_ID,
      rankInfo,
    };
  }
  return {
    requesterRank,
    requesterRankName: rankInfo?.name || (requesterRank ? `Rank ${requesterRank}` : "Unknown Rank"),
    bypass: false,
    reviewMinRank: SECOND_APPROVAL_REVIEW_MIN_RANK,
    reviewRankLabel: "Executive+",
    pingRoleId: SECOND_APPROVAL_PING_ROLE_ID,
    rankInfo,
  };
}

async function resolveRobloxRankInfoForUserId(robloxUserId, fallbackRank = 0, fallbackName = null) {
  const rankInfo = await getUserRankInGroup(robloxUserId).catch((error) => {
    console.error("[RankPolicy] Roblox rank lookup failed:", error.message);
    return null;
  });
  const rank = Number(rankInfo?.rank || fallbackRank || 0);
  return {
    rank,
    name: rankInfo?.name || fallbackName || (rank ? `Rank ${rank}` : "Unknown Rank"),
    id: rankInfo?.id || null,
  };
}

function getAdminAbusePolicyForRank(rank) {
  const numericRank = Number(rank || 0);
  if (numericRank >= SWEETSIEZ_STRUCTURE_CONFIG.PRESIDENT_RANK) {
    return {
      bypass: true,
      label: "President Bypass",
      reviewMinRank: SWEETSIEZ_STRUCTURE_CONFIG.PRESIDENT_RANK,
      reviewRankLabel: "President",
      channelId: null,
      pingRoleIds: [],
      dmRanks: [],
    };
  }
  if (numericRank >= SWEETSIEZ_STRUCTURE_CONFIG.VICE_PRESIDENT_RANK) {
    return {
      bypass: false,
      label: "Director Admin Abuse",
      reviewMinRank: SWEETSIEZ_STRUCTURE_CONFIG.PRESIDENT_RANK,
      reviewRankLabel: "President",
      channelId: null,
      pingRoleIds: [],
      dmRanks: [SWEETSIEZ_STRUCTURE_CONFIG.PRESIDENT_RANK],
    };
  }
  if (numericRank === SWEETSIEZ_STRUCTURE_CONFIG.EXECUTIVE_DIRECTOR_RANK) {
    return {
      bypass: false,
      label: "Director Admin Abuse",
      reviewMinRank: SWEETSIEZ_STRUCTURE_CONFIG.VICE_PRESIDENT_RANK,
      reviewRankLabel: "Leadership Team",
      channelId: ADMIN_ABUSE_LEADERSHIP_CHANNEL_ID,
      pingRoleIds: [ADMIN_ABUSE_LEADERSHIP_PING_ROLE_ID],
      dmRanks: [],
    };
  }
  if (numericRank === SWEETSIEZ_STRUCTURE_CONFIG.EXECUTIVE_BOARD_RANK) {
    return {
      bypass: false,
      label: "Executive Admin Abuse",
      reviewMinRank: SWEETSIEZ_STRUCTURE_CONFIG.SENIOR_HIGH_RANK,
      reviewRankLabel: "Director+",
      channelId: ADMIN_ABUSE_REVIEW_CHANNEL_ID,
      pingRoleIds: [SECOND_APPROVAL_ED_PING_ROLE_ID],
      dmRanks: [],
    };
  }
  return {
    bypass: false,
    label: "Staff Admin Abuse",
    reviewMinRank: SWEETSIEZ_STRUCTURE_CONFIG.EXECUTIVE_BOARD_RANK,
    reviewRankLabel: "Executive+",
    channelId: ADMIN_ABUSE_REVIEW_CHANNEL_ID,
    pingRoleIds: [SECOND_APPROVAL_PING_ROLE_ID],
    dmRanks: [],
  };
}

async function getAdminAbusePolicyForIncident(incident) {
  const rankInfo = await resolveRobloxRankInfoForUserId(
    incident.robloxUserId,
    incident.robloxRank,
    null,
  );
  return {
    ...getAdminAbusePolicyForRank(rankInfo.rank),
    requesterRank: rankInfo.rank,
    requesterRankName: rankInfo.name,
  };
}

async function getVerifiedDiscordIdsForExactMainRanks(rankList) {
  const wanted = new Set((rankList || []).map(rank => Number(rank)));
  const results = [];
  for (const [discordId] of verifiedUsers.entries()) {
    const rankInfo = await getVerifiedMainRankForDiscord(discordId).catch(() => null);
    if (rankInfo && wanted.has(Number(rankInfo.rank))) {
      results.push(discordId);
    }
  }
  return results;
}

async function postAdminAbuseMessage(incident) {
  if (!client?.isReady?.()) throw new Error("Discord client is not ready.");
  const policy = await getAdminAbusePolicyForIncident(incident);
  if (policy.bypass) return null;

  if (policy.dmRanks?.length) {
    const reviewerIds = await getVerifiedDiscordIdsForExactMainRanks(policy.dmRanks);
    let firstMessage = null;
    for (const discordId of reviewerIds) {
      const user = await client.users.fetch(discordId).catch(() => null);
      if (!user) continue;
      const dmMessage = await user.send({
        content: `Personal admin-abuse review required for **${incident.robloxUsername}** (${policy.requesterRankName}).`,
        embeds: [buildAdminAbuseEmbed(incident)],
        components: [buildAdminAbuseRow(incident)],
        allowedMentions: { parse: [] },
      }).catch(error => {
        console.error(`[AdminAbuse] Failed to DM reviewer ${discordId}:`, error.message);
        return null;
      });
      if (dmMessage && !firstMessage) firstMessage = dmMessage;
    }
    if (!firstMessage) throw new Error("No eligible personal admin-abuse reviewers could be DMed.");
    incident.channelId = firstMessage.channel.id;
    incident.messageId = firstMessage.id;
    await incident.save();
    return firstMessage;
  }

  const channel = await client.channels.fetch(policy.channelId).catch(() => null);
  if (!channel?.isTextBased?.()) throw new Error("Admin abuse review channel is unavailable.");
  const roleIds = [...new Set(policy.pingRoleIds || [])].filter(Boolean);
  const message = await channel.send({
    content: `${roleIds.map(roleId => `<@&${roleId}>`).join(" ")} Immediate ${policy.reviewRankLabel} admin-abuse review required.`.trim(),
    embeds: [buildAdminAbuseEmbed(incident)],
    components: [buildAdminAbuseRow(incident)],
    allowedMentions: { roles: roleIds },
  });
  incident.channelId = channel.id;
  incident.messageId = message.id;
  await incident.save();
  return message;
}

async function appendBanRecordUpdate(record, title, details) {
  if (!record?.forumThreadId) return;
  const thread = await client.channels.fetch(record.forumThreadId).catch(() => null);
  if (!thread?.isThread?.()) return;
  if (thread.archived) await thread.setArchived(false).catch(() => {});
  await thread.send({
    embeds: [
      new EmbedBuilder()
        .setColor(0x57f287)
        .setTitle(title)
        .setDescription(details)
        .setTimestamp(),
    ],
  }).catch(() => {});
}

