// ─────────────────────────────────────────────────────────────
// POST /auth/roblox
// Called by the workspace frontend after Roblox OAuth redirect.
// Exchanges the auth code for tokens, fetches the user's profile,
// checks their rank in the group, and returns user info if allowed.
// ─────────────────────────────────────────────────────────────
app.post('/auth/roblox', async (req, res) => {
  const { code, redirect_uri, code_verifier } = req.body;

  if (!code || !redirect_uri) {
    return res.status(400).json({ message: 'Missing code or redirect_uri' });
  }

  try {
    // ── Step 1: Exchange auth code for access token ────────────
    const tokenParams = new URLSearchParams({
      client_id:     '5921203059028403765',
      client_secret: process.env.ROBLOX_OAUTH_SECRET,  // add this to your .env
      grant_type:    'authorization_code',
      code,
      redirect_uri,
    });
    // If PKCE was used (it is), include the verifier
    if (code_verifier) tokenParams.set('code_verifier', code_verifier);

    const tokenRes = await axios.post(
      'https://apis.roblox.com/oauth/v1/token',
      tokenParams.toString(),
      { headers: { 'Content-Type': 'application/x-www-form-urlencoded' } }
    );

    const { access_token } = tokenRes.data;
    if (!access_token) throw new Error('No access_token in Roblox response');

    // ── Step 2: Fetch user profile (username, avatar, userId) ──
    const userInfoRes = await axios.get('https://apis.roblox.com/oauth/v1/userinfo', {
      headers: { Authorization: `Bearer ${access_token}` }
    });

    const {
      sub: userId,           // Roblox user ID (as string)
      preferred_username: name,
      name: displayName,
      picture: avatar,
    } = userInfoRes.data;

    // ── Step 3: Check group rank ───────────────────────────────
    const groupId = config.GROUP_ID || '33358685';
    const rankRes = await axios.get(
      `https://groups.roblox.com/v2/users/${userId}/groups/roles`,
      { headers: { 'Content-Type': 'application/json' } }
    );

    const groupEntries = (rankRes.data?.data || []).filter(
      g => String(g.group?.id) === String(groupId)
    );

    // Pick the highest rank the user holds (multi-role support)
    const topEntry  = groupEntries.reduce((best, g) =>
      (g.role?.rank ?? 0) > (best?.role?.rank ?? -1) ? g : best, null
    );

    const rank     = topEntry?.role?.rank ?? 0;
    const rankName = topEntry?.role?.name ?? 'Guest';
    const minRank  = 9;

    if (rank < minRank) {
      return res.status(403).json({
        message: `Access denied. Rank ${rank} (${rankName}) is below the required rank ${minRank}.`
      });
    }

    // ── Step 4: Issue a portal session token and return the profile ──
    // The frontend must send this back as `Authorization: Bearer <token>`; the
    // rank below is the server-verified rank and is what the protected routes
    // trust, never a value supplied by the client.
    const tokenExpiresAt = Date.now() + PORTAL_TOKEN_TTL_MS;
    const token = signPortalToken({
      r: String(userId),
      n: name,
      k: rank,
      exp: tokenExpiresAt,
    });
    if (!token) {
      console.error('[Workspace] Login succeeded but no portal token could be signed — check PORTAL_SESSION_SECRET.');
    }

    console.log(`[Workspace] Login: ${name} (${userId}) — rank ${rank} (${rankName})`);

    return res.json({
      id:          userId,
      name,
      displayName,
      rank,
      rankName,
      avatar:      avatar || '',
      token,
      tokenExpiresAt: token ? new Date(tokenExpiresAt).toISOString() : null,
    });

  } catch (err) {
    console.error('[Workspace] /auth/roblox error:', err?.response?.data || err.message);
    const status = err?.response?.status || 500;
    return res.status(status).json({
      message: err?.response?.data?.message || 'Authentication failed'
    });
  }
});


// ─────────────────────────────────────────────────────────────
// GET /activity?groupId=...
// Returns the full staff activity leaderboard for the workspace.
// Pulls from your existing activityData Map that the bot already
// maintains via /api/track-activity.
// ─────────────────────────────────────────────────────────────
app.get('/activity', requirePortalOrApiKey, async (req, res) => {
  try {
    // activityData is your existing Map<username, { dailyActivity, ... }>
    // We build a leaderboard from it.
    const now    = new Date();
    const year   = now.getFullYear();
    const month  = now.getMonth() + 1;

    // Get start of current week (Monday)
    const dayOfWeek    = now.getDay() === 0 ? 7 : now.getDay(); // Mon=1 … Sun=7
    const weekStart    = new Date(now);
    weekStart.setDate(now.getDate() - (dayOfWeek - 1));
    weekStart.setHours(0, 0, 0, 0);

    const result = [];

    for (const [username, data] of activityData.entries()) {
      let weekMin  = 0;
      let monthMin = 0;
      let sessions = 0;

      const prefix = `${year}-${String(month).padStart(2, '0')}-`;

      for (const [dateStr, minutes] of Object.entries(data.dailyActivity || {})) {
        const d = new Date(dateStr);
        // Monthly total
        if (dateStr.startsWith(prefix)) monthMin += minutes;
        // Weekly total
        if (d >= weekStart) weekMin += minutes;
      }

      // Count sessions from sessionLog if you have it
      // sessions = (data.sessions || []).filter(s => new Date(s.date) >= weekStart).length;

      // Try to get their rank from Roblox group (cached lookup)
      let rankName = 'Staff';
      let rankNum  = 0;
      try {
        const userId = await getRobloxUserId(username); // reuse your existing helper
        if (userId) {
          const rRes = await axios.get(
            `https://groups.roblox.com/v2/users/${userId}/groups/roles`
          );
          const entries = (rRes.data?.data || []).filter(
            g => String(g.group?.id) === String(config.GROUP_ID || '33358685')
          );
          const top = entries.reduce((best, g) =>
            (g.role?.rank ?? 0) > (best?.role?.rank ?? -1) ? g : best, null
          );
          if (top) { rankName = top.role.name; rankNum = top.role.rank; }
        }
      } catch (_) {}

      // Only include actual group members
      if (rankNum > 0 || weekMin > 0) {
        // Quota % — derived from QUOTA_CONFIG
        const required = QUOTA_CONFIG.REQUIREMENTS[rankNum] ? QUOTA_CONFIG.REQUIREMENTS[rankNum].mins : null;
        const quota    = required ? Math.round((weekMin / required) * 100) : null;

        result.push({ name: username, rank: rankName, weekMin, monthMin, sessions, quota });
      }
    }

    // Sort by weekMin descending
    result.sort((a, b) => b.weekMin - a.weekMin);
    return res.json(result);

  } catch (err) {
    console.error('[Workspace] /activity error:', err.message);
    return res.status(500).json({ error: 'Internal server error' });
  }
});


// ─────────────────────────────────────────────────────────────
// POST /logbook
// Saves a log action (warning, suspension, etc.) and posts it
// to your existing punishment log Discord channel.
// ─────────────────────────────────────────────────────────────
app.post('/logbook', requirePortalOrApiKey, async (req, res) => {
  const { target, action, reason, duration, evidence, issuedBy } = req.body;

  if (!target || !action || !reason) {
    return res.status(400).json({ message: 'Missing target, action, or reason' });
  }

  // Attribution always comes from the authenticated caller, never the body.
  const actor = req.auth?.kind === 'portal' ? req.auth.label : (issuedBy || req.auth?.label || 'N/A');

  try {
    // ── Post to Discord punishment log channel ─────────────────
    const ACTION_COLORS = {
      Warning:       0xfbbf24,
      Suspension:    0xf87171,
      Demotion:      0xa78bfa,
      Termination:   0xef4444,
      Strike:        0xfb923c,
      Commendation:  0x4ade80,
      Blacklist:     0x991b1b,
    };

    const embed = new EmbedBuilder()
      .setTitle(`📋 ${action} — ${target}`)
      .setColor(ACTION_COLORS[action] ?? 0xaaaaaa)
      .addFields(
        { name: 'Staff Member', value: target,             inline: true },
        { name: 'Action',       value: action,             inline: true },
        { name: 'Issued By',    value: actor,             inline: true },
        { name: 'Reason',       value: reason,             inline: false },
      )
      .setTimestamp();

    if (duration) embed.addFields({ name: 'Duration', value: duration, inline: true });
    if (evidence) embed.addFields({ name: 'Evidence', value: evidence, inline: false });

    const channel = await client.channels.fetch(config.PUNISHMENT_LOG_CHANNEL_ID).catch(() => null);
    if (channel) await channel.send({ embeds: [embed] }).catch(() => {});

    console.log(`[Workspace] Logbook: ${action} on ${target} by ${actor}`);
    return res.json({ success: true });

  } catch (err) {
    console.error('[Workspace] /logbook error:', err.message);
    return res.status(500).json({ message: 'Failed to log action' });
  }
});


// ─  ───────────────────────────────────────────────────────────
// POST /rank
// Ranks a member in the Roblox group from the workspace UI.
// Reuses your existing rank logic.
// ──────────────────────────────────────────────────────  ──────
app.post('/rank', requirePortalOrApiKey, async (req, res) => {
  const { username, rank, reason } = req.body;

  if (!username || !rank) {
    return res.status(400).json({ message: 'Missing username or rank' });
  }

  // A portal session may only rank if its server-verified Roblox rank is high
  // enough. API-key callers (game server / internal jobs) skip this gate.
  if (req.auth?.kind === 'portal' && Number(req.auth.rank || 0) < config.MIN_RANK_TO_USE_COMMANDS) {
    return res.status(403).json({
      message: `Rank ${req.auth.rank || 0} is below the required rank ${config.MIN_RANK_TO_USE_COMMANDS} for rank changes.`,
    });
  }
  // Attribution always comes from the authenticated caller, never the body.
  const issuedBy = req.auth?.kind === 'portal'
    ? req.auth.label
    : (req.body.issuedBy || req.auth?.label || 'N/A');

  try {
    // Accept "Supervisor (Rank 10)" or a bare number.
    const rankMatch = String(rank).match(/Rank\s*(\d+)/i) || String(rank).match(/^(\d+)$/);
    if (!rankMatch) return res.status(400).json({ message: 'Could not parse rank number from: ' + rank });
    const rankNumber = parseInt(rankMatch[1], 10);

    const userId = await getRobloxUserId(username);
    if (!userId) return res.status(404).json({ message: `User '${username}' not found on Roblox` });

    // One canonical path for every rank change: Open Cloud
    // UpdateGroupMembership (verified), legacy cookie PATCH only as fallback.
    const result = await applyRobloxRank({ userId, rank: rankNumber });
    if (!result.ok) {
      console.error(`[Workspace] /rank failed for ${username} (rank ${rankNumber}): ${result.error}`);
      return res.status(502).json({
        message: `Roblox rank change failed: ${result.error || 'unknown error'}`,
        appliedVia: result.method,
      });
    }

    const newRankLabel = result.role ? `${result.role.name} (Rank ${result.role.rank})` : String(rank);

    // Log to Discord ranking channel
    const embed = new EmbedBuilder()
      .setTitle('🔼 Rank Change — Workspace')
      .setColor(0x60a5fa)
      .addFields(
        { name: 'Target',      value: username,         inline: true },
        { name: 'New Rank',    value: newRankLabel,     inline: true },
        { name: 'Issued By',   value: issuedBy,         inline: true },
        { name: 'Reason',      value: reason || 'N/A',  inline: false },
        { name: 'Applied Via', value: result.method || 'unknown', inline: true },
      )
      .setTimestamp();

    const channel = await client.channels.fetch(config.RANKING_LOG_CHANNEL_ID).catch(() => null);
    if (channel) await channel.send({ embeds: [embed] }).catch(() => {});

    console.log(`[Workspace] Rank: ${username} → ${newRankLabel} by ${issuedBy} via ${result.method}`);
    return res.json({
      success: true,
      appliedVia: result.method,
      rank: result.rank,
      roleId: result.role?.id || null,
      leftoverRoles: (result.leftoverRoles || []).map(role => role.name),
    });

  } catch (err) {
    console.error('[Workspace] /rank error:', err?.response?.data || err.message);
    return res.status(500).json({ message: 'Ranking failed: ' + (err?.response?.data?.message || err.message) });
  }
});


// ─────────────────────────────────────────────────────────────
// Helper: get the Roblox roleId for a given rank number in your group
// ─────────────────────────────────────────────────────────────
// Rank -> roleId resolution is delegated to the shared group-role service
// (Open Cloud first, legacy v1 fallback) so role ids always match the group's
// current role list instead of a stale unauthenticated fetch.
async function getRoleIdForRank(rankNumber) {
  const role = await resolveGroupRoleByRank(rankNumber);
  if (!role) throw new Error(`No role found with rank number ${rankNumber}`);
  return role.id;
}


app.post('/api/update-server-status', validateApiKey, async (req, res) => {
  const { jobId, players, staff } = req.body;
  bakeryServers.set(jobId, {
    playerCount: players,
    staffCount: staff,
    lastUpdate: Date.now()
  });

  // INTELLIGENCE: Auto-Alert if server is understaffed
  // If more than 10 players but 0 staff
  if (players >= 10 && staff === 0) {
    const alertChannel = client.channels.cache.get(LOW_COVERAGE_ALERT_CHANNEL_ID);
    if (alertChannel) {
      alertChannel.send(`⚠️ **LOW COVERAGE ALERT:** Server \`${jobId.substring(0, 8)}\` has **${players} customers** and **0 staff**! Join now for 2x points!`);
    }
  }
  res.json({ success: true });
});

// Log when a banned user attempts to join (optional - for tracking)
app.post('/api/log-ban-attempt', validateApiKey, async (req, res) => {
  try {
    const { userId, username, game } = req.body;

    if (!userId || !game) {
      return res.status(400).json({
        success: false,
        error: 'Missing required fields: userId, game'
      });
    }

    console.log(`🚫 Banned user ${username || userId} attempted to join ${game}`);

    // Create a case record for the attempt
    const caseRecord = nextCase(
      'BannedUserAttempt',
      'system',
      userId,
      `Banned user attempted to join ${game}`,
      { username, game, attemptTime: new Date().toISOString() }
    );

    return res.json({
      success: true,
      logged: true,
      caseId: caseRecord.caseId
    });

  } catch (error) {
    console.error('Log ban attempt error:', error);
    return res.status(500).json({
      success: false,
      error: 'Internal server error'
    });
  }
});

