// ── GET /api/rank ─────────────────────────────────────────────────────────
app.get("/api/rank", async (req, res) => {
  const apiKey = req.headers["x-api-key"];
  if (!apiKey || apiKey !== config.HTTP_API_KEY) return res.status(401).json({ error: "Unauthorized" });
  const { discordId } = req.query;
  if (!discordId) return res.status(400).json({ error: "Missing discordId" });
  const robloxUsername = verifiedUsers.get(discordId);
  if (!robloxUsername) return res.status(404).json({ error: "not_verified" });
  try {
    const userId = await getRobloxUserId(robloxUsername);
    const rankInfo = await getUserRankInGroup(userId);
    if (!rankInfo) return res.status(404).json({ error: "Not in group" });
    return res.json({ rankId: rankInfo.rank, rankName: rankInfo.name, robloxUsername });
  } catch (err) {
    return res.status(500).json({ error: "Roblox API error" });
  }
});
 
// ============================================================================
// SWEETSIEZ OFFICE - IDENTITY BRIDGE (read-only, plus one admin mapping write)
//
// Sweetsiez Office (the Supabase-backed document platform) has to know which
// Roblox account a signed-in @sweetsiez.com address belongs to. It must never
// work that out for itself: every identity fact lives here, in the
// `verifiedusers` collection that /verify, in-game verification and
// /manualverify write.
//
// Two routes are the entire surface the Office may call. Neither writes a rank,
// a link, a profile or an audit row:
//
//   GET /api/office/identity?email=<address>  email -> verified Roblox identity
//   GET /api/office/rank/:robloxId            current group rank for a Roblox id
//
// The one write in this file is setOfficeEmailRecord(), used by the
// !officeemail command to record which address a member was actually issued.
// It changes no rank and no Roblox link - only the address -> member mapping.
//
// Auth: a dedicated OFFICE_SERVICE_KEY header, deliberately NOT HTTP_API_KEY.
// The game server holds HTTP_API_KEY inside a Roblox place; that credential
// must never be able to reach a web service. With OFFICE_SERVICE_KEY unset the
// routes fail closed with 503 rather than falling back to anything.
//
// Resolution order, most authoritative first:
//   1. an address explicitly recorded against a member  (email_recorded)
//   2. an address whose local part IS the Roblox username (email_exact)
//   3. an address whose local part is a FORMER username  (email_former_username)
//   4. otherwise                                        (not_found)
//
// Nothing here guesses. A local part that merely resembles a username never
// matches: the President's address is sabrinacarpentxr@sweetsiez.com and their
// Roblox username is carpentxr, which is exactly why order (1) exists.
//
// The host's panel console cannot run commands, so logOfficeIdentityBridgeStatus()
// prints the bridge's state at startup (and optionally one real lookup when
// OFFICE_TEST_EMAIL is set). That console line is how the deployment is verified.
// ============================================================================

const OFFICE_EMAIL_DOMAIN = "sweetsiez.com";

// Roblox usernames are 3-20 characters drawn from A-Z, a-z, 0-9 and underscore.
const OFFICE_ROBLOX_USERNAME_PATTERN = /^[A-Za-z0-9_]{3,20}$/;
// A Workspace address is looser: dots, dashes and longer local parts are legal
// and simply mean "this can never be a plain Roblox username match".
const OFFICE_EMAIL_LOCAL_PATTERN = /^[a-z0-9._-]{1,64}$/;

/**
 * Validate a @sweetsiez.com address and extract the part before the @.
 *
 * This is the *only* address validation in the bridge. It deliberately does not
 * reject addresses that cannot be Roblox usernames - the President's address is
 * one - it only reports whether the local part could double as one, which
 * decides whether the username convention may be tried at all.
 */
function normalizeOfficeEmail(rawEmail) {
  const raw = String(rawEmail == null ? "" : rawEmail).trim();
  if (!raw) return { ok: false, reason: "missing_email" };

  const atIndex = raw.lastIndexOf("@");
  if (atIndex <= 0 || atIndex === raw.length - 1) {
    return { ok: false, reason: "malformed_email" };
  }

  const localPart = raw.slice(0, atIndex).trim();
  const domain = raw.slice(atIndex + 1).trim().toLowerCase();

  if (domain !== OFFICE_EMAIL_DOMAIN) return { ok: false, reason: "wrong_domain" };
  // A +tag is a legal Google alias but is never the address that was issued, so
  // accepting one would let a member present an address they do not hold.
  if (localPart.includes("+")) return { ok: false, reason: "plus_addressing_not_allowed" };

  const normalizedLocal = localPart.toLowerCase();
  if (!OFFICE_EMAIL_LOCAL_PATTERN.test(normalizedLocal)) {
    return { ok: false, reason: "malformed_email" };
  }

  return {
    ok: true,
    localPart: normalizedLocal,
    domain,
    email: `${normalizedLocal}@${OFFICE_EMAIL_DOMAIN}`,
    robloxUsernameShaped: OFFICE_ROBLOX_USERNAME_PATTERN.test(localPart),
  };
}

/**
 * Decide what a set of verification rows proves.
 *
 * `robloxId` is the stable identity. Several Discord accounts may legitimately
 * link to one Roblox account, so more than one row for a username means the
 * *Roblox* identity is still certain while the *Discord* identity is not - that
 * is reported as a candidate list, never resolved by picking one.
 *
 * Two rows that disagree about the Roblox id means the store contradicts
 * itself; nothing may be inferred from it.
 */
function classifyOfficeEmailMatch({ exactRows = [], formerRows = [], matchedVia = null } = {}) {
  const clean = rows => (Array.isArray(rows) ? rows.filter(Boolean) : []);
  const exact = clean(exactRows);
  const former = clean(formerRows);

  const empty = {
    status: "not_found",
    matchedVia: null,
    rows: [],
    robloxUserId: null,
    robloxUsername: null,
    discordUserIds: [],
    discordUserId: null,
  };
  if (exact.length === 0 && former.length === 0) return empty;

  const resolvedMatchedVia = matchedVia || (exact.length > 0 ? "email_exact" : "email_former_username");
  const rows = exact.length > 0 ? exact : former;

  const distinct = values => [...new Set(values)];
  const robloxIds = distinct(rows.map(row => String(row.robloxId || "").trim()).filter(Boolean));
  const discordUserIds = distinct(rows.map(row => String(row.discordId || "").trim()).filter(Boolean));

  if (robloxIds.length > 1) {
    return {
      status: "ambiguous_roblox_account",
      matchedVia: resolvedMatchedVia,
      rows,
      robloxUserId: null,
      robloxUsername: null,
      discordUserIds,
      discordUserId: null,
    };
  }

  if (robloxIds.length === 0) {
    // A verified row whose cached Roblox id was never backfilled. The username
    // is known, so the caller may resolve the id live; nothing is assumed here.
    // The single-Discord case is still certain, so it is reported.
    return {
      status: "roblox_id_missing",
      matchedVia: resolvedMatchedVia,
      rows,
      robloxUserId: null,
      robloxUsername: rows[0].robloxUsername || null,
      discordUserIds,
      discordUserId: discordUserIds.length === 1 ? discordUserIds[0] : null,
    };
  }

  return {
    status: exact.length > 0 ? "verified" : "verified_former_username",
    matchedVia: resolvedMatchedVia,
    rows,
    robloxUserId: robloxIds[0],
    robloxUsername: rows[0].robloxUsername || null,
    discordUserIds,
    discordUserId: discordUserIds.length === 1 ? discordUserIds[0] : null,
  };
}

/**
 * Translate a group-membership read into a membership verdict.
 *
 * A failed Roblox read is "unknown", never "not in the group": an outage must
 * not be allowed to look like a termination.
 */
function classifyOfficeMembership(membership, rankLadderEntry = null) {
  if (!membership || membership.ok !== true) {
    return { status: "unknown", inGroup: null, rankValue: null, rankName: null, rankLadderName: null, robloxRoleId: null };
  }
  if (membership.inGroup !== true) {
    return { status: "left_group", inGroup: false, rankValue: null, rankName: null, rankLadderName: null, robloxRoleId: null };
  }

  const rankValue = Number.isFinite(Number(membership.rank)) ? Number(membership.rank) : 0;
  return {
    status: "in_group",
    inGroup: true,
    rankValue,
    // The group role name is authoritative (it is what Roblox actually holds);
    // the ladder name is reported alongside it so a rename shows up as a
    // mismatch instead of being silently trusted.
    rankName: membership.name || null,
    rankLadderName: rankLadderEntry ? rankLadderEntry.name || null : null,
    robloxRoleId: membership.id ? String(membership.id) : null,
  };
}

/** Assemble the JSON body the Office consumes. No rank is ever invented here. */
function buildOfficeIdentityPayload({ email = null, match, membership = null, observedAt = new Date() } = {}) {
  const resolvedMatch = match || classifyOfficeEmailMatch({});
  const resolvedMembership = membership || classifyOfficeMembership(null);
  return {
    ok: true,
    email,
    verificationStatus: resolvedMatch.status,
    matchedVia: resolvedMatch.matchedVia,
    robloxUserId: resolvedMatch.robloxUserId,
    robloxUsername: resolvedMatch.robloxUsername,
    discordUserId: resolvedMatch.discordUserId || null,
    discordUserIds: resolvedMatch.discordUserIds || [],
    membershipStatus: resolvedMembership.status,
    rankValue: resolvedMembership.rankValue,
    rankName: resolvedMembership.rankName,
    rankLadderName: resolvedMembership.rankLadderName,
    robloxRoleId: resolvedMembership.robloxRoleId || null,
    // True when the stored row had no cached Roblox id and this answer came from
    // resolving the username live. It is a data-quality signal, never a reason to
    // doubt the identity: verificationStatus already accounts for it.
    robloxIdResolvedLive: Boolean(resolvedMatch.robloxIdResolvedLive),
    observedAt: observedAt instanceof Date ? observedAt.toISOString() : String(observedAt),
  };
}

/**
 * The complete email -> identity resolution, shared by the HTTP route and the
 * startup self-check so the two can never drift apart.
 *
 * Returns { statusCode, body } and never throws.
 */
async function resolveOfficeIdentityByEmail(rawEmail) {
  const normalized = normalizeOfficeEmail(rawEmail);
  if (!normalized.ok) {
    return { statusCode: 400, body: { ok: false, error: normalized.reason } };
  }

  // (1) An address explicitly recorded against a member beats every inference.
  const recordedRows = await VerifiedUser
    .find({ officeEmailLower: normalized.email })
    .lean()
    .catch(() => null);
  if (recordedRows === null) {
    return { statusCode: 500, body: { ok: false, error: "identity_store_unavailable" } };
  }

  let match = null;

  if (Array.isArray(recordedRows) && recordedRows.length > 0) {
    match = classifyOfficeEmailMatch({ exactRows: recordedRows, matchedVia: "email_recorded" });

    // A recorded address that collides with a *different* member's username is a
    // data-entry accident worth seeing, not something to silently prefer.
    if (normalized.robloxUsernameShaped && match.robloxUserId) {
      const conventionRows = await VerifiedUser
        .find({ robloxUsernameLower: normalized.localPart })
        .lean()
        .catch(() => []);
      const conventionIds = new Set(
        (Array.isArray(conventionRows) ? conventionRows : [])
          .map(row => String(row.robloxId || "").trim())
          .filter(Boolean),
      );
      if (conventionIds.size > 0 && !conventionIds.has(String(match.robloxUserId))) {
        console.warn(
          `[Office] ${normalized.email} is recorded for Roblox ${match.robloxUserId} but also matches ` +
          `the username of Roblox ${[...conventionIds].join(", ")} - the recorded address wins.`,
        );
      }
    }
  } else if (normalized.robloxUsernameShaped) {
    // (2) The convention: local part === Roblox username.
    const exactRows = await VerifiedUser
      .find({ robloxUsernameLower: normalized.localPart })
      .lean()
      .catch(() => null);
    if (exactRows === null) {
      return { statusCode: 500, body: { ok: false, error: "identity_store_unavailable" } };
    }

    let formerRows = [];
    if (exactRows.length === 0) {
      // previousUsernames keeps the casing it was stored with, so match the
      // local part case-insensitively. The local part carries no regex
      // metacharacter by this point.
      const found = await VerifiedUser
        .find({ previousUsernames: { $regex: `^${normalized.localPart}$`, $options: "i" } })
        .lean()
        .catch(() => null);
      formerRows = Array.isArray(found) ? found : [];
    }

    match = classifyOfficeEmailMatch({ exactRows, formerRows });
  } else {
    // A real-looking address that is neither recorded nor a username. There is
    // nothing to look up, and no Roblox request is worth making.
    match = classifyOfficeEmailMatch({});
  }

  // Resolve the one hole a stored row can have: a verified row that was never
  // backfilled with its Roblox id. The username is known, so ask Roblox once
  // rather than reporting an identity we could have resolved.
  //
  // Once resolved, the verification IS established - so the status becomes
  // "verified" and the cache gap is reported separately as robloxIdResolvedLive.
  // Leaving it as "roblox_id_missing" would make a consumer treat a confirmed
  // President as unverified. Only a row whose id cannot be resolved at all keeps
  // that status, and only then is there no identity to report.
  let robloxUserId = match.robloxUserId;
  if (!robloxUserId && match.status === "roblox_id_missing" && match.robloxUsername) {
    const resolved = await getRobloxUserId(match.robloxUsername).catch(() => null);
    if (resolved) {
      robloxUserId = String(resolved);
      match.robloxUserId = robloxUserId;
      match.status = match.matchedVia === "email_former_username"
        ? "verified_former_username"
        : "verified";
      match.robloxIdResolvedLive = true;
    }
  }

  if (!robloxUserId) {
    return { statusCode: 200, body: buildOfficeIdentityPayload({ email: normalized.email, match }) };
  }

  const membership = await getMainGroupMembershipStatus(robloxUserId).catch(() => null);
  const membershipView = classifyOfficeMembership(
    membership,
    getRankLadderEntry(membership && membership.rank),
  );

  return {
    statusCode: 200,
    body: buildOfficeIdentityPayload({
      email: normalized.email,
      match,
      membership: membershipView,
    }),
  };
}

/**
 * Record (or clear) which Workspace address a member was issued.
 *
 * This is the only write in the bridge, and it is deliberately narrow: it sets
 * four fields on an existing verification row and never touches the Roblox
 * identity, the rank, roles or placements. A member must already be verified -
 * an address cannot create a member.
 *
 * `email` may be the literal "clear" to remove a wrong entry.
 * Returns { ok, reason? , email?, robloxUsername?, cleared? } and never throws.
 */
async function setOfficeEmailRecord({ discordId, email, actorId = null } = {}) {
  const target = String(discordId || "").trim();
  if (!target) return { ok: false, reason: "missing_member" };

  const clear = String(email == null ? "" : email).trim().toLowerCase() === "clear";
  const normalized = clear ? null : normalizeOfficeEmail(email);
  if (!clear && !normalized.ok) return { ok: false, reason: normalized.reason };

  const row = await VerifiedUser.findOne({ discordId: target }).lean().catch(() => null);
  if (!row) return { ok: false, reason: "member_not_verified" };

  if (clear) {
    await VerifiedUser.updateOne(
      { discordId: target },
      { $unset: { officeEmail: "", officeEmailLower: "" }, $set: { officeEmailSetBy: String(actorId || ""), officeEmailSetAt: new Date() } },
    );
    return { ok: true, cleared: true, robloxUsername: row.robloxUsername || null };
  }

  await VerifiedUser.updateOne(
    { discordId: target },
    {
      $set: {
        officeEmail: normalized.email,
        officeEmailLower: normalized.email,
        officeEmailSetBy: String(actorId || ""),
        officeEmailSetAt: new Date(),
      },
    },
  );

  return { ok: true, cleared: false, email: normalized.email, robloxUsername: row.robloxUsername || null };
}

/**
 * Printed once at startup so the hosting panel's console - the only output a
 * bot host without a shell gives you - shows whether the bridge is actually
 * live. Set OFFICE_TEST_EMAIL to also run one real lookup through it.
 *
 * Never throws and never writes anything.
 */
async function logOfficeIdentityBridgeStatus() {
  const enabled = Boolean(getOfficeServiceKey());
  const groupId = config && config.GROUP_ID ? String(config.GROUP_ID) : null;

  console.log(
    `[Office] identity bridge ${enabled ? "ENABLED" : "DISABLED (set OFFICE_SERVICE_KEY)"}` +
    ` | group ${groupId || "MISSING (set GROUP_ID)"}` +
    ` | routes /api/office/identity, /api/office/rank/:robloxId`,
  );
  if (!groupId) {
    console.warn("[Office] GROUP_ID is not set - every rank lookup returns null. Set GROUP_ID=33358685.");
  }
  if (!enabled) return { enabled: false, groupId, result: null };

  const testEmail = String(process.env.OFFICE_TEST_EMAIL || "").trim();
  if (!testEmail) return { enabled: true, groupId, result: null };

  if (!mongoose || mongoose.connection.readyState !== 1) {
    console.warn("[Office] self-check skipped: MongoDB is not connected.");
    return { enabled: true, groupId, result: null };
  }

  const result = await resolveOfficeIdentityByEmail(testEmail);
  console.log(`[Office] self-check ${testEmail} -> HTTP ${result.statusCode} ${JSON.stringify(result.body)}`);
  return { enabled: true, groupId, testEmail, result };
}

function getOfficeServiceKey() {
  const value = process.env.OFFICE_SERVICE_KEY;
  return typeof value === "string" && value.trim() ? value.trim() : null;
}

/** Constant-time comparison, so a wrong key cannot be narrowed by timing. */
function officeServiceKeyMatches(provided, expected) {
  const given = Buffer.from(String(provided == null ? "" : provided), "utf8");
  const want = Buffer.from(String(expected == null ? "" : expected), "utf8");
  if (given.length === 0 || given.length !== want.length) return false;
  return crypto.timingSafeEqual(given, want);
}

function requireOfficeServiceKey(req, res, next) {
  const expected = getOfficeServiceKey();
  if (!expected) {
    console.error("[Office] OFFICE_SERVICE_KEY is not set - /api/office/* is disabled.");
    return res.status(503).json({ ok: false, error: "office_integration_disabled" });
  }

  const headers = req.headers || {};
  const headerKey = headers["x-office-key"];
  const authorization = headers.authorization;
  const bearer = typeof authorization === "string" && authorization.startsWith("Bearer ")
    ? authorization.slice(7)
    : null;
  const provided = headerKey || bearer;

  if (!provided || !officeServiceKeyMatches(provided, expected)) {
    return res.status(401).json({ ok: false, error: "unauthorized" });
  }
  return next();
}

// GET /api/office/identity?email=exampleusername@sweetsiez.com
// Read-only. Resolves the address to a verified Roblox identity and its
// current group membership. Never creates, links or ranks anything.
app.get("/api/office/identity", requireOfficeServiceKey, async (req, res) => {
  try {
    const { statusCode, body } = await resolveOfficeIdentityByEmail(req.query ? req.query.email : null);
    return res.status(statusCode).json(body);
  } catch (error) {
    console.error("[Office] identity lookup failed:", error.message);
    return res.status(500).json({ ok: false, error: "identity_lookup_failed" });
  }
});

// GET /api/office/rank/:robloxId
// Read-only. The reconciler half of the bridge: given a Roblox id the Office
// already trusts, report the member's live group rank. Uses the bot's existing
// 20-second membership cache, so a batch reconcile stays cheap.
app.get("/api/office/rank/:robloxId", requireOfficeServiceKey, async (req, res) => {
  try {
    const rawId = String((req.params && req.params.robloxId) || "").trim();
    if (!/^[0-9]{1,20}$/.test(rawId)) {
      return res.status(400).json({ ok: false, error: "invalid_roblox_user_id" });
    }

    const membership = await getMainGroupMembershipStatus(rawId).catch(() => null);
    const membershipView = classifyOfficeMembership(
      membership,
      getRankLadderEntry(membership && membership.rank),
    );

    return res.json({
      ok: true,
      robloxUserId: rawId,
      membershipStatus: membershipView.status,
      rankValue: membershipView.rankValue,
      rankName: membershipView.rankName,
      rankLadderName: membershipView.rankLadderName,
      robloxRoleId: membershipView.robloxRoleId,
      observedAt: new Date().toISOString(),
    });
  } catch (error) {
    console.error("[Office] rank lookup failed:", error.message);
    return res.status(500).json({ ok: false, error: "rank_lookup_failed" });
  }
});

// ============================================================================
// OFFICE SYNC - the bot pushes into Supabase
//
// The Office is on Cloudflare and this bot sits on a consumer connection with no
// TLS, so the Office does NOT call the bot: putting OFFICE_SERVICE_KEY on a
// plain-HTTP wire would hand it to anyone on the path. The bot instead makes
// OUTBOUND https calls, which work from behind any NAT, any rotating IP.
//
// Every OFFICE_SYNC_INTERVAL_MS the bot:
//   1. asks Supabase which members still need attention  (office_identity_work)
//   2. resolves each one with the SAME resolver the HTTP route uses
//   3. writes the answer back                            (office_apply_identity)
//
// It reports FACTS only - identity, membership, employment, rank. Eligibility is
// derived inside the SQL function, so it can never be set by the caller and
// never depends on a rank number handed in from outside.
//
// The HTTP routes above stay: they are how this is diagnosed by hand.
// ============================================================================

const OFFICE_SYNC_INTERVAL_MS = 90 * 1000;
const OFFICE_SYNC_BATCH = 15;
const OFFICE_SYNC_TIMEOUT_MS = 15000;

/** Supabase credentials, or null when the sync is not configured. */
function getOfficeSupabaseConfig() {
  const url = String(process.env.SUPABASE_URL || "").trim().replace(/\/+$/, "");
  const key = String(process.env.SUPABASE_SERVICE_ROLE_KEY || "").trim();
  if (!url || !key) return null;
  return { url, key };
}

/**
 * One PostgREST call. Always resolves to { ok, status?, json?, reason? } and
 * never throws, so a network blip can only ever skip a cycle.
 */
async function callOfficeSupabase(pathname, body) {
  const config = getOfficeSupabaseConfig();
  if (!config) return { ok: false, reason: "not_configured" };

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), OFFICE_SYNC_TIMEOUT_MS);
  try {
    const response = await fetch(`${config.url}${pathname}`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        apikey: config.key,
        authorization: `Bearer ${config.key}`,
      },
      body: JSON.stringify(body || {}),
      signal: controller.signal,
    });
    const text = await response.text();
    let json = null;
    if (text) {
      try { json = JSON.parse(text); } catch { json = null; }
    }
    if (!response.ok) {
      return { ok: false, status: response.status, reason: `http_${response.status}`, detail: text.slice(0, 300) };
    }
    return { ok: true, status: response.status, json, text };
  } catch (error) {
    return { ok: false, reason: "request_failed", detail: error.message };
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Employment and suspension, both of which the identity resolver does not know
 * about. Missing data is reported as unknown, never as "fine".
 *
 * Only staff carry a StaffProfile row, so "unknown" is the normal answer for an
 * everyday member and must NOT be treated as an ineligibility.
 */
async function getOfficeMemberContext(discordUserId) {
  const discordId = String(discordUserId || "").trim();
  if (!discordId) return { employmentStatus: "unknown", suspended: null };

  let employmentStatus = "unknown";
  try {
    const profile = await StaffProfile.findOne({ discordId }).lean();
    const status = profile && profile.status ? String(profile.status) : "";
    if (["employed", "resigned", "terminated", "closed"].includes(status)) {
      employmentStatus = status;
    }
  } catch (error) {
    console.warn("[Office] employment lookup failed:", error.message);
  }

  let suspended = null;
  try {
    const record = typeof suspensions.get === "function" ? suspensions.get(discordId) : null;
    if (!record) {
      suspended = false;
    } else {
      const end = record.endDate ? new Date(record.endDate).getTime() : NaN;
      suspended = Number.isFinite(end) ? end > Date.now() : true;
    }
  } catch (error) {
    console.warn("[Office] suspension lookup failed:", error.message);
  }

  return { employmentStatus, suspended };
}

/** Resolve one member and shape the arguments office_apply_identity expects. */
async function buildOfficeSyncArgs(profileId, email) {
  const { statusCode, body } = await resolveOfficeIdentityByEmail(email);
  if (statusCode !== 200 || !body || body.ok !== true) {
    return { ok: false, reason: body && body.error ? body.error : `resolver_${statusCode}` };
  }

  const context = await getOfficeMemberContext(body.discordUserId);

  return {
    ok: true,
    args: {
      p_profile_id: profileId,
      p_matched_email: body.email,
      p_verification_status: body.verificationStatus,
      p_matched_via: body.matchedVia,
      p_roblox_user_id: body.robloxUserId ? Number(body.robloxUserId) : null,
      p_roblox_username: body.robloxUsername,
      p_discord_user_id: body.discordUserId,
      p_discord_candidate_ids: Array.isArray(body.discordUserIds) ? body.discordUserIds : [],
      p_roblox_id_resolved_live: Boolean(body.robloxIdResolvedLive),
      p_membership_status: body.membershipStatus,
      p_employment_status: context.employmentStatus,
      p_suspended: context.suspended,
      p_rank_value: Number.isFinite(Number(body.rankValue)) ? Number(body.rankValue) : null,
      p_rank_name: body.rankName,
      p_rank_ladder_name: body.rankLadderName,
      p_roblox_role_id: body.robloxRoleId ? Number(body.robloxRoleId) : null,
      p_observed_at: body.observedAt,
    },
  };
}

/** One pass. Never throws; always leaves a one-line console record when it did work. */
async function runOfficeIdentitySync(triggeredBy = "scheduled") {
  if (!getOfficeSupabaseConfig()) return { skipped: true, reason: "not_configured" };

  const work = await callOfficeSupabase("/rest/v1/rpc/office_identity_work", { limit_count: OFFICE_SYNC_BATCH });
  if (!work.ok) {
    console.warn(`[Office] sync could not read the work queue (${work.reason}${work.detail ? `: ${work.detail}` : ""})`);
    return { skipped: true, reason: work.reason };
  }

  const queue = Array.isArray(work.json) ? work.json : [];
  if (queue.length === 0) return { processed: 0, applied: 0, failures: [] };

  let applied = 0;
  const failures = [];

  for (const item of queue) {
    const profileId = String((item && item.profile_id) || "").trim();
    const email = String((item && item.email) || "").trim();
    if (!profileId || !email) continue;

    const built = await buildOfficeSyncArgs(profileId, email);
    if (!built.ok) {
      failures.push(`${email} (${built.reason})`);
      continue;
    }

    const write = await callOfficeSupabase("/rest/v1/rpc/office_apply_identity", built.args);
    if (write.ok) {
      applied += 1;
      if (String((item && item.reason) || "") !== "refresh") {
        console.log(`[Office] sync ${email} -> ${built.args.p_verification_status}/${built.args.p_membership_status} rank ${built.args.p_rank_value ?? "none"}`);
      }
    } else {
      failures.push(`${email} (${write.reason}${write.detail ? `: ${write.detail}` : ""})`);
    }
  }

  const summary = `[Office] sync (${triggeredBy}): ${applied}/${queue.length} applied`;
  if (failures.length > 0) {
    console.warn(`${summary}, ${failures.length} failed - ${failures.join("; ")}`);
  } else {
    console.log(summary);
  }

  return { processed: queue.length, applied, failures };
}


/**
 * SWEETSIEZ OFFICE — department placement bridge.
 * MongoDB staffplacements remains authoritative; Supabase is a reconciled mirror.
 */
let officeDepartmentSyncRunning = false;

async function getOfficeRows(pathname) {
  const config = getOfficeSupabaseConfig();
  if (!config) return { ok: false, reason: "not_configured" };
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), OFFICE_SYNC_TIMEOUT_MS);
  try {
    const response = await fetch(config.url + pathname, {
      method: "GET",
      headers: { apikey: config.key, authorization: "Bearer " + config.key },
      signal: controller.signal,
    });
    const text = await response.text();
    let json = null;
    if (text) {
      try { json = JSON.parse(text); } catch { json = null; }
    }
    if (!response.ok) {
      return { ok: false, reason: "http_" + response.status, detail: text.slice(0, 300) };
    }
    return { ok: true, rows: Array.isArray(json) ? json : [] };
  } catch (error) {
    return { ok: false, reason: "request_failed", detail: error.message };
  } finally {
    clearTimeout(timer);
  }
}

async function getOfficeProfileIdByEmail(email) {
  const normalizedEmail = String(email || "").trim().toLowerCase();
  if (!normalizedEmail) return { ok: false, reason: "missing_email" };
  const result = await getOfficeRows(
    "/rest/v1/profiles?select=id,email&email=eq." +
    encodeURIComponent(normalizedEmail) + "&limit=2",
  );
  if (!result.ok) return result;
  if (result.rows.length !== 1 || !result.rows[0] || !result.rows[0].id) {
    return {
      ok: false,
      reason: result.rows.length === 0 ? "office_profile_not_found" : "office_profile_email_not_unique",
    };
  }
  return { ok: true, profileId: String(result.rows[0].id) };
}

async function deactivateOfficeDepartmentPlacement(
  discordUserId,
  reason = "removed_by_bot",
  sourceUpdatedAt = new Date(),
) {
  return callOfficeSupabase("/rest/v1/rpc/office_deactivate_department_assignment", {
    p_discord_user_id: String(discordUserId || "").trim(),
    p_inactive_reason: String(reason || "removed_by_bot").slice(0, 300),
    p_source_updated_at: sourceUpdatedAt instanceof Date
      ? sourceUpdatedAt.toISOString()
      : String(sourceUpdatedAt || new Date().toISOString()),
  });
}

/**
 * Only sync a placement after the existing identity resolver proves the Roblox
 * identity and Discord candidate. Ambiguous Discord matches stay unlinked.
 */
async function syncOfficeDepartmentPlacement(placement, triggeredBy = "scheduled") {
  if (!getOfficeSupabaseConfig()) return { ok: false, reason: "not_configured" };
  if (!placement || !placement.discordId) return { ok: false, reason: "invalid_placement" };

  const discordUserId = String(placement.discordId).trim();
  const robloxUserId = String(placement.robloxUserId || "").trim();
  const placementType = String(placement.placementType || "").trim();
  const placementKey = String(placement.placementKey || "").trim();
  const placementConfig = getPlacementConfig(placementType, placementKey);
  if (!robloxUserId || !placementConfig) {
    return { ok: false, reason: "invalid_mongo_placement" };
  }

  const boardKey = placementType === "team"
    ? String(placementConfig.boardKey || "")
    : placementKey;
  const boardConfig = SWEETSIEZ_STRUCTURE_CONFIG.BOARDS[boardKey];
  const departmentKey = boardConfig && boardConfig.aliasOf ? boardConfig.aliasOf : boardKey;
  if (!["operations", "marketing", "moderation"].includes(departmentKey)) {
    return { ok: false, reason: "unsupported_department" };
  }

  let verifiedRow;
  try {
    verifiedRow = await VerifiedUser.findOne({ discordId: discordUserId }).lean();
  } catch (error) {
    // A database read failure is not evidence that verification disappeared.
    // Do not revoke an existing Office placement during a transient outage.
    return { ok: false, reason: "verification_store_unavailable", detail: error.message };
  }

  if (!verifiedRow) {
    const deactivated = await deactivateOfficeDepartmentPlacement(
      discordUserId, "verified_identity_missing", placement.updatedAt || new Date(),
    );
    return { ok: false, reason: "verified_identity_missing", deactivated: deactivated.ok };
  }

  if (verifiedRow.robloxId && String(verifiedRow.robloxId) !== robloxUserId) {
    const deactivated = await deactivateOfficeDepartmentPlacement(
      discordUserId, "roblox_identity_mismatch", placement.updatedAt || new Date(),
    );
    return { ok: false, reason: "roblox_identity_mismatch", deactivated: deactivated.ok };
  }

  const username = String(verifiedRow.robloxUsername || placement.robloxUsername || "").trim();
  if (!username) return { ok: false, reason: "verified_username_missing" };
  const email = String(
    verifiedRow.officeEmailLower ||
    verifiedRow.officeEmail ||
    (username + "@" + OFFICE_EMAIL_DOMAIN)
  ).trim().toLowerCase();

  const resolved = await resolveOfficeIdentityByEmail(email);
  if (resolved.statusCode >= 500) {
    return { ok: false, reason: "identity_resolver_unavailable" };
  }
  if (resolved.statusCode === 400) {
    // A malformed or invalid recorded address needs correction; it is not
    // sufficient evidence to revoke a previously linked Office identity.
    return { ok: false, reason: "office_email_invalid" };
  }
  if (resolved.statusCode !== 200 || !resolved.body || resolved.body.ok !== true) {
    return { ok: false, reason: "office_identity_resolution_inconclusive" };
  }

  const identity = resolved.body;
  const verificationStatus = String(identity.verificationStatus || "");
  const verificationIsValid = ["verified", "verified_former_username"].includes(
    verificationStatus,
  );

  // A missing/ambiguous cached Roblox ID is inconclusive, not proof that the
  // member lost verification. Preserve the current Office assignment until the
  // resolver can positively confirm or contradict the identity.
  if (!verificationIsValid || !identity.robloxUserId) {
    return { ok: false, reason: "office_identity_verification_inconclusive" };
  }

  if (String(identity.robloxUserId) !== robloxUserId) {
    const deactivated = await deactivateOfficeDepartmentPlacement(
      discordUserId, "office_identity_verification_mismatch", placement.updatedAt || new Date(),
    );
    return { ok: false, reason: "office_identity_verification_mismatch", deactivated: deactivated.ok };
  }

  if (identity.membershipStatus === "left_group") {
    const deactivated = await deactivateOfficeDepartmentPlacement(
      discordUserId, "member_left_roblox_group", placement.updatedAt || new Date(),
    );
    return { ok: false, reason: "member_left_roblox_group", deactivated: deactivated.ok };
  }
  if (identity.membershipStatus !== "in_group") {
    return { ok: false, reason: "roblox_membership_unconfirmed" };
  }

  const candidateIds = Array.isArray(identity.discordUserIds)
    ? identity.discordUserIds.map(value => String(value))
    : [];
  let profileId = null;
  if (String(identity.discordUserId || "") === discordUserId) {
    const profile = await getOfficeProfileIdByEmail(identity.email || email);
    if (!profile.ok) return profile;
    profileId = profile.profileId;
  } else if (!identity.discordUserId && candidateIds.includes(discordUserId)) {
    // Same verified Roblox account, multiple Discord candidates: never link a profile.
    profileId = null;
  } else {
    const deactivated = await deactivateOfficeDepartmentPlacement(
      discordUserId, "discord_identity_ambiguous_or_mismatched", placement.updatedAt || new Date(),
    );
    return {
      ok: false,
      reason: "discord_identity_ambiguous_or_mismatched",
      deactivated: deactivated.ok,
    };
  }

  const sourceUpdatedAt = placement.updatedAt || placement.assignedAt || new Date();
  const write = await callOfficeSupabase("/rest/v1/rpc/office_sync_department_assignment", {
    p_discord_user_id: discordUserId,
    p_profile_id: profileId,
    p_roblox_user_id: robloxUserId,
    p_roblox_username: username,
    p_department_key: departmentKey,
    p_placement_type: placementType,
    p_placement_key: placementKey,
    p_placement_label: String(placement.placementLabel || placementConfig.label || placementKey),
    p_assigned_by_discord_id: placement.assignedByDiscordId || null,
    p_assigned_by_tag: placement.assignedByTag || null,
    p_source_updated_at: sourceUpdatedAt instanceof Date
      ? sourceUpdatedAt.toISOString()
      : String(sourceUpdatedAt),
  });
  if (!write.ok) {
    console.warn(
      "[Office] department sync failed for " + discordUserId + " (" + triggeredBy + "): " +
      write.reason + (write.detail ? " — " + write.detail : ""),
    );
    return write;
  }
  return { ok: true, profileLinked: Boolean(profileId), departmentKey };
}

async function listOfficeActiveDepartmentAssignments() {
  const allRows = [];
  const pageSize = 1000;
  for (let offset = 0; ; offset += pageSize) {
    const result = await getOfficeRows(
      "/rest/v1/member_department_assignments?select=discord_user_id&is_active=eq.true" +
      "&order=discord_user_id.asc&limit=" + pageSize + "&offset=" + offset,
    );
    if (!result.ok) return result;
    allRows.push(...result.rows);
    if (result.rows.length < pageSize) break;
    if (offset >= 100000) {
      return { ok: false, reason: "office_assignment_page_limit_reached" };
    }
  }
  return { ok: true, rows: allRows };
}

/**
 * MongoDB is authoritative. Never deactivate rows when either source read fails.
 */
async function runOfficeDepartmentSync(triggeredBy = "scheduled") {
  if (officeDepartmentSyncRunning) return { skipped: true, reason: "already_running" };
  if (!getOfficeSupabaseConfig()) return { skipped: true, reason: "not_configured" };
  if (mongoose.connection.readyState !== 1) return { skipped: true, reason: "mongodb_unavailable" };

  officeDepartmentSyncRunning = true;
  try {
    let placements;
    try {
      placements = await StaffPlacement.find({}).lean();
    } catch (error) {
      console.warn("[Office] department sync could not read MongoDB (" + triggeredBy + "):", error.message);
      return { skipped: true, reason: "mongodb_read_failed" };
    }
    if (!Array.isArray(placements)) return { skipped: true, reason: "mongodb_read_failed" };

    const mongoDiscordIds = new Set(
      placements.map(row => String(row.discordId || "").trim()).filter(Boolean),
    );
    let applied = 0;
    let failures = 0;

    for (const placement of placements) {
      try {
        const result = await syncOfficeDepartmentPlacement(placement, triggeredBy);
        if (result.ok) applied += 1;
        else if (!["office_profile_not_found", "roblox_membership_unconfirmed"].includes(result.reason)) {
          failures += 1;
        }
      } catch (error) {
        failures += 1;
        console.warn("[Office] department placement sync failed:", error.message);
      }
    }

    const officeRows = await listOfficeActiveDepartmentAssignments();
    if (!officeRows.ok) {
      console.warn(
        "[Office] department stale-row check skipped (" + officeRows.reason +
        (officeRows.detail ? ": " + officeRows.detail : "") + ")",
      );
      return { processed: placements.length, applied, failures, staleCheck: "skipped" };
    }

    let deactivated = 0;
    for (const row of officeRows.rows) {
      const discordUserId = String(row.discord_user_id || "").trim();
      if (!discordUserId || mongoDiscordIds.has(discordUserId)) continue;
      const result = await deactivateOfficeDepartmentPlacement(
        discordUserId, "placement_missing_from_mongodb", new Date(),
      );
      if (result.ok) deactivated += 1;
      else failures += 1;
    }

    const summary =
      "[Office] department sync (" + triggeredBy + "): " +
      applied + "/" + placements.length + " active placements applied, " +
      deactivated + " stale placements deactivated, " + failures + " issue(s)";
    if (failures > 0) console.warn(summary);
    else console.log(summary);
    return { processed: placements.length, applied, deactivated, failures };
  } finally {
    officeDepartmentSyncRunning = false;
  }
}

function startOfficeDepartmentSync() {
  if (!getOfficeSupabaseConfig()) {
    console.log("[Office] department sync DISABLED (set SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY)");
    return null;
  }
  console.log(
    "[Office] department sync ENABLED - reconciling MongoDB placements every " +
    Math.round(OFFICE_SYNC_INTERVAL_MS / 1000) + "s",
  );
  runOfficeDepartmentSync("startup").catch(error =>
    console.warn("[Office] department startup sync failed:", error.message),
  );
  const timer = setInterval(() => {
    runOfficeDepartmentSync("scheduled").catch(error =>
      console.warn("[Office] department scheduled sync failed:", error.message),
    );
  }, OFFICE_SYNC_INTERVAL_MS);
  if (timer && typeof timer.unref === "function") timer.unref();
  return timer;
}


/** Start the loop. Returns the timer, or null when the sync is not configured. */
function startOfficeIdentitySync() {
  if (!getOfficeSupabaseConfig()) {
    console.log("[Office] sync DISABLED (set SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY)");
    return null;
  }

  console.log(`[Office] sync ENABLED - polling Supabase every ${Math.round(OFFICE_SYNC_INTERVAL_MS / 1000)}s`);
  runOfficeIdentitySync("startup").catch(error => console.warn("[Office] startup sync failed:", error.message));

  const timer = setInterval(() => {
    runOfficeIdentitySync("scheduled").catch(error => console.warn("[Office] scheduled sync failed:", error.message));
  }, OFFICE_SYNC_INTERVAL_MS);
  if (timer && typeof timer.unref === "function") timer.unref();
  return timer;
}

