// HTTP promote
app.post("/api/promote", validateApiKey, async (req, res) => {
  try {
    const { username, ranker_username, game_name } = req.body;
    if (!username || !ranker_username) {
      return res.status(400).json({
        success: false,
        error: "Missing required fields: username, ranker_username",
      });
    }
    const rankerDiscordId = _getDiscordIdForRoblox(ranker_username.toLowerCase());
    if (!rankerDiscordId) {
      return res
        .status(403)
        .json({ success: false, error: "Ranker is not verified" });
    }
    const canRank = await canUseRankingCommands(rankerDiscordId);
    if (!canRank) {
      return res.status(403).json({
        success: false,
        error: "Ranker does not have permission to use ranking commands",
      });
    }
    if (username.toLowerCase() === ranker_username.toLowerCase()) {
      return res
        .status(400)
        .json({ success: false, error: "Cannot promote yourself" });
    }
    const userId = await getRobloxUserId(username);
    if (!userId) {
      return res.status(404).json({ success: false, error: "User not found" });
    }
    const currentRank = await getUserRankInGroup(userId);
    if (!currentRank) {
      return res
        .status(404)
        .json({ success: false, error: "User is not in the group" });
    }
    const nextRole = await resolveAdjacentGroupRole(currentRank.rank, 'up');
    if (!nextRole) {
      return res
        .status(400)
        .json({ success: false, error: "User is already at highest rank" });
    }
    const promoteResult = await applyRobloxRank({ userId, roleId: nextRole.id });
    const success = promoteResult.ok;
    if (success) {
      const guild = client.guilds.cache.first();
      if (guild) {
        await logRankingAction(
          guild,
          ranker_username,
          username,
          currentRank.name,
          nextRole.name,
          "Promotion (HTTP)",
          game_name,
        );
      }
      return res.json({
        success: true,
        data: {
          username: username,
          old_rank: currentRank.name,
          new_rank: nextRole.name,
          ranker: ranker_username,
        },
      });
    } else {
      return res
        .status(502)
        .json({ success: false, error: `Failed to promote user: ${promoteResult.error || "unknown error"}` });
    }
  } catch (error) {
    console.error("HTTP promote error:", error);
    return res
      .status(500)
      .json({ success: false, error: "Internal server error" });
  }
});

