// HTTP setrank
app.post("/api/setrank", validateApiKey, async (req, res) => {
  try {
    const { username, rank, ranker_username, game_name, bypass_verification } = req.body;
    if (!username || rank === undefined || !ranker_username) {
      return res.status(400).json({
        success: false,
        error: "Missing required fields: username, rank, ranker_username",
      });
    }
    // Callers are already authenticated by validateApiKey (x-api-key / bearer),
    // so the old hardcoded bypass string has been removed. A bypass is only
    // honoured when it matches RANK_BYPASS_SECRET, or when the caller explicitly
    // sends the boolean true (equivalent trust level: they hold the API key).
    const configuredBypassSecret = process.env.RANK_BYPASS_SECRET;
    const bypassOk =
      bypass_verification === true ||
      String(bypass_verification).toLowerCase() === "true" ||
      (Boolean(configuredBypassSecret) && bypass_verification === configuredBypassSecret);

    let rankerDiscordId = "Bypassed by API Key";
    if (bypassOk) {
      console.warn(
        `⚠️ /api/setrank bypass_verification used by ${ranker_username} (${game_name || "unknown game"}) — the caller held the API key.`,
      );
    } else {
      rankerDiscordId = _getDiscordIdForRoblox(ranker_username.toLowerCase());
      if (!rankerDiscordId) {
        return res
          .status(403)
          .json({ success: false, error: "Ranker is not verified" });
      }
      const canRank = await canUseRankingCommands(rankerDiscordId);
      if (!canRank) {
        return res.status(403).json({
          success: false,
          error: "Ranker does not have permission to use ranking commands",
        });
      }
    }
    if (username.toLowerCase() === ranker_username.toLowerCase()) {
      return res
        .status(400)
        .json({ success: false, error: "Cannot change your own rank" });
    }
    const userId = await getRobloxUserId(username);
    if (!userId) {
      return res.status(404).json({ success: false, error: "User not found" });
    }
    const currentRank = await getUserRankInGroup(userId);
    if (!currentRank) {
      return res
        .status(404)
        .json({ success: false, error: "User is not in the group" });
    }
    // Accept a numeric rank or a numeric string from the game server.
    const requestedRank = Number(rank);
    const targetRole = await resolveGroupRoleByRank(requestedRank);
    if (!targetRole) {
      return res
        .status(400)
        .json({ success: false, error: "Invalid rank number" });
    }
    const success = await setUserRank(userId, targetRole.id);
    if (success) {
      const guild = client.guilds.cache.first();
      if (guild) {
        await logRankingAction(
          guild,
          ranker_username,
          username,
          currentRank.name,
          targetRole.name,
          "Set Rank (HTTP)",
          game_name,
        );
      }
      return res.json({
        success: true,
        data: {
          username: username,
          old_rank: currentRank.name,
          new_rank: targetRole.name,
          ranker: ranker_username,
        },
      });
    } else {
      return res
        .status(500)
        .json({ success: false, error: "Failed to set rank" });
    }
  } catch (error) {
    console.error("HTTP setrank error:", error);
    return res
      .status(500)
      .json({ success: false, error: "Internal server error" });
  }
});

