app.post("/api/log-training", validateApiKey, async (req, res) => {
  try {
    const {
      host_username,
      attendees,
      session_time,
      promoter,
      group_a_trainer,
      group_b_trainer,
      group_a_assistant,
      group_b_assistant,
    } = req.body;

    // Validate required fields
    if (!host_username || !attendees || !Array.isArray(attendees)) {
      return res.status(400).json({
        success: false,
        error:
          "Missing required fields: host_username (string), attendees (array)",
      });
    }

    // Verify the host is a verified user
    const hostDiscordId = Array.from(verifiedUsers.entries()).find(
      ([_, user]) => user.toLowerCase() === host_username.toLowerCase(),
    )?.[0];

    if (!hostDiscordId) {
      return res.status(403).json({
        success: false,
        error: "Host is not verified in Discord",
      });
    }

    // Get host's Roblox rank
    const hostUserId = await getRobloxUserId(host_username);
    if (!hostUserId) {
      return res.status(404).json({
        success: false,
        error: "Host Roblox user not found",
      });
    }

    const hostRank = await getUserRankInGroup(hostUserId);
    if (!hostRank || hostRank.rank < 10) {
      return res.status(403).json({
        success: false,
        error:
          "Host does not have sufficient rank to host trainings (requires rank 10+)",
      });
    }

    // Round session time down to nearest hour
    let roundedSessionTime = session_time || "Not specified";
    if (session_time) {
      const match = session_time.match(/(\d+):(\d+)\s*(AM|PM)\s*EST/i);
      if (match) {
        const hour = match[1];
        const ampm = match[3];
        roundedSessionTime = `${hour}:00 ${ampm} EST`;
      }
    }

    // Validate attendees (check if they exist in Roblox)
    const validatedAttendees = [];
    const invalidAttendees = [];

    for (const username of attendees) {
      const userId = await getRobloxUserId(username);
      if (userId) {
        validatedAttendees.push(username);
      } else {
        invalidAttendees.push(username);
      }
    }

    // Log to Discord channel
    const guild = client.guilds.cache.first();
    if (guild && config.TRAINING_LOG_CHANNEL_ID) {
      try {
        const channel = await guild.channels.fetch(
          config.TRAINING_LOG_CHANNEL_ID,
        );
        if (channel) {
          const embed = new EmbedBuilder()
            .setTitle("📋 Training Session Logged")
            .setColor(0x00ff00)
            .addFields(
              { name: "Host", value: host_username, inline: true },
              { name: "Session Time", value: roundedSessionTime, inline: true },
              {
                name: "Total Attendees",
                value: validatedAttendees.length.toString(),
                inline: true,
              },
              { name: "Promoter", value: promoter || "None", inline: true },
              {
                name: "Group A Trainer",
                value: group_a_trainer || "None",
                inline: true,
              },
              {
                name: "Group B Trainer",
                value: group_b_trainer || "None",
                inline: true,
              },
              {
                name: "Group A Assistant",
                value: group_a_assistant || "None",
                inline: true,
              },
              {
                name: "Group B Assistant",
                value: group_b_assistant || "None",
                inline: true,
              },
              { name: "\u200B", value: "\u200B", inline: true }, // Empty field for alignment
              {
                name: "All Participants",
                value: validatedAttendees.join(", ") || "None",
                inline: false,
              },
            )
            .setTimestamp();

          if (invalidAttendees.length > 0) {
            embed.addFields({
              name: "⚠️ Invalid Usernames",
              value: invalidAttendees.join(", "),
              inline: false,
            });
          }

          await channel.send({ embeds: [embed] });
        }
      } catch (error) {
        console.error("Error sending training log to Discord:", error);
      }
    }

    return res.json({
      success: true,
      data: {
        host: host_username,
        validated_attendees: validatedAttendees,
        invalid_attendees: invalidAttendees,
        total_attendees: validatedAttendees.length,
        session_time: roundedSessionTime,
        roles: {
          promoter,
          group_a_trainer,
          group_b_trainer,
          group_a_assistant,
          group_b_assistant,
        },
      },
    });
  } catch (error) {
    console.error("HTTP log-training error:", error);
    return res.status(500).json({
      success: false,
      error: "Internal server error",
    });
  }
});

