app.post('/api/shift-event', validateApiKey, async (req, res) => {
  try {
    const body = req.body || {};
    const eventType = String(body.event_type || body.eventType || "").toLowerCase();
    const shiftId = String(body.shift_id || body.shiftId || "").trim();
    const hostUsername = String(body.host_username || body.hostUsername || "").trim();
    const hostUserIdRaw = body.host_user_id ?? body.hostUserId;
    const hostUserId = hostUserIdRaw !== undefined && hostUserIdRaw !== null ? String(hostUserIdRaw).trim() : null;
    const hostRank = Number(body.host_rank ?? body.hostRank);
    const placeId = body.place_id !== undefined && body.place_id !== null ? String(body.place_id) : null;
    const jobId = body.job_id !== undefined && body.job_id !== null ? String(body.job_id) : null;
    const rawShiftType = String(body.shift_type || body.shiftType || "").toLowerCase().trim();

    if (eventType === "claim") {
      const result = await createShiftClaimFromGame(body);
      return res.status(result.statusCode).json(result.payload);
    }

    if (!["begin", "attendance", "conclude"].includes(eventType)) {
      return res.status(400).json({ success: false, error: "Invalid or missing event_type" });
    }
    if (!shiftId || !hostUsername) {
      return res.status(400).json({ success: false, error: "Missing required fields: shift_id, host_username" });
    }

    let record = await ShiftAttendance.findOne({ shiftId });
    if (!record) {
      record = new ShiftAttendance({
        shiftId,
        hostUsername,
        hostUserId,
      });
    }

    record.hostUsername = hostUsername;
    if (hostUserId) record.hostUserId = hostUserId;
    if (Number.isFinite(hostRank)) record.hostRank = hostRank;
    if (placeId) record.placeId = placeId;
    if (jobId) record.jobId = jobId;
    if (["regular", "recruitment", "promotional"].includes(rawShiftType)) record.shiftType = rawShiftType;
    if (!record.shiftType || record.shiftType === "regular") {
      const claimMatch = findGameBeginShiftClaim(hostUsername);
      if (claimMatch.ok) record.shiftType = claimMatch.claim.shiftType || "regular";
    }
    record.updatedAt = new Date();

    const hostDiscordId = _getDiscordIdForRoblox(hostUsername.toLowerCase());
    const hostDisplay = hostDiscordId ? `${hostUsername} (<@${hostDiscordId}>)` : hostUsername;

    if (eventType === "begin") {
      const startedAt = unixSecondsToDate(body.started_at ?? body.startedAt ?? body.sent_at);
      record.startedAt = startedAt;
      await record.save();

      if (!record.publicStartAnnouncementSent && await sendPublicShiftAnnouncement(record)) {
        record.publicStartAnnouncementSent = true;
        await record.save();
      }

      const embed = new EmbedBuilder()
        .setTitle("Shift Started")
        .setColor(0x6bcf7f)
        .addFields(
          { name: "Host", value: hostDisplay, inline: true },
          { name: "Shift ID", value: `\`${shiftId}\``, inline: true },
          { name: "Started", value: shiftEventTimestamp(startedAt), inline: false },
        )
        .setTimestamp();

      await sendShiftAttendanceLog(embed);
      await sendBotActivityLog({ title: "Game Shift Began", color: 0x6bcf7f, fields: [
        { name: "Host", value: hostDisplay, inline: true },
        { name: "Shift Type", value: record.shiftType || "regular", inline: true },
        { name: "Shift ID", value: shiftId, inline: true },
        { name: "Server", value: getPublicShiftServerLink(record.placeId, record.jobId), inline: false },
      ] });
      return res.json({ success: true, data: { shift_id: shiftId, event_type: eventType } });
    }

    if (eventType === "attendance") {
      const attendanceLoggedAt = unixSecondsToDate(body.logged_at ?? body.attendance_logged_at ?? body.sent_at);
      const attendees = normalizeShiftAttendees(body.attendees);
      const attendeeKey = (attendee) => attendee.userId || attendee.username.toLowerCase();
      const previousKeys = new Set((record.attendees || []).map(attendeeKey));
      const newlyCounted = attendees.filter((attendee) => !previousKeys.has(attendeeKey(attendee)));

      record.attendanceLoggedAt = attendanceLoggedAt;
      record.attendees = attendees;
      await record.save();
      await creditShiftCompletedForAttendees(newlyCounted);

      const embed = new EmbedBuilder()
        .setTitle("Shift Attendance Logged")
        .setColor(0x5bc0de)
        .addFields(
          { name: "Host", value: hostDisplay, inline: true },
          { name: "Attendees", value: String(attendees.length), inline: true },
          { name: "New Completed Credits", value: String(newlyCounted.length), inline: true },
          { name: "Logged", value: shiftEventTimestamp(attendanceLoggedAt), inline: false },
          { name: "Attendance List", value: formatShiftAttendeeList(attendees), inline: false },
        )
        .setFooter({ text: `Shift ID: ${shiftId}` })
        .setTimestamp();

      await sendShiftAttendanceLog(embed);
      return res.json({
        success: true,
        data: {
          shift_id: shiftId,
          event_type: eventType,
          attendees: attendees.length,
          counted_new: newlyCounted.length,
        },
      });
    }

    const concludedAt = unixSecondsToDate(body.concluded_at ?? body.concludedAt ?? body.sent_at);
    record.concludedAt = concludedAt;
    await record.save();

    if (!record.publicConclusionAnnouncementSent && await sendPublicShiftAnnouncement(record, true)) {
      record.publicConclusionAnnouncementSent = true;
      await record.save();
    }

    const embed = new EmbedBuilder()
      .setTitle("Shift Concluded")
      .setColor(0xffa500)
      .addFields(
        { name: "Host", value: hostDisplay, inline: true },
        { name: "Shift ID", value: `\`${shiftId}\``, inline: true },
        { name: "Concluded", value: shiftEventTimestamp(concludedAt), inline: false },
      )
      .setTimestamp();

    await sendShiftAttendanceLog(embed);
    await sendBotActivityLog({ title: "Game Shift Concluded", color: 0xffa500, fields: [
      { name: "Host", value: hostDisplay, inline: true },
      { name: "Shift Type", value: record.shiftType || "regular", inline: true },
      { name: "Shift ID", value: shiftId, inline: true },
    ] });
    return res.json({ success: true, data: { shift_id: shiftId, event_type: eventType } });
  } catch (error) {
    console.error("HTTP shift-event error:", error);
    await sendBotActivityLog({ title: "Game Shift Event Error", color: 0xe74c3c, error, pingErrorRole: true });
    return res.status(500).json({
      success: false,
      error: "Internal server error",
    });
  }
});

