// Track activity endpoint - called from Roblox game
app.post('/api/track-activity', validateApiKey, async (req, res) => {
  try {
    const { username, minutes, points, credits } = req.body;
    if (!username || minutes === undefined) {
      return res.status(400).json({ success: false, error: 'Missing required fields' });
    }

    const userId = await getRobloxUserId(username);
    if (!userId) {
      return res.status(404).json({ success: false, error: 'User not found' });
    }

    const today = req.body.date || getEasternDateString();


    // 1. Get or create activity record
    let activity = activityData.get(username.toLowerCase()) || {
      userId: userId,
      dailyActivity: {},
      totalActivity: 0,
      points: 0,
      lastUpdated: new Date().toISOString()
    };

    // 2. Update activity values
    activity.dailyActivity[today] = (activity.dailyActivity[today] || 0) + minutes;
    activity.totalActivity += minutes;
    if (points !== undefined) {
      activity.points = points;
    } else {
      activity.points += minutes;
    }
    activity.lastUpdated = new Date().toISOString();

    // 3. Save activity
    activityData.set(username.toLowerCase(), activity);
    await saveActivity();

    // 4. ECONOMY LOGIC
    // The Roblox DataStore (PlayerCredits_v1) is the single source of truth.
    // The game sends the player's live credit balance with every activity update.
    // We mirror it into MongoDB so Discord commands (/balance, /shop) can read it.
    let economy;
    if (credits !== undefined && typeof credits === 'number') {
      // Use the authoritative DataStore value sent by Roblox
      const existingDoc = await Economy.findOne({ robloxUsernameLower: username.toLowerCase() });
      const prevBalance = existingDoc?.balance ?? 0;
      const prevTotalEarned = existingDoc?.totalEarned ?? 0;
      const newTotalEarned = credits > prevBalance
        ? prevTotalEarned + (credits - prevBalance)
        : prevTotalEarned;
      economy = { balance: credits, totalEarned: newTotalEarned };
    } else {
      // credits not sent — keep whatever MongoDB already has (no fabrication)
      const existingDoc = await Economy.findOne({ robloxUsernameLower: username.toLowerCase() });
      economy = existingDoc
        ? { balance: existingDoc.balance, totalEarned: existingDoc.totalEarned }
        : { balance: 0, totalEarned: 0 };
    }
    // Mirror into MongoDB and in-memory cache
    economyData.set(username.toLowerCase(), economy);
    await Economy.findOneAndUpdate(
      { robloxUsernameLower: username.toLowerCase() },
      { robloxUsernameLower: username.toLowerCase(), balance: economy.balance, totalEarned: economy.totalEarned },
      { upsert: true }
    );








    // 5. ACHIEVEMENT LOGIC (Now "activity" is defined!)
    const userMedals = achievementData.get(username.toLowerCase()) || { medals: [] };
    let earnedNew = false;
    MILESTONES.forEach(m => {
      const stat = (m.type === 'points') ? activity.points : activity.totalActivity;
      if (stat >= m.requirement && !userMedals.medals.includes(m.id)) {
        userMedals.medals.push(m.id);
        earnedNew = true;
        const commChannel = client.channels.cache.get(config.COMMUNITY_CHANNEL_ID);
        if (commChannel) {
          commChannel.send(`🎊 **ACHIEVEMENT UNLOCKED:** **${username}** has earned the **${m.name}** medal!`);
        }
      }
    });

    if (earnedNew) {
      achievementData.set(username.toLowerCase(), userMedals);
      await saveAchievements();
    }

    return res.json({
      success: true,
      data: {
        username: username,
        daily_minutes: activity.dailyActivity[today],
        total_minutes: activity.totalActivity,
        points: activity.points,
        balance: economy.balance
      }
    });

  } catch (error) {
    console.error('HTTP track-activity error:', error);
    return res.status(500).json({ 
      success: false, 
      error: 'Internal server error',
      details: error.message // Add details for debugging
    });
  }
});


// ── GET /api/credits/:username ────────────────────────────────────────────
// NOTE: The Roblox DataStore (PlayerCredits_v1) is now the single source of truth.
// The bot's MongoDB balance is a read mirror, kept in sync by /api/track-activity.
// This endpoint returns the last mirrored balance for informational use only.
