// ── POST /api/credits/:username ───────────────────────────────────────────
// Kept for backwards compatibility. Mirrors a balance value into MongoDB.
// The game should send credits via /api/track-activity instead.
app.post('/api/credits/:username', validateApiKey, async (req, res) => {
  try {
    const username = req.params.username.toLowerCase();
    const { credits } = req.body;
    if (credits === undefined || typeof credits !== 'number') {
      return res.status(400).json({ success: false, error: 'Missing or invalid field: credits (must be a number)' });
    }
    const newBalance = Math.max(0, credits);
    const existing = economyData.get(username) || { balance: 0, totalEarned: 0 };
    const totalEarned = credits > existing.balance
      ? existing.totalEarned + (credits - existing.balance)
      : existing.totalEarned;
    economyData.set(username, { balance: newBalance, totalEarned });
    await Economy.findOneAndUpdate(
      { robloxUsernameLower: username },
      { robloxUsernameLower: username, balance: newBalance, totalEarned },
      { upsert: true }
    );
    return res.json({ success: true, username: req.params.username, credits: newBalance, totalEarned });
  } catch (error) {
    console.error('POST /api/credits error:', error);
    return res.status(500).json({ success: false, error: 'Internal server error' });
  }
});



// ============================================================
// ActivityCalendar API — called by ActivityCalendarService.lua
// GET /api/activity?username=X&year=Y&month=M
// Returns: { days: { "1": 45, "3": 120, ... } }
// Keys are day-of-month strings, values are total minutes for that day.
// ============================================================
app.get('/api/activity', validateApiKey, async (req, res) => {
  try {
    const { username, year, month } = req.query;

    if (!username || !year || !month) {
      return res.status(400).json({ error: 'Missing required query params: username, year, month' });
    }

    const yearNum  = parseInt(year,  10);
    const monthNum = parseInt(month, 10);

    if (isNaN(yearNum) || isNaN(monthNum) || monthNum < 1 || monthNum > 12) {
      return res.status(400).json({ error: 'Invalid year or month' });
    }

    // Don't serve future months
    const now = new Date();
    if (yearNum > now.getFullYear() || (yearNum === now.getFullYear() && monthNum > now.getMonth() + 1)) {
      return res.status(400).json({ error: 'Cannot request future months' });
    }

    const userKey  = username.toLowerCase();
    const userData = activityData.get(userKey);

    if (!userData) {
      // User exists but has no activity recorded — return empty days object
      return res.json({ days: {} });
    }

    // dailyActivity keys are stored as "YYYY-MM-DD" strings.
    // We need to find all keys matching the requested year/month and remap them
    // to day-of-month numbers as string keys, e.g. "1", "15".
    const prefix = `${yearNum}-${String(monthNum).padStart(2, '0')}-`;
    const days   = {};

    for (const [dateStr, minutes] of Object.entries(userData.dailyActivity)) {
      if (dateStr.startsWith(prefix)) {
        // Extract the day portion and strip any leading zero so "03" → "3"
        const dayPart = dateStr.slice(prefix.length);     // e.g. "03" or "15"
        const dayNum  = parseInt(dayPart, 10);             // strip leading zero
        if (!isNaN(dayNum) && minutes > 0) {
          days[String(dayNum)] = minutes;
        }
      }
    }

    return res.json({ days });

  } catch (error) {
    console.error('[ActivityCalendar] /api/activity error:', error);
    return res.status(500).json({ error: 'Internal server error' });
  }
});

