async function saveResignations() {
  try {
    const bulkOps = [];
    for (const [discordId, resignation] of pendingResignations.entries()) {
      bulkOps.push({
        updateOne: {
          filter: { discordId },
          update: {
            discordId,
            robloxUsername: resignation.robloxUsername,
            userId: resignation.userId || null,
            oldRank: resignation.oldRank ?? null,
            oldRankName: resignation.oldRankName || null,
            reason: resignation.reason,
            timestamp: resignation.expiresAt || resignation.timestamp,
            processed: resignation.processed || false,
          },
          upsert: true,
        },
      });
    }
    if (bulkOps.length > 0) await Resignation.bulkWrite(bulkOps);
    console.log(`💾 Saved ${pendingResignations.size} pending resignations to MongoDB`);
  } catch (error) {
    console.error('Error saving resignations to MongoDB:', error.message);
  }
}

async function loadResignations() {
  try {
    const docs = await Resignation.find({ processed: false });
    const now = Date.now();
    pendingResignations.clear();

    for (const doc of docs) {
      const timeRemaining = doc.timestamp - now; // Assuming timestamp is expiresAt

      if (timeRemaining > 0) {
        // Reschedule the timeout
        const timeoutId = setTimeout(async () => {
          await processResignation(
            doc.discordId,
            doc.reason,
            doc.robloxUsername,
            doc.oldRank,
            doc.userId
          );
        }, timeRemaining);

        pendingResignations.set(doc.discordId, {
          reason: doc.reason,
          robloxUsername: doc.robloxUsername,
          timestamp: doc.timestamp,
          expiresAt: doc.timestamp,
          processed: doc.processed,
          oldRank: doc.oldRank,
          oldRankName: doc.oldRankName,
          userId: doc.userId,
          timeoutId,
        });

        console.log(`⏰ Rescheduled resignation for ${doc.robloxUsername} (${Math.round(timeRemaining / 1000 / 60)} minutes remaining)`);
      } else {
        // Already expired, process immediately
        console.log(`⚡ Processing expired resignation for ${doc.robloxUsername}`);
        pendingResignations.set(doc.discordId, {
          reason: doc.reason,
          robloxUsername: doc.robloxUsername,
          timestamp: doc.timestamp,
          expiresAt: doc.timestamp,
          processed: doc.processed,
          oldRank: doc.oldRank,
          oldRankName: doc.oldRankName,
          userId: doc.userId,
          timeoutId: null,
        });
        await processResignation(
          doc.discordId,
          doc.reason,
          doc.robloxUsername,
          doc.oldRank,
          doc.userId
        );
      }
    }

    console.log(`✅ Loaded ${pendingResignations.size} pending resignations from MongoDB`);
  } catch (error) {
    console.error('Error loading resignations from MongoDB:', error.message);
  }
}

// Additional load/save functions for MongoDB
async function loadEconomy() {
  try {
    const docs = await Economy.find({});
    economyData.clear();
    docs.forEach(doc => {
      economyData.set(doc.robloxUsernameLower, {
        balance: doc.balance,
        totalEarned: doc.totalEarned,
      });
    });
    console.log(`✅ Loaded economy data from MongoDB`);
  } catch (error) {
    console.error('Error loading economy from MongoDB:', error.message);
  }
}

async function saveEconomy() {
  try {
    const bulkOps = [];
    economyData.forEach((data, robloxUsernameLower) => {
      bulkOps.push({
        updateOne: {
          filter: { robloxUsernameLower },
          update: {
            $set: {
              robloxUsernameLower,
              balance: data.balance,
              totalEarned: data.totalEarned,
            },
          },
          upsert: true,
        },
      });
    });
    if (bulkOps.length > 0) await Economy.bulkWrite(bulkOps);
    console.log(`💾 Saved economy data to MongoDB`);
  } catch (error) {
    console.error('Error saving economy to MongoDB:', error.message);
  }
}

