const PUBLIC_SHIFT_ANNOUNCEMENT_CHANNEL_ID = "1515779043100987613";
const PUBLIC_SHIFT_PING_ROLE_ID = "1472318661112103055";

function getPublicShiftServerLink(placeId, jobId) {
  if (!placeId || !jobId) return "Server link unavailable.";
  return `https://www.roblox.com/games/${placeId}?gameInstanceId=${jobId}`;
}

async function sendPublicShiftAnnouncement(record, isConclusion = false) {
  const guild = client.guilds.cache.first();
  const channel = guild ? await guild.channels.fetch(PUBLIC_SHIFT_ANNOUNCEMENT_CHANNEL_ID).catch(() => null) : null;
  if (!channel?.send) return false;
  if (isConclusion) {
    await channel.send({ content: ":cupcake: **SHIFT CONCLUDED**\n\nThat’s a wrap! Huge thanks to everyone who came out and joined the shift, we loved having you there. :sparkling_heart: If you couldn’t make it this time, no worries! There will be plenty more chances to hop in soon." });
    return true;
  }
  const serverLink = getPublicShiftServerLink(record.placeId, record.jobId);
  let content;
  if (record.shiftType === "recruitment") content = `**:cupcake: RECRUITMENT SHIFT**\n\nGreetings, <@&${PUBLIC_SHIFT_PING_ROLE_ID}>! A recruitment shift is being hosted by **${record.hostUsername}** down at the bakery. This shift will be used to scout potential Shift Leads, as well as observe current Shift Leads for the possibility of Supervisor. Why not head on down and grab something to eat? We can't wait to see you there!\n\n> :link: - ${serverLink}`;
  else if (record.shiftType === "promotional") content = `**🧁 PROMOTIONAL SHIFT**\n\nGreetings, <@&${PUBLIC_SHIFT_PING_ROLE_ID}> @here! A **Promotional Shift** is now being hosted by **${record.hostUsername}** at the bakery. This is your chance to showcase your skills, work hard, and possibly earn a promotion to the next rank! ✨\n\nCome join us, enjoy the atmosphere, and don’t miss out on this opportunity!\n\n> 🔗 - ${serverLink}`;
  else content = `**:cupcake: SHIFT**\n\nGreetings, <@&${PUBLIC_SHIFT_PING_ROLE_ID}>! A shift is being hosted by **${record.hostUsername}** down at the bakery. Why not head on down and grab something to eat? We can't wait to see you there!\n\n> :link: ${serverLink}`;
  await channel.send({ content, allowedMentions: { roles: [PUBLIC_SHIFT_PING_ROLE_ID], parse: record.shiftType === "promotional" ? ["everyone"] : [] } });
  return true;
}

