const BOT_ACTIVITY_LOG_CHANNEL_ID = "1547342011462451220";
const BOT_ERROR_PING_ROLE_ID = "1463261653297664000";
const BOT_LOG_SENSITIVE_OPTION_NAMES = /token|key|secret|password|cookie|evidence|report|appeal/i;

function formatBotLogValue(value, fallback = "Not provided") {
  const text = String(value ?? "").trim();
  return text ? truncateForDiscord(text, 1024) : fallback;
}

async function sendBotActivityLog({ title, color = 0x5865f2, fields = [], error = null, pingErrorRole = false }) {
  const guild = client.guilds.cache.first();
  const channel = guild ? await guild.channels.fetch(BOT_ACTIVITY_LOG_CHANNEL_ID).catch(() => null) : null;
  if (!channel?.send) return false;
  const embed = new EmbedBuilder().setTitle(title).setColor(color).setTimestamp();
  for (const field of fields.slice(0, 25)) embed.addFields({ name: field.name, value: formatBotLogValue(field.value), inline: Boolean(field.inline) });
  if (error) embed.addFields({ name: "Error", value: formatBotLogValue(error.stack || error.message || error), inline: false });
  await channel.send({
    content: pingErrorRole ? `<@&${BOT_ERROR_PING_ROLE_ID}>` : undefined,
    embeds: [embed],
    allowedMentions: pingErrorRole ? { roles: [BOT_ERROR_PING_ROLE_ID] } : { parse: [] },
  }).catch(() => {});
  return true;
}

async function canReplyToBotDm(interaction) {
  const rankInfo = await getVerifiedMainRankForDiscord(interaction.user.id).catch(() => null);
  return Number(rankInfo?.rank || 0) >= 20;
}

async function forwardBotDmToLog(message) {
  if (message.author.bot || message.guild) return;
  const guild = client.guilds.cache.first();
  const channel = guild ? await guild.channels.fetch(BOT_ACTIVITY_LOG_CHANNEL_ID).catch(() => null) : null;
  if (!channel?.send) return;
  const attachments = [...message.attachments.values()].map(attachment => attachment.url).join("\n");
  const embed = new EmbedBuilder()
    .setTitle("Bot DM Received")
    .setColor(0x3498db)
    .setDescription(formatBotLogValue(message.content, "No text content"))
    .addFields(
      { name: "Sender", value: `${message.author.tag} (<@${message.author.id}>)`, inline: true },
      { name: "User ID", value: message.author.id, inline: true },
      { name: "Attachments", value: attachments ? truncateForDiscord(attachments, 1024) : "None", inline: false },
    )
    .setTimestamp(message.createdAt);
  const row = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`botdm_reply:${message.author.id}`).setLabel("Reply in DMs").setStyle(ButtonStyle.Primary),
  );
  await channel.send({ embeds: [embed], components: [row], allowedMentions: { users: [message.author.id] } }).catch(() => {});
}

client.on("messageCreate", message => forwardBotDmToLog(message).catch(error => console.error("Could not forward bot DM:", error.message)));

client.on("interactionCreate", async interaction => {
  if (interaction.isButton?.() && interaction.customId.startsWith("botdm_reply:")) {
    if (!await canReplyToBotDm(interaction)) return interaction.reply({ content: "Only Head Developer, Director, or President may reply to bot DMs.", flags: MessageFlags.Ephemeral });
    const userId = interaction.customId.split(":")[1];
    const { ModalBuilder, TextInputBuilder, TextInputStyle } = require("discord.js");
    const modal = new ModalBuilder().setCustomId(`botdm_reply_modal:${userId}`).setTitle("Reply through Sweetsiez Assistant");
    modal.addComponents(new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId("message").setLabel("Message").setStyle(TextInputStyle.Paragraph).setMaxLength(1800).setRequired(true)));
    return interaction.showModal(modal);
  }
  if (interaction.isModalSubmit?.() && interaction.customId.startsWith("botdm_reply_modal:")) {
    if (!await canReplyToBotDm(interaction)) return interaction.reply({ content: "Only Head Developer, Director, or President may reply to bot DMs.", flags: MessageFlags.Ephemeral });
    const userId = interaction.customId.split(":")[1];
    const replyText = interaction.fields.getTextInputValue("message").trim();
    const recipient = await client.users.fetch(userId).catch(() => null);
    if (!recipient) return interaction.reply({ content: "That DM sender could not be found.", flags: MessageFlags.Ephemeral });
    await recipient.send(replyText).catch(() => null);
    await sendBotActivityLog({ title: "Bot DM Replied", color: 0x57f287, fields: [
      { name: "Recipient", value: `${recipient.tag} (${recipient.id})`, inline: true },
      { name: "Sent By", value: `${interaction.user.tag} (${interaction.user.id})`, inline: true },
      { name: "Message", value: replyText, inline: false },
    ] });
    return interaction.reply({ content: `Reply sent to ${recipient.tag}.`, flags: MessageFlags.Ephemeral });
  }
});

function getInteractionOptionLog(interaction) {
  if (!interaction.isChatInputCommand?.()) return "None";
  const options = interaction.options?.data || [];
  return options.map(option => {
    if (option.options) return `${option.name}: ${option.options.map(child => `${child.name}=${BOT_LOG_SENSITIVE_OPTION_NAMES.test(child.name) ? "[redacted]" : child.value ?? child.user?.id ?? ""}`).join(", ")}`;
    return `${option.name}=${BOT_LOG_SENSITIVE_OPTION_NAMES.test(option.name) ? "[redacted]" : option.value ?? option.user?.id ?? ""}`;
  }).join("\n") || "None";
}

