async function userOwnsGamepass(userId, gamepassId) {
  try {
    const response = await axios.get(
      `https://inventory.roblox.com/v1/users/${userId}/items/GamePass/${gamepassId}`,
      {
        headers: {
          Cookie: `.ROBLOSECURITY=${config.ROBLOX_COOKIE}`,
        },
      }
    );
    
    // Check if the response data indicates ownership
    return response.data && response.data.data && response.data.data.length > 0;
  } catch (error) {
    // If we get a 400 error, the gamepass doesn't exist or user doesn't own it
    if (error.response?.status === 400) {
      return false;
    }
    console.error(`Error checking gamepass ${gamepassId} for user ${userId}:`, error.message);
    return false;
  }
}


async function getUserGamepassRoles(userId) {
  const rolesToGive = new Set();
  
  // Check each gamepass in our bindings
  for (const [gamepassId, roles] of Object.entries(GAMEPASS_ROLE_BINDS)) {
    try {
      const ownsGamepass = await userOwnsGamepass(userId, gamepassId);
      if (ownsGamepass) {
        console.log(`✅ User ${userId} owns gamepass ${gamepassId}`);
        roles.forEach(role => rolesToGive.add(role));
      }
    } catch (error) {
      console.error(`Error checking gamepass ${gamepassId}:`, error.message);
    }
  }
  
  return rolesToGive;
}

// _getMembershipId removed — superseded by getOpenCloudMembershipPath


async function updateDiscordRoles(member, robloxRank, userId = null) {
  try {
    const guild = member.guild;
    const rolesToGive = new Set();
    const mainRankSet = new Set();
    const rememberMainRank = (rank) => {
      const numericRank = Number(rank || 0);
      if (numericRank > 0) mainRankSet.add(numericRank);
    };
    rememberMainRank(robloxRank);
 
    // ── Main group: multi-role aware ─────────────────────────────────────
    if (userId) {
      let mainRoles = [];

      // Preferred: Open Cloud (most accurate, handles new multi-role system)
      if (config.ROBLOX_OPEN_CLOUD_KEY) {
        mainRoles = await getUserMultipleRolesInGroup(userId, config.GROUP_ID);
      }

      // Fallback: v2 groups endpoint allRoles (also multi-role aware)
      if (mainRoles.length === 0) {
        const allRanks = await getAllUserGroupRanks(userId);
        const mainEntry = allRanks[config.GROUP_ID];
        if (mainEntry?.allRoles?.length > 0) {
          mainRoles = mainEntry.allRoles;
        }
      }

      if (mainRoles.length > 0) {
        for (const roleInfo of mainRoles) {
          rememberMainRank(roleInfo.rank);
          const boundRoles = ROLE_BINDS[roleInfo.rank] || [];
          boundRoles.forEach(r => rolesToGive.add(r));
        }
      } else {
        // Not in main group or couldn't fetch — use the provided rank number
        rememberMainRank(robloxRank);
        const fallbackRoles = ROLE_BINDS[robloxRank] || [];
        fallbackRoles.forEach(r => rolesToGive.add(r));
      }
    } else {
      // No userId at all — legacy behaviour
      rememberMainRank(robloxRank);
      const mainGroupRoles = ROLE_BINDS[robloxRank] || [];
      mainGroupRoles.forEach(r => rolesToGive.add(r));
    }
 
    // ── Additional groups (dev group, etc.) ──────────────────────────────
    if (userId) {
      const allRanks = await getAllUserGroupRanks(userId);
 
      for (const [groupId, rankInfo] of Object.entries(allRanks)) {
        if (groupId === String(config.GROUP_ID)) continue; // already handled above
 
        const groupBinds = ADDITIONAL_GROUP_BINDS[groupId];
        if (groupBinds && groupBinds[rankInfo.rank]) {
          groupBinds[rankInfo.rank].forEach(r => rolesToGive.add(r));
        }
      }
 
      // ── Gamepass roles ───────────────────────────────────────────────
      console.log(`🎮 Checking gamepasses for user ${userId}...`);
      const gamepassRoles = await getUserGamepassRoles(userId);
      gamepassRoles.forEach(r => {
        console.log(`🎮 Adding gamepass role: ${r}`);
        rolesToGive.add(r);
      });
      if (gamepassRoles.size > 0) {
        console.log(`✅ Added ${gamepassRoles.size} gamepass role(s) for user ${userId}`);
      }
    }
 
    // ── Department membership follows the rank ───────────────────────────
    // Every rank change funnels through here, so this is where a placement the member
    // can no longer hold is dropped: resignation, termination and demotions all stop
    // leaving them in the department they left.
    // Suspended members are parked at rank 1 and must keep their placement for the
    // restore, so they are skipped. The caller's rank wins over the live lookup because a
    // rank change just written can still be served from the group-membership cache.
    if (!suspensions.has(member.id)) {
      const explicitRank = Number(robloxRank) || 0;
      const liveRank = mainRankSet.size ? Math.max(...mainRankSet) : 0;
      const reconcileRank = explicitRank > 0 ? explicitRank : liveRank;
      if (reconcileRank > 0) {
        await clearStaleStaffPlacement({
          discordId: member.id,
          rank: reconcileRank,
          reason: `Discord role sync at rank ${reconcileRank}`,
          guild,
        }).catch(error => {
          console.warn(`[Placement] Reconcile after role sync failed for ${member.id}:`, error.message);
          return null;
        });
      }
    }

    // ── Resolve role names → Discord Role objects ────────────────────────
    // `member` is passed through so a Director's Lead/Co-Lead choice is read from the
    // roles we just fetched, not from a possibly-cold cache.
    const placementRoleNames = await getPlacementRoleNamesForMember(member.id, mainRankSet, member);
    placementRoleNames.forEach(roleName => rolesToGive.add(roleName));

    const discordRolesToAdd = [];
    for (const roleName of rolesToGive) {
      const role = resolveGuildRoleByName(guild, roleName);
      if (role) discordRolesToAdd.push(role);
    }
    const roleIdsToKeep = new Set(discordRolesToAdd.map(role => role.id));
 
    // ── Build the full set of managed role names ─────────────────────────
    const allBoundRoleNames = getAllBoundRoleNamesForCleanup();
    const allManagedRoleIds = getManagedStructureRoleIds();

    // Roles bound to a Roblox group we could not read this cycle. They are managed
    // names, so without this they would be removed — a failed lookup is not proof the
    // member left the group.
    const unverifiedGroupRoleNames = new Set();
    for (const [groupId, groupBinds] of Object.entries(ADDITIONAL_GROUP_BINDS)) {
      if (!isGroupLookupUnresolved(groupId)) continue;
      for (const roleNames of Object.values(groupBinds)) {
        roleNames.forEach(roleName => unverifiedGroupRoleNames.add(roleName));
      }
    }
 
    // ── Update last-updated timestamp ────────────────────────────────────
    const robloxUsername = verifiedUsers.get(member.id);
    if (robloxUsername) {
      await updateLastUpdatedTimestamp(robloxUsername);
    }
 
    // ── Remove roles the member shouldn't have ───────────────────────────
    const discordRolesToRemove = [];
    member.roles.cache.forEach(role => {
      const managed = allBoundRoleNames.has(role.name) || allManagedRoleIds.has(role.id);
      if (unverifiedGroupRoleNames.has(role.name)) return;
      if (managed && !rolesToGive.has(role.name) && !roleIdsToKeep.has(role.id)) {
        discordRolesToRemove.push(role);
      }
    });
    const unverifiedRole = guild.roles.cache.get(VERIFICATION_THREAD_CONFIG.UNVERIFIED_ROLE_ID);
    if (
      unverifiedRole &&
      member.roles.cache.has(unverifiedRole.id) &&
      !discordRolesToRemove.some(role => role.id === unverifiedRole.id)
    ) {
      discordRolesToRemove.push(unverifiedRole);
    }
 
    if (discordRolesToRemove.length > 0) await member.roles.remove(discordRolesToRemove);
    if (discordRolesToAdd.length > 0)    await member.roles.add(discordRolesToAdd);
 
    console.log(
      `✅ Roles updated for ${member.user.tag}:`,
      `+[${discordRolesToAdd.map(r => r.name).join(', ')}]`,
      `-[${discordRolesToRemove.map(r => r.name).join(', ')}]`,
    );
 
    return {
      added:   discordRolesToAdd.map(r => r.name),
      removed: discordRolesToRemove.map(r => r.name),
    };
  } catch (error) {
    console.error('Error updating Discord roles:', error.message);
    return null;
  }
}


// Update nickname
async function updateDiscordNickname(member, nickname) {
  try {
    if (member.manageable) {
      const trimmedNickname = nickname.substring(0, 32);
      if (member.nickname !== trimmedNickname) {
        await member.setNickname(trimmedNickname);
        console.log(
          `Successfully updated nickname for ${member.user.tag} to ${trimmedNickname}`,
        );
        return true;
      }
      return false;
    } else {
      console.warn(
        `Cannot update nickname for ${member.user.tag}. Bot lacks 'Manage Nicknames' permission or member is higher/equal role.`,
      );
      return false;
    }
  } catch (error) {
    console.error(
      `Error updating nickname for ${member.user.tag} to ${nickname}:`,
      error.message,
    );
    return false;
  }
}

