// Parse length to ms
function parseLengthToMs(length) {
  const regex = /(\d+)\s*(d|h|m|s)/i;
  const match = length.match(regex);
  if (!match) return null;
  const value = parseInt(match[1]);
  const unit = match[2].toLowerCase();
  switch (unit) {
    case "d":
      return value * 24 * 60 * 60 * 1000;
    case "h":
      return value * 60 * 60 * 1000;
    case "m":
      return value * 60 * 1000;
    case "s":
      return value * 1000;
    default:
      return null;
  }
}

// Schedule suspension restore
function scheduleSuspensionRestore(discordId, timeoutMs) {
  const MAX_TIMEOUT_MS = 2_147_483_647; // ~24.8 days — Node.js 32-bit setTimeout limit
  if (timeoutMs > MAX_TIMEOUT_MS) {
    // Duration exceeds the limit — skip the in-process timer.
    // loadSuspensions() will catch and restore this on the next bot restart.
    console.log(`⏰ Suspension for ${discordId} exceeds 32-bit timeout limit (${Math.round(timeoutMs / 86400000)}d). Will restore on next restart.`);
    return;
  }
  setTimeout(async () => {
    const susp = suspensions.get(discordId);
    if (!susp) return;
    const result = await restoreFromSuspension(discordId, susp);
    if (result && result.ok) {
      suspensions.delete(discordId);
      await saveSuspensions();
    } else {
      console.error(
        `⚠️ Suspension restore for ${discordId} did not complete (${result?.reason || 'unknown reason'}) — keeping the record so it is retried on the next restart.`,
      );
    }
  }, timeoutMs);
}

// Restore from suspension
async function restoreFromSuspension(discordId, susp) {
  try {
    const robloxUsername = verifiedUsers.get(discordId);
    if (!robloxUsername) return { ok: false, reason: "no linked Roblox username" };
    const userId = await getRobloxUserId(robloxUsername);
    if (!userId) return { ok: false, reason: "Roblox user could not be resolved" };
    const originalRole = await resolveGroupRoleByRank(susp.originalRank);
    if (!originalRole) {
      return { ok: false, reason: `rank ${susp.originalRank} no longer exists in the group` };
    }
    const restoreResult = await applyRobloxRank({ userId, roleId: originalRole.id });
    if (!restoreResult.ok) {
      return { ok: false, reason: restoreResult.error || "Roblox rank change failed" };
    }

    const guild = getPrimaryGuild();
    if (guild) {
      const member = await guild.members.fetch(discordId).catch(() => null);
      if (member) {
        await updateDiscordRoles(member, susp.originalRank, userId);
        const suspendedRole = guild.roles.cache.find(
          (r) => r.name === config.SUSPENDED_ROLE_NAME,
        );
        if (suspendedRole) {
          await member.roles.remove(suspendedRole);
        }
      }
    }
    return { ok: true, reason: null };
  } catch (error) {
    console.error("Error restoring from suspension:", error.message);
    return { ok: false, reason: error.message };
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// BOOSTER PERKS — Helpers
// ══════════════════════════════════════════════════════════════════════════════

/** Returns true if the guild is at boost level 2 or higher */
function boosterIsLevel2(guild) {
  return guild.premiumTier >= 2;
}

/** Returns true if the member is currently boosting */
function isBoosting(member) {
  return !!member.premiumSince;
}

/** Resolves an integer colour from a hex string like "#ff69b4". Returns 0xffffff on invalid input. */
function boosterResolveColour(hex) {
  if (!hex) return 0xffffff;
  const val = parseInt(hex.replace(/^#/, ''), 16);
  return isNaN(val) ? 0xffffff : val;
}

/** Validates a hex colour string. */
function boosterIsValidHex(hex) {
  return /^#?[0-9a-fA-F]{6}$/.test((hex || '').trim());
}

/**
 * Returns the position the custom role should sit at —
 * one slot above the booster's current highest role (excluding @everyone and their own custom role).
 */
function boosterTargetPosition(member, customRoleId) {
  const highest = member.roles.cache
    .filter(r => r.id !== member.guild.id && r.id !== customRoleId)
    .sort((a, b) => b.position - a.position)
    .first();
  return highest ? highest.position + 1 : 1;
}

/**
 * Creates a custom role for the booster, saves it to MongoDB,
 * assigns it to the member, and positions it correctly.
 */
async function boosterCreateCustomRole(guild, member, roleName, colour, iconURL) {
  const colorInt = boosterResolveColour(colour);
  const roleOptions = {
    name:        roleName,
    color:       colorInt,
    reason:      `Booster perk — custom role for ${member.user.tag}`,
    permissions: [],
  };
  if (iconURL && boosterIsLevel2(guild)) roleOptions.icon = iconURL;

  const role = await guild.roles.create(roleOptions);
  await member.roles.add(role, 'Booster custom role assigned');

  // Position it just above the member's highest current role
  try {
    const pos = boosterTargetPosition(member, role.id);
    await guild.roles.setPositions([{ role: role.id, position: pos }]);
  } catch { /* Non-fatal — role still works if positioning fails */ }

  await BoosterRole.findOneAndUpdate(
    { userId: member.id },
    { userId: member.id, roleId: role.id, guildId: guild.id, roleName, colour: colour || '#ffffff', iconURL: iconURL || null, updatedAt: new Date() },
    { upsert: true, new: true }
  );

  return role;
}

/** Deletes the custom role from the guild and removes the MongoDB record. */
async function boosterDeleteCustomRole(guild, doc) {
  try {
    const role = guild.roles.cache.get(doc.roleId);
    if (role) await role.delete('Booster stopped — custom role removed');
  } catch (err) {
    console.warn(`[BoosterPerks] Could not delete role ${doc.roleId}:`, err.message);
  }
  await BoosterRole.deleteOne({ userId: doc.userId });
}

/** Repositions the custom role to always sit above the booster's highest role. */
async function boosterSyncRolePosition(guild, member, doc) {
  const role = guild.roles.cache.get(doc.roleId);
  if (!role) return;
  try {
    const desired = boosterTargetPosition(member, doc.roleId);
    if (role.position !== desired) {
      await guild.roles.setPositions([{ role: role.id, position: desired }]);
    }
  } catch { /* Non-fatal */ }
}

/** Builds the main /boosterperks embed showing current role settings. */
function boosterBuildEmbed(member, doc, guild) {
  const hasRole = !!doc;
  const lv2     = boosterIsLevel2(guild);
  const embed   = new EmbedBuilder()
    .setColor(hasRole ? boosterResolveColour(doc?.colour) : 0xf47fff)
    .setTitle('🚀 Your Booster Perks')
    .setDescription(
      `Thank you for boosting **${guild.name}**! 💗\n\n` +
      `As a Nitro Booster, you get a **fully custom role** — pick your own name, colour${lv2 ? ', gradient, and icon' : ''} and more.`
    )
    .setThumbnail(member.user.displayAvatarURL({ dynamic: true }));

  if (hasRole) {
    embed.addFields(
      { name: '🏷️ Role Name', value: doc.roleName, inline: true },
      { name: '🎨 Colour',    value: doc.colour,    inline: true },
    );
    if (doc.iconURL) embed.addFields({ name: '🖼️ Icon', value: '[Set]', inline: true });
    if (doc.gradient && doc.gradient.length === 2) {
      embed.addFields({
        name:  '🌈 Gradient',
        value: `${doc.gradient[0]} → ${doc.gradient[1]}`,
        inline: false,
      });
    }
    embed.addFields({ name: '\u200b', value: 'Use the buttons below to edit your role.', inline: false });
  } else {
    embed.addFields({ name: '✨ Ready to claim?', value: 'Click **Create Role** to set up your custom role!', inline: false });
  }

  embed.setFooter({ text: lv2 ? 'Server Level 2 unlocked — role icons & gradient styles available!' : 'Role icons & gradients unlock at Server Level 2 (2+ boosts)' });
  return embed;
}

/** Builds the action row for the /boosterperks embed. */
function boosterBuildComponents(hasRole) {
  const row = new ActionRowBuilder();
  if (!hasRole) {
    row.addComponents(
      new ButtonBuilder().setCustomId('bperks_create').setLabel('Create Role').setEmoji('✨').setStyle(ButtonStyle.Success)
    );
  } else {
    row.addComponents(
      new ButtonBuilder().setCustomId('bperks_edit_name').setLabel('Edit Name').setEmoji('🏷️').setStyle(ButtonStyle.Primary),
      new ButtonBuilder().setCustomId('bperks_edit_colour').setLabel('Edit Colour').setEmoji('🎨').setStyle(ButtonStyle.Primary),
      new ButtonBuilder().setCustomId('bperks_edit_icon').setLabel('Edit Icon').setEmoji('🖼️').setStyle(ButtonStyle.Primary),
      new ButtonBuilder().setCustomId('bperks_delete').setLabel('Delete Role').setEmoji('🗑️').setStyle(ButtonStyle.Danger)
    );
  }
  return row;
}

// ══════════════════════════════════════════════════════════════════════════════
// GIVEAWAY SYSTEM
// ══════════════════════════════════════════════════════════════════════════════

const GIVEAWAY_HOST_ROLES = [
  '1482846276973236324', // Giveaway Host (Sponsor 5+ giveaways)
  SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Executive Board"],
  SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Executive Director"],
  SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Vice President"],
  SWEETSIEZ_STRUCTURE_CONFIG.ROLES.President,
  '1449335609733943296', // Leadership Team
];

// Single shared giveaway host-role check (previously duplicated in every
// giveaway subcommand as hasGiveawayHostRole / 2 / 3).
function hasGiveawayHostRole(member) {
  if (!member || !member.roles) return false;
  return GIVEAWAY_HOST_ROLES.some(roleId => member.roles.cache.has(roleId));
}

// In-memory giveaway store: messageId -> giveaway object
const activeGiveaways = new Map();
// Finished giveaways store (for rerolls): messageId -> giveaway
const finishedGiveaways = new Map();
const GIVEAWAY_TIMEOUT_MAX_MS = 2147483647;

function normalizeGiveawayRequirements(requirements) {
  requirements = requirements || {};
  return {
    minMessages: Math.max(0, Number(requirements.minMessages || 0)),
    roleId: requirements.roleId || null,
    requireBooster: requirements.requireBooster === true,
    requireServerTag: requirements.requireServerTag === true,
    requireGroup: requirements.requireGroup === true,
    requireVerified: requirements.requireVerified === true,
  };
}

function giveawayEntriesArray(giveaway) {
  if (!giveaway || !giveaway.entries) return [];
  return giveaway.entries instanceof Set ? [...giveaway.entries] : [...giveaway.entries];
}

function giveawayMessageCountsToMap(rawCounts) {
  if (!rawCounts) return new Map();
  if (rawCounts instanceof Map) {
    return new Map([...rawCounts.entries()].map(function(pair) {
      return [pair[0], Number(pair[1]) || 0];
    }));
  }
  return new Map(Object.entries(rawCounts).map(function(pair) {
    return [pair[0], Number(pair[1]) || 0];
  }));
}

function normalizeGiveaway(raw) {
  const data = raw && typeof raw.toObject === 'function' ? raw.toObject() : (raw || {});
  return {
    messageId: data.messageId,
    guildId: data.guildId,
    channelId: data.channelId,
    prize: data.prize,
    description: data.description || null,
    winnerCount: Number(data.winnerCount || 1),
    hostedBy: data.hostedBy,
    startedAt: Number(data.startedAt || Date.now()),
    endsAt: Number(data.endsAt || Date.now()),
    entries: new Set(data.entries || []),
    winners: Array.isArray(data.winners) ? data.winners : [],
    ended: data.ended === true,
    finishedAt: data.finishedAt ? Number(data.finishedAt) : null,
    messageCounts: giveawayMessageCountsToMap(data.messageCounts),
    requirements: normalizeGiveawayRequirements(data.requirements),
  };
}

function giveawayToMongo(giveaway) {
  const messageCounts = {};
  const counts = giveawayMessageCountsToMap(giveaway.messageCounts);
  for (const [userId, count] of counts.entries()) {
    messageCounts[userId] = count;
  }
  return {
    messageId: giveaway.messageId,
    guildId: giveaway.guildId,
    channelId: giveaway.channelId,
    prize: giveaway.prize,
    description: giveaway.description || null,
    winnerCount: giveaway.winnerCount,
    hostedBy: giveaway.hostedBy,
    startedAt: giveaway.startedAt,
    endsAt: giveaway.endsAt,
    entries: giveawayEntriesArray(giveaway),
    winners: Array.isArray(giveaway.winners) ? giveaway.winners : [],
    ended: giveaway.ended === true,
    finishedAt: giveaway.finishedAt || null,
    messageCounts,
    requirements: normalizeGiveawayRequirements(giveaway.requirements),
    updatedAt: new Date(),
  };
}

async function saveGiveaway(giveaway) {
  if (!giveaway || !giveaway.messageId) return;
  try {
    await Giveaway.findOneAndUpdate(
      { messageId: giveaway.messageId },
      { $set: giveawayToMongo(giveaway) },
      { upsert: true, setDefaultsOnInsert: true }
    );
  } catch (error) {
    console.error('Error saving giveaway to MongoDB:', error.message);
  }
}

function formatGiveawayRequirements(giveaway) {
  const requirements = normalizeGiveawayRequirements(giveaway.requirements);
  const parts = [];
  if (requirements.minMessages > 0) {
    parts.push(requirements.minMessages + ' message(s) during this giveaway');
  }
  if (requirements.roleId) {
    parts.push('Must have <@&' + requirements.roleId + '>');
  }
  if (requirements.requireBooster) {
    parts.push('Must be a Nitro Booster');
  }
  if (requirements.requireServerTag) {
    parts.push('Must have this server tag equipped');
  }
  if (requirements.requireGroup) {
    parts.push('Must be in the Roblox group');
  }
  if (requirements.requireVerified) {
    parts.push('Must be verified');
  }
  return parts.length > 0 ? parts.join('\n') : 'None';
}

function hasGiveawayRequirements(giveaway) {
  return formatGiveawayRequirements(giveaway) !== 'None';
}

function getGiveawayMessageCount(giveaway, userId) {
  const counts = giveawayMessageCountsToMap(giveaway.messageCounts);
  return counts.get(userId) || 0;
}

function memberIsBooster(member) {
  if (!member) return false;
  const boosterRole = member.guild.roles.premiumSubscriberRole;
  return Boolean(member.premiumSince || (boosterRole && member.roles.cache.has(boosterRole.id)));
}

function memberHasServerTag(member) {
  const user = member && member.user;
  if (!user || !member.guild) return false;
  const possibleGuildIds = [
    user.primaryGuild && user.primaryGuild.identityGuildId,
    user.primaryGuild && user.primaryGuild.guildId,
    user.primaryGuild && user.primaryGuild.id,
    user.clan && user.clan.identityGuildId,
    user.clan && user.clan.guildId,
    user.clan && user.clan.id,
  ];
  return possibleGuildIds.some(function(id) {
    return id && String(id) === String(member.guild.id);
  });
}

async function checkGiveawayRequirements(giveaway, member, options) {
  options = options || {};
  const includeMessages = options.includeMessages === true;
  const requirements = normalizeGiveawayRequirements(giveaway.requirements);
  const missing = [];

  if (!member) {
    return { ok: false, missing: ['You must still be in the server.'] };
  }

  if (requirements.roleId && !member.roles.cache.has(requirements.roleId)) {
    missing.push('You need the <@&' + requirements.roleId + '> role.');
  }

  if (requirements.requireBooster && !memberIsBooster(member)) {
    missing.push('You need to be a Nitro Booster.');
  }

  if (requirements.requireServerTag && !memberHasServerTag(member)) {
    missing.push('You need this server tag equipped.');
  }

  const isVerified = verifiedUsers.has(member.id);
  if (requirements.requireVerified && !isVerified) {
    missing.push('You need to be verified.');
  }

  if (requirements.requireGroup) {
    if (!config.GROUP_ID) {
      missing.push('Roblox group checks are not configured yet.');
    } else if (!isVerified) {
      missing.push('You need to be verified so I can check Roblox group membership.');
    } else {
      const robloxUsername = verifiedUsers.get(member.id);
      const robloxUserId = await getRobloxUserId(robloxUsername);
      const rankInfo = robloxUserId ? await getUserRankInGroup(robloxUserId, config.GROUP_ID) : null;
      if (!rankInfo || rankInfo.rank <= 0) {
        missing.push('Your verified Roblox account needs to be in the group.');
      }
    }
  }

  if (includeMessages && requirements.minMessages > 0) {
    const count = getGiveawayMessageCount(giveaway, member.id);
    if (count < requirements.minMessages) {
      missing.push('You need ' + requirements.minMessages + ' message(s) during this giveaway. Current: ' + count + '/' + requirements.minMessages + '.');
    }
  }

  return { ok: missing.length === 0, missing };
}

async function getEligibleGiveawayEntries(giveaway) {
  const entries = giveawayEntriesArray(giveaway);
  if (!hasGiveawayRequirements(giveaway)) return entries;

  const guild = client.guilds.cache.get(giveaway.guildId);
  if (!guild) return entries;

  const eligible = [];
  for (const userId of entries) {
    const member = await guild.members.fetch(userId).catch(function() { return null; });
    const result = await checkGiveawayRequirements(giveaway, member, { includeMessages: true });
    if (result.ok) eligible.push(userId);
  }
  return eligible;
}

function scheduleGiveawayEnd(giveaway) {
  if (!giveaway || giveaway.ended) return;
  const delay = giveaway.endsAt - Date.now();
  if (delay <= 0) {
    setTimeout(async function() {
      const still = activeGiveaways.get(giveaway.messageId);
      if (still && !still.ended) await endGiveaway(still);
    }, 1000);
    return;
  }

  setTimeout(async function() {
    const still = activeGiveaways.get(giveaway.messageId);
    if (!still || still.ended) return;
    if (Date.now() >= still.endsAt) await endGiveaway(still);
    else scheduleGiveawayEnd(still);
  }, Math.min(delay, GIVEAWAY_TIMEOUT_MAX_MS));
}

async function loadGiveaways() {
  try {
    activeGiveaways.clear();
    finishedGiveaways.clear();
    const docs = await Giveaway.find({});
    for (const doc of docs) {
      const giveaway = normalizeGiveaway(doc);
      if (giveaway.ended) {
        finishedGiveaways.set(giveaway.messageId, giveaway);
      } else {
        activeGiveaways.set(giveaway.messageId, giveaway);
        scheduleGiveawayEnd(giveaway);
      }
    }
    console.log('Loaded ' + activeGiveaways.size + ' active giveaway(s) and ' + finishedGiveaways.size + ' finished giveaway(s) from MongoDB');
  } catch (error) {
    console.error('Error loading giveaways from MongoDB:', error.message);
  }
}

async function trackGiveawayMessage(message) {
  if (!message.guild || message.author.bot) return;
  if (activeGiveaways.size === 0) return;

  const now = Date.now();
  const updates = [];
  for (const giveaway of activeGiveaways.values()) {
    if (giveaway.ended || giveaway.guildId !== message.guild.id) continue;
    const requirements = normalizeGiveawayRequirements(giveaway.requirements);
    if (requirements.minMessages <= 0) continue;
    if (now < giveaway.startedAt || now > giveaway.endsAt) continue;

    const current = getGiveawayMessageCount(giveaway, message.author.id);
    giveaway.messageCounts.set(message.author.id, current + 1);
    updates.push(Giveaway.updateOne(
      { messageId: giveaway.messageId },
      { $inc: { ['messageCounts.' + message.author.id]: 1 }, $set: { updatedAt: new Date() } }
    ));
  }

  if (updates.length > 0) {
    await Promise.all(updates).catch(function(error) {
      console.error('Error updating giveaway message counts:', error.message);
    });
  }
}

/**
 * Parse a duration string like "10m", "2h", "1d" into milliseconds.
 */
function parseGiveawayDuration(str) {
  const match = str.trim().match(/^(\d+)\s*(s|m|h|d)$/i);
  if (!match) return null;
  const n = parseInt(match[1]);
  const unit = match[2].toLowerCase();
  const multipliers = { s: 1000, m: 60000, h: 3600000, d: 86400000 };
  return n * multipliers[unit];
}

/**
 * Format milliseconds into a readable string.
 */
function formatGiveawayDuration(ms) {
  const d = Math.floor(ms / 86400000);
  const h = Math.floor((ms % 86400000) / 3600000);
  const m = Math.floor((ms % 3600000) / 60000);
  const s = Math.floor((ms % 60000) / 1000);
  const parts = [];
  if (d) parts.push(d + 'd');
  if (h) parts.push(h + 'h');
  if (m) parts.push(m + 'm');
  if (s && !d && !h) parts.push(s + 's');
  return parts.join(' ') || '0s';
}

/**
 * Pick random unique winners from an array of user IDs.
 */
function pickGiveawayWinners(entries, count) {
  const pool = [...entries];
  const winners = [];
  while (winners.length < count && pool.length > 0) {
    const idx = Math.floor(Math.random() * pool.length);
    winners.push(pool.splice(idx, 1)[0]);
  }
  return winners;
}

/**
 * Build the giveaway embed.
 */
function buildGiveawayEmbed(giveaway, ended) {
  ended = ended || false;
  const endsAt = Math.floor(giveaway.endsAt / 1000);
  if (!(giveaway.entries instanceof Set)) giveaway.entries = new Set(giveaway.entries || []);
  const embed = new EmbedBuilder()
    .setTitle('🎉 ' + giveaway.prize)
    .setColor(ended ? 0x808080 : 0xff73fa)
    .addFields(
      { name: '🏆 Winners', value: giveaway.winnerCount.toString(), inline: true },
      { name: '🎟️ Entries', value: giveaway.entries.size.toString(), inline: true },
      { name: ended ? '⏰ Ended' : '⏰ Ends', value: '<t:' + endsAt + ':R>', inline: true },
      { name: '👑 Hosted by', value: '<@' + giveaway.hostedBy + '>', inline: true }
    )
    .setFooter({ text: ended ? 'Giveaway ended' : 'Click 🎉 to enter!' })
    .setTimestamp(giveaway.endsAt);

  if (giveaway.description) {
    embed.setDescription(giveaway.description);
  }

  if (hasGiveawayRequirements(giveaway)) {
    embed.addFields({ name: 'Requirements', value: formatGiveawayRequirements(giveaway), inline: false });
  }

  if (ended && giveaway.winners && giveaway.winners.length > 0) {
    embed.addFields({ name: '🎊 Winners', value: giveaway.winners.map(function(id) { return '<@' + id + '>'; }).join(', '), inline: false });
  } else if (ended) {
    embed.addFields({ name: '🎊 Winners', value: 'No valid entries.', inline: false });
  }

  return embed;
}

/**
 * End a giveaway, pick winners, update the message.
 */
async function finalizeGiveawayWinners(giveaway) {
  const entries = await getEligibleGiveawayEntries(giveaway);
  const winnerCount = Math.min(giveaway.winnerCount, entries.length);
  const winners = pickGiveawayWinners(entries, winnerCount);
  giveaway.winners = winners;
  giveaway.finishedAt = Date.now();
  finishedGiveaways.set(giveaway.messageId, giveaway);
  await saveGiveaway(giveaway);
  return winners;
}

async function endGiveaway(giveaway) {
  if (!giveaway || giveaway.ended) return;
  giveaway.ended = true;
  activeGiveaways.delete(giveaway.messageId);

  const channel = await client.channels.fetch(giveaway.channelId).catch(function() { return null; });
  if (!channel) {
    await finalizeGiveawayWinners(giveaway);
    return;
  }

  const msg = await channel.messages.fetch(giveaway.messageId).catch(function() { return null; });
  if (!msg) {
    await finalizeGiveawayWinners(giveaway);
    return;
  }

  const winners = await finalizeGiveawayWinners(giveaway);

  const embed = buildGiveawayEmbed(giveaway, true);
  await msg.edit({ embeds: [embed], components: [] }).catch(console.error);

  if (winners.length > 0) {
    await channel.send({
      content: '🎉 Congratulations ' + winners.map(function(id) { return '<@' + id + '>'; }).join(', ') + '! You won **' + giveaway.prize + '**!',
    }).catch(console.error);
  } else {
    await channel.send({ content: '😔 No one entered the **' + giveaway.prize + '** giveaway.' }).catch(console.error);
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// /restrict  +  /unrestrict — per-member channel visibility lock
//
// /restrict denies ViewChannel for one member on every channel they can
// currently see — the whole "public" surface of the server — so the channels
// simply vanish from their sidebar. No DM is sent, no role is removed, and
// nothing else about their membership changes.
//
// /unrestrict is the undo: it puts the ViewChannel bit back to neutral so the
// member's normal role and category permissions apply again.
//
// The restriction is stored in Mongo, not just in channel overwrites, so it is
// re-applied when the member rejoins, when the bot starts (or reconnects), and
// when a new channel is created. /unrestrict clears both the overwrites and the
// stored record — a rejoining member is never re-locked after that.
//
// Both are locked to the President (rank 255) or a Discord Administrator.
// ══════════════════════════════════════════════════════════════════════════════

// Channel kinds that carry member permission overwrites. Categories are skipped
// (the per-channel denies already cover their children) and threads are skipped
// (they inherit visibility from the parent channel).
const RESTRICT_CHANNEL_TYPES = new Set([
  ChannelType.GuildText,
  ChannelType.GuildAnnouncement,
  ChannelType.GuildVoice,
  ChannelType.GuildStageVoice,
  ChannelType.GuildForum,
  ChannelType.GuildMedia,
]);

// One overwrite write per channel; small batches stay inside Discord's per-route
// rate limit while keeping the whole sweep down to a few seconds.
const RESTRICT_OVERWRITE_BATCH_SIZE = 4;

// guildId -> Set<userId> mirror of the restricted_members collection, so hot
// paths (a channel being created, a member rejoining) do not need a DB round trip.
const restrictedMembersByGuild = new Map();

function rememberRestrictedMember(guildId, userId) {
  if (!guildId || !userId) return;
  let set = restrictedMembersByGuild.get(guildId);
  if (!set) {
    set = new Set();
    restrictedMembersByGuild.set(guildId, set);
  }
  set.add(userId);
}

function forgetRestrictedMember(guildId, userId) {
  const set = restrictedMembersByGuild.get(guildId);
  if (!set) return;
  set.delete(userId);
  if (set.size === 0) restrictedMembersByGuild.delete(guildId);
}

function isMongoReady() {
  return mongoose.connection.readyState === 1;
}

/** Adds (restore=false) or clears (restore=true) one member's ViewChannel deny
 * on every channel they can currently see. Shared by the slash commands, the
 * rejoin hook and the startup sweep so a re-applied lock behaves exactly like a
 * manual one. Never sends the target anything. */
async function sweepChannelViewOverwrites(guild, targetMember, { restore = false, reason = "", executorTag = "" } = {}) {
  const pending = [];
  let skipped = 0;

  for (const channel of guild.channels.cache.values()) {
    if (!RESTRICT_CHANNEL_TYPES.has(channel.type)) continue;
    const existing = channel.permissionOverwrites?.cache?.get(targetMember.id) || null;
    const alreadyDenied = Boolean(existing?.deny?.has(PermissionFlagsBits.ViewChannel));

    if (restore) {
      if (alreadyDenied) pending.push(channel);
      else skipped += 1;
      continue;
    }
    if (alreadyDenied) {
      skipped += 1;
      continue;
    }
    if (!channel.permissionsFor(targetMember)?.has(PermissionFlagsBits.ViewChannel)) {
      skipped += 1;
      continue;
    }
    pending.push(channel);
  }

  const verb = restore ? "unrestrict" : "restrict";
  const auditReason = `/${verb}${executorTag ? ` by ${executorTag}` : ""}${reason ? ` — ${reason}` : ""}`.slice(0, 500);
  const overwriteOptions = restore ? { ViewChannel: null } : { ViewChannel: false };
  const changed = [];
  const failed = [];

  for (let index = 0; index < pending.length; index += RESTRICT_OVERWRITE_BATCH_SIZE) {
    const batch = pending.slice(index, index + RESTRICT_OVERWRITE_BATCH_SIZE);
    const results = await Promise.all(batch.map(async channel => {
      for (let attempt = 1; attempt <= 2; attempt += 1) {
        try {
          await channel.permissionOverwrites.edit(targetMember.user || targetMember, overwriteOptions, { reason: auditReason });
          return { channel, ok: true };
        } catch (error) {
          const retryMs = getGatewayRetryMs(error);
          if (attempt === 2 || !retryMs) return { channel, ok: false, error };
          await waitMs(Math.min(retryMs, 5000));
        }
      }
      return { channel, ok: false };
    }));

    for (const result of results) {
      if (result.ok) changed.push(result.channel);
      else failed.push(result);
    }
    if (index + RESTRICT_OVERWRITE_BATCH_SIZE < pending.length) await waitMs(300);
  }

  return { skipped, changed, failed };
}

async function getPersistedChannelRestriction(guildId, userId) {
  if (!isMongoReady()) return null;
  return RestrictedMember.findOne({ guildId, userId }).lean().catch(() => null);
}

/** Stores the intent so the lock survives a rejoin. Returns the saved record, or
 * null when Mongo is unavailable (the caller then warns the admin). */
async function persistChannelRestriction({ guildId, userId, reason, executorId, executorTag, applied, failedCount }) {
  rememberRestrictedMember(guildId, userId);
  if (!isMongoReady()) return null;
  try {
    return await RestrictedMember.findOneAndUpdate(
      { guildId, userId },
      {
        $set: {
          reason: reason || "",
          restrictedBy: executorId || "",
          restrictedByTag: executorTag || "",
          restrictedAt: new Date(),
          lastAppliedAt: new Date(),
          lastAppliedChannels: applied,
          lastApplyFailed: failedCount,
          updatedAt: new Date(),
        },
        $setOnInsert: { createdAt: new Date() },
      },
      { upsert: true, new: true },
    ).lean();
  } catch (error) {
    console.warn(`[ChannelRestriction] Could not persist restriction for ${userId}: ${error.message}`);
    return null;
  }
}

/** Removes the stored intent and returns the record that existed (or null). */
async function takePersistedChannelRestriction(guildId, userId) {
  forgetRestrictedMember(guildId, userId);
  if (!isMongoReady()) return null;
  return RestrictedMember.findOneAndDelete({ guildId, userId }).lean().catch(() => null);
}

async function touchPersistedChannelRestriction(guildId, userId, { applied, failedCount }) {
  if (!isMongoReady()) return;
  await RestrictedMember.updateOne(
    { guildId, userId },
    { $set: { lastAppliedAt: new Date(), lastAppliedChannels: applied, lastApplyFailed: failedCount, updatedAt: new Date() } },
  ).catch(() => null);
}

/** Re-applies a stored restriction to a member who is currently in the guild. */
async function reapplyPersistedChannelRestriction(member, record, context = "rejoin") {
  const guild = member?.guild;
  if (!guild || !record) return null;

  if (member.permissions?.has(PermissionFlagsBits.Administrator)) {
    console.warn(`[ChannelRestriction] Not re-applying for ${member.user?.tag || member.id} — they hold Administrator, which ignores overwrites.`);
    return null;
  }

  const { changed, failed, skipped } = await sweepChannelViewOverwrites(guild, member, {
    restore: false,
    reason: record.reason || "",
    executorTag: "restriction persistence",
  });

  await touchPersistedChannelRestriction(guild.id, member.id, {
    applied: changed.length,
    failedCount: failed.length,
  });

  console.log(
    `[ChannelRestriction] Re-applied restriction to ${member.user?.tag || member.id} (${context}) — ` +
    `${changed.length} updated, ${failed.length} failed, ${skipped} skipped`,
  );

  // Only mirror a re-apply into the mod log when it actually changed something:
  // a restart where the overwrites are still intact should stay silent.
  if (changed.length > 0) {
    await logChannelRestriction({
      guild,
      actor: { id: record.restrictedBy || "", tag: record.restrictedByTag || "" },
      targetMember: member,
      restore: false,
      reason: record.reason || "",
      changed,
      failed,
      skipped,
      context,
    });
  }

  return { changed, failed, skipped };
}

/** Startup pass: reload every stored restriction and re-apply it. Covers members
 * who rejoined (or channels Discord reset) while the bot was offline. */
async function reapplyAllPersistedChannelRestrictions(botClient) {
  if (!isMongoReady()) return { records: 0, applied: 0 };
  if (typeof botClient?.isReady === "function" && !botClient.isReady()) return { records: 0, applied: 0 };

  const records = await RestrictedMember.find({}).limit(500).lean().catch(() => []);
  restrictedMembersByGuild.clear();
  for (const record of records) rememberRestrictedMember(record.guildId, record.userId);

  let applied = 0;
  for (const record of records) {
    const guild = botClient.guilds.cache.get(record.guildId);
    if (!guild) continue;
    const member = guild.members.cache.get(record.userId)
      || await guild.members.fetch(record.userId).catch(() => null);
    if (!member) continue; // not in the server right now — the join hook covers it
    try {
      const result = await reapplyPersistedChannelRestriction(member, record, "bot startup");
      if (result) applied += 1;
    } catch (error) {
      console.warn(`[ChannelRestriction] Startup re-apply failed for ${record.userId}: ${error.message}`);
    }
    await waitMs(250);
  }

  console.log(`[ChannelRestriction] Startup re-apply: ${applied}/${records.length} stored restriction(s) re-locked.`);
  return { records: records.length, applied };
}

// Re-apply the stored lock the moment they come back, in case their member
// overwrites did not survive the leave.
client.on("guildMemberAdd", async member => {
  try {
    if (!member?.guild || member.user?.bot) return;
    const record = await getPersistedChannelRestriction(member.guild.id, member.id);
    if (!record) return;
    await reapplyPersistedChannelRestriction(member, record, "rejoined the server");
  } catch (error) {
    console.warn(`[ChannelRestriction] Re-apply on join failed for ${member?.id}: ${error.message}`);
  }
});

// A role change can hand a restricted member access to channels they could not
// see before, so keep the lock in sync while they are restricted.
client.on("guildMemberUpdate", async (oldMember, newMember) => {
  try {
    const guildId = newMember?.guild?.id;
    if (!guildId) return;
    const restricted = restrictedMembersByGuild.get(guildId);
    if (!restricted?.has(newMember.id)) return;

    const before = oldMember?.roles?.cache;
    const after = newMember.roles?.cache;
    if (before && after && before.size === after.size
      && [...after.values()].every(role => before.has(role.id))) return; // not a role change

    const record = await getPersistedChannelRestriction(guildId, newMember.id);
    if (!record) return;
    await reapplyPersistedChannelRestriction(newMember, record, "roles changed");
  } catch (error) {
    console.warn(`[ChannelRestriction] Re-apply after role change failed: ${error.message}`);
  }
});

// A new channel starts visible to everyone, which would leak the restricted
// member's view again; deny it immediately from the in-memory index.
client.on("channelCreate", async channel => {
  try {
    if (!channel?.guild || !RESTRICT_CHANNEL_TYPES.has(channel.type)) return;
    const restricted = restrictedMembersByGuild.get(channel.guild.id);
    if (!restricted?.size) return;
    for (const userId of [...restricted]) {
      const member = channel.guild.members.cache.get(userId);
      if (!member) continue;
      if (member.permissions?.has(PermissionFlagsBits.Administrator)) continue;
      await channel.permissionOverwrites
        .edit(member.user || member, { ViewChannel: false }, { reason: "Persisted /restrict — new channel" })
        .catch(error => console.warn(`[ChannelRestriction] New-channel deny failed for ${userId}: ${error.message}`));
    }
  } catch (error) {
    console.warn(`[ChannelRestriction] channelCreate hook failed: ${error.message}`);
  }
});


/** True for the President (rank 255), a Discord Administrator, or the owner. */
async function canUseChannelRestriction(interaction) {
  const guild = interaction.guild;
  const member = interaction.member;
  if (!guild || !member) return false;
  if (guild.ownerId === interaction.user.id) return true;
  if (member.permissions?.has(PermissionFlagsBits.Administrator)) return true;
  if (member.roles?.cache?.has(SWEETSIEZ_STRUCTURE_CONFIG.ROLES.President)) return true;
  const rankInfo = await getVerifiedMainRankForDiscord(interaction.user.id).catch(() => null);
  return Number(rankInfo?.rank || 0) >= SWEETSIEZ_STRUCTURE_CONFIG.PRESIDENT_RANK;
}

/** Mirrors /restrict and /unrestrict into the mod log. Never notifies the target. */
async function logChannelRestriction({ guild, actor, targetMember, restore, reason, changed, failed, skipped, context }) {
  const verb = restore ? "unrestrict" : "restrict";
  const actorLabel = actor?.tag || "unknown";
  console.log(
    `[ChannelRestriction] /${verb} ${targetMember.user.tag} (${targetMember.id}) by ${actorLabel} ` +
    `— ${changed.length} updated, ${failed.length} failed, ${skipped} skipped${context ? ` [${context}]` : ""}`,
  );

  const modLogChannelId = config.MOD_LOG_CHANNEL_ID;
  if (!modLogChannelId) return;
  const modLogChannel = guild?.channels?.cache?.get(modLogChannelId)
    || await client.channels.fetch(modLogChannelId).catch(() => null);
  if (!modLogChannel?.send) return;

  const describeFailure = result =>
    `<#${result.channel.id}> — ${(result.error?.message || "unknown error").slice(0, 120)}`;

  const embed = new EmbedBuilder()
    .setTitle(restore ? "🔓 Channel Access Restored" : "🔒 Channel Access Restricted")
    .setColor(restore ? 0x2ecc71 : 0xe74c3c)
    .addFields(
      { name: "Member", value: `<@${targetMember.id}> (${targetMember.user.tag})`, inline: true },
      { name: "Issued by", value: actor?.id ? `<@${actor.id}> (${actorLabel})` : actorLabel, inline: true },
      { name: restore ? "Channels restored" : "Channels restricted", value: String(changed.length), inline: true },
      { name: "Already covered", value: String(skipped), inline: true },
      { name: "Reason", value: reason || "No reason provided", inline: false },
    )
    .setTimestamp();

  if (context) embed.addFields({ name: "Trigger", value: context, inline: true });

  if (changed.length) {
    embed.addFields({
      name: "Channels",
      value: changed.slice(0, 15).map(channel => `<#${channel.id}>`).join(", ").slice(0, 1024),
    });
  }
  if (failed.length) {
    embed.addFields({
      name: `Failed (${failed.length})`,
      value: failed.slice(0, 6).map(describeFailure).join("\n").slice(0, 1024),
    });
  }

  await modLogChannel.send({ embeds: [embed] }).catch(() => null);
}

/** Applies or clears one member's ViewChannel deny across the guild. */
async function handleChannelRestrictionCommand(interaction, { restore = false } = {}) {
  const verb = restore ? "unrestrict" : "restrict";

  if (!(await canUseChannelRestriction(interaction))) {
    return interaction.editReply({
      content: `❌ Only the **President** (rank ${SWEETSIEZ_STRUCTURE_CONFIG.PRESIDENT_RANK}) or a Discord **Administrator** can use \`/${verb}\`. Nothing was changed.`,
    }).catch(() => {});
  }

  const guild = interaction.guild;
  const botMember = guild.members.me;
  const missingPermissions = [];
  if (!botMember?.permissions?.has(PermissionFlagsBits.ManageRoles)) missingPermissions.push("Manage Roles");
  if (!botMember?.permissions?.has(PermissionFlagsBits.ManageChannels)) missingPermissions.push("Manage Channels");
  if (missingPermissions.length) {
    return interaction.editReply({
      content: `❌ I need **${missingPermissions.join("** and **")}** to change per-member channel permissions. Nothing was changed.`,
    }).catch(() => {});
  }

  const targetUser = interaction.options.getUser("user", true);
  const reason = (interaction.options.getString("reason") || "").trim();

  const targetMember = await guild.members.fetch(targetUser.id).catch(() => null);
  if (!targetMember) {
    if (restore) {
      // A stored restriction outlives membership, so /unrestrict still has to be
      // able to clear it for someone who already left.
      if (!isMongoReady()) {
        return interaction.editReply({
          content: `⚠️ <@${targetUser.id}> is not in the server, and MongoDB is offline, so a stored restriction cannot be checked or cleared right now. Try again once it reconnects.`,
        }).catch(() => {});
      }
      const cleared = await takePersistedChannelRestriction(guild.id, targetUser.id);
      return interaction.editReply({
        content: cleared
          ? `🔓 <@${targetUser.id}> is not in the server, so there were no channel overwrites to clear — but their stored restriction is gone, so a rejoin will not re-lock them.`
          : `ℹ️ <@${targetUser.id}> is not in the server and has no stored restriction on record.`,
      }).catch(() => {});
    }
    return interaction.editReply({
      content: `❌ <@${targetUser.id}> is not in this server, so there are no channel permissions to change.`,
    }).catch(() => {});
  }
  if (targetMember.id === interaction.user.id) {
    return interaction.editReply({ content: `❌ You cannot \`/${verb}\` yourself.` }).catch(() => {});
  }
  if (targetMember.id === guild.ownerId) {
    return interaction.editReply({ content: "❌ The server owner keeps access to every channel." }).catch(() => {});
  }
  if (!restore && targetMember.permissions?.has(PermissionFlagsBits.Administrator)) {
    return interaction.editReply({
      content:
        `❌ <@${targetMember.id}> has the **Administrator** permission, which overrides every channel overwrite, so ` +
        "hiding channels from them cannot work while they hold it. Remove that permission first, then run `/restrict` again.",
    }).catch(() => {});
  }

  const { changed, failed, skipped } = await sweepChannelViewOverwrites(guild, targetMember, {
    restore,
    reason,
    executorTag: interaction.user.tag,
  });

  // Persist (or clear) the intent so the lock survives a rejoin. The channel
  // overwrites alone are not durable: a member leaving/rejoining, or a channel
  // reset, can wipe them.
  const mongoReady = isMongoReady();
  const storedRecord = restore
    ? await takePersistedChannelRestriction(guild.id, targetMember.id)
    : await persistChannelRestriction({
        guildId: guild.id,
        userId: targetMember.id,
        reason,
        executorId: interaction.user.id,
        executorTag: interaction.user.tag,
        applied: changed.length,
        failedCount: failed.length,
      });

  const memberLabel = `<@${targetMember.id}>`;
  const plural = count => (count === 1 ? "" : "s");
  const headline = changed.length === 0
    ? (restore
        ? `Nothing to restore — no channel denies \`View Channel\` to ${memberLabel} right now.`
        : `${memberLabel} cannot see any channels right now, so nothing had to change.`)
    : (restore
        ? `Restored ${memberLabel}'s normal channel visibility in **${changed.length}** channel${plural(changed.length)}.`
        : `Hid **${changed.length}** channel${plural(changed.length)} from ${memberLabel}. No DM was sent — the channels just disappear for them.`);

  const persistenceNote = restore
    ? (!mongoReady
        ? "⚠️ MongoDB is offline, so the stored record could not be cleared. Run `/unrestrict` again once it reconnects, or a rejoin may re-lock them."
        : (storedRecord
            ? "The stored restriction is cleared, so a rejoin will not re-lock them."
            : "No stored restriction existed for them; only the channel overwrites were cleared."))
    : (storedRecord
        ? "Stored: this re-applies automatically if they rejoin, or when a new channel is created."
        : "⚠️ Could not save this to the database, so it will NOT survive a rejoin. Re-run `/restrict` once MongoDB is connected.");

  const embed = new EmbedBuilder()
    .setTitle(restore ? "🔓 Channel Access Restored" : "🔒 Channel Access Restricted")
    .setColor(restore ? 0x2ecc71 : 0xe74c3c)
    .setDescription(`${headline}\n\n${persistenceNote}`)
    .addFields(
      { name: "Already covered", value: String(skipped), inline: true },
      {
        name: "Stored",
        value: restore
          ? (!mongoReady ? "Unknown — database offline" : (storedRecord ? "Cleared" : "Nothing stored"))
          : (storedRecord ? "Yes — survives rejoin" : "No — database offline"),
        inline: true,
      },
    )
    .setFooter({
      text: restore
        ? `Re-apply with /restrict user:@${targetMember.user.username}`
        : `Undo with /unrestrict user:@${targetMember.user.username}`,
    })
    .setTimestamp();

  if (failed.length) {
    embed.addFields({
      name: `⚠️ ${failed.length} channel${plural(failed.length)} failed`,
      value: failed
        .slice(0, 6)
        .map(result => `<#${result.channel.id}> — ${(result.error?.message || "unknown error").slice(0, 120)}`)
        .join("\n")
        .slice(0, 1024),
    });
  }

  await interaction.editReply({ embeds: [embed] }).catch(() => {});

  await logChannelRestriction({
    guild,
    actor: { id: interaction.user.id, tag: interaction.user.tag },
    targetMember,
    restore,
    reason,
    changed,
    failed,
    skipped,
  });
}

