function startOnTheDotConversationStarter() {
  const sendAtNext4HourMark = () => {
    const now = new Date();
    const hours = now.getHours();
    const minutes = now.getMinutes();
    const seconds = now.getSeconds();

    // Find the next 4-hour mark (0, 4, 8, 12, 16, 20)
    const nextHour = Math.ceil(hours / 4) * 4;
    let target = new Date(now);
    target.setHours(nextHour, 0, 0, 0); // Next 00:00 of the 4-hour block

    // If we're already past 20:00 today, go to midnight tomorrow
    if (nextHour >= 24) {
      target.setDate(target.getDate() + 1);
      target.setHours(0, 0, 0, 0);
    }

    const delayMs = target.getTime() - now.getTime();

    console.log(
      `Next conversation starter scheduled for ${target.toLocaleString()} (in ${Math.round(delayMs / 60000)} minutes)`,
    );

    setTimeout(() => {
      sendConversationStarter();
      // After sending, schedule the next one (every 4 hours from now on)
      setInterval(sendConversationStarter, 4 * 60 * 60 * 1000);
    }, delayMs);
  };

  sendAtNext4HourMark();
}

async function sendConversationStarter() {
  if (!COMMUNITY_CHANNEL_ID || !COMMUNITY_ROLE_ID) {
    console.warn("Conversation starter skipped: Missing channel/role ID");
    return;
  }

  const guild = client.guilds.cache.first();
  if (!guild) return;

  const channel = await guild.channels
    .fetch(COMMUNITY_CHANNEL_ID)
    .catch(() => null);
  if (!channel?.isTextBased()) {
    console.warn(
      `Community channel ${COMMUNITY_CHANNEL_ID} not found or not text-based.`,
    );
    return;
  }

  const randomQuestion =
    CONVERSATION_STARTERS[
    Math.floor(Math.random() * CONVERSATION_STARTERS.length)
    ];
  const roleMention =
    COMMUNITY_ROLE_ID === guild.id ? "@everyone" : `<@&${COMMUNITY_ROLE_ID}>`;

  const embed = new EmbedBuilder()
    .setColor(0xffb6c1)
    .setTitle(" Conversation Starter!")
    .setDescription(`**${randomQuestion}**\n\nCome chat with us!`)
    .setFooter({ text: "Every 4 hours on the dot • Sweetsiez Community" })
    .setTimestamp();

  await channel
    .send({
      content: `${roleMention}`,
      embeds: [embed],
    })
    .catch((err) => {
      console.error("Failed to send on-the-dot conversation starter:", err);
    });
}

