// ========================================
// STAFF OF THE WEEK SYSTEM
// ========================================

const STAFF_OF_THE_WEEK_ROLE_ID = process.env.STAFF_OF_THE_WEEK_ROLE_ID || '';

async function runStaffOfTheWeek(triggeredBy = 'scheduler') {
  console.log(`🏆 Running Staff of the Week (triggered by: ${triggeredBy})`);

  const guild = client.guilds.cache.first();
  if (!guild) return console.error('Staff of the Week: No guild found');

  const channel = await guild.channels.fetch(config.COMMUNITY_CHANNEL_ID).catch(() => null);
  if (!channel?.isTextBased()) return console.error('Staff of the Week: Community channel not found');

  // 1. Remove old Staff of the Week role from everyone who has it
  if (STAFF_OF_THE_WEEK_ROLE_ID) {
    const roleObj = guild.roles.cache.get(STAFF_OF_THE_WEEK_ROLE_ID);
    if (roleObj) {
      for (const [, member] of roleObj.members) {
        await member.roles.remove(STAFF_OF_THE_WEEK_ROLE_ID).catch(() => {});
      }
    }
  }

  // 2. Build candidate list: verified users with rank 5+, sorted by weekly activity
  const now = new Date();
  const oneWeekAgo = new Date(now - 7 * 24 * 60 * 60 * 1000);

  const candidates = [];

  for (const [discordId, robloxUsername] of verifiedUsers) {
    // Get weekly activity minutes
    const activity = activityData.get(robloxUsername.toLowerCase());
    if (!activity) continue;

    let weeklyMinutes = 0;
    for (const [dateStr, mins] of Object.entries(activity.dailyActivity || {})) {
      if (new Date(dateStr) >= oneWeekAgo) weeklyMinutes += mins;
    }
    if (weeklyMinutes === 0) continue;

    // Check Roblox rank (must be rank 5+)
    const robloxId = await getRobloxUserId(robloxUsername).catch(() => null);
    if (!robloxId) continue;
    const rankData = await getUserRankInGroup(robloxId).catch(() => null);
    if (!rankData || rankData.rank < 5) continue;

    candidates.push({ discordId, robloxUsername, weeklyMinutes, rankData });
  }

  // Sort by weekly activity descending, take top 3
  candidates.sort((a, b) => b.weeklyMinutes - a.weeklyMinutes);
  const top3 = candidates.slice(0, 3);

  if (top3.length === 0) {
    return channel.send('📊 No eligible staff activity recorded this week for Staff of the Week.');
  }

  // 3. Give winners the role and build embed fields
  const medals = ['🥇', '🥈', '🥉'];
  const fields = [];

  for (let i = 0; i < top3.length; i++) {
    const winner = top3[i];
    const hours = Math.floor(winner.weeklyMinutes / 60);
    const mins = winner.weeklyMinutes % 60;
    const timeStr = hours > 0 ? `${hours}h ${mins}m` : `${mins}m`;

    if (STAFF_OF_THE_WEEK_ROLE_ID) {
      const member = await guild.members.fetch(winner.discordId).catch(() => null);
      if (member) await member.roles.add(STAFF_OF_THE_WEEK_ROLE_ID).catch(() => {});
    }

    fields.push({
      name: `${medals[i]} #${i + 1} — ${winner.robloxUsername}`,
      value: `<@${winner.discordId}> • **${winner.rankData.name}**\n⏱️ ${timeStr} this week`,
      inline: false,
    });
  }

  // 4. Post embed
  const embed = new EmbedBuilder()
    .setTitle('🏆 Staff of the Week')
    .setColor(0xffd700)
    .setDescription(`Congratulations to this week's top performers! These staff members went above and beyond at Sweetsiez.\n\u200b`)
    .addFields(fields)
    .setFooter({ text: 'Keep up the great work! • Sweetsiez Staff of the Week' })
    .setTimestamp();

  const mentions = top3.map(w => `<@${w.discordId}>`).join(' ');
  await channel.send({ content: `🎉 ${mentions}`, embeds: [embed] });
  console.log(`✅ Staff of the Week posted with ${top3.length} winner(s)`);
}

/**
 * Schedules Staff of the Week to run every Sunday at noon (EST)
 */
function startStaffOfTheWeekScheduler() {
  const checkInterval = 60 * 1000; // check every minute

  setInterval(() => {
    const now = new Date();
    // Sunday = 0, noon = 12, minute = 0
    if (now.getDay() === 0 && now.getHours() === 12 && now.getMinutes() === 0) {
      runStaffOfTheWeek('weekly scheduler');
    }
  }, checkInterval);

  console.log('✅ Staff of the Week scheduler started (fires every Sunday at noon)');
}

// ========================================
// MONTHLY RECOGNITION SYSTEM
// ========================================

function getMonthlyRecognitionPreviousMonthWindow(referenceDate = new Date()) {
  const easternNow = getEasternDateParts(referenceDate);
  let year = easternNow.year;
  let month = easternNow.month - 1;
  if (month < 1) {
    month = 12;
    year -= 1;
  }

  const startYmd = { year, month, day: 1 };
  const endYmd = month === 12
    ? { year: year + 1, month: 1, day: 1 }
    : { year, month: month + 1, day: 1 };
  const monthDate = easternLocalToDate({ year, month, day: 2 }, 12, 0);
  const monthName = new Intl.DateTimeFormat("en-US", {
    month: "long",
    timeZone: QUOTA_TIME_ZONE,
  }).format(monthDate);

  const monthDates = [];
  let cursor = startYmd;
  while (Date.UTC(cursor.year, cursor.month - 1, cursor.day) < Date.UTC(endYmd.year, endYmd.month - 1, endYmd.day)) {
    monthDates.push(formatYmd(cursor));
    cursor = addDaysToYmd(cursor, 1);
  }

  return {
    start: easternLocalToDate(startYmd),
    end: easternLocalToDate(endYmd),
    startYmd,
    endYmd,
    monthDates,
    monthKey: `${year}-${String(month).padStart(2, "0")}`,
    monthName,
    monthLabel: `${monthName} ${year}`,
  };
}

function getMonthlyRecognitionRewardExpiry(referenceDate = new Date()) {
  const easternNow = getEasternDateParts(referenceDate);
  const nextMonth = easternNow.month === 12
    ? { year: easternNow.year + 1, month: 1, day: 1 }
    : { year: easternNow.year, month: easternNow.month + 1, day: 1 };
  return easternLocalToDate(nextMonth);
}

function getMonthlyRecognitionRewardExpiryForMonthKey(monthKey) {
  const [yearRaw, monthRaw] = String(monthKey || "").split("-");
  let year = Number(yearRaw);
  let month = Number(monthRaw);
  if (!year || !month) return getMonthlyRecognitionRewardExpiry();

  month += 2;
  while (month > 12) {
    month -= 12;
    year += 1;
  }
  return easternLocalToDate({ year, month, day: 1 });
}

function formatMonthlyRecognitionMinutes(minutes) {
  const total = Math.max(0, Math.round(Number(minutes) || 0));
  const hours = Math.floor(total / 60);
  const mins = total % 60;
  if (hours > 0 && mins > 0) return `${hours}h ${mins}m`;
  if (hours > 0) return `${hours}h`;
  return `${mins}m`;
}

function generateMonthlyRecognitionId(monthKey) {
  return `monrec_${monthKey.replace(/[^0-9]/g, "")}_${Date.now().toString(36)}`;
}

function getMonthlyRecognitionAuditId(entry) {
  if (entry.id) return String(entry.id);
  const actorId = entry.actor?.user?.userId || "unknown";
  const actionType = entry.actionType || "Unknown";
  const created = entry.created || new Date().toISOString();
  const target = entry.description?.TargetId || entry.description?.TargetName || entry.description?.AssetId || entry.description?.AssetName || "target";
  return `${created}:${actionType}:${actorId}:${target}`;
}

function getMonthlyRecognitionAuditActor(entry) {
  const actor = entry.actor?.user || {};
  return {
    robloxUserId: actor.userId ? String(actor.userId) : null,
    robloxUsername: actor.username || actor.name || null,
  };
}

function getMonthlyRecognitionAuditTargetName(entry) {
  const desc = entry.description || {};
  return desc.TargetName || desc.AssetName || desc.Name || desc.NewName || null;
}

async function recordMonthlyRecognitionAuditEntry(entry) {
  const actionType = entry?.actionType || "Unknown";
  if (!MONTHLY_RECOGNITION_ASSET_ACTIONS.has(actionType)) return null;

  const actor = getMonthlyRecognitionAuditActor(entry);
  const createdAt = entry.created ? new Date(entry.created) : new Date();
  if (Number.isNaN(createdAt.getTime())) return null;

  const auditId = getMonthlyRecognitionAuditId(entry);
  return MonthlyRecognitionAudit.findOneAndUpdate(
    { auditId },
    {
      $setOnInsert: {
        auditId,
        actionType,
        actorRobloxUserId: actor.robloxUserId,
        actorRobloxUsername: actor.robloxUsername,
        targetName: getMonthlyRecognitionAuditTargetName(entry),
        details: entry.description || {},
        createdAt,
        recordedAt: new Date(),
      },
    },
    { upsert: true, new: true },
  ).catch(error => {
    console.warn("[MonthlyRecognition] Could not record audit entry:", error.message);
    return null;
  });
}

async function fetchMonthlyRecognitionGroupAuditLog(groupId, cursor = null) {
  try {
    const params = { limit: 25, sortOrder: "Desc" };
    if (cursor) params.cursor = cursor;

    const response = await axios.get(
      `https://groups.roblox.com/v1/groups/${groupId}/audit-log`,
      {
        params,
        headers: {
          Cookie: `.ROBLOSECURITY=${config.ROBLOX_COOKIE}`,
        },
        timeout: ROBLOX_HTTP_TIMEOUT_MS,
      },
    );
    return response.data;
  } catch (error) {
    console.warn("[MonthlyRecognition] Audit backfill fetch failed:", error.message);
    return null;
  }
}

async function backfillMonthlyRecognitionAssetAudits(windowInfo) {
  if (!config.GROUP_ID) return 0;

  let cursor = null;
  let pages = 0;
  let saved = 0;
  let reachedBeforeWindow = false;

  while (pages < 10 && !reachedBeforeWindow) {
    const auditData = await fetchMonthlyRecognitionGroupAuditLog(config.GROUP_ID, cursor);
    pages += 1;
    if (!auditData || !Array.isArray(auditData.data) || auditData.data.length === 0) break;

    for (const entry of auditData.data) {
      const created = entry.created ? new Date(entry.created) : null;
      if (!created || Number.isNaN(created.getTime())) continue;
      if (created < windowInfo.start) {
        reachedBeforeWindow = true;
        continue;
      }
      if (created >= windowInfo.end) continue;
      if (!MONTHLY_RECOGNITION_ASSET_ACTIONS.has(entry.actionType || "")) continue;
      const doc = await recordMonthlyRecognitionAuditEntry(entry);
      if (doc) saved += 1;
    }

    cursor = auditData.nextPageCursor;
    if (!cursor) break;
  }

  return saved;
}

function isMonthlyRecognitionRankEligible(category, rank) {
  const numericRank = Number(rank || 0);
  if (Array.isArray(category?.eligibleRanks) && category.eligibleRanks.length > 0) {
    return category.eligibleRanks.map(Number).includes(numericRank);
  }
  return numericRank >= Number(category?.minRank || 0) &&
    numericRank <= Number(category?.maxRank ?? 255);
}

async function getMonthlyRecognitionActivityCandidates(categoryKey, windowInfo) {
  const category = MONTHLY_RECOGNITION_CONFIG.CATEGORIES[categoryKey];
  const candidates = [];

  for (const [discordId, robloxUsername] of verifiedUsers.entries()) {
    const robloxUsernameLower = robloxUsername.toLowerCase();
    const activity = activityData.get(robloxUsernameLower);
    if (!activity) continue;

    let minutes = 0;
    for (const dateKey of windowInfo.monthDates) {
      minutes += Number(activity.dailyActivity?.[dateKey] || 0);
    }
    if (minutes <= 0) continue;

    const robloxUserId = activity.userId || await getRobloxUserId(robloxUsername).catch(() => null);
    if (!robloxUserId) continue;
    const rankData = await getUserRankInGroup(robloxUserId).catch(() => null);
    if (!rankData || !isMonthlyRecognitionRankEligible(category, rankData.rank)) continue;

    candidates.push({
      discordId,
      robloxUsername,
      robloxUserId: String(robloxUserId),
      rank: rankData.rank,
      rankName: rankData.name,
      score: minutes,
      scoreLabel: formatMonthlyRecognitionMinutes(minutes),
      reason: `${formatMonthlyRecognitionMinutes(minutes)} active in ${windowInfo.monthName}`,
    });
  }

  candidates.sort((a, b) => b.score - a.score || a.robloxUsername.localeCompare(b.robloxUsername));
  return candidates;
}

async function findMonthlyRecognitionDiscordForRoblox(robloxUserId, robloxUsername) {
  const idString = robloxUserId ? String(robloxUserId) : null;
  if (idString) {
    for (const [discordId, cachedId] of robloxIdCache.entries()) {
      if (String(cachedId) === idString) return discordId;
    }
  }

  if (robloxUsername) {
    const direct = _getDiscordIdForRoblox(String(robloxUsername).toLowerCase());
    if (direct) return direct;
  }

  if (idString) {
    for (const [discordId, username] of verifiedUsers.entries()) {
      const resolved = await getRobloxUserId(username).catch(() => null);
      if (resolved && String(resolved) === idString) {
        robloxIdCache.set(discordId, idString);
        return discordId;
      }
    }
  }

  return null;
}

async function getMonthlyRecognitionDeveloperCandidates(windowInfo) {
  await backfillMonthlyRecognitionAssetAudits(windowInfo);

  const docs = await MonthlyRecognitionAudit.find({
    actionType: { $in: Array.from(MONTHLY_RECOGNITION_ASSET_ACTIONS) },
    createdAt: { $gte: windowInfo.start, $lt: windowInfo.end },
  }).lean();

  const counts = new Map();
  for (const doc of docs) {
    const key = doc.actorRobloxUserId || (doc.actorRobloxUsername || "").toLowerCase();
    if (!key) continue;
    if (!counts.has(key)) {
      counts.set(key, {
        robloxUserId: doc.actorRobloxUserId || null,
        robloxUsername: doc.actorRobloxUsername || null,
        score: 0,
        actions: {},
      });
    }
    const entry = counts.get(key);
    entry.score += 1;
    entry.actions[doc.actionType] = (entry.actions[doc.actionType] || 0) + 1;
  }

  const candidates = [];
  for (const entry of counts.values()) {
    const discordId = await findMonthlyRecognitionDiscordForRoblox(entry.robloxUserId, entry.robloxUsername);
    if (!discordId) continue;

    const rankData = await getVerifiedMainRankForDiscord(discordId).catch(() => null);
    if (!rankData || rankData.rank < 19 || rankData.rank > 20) continue;

    candidates.push({
      discordId,
      robloxUsername: rankData.robloxUsername || entry.robloxUsername || "Unknown",
      robloxUserId: String(rankData.robloxUserId || entry.robloxUserId || ""),
      rank: rankData.rank,
      rankName: rankData.rankName,
      score: entry.score,
      scoreLabel: `${entry.score} asset action${entry.score === 1 ? "" : "s"}`,
      reason: `${entry.score} asset action${entry.score === 1 ? "" : "s"} in ${windowInfo.monthName}`,
      actions: entry.actions,
    });
  }

  candidates.sort((a, b) => b.score - a.score || a.robloxUsername.localeCompare(b.robloxUsername));
  return candidates;
}

async function getMonthlyRecognitionEventAttendanceCandidates(windowInfo) {
  const events = await BoardEvent.find({
    status: { $in: ["awaiting_recap", "completed", "active"] },
    $or: [
      { activeStartedAt: { $gte: windowInfo.start, $lt: windowInfo.end } },
      { scheduledAt: { $gte: windowInfo.start, $lt: windowInfo.end } },
    ],
  }).lean();

  const counts = new Map();
  for (const eventDoc of events) {
    const eventKey = eventDoc.eventId;
    const seenForEvent = new Set();
    for (const checkIn of getEventVerifiedCheckIns(eventDoc)) {
      const checkedInAt = checkIn.checkedInAt ? new Date(checkIn.checkedInAt) : new Date(eventActivityDate(eventDoc));
      if (checkedInAt < windowInfo.start || checkedInAt >= windowInfo.end) continue;
      const discordId = String(checkIn.discordId || "");
      if (!discordId || seenForEvent.has(discordId)) continue;
      seenForEvent.add(discordId);
      if (!counts.has(discordId)) {
        counts.set(discordId, {
          discordId,
          events: new Set(),
          rsvpedEvents: 0,
        });
      }
      const entry = counts.get(discordId);
      entry.events.add(eventKey);
      if (checkIn.rsvped) entry.rsvpedEvents += 1;
    }
  }

  const candidates = [];
  for (const entry of counts.values()) {
    const robloxUsername = verifiedUsers.get(entry.discordId) || "Community Member";
    const rankData = await getVerifiedMainRankForDiscord(entry.discordId).catch(() => null);
    const score = entry.events.size;
    if (score <= 0) continue;
    candidates.push({
      discordId: entry.discordId,
      robloxUsername: rankData?.robloxUsername || robloxUsername,
      robloxUserId: String(rankData?.robloxUserId || ""),
      rank: rankData?.rank || 0,
      rankName: rankData?.rankName || "Community",
      score,
      scoreLabel: `${score} verified event check-in${score === 1 ? "" : "s"}`,
      reason: `${score} verified event check-in${score === 1 ? "" : "s"} in ${windowInfo.monthName}`,
      rsvpedEvents: entry.rsvpedEvents,
    });
  }

  candidates.sort((a, b) => b.score - a.score || b.rsvpedEvents - a.rsvpedEvents || a.discordId.localeCompare(b.discordId));
  return candidates;
}

async function calculateMonthlyRecognitionWinners(windowInfo) {
  const winners = {};

  for (const categoryKey of MONTHLY_RECOGNITION_CATEGORY_ORDER) {
    const category = MONTHLY_RECOGNITION_CONFIG.CATEGORIES[categoryKey];
    const candidates = category.scoreType === "asset_audit"
      ? await getMonthlyRecognitionDeveloperCandidates(windowInfo)
      : category.scoreType === "event_attendance"
        ? await getMonthlyRecognitionEventAttendanceCandidates(windowInfo)
        : await getMonthlyRecognitionActivityCandidates(categoryKey, windowInfo);

    winners[categoryKey] = candidates[0] || null;
  }

  return winners;
}

function buildMonthlyRecognitionPreviewEmbed(doc) {
  const embed = new EmbedBuilder()
    .setColor(0xffb6c1)
    .setTitle(`Sweetsiez ${doc.monthName} Recognitions Preview`)
    .setDescription(
      `This preview is based on ${doc.monthLabel} activity, event check-ins, and group-audit data.\n` +
      "Leadership may approve, reroll, or cancel this preview."
    )
    .setFooter({ text: `Recognition ID: ${doc.recognitionId}` })
    .setTimestamp(doc.updatedAt || new Date());

  for (const categoryKey of MONTHLY_RECOGNITION_CATEGORY_ORDER) {
    const category = MONTHLY_RECOGNITION_CONFIG.CATEGORIES[categoryKey];
    const winner = doc.winners?.[categoryKey];
    embed.addFields({
      name: category.label,
      value: winner?.discordId
        ? `<@${winner.discordId}> - **${winner.robloxUsername}** (${winner.rankName || `Rank ${winner.rank}`})\nScore: **${winner.scoreLabel || winner.score || "N/A"}**`
        : "No eligible winner found yet.",
      inline: false,
    });
  }

  if (doc.approvedByTag) {
    embed.addFields({ name: "Approved By", value: doc.approvedByTag, inline: true });
  }

  return embed;
}

function buildMonthlyRecognitionPreviewRows(doc) {
  const disabled = doc.status !== "preview";
  return [
    new ActionRowBuilder().addComponents(
      new ButtonBuilder()
        .setCustomId(`monthlyrec:approve:${doc.recognitionId}`)
        .setLabel("Approve & Post")
        .setStyle(ButtonStyle.Success)
        .setDisabled(disabled),
      new ButtonBuilder()
        .setCustomId(`monthlyrec:reroll:${doc.recognitionId}`)
        .setLabel("Reroll")
        .setStyle(ButtonStyle.Primary)
        .setDisabled(disabled),
      new ButtonBuilder()
        .setCustomId(`monthlyrec:cancel:${doc.recognitionId}`)
        .setLabel("Cancel")
        .setStyle(ButtonStyle.Danger)
        .setDisabled(disabled),
    ),
  ];
}

function getMonthlyRecognitionReviewRoleIds() {
  return (MONTHLY_RECOGNITION_CONFIG.REVIEW_PING_ROLE_IDS || [])
    .filter(Boolean);
}

function formatMonthlyRecognitionReviewMentions() {
  return getMonthlyRecognitionReviewRoleIds()
    .map(roleId => `<@&${roleId}>`)
    .join(" ");
}

async function sendOrUpdateMonthlyRecognitionPreview(clientRef, doc) {
  const channel = await clientRef.channels.fetch(MONTHLY_RECOGNITION_CONFIG.REVIEW_CHANNEL_ID).catch(() => null);
  if (!channel?.isTextBased()) throw new Error("Monthly recognition review channel was not found.");

  const payload = {
    embeds: [buildMonthlyRecognitionPreviewEmbed(doc)],
    components: buildMonthlyRecognitionPreviewRows(doc),
  };

  let message = null;
  if (doc.reviewMessageId) {
    message = await channel.messages.fetch(doc.reviewMessageId).catch(() => null);
    if (message) await message.edit(payload);
  }

  if (!message) {
    const reviewRoleIds = getMonthlyRecognitionReviewRoleIds();
    message = await channel.send({
      content: formatMonthlyRecognitionReviewMentions(),
      allowedMentions: { roles: reviewRoleIds },
      ...payload,
    });
  }

  await MonthlyRecognition.updateOne(
    { recognitionId: doc.recognitionId },
    {
      $set: {
        reviewChannelId: channel.id,
        reviewMessageId: message.id,
        updatedAt: new Date(),
      },
    },
  );

  return message;
}

async function createOrRefreshMonthlyRecognitionPreview(clientRef, generatedBy = null, options = {}) {
  const windowInfo = getMonthlyRecognitionPreviousMonthWindow();
  let doc = await MonthlyRecognition.findOne({
    monthKey: windowInfo.monthKey,
    status: { $in: ["preview", "approved"] },
  });

  if (doc?.status === "approved" && !options.allowApprovedRefresh) {
    return { doc, message: null, alreadyApproved: true };
  }

  const winners = await calculateMonthlyRecognitionWinners(windowInfo);
  const now = new Date();
  if (!doc || options.forceNew) {
    doc = await MonthlyRecognition.create({
      recognitionId: generateMonthlyRecognitionId(windowInfo.monthKey),
      monthKey: windowInfo.monthKey,
      monthName: windowInfo.monthName,
      monthLabel: windowInfo.monthLabel,
      winners,
      generatedByDiscordId: generatedBy?.id || null,
      generatedByTag: generatedBy?.tag || null,
      createdAt: now,
      updatedAt: now,
    });
  } else {
    doc.winners = winners;
    doc.generatedByDiscordId = generatedBy?.id || doc.generatedByDiscordId || null;
    doc.generatedByTag = generatedBy?.tag || doc.generatedByTag || null;
    doc.updatedAt = now;
    await doc.save();
  }

  const message = await sendOrUpdateMonthlyRecognitionPreview(clientRef, doc.toObject ? doc.toObject() : doc);
  return { doc: await MonthlyRecognition.findOne({ recognitionId: doc.recognitionId }).lean(), message };
}

async function requireMonthlyRecognitionApprover(interaction) {
  const rankData = await getVerifiedMainRankForDiscord(interaction.user.id).catch(() => null);
  if (!rankData || rankData.rank < MONTHLY_RECOGNITION_CONFIG.APPROVER_MIN_RANK) {
    return {
      ok: false,
      message: `You must be verified as rank ${MONTHLY_RECOGNITION_CONFIG.APPROVER_MIN_RANK}+ to use monthly recognition controls.`,
    };
  }
  return { ok: true, rankData };
}

function buildMonthlyRecognitionPublicMessage(doc) {
  const lines = [
    `:cupcake: **SWEETSIEZ ${String(doc.monthName || "MONTH").toUpperCase()} RECOGNITIONS**`,
    "",
    `Hey, @everyone! I'll be announcing our monthly recognitions for **${doc.monthName}**! Those who are selected will have their rank of the month role for the entire month, as well as complementary prizes. These are reviewed by our Leadership Team. Congratulations!`,
    "",
  ];

  for (const categoryKey of MONTHLY_RECOGNITION_CATEGORY_ORDER) {
    const category = MONTHLY_RECOGNITION_CONFIG.CATEGORIES[categoryKey];
    const winner = doc.winners?.[categoryKey];
    lines.push(`**${category.label}** - ${winner?.discordId ? `<@${winner.discordId}>` : "Not selected"}`);
  }

  lines.push(
    "",
    "That's all of our recognitions for this month, thank you for your efforts if you were recognized! High hopes next month!",
  );

  return lines.join("\n");
}

function buildMonthlyRecognitionRewardRows(recognitionId, categoryKey) {
  const category = MONTHLY_RECOGNITION_CONFIG.CATEGORIES[categoryKey];
  if (category?.rewardEligible === false) return [];
  return [
    new ActionRowBuilder().addComponents(
      new ButtonBuilder()
        .setCustomId(`monthlyreward:hours:${recognitionId}:${categoryKey}`)
        .setLabel("+5 Hours")
        .setStyle(ButtonStyle.Primary),
      new ButtonBuilder()
        .setCustomId(`monthlyreward:excused:${recognitionId}:${categoryKey}`)
        .setLabel("Excused Week")
        .setStyle(ButtonStyle.Secondary),
      new ButtonBuilder()
        .setCustomId(`monthlyreward:custom:${recognitionId}:${categoryKey}`)
        .setLabel("Custom Role")
        .setStyle(ButtonStyle.Success),
    ),
  ];
}

function buildMonthlyRecognitionRewardDm(doc, categoryKey, winner = null) {
  const category = MONTHLY_RECOGNITION_CONFIG.CATEGORIES[categoryKey];
  if (category?.rewardEligible === false) {
    return [
      ":cupcake: **MONTHLY RECOGNITION**",
      "",
      `Greetings, ${winner?.discordId ? `<@${winner.discordId}>` : "there"}! Congratulations on earning **${category.label}** for this month! :tada:`,
      "",
      "This award is based on verified event check-ins tracked by Sweetsiez Assistant. Thank you for showing up, participating, and helping keep the community active.",
      "",
      "Your monthly recognition role has been applied for the month.",
      "",
      "Much regards,",
      "*Sweetsiez Assistant*",
    ].join("\n");
  }
  return [
    ":cupcake: **STAFF OF THE MONTH AWARDS**",
    "",
    `Greetings, ${winner?.discordId ? `<@${winner.discordId}>` : "there"}! Congratulations on earning **${category.label}** for this upcoming month! :tada:`,
    "",
    "Your hard work, consistency, and positive attitude haven't gone unnoticed, and to celebrate your achievement, you'll be able to choose **one** reward from the list below.",
    "",
    "> - +5 Hours Added to Your Log",
    "> - A Week of Excused Requirements",
    "> - A Custom Personal Role in the Discord for the remainder of the month",
    "",
    "Use the buttons below to choose your reward. Thank you for your ongoing dedication and contribution to Sweetsiez! :sparkling_heart:",
    "",
    "Much regards,",
    "*Sweetsiez Assistant*",
  ].join("\n");
}

async function cleanupMonthlyRecognitionCustomRoles(guild, reason = "monthly recognition cleanup") {
  if (!guild) return 0;
  const now = new Date();
  const docs = await MonthlyRecognitionCustomRole.find({
    active: true,
    expiresAt: { $lte: now },
  });

  let removed = 0;
  for (const doc of docs) {
    const role = guild.roles.cache.get(doc.roleId) || await guild.roles.fetch(doc.roleId).catch(() => null);
    if (role) {
      await role.delete(reason).catch(error =>
        console.warn(`[MonthlyRecognition] Could not delete custom role ${doc.roleId}:`, error.message),
      );
    }
    doc.active = false;
    doc.deletedAt = new Date();
    await doc.save().catch(() => {});
    removed += 1;
  }

  return removed;
}

async function removeMonthlyRecognitionAwardRoles(guild) {
  await guild.members.fetch().catch(() => null);
  for (const category of Object.values(MONTHLY_RECOGNITION_CONFIG.CATEGORIES)) {
    const role = guild.roles.cache.get(category.roleId) || await guild.roles.fetch(category.roleId).catch(() => null);
    if (!role) continue;
    for (const [, member] of role.members) {
      await member.roles.remove(role, "Monthly recognition rollover").catch(() => {});
    }
  }
}

async function applyMonthlyRecognitionAwardRoles(guild, doc) {
  for (const categoryKey of MONTHLY_RECOGNITION_CATEGORY_ORDER) {
    const category = MONTHLY_RECOGNITION_CONFIG.CATEGORIES[categoryKey];
    const winner = doc.winners?.[categoryKey];
    if (!winner?.discordId) continue;
    const member = await guild.members.fetch(winner.discordId).catch(() => null);
    if (!member) continue;
    await member.roles.add(category.roleId, `${category.label} winner`).catch(error =>
      console.warn(`[MonthlyRecognition] Could not add ${category.label} role to ${winner.discordId}:`, error.message),
    );
  }
}

async function sendMonthlyRecognitionRewardDms(doc) {
  for (const categoryKey of MONTHLY_RECOGNITION_CATEGORY_ORDER) {
    const category = MONTHLY_RECOGNITION_CONFIG.CATEGORIES[categoryKey];
    const winner = doc.winners?.[categoryKey];
    if (!winner?.discordId) continue;

    if (category?.rewardEligible !== false) {
      await MonthlyRecognitionReward.findOneAndUpdate(
        { recognitionId: doc.recognitionId, categoryKey, discordId: winner.discordId },
        {
          $setOnInsert: {
            recognitionId: doc.recognitionId,
            monthKey: doc.monthKey,
            categoryKey,
            discordId: winner.discordId,
            robloxUsername: winner.robloxUsername || null,
            createdAt: new Date(),
          },
          $set: { updatedAt: new Date() },
        },
        { upsert: true, new: true },
      );
    }

    const user = await client.users.fetch(winner.discordId).catch(() => null);
    if (!user) continue;
    const components = buildMonthlyRecognitionRewardRows(doc.recognitionId, categoryKey);
    const dmPayload = {
      content: buildMonthlyRecognitionRewardDm(doc, categoryKey, winner),
    };
    if (components.length) dmPayload.components = components;
    await user.send(dmPayload).catch(error =>
      console.warn(`[MonthlyRecognition] Could not DM winner ${winner.discordId}:`, error.message),
    );
  }
}

async function approveMonthlyRecognition(interaction, recognitionId) {
  const doc = await MonthlyRecognition.findOne({ recognitionId });
  if (!doc) return interaction.editReply("I could not find that monthly recognition preview.");
  if (doc.status !== "preview") return interaction.editReply("That monthly recognition preview has already been handled.");

  const guild = interaction.guild || client.guilds.cache.get(SWEETSIEZ_STRUCTURE_CONFIG.GUILD_ID) || client.guilds.cache.first();
  if (!guild) return interaction.editReply("I could not find the server to update roles.");

  const announcementChannel = await client.channels.fetch(MONTHLY_RECOGNITION_CONFIG.ANNOUNCEMENT_CHANNEL_ID).catch(() => null);
  if (!announcementChannel?.isTextBased()) return interaction.editReply("I could not find the public announcements channel.");

  await cleanupMonthlyRecognitionCustomRoles(guild, "Monthly recognition rollover");
  await removeMonthlyRecognitionAwardRoles(guild);
  await applyMonthlyRecognitionAwardRoles(guild, doc.toObject());

  const publicMessage = await announcementChannel.send({
    content: buildMonthlyRecognitionPublicMessage(doc.toObject()),
    allowedMentions: { parse: ["everyone", "users"] },
  });

  doc.status = "approved";
  doc.publicChannelId = announcementChannel.id;
  doc.publicMessageId = publicMessage.id;
  doc.approvedByDiscordId = interaction.user.id;
  doc.approvedByTag = interaction.user.tag;
  doc.approvedAt = new Date();
  doc.updatedAt = new Date();
  await doc.save();

  await sendMonthlyRecognitionPreviewUpdate(doc.toObject());
  await sendMonthlyRecognitionRewardDms(doc.toObject());

  return interaction.editReply(`Monthly recognitions approved and posted: https://discord.com/channels/${guild.id}/${announcementChannel.id}/${publicMessage.id}`);
}

async function sendMonthlyRecognitionPreviewUpdate(doc) {
  if (!doc.reviewChannelId || !doc.reviewMessageId) return;
  const channel = await client.channels.fetch(doc.reviewChannelId).catch(() => null);
  if (!channel?.isTextBased()) return;
  const message = await channel.messages.fetch(doc.reviewMessageId).catch(() => null);
  if (!message) return;
  await message.edit({
    embeds: [buildMonthlyRecognitionPreviewEmbed(doc)],
    components: buildMonthlyRecognitionPreviewRows(doc),
  }).catch(() => {});
}

async function handleMonthlyRecognitionButton(interaction) {
  const parts = interaction.customId.split(":");
  const type = parts[0];

  if (type === "monthlyrec") {
    const action = parts[1];
    const recognitionId = parts.slice(2).join(":");
    if (!interaction.deferred && !interaction.replied) {
      await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
    }

    const access = await requireMonthlyRecognitionApprover(interaction);
    if (!access.ok) return interaction.editReply(access.message);

    if (action === "approve") {
      await interaction.editReply("Approving and posting monthly recognitions...");
      return approveMonthlyRecognition(interaction, recognitionId);
    }

    if (action === "reroll") {
      const existing = await MonthlyRecognition.findOne({ recognitionId });
      if (!existing || existing.status !== "preview") {
        return interaction.editReply("That preview can no longer be rerolled.");
      }
      await interaction.editReply("Refreshing the monthly recognition preview...");
      const result = await createOrRefreshMonthlyRecognitionPreview(interaction.client, interaction.user, { allowApprovedRefresh: false });
      return interaction.editReply(`Monthly recognition preview refreshed for **${result.doc.monthLabel}**.`);
    }

    if (action === "cancel") {
      const doc = await MonthlyRecognition.findOne({ recognitionId });
      if (!doc || doc.status !== "preview") return interaction.editReply("That preview can no longer be cancelled.");
      doc.status = "cancelled";
      doc.updatedAt = new Date();
      await doc.save();
      await sendMonthlyRecognitionPreviewUpdate(doc.toObject());
      return interaction.editReply("Monthly recognition preview cancelled.");
    }
  }

  if (type === "monthlyreward") {
    const action = parts[1];
    const recognitionId = parts[2];
    const categoryKey = parts[3];

    if (action === "custom") {
      const reward = await MonthlyRecognitionReward.findOne({ recognitionId, categoryKey, discordId: interaction.user.id });
      if (!reward) {
        return interaction.reply({ content: "I could not find a reward record for you.", flags: MessageFlags.Ephemeral });
      }
      const { ModalBuilder, TextInputBuilder, TextInputStyle } = require("discord.js");
      const modal = new ModalBuilder()
        .setCustomId(`monthlyreward_modal:${recognitionId}:${categoryKey}`)
        .setTitle("Monthly Custom Role");
      modal.addComponents(
        new ActionRowBuilder().addComponents(
          new TextInputBuilder()
            .setCustomId("role_name")
            .setLabel("Role name")
            .setStyle(TextInputStyle.Short)
            .setMaxLength(80)
            .setRequired(true)
            .setPlaceholder("e.g. June Cupcake Star"),
        ),
        new ActionRowBuilder().addComponents(
          new TextInputBuilder()
            .setCustomId("role_colour")
            .setLabel("Role color hex")
            .setStyle(TextInputStyle.Short)
            .setMaxLength(7)
            .setRequired(false)
            .setPlaceholder("#ffb6c1"),
        ),
      );
      return interaction.showModal(modal);
    }

    if (!interaction.deferred && !interaction.replied) {
      await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
    }
    const reward = await MonthlyRecognitionReward.findOne({ recognitionId, categoryKey, discordId: interaction.user.id });
    if (!reward) return interaction.editReply("I could not find a reward record for you.");
    if (reward.status === "selected") return interaction.editReply("You already selected a monthly recognition reward.");

    const rewardType = action === "hours" ? "hours" : action === "excused" ? "excused" : null;
    if (!rewardType) return interaction.editReply("Unknown reward option.");

    reward.rewardType = rewardType;
    reward.status = "selected";
    reward.selectedAt = new Date();
    reward.updatedAt = new Date();
    if (rewardType === "excused") reward.expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
    await reward.save();

    await notifyMonthlyRecognitionRewardSelection(reward, rewardType === "hours" ? "+5 Hours Added to Log" : "A Week of Excused Requirements");
    return interaction.editReply("Your monthly recognition reward choice has been saved.");
  }
}

async function notifyMonthlyRecognitionRewardSelection(reward, label) {
  const channel = await client.channels.fetch(MONTHLY_RECOGNITION_CONFIG.REVIEW_CHANNEL_ID).catch(() => null);
  if (!channel?.isTextBased()) return;
  await channel.send({
    embeds: [
      new EmbedBuilder()
        .setColor(0xffb6c1)
        .setTitle("Monthly Recognition Reward Selected")
        .addFields(
          { name: "Winner", value: `<@${reward.discordId}>`, inline: true },
          { name: "Reward", value: label, inline: true },
          { name: "Month", value: reward.monthKey, inline: true },
        )
        .setTimestamp(),
    ],
  }).catch(() => {});
}

async function handleMonthlyRecognitionRewardModal(interaction) {
  if (!interaction.deferred && !interaction.replied) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
  }

  const parts = interaction.customId.split(":");
  const recognitionId = parts[1];
  const categoryKey = parts[2];
  const reward = await MonthlyRecognitionReward.findOne({ recognitionId, categoryKey, discordId: interaction.user.id });
  if (!reward) return interaction.editReply("I could not find a reward record for you.");
  if (reward.status === "selected") return interaction.editReply("You already selected a monthly recognition reward.");

  const guild = client.guilds.cache.get(SWEETSIEZ_STRUCTURE_CONFIG.GUILD_ID) || client.guilds.cache.first();
  if (!guild) return interaction.editReply("I could not find the server to create your role.");
  const member = await guild.members.fetch(interaction.user.id).catch(() => null);
  if (!member) return interaction.editReply("I could not find your member profile in the server.");

  const roleName = truncateForDiscord(interaction.fields.getTextInputValue("role_name").trim(), 80);
  const rawColour = (interaction.fields.getTextInputValue("role_colour") || "#ffb6c1").trim();
  const colour = boosterIsValidHex(rawColour) ? (rawColour.startsWith("#") ? rawColour : `#${rawColour}`) : "#ffb6c1";
  const expiry = getMonthlyRecognitionRewardExpiryForMonthKey(reward.monthKey);

  const existingRoles = await MonthlyRecognitionCustomRole.find({ discordId: interaction.user.id, active: true });
  for (const existing of existingRoles) {
    const oldRole = guild.roles.cache.get(existing.roleId) || await guild.roles.fetch(existing.roleId).catch(() => null);
    if (oldRole) await oldRole.delete("Monthly recognition custom role replaced").catch(() => {});
    existing.active = false;
    existing.deletedAt = new Date();
    await existing.save().catch(() => {});
  }

  const role = await guild.roles.create({
    name: roleName,
    color: boosterResolveColour(colour),
    reason: `Monthly recognition custom role for ${interaction.user.tag}`,
    permissions: [],
  });
  await member.roles.add(role, "Monthly recognition custom role assigned").catch(() => {});
  try {
    const pos = boosterTargetPosition(member, role.id);
    await guild.roles.setPositions([{ role: role.id, position: pos }]);
  } catch {}

  await MonthlyRecognitionCustomRole.create({
    recognitionId,
    monthKey: reward.monthKey,
    discordId: interaction.user.id,
    guildId: guild.id,
    roleId: role.id,
    roleName,
    colour,
    active: true,
    expiresAt: expiry,
  });

  reward.rewardType = "custom_role";
  reward.status = "selected";
  reward.customRoleId = role.id;
  reward.customRoleName = roleName;
  reward.customRoleColour = colour;
  reward.selectedAt = new Date();
  reward.expiresAt = expiry;
  reward.updatedAt = new Date();
  await reward.save();

  await notifyMonthlyRecognitionRewardSelection(reward, `Custom Role: ${roleName} (${colour})`);
  return interaction.editReply(`Your custom role **${roleName}** has been created and will expire on <t:${Math.floor(expiry.getTime() / 1000)}:F>.`);
}

let monthlyRecognitionSchedulerStarted = false;
let monthlyRecognitionLastRunKey = null;

function startMonthlyRecognitionScheduler(clientRef) {
  if (monthlyRecognitionSchedulerStarted) return;
  monthlyRecognitionSchedulerStarted = true;

  const runCheck = async () => {
    const guild = clientRef.guilds.cache.get(SWEETSIEZ_STRUCTURE_CONFIG.GUILD_ID) || clientRef.guilds.cache.first();
    if (guild) await cleanupMonthlyRecognitionCustomRoles(guild, "Monthly recognition scheduled cleanup").catch(() => {});

    const easternNow = getEasternDateParts(new Date());
    if (easternNow.day !== 1 || easternNow.hour < 9) return;

    const windowInfo = getMonthlyRecognitionPreviousMonthWindow();
    if (monthlyRecognitionLastRunKey === windowInfo.monthKey) return;

    const existing = await MonthlyRecognition.findOne({
      monthKey: windowInfo.monthKey,
      status: { $in: ["preview", "approved"] },
    }).lean();
    if (existing) {
      monthlyRecognitionLastRunKey = windowInfo.monthKey;
      return;
    }

    await createOrRefreshMonthlyRecognitionPreview(clientRef, null);
    monthlyRecognitionLastRunKey = windowInfo.monthKey;
  };

  setInterval(() => {
    runCheck().catch(error => console.error("[MonthlyRecognition] Scheduler error:", error.message));
  }, 60 * 60 * 1000);

  setTimeout(() => {
    runCheck().catch(error => console.error("[MonthlyRecognition] Startup check error:", error.message));
  }, 30 * 1000);

  console.log("Monthly recognition scheduler started.");
}




