// BIRTHDAY SYSTEM
// ========================================

const BIRTHDAY_ROLE_ID = '1361558397467623627';

/**
 * Checks for birthdays each morning, grants/removes the birthday role,
 * and posts a celebration message in the community channel.
 */
async function runBirthdayCheck() {
  try {
    const now   = new Date();
    const month = now.getMonth() + 1;
    const day   = now.getDate();

    const guild = client.guilds.cache.first();
    if (!guild) return;

    const channel = await guild.channels.fetch(config.COMMUNITY_CHANNEL_ID).catch(() => null);

    // Remove birthday role from anyone whose birthday was yesterday
    const birthdayRole = guild.roles.cache.get(BIRTHDAY_ROLE_ID);
    if (birthdayRole) {
      for (const [, member] of birthdayRole.members) {
        await member.roles.remove(BIRTHDAY_ROLE_ID).catch(() => {});
      }
    }

    // Find today's birthdays
    const todayBirthdays = await Birthday.find({ month, day });
    if (todayBirthdays.length === 0) return;

    for (const doc of todayBirthdays) {
      const member = await guild.members.fetch(doc.discordId).catch(() => null);
      if (!member) continue;

      // Grant birthday role
      if (birthdayRole) {
        await member.roles.add(BIRTHDAY_ROLE_ID).catch(() => {});
      }

      // Post birthday message in community channel
      if (channel) {
        const age = doc.year ? ` They're turning **${now.getFullYear() - doc.year}** today!` : '';
        await channel.send({
          embeds: [
            new EmbedBuilder()
              .setColor(0xff69b4)
              .setTitle('🎂 Happy Birthday!')
              .setDescription(`Today is <@${doc.discordId}>'s birthday! 🎉${age}\n\nWishing you an amazing day from the whole Sweetsiez team! 🧁`)
              .setThumbnail(member.user.displayAvatarURL())
              .setTimestamp(),
          ],
        });
      }

      // DM the birthday person
      await member.user.send({
        embeds: [
          new EmbedBuilder()
            .setColor(0xff69b4)
            .setTitle('🎂 Happy Birthday from Sweetsiez!')
            .setDescription(`Wishing you a fantastic birthday! The whole Sweetsiez community is celebrating with you today. 🎉🧁`)
            .setTimestamp(),
        ],
      }).catch(() => {}); // DMs may be closed
    }

    console.log(`🎂 Birthday check complete — ${todayBirthdays.length} birthday(s) today`);
  } catch (err) {
    console.error('Birthday check error:', err);
  }
}

/**
 * Schedules the birthday check to run every day at 9:00 AM EST.
 */
function startBirthdayScheduler() {
  const checkInterval = 60 * 1000; // check every minute

  setInterval(() => {
    const now = new Date();
    const est = new Date(now.toLocaleString('en-US', { timeZone: 'America/New_York' }));
    if (est.getHours() === 9 && est.getMinutes() === 0) {
      runBirthdayCheck();
    }
  }, checkInterval);

  console.log('✅ Birthday scheduler started (fires daily at 9:00 AM EST)');
}




