/**
 * Load shift posts from MongoDB
 */
async function loadShiftPosts() {
  try {
    const docs = await ShiftPost.find({});
    shiftPosts.clear();
    docs.forEach(doc => {
      const claims = Array.isArray(doc.claims) ? doc.claims : [];
      const standbys = Array.isArray(doc.standbys) ? doc.standbys : [];
      shiftPosts.set(doc.date, {
        threadId: doc.threadId,
        claimCount: claims.length
          ? claims.filter(claim => claim.status !== "cancelled").length
          : doc.claimCount,
        claimedBy: doc.claimedBy || [],
        claims,
        standbys,
      });
      for (const claim of claims) {
        if (claim.messageId && claim.status !== "cancelled") {
          shiftMessages.set(claim.messageId, {
            userId: claim.claimedByDiscordId || claim.discordId,
            claimDiscordId: claim.discordId,
            date: doc.date,
            threadId: doc.threadId,
            kind: "claim",
          });
        }
      }
      for (const standby of standbys) {
        if (standby.messageId && standby.status === "waiting") {
          shiftMessages.set(standby.messageId, {
            userId: standby.discordId,
            date: doc.date,
            threadId: doc.threadId,
            kind: "standby",
          });
        }
      }
    });
    console.log(`✅ Loaded ${shiftPosts.size} shift post records from MongoDB`);
  } catch (error) {
    console.error("Error loading shift posts from MongoDB:", error);
  }
}

/**
 * Save shift posts to MongoDB
 */
async function saveShiftPosts() {
  try {
    const bulkOps = [];
    shiftPosts.forEach((data, date) => {
      bulkOps.push({
        updateOne: {
          filter: { date },
          update: {
            date,
            threadId: data.threadId,
            claimCount: data.claimCount,
            claimedBy: data.claimedBy,
            claims: data.claims || [],
            standbys: data.standbys || [],
          },
          upsert: true,
        },
      });
    });
    if (bulkOps.length > 0) await ShiftPost.bulkWrite(bulkOps);
    console.log(`💾 Saved shift posts to MongoDB`);
  } catch (error) {
    console.error("Error saving shift posts to MongoDB:", error);
  }
}

/**
 * Get current EST date as YYYY-MM-DD string
 */
function getESTDate() {
  const now = new Date();
  const estDate = new Date(now.toLocaleString("en-US", { timeZone: SHIFT_CLAIMING_CONFIG.TIMEZONE }));
  const year = estDate.getFullYear();
  const month = String(estDate.getMonth() + 1).padStart(2, '0');
  const day = String(estDate.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

/**
 * Format date as MM/DD/YY for display
 */
function formatDateForDisplay(dateStr) {
  const [year, month, day] = dateStr.split('-');
  const shortYear = year.slice(2);
  return `${month}/${day}/${shortYear}`;
}

/**
 * Create a new shift post for today
 */
/**
 * Shift claim post, as an embed. Formats sit in a monospaced block so they can be copied exactly,
 * and the claim count lives in the footer so it updates without disturbing the instructions.
 */
function buildShiftClaimEmbed(displayDate, claimCount = 0) {
  const max = SHIFT_CLAIMING_CONFIG.MAX_SHIFTS_PER_DAY;
  return new EmbedBuilder()
    .setColor(0xf5a3c7)
    .setTitle(`🧁 Shift Claims — ${displayDate}`)
    .setDescription(
      `Claim a slot by commenting below. The first **${max}** claims are accepted, and you may claim more than one slot.`,
    )
    .addFields(
      {
        name: "✅ How to Claim",
        value: [
          "```",
          "Regular       JohnDoe | 3:00 PM EST",
          "Recruitment   RECRUITMENT | JohnDoe | 3:00 PM EST",
          "Promotional   PROMOTIONAL | JohnDoe | 3:00 PM EST",
          "Standby       STANDBY | JohnDoe | 3:00 PM EST",
          "```",
        ].join("\n"),
        inline: false,
      },
      {
        name: "🎓 Supervised Certification",
        value: [
          "Uncertified Supervisor+ hosts need this claimed for them by **Human Resources Aspirants or Executives**.",
          "```",
          "SUPERVISED | HOST_USERNAME | TIME EST",
          "```",
        ].join("\n"),
        inline: false,
      },
      {
        name: "🛟 Standby",
        value: "Agree to be assigned automatically if your slot opens.",
        inline: true,
      },
      {
        name: "❌ Cancelling",
        value: "Delete your claim, or react with ❌ on it.",
        inline: true,
      },
      {
        name: "⚠️ Rules",
        value: "Off-topic comments are deleted. This post locks at 12:00 AM EST.",
        inline: false,
      },
    )
    .setFooter({ text: `${claimCount}/${max} claimed · locks 12:00 AM EST` });
}

async function createShiftPost(client) {
  try {
    const today = getESTDate();
    const displayDate = formatDateForDisplay(today);
    
    // Check if post already exists for today
    if (shiftPosts.has(today)) {
      console.log(`Shift post for ${today} already exists`);
      return;
    }

    const forumChannel = await client.channels.fetch(SHIFT_CLAIMING_CONFIG.FORUM_CHANNEL_ID);
    
    if (!forumChannel || forumChannel.type !== ChannelType.GuildForum) {
      console.error("Shift claiming channel is not a forum channel!");
      return;
    }

    // Create the forum post
    const thread = await forumChannel.threads.create({
      name: `Shifts - ${displayDate}`,
      message: { embeds: [buildShiftClaimEmbed(displayDate, 0)] },
    });

    // Store the post info
    shiftPosts.set(today, {
      threadId: thread.id,
      claimCount: 0,
      claimedBy: [],
      claims: [],
      standbys: [],
    });
    
    currentShiftThreadId = thread.id;
    await saveShiftPosts();

    console.log(`✅ Created shift post for ${displayDate} (Thread ID: ${thread.id})`);
  } catch (error) {
    console.error("Error creating shift post:", error);
  }
}

/**
 * Lock yesterday's shift post
 */
async function lockYesterdayShiftPost(client) {
  try {
    const today = new Date();
    const estDate = new Date(today.toLocaleString("en-US", { timeZone: SHIFT_CLAIMING_CONFIG.TIMEZONE }));
    estDate.setDate(estDate.getDate() - 1); // Get yesterday
    
    const year = estDate.getFullYear();
    const month = String(estDate.getMonth() + 1).padStart(2, '0');
    const day = String(estDate.getDate()).padStart(2, '0');
    const yesterday = `${year}-${month}-${day}`;

    const postInfo = shiftPosts.get(yesterday);
    if (postInfo && postInfo.threadId) {
      try {
        const forumChannel = await client.channels.fetch(SHIFT_CLAIMING_CONFIG.FORUM_CHANNEL_ID);
        const thread = await forumChannel.threads.fetch(postInfo.threadId);
        
        if (thread && !thread.locked) {
          await thread.setLocked(true);
          console.log(`🔒 Locked shift post for ${formatDateForDisplay(yesterday)}`);
        }
      } catch (error) {
        console.error(`Error locking thread for ${yesterday}:`, error);
      }
    }
  } catch (error) {
    console.error("Error in lockYesterdayShiftPost:", error);
  }
}

/**
 * Check if a message follows the shift claiming format
 */
function getShiftClaimTypeConfig(shiftType) {
  return SHIFT_CLAIM_TYPE_CONFIG[shiftType] || SHIFT_CLAIM_TYPE_CONFIG.regular;
}

function formatShiftClaimTitle(claimOrParsed) {
  const shiftType = claimOrParsed?.shiftType || "regular";
  const typeConfig = getShiftClaimTypeConfig(shiftType);
  const timeLabel = claimOrParsed?.timeLabel || "scheduled time";
  return shiftType === "regular"
    ? `${timeLabel} shift`
    : `${typeConfig.claimLabel} at ${timeLabel}`;
}

function formatShiftClaimReplyFormat(claimOrParsed) {
  const shiftType = claimOrParsed?.shiftType || "regular";
  const timeLabel = claimOrParsed?.timeLabel || "TIME EST";
  if (shiftType === "recruitment") return `RECRUITMENT | USERNAME | ${timeLabel}`;
  if (shiftType === "promotional") return `PROMOTIONAL | USERNAME | ${timeLabel}`;
  return `USERNAME | ${timeLabel}`;
}

function getShiftClaimPermissionLabel(typeConfig) {
  if (!typeConfig?.allowedLevels) return "eligible shift hosts";
  return typeConfig.allowedLevels.includes("recruitment")
    ? "Human Resources Aspirants or Executives"
    : "Human Resources Department members, Human Resources Lead, the Human Resources Director, or the President";
}

function parseShiftClaim(content, dateStr) {
  const parts = String(content || "").split("|").map(part => part.trim());
  const mode = parts[0]?.toLowerCase();
  const isStandby = mode === "standby";
  const isSupervised = SHIFT_CERTIFICATION_CONFIG.SUPERVISED_CLAIM_PREFIXES.has(mode);
  let shiftType = "regular";
  let username = null;
  let timeInput = null;

  if (isStandby || isSupervised) {
    if (parts.length !== 3) return null;
    username = parts[1];
    timeInput = parts[2];
  } else if (SHIFT_CLAIM_TYPE_PREFIXES.has(mode)) {
    if (parts.length !== 3) return null;
    shiftType = SHIFT_CLAIM_TYPE_PREFIXES.get(mode);
    username = parts[1];
    timeInput = parts[2];
  } else {
    if (parts.length !== 2) return null;
    username = parts[0];
    timeInput = parts[1];
  }

  if (!/^[a-zA-Z0-9_]{3,20}$/.test(username || "")) return null;

  const timeMatch = String(timeInput || "").match(
    /^(\d{1,2})(?::(\d{2}))?\s*(AM|PM)\s*(EST|EDT|ET)$/i,
  );
  if (!timeMatch) return null;

  let hour = Number(timeMatch[1]);
  const minute = Number(timeMatch[2] || 0);
  if (hour < 1 || hour > 12 || minute < 0 || minute > 59) return null;
  const period = timeMatch[3].toUpperCase();
  if (period === "PM" && hour !== 12) hour += 12;
  if (period === "AM" && hour === 12) hour = 0;

  const [year, month, day] = dateStr.split("-").map(Number);
  const scheduledAt = easternLocalToDate({ year, month, day }, hour, minute);
  const displayHour = Number(timeMatch[1]);
  const displayMinute = String(minute).padStart(2, "0");
  const typeConfig = getShiftClaimTypeConfig(shiftType);

  return {
    isStandby,
    isSupervised,
    shiftType,
    shiftTypeLabel: typeConfig.label,
    robloxUsername: username,
    timeLabel: `${displayHour}:${displayMinute} ${period} ET`,
    scheduledAt: scheduledAt.toISOString(),
  };
}

function isValidShiftClaimFormat(content) {
  return Boolean(parseShiftClaim(content, getESTDate()));
}

function formatGameShiftClaimContent(parsed, robloxUsername) {
  const username = robloxUsername || parsed?.robloxUsername || "USERNAME";
  const timeLabel = parsed?.timeLabel || "TIME EST";
  if (parsed?.shiftType === "recruitment") return `RECRUITMENT | ${username} | ${timeLabel}`;
  if (parsed?.shiftType === "promotional") return `PROMOTIONAL | ${username} | ${timeLabel}`;
  return `${username} | ${timeLabel}`;
}

function getShiftBeginClaimWindow(claim) {
  const scheduledTime = new Date(claim?.scheduledAt || 0).getTime();
  if (!Number.isFinite(scheduledTime) || scheduledTime <= 0) return null;
  return {
    scheduledTime,
    opensAt: scheduledTime - SHIFT_CLAIMING_CONFIG.BEGIN_EARLY_WINDOW_MINUTES * 60 * 1000,
    closesAt: scheduledTime + SHIFT_CLAIMING_CONFIG.BEGIN_LATE_WINDOW_MINUTES * 60 * 1000,
  };
}

function getBeginEligibleClaimUsername(claim) {
  if (!claim || claim.status === "cancelled") return null;
  if (claim.status === "replacement_assigned" && claim.replacementRobloxUsername) {
    return String(claim.replacementRobloxUsername).toLowerCase();
  }
  if (["scheduled", "no_show"].includes(claim.status) && claim.robloxUsername) {
    return String(claim.robloxUsername).toLowerCase();
  }
  return null;
}

function findGameBeginShiftClaim(hostUsername, now = new Date()) {
  const usernameLower = String(hostUsername || "").toLowerCase();
  const today = getESTDate();
  const postInfo = shiftPosts.get(today);
  if (!postInfo) {
    return { ok: false, reason: "There is no shift claim post loaded for today." };
  }

  const nowMs = now.getTime();
  const matchingClaims = (postInfo.claims || [])
    .map(claim => {
      const eligibleUsername = getBeginEligibleClaimUsername(claim);
      const windowInfo = getShiftBeginClaimWindow(claim);
      if (!eligibleUsername || !windowInfo || eligibleUsername !== usernameLower) return null;
      return { claim, windowInfo };
    })
    .filter(Boolean)
    .sort((a, b) => Math.abs(a.windowInfo.scheduledTime - nowMs) - Math.abs(b.windowInfo.scheduledTime - nowMs));

  const activeMatch = matchingClaims.find(({ windowInfo }) =>
    nowMs >= windowInfo.opensAt && nowMs <= windowInfo.closesAt,
  );
  if (activeMatch) return { ok: true, claim: activeMatch.claim, windowInfo: activeMatch.windowInfo, date: today };

  const nextClaim = matchingClaims.find(({ windowInfo }) => nowMs < windowInfo.opensAt);
  if (nextClaim) {
    return {
      ok: false,
      reason:
        `Your next claimed shift is ${nextClaim.claim.timeLabel}. ` +
        `/begin opens ${SHIFT_CLAIMING_CONFIG.BEGIN_EARLY_WINDOW_MINUTES} minutes before the claimed time.`,
      claim: nextClaim.claim,
    };
  }

  const previousClaim = matchingClaims.find(({ windowInfo }) => nowMs > windowInfo.closesAt);
  if (previousClaim) {
    return {
      ok: false,
      reason:
        `Your latest claimed shift window for ${previousClaim.claim.timeLabel} has expired. ` +
        "Please claim a new shift before using /begin.",
      claim: previousClaim.claim,
    };
  }

  return {
    ok: false,
    reason: "No active shift claim was found for your Roblox username today.",
  };
}

async function verifyGameShiftBeginClaim(body = {}) {
  const hostUsername = String(body.host_username || body.hostUsername || "").trim();
  if (!hostUsername) {
    return {
      statusCode: 400,
      payload: { success: false, allowed: false, error: "Missing host_username." },
    };
  }

  const hostDiscordId = findVerifiedDiscordIdByRobloxUsername(hostUsername);
  if (!hostDiscordId) {
    return {
      statusCode: 403,
      payload: {
        success: false,
        allowed: false,
        error: "That Roblox username is not linked to a verified Discord account.",
      },
    };
  }

  const linkedUsername = verifiedUsers.get(hostDiscordId);
  if (!linkedUsername || linkedUsername.toLowerCase() !== hostUsername.toLowerCase()) {
    return {
      statusCode: 403,
      payload: {
        success: false,
        allowed: false,
        error: "Verified Roblox username does not match the in-game host.",
      },
    };
  }

  const match = findGameBeginShiftClaim(linkedUsername);
  if (!match.ok) {
    return {
      statusCode: 403,
      payload: {
        success: false,
        allowed: false,
        error: match.reason,
        shift_type: match.claim?.shiftType || null,
        time_label: match.claim?.timeLabel || null,
      },
    };
  }

  return {
    statusCode: 200,
    payload: {
      success: true,
      allowed: true,
      data: {
        shift_type: match.claim.shiftType || "regular",
        shift_type_label: match.claim.shiftTypeLabel || getShiftClaimTypeConfig(match.claim.shiftType).label,
        time_label: match.claim.timeLabel || null,
        scheduled_at: match.claim.scheduledAt || null,
        claim_message_id: match.claim.messageId || null,
        date: match.date,
      },
    },
  };
}

async function createShiftClaimFromGame(body = {}) {
  const today = getESTDate();
  const rawShiftType = String(body.shift_type || body.shiftType || "regular").toLowerCase().trim();
  const shiftType = SHIFT_CLAIM_TYPE_CONFIG[rawShiftType] ? rawShiftType : SHIFT_CLAIM_TYPE_PREFIXES.get(rawShiftType) || "regular";
  const hostUsername = String(body.host_username || body.hostUsername || "").trim();
  const hostUserIdRaw = body.host_user_id ?? body.hostUserId;
  const hostUserId = hostUserIdRaw !== undefined && hostUserIdRaw !== null ? String(hostUserIdRaw).trim() : null;
  const hostRank = Number(body.host_rank ?? body.hostRank);
  const timeLabelInput = String(body.time_label || body.timeLabel || body.time || "").trim();
  const claimText = String(
    body.claim_text ||
    body.claimText ||
    formatGameShiftClaimContent({ shiftType, timeLabel: timeLabelInput }, hostUsername),
  ).trim();

  if (!hostUsername) {
    return { statusCode: 400, payload: { success: false, error: "Missing host_username." } };
  }

  const parsed = parseShiftClaim(claimText, today);
  if (!parsed || parsed.isStandby || parsed.isSupervised) {
    return {
      statusCode: 400,
      payload: {
        success: false,
        error: "Invalid shift claim. Use regular, recruitment, or promotional with a time like 3:00 PM EST.",
      },
    };
  }

  if (parsed.shiftType !== shiftType) {
    return { statusCode: 400, payload: { success: false, error: "Shift type did not match the claim text." } };
  }
  if (parsed.robloxUsername.toLowerCase() !== hostUsername.toLowerCase()) {
    return { statusCode: 400, payload: { success: false, error: "Claim username must match the in-game host." } };
  }

  const guild = client.guilds.cache.get(SWEETSIEZ_STRUCTURE_CONFIG.GUILD_ID) ||
    client.guilds.cache.get(config.IA_GUILD_ID) ||
    client.guilds.cache.first();
  if (!guild) {
    return { statusCode: 503, payload: { success: false, error: "Discord guild is not available." } };
  }

  const hostDiscordId = findVerifiedDiscordIdByRobloxUsername(hostUsername);
  if (!hostDiscordId) {
    return { statusCode: 404, payload: { success: false, error: "That Roblox username is not linked to a verified Discord account." } };
  }

  const linkedUsername = verifiedUsers.get(hostDiscordId);
  if (!linkedUsername || linkedUsername.toLowerCase() !== hostUsername.toLowerCase()) {
    return { statusCode: 400, payload: { success: false, error: "Verified Roblox username does not match the in-game host." } };
  }

  const hostRankInfo = await getVerifiedMainRankForDiscord(hostDiscordId).catch(() => null);
  if (
    isShiftCertificationRank(hostRankInfo?.rank) &&
    !(await isShiftHostCertified(hostDiscordId))
  ) {
    return {
      statusCode: 403,
      payload: {
        success: false,
        error: "Uncertified Supervisor+ hosts cannot claim shifts for themselves. Have an eligible supervisor claim it as a supervised certification shift in Discord.",
      },
    };
  }

  const member = await guild.members.fetch(hostDiscordId).catch(() => null);
  if (parsed.shiftType !== "regular") {
    const typeConfig = getShiftClaimTypeConfig(parsed.shiftType);
    const authority = await getShiftCertificationAuthorityContext(guild, hostDiscordId, member).catch(error => {
      console.error("Game shift claim permission lookup failed:", error.message);
      return { ok: false, reason: "I could not verify your special shift permissions." };
    });
    if (!authority.ok || !typeConfig.allowedLevels?.includes(authority.level)) {
      return {
        statusCode: 403,
        payload: {
          success: false,
          error: `${typeConfig.label} claims can only be made by ${getShiftClaimPermissionLabel(typeConfig)}.`,
        },
      };
    }
  }

  if (new Date(parsed.scheduledAt).getTime() < Date.now() - 10 * 60 * 1000) {
    return { statusCode: 400, payload: { success: false, error: "That shift time has already passed." } };
  }

  let postInfo = shiftPosts.get(today);
  if (!postInfo) {
    await createShiftPost(client);
    postInfo = shiftPosts.get(today);
  }
  if (!postInfo?.threadId) {
    return { statusCode: 503, payload: { success: false, error: "Today's shift claiming post is not available." } };
  }

  const forumChannel = await client.channels.fetch(SHIFT_CLAIMING_CONFIG.FORUM_CHANNEL_ID).catch(() => null);
  const thread = forumChannel?.threads
    ? await forumChannel.threads.fetch(postInfo.threadId).catch(() => null)
    : null;
  if (!thread) {
    return { statusCode: 503, payload: { success: false, error: "Today's shift claiming thread could not be opened." } };
  }

  postInfo.claims = postInfo.claims || [];
  postInfo.standbys = postInfo.standbys || [];
  postInfo.claimedBy = postInfo.claimedBy || [];

  const duplicate = postInfo.claims.some(entry =>
    entry.discordId === hostDiscordId &&
    entry.scheduledAt === parsed.scheduledAt &&
    entry.status !== "cancelled",
  );
  if (duplicate) {
    return { statusCode: 409, payload: { success: false, error: `You already have a ${formatShiftClaimTitle(parsed)} recorded.` } };
  }

  if (postInfo.claimCount >= SHIFT_CLAIMING_CONFIG.MAX_SHIFTS_PER_DAY) {
    return {
      statusCode: 409,
      payload: {
        success: false,
        error: `All ${SHIFT_CLAIMING_CONFIG.MAX_SHIFTS_PER_DAY} shift slots are already claimed.`,
      },
    };
  }

  const claimContent = formatGameShiftClaimContent(parsed, linkedUsername);
  const claimMessage = await thread.send({
    content: `${claimContent}\n-# Claimed in-game by ${hostUsername}.`,
    allowedMentions: { parse: [] },
  });

  const hostUser = await client.users.fetch(hostDiscordId).catch(() => null);
  const entry = {
    discordId: hostDiscordId,
    discordTag: hostUser?.tag || "Verified Host",
    robloxUsername: linkedUsername,
    timeLabel: parsed.timeLabel,
    shiftType: parsed.shiftType || "regular",
    shiftTypeLabel: parsed.shiftTypeLabel || getShiftClaimTypeConfig(parsed.shiftType).label,
    operationsPointType: getShiftClaimTypeConfig(parsed.shiftType).operationsPointType || null,
    operationsPointCredited: false,
    scheduledAt: parsed.scheduledAt,
    messageId: claimMessage.id,
    status: "scheduled",
    remindersSent: [],
    createdAt: new Date().toISOString(),
    createdVia: "game_admin",
    gameHostUserId: hostUserId,
    gameHostRank: Number.isFinite(hostRank) ? hostRank : null,
    gamePlaceId: body.place_id !== undefined && body.place_id !== null ? String(body.place_id) : null,
    gameJobId: body.job_id !== undefined && body.job_id !== null ? String(body.job_id) : null,
  };

  postInfo.claims.push(entry);
  postInfo.claimCount = postInfo.claims.filter(claim => claim.status !== "cancelled").length;
  if (!postInfo.claimedBy.includes(hostDiscordId)) postInfo.claimedBy.push(hostDiscordId);
  shiftPosts.set(today, postInfo);
  shiftMessages.set(claimMessage.id, {
    userId: hostDiscordId,
    claimDiscordId: hostDiscordId,
    date: today,
    threadId: thread.id,
    kind: "claim",
  });

  await saveShiftPosts();
  await updateShiftReliability(hostDiscordId, linkedUsername, "scheduled");
  await claimMessage.react("\u274C").catch(() => {});
  await claimMessage.react("\u2705").catch(() => {});
  await updateShiftPostCount(thread, postInfo.claimCount);
  await hostUser?.send(
    `Your ${formatShiftClaimTitle(parsed)} is claimed from in-game. I will remind you about one hour and 15 minutes before it begins.`,
  ).catch(() => {});

  return {
    statusCode: 200,
    payload: {
      success: true,
      data: {
        event_type: "claim",
        shift_type: parsed.shiftType,
        time_label: parsed.timeLabel,
        scheduled_at: parsed.scheduledAt,
        claim_count: postInfo.claimCount,
        message_id: claimMessage.id,
        message_url: `https://discord.com/channels/${guild.id}/${thread.id}/${claimMessage.id}`,
      },
    },
  };
}

async function updateShiftReliability(discordId, robloxUsername, field, amount = 1) {
  if (!discordId || !field) return;
  await ShiftReliability.findOneAndUpdate(
    { discordId },
    {
      $inc: { [field]: amount },
      $set: { robloxUsername: robloxUsername || null, updatedAt: new Date() },
    },
    { upsert: true },
  ).catch(error => console.error("[ShiftCoverage] Reliability update failed:", error.message));
}

function isShiftCertificationRank(rank) {
  const numericRank = Number(rank || 0);
  return numericRank >= SHIFT_CERTIFICATION_CONFIG.MIN_HOST_RANK && isStaffProfileRank(numericRank);
}

async function getShiftCertificationAuthorityContext(guild, discordId, member = null) {
  const rankInfo = await getVerifiedMainRankForDiscord(discordId).catch(() => null);
  const rank = Number(rankInfo?.rank || 0);
  if (!rankInfo || rank < SHIFT_CERTIFICATION_CONFIG.MIN_GRADER_RANK) {
    return {
      ok: false,
      reason: "You must be verified and hold an eligible Manager+ rank to manage shift certification.",
    };
  }

  let guildMember = member;
  if (!guildMember?.roles?.cache && guild?.members?.fetch) {
    guildMember = await guild.members.fetch(discordId).catch(() => null);
  }
  const hasRole = roleId => Boolean(roleId && guildMember?.roles?.cache?.has(roleId));
  const placement = await StaffPlacement.findOne({ discordId }).lean().catch(() => null);

  const isPresident =
    rank >= SWEETSIEZ_STRUCTURE_CONFIG.PRESIDENT_RANK ||
    hasRole(SWEETSIEZ_STRUCTURE_CONFIG.ROLES.President);
  if (isPresident) return { ok: true, level: "president", rankInfo };

  const isOperationsOverseer =
    rank === SWEETSIEZ_STRUCTURE_CONFIG.VICE_PRESIDENT_RANK &&
    placement?.placementType === "board" &&
    placement?.placementKey === "operations";
  if (isOperationsOverseer) return { ok: true, level: "operations_overseer", rankInfo };

  const isOperationsHead =
    (
      rank === SWEETSIEZ_STRUCTURE_CONFIG.EXECUTIVE_DIRECTOR_RANK &&
      placement?.placementType === "board" &&
      placement?.placementKey === "operations"
    ) ||
    hasRole(SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Head of Operations"]);
  if (isOperationsHead) return { ok: true, level: "operations_head", rankInfo };

  const isOperationsBoard =
    rank >= SWEETSIEZ_STRUCTURE_CONFIG.EXECUTIVE_BOARD_RANK &&
    (
      hasRole(SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Operations Board"]) ||
      (placement?.placementType === "board" && placement?.placementKey === "operations")
    );
  if (isOperationsBoard) return { ok: true, level: "operations", rankInfo };

  const isRecruitmentManager =
    rank === SWEETSIEZ_STRUCTURE_CONFIG.MANAGER_RANK &&
    (
      hasRole(SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Growth Team"]) ||
      (placement?.placementType === "team" && placement?.placementKey === "recruitment")
    );
  if (isRecruitmentManager) return { ok: true, level: "recruitment", rankInfo };

  return {
    ok: false,
    rankInfo,
    reason: "Only Human Resources Aspirant Managers, Human Resources Department members, Human Resources Lead, the Human Resources Director, or the President may manage shift certification.",
  };
}

async function resolveShiftCertificationTargetByUsername(robloxUsername) {
  const discordId = findVerifiedDiscordIdByRobloxUsername(robloxUsername);
  if (!discordId) {
    return { ok: false, reason: "That Roblox username is not linked to a verified Discord account." };
  }
  const verifiedUsername = verifiedUsers.get(discordId) || robloxUsername;
  const robloxUserId = await getRobloxUserId(verifiedUsername).catch(() => null);
  const rankInfo = robloxUserId ? await getUserRankInGroup(robloxUserId).catch(() => null) : null;
  if (!robloxUserId || !rankInfo) {
    return { ok: false, reason: "I could not resolve that staff member's current Roblox rank." };
  }
  if (!isShiftCertificationRank(rankInfo.rank)) {
    return { ok: false, reason: "Shift certification can only be used for Supervisor+ staff with staff profiles." };
  }
  return {
    ok: true,
    discordId,
    robloxUsername: verifiedUsername,
    robloxUserId,
    rankInfo,
  };
}

async function resolveShiftCertificationTargetByDiscordUser(user) {
  const robloxUsername = verifiedUsers.get(user.id);
  if (!robloxUsername) return { ok: false, reason: "The selected user is not verified." };
  const target = await resolveShiftCertificationTargetByUsername(robloxUsername);
  return target.ok ? { ...target, user } : target;
}

async function resolveManualShiftCertificationTargetByDiscordUser(user) {
  const robloxUsername = verifiedUsers.get(user.id);
  if (!robloxUsername) return { ok: false, reason: "The selected user is not verified." };
  const robloxUserId = await getRobloxUserId(robloxUsername).catch(() => null);
  const rankInfo = robloxUserId ? await getUserRankInGroup(robloxUserId).catch(() => null) : null;
  if (!robloxUserId || !rankInfo) {
    return { ok: false, reason: "I could not resolve that staff member's current Roblox rank." };
  }
  if (Number(rankInfo.rank || 0) < SHIFT_CERTIFICATION_CONFIG.MIN_HOST_RANK) {
    return { ok: false, reason: "Shift certification can only be used for Supervisor+ staff." };
  }
  return {
    ok: true,
    discordId: user.id,
    robloxUsername,
    robloxUserId,
    rankInfo,
    user,
  };
}

async function isShiftHostCertified(discordId) {
  const record = await ShiftCertification.findOne({ discordId }).lean().catch(() => null);
  return record?.certified === true || record?.status === "certified";
}

function splitCertificationPoints(value, maxItems = 3) {
  const points = String(value || "")
    .split(/\r?\n|[;•]/)
    .map(part => part.replace(/^[-*]\s*/, "").trim())
    .filter(Boolean)
    .slice(0, maxItems);
  return points.length ? points : ["Not provided"];
}

function formatCertificationBullets(points, maxLength = 180) {
  return points.map(point => `• ${truncateForDiscord(point, maxLength)}`).join("\n");
}

function findLatestShiftCertificationClaim(discordId) {
  const candidates = [];
  for (const [date, postInfo] of shiftPosts.entries()) {
    for (const claim of postInfo.claims || []) {
      if (claim.discordId !== discordId || claim.status === "cancelled") continue;
      candidates.push({ date, postInfo, claim });
    }
  }
  candidates.sort((a, b) =>
    new Date(b.claim.scheduledAt || 0).getTime() - new Date(a.claim.scheduledAt || 0).getTime(),
  );
  return candidates.find(item => item.claim.supervised || item.claim.certificationRequired) || candidates[0] || null;
}

function findLatestSupervisedShiftCertificationClaim(discordId) {
  const candidates = [];
  for (const [date, postInfo] of shiftPosts.entries()) {
    for (const claim of postInfo.claims || []) {
      if (claim.discordId !== discordId || claim.status === "cancelled") continue;
      if (!claim.supervised && !claim.certificationRequired) continue;
      candidates.push({ date, postInfo, claim });
    }
  }
  candidates.sort((a, b) =>
    new Date(b.claim.scheduledAt || 0).getTime() - new Date(a.claim.scheduledAt || 0).getTime(),
  );
  return candidates[0] || null;
}

function getShiftCertificationClaimTimestamp(latestClaim) {
  const raw = latestClaim?.claim?.scheduledAt || latestClaim?.claim?.createdAt || latestClaim?.date;
  const date = raw ? new Date(raw) : null;
  return date && Number.isFinite(date.getTime()) ? date : null;
}

function getShiftCertificationDashboardBucket(staffEntry, record, latestSupervisedClaim) {
  if (record?.certified === true || record?.status === "certified") return "certified";

  const claimStatus = latestSupervisedClaim?.claim?.certificationStatus || null;
  const claimDate = getShiftCertificationClaimTimestamp(latestSupervisedClaim);
  const gradedAt = record?.gradedAt ? new Date(record.gradedAt) : null;
  const hasNewerPendingClaim =
    latestSupervisedClaim?.claim &&
    (!claimStatus || claimStatus === "pending") &&
    (!gradedAt || !claimDate || claimDate.getTime() >= gradedAt.getTime());

  if (record?.status === "pending" || hasNewerPendingClaim) return "pending_feedback";
  if (record?.status === "not_certified" || (record?.certified === false && record?.gradedAt)) return "needs_resupervision";
  return "needs_supervision";
}

function formatShiftCertificationDashboardLine(entry) {
  const rankText = entry.rankName ? ` (${entry.rankName})` : "";
  const lastShift = entry.record?.lastShiftDate
    ? ` - last: ${entry.record.lastShiftDate}${entry.record.lastShiftTimeLabel ? ` ${entry.record.lastShiftTimeLabel}` : ""}`
    : entry.latestSupervisedClaim?.claim?.timeLabel
      ? ` - supervised: ${formatDateForDisplay(entry.latestSupervisedClaim.date)} ${entry.latestSupervisedClaim.claim.timeLabel}`
      : "";
  return `• <@${entry.discordId}> - **${entry.robloxUsername || "Unknown"}**${rankText}${lastShift}`;
}

function formatShiftCertificationDashboardList(entries, emptyText, limit = 12) {
  if (!entries.length) return emptyText;
  const sorted = [...entries].sort((a, b) =>
    String(a.robloxUsername || "").localeCompare(String(b.robloxUsername || "")),
  );
  const visible = sorted.slice(0, limit).map(formatShiftCertificationDashboardLine);
  const hidden = sorted.length - visible.length;
  return truncateForDiscord(
    hidden > 0
      ? `${visible.join("\n")}\n…and **${hidden}** more.`
      : visible.join("\n"),
    1024,
  );
}

async function resolveCurrentShiftCertificationStaffEntry(guild, discordId, fallback = {}) {
  const id = String(discordId || "");
  if (!id) return null;

  const linkedUsername = verifiedUsers.get(id);
  if (!linkedUsername) return null;

  let member = guild?.members?.cache?.get(id) || null;
  if (!member && guild?.members?.fetch) {
    member = await guild.members.fetch(id).catch(() => null);
  }
  if (!member || member.user?.bot) return null;

  const rankInfo = await getVerifiedMainRankForDiscord(id).catch(error => {
    console.warn(`[CertStatus] Could not verify current Roblox rank for ${id}:`, error.message);
    return null;
  });

  if (rankInfo) {
    if (!isShiftCertificationRank(rankInfo.rank)) return null;
    return {
      discordId: id,
      robloxUsername: rankInfo.robloxUsername || linkedUsername,
      robloxUserId: rankInfo.robloxUserId || fallback.robloxUserId || null,
      rank: Number(rankInfo.rank || 0),
      rankName: rankInfo.rankName || getRankDisplayNameFromBind(rankInfo.rank),
      source: fallback.source ? `${fallback.source}, current_roblox_rank` : "current_roblox_rank",
    };
  }

  const roleRank = inferStaffRankFromDiscordRoles(member);
  if (!roleRank || !isShiftCertificationRank(roleRank.rank)) return null;
  return {
    discordId: id,
    robloxUsername: linkedUsername,
    robloxUserId: fallback.robloxUserId || null,
    rank: Number(roleRank.rank || 0),
    rankName: roleRank.rankName || getRankDisplayNameFromBind(roleRank.rank),
    source: fallback.source ? `${fallback.source}, discord_roles_fallback` : "discord_roles_fallback",
  };
}

async function getShiftCertificationDashboardEntries(guild) {
  const candidateByDiscord = new Map();
  const staffByDiscord = new Map();
  const mergeEntry = (targetMap, entry) => {
    if (!entry?.discordId) return;
    const existing = targetMap.get(entry.discordId) || {};
    targetMap.set(entry.discordId, {
      ...existing,
      ...entry,
      rank: Math.max(Number(existing.rank || 0), Number(entry.rank || 0)),
      rankName: Number(entry.rank || 0) >= Number(existing.rank || 0)
        ? entry.rankName || existing.rankName
        : existing.rankName || entry.rankName,
      robloxUsername: entry.robloxUsername || existing.robloxUsername,
      robloxUserId: entry.robloxUserId || existing.robloxUserId,
      source: existing.source && existing.source !== entry.source
        ? `${existing.source}, ${entry.source}`
        : entry.source || existing.source,
    });
  };
  const addCandidate = entry => mergeEntry(candidateByDiscord, entry);
  const addCurrentStaff = entry => mergeEntry(staffByDiscord, entry);

  const profiles = await StaffProfile.find({
    status: "employed",
    rankEmployedAs: { $gte: SHIFT_CERTIFICATION_CONFIG.MIN_HOST_RANK },
  }).lean().catch(error => {
    console.error("[CertStatus] Failed to load staff profiles:", error.message);
    return [];
  });

  for (const profile of profiles) {
    if (!isShiftCertificationRank(profile.rankEmployedAs)) continue;
    addCandidate({
      discordId: String(profile.discordId),
      robloxUsername: profile.robloxUsername,
      robloxUserId: profile.robloxUserId,
      rank: Number(profile.rankEmployedAs || 0),
      rankName: profile.rankNameEmployedAs || getRankDisplayNameFromBind(profile.rankEmployedAs),
      source: "staff_profile",
    });
  }

  if (guild?.members?.fetch) {
    await guild.members.fetch().catch(error =>
      console.warn("[CertStatus] Could not refresh guild members:", error.message),
    );
    for (const member of guild.members.cache.values()) {
      if (member.user?.bot) continue;
      const roleRank = inferStaffRankFromDiscordRoles(member);
      if (!roleRank || !isShiftCertificationRank(roleRank.rank)) continue;
      const robloxUsername = verifiedUsers.get(member.id);
      if (!robloxUsername) continue;
      addCandidate({
        discordId: member.id,
        robloxUsername,
        rank: roleRank.rank,
        rankName: roleRank.rankName,
        source: "discord_roles",
      });
    }
  }

  const resolvedCurrentEntries = await Promise.all(
    [...candidateByDiscord.values()].map(candidate =>
      resolveCurrentShiftCertificationStaffEntry(guild, candidate.discordId, candidate),
    ),
  );
  for (const currentEntry of resolvedCurrentEntries) {
    if (currentEntry) addCurrentStaff(currentEntry);
  }

  const discordIds = [...staffByDiscord.keys()];
  const records = discordIds.length
    ? await ShiftCertification.find({ discordId: { $in: discordIds } }).lean().catch(error => {
        console.error("[CertStatus] Failed to load certification records:", error.message);
        return [];
      })
    : [];
  const recordsByDiscord = new Map(records.map(record => [String(record.discordId), record]));

  return [...staffByDiscord.values()]
    .filter(entry => isShiftCertificationRank(entry.rank))
    .map(entry => {
      const record = recordsByDiscord.get(entry.discordId) || null;
      const latestSupervisedClaim = findLatestSupervisedShiftCertificationClaim(entry.discordId);
      return {
        ...entry,
        record,
        latestSupervisedClaim,
        bucket: getShiftCertificationDashboardBucket(entry, record, latestSupervisedClaim),
      };
    });
}

function buildShiftCertificationDashboardEmbed(entries, view = "all") {
  const groups = {
    certified: entries.filter(entry => entry.bucket === "certified"),
    needs_supervision: entries.filter(entry => entry.bucket === "needs_supervision"),
    pending_feedback: entries.filter(entry => entry.bucket === "pending_feedback"),
    needs_resupervision: entries.filter(entry => entry.bucket === "needs_resupervision"),
  };
  const selectedView = view || "all";
  const showAll = selectedView === "all";

  const embed = new EmbedBuilder()
    .setColor(0x2f80ed)
    .setTitle("Shift Certification Dashboard")
    .setDescription([
      `Supervisor+ certification overview for current verified staff.`,
      `Total Tracked: **${entries.length}**`,
      `Certified: **${groups.certified.length}** | Needs Supervision: **${groups.needs_supervision.length}** | Pending Feedback: **${groups.pending_feedback.length}** | Needs Re-Supervision: **${groups.needs_resupervision.length}**`,
    ].join("\n"))
    .setFooter({ text: "Uses current Roblox ranks, verified server membership, certification records, and supervised shift claims." })
    .setTimestamp();

  const addGroup = (key, name, emptyText) => {
    if (!showAll && selectedView !== key) return;
    embed.addFields({
      name: `${name} (${groups[key].length})`,
      value: formatShiftCertificationDashboardList(groups[key], emptyText),
      inline: false,
    });
  };

  addGroup("certified", "Certified", "No certified Supervisor+ staff found.");
  addGroup("needs_supervision", "Needs Supervision", "No staff currently need their first supervised certification shift.");
  addGroup("pending_feedback", "Pending Feedback", "No supervised certification shifts are waiting for grading.");
  addGroup("needs_resupervision", "Not Certified / Needs Re-Supervised Shift", "No failed certification records need re-supervision.");

  return embed;
}

async function handleCertificationStatusCommand(interaction) {
  const authority = await getShiftCertificationAuthorityContext(interaction.guild, interaction.user.id, interaction.member);
  if (!authority.ok) return interaction.editReply(authority.reason);

  const view = interaction.options.getString("view") || "all";
  const entries = await getShiftCertificationDashboardEntries(interaction.guild);
  return interaction.editReply({
    embeds: [buildShiftCertificationDashboardEmbed(entries, view)],
    allowedMentions: { parse: [] },
  });
}

async function markShiftCertificationClaimOutcome(latestClaim, certified, actor, feedbackMessageId) {
  if (!latestClaim?.claim) return;
  latestClaim.claim.certificationStatus = certified ? "certified" : "not_certified";
  latestClaim.claim.certificationLoggedAt = new Date().toISOString();
  latestClaim.claim.certificationLoggedByDiscordId = actor.id;
  latestClaim.claim.certificationLoggedByTag = actor.tag;
  latestClaim.claim.certificationFeedbackMessageId = feedbackMessageId || null;
  shiftPosts.set(latestClaim.date, latestClaim.postInfo);
  await saveShiftPosts();
}

function buildShiftCertificationFeedbackMessage({
  targetUsername,
  targetRankName,
  gradedByUsername,
  overall,
  strengths,
  improvements,
  recommendations,
  certified,
  latestClaim,
}) {
  const statusLine = certified ? "• **Certified:** Yes" : "• **Certified:** No";
  const shiftLine = latestClaim?.claim
    ? `\n**🕒 SHIFT REVIEWED**\n• **Date/Time:** ${formatDateForDisplay(latestClaim.date)} at ${latestClaim.claim.timeLabel}\n`
    : "";
  const improvementReminder = certified
    ? ""
    : "\n\nBefore future independent shifts, please improve the areas listed above. If you choose to host again, you will need to be supervised again and receive a passing certification before hosting independently.";

  return [
    "📝 **FIRST SHIFT HOST FEEDBACK**",
    "",
    `Greetings, ${targetUsername}. Thank you for hosting your first shift today. As part of your certification process, the Human Resources Department has reviewed your performance and compiled feedback to support your growth as a **${targetRankName || "Supervisor"}**.`,
    shiftLine,
    "**📌 OVERALL PERFORMANCE**",
    truncateForDiscord(overall, 450),
    "",
    "**✅ STRENGTHS**",
    formatCertificationBullets(strengths, 170),
    "",
    "**⚠️ AREAS FOR IMPROVEMENT**",
    formatCertificationBullets(improvements, 170),
    "",
    "**📚 RECOMMENDATIONS**",
    `• ${truncateForDiscord(recommendations, 450)}`,
    "",
    "**📊 CERTIFICATION STATUS**",
    `${statusLine}${improvementReminder}`,
    "",
    "We appreciate your efforts and commitment to the Sweetsiez community. If you have any questions regarding this feedback or need further guidance, feel free to reach out to the Human Resources Department at any time.",
    "",
    "Much Regards,",
    `*${gradedByUsername}*`,
  ].join("\n").slice(0, 2000);
}

function buildManualShiftCertificationMessage({
  targetUsername,
  targetRankName,
  markedByUsername,
  reason,
  evidence,
}) {
  return [
    "**SHIFT CERTIFICATION MANUAL UPDATE**",
    "",
    `Greetings, ${targetUsername}. Your shift certification status has been manually marked as **Certified** for your role as **${targetRankName || "Supervisor"}**.`,
    "",
    "**CERTIFICATION STATUS**",
    "- **Certified:** Yes",
    "",
    "**REASON**",
    `- ${truncateForDiscord(reason, 700)}`,
    evidence ? "" : null,
    evidence ? "**EVIDENCE / REFERENCE**" : null,
    evidence ? `- ${truncateForDiscord(evidence, 500)}` : null,
    "",
    "This manual certification was recorded by an Director+ authority and does not require a supervised shift record.",
    "",
    "Much Regards,",
    `*${markedByUsername}*`,
  ].filter(line => line !== null).join("\n").slice(0, 2000);
}

async function handleShiftCertificationCommand(interaction) {
  const subcommand = interaction.options.getSubcommand();
  if (subcommand === "mark") {
    const issuerRank = await getVerifiedMainRankForDiscord(interaction.user.id).catch(() => null);
    const issuerRankNumber = Number(issuerRank?.rank || 0);
    if (!issuerRank || !isExecutiveDirectorOrLeadershipRank(issuerRankNumber)) {
      return interaction.editReply("You must be verified and Director+ to manually mark shift certification.");
    }

    const targetUser = interaction.options.getUser("user", true);
    if (targetUser.bot) return interaction.editReply("Bots cannot be shift certified.");
    if (
      targetUser.id === interaction.user.id &&
      issuerRankNumber < SHIFT_CERTIFICATION_CONFIG.SELF_MANUAL_MARK_MIN_RANK
    ) {
      return interaction.editReply("You must be Director+ to manually mark yourself as shift certified.");
    }

    const target = await resolveManualShiftCertificationTargetByDiscordUser(targetUser);
    if (!target.ok) return interaction.editReply(`Shift certification issue: ${target.reason}`);

    const reason = interaction.options.getString("reason", true);
    const evidence = interaction.options.getString("evidence") || null;
    let sentMessage = null;
    let thread = null;

    if (isStaffProfileRank(target.rankInfo.rank)) {
      const profileData = await getOrCreateStaffProfileThread({
        discordId: targetUser.id,
        robloxUsername: target.robloxUsername,
        robloxUserId: target.robloxUserId,
        rank: target.rankInfo.rank,
        rankName: target.rankInfo.name,
      }).catch(() => null);
      thread = profileData?.thread || null;
      if (thread) {
        if (thread.archived) await thread.setArchived(false).catch(() => {});
        if (thread.locked) await thread.setLocked(false).catch(() => {});
        sentMessage = await thread.send({
          content: buildManualShiftCertificationMessage({
            targetUsername: target.robloxUsername,
            targetRankName: target.rankInfo.name,
            markedByUsername: issuerRank?.robloxUsername || interaction.user.username,
            reason,
            evidence,
          }),
          allowedMentions: { users: [targetUser.id] },
        }).catch(() => null);
      }
    }

    await ShiftCertification.findOneAndUpdate(
      { discordId: targetUser.id },
      {
        $set: {
          discordId: targetUser.id,
          robloxUsername: target.robloxUsername,
          robloxUsernameLower: target.robloxUsername.toLowerCase(),
          robloxUserId: String(target.robloxUserId),
          rankAtCertification: Number(target.rankInfo.rank),
          rankNameAtCertification: target.rankInfo.name || `Rank ${target.rankInfo.rank}`,
          status: "certified",
          certified: true,
          lastShiftDate: null,
          lastShiftTimeLabel: null,
          lastShiftClaimMessageId: null,
          lastAttendanceShiftId: null,
          gradedByDiscordId: interaction.user.id,
          gradedByTag: interaction.user.tag,
          gradedByRobloxUsername: issuerRank?.robloxUsername || null,
          overall: `Manual certification override: ${reason}`,
          strengths: [],
          improvements: [],
          recommendations: "Manual certification recorded by an Director+ authority.",
          evidence,
          manualOverride: true,
          manualReason: reason,
          feedbackMessageId: sentMessage?.id || null,
          feedbackThreadId: thread?.id || null,
          gradedAt: new Date(),
          updatedAt: new Date(),
        },
        $setOnInsert: { createdAt: new Date() },
      },
      { upsert: true, new: true },
    );

    return interaction.editReply(
      `**${target.robloxUsername}** has been manually marked as shift certified.` +
      (thread
        ? `\nProfile: https://discord.com/channels/${thread.guildId}/${thread.id}`
        : "\nNo staff profile log was available for this rank, so the certification was saved to the bot record only."),
    );

  }

  if (subcommand !== "grade") return interaction.editReply("Unknown shift certification action.");

  const authority = await getShiftCertificationAuthorityContext(interaction.guild, interaction.user.id, interaction.member);
  if (!authority.ok) return interaction.editReply(`❌ ${authority.reason}`);

  const targetUser = interaction.options.getUser("user", true);
  if (targetUser.bot) return interaction.editReply("❌ Bots cannot be shift certified.");
  if (targetUser.id === interaction.user.id) {
    return interaction.editReply("❌ You cannot grade your own shift certification.");
  }

  const target = await resolveShiftCertificationTargetByDiscordUser(targetUser);
  if (!target.ok) return interaction.editReply(`❌ ${target.reason}`);

  const certified = interaction.options.getBoolean("certified", true);
  const overall = interaction.options.getString("overall", true);
  const strengths = splitCertificationPoints(interaction.options.getString("strengths", true));
  const improvements = splitCertificationPoints(interaction.options.getString("improvements", true));
  const recommendations = interaction.options.getString("recommendations", true);
  const evidence = interaction.options.getString("evidence") || null;
  const latestClaim = findLatestShiftCertificationClaim(targetUser.id);

  const profileData = await getOrCreateStaffProfileThread({
    discordId: targetUser.id,
    robloxUsername: target.robloxUsername,
    robloxUserId: target.robloxUserId,
    rank: target.rankInfo.rank,
    rankName: target.rankInfo.name,
  });
  const thread = profileData?.thread;
  if (!thread) return interaction.editReply("❌ I could not access that staff member's profile log.");
  if (thread.archived) await thread.setArchived(false).catch(() => {});
  if (thread.locked) await thread.setLocked(false).catch(() => {});

  const feedbackContent = buildShiftCertificationFeedbackMessage({
    targetUsername: target.robloxUsername,
    targetRankName: target.rankInfo.name,
    gradedByUsername: authority.rankInfo?.robloxUsername || interaction.user.username,
    overall,
    strengths,
    improvements,
    recommendations,
    certified,
    latestClaim,
  });

  const sentMessage = await thread.send({
    content: feedbackContent,
    allowedMentions: { users: [targetUser.id] },
  });

  await ShiftCertification.findOneAndUpdate(
    { discordId: targetUser.id },
    {
      $set: {
        discordId: targetUser.id,
        robloxUsername: target.robloxUsername,
        robloxUsernameLower: target.robloxUsername.toLowerCase(),
        robloxUserId: String(target.robloxUserId),
        rankAtCertification: Number(target.rankInfo.rank),
        rankNameAtCertification: target.rankInfo.name || `Rank ${target.rankInfo.rank}`,
        status: certified ? "certified" : "not_certified",
        certified,
        lastShiftDate: latestClaim?.date || null,
        lastShiftTimeLabel: latestClaim?.claim?.timeLabel || null,
        lastShiftClaimMessageId: latestClaim?.claim?.messageId || null,
        lastAttendanceShiftId: latestClaim?.claim?.attendanceShiftId || null,
        gradedByDiscordId: interaction.user.id,
        gradedByTag: interaction.user.tag,
        gradedByRobloxUsername: authority.rankInfo?.robloxUsername || null,
        overall,
        strengths,
        improvements,
        recommendations,
        evidence,
        manualOverride: false,
        manualReason: null,
        feedbackMessageId: sentMessage.id,
        feedbackThreadId: thread.id,
        gradedAt: new Date(),
        updatedAt: new Date(),
      },
      $setOnInsert: { createdAt: new Date() },
    },
    { upsert: true, new: true },
  );

  await markShiftCertificationClaimOutcome(latestClaim, certified, interaction.user, sentMessage.id);
  await logBoardContribution({
    board: "operations",
    activityType: "shift_certification_graded",
    discordId: interaction.user.id,
    sourceType: "shift_certification",
    sourceId: `${targetUser.id}:${sentMessage.id}`,
    summary: `Logged shift certification feedback for ${target.robloxUsername}.`,
    loggedBy: interaction.user,
  }).catch(() => {});

  return interaction.editReply(
    `✅ Shift certification feedback logged for **${target.robloxUsername}**. ` +
    `Status: **${certified ? "Certified" : "Not Certified"}**.\n` +
    `Profile: https://discord.com/channels/${thread.guildId}/${thread.id}`,
  );
}

function escapeMongoRegex(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

async function findAttendanceForShiftClaim(claim) {
  const scheduledAt = new Date(claim.scheduledAt);
  const start = new Date(scheduledAt.getTime() - 20 * 60 * 1000);
  const end = new Date(scheduledAt.getTime() + 60 * 60 * 1000);
  const usernames = [claim.robloxUsername, claim.replacementRobloxUsername].filter(Boolean);
  if (!usernames.length) return null;

  return ShiftAttendance.findOne({
    hostUsername: {
      $in: usernames.map(username => new RegExp(`^${escapeMongoRegex(username)}$`, "i")),
    },
    startedAt: { $gte: start, $lte: end },
  }).lean().catch(() => null);
}

async function creditTypedShiftCompletionPoint(claim, discordId, robloxUsername, client, thread) {
  const typeConfig = getShiftClaimTypeConfig(claim?.shiftType);
  if (!typeConfig.operationsPointType || claim?.operationsPointCredited || !discordId) return false;

  const rankInfo = await getVerifiedMainRankForDiscord(discordId).catch(() => null);
  if (!rankInfo) return false;

  const assignment = await getBoardQuotaAssignmentForDiscord(thread?.guild, discordId, rankInfo.rank).catch(() => null);
  if (assignment?.boardKey !== "operations") return false;

  const sourceId = claim.messageId
    ? `shift_claim:${claim.messageId}:${claim.shiftType}`
    : `shift_claim:${claim.scheduledAt}:${discordId}:${claim.shiftType}`;
  const existing = await BoardContribution.findOne({
    board: "operations",
    activityType: typeConfig.operationsPointType,
    discordId,
    sourceType: "shift_claim",
    sourceId,
  }).lean().catch(() => null);

  if (existing) {
    claim.operationsPointCredited = true;
    claim.operationsPointContributionId = existing.contributionId || null;
    return false;
  }

  const result = await logBoardContribution({
    board: "operations",
    activityType: typeConfig.operationsPointType,
    discordId,
    sourceType: "shift_claim",
    sourceId,
    summary:
      `${typeConfig.label} completed by ${robloxUsername || "Unknown host"} from the shift claim for ${claim.timeLabel}. ` +
      `Attendance record: ${claim.attendanceShiftId || "confirmed"}.`,
    loggedBy: {
      id: client?.user?.id || discordId,
      tag: client?.user?.tag || "Sweetsiez Bot",
    },
  });

  if (!result?.contributionDoc) return false;
  claim.operationsPointCredited = true;
  claim.operationsPointContributionId = result.contributionDoc.contributionId;
  return true;
}

async function assignShiftReplacement(postInfo, claim, thread, reason) {
  const claimTime = new Date(claim.scheduledAt).getTime();
  const typeConfig = getShiftClaimTypeConfig(claim?.shiftType);
  const claimTitle = formatShiftClaimTitle(claim);
  const replyFormat = formatShiftClaimReplyFormat(claim);
  let standby = null;

  for (const entry of postInfo.standbys || []) {
    const isEligibleTime =
      entry.status === "waiting" &&
      Math.abs(new Date(entry.scheduledAt).getTime() - claimTime) <= 30 * 60 * 1000;
    if (!isEligibleTime) continue;

    if (typeConfig.allowedLevels) {
      const authority = await getShiftCertificationAuthorityContext(thread?.guild, entry.discordId).catch(() => null);
      if (!authority?.ok || !typeConfig.allowedLevels.includes(authority.level)) continue;
    }

    standby = entry;
    break;
  }

  if (!standby) {
    await thread.send(
      `🚨 **Open coverage needed for the ${claimTitle}.**\n` +
      `Reason: ${reason}\nReply with **${replyFormat}** to claim the opening.`,
    ).catch(() => {});
    return null;
  }

  standby.status = "assigned";
  standby.assignedAt = new Date().toISOString();
  claim.replacementDiscordId = standby.discordId;
  claim.replacementRobloxUsername = standby.robloxUsername;
  claim.replacementAssignedAt = new Date().toISOString();
  claim.status = "replacement_assigned";
  postInfo.claimCount = (postInfo.claims || []).filter(entry => entry.status !== "cancelled").length;
  if (!postInfo.claimedBy.includes(standby.discordId)) postInfo.claimedBy.push(standby.discordId);
  await updateShiftReliability(standby.discordId, standby.robloxUsername, "covered");

  const user = await client.users.fetch(standby.discordId).catch(() => null);
  if (user) {
    await user.send(
      `🛟 You were assigned from standby to cover the **${claimTitle}**. ` +
      "Please begin the shift on time. If an emergency prevents you from covering it, contact Management immediately.",
    ).catch(() => {});
  }
  await thread.send(
    `🛟 **Standby assigned:** <@${standby.discordId}> (${standby.robloxUsername}) will cover the **${claimTitle}**.`,
  ).catch(() => {});
  return standby;
}

/**
 * Update shift post claim count
 */
async function updateShiftPostCount(thread, claimCount) {
  try {
    const starterMessage = await thread.fetchStarterMessage();
    if (starterMessage) {
      // The post is an embed now, so starterMessage.content is empty — rebuild the embed with the
      // new count instead of regex-replacing text that no longer exists.
      const displayDate = String(thread.name || "").replace(/^Shifts\s*-\s*/i, "").trim() || getESTDate();
      // content: "" is required — an embed-only edit leaves the old text in place.
      await starterMessage.edit({ content: "", embeds: [buildShiftClaimEmbed(displayDate, claimCount)] });
    }
  } catch (error) {
    console.error("Error updating shift post count:", error);
  }
}

/**
 * Handle shift claim cancellation via message deletion
 */
async function handleShiftCancellation(message, client) {
  const messageInfo = shiftMessages.get(message.id);
  if (!messageInfo) return;

  const { userId, date, threadId, kind = "claim" } = messageInfo;
  const postInfo = shiftPosts.get(date);
  if (!postInfo) return;

  const entries = kind === "standby" ? (postInfo.standbys || []) : (postInfo.claims || []);
  const entry = entries.find(item => item.messageId === message.id);
  if (!entry || entry.status === "cancelled") return;
  const hostDiscordId = entry.discordId || messageInfo.claimDiscordId || userId;

  entry.status = "cancelled";
  entry.cancelledAt = new Date().toISOString();
  shiftMessages.delete(message.id);

  if (kind === "claim") {
    postInfo.claimCount = (postInfo.claims || []).filter(claim => claim.status !== "cancelled").length;
    if (!(postInfo.claims || []).some(claim => claim.discordId === hostDiscordId && claim.status !== "cancelled")) {
      postInfo.claimedBy = postInfo.claimedBy.filter(id => id !== hostDiscordId);
    }
    await updateShiftReliability(hostDiscordId, entry.robloxUsername, "cancelled");
  } else {
    const assignedClaim = (postInfo.claims || []).find(claim =>
      claim.replacementDiscordId === hostDiscordId && claim.status === "replacement_assigned",
    );
    if (assignedClaim) {
      assignedClaim.status = "no_show";
      assignedClaim.replacementDiscordId = null;
      assignedClaim.replacementRobloxUsername = null;
    }
  }
  shiftPosts.set(date, postInfo);
  await saveShiftPosts();

  try {
    const thread = await client.channels.fetch(threadId);
    if (kind === "claim") {
      await updateShiftPostCount(thread, postInfo.claimCount);
      await thread.send(
        `🔄 <@${hostDiscordId}> canceled the **${formatShiftClaimTitle(entry)}** claim. ` +
        `**${postInfo.claimCount}/${SHIFT_CLAIMING_CONFIG.MAX_SHIFTS_PER_DAY}** slots claimed.`,
      );
      if (new Date(entry.scheduledAt).getTime() > Date.now()) {
        await assignShiftReplacement(postInfo, entry, thread, "The original host cancelled.");
        await saveShiftPosts();
        await updateShiftPostCount(thread, postInfo.claimCount);
      }
    } else {
      await thread.send(`🔄 <@${hostDiscordId}> left standby coverage for **${entry.timeLabel}**.`);
      const uncoveredClaim = (postInfo.claims || []).find(claim =>
        claim.status === "no_show" &&
        Math.abs(new Date(claim.scheduledAt).getTime() - new Date(entry.scheduledAt).getTime()) <= 30 * 60 * 1000,
      );
      if (uncoveredClaim) {
        await assignShiftReplacement(postInfo, uncoveredClaim, thread, "The assigned standby became unavailable.");
        await saveShiftPosts();
      }
    }
  } catch (error) {
    console.error("Error updating after cancellation:", error);
  }
}

/**
 * Handle shift claim cancellation via reaction
 */
async function handleShiftReactionCancel(reaction, user, client) {
  if (user.bot) return;
  if (!["\u274C", "❌"].includes(reaction.emoji.name)) return;
  if (reaction.partial) {
    try {
      await reaction.fetch();
    } catch (error) {
      console.error('Error fetching reaction:', error);
      return;
    }
  }

  const message = reaction.message;
  const messageInfo = shiftMessages.get(message.id);
  if (!messageInfo) return;

  const { userId, date, threadId, kind = "claim" } = messageInfo;
  const postInfo = shiftPosts.get(date);
  if (!postInfo) return;

  const entries = kind === "standby" ? (postInfo.standbys || []) : (postInfo.claims || []);
  const entry = entries.find(item => item.messageId === message.id);
  if (!entry || entry.status === "cancelled") return;
  const hostDiscordId = entry.discordId || messageInfo.claimDiscordId || userId;
  const cancelActorIds = new Set([
    userId,
    messageInfo.claimDiscordId,
    entry.discordId,
    entry.claimedByDiscordId,
  ].filter(Boolean));

  if (!cancelActorIds.has(user.id)) {
    try {
      await reaction.users.remove(user.id);
    } catch (error) {
      console.error("Error removing reaction:", error);
    }
    return;
  }

  entry.status = "cancelled";
  entry.cancelledAt = new Date().toISOString();
  shiftMessages.delete(message.id);
  if (kind === "claim") {
    postInfo.claimCount = (postInfo.claims || []).filter(claim => claim.status !== "cancelled").length;
    if (!(postInfo.claims || []).some(claim => claim.discordId === hostDiscordId && claim.status !== "cancelled")) {
      postInfo.claimedBy = postInfo.claimedBy.filter(id => id !== hostDiscordId);
    }
    await updateShiftReliability(hostDiscordId, entry.robloxUsername, "cancelled");
  } else {
    const assignedClaim = (postInfo.claims || []).find(claim =>
      claim.replacementDiscordId === hostDiscordId && claim.status === "replacement_assigned",
    );
    if (assignedClaim) {
      assignedClaim.status = "no_show";
      assignedClaim.replacementDiscordId = null;
      assignedClaim.replacementRobloxUsername = null;
    }
  }
  shiftPosts.set(date, postInfo);
  await saveShiftPosts();
  await message.delete().catch(error => console.error("Error deleting message:", error));

  try {
    const thread = await client.channels.fetch(threadId);
    if (kind === "claim") {
      const cancellationText = user.id === hostDiscordId
        ? `<@${hostDiscordId}> canceled`
        : `<@${user.id}> canceled <@${hostDiscordId}>'s`;
      await updateShiftPostCount(thread, postInfo.claimCount);
      await thread.send(
        `🔄 ${cancellationText} the **${formatShiftClaimTitle(entry)}** claim. ` +
        `**${postInfo.claimCount}/${SHIFT_CLAIMING_CONFIG.MAX_SHIFTS_PER_DAY}** slots claimed.`,
      );
      if (new Date(entry.scheduledAt).getTime() > Date.now()) {
        await assignShiftReplacement(postInfo, entry, thread, "The original host cancelled.");
        await saveShiftPosts();
        await updateShiftPostCount(thread, postInfo.claimCount);
      }
    } else {
      const standbyText = user.id === hostDiscordId
        ? `<@${hostDiscordId}> left`
        : `<@${user.id}> removed <@${hostDiscordId}> from`;
      await thread.send(`🔄 ${standbyText} standby coverage for **${entry.timeLabel}**.`);
      const uncoveredClaim = (postInfo.claims || []).find(claim =>
        claim.status === "no_show" &&
        Math.abs(new Date(claim.scheduledAt).getTime() - new Date(entry.scheduledAt).getTime()) <= 30 * 60 * 1000,
      );
      if (uncoveredClaim) {
        await assignShiftReplacement(postInfo, uncoveredClaim, thread, "The assigned standby became unavailable.");
        await saveShiftPosts();
      }
    }
  } catch (error) {
    console.error("Error updating after cancellation:", error);
  }
}

async function runShiftCoverageCheck(client) {
  const now = Date.now();
  const today = getESTDate();
  const date = new Date(`${today}T12:00:00Z`);
  date.setUTCDate(date.getUTCDate() - 1);
  const yesterday = date.toISOString().slice(0, 10);

  for (const dateKey of [yesterday, today]) {
    const postInfo = shiftPosts.get(dateKey);
    if (!postInfo?.threadId) continue;
    const thread = await client.channels.fetch(postInfo.threadId).catch(() => null);
    if (!thread?.isTextBased()) continue;

    let changed = false;
    for (const claim of postInfo.claims || []) {
      if (["cancelled", "uncovered"].includes(claim.status)) continue;
      if (claim.status === "completed") {
        const completedDiscordId = claim.replacementDiscordId || claim.discordId;
        const completedUsername = claim.replacementRobloxUsername || claim.robloxUsername;
        const shouldCreditOperationsPoint = Boolean(getShiftClaimTypeConfig(claim.shiftType).operationsPointType);
        if (shouldCreditOperationsPoint && !claim.operationsPointCredited) {
          const credited = await creditTypedShiftCompletionPoint(
            claim,
            completedDiscordId,
            completedUsername,
            client,
            thread,
          ).catch(error => {
            console.error("[ShiftCoverage] Typed shift point credit failed:", error.message);
            return false;
          });
          if (credited || claim.operationsPointCredited) changed = true;
        }
        continue;
      }
      const scheduledAt = new Date(claim.scheduledAt).getTime();
      if (!Number.isFinite(scheduledAt)) continue;

      const minutesUntil = Math.floor((scheduledAt - now) / 60000);
      claim.remindersSent = Array.isArray(claim.remindersSent) ? claim.remindersSent : [];

      if (claim.status === "scheduled" && minutesUntil > 0) {
        const threshold = minutesUntil <= 15
          ? 15
          : minutesUntil <= 60
            ? 60
            : null;
        if (threshold && !claim.remindersSent.includes(threshold)) {
          const user = await client.users.fetch(claim.discordId).catch(() => null);
          if (user) {
            await user.send(
              `⏰ Reminder: you claimed the **${formatShiftClaimTitle(claim)}** today. ` +
              `It begins in about **${threshold} minutes**.`,
            ).catch(() => {});
          }
          claim.remindersSent.push(threshold);
          changed = true;
        }
      }

      if (now < scheduledAt - 20 * 60 * 1000) continue;
      const attendance = await findAttendanceForShiftClaim(claim);
      if (attendance?.startedAt) {
        claim.status = "completed";
        claim.completedAt = new Date(attendance.startedAt).toISOString();
        claim.attendanceShiftId = attendance.shiftId;
        const completedDiscordId = claim.replacementDiscordId || claim.discordId;
        const completedUsername = claim.replacementRobloxUsername || claim.robloxUsername;
        if (!claim.completionCredited) {
          claim.completionCredited = true;
          await updateShiftReliability(completedDiscordId, completedUsername, "completed");
        }
        const shouldCreditOperationsPoint = Boolean(getShiftClaimTypeConfig(claim.shiftType).operationsPointType);
        if (shouldCreditOperationsPoint && !claim.operationsPointCredited) {
          const credited = await creditTypedShiftCompletionPoint(
            claim,
            completedDiscordId,
            completedUsername,
            client,
            thread,
          ).catch(error => {
            console.error("[ShiftCoverage] Typed shift point credit failed:", error.message);
            return false;
          });
          if (credited || claim.operationsPointCredited) changed = true;
        }
        await thread.send(
          `✅ **Coverage confirmed:** ${completedUsername} started the **${formatShiftClaimTitle(claim)}**.`,
        ).catch(() => {});
        changed = true;
        continue;
      }

      const noShowAt = scheduledAt + SHIFT_CLAIMING_CONFIG.NO_SHOW_GRACE_MINUTES * 60 * 1000;
      if (claim.status === "scheduled" && now >= noShowAt) {
        claim.status = "no_show";
        claim.noShowAt = new Date().toISOString();
        if (!claim.missedCredited) {
          claim.missedCredited = true;
          await updateShiftReliability(claim.discordId, claim.robloxUsername, "missed");
        }
        await thread.send(
          `⚠️ **Possible no-show:** <@${claim.discordId}> has not started the **${formatShiftClaimTitle(claim)}** ` +
          `${SHIFT_CLAIMING_CONFIG.NO_SHOW_GRACE_MINUTES} minutes after its scheduled time.`,
        ).catch(() => {});
        await assignShiftReplacement(postInfo, claim, thread, "The scheduled host did not begin the shift.");
        changed = true;
        continue;
      }

      const replacementDeadline =
        scheduledAt +
        (SHIFT_CLAIMING_CONFIG.NO_SHOW_GRACE_MINUTES + SHIFT_CLAIMING_CONFIG.REPLACEMENT_GRACE_MINUTES) * 60 * 1000;
      if (
        claim.status === "replacement_assigned" &&
        now >= replacementDeadline &&
        !claim.replacementMissedCredited
      ) {
        claim.status = "uncovered";
        claim.replacementMissedCredited = true;
        await updateShiftReliability(
          claim.replacementDiscordId,
          claim.replacementRobloxUsername,
          "missed",
        );
        await thread.send(
          `🚨 **Shift remains uncovered:** the standby replacement for the **${formatShiftClaimTitle(claim)}** did not start it. ` +
          "Management should arrange immediate coverage.",
        ).catch(() => {});
        changed = true;
      }
    }

    if (changed) {
      postInfo.claimCount = (postInfo.claims || []).filter(claim => claim.status !== "cancelled").length;
      shiftPosts.set(dateKey, postInfo);
      await saveShiftPosts();
      await updateShiftPostCount(thread, postInfo.claimCount);
    }
  }
}

/**
 * Start the shift claiming scheduler
 */
function startShiftClaimingScheduler(client) {
  runShiftCoverageCheck(client).catch(error =>
    console.error("[ShiftCoverage] Initial check failed:", error.message),
  );

  // Check every minute for midnight EST
  setInterval(async () => {
    await runShiftCoverageCheck(client).catch(error =>
      console.error("[ShiftCoverage] Scheduled check failed:", error.message),
    );

    const now = new Date();
    const estTime = new Date(now.toLocaleString("en-US", { timeZone: SHIFT_CLAIMING_CONFIG.TIMEZONE }));
    
    // Check if it's midnight EST (00:00)
    if (estTime.getHours() === 0 && estTime.getMinutes() === 0) {
      console.log("🕐 Midnight EST - Running shift post tasks...");
      
      // Lock yesterday's post
      await lockYesterdayShiftPost(client);
      
      // Create today's post
      await createShiftPost(client);
    }
  }, 60000); // Check every minute

  console.log("✅ Shift claiming scheduler started");
}

/**
 * Handle messages in shift forum threads
 */
async function handleShiftMessage(message, client) {
  if (message.author.bot) return;
  if (message.channel.parentId !== SHIFT_CLAIMING_CONFIG.FORUM_CHANNEL_ID) return;

  const today = getESTDate();
  const postInfo = shiftPosts.get(today);
  if (!postInfo || message.channel.id !== postInfo.threadId) return;

  const parsed = parseShiftClaim(message.content, today);
  if (!parsed) {
    try {
      await message.delete();
      const warning = await message.channel.send(
        `${message.author}, use **USERNAME | TIME EST**, **RECRUITMENT | USERNAME | TIME EST**, or ` +
        `**PROMOTIONAL | USERNAME | TIME EST** for shift claims. ` +
        `Standby uses **STANDBY | USERNAME | TIME EST**. ` +
        `Certification shifts use **SUPERVISED | HOST_USERNAME | TIME EST**.`,
      );
      setTimeout(() => warning.delete().catch(() => {}), 10000);
    } catch (error) {
      console.error("Error deleting off-topic message:", error);
    }
    return;
  }

  const linkedUsername = verifiedUsers.get(message.author.id);
  let claimDiscordId = message.author.id;
  let claimDiscordTag = message.author.tag;
  let claimRobloxUsername = linkedUsername;
  let supervisedTarget = null;
  let certificationAuthority = null;

  if (parsed.isSupervised) {
    certificationAuthority = await getShiftCertificationAuthorityContext(message.guild, message.author.id, message.member);
    if (!certificationAuthority.ok) {
      await message.delete().catch(() => {});
      const warning = await message.channel.send(`${message.author}, ${certificationAuthority.reason}`);
      setTimeout(() => warning.delete().catch(() => {}), 12000);
      return;
    }

    supervisedTarget = await resolveShiftCertificationTargetByUsername(parsed.robloxUsername);
    if (!supervisedTarget.ok) {
      await message.delete().catch(() => {});
      const warning = await message.channel.send(`${message.author}, ${supervisedTarget.reason}`);
      setTimeout(() => warning.delete().catch(() => {}), 12000);
      return;
    }

    if (await isShiftHostCertified(supervisedTarget.discordId)) {
      await message.delete().catch(() => {});
      const warning = await message.channel.send(
        `${message.author}, **${supervisedTarget.robloxUsername}** is already certified. They may claim shifts normally.`,
      );
      setTimeout(() => warning.delete().catch(() => {}), 12000);
      return;
    }

    claimDiscordId = supervisedTarget.discordId;
    const supervisedDiscordUser = await client.users.fetch(supervisedTarget.discordId).catch(() => null);
    claimDiscordTag = supervisedDiscordUser?.tag || "Supervised Host";
    claimRobloxUsername = supervisedTarget.robloxUsername;
  } else {
    if (!linkedUsername || linkedUsername.toLowerCase() !== parsed.robloxUsername.toLowerCase()) {
      await message.delete().catch(() => {});
      const warning = await message.channel.send(
        `${message.author}, the Roblox username must match the account linked to your Discord verification.`,
      );
      setTimeout(() => warning.delete().catch(() => {}), 10000);
      return;
    }

    const authorRank = await getVerifiedMainRankForDiscord(message.author.id).catch(() => null);
    if (
      isShiftCertificationRank(authorRank?.rank) &&
      !(await isShiftHostCertified(message.author.id))
    ) {
      await message.delete().catch(() => {});
      const warning = await message.channel.send(
        `${message.author}, uncertified Supervisor+ hosts cannot claim shifts or standby coverage for themselves. ` +
        `Have an eligible Human Resources Aspirants or Executives claim it as ` +
        `**SUPERVISED | ${linkedUsername} | TIME EST**.`,
      );
      setTimeout(() => warning.delete().catch(() => {}), 15000);
      return;
    }
  }

  if (parsed.shiftType !== "regular") {
    const typeConfig = getShiftClaimTypeConfig(parsed.shiftType);
    const authority = await getShiftCertificationAuthorityContext(
      message.guild,
      message.author.id,
      message.member,
    ).catch(error => {
      console.error("Shift type claim permission lookup failed:", error.message);
      return { ok: false, reason: "I could not verify your special shift permissions." };
    });
    if (!authority.ok || !typeConfig.allowedLevels?.includes(authority.level)) {
      await message.delete().catch(() => {});
      const warning = await message.channel.send(
        `${message.author}, ${typeConfig.label} claims can only be made by ${getShiftClaimPermissionLabel(typeConfig)}.`,
      );
      setTimeout(() => warning.delete().catch(() => {}), 12000);
      return;
    }
  }

  if (new Date(parsed.scheduledAt).getTime() < Date.now() - 10 * 60 * 1000) {
    await message.delete().catch(() => {});
    const warning = await message.channel.send(
      `${message.author}, that shift time has already passed.`,
    );
    setTimeout(() => warning.delete().catch(() => {}), 10000);
    return;
  }

  postInfo.claims = postInfo.claims || [];
  postInfo.standbys = postInfo.standbys || [];
  const targetCollection = parsed.isStandby ? postInfo.standbys : postInfo.claims;
  const duplicate = targetCollection.some(entry =>
    entry.discordId === claimDiscordId &&
    entry.scheduledAt === parsed.scheduledAt &&
    entry.status !== "cancelled",
  );
  if (duplicate) {
    await message.delete().catch(() => {});
    const warning = await message.channel.send(
      `${message.author}, you already have that ${parsed.isStandby ? "standby entry" : `${formatShiftClaimTitle(parsed)} claim`} recorded.`,
    );
    setTimeout(() => warning.delete().catch(() => {}), 10000);
    return;
  }

  if (!parsed.isStandby && postInfo.claimCount >= SHIFT_CLAIMING_CONFIG.MAX_SHIFTS_PER_DAY) {
    await message.delete().catch(() => {});
    const warning = await message.channel.send(
      `${message.author}, all ${SHIFT_CLAIMING_CONFIG.MAX_SHIFTS_PER_DAY} shift slots are claimed. ` +
      "You may still register as standby.",
    );
    setTimeout(() => warning.delete().catch(() => {}), 10000);
    return;
  }

  const entry = {
    discordId: claimDiscordId,
    discordTag: claimDiscordTag,
    robloxUsername: claimRobloxUsername,
    timeLabel: parsed.timeLabel,
    shiftType: parsed.shiftType || "regular",
    shiftTypeLabel: parsed.shiftTypeLabel || getShiftClaimTypeConfig(parsed.shiftType).label,
    operationsPointType: getShiftClaimTypeConfig(parsed.shiftType).operationsPointType || null,
    operationsPointCredited: false,
    scheduledAt: parsed.scheduledAt,
    messageId: message.id,
    status: parsed.isStandby ? "waiting" : "scheduled",
    remindersSent: [],
    createdAt: new Date().toISOString(),
  };
  if (parsed.isSupervised) {
    entry.supervised = true;
    entry.certificationRequired = true;
    entry.claimedByDiscordId = message.author.id;
    entry.claimedByTag = message.author.tag;
    entry.claimedByRobloxUsername = certificationAuthority?.rankInfo?.robloxUsername || linkedUsername || null;
    entry.targetRank = supervisedTarget?.rankInfo?.rank || null;
    entry.targetRankName = supervisedTarget?.rankInfo?.name || null;
    entry.certificationStatus = "pending";
  }
  targetCollection.push(entry);
  if (!parsed.isStandby) {
    postInfo.claimCount = postInfo.claims.filter(claim => claim.status !== "cancelled").length;
    if (!postInfo.claimedBy.includes(claimDiscordId)) postInfo.claimedBy.push(claimDiscordId);
    await updateShiftReliability(claimDiscordId, claimRobloxUsername, "scheduled");
  }
  shiftPosts.set(today, postInfo);
  shiftMessages.set(message.id, {
    userId: message.author.id,
    claimDiscordId,
    date: today,
    threadId: message.channel.id,
    kind: parsed.isStandby ? "standby" : "claim",
  });
  await saveShiftPosts();
  await message.react("❌").catch(() => {});

  if (parsed.isStandby) {
    await message.react("🛟").catch(() => {});
    await message.author.send(
      `🛟 You are on standby for **${parsed.timeLabel}**. If that shift opens, the bot may assign you automatically.`,
    ).catch(() => {});
    const openClaim = postInfo.claims.find(claim =>
      ["no_show", "uncovered"].includes(claim.status) &&
      Math.abs(new Date(claim.scheduledAt).getTime() - new Date(parsed.scheduledAt).getTime()) <= 30 * 60 * 1000,
    );
    if (openClaim) {
      await assignShiftReplacement(postInfo, openClaim, message.channel, "An uncovered shift matched this standby time.");
      await saveShiftPosts();
      await updateShiftPostCount(message.channel, postInfo.claimCount);
    }
    return;
  }

  await message.react("✅").catch(() => {});
  await updateShiftPostCount(message.channel, postInfo.claimCount);
  if (parsed.isSupervised) {
    const hostUser = await client.users.fetch(claimDiscordId).catch(() => null);
    await hostUser?.send(
      `✅ Your supervised certification shift for **${parsed.timeLabel}** was claimed by **${message.author.tag}**. ` +
      "I will remind you about one hour and 15 minutes before it begins.",
    ).catch(() => {});
    await message.author.send(
      `✅ Supervised certification shift claimed for **${claimRobloxUsername}** at **${parsed.timeLabel}**.`,
    ).catch(() => {});
    await message.channel.send(
      `📋 **Supervised certification shift recorded:** <@${claimDiscordId}> (${claimRobloxUsername}) ` +
      `will host at **${parsed.timeLabel}**, claimed by <@${message.author.id}>.`,
    ).catch(() => {});
  } else {
    await message.author.send(
      `✅ Your **${formatShiftClaimTitle(parsed)}** is claimed. I will remind you about one hour and 15 minutes before it begins.`,
    ).catch(() => {});
  }

  if (postInfo.claimCount === SHIFT_CLAIMING_CONFIG.MAX_SHIFTS_PER_DAY) {
    await message.channel.send(
      `🎯 **All ${SHIFT_CLAIMING_CONFIG.MAX_SHIFTS_PER_DAY} shift slots have been claimed. Standby entries remain open.**`,
    );
  }
}

// ===========================
// TRIAL SYSTEM FUNCTIONS
// ===========================

function normalizeTrialAnswers(rawAnswers = []) {
  return (Array.isArray(rawAnswers) ? rawAnswers : [])
    .map((answer, index) => {
      if (!answer || typeof answer !== "object") return null;
      const hasSavedQuestionIndex = answer.questionIndex !== null && answer.questionIndex !== undefined;
      const questionIndex = hasSavedQuestionIndex && Number.isInteger(Number(answer.questionIndex))
        ? Number(answer.questionIndex)
        : index;
      if (questionIndex < 0 || questionIndex >= TRIAL_QUESTIONS.length) return null;
      return {
        ...answer,
        questionIndex,
        question: answer.question || TRIAL_QUESTIONS[questionIndex]?.question || `Question ${questionIndex + 1}`,
      };
    })
    .filter(Boolean)
    .sort((a, b) => Number(a.questionIndex) - Number(b.questionIndex));
}

function getNextTrialQuestionIndex(rawAnswers = []) {
  const answeredIndexes = new Set(
    normalizeTrialAnswers(rawAnswers)
      .filter(answer => String(answer.answer || "").trim())
      .map(answer => Number(answer.questionIndex)),
  );
  for (let index = 0; index < TRIAL_QUESTIONS.length; index++) {
    if (!answeredIndexes.has(index)) return index;
  }
  return TRIAL_QUESTIONS.length;
}

function resolveSavedTrialQuestionIndex(docOrData = {}) {
  const fallbackIndex = getNextTrialQuestionIndex(docOrData.answers || []);
  const savedIndex = Number(docOrData.currentQuestion);
  if (!Number.isInteger(savedIndex)) return fallbackIndex;
  if (savedIndex < 0) return 0;
  if (savedIndex > TRIAL_QUESTIONS.length) return TRIAL_QUESTIONS.length;
  return Math.max(savedIndex, fallbackIndex);
}

// Load trials from MongoDB
async function loadTrials() {
  try {
    const docs = await Trial.find({});
    activeTrials.clear();
    docs.forEach(doc => {
      const rawDoc = typeof doc.toObject === "function" ? doc.toObject() : doc;
      const answers = normalizeTrialAnswers(rawDoc.answers);
      const hasPendingEdit = rawDoc.pendingEdit !== null && rawDoc.pendingEdit !== undefined;
      const pendingEdit = hasPendingEdit && Number.isInteger(Number(rawDoc.pendingEdit))
        ? Number(rawDoc.pendingEdit)
        : undefined;
      activeTrials.set(rawDoc.threadId, {
        threadId: rawDoc.threadId,
        userId: rawDoc.userId,
        robloxUsername: rawDoc.robloxUsername,
        startedBy: rawDoc.startedBy,
        startedByUsername: rawDoc.startedByUsername,
        startedAt: rawDoc.startedAt,
        lastActivity: rawDoc.lastActivity || rawDoc.startedAt,
        stage: rawDoc.stage,
        currentQuestion: resolveSavedTrialQuestionIndex({ ...rawDoc, answers }),
        pendingEdit,
        answers,
        passed: rawDoc.passed,
        completedAt: rawDoc.completedAt || null,
      });
    });
    console.log(`✅ Loaded ${activeTrials.size} active trials from MongoDB`);
  } catch (error) {
    console.error("Error loading trials from MongoDB:", error);
  }
}

// Save trials to MongoDB
async function saveTrials() {
  try {
    const bulkOps = [];
    activeTrials.forEach((data, threadId) => {
      bulkOps.push({
        updateOne: {
          filter: { threadId },
          update: {
            $set: {
              threadId,
              userId: data.userId,
              robloxUsername: data.robloxUsername,
              startedBy: data.startedBy,
              startedByUsername: data.startedByUsername || null,
              startedAt: data.startedAt,
              lastActivity: data.lastActivity || data.startedAt,
              stage: data.stage,
              currentQuestion: resolveSavedTrialQuestionIndex(data),
              pendingEdit: data.pendingEdit ?? null,
              answers: normalizeTrialAnswers(data.answers),
              passed: data.passed,
              completedAt: data.completedAt || null,
            },
          },
          upsert: true,
        },
      });
    });
    if (bulkOps.length > 0) await Trial.bulkWrite(bulkOps);
    console.log(`💾 Saved trials to MongoDB`);
  } catch (error) {
    console.error("Error saving trials to MongoDB:", error);
  }
}

// ── Trial inactivity + 48h timeout system ────────────────────────────────────
// Runs every 15 minutes. For each active trial:
//   • If the participant hasn't sent a message in 3 hours → ping them.
//   • If 48 hours have elapsed since the trial started → expire it.
const TRIAL_INACTIVITY_PING_MS   = 3  * 60 * 60 * 1000; // 3 hours
const TRIAL_INACTIVITY_WARN_MS   = 3  * 60 * 60 * 1000; // re-ping every 3h
const TRIAL_EXPIRE_MS            = 48 * 60 * 60 * 1000; // 48 hours total
const TRIAL_ROLE_ID_GLOBAL       = TRIAL_ROLE_ID;
const SA_TRIAL_LOG_CHANNEL_ID_GLOBAL = "1463586676352745640";
const SA_TRIAL_REVIEW_PING_ROLE_IDS = [
  "1521611454741090364", // Human Resources Aspirant
  "1521611446591426690", // Human Resources Department
];

// Tracks when we last pinged each trial thread (threadId -> Date)
const trialLastPingMap = new Map();

async function runTrialInactivityCheck(client) {
  const now = Date.now();
  for (const [threadId, trialData] of activeTrials.entries()) {
    // Only monitor trials that are still in progress
    if (!['welcome', 'questions'].includes(trialData.stage)) continue;

    const startedAt    = new Date(trialData.startedAt).getTime();
    const lastActivity = new Date(trialData.lastActivity || trialData.startedAt).getTime();
    const lastPing     = trialLastPingMap.get(threadId) || 0;

    // ── 48-hour expiry ────────────────────────────────────────────────────
    if (now - startedAt >= TRIAL_EXPIRE_MS) {
      try {
        const thread = await client.channels.fetch(threadId).catch(() => null);
        const guild  = thread?.guild || client.guilds.cache.first();

        // Remove trial role
        if (guild) {
          const member = await guild.members.fetch(trialData.userId).catch(() => null);
          if (member) await member.roles.remove(TRIAL_ROLE_ID_GLOBAL).catch(() => {});
        }

        // DM the participant
        const trialUser = await client.users.fetch(trialData.userId).catch(() => null);
        if (trialUser) {
          const expiredDmEmbed = new EmbedBuilder()
            .setColor(0xff0000)
            .setDescription(
              `🧁 **TRIAL EXPIRED**\n\nGreetings, ${trialData.robloxUsername}. Unfortunately, your Supervisor trial has been closed as the 48-hour time limit has been reached without completion.\n\nIf you believe this was an error or would like to discuss the matter, please reach out to a Manager. You are welcome to be re-trialed in the future.\n\nMuch Regards,\n*Sweetsiez Management Team*`
            );
          await trialUser.send({ embeds: [expiredDmEmbed] }).catch(() => {});
        }

        // Log to trial log channel
        if (guild) {
          const logChannel = await client.channels.fetch(SA_TRIAL_LOG_CHANNEL_ID_GLOBAL).catch(() => null);
          if (logChannel) {
            const logEmbed = new EmbedBuilder()
              .setTitle("⏰ Trial Expired — Time Limit Reached")
              .setColor(0xff6600)
              .addFields(
                { name: "Discord User", value: `<@${trialData.userId}> (${trialData.userId})`, inline: false },
                { name: "Roblox Username", value: trialData.robloxUsername, inline: false },
                { name: "Trial Started By", value: `<@${trialData.startedBy}>`, inline: false },
                { name: "Trial Thread", value: `<#${threadId}>`, inline: true },
                { name: "Duration", value: "48 hours elapsed", inline: true }
              )
              .setTimestamp();
            await logChannel.send({ embeds: [logEmbed] }).catch(() => {});
          }
        }

        // Mark expired and clean up
        trialData.stage = "expired";
        await saveTrials();
        activeTrials.delete(threadId);
        trialLastPingMap.delete(threadId);
        await Trial.deleteOne({ threadId }).catch(() => {});

        // Delete the thread
        if (thread) await thread.delete('Trial expired — 48h time limit reached').catch(() => {});
      } catch (err) {
        console.error(`[TrialExpiry] Error expiring trial ${threadId}:`, err.message);
      }
      continue;
    }

    // ── 3-hour inactivity ping ────────────────────────────────────────────
    const timeSinceActivity = now - lastActivity;
    const timeSinceLastPing = now - lastPing;

    if (timeSinceActivity >= TRIAL_INACTIVITY_PING_MS && timeSinceLastPing >= TRIAL_INACTIVITY_WARN_MS) {
      try {
        const thread = await client.channels.fetch(threadId).catch(() => null);
        if (thread) {
          const hoursLeft = Math.max(0, Math.floor((TRIAL_EXPIRE_MS - (now - startedAt)) / (60 * 60 * 1000)));
          await thread.send(
            `<@${trialData.userId}> ⏰ Just checking in — we noticed you haven't sent a message in a while! Your trial thread will be automatically closed in approximately **${hoursLeft} hour(s)** if it is not completed. Please continue when you're ready!`
          ).catch(() => {});
          trialLastPingMap.set(threadId, now);
        }
      } catch (err) {
        console.error(`[TrialInactivity] Error pinging trial ${threadId}:`, err.message);
      }
    }
  }
}

// Start the inactivity check interval (every 15 minutes)
setInterval(() => {
  if (typeof client !== 'undefined') runTrialInactivityCheck(client).catch(console.error);
}, 15 * 60 * 1000);

