  function canAccessHandbookGuide(guide, viewerRank, member) {
    const minRank = Number(guide.minRank || 0);
    const hasRankAccess = minRank === SWEETSIEZ_STRUCTURE_CONFIG.EXECUTIVE_DIRECTOR_RANK
      ? isExecutiveDirectorOrLeadershipRank(viewerRank)
      : viewerRank >= minRank;
    if (!hasRankAccess) return false;
    if (!canAccessResourceKey(guide.accessKey, viewerRank, member)) return false;
    if (
      guide.requiresMarketingRole &&
      !member?.roles.cache.has(REPORT_SYSTEM_CONFIG.MARKETING_TEAM_ROLE_ID)
    ) {
      return false;
    }
    return true;
  }

