  function buildButtonRows(items, buildButton) {
    const rows = [];
    let row = new ActionRowBuilder();

    items.forEach((item, index) => {
      if (index > 0 && index % 5 === 0) {
        rows.push(row);
        row = new ActionRowBuilder();
      }
      row.addComponents(buildButton(item));
    });

    if (row.components.length > 0) rows.push(row);
    return rows;
  }

  function truncateComponentText(value, maxLength = 100) {
    const text = String(value || "").trim();
    if (text.length <= maxLength) return text;
    return `${text.slice(0, Math.max(0, maxLength - 1))}…`;
  }

  function buildSelectRows(customId, placeholder, options) {
    const select = new StringSelectMenuBuilder()
      .setCustomId(customId)
      .setPlaceholder(truncateComponentText(placeholder, 150))
      .setMinValues(1)
      .setMaxValues(1);

    for (const option of options.slice(0, 25)) {
      const builder = new StringSelectMenuOptionBuilder()
        .setLabel(truncateComponentText(option.label, 100))
        .setValue(truncateComponentText(option.value, 100));
      if (option.description) builder.setDescription(truncateComponentText(option.description, 100));
      if (option.emoji) builder.setEmoji(option.emoji);
      select.addOptions(builder);
    }

    return [new ActionRowBuilder().addComponents(select)];
  }

