  async function getResourceInteractionMember(interaction) {
    if (interaction.member?.roles?.cache) return interaction.member;
    return interaction.guild?.members?.fetch?.(interaction.user.id).catch(() => null) || null;
  }

  async function hasVerificationSupportAccess(memberOrInteraction) {
    const member = memberOrInteraction?.member || memberOrInteraction;
    const userId = memberOrInteraction?.user?.id || member?.id;
    if (!member && !userId) return false;
    if (member?.permissions?.has?.(PermissionFlagsBits.ManageThreads) || member?.permissions?.has?.(PermissionFlagsBits.Administrator)) {
      return true;
    }
    if (
      member?.roles?.cache?.has?.(VERIFICATION_THREAD_CONFIG.MANAGER_ROLE_ID) ||
      member?.roles?.cache?.has?.(VERIFICATION_THREAD_CONFIG.EXECUTIVE_BOARD_ROLE_ID)
    ) {
      return true;
    }
    const rankInfo = userId ? await getVerifiedMainRankForDiscord(userId).catch(() => null) : null;
    return Number(rankInfo?.rank || 0) >= VERIFICATION_THREAD_CONFIG.MANUAL_CREATE_MIN_RANK;
  }

  async function handleVerificationThreadButton(interaction) {
    if (!interaction.deferred && !interaction.replied) {
      if (!interaction.deferred && !interaction.replied) {
        await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});
      }
    }

    const parts = interaction.customId.split("_");
    const action = parts[1];
    const memberId = parts[2];
    const threadId = parts[3];
    const thread = await interaction.guild.channels.fetch(threadId).catch(() => null);
    if (!thread?.isThread?.() || !isVerificationThread(thread, memberId)) {
      return interaction.editReply("❌ I could not find that verification thread.");
    }

    if (action === "help") {
      if (interaction.user.id !== memberId) {
        return interaction.editReply("❌ This help button is only for the member assigned to this verification thread.");
      }

      const alertChannel = await interaction.guild.channels.fetch(VERIFICATION_THREAD_CONFIG.HELP_ALERT_CHANNEL_ID).catch(() => null);
      if (!alertChannel?.isTextBased?.()) {
        return interaction.editReply("❌ I could not reach the verification help alert channel. Please DM a Manager or Executive member.");
      }

      const alertEmbed = new EmbedBuilder()
        .setColor(0xffc107)
        .setTitle("Verification Help Requested")
        .setDescription(`<@${memberId}> needs help completing verification.`)
        .addFields(
          { name: "Verification Thread", value: `${thread}`, inline: true },
          { name: "Requested By", value: `${interaction.user.tag} (${interaction.user.id})`, inline: true },
        )
        .setTimestamp();

      await alertChannel.send({
        content: `<@&${VERIFICATION_THREAD_CONFIG.MANAGER_ROLE_ID}> <@&${VERIFICATION_THREAD_CONFIG.EXECUTIVE_BOARD_ROLE_ID}>`,
        embeds: [alertEmbed],
        components: [buildVerificationStaffButtons(memberId, thread.id)],
        allowedMentions: {
          roles: [
            VERIFICATION_THREAD_CONFIG.MANAGER_ROLE_ID,
            VERIFICATION_THREAD_CONFIG.EXECUTIVE_BOARD_ROLE_ID,
          ],
        },
      });

      await interaction.message.edit({
        components: [buildVerificationHelpButton(memberId, thread.id, true)],
      }).catch(() => {});

      await thread.send({
        content: "🛟 Help has been requested. A Manager or Executive member will join this thread shortly.",
        allowedMentions: { parse: [] },
      }).catch(() => {});

      return interaction.editReply("✅ Help request sent. A Manager or Executive member will join shortly.");
    }

    const hasAccess = await hasVerificationSupportAccess(interaction);
    if (!hasAccess) {
      return interaction.editReply("❌ Only Manager+ or Executive support staff may use this verification help action.");
    }

    if (action === "join") {
      await thread.setArchived(false).catch(() => {});
      await thread.setLocked(false).catch(() => {});
      await thread.members?.add?.(interaction.user.id).catch(() => {});
      await thread.send({
        content: `➕ ${interaction.user} joined to help with verification.`,
        allowedMentions: { users: [interaction.user.id] },
      }).catch(() => {});
      return interaction.editReply(`✅ You have been added to ${thread}.`);
    }

    if (action === "resolve") {
      await thread.send({
        content: `✅ Verification help request marked resolved by ${interaction.user}.`,
        allowedMentions: { users: [interaction.user.id] },
      }).catch(() => {});
      await interaction.message.edit({
        components: [buildVerificationStaffButtons(memberId, thread.id, true)],
      }).catch(() => {});
      return interaction.editReply("✅ Verification help request marked resolved.");
    }

    return interaction.editReply("❌ Unknown verification thread action.");
  }

