  // ---------- Data persistence helpers (from Bot 3) ----------
  const DATA_DIR = path.join(__dirname, 'data');
  if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });

  const INFRACTIONS_FILE = path.join(DATA_DIR, 'infractions.json');
  const CASES_FILE = path.join(DATA_DIR, 'cases.json');

  /**
   * Loads JSON data from a file, creating it with a fallback if it doesn't exist.
   * @param {string} filePath - The path to the JSON file.
   * @param {any} fallback - The default value to use if the file doesn't exist or is invalid.
   * @returns {any} The parsed JSON data.
   */
  function loadJson(filePath, fallback) {
    try {
      if (!fs.existsSync(filePath)) {
        fs.writeFileSync(filePath, JSON.stringify(fallback, null, 2));
        return JSON.parse(JSON.stringify(fallback)); // Return a deep copy
      }
      return JSON.parse(fs.readFileSync(filePath, 'utf8'));
    } catch (err) {
      console.error(`Failed to load JSON from ${filePath}:`, err);
      return JSON.parse(JSON.stringify(fallback));
    }
  }

  /**
   * Saves an object to a JSON file.
   * @param {string} filePath - The path to the JSON file.
   * @param {object} obj - The object to save.
   */
  function saveJson(filePath, obj) {
    try {
      fs.writeFileSync(filePath, JSON.stringify(obj, null, 2));
    } catch (err) {
      console.error(`Failed to save JSON to ${filePath}:`, err);
    }
  }

  const ARCHIVED_CHANNELS_FILE = path.join(DATA_DIR, 'archived_channels.json');
  let archivedChannelRecords = loadJson(ARCHIVED_CHANNELS_FILE, {});
  if (!archivedChannelRecords || typeof archivedChannelRecords !== "object" || Array.isArray(archivedChannelRecords)) {
    archivedChannelRecords = {};
    saveJson(ARCHIVED_CHANNELS_FILE, archivedChannelRecords);
  }

  function saveArchivedChannelRecords() {
    saveJson(ARCHIVED_CHANNELS_FILE, archivedChannelRecords);
  }

  function isArchiveCategoryId(categoryId) {
    return CHANNEL_ARCHIVE_CONFIG.CATEGORY_IDS.includes(String(categoryId || ""));
  }

  function serializePermissionOverwrites(channel) {
    return [...(channel.permissionOverwrites?.cache?.values?.() || [])].map(overwrite => ({
      id: overwrite.id,
      type: overwrite.type,
      allow: overwrite.allow?.bitfield?.toString?.() || "0",
      deny: overwrite.deny?.bitfield?.toString?.() || "0",
    }));
  }

  function buildArchivePermissionOverwrites(guild) {
    // Archived channels are locked to everyone; administrators still see them because the
    // Administrator permission bypasses channel overwrites. Deliberately no role lookups:
    // a deleted role id here used to throw "Supplied parameter is not a cached User or Role"
    // from PermissionOverwrites.resolve and abort the whole archive.
    const overwrites = [
      {
        id: guild.roles.everyone.id,
        deny: [PermissionFlagsBits.ViewChannel],
      },
    ];

    // The bot keeps access so it can post the archive notice and unarchive on request.
    const botMember = guild.members.me || guild.members.cache.get(client.user.id);
    if (botMember) {
      overwrites.push({
        id: botMember.id,
        allow: [
          PermissionFlagsBits.ViewChannel,
          PermissionFlagsBits.SendMessages,
          PermissionFlagsBits.ReadMessageHistory,
          PermissionFlagsBits.ManageChannels,
          PermissionFlagsBits.ManageThreads,
          PermissionFlagsBits.CreatePublicThreads,
        ],
      });
    }

    return overwrites;
  }

  async function chooseArchiveCategory(guild, currentParentId = null) {
    if (isArchiveCategoryId(currentParentId)) {
      const current = await guild.channels.fetch(currentParentId).catch(() => null);
      if (current) return current;
    }

    for (const categoryId of CHANNEL_ARCHIVE_CONFIG.CATEGORY_IDS) {
      const category = await guild.channels.fetch(categoryId).catch(() => null);
      if (!category || category.type !== ChannelType.GuildCategory) continue;
      const childCount = guild.channels.cache.filter(channel =>
        channel.parentId === category.id && !channel.isThread?.()
      ).size;
      if (childCount < CHANNEL_ARCHIVE_CONFIG.CATEGORY_LIMIT) return category;
    }
    return null;
  }

  function archiveNoticeContent({ archived, actorId, reason }) {
    return archived
      ? [
          "**Channel Archived**",
          "",
          `This channel was archived by <@${actorId}>.`,
          reason ? `**Reason:** ${reason}` : null,
          "",
          `Only <@&${CHANNEL_ARCHIVE_CONFIG.VIEW_ROLE_ID}> and the bot can view this channel while it is archived.`,
        ].filter(Boolean).join("\n")
      : [
          "**Channel Unarchived**",
          "",
          `This channel was unarchived by <@${actorId}>.`,
          reason ? `**Reason:** ${reason}` : null,
        ].filter(Boolean).join("\n");
  }

  async function postArchiveNotice(channel, { archived, actorId, reason }) {
    const content = archiveNoticeContent({ archived, actorId, reason });
    if (typeof channel.send === "function") {
      await channel.send({ content, allowedMentions: { users: [actorId], roles: [CHANNEL_ARCHIVE_CONFIG.VIEW_ROLE_ID] } }).catch(() => null);
      return;
    }

    if (channel.type === ChannelType.GuildForum && channel.threads?.create) {
      const noticeTag = channel.availableTags?.find(tag => /archiv|closed/i.test(tag.name)) ||
        channel.availableTags?.[0] ||
        null;
      const thread = await channel.threads.create({
        name: archived ? "Archived - Read Me" : "Unarchived - Read Me",
        appliedTags: noticeTag ? [noticeTag.id] : undefined,
        message: { content, allowedMentions: { users: [actorId], roles: [CHANNEL_ARCHIVE_CONFIG.VIEW_ROLE_ID] } },
        reason: archived ? "Archive notice" : "Unarchive notice",
      }).catch(() => null);
      if (thread?.setPinned) {
        await thread.setPinned(true, archived ? "Pinned archive notice" : "Pinned unarchive notice").catch(() => null);
      }
    }
  }

  async function requireArchiveRank(interaction) {
    const rankInfo = await getVerifiedMainRankForDiscord(interaction.user.id).catch(() => null);
    if (!rankInfo || !isExecutiveDirectorOrLeadershipRank(rankInfo.rank)) {
      return {
        ok: false,
        reason: `You must be verified as Director+ (rank ${SWEETSIEZ_STRUCTURE_CONFIG.EXECUTIVE_DIRECTOR_RANK}+) to use archive commands.`,
      };
    }
    return { ok: true, ...rankInfo };
  }

  async function archiveDiscordChannel(interaction) {
    const permission = await requireArchiveRank(interaction);
    if (!permission.ok) return interaction.editReply(`❌ ${permission.reason}`);

    const channel = interaction.options.getChannel("channel") || interaction.channel;
    const reason = interaction.options.getString("reason") || "No reason provided";
    if (!channel || !channel.guild || channel.guild.id !== interaction.guild.id) {
      return interaction.editReply("❌ I could not access that channel in this server.");
    }
    if (channel.type === ChannelType.GuildCategory) {
      return interaction.editReply("❌ Please choose a channel, not a category.");
    }

    const archiveCategory = await chooseArchiveCategory(interaction.guild, channel.parentId);
    if (!archiveCategory) {
      return interaction.editReply("❌ All archive categories appear to be full or unavailable.");
    }

    if (!archivedChannelRecords[channel.id]) {
      archivedChannelRecords[channel.id] = {
        channelId: channel.id,
        channelName: channel.name,
        originalParentId: channel.parentId || null,
        originalParentName: channel.parent?.name || null,
        originalOverwrites: serializePermissionOverwrites(channel),
        archivedBy: interaction.user.id,
        archivedAt: new Date().toISOString(),
        reason,
      };
      saveArchivedChannelRecords();
    }

    await channel.setParent(archiveCategory.id, {
      lockPermissions: false,
      reason: `Archived by ${interaction.user.tag}: ${reason}`,
    });
    await channel.permissionOverwrites.set(
      buildArchivePermissionOverwrites(interaction.guild),
      `Archived by ${interaction.user.tag}: ${reason}`,
    );
    await postArchiveNotice(channel, { archived: true, actorId: interaction.user.id, reason });

    await sendEventLog(interaction.guild, "Channel Archived", 0x8b5cf6, [
      { name: "Channel", value: `${channel} (${channel.id})`, inline: true },
      { name: "Archive Category", value: `${archiveCategory.name} (${archiveCategory.id})`, inline: true },
      { name: "Archived By", value: `${interaction.user.tag} (${interaction.user.id})`, inline: true },
      { name: "Reason", value: reason.slice(0, 1024), inline: false },
    ]).catch(() => null);

    return interaction.editReply(
      `✅ Archived ${channel} into **${archiveCategory.name}** and locked visibility to administrators only.`,
    );
  }

  async function unarchiveDiscordChannel(interaction) {
    const permission = await requireArchiveRank(interaction);
    if (!permission.ok) return interaction.editReply(`❌ ${permission.reason}`);

    const channel = interaction.options.getChannel("channel") || interaction.channel;
    const destination = interaction.options.getChannel("category");
    const reason = interaction.options.getString("reason") || "No reason provided";
    if (!channel || !channel.guild || channel.guild.id !== interaction.guild.id) {
      return interaction.editReply("❌ I could not access that channel in this server.");
    }

    const record = archivedChannelRecords[channel.id] || null;
    let destinationCategory = destination || null;
    if (!destinationCategory && record?.originalParentId) {
      destinationCategory = await interaction.guild.channels.fetch(record.originalParentId).catch(() => null);
    }

    if (!destinationCategory && !record) {
      return interaction.editReply(
        "❌ I do not have a saved original location for that older archived channel. Please choose a destination category.",
      );
    }
    if (destinationCategory && destinationCategory.type !== ChannelType.GuildCategory) {
      return interaction.editReply("❌ The destination must be a category.");
    }

    if (destinationCategory) {
      await channel.setParent(destinationCategory.id, {
        lockPermissions: !record,
        reason: `Unarchived by ${interaction.user.tag}: ${reason}`,
      });
    }

    if (record && Array.isArray(record.originalOverwrites)) {
      await channel.permissionOverwrites.set(
        record.originalOverwrites.map(overwrite => ({
          id: overwrite.id,
          type: overwrite.type,
          allow: BigInt(overwrite.allow || "0"),
          deny: BigInt(overwrite.deny || "0"),
        })),
        `Restored pre-archive permissions by ${interaction.user.tag}: ${reason}`,
      );
    } else if (destinationCategory) {
      await channel.lockPermissions().catch(() => null);
    }

    await postArchiveNotice(channel, { archived: false, actorId: interaction.user.id, reason });
    delete archivedChannelRecords[channel.id];
    saveArchivedChannelRecords();

    await sendEventLog(interaction.guild, "Channel Unarchived", 0x6bcf7f, [
      { name: "Channel", value: `${channel} (${channel.id})`, inline: true },
      { name: "Destination", value: destinationCategory ? `${destinationCategory.name} (${destinationCategory.id})` : "Original permissions restored only", inline: true },
      { name: "Unarchived By", value: `${interaction.user.tag} (${interaction.user.id})`, inline: true },
      { name: "Reason", value: reason.slice(0, 1024), inline: false },
    ]).catch(() => null);

    return interaction.editReply(
      `✅ Unarchived ${channel}${destinationCategory ? ` into **${destinationCategory.name}**` : ""}.`,
    );
  }

  let infractions = loadJson(INFRACTIONS_FILE, []); // Array of { id, userId, moderatorId, reason, timestamp }
  // Safety check: ensure infractions is always an array
  if (!Array.isArray(infractions)) {
    console.warn('⚠️ Infractions data was not an array, resetting to empty array');
    infractions = [];
    saveJson(INFRACTIONS_FILE, infractions);
  }
  let cases = loadJson(CASES_FILE, { nextCaseId: 1, records: [] }); // { nextCaseId, records: [] }
  // The counter used to be written as `lastCaseId` while the store was seeded
  // with `nextCaseId`. Migrate it, and derive it from the highest stored case id
  // so a reset or truncated counter can never hand out a duplicate case number.
  if (typeof cases.nextCaseId !== 'number' || cases.nextCaseId <= 0) {
    const highestKnownCaseId = Array.isArray(cases.records)
      ? cases.records.reduce((max, record) => Math.max(max, Number(record?.caseId) || 0), 0)
      : 0;
    cases.nextCaseId = Math.max(
      typeof cases.lastCaseId === 'number' ? cases.lastCaseId + 1 : 1,
      highestKnownCaseId + 1,
    );
  }
  if (Object.prototype.hasOwnProperty.call(cases, 'lastCaseId')) delete cases.lastCaseId;

  /**
   * Creates a new case record for a moderation action.
   * @param {string} action - The type of moderation action (e.g., 'Warn', 'Kick', 'Ban').
   * @param {string} moderatorId - The ID of the moderator who performed the action.
   * @param {string} targetUserId - The ID of the user targeted by the action.
   * @param {string} reason - The reason for the action.
   * @param {object} [extra={}] - Additional data to store with the case.
   * @returns {object} The created case record.
   */
  function nextCase(action, moderatorId, targetUserId, reason, extra = {}) {
    if (typeof cases.nextCaseId !== 'number' || cases.nextCaseId <= 0) cases.nextCaseId = 1;
    const caseId = cases.nextCaseId;
    cases.nextCaseId += 1;
    const record = {
      caseId,
      action,
      moderatorId,
      targetUserId,
      reason,
      timestamp: new Date().toISOString(),
      extra
    };
    cases.records.push(record);
    saveJson(CASES_FILE, cases);
    return record;
  }

  function getSupportBlacklistStatus(userId) {
    const records = cases.records
      .filter(record =>
        record.targetUserId === userId &&
        (record.action === 'SupportBlacklist' || record.action === 'SupportBlacklistRemove')
      )
      .sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));

    const latest = records[records.length - 1];
    return {
      isBlacklisted: latest?.action === 'SupportBlacklist' && !latest.extra?.revokedAt,
      latest,
    };
  }

  async function logSupportBlacklistAction(guild, title, color, fields) {
    const logChannel = config.TICKET_LOG_CHANNEL_ID
      ? await guild.channels.fetch(config.TICKET_LOG_CHANNEL_ID).catch(() => null)
      : null;

    if (!logChannel) return;

    const embed = new EmbedBuilder()
      .setTitle(title)
      .setColor(color)
      .addFields(fields)
      .setTimestamp();

    await logChannel.send({ embeds: [embed] }).catch(console.error);
  }


  /**
   * Formats a duration in milliseconds into a human-readable string (days, hours, minutes).
   * @param {number} ms - The duration in milliseconds.
   * @returns {string} The formatted duration string.
   */
  function formatDuration(ms) {
    const days = Math.floor(ms / (1000 * 60 * 60 * 24));
    const hours = Math.floor((ms % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    const minutes = Math.floor((ms % (1000 * 60 * 60)) / (1000 * 60));

    let parts = [];
    if (days > 0) parts.push(`${days} day${days > 1 ? 's' : ''}`);
    if (hours > 0) parts.push(`${hours} hour${hours > 1 ? 's' : ''}`);
    if (minutes > 0) parts.push(`${minutes} minute${minutes > 1 ? 's' : ''}`);

    return parts.length > 0 ? parts.join(', ') : 'less than a minute';
  }

  /**
   * Generates a unique acknowledgement code for a case.
   * @param {number} caseId - The ID of the case.
   * @returns {string} The generated acknowledgement code.
   */
  function generateAckCode(caseId) {
    const randomPart = Math.random().toString(36).substring(2, 6).toUpperCase();
    return `ACK-${caseId}-${randomPart}`;
  }

  /**
   * Updates the 'extra' field of a case record.
   * @param {object} record - The case record to update.
   * @param {object} updates - An object containing key-value pairs to merge into 'extra'.
   */
  function updateCaseExtra(record, updates) {
    record.extra = { ...(record.extra || {}), ...updates };
    saveJson(CASES_FILE, cases);
  }

  /**
   * Attempts to close an acknowledgement thread associated with a case.
   * @param {import('discord.js').Guild} guild - The guild where the thread is located.
   * @param {number} caseId - The ID of the case.
   */
  async function closeAcknowledgementThread(guild, caseId) {
    if (!config.RULES_CHANNEL_ID) return;
    try {
      const rulesChannel = await guild.channels.fetch(config.RULES_CHANNEL_ID).catch(() => null);
      if (!rulesChannel || !rulesChannel.threads) return;
      const threads = await rulesChannel.threads.fetch();
      const targetThread = threads.threads.find(t => t.name.includes(`Case ${caseId}`));
      if (targetThread) {
        await targetThread.delete().catch(() => { });
      }
    } catch (err) {
      console.error('Failed to close acknowledgement thread:', err);
    }
  }

  /**
   * Creates a private thread in the configured RULES_CHANNEL_ID and adds only the punished user.
   * This thread serves as an acknowledgement mechanism.
   * @param {object} options - Options for creating the thread.
   * @param {import('discord.js').Guild} options.guild - The guild where the thread is created.
   * @param {import('discord.js').User} options.user - The user to add to the thread.
   * @param {string} options.title - The title of the embed in the thread.
   * @param {string} options.description - The description for the embed (explaining the action).
   * @param {number} options.caseId - The case ID associated with the action.
   * @param {string} options.actionType - The type of moderation action (e.g., 'Warn', 'Timeout').
   * @param {string} options.ackCode - The acknowledgement code the user must DM to the bot.
   * @param {boolean} [options.ackRemovesTimeout=false] - Whether acknowledging removes a timeout.
   * @returns {Promise<import('discord.js').ThreadChannel|null>} The created thread channel, or null if creation failed.
   */
  async function createAcknowledgementThread({ guild, user, title, description, caseId, actionType, ackCode, ackRemovesTimeout = false }) {
    if (!config.RULES_CHANNEL_ID) {
      console.warn('RULES_CHANNEL_ID not set; cannot create acknowledgement thread.');
      await sendEventLog(guild, '❌ No Rules Channel for Ack', 0xffa500, [
        { name: 'User ID', value: user.id, inline: false },
        { name: 'Action', value: actionType, inline: false },
        { name: 'Error', value: 'RULES_CHANNEL_ID not configured', inline: false }
      ]).catch(console.error);
      return null;
    }
    try {
      const rulesChannel = await guild.channels.fetch(config.RULES_CHANNEL_ID).catch(() => null);
      if (!rulesChannel) {
        console.warn(`Rules channel with ID ${config.RULES_CHANNEL_ID} not found or bot lacks access.`);
        await sendEventLog(guild, '❌ Rules Channel Access Error', 0xffa500, [
          { name: 'User ID', value: user.id, inline: false },
          { name: 'Action', value: actionType, inline: false },
          { name: 'Error', value: 'Rules channel not found or bot lacks access', inline: false }
        ]).catch(console.error);
        return null;
      }

      // Send a message to start the thread, then delete it to keep channel clean
      const starter = await rulesChannel.send({ content: `<@${user.id}>` });

      const thread = await starter.startThread({
        name: `${actionType} • Case ${caseId}`,
        autoArchiveDuration: 60,
        type: ChannelType.PrivateThread,
        invitable: false // Ensure only added members can see/join
      });

      await starter.delete().catch(() => { }); // Delete starter message
      await thread.members.add(user.id).catch(() => { }); // Add the targeted user to the private thread

      const actionLabel = actionType.toLowerCase() === 'warn'
        ? 'warning'
        : actionType.toLowerCase() === 'timeout'
          ? 'timeout'
          : actionType.toLowerCase();

      const ackInstruction = `To acknowledge your ${actionLabel}, DM me the following code: \`${ackCode}\`.`;
      const ackNote = actionLabel === 'timeout' && ackRemovesTimeout
        ? 'Acknowledging will **remove** your timeout.'
        : (actionLabel === 'timeout' && !ackRemovesTimeout
          ? 'Acknowledging will **not** remove your timeout.'
          : '');

      const embedDescription = `${description}\n\n**How to Acknowledge:**\n${ackInstruction}${ackNote ? `\n${ackNote}` : ''}`.trim();

      const embed = new EmbedBuilder()
        .setTitle(title)
        .setDescription(embedDescription)
        .addFields(
          { name: 'Case ID', value: `${caseId}`, inline: true },
          { name: 'Action', value: actionType, inline: true }
        )
        .setTimestamp();

      await thread.send({ embeds: [embed] }).catch(console.error);

      return thread;
    } catch (err) {
      console.error('Failed to create acknowledgement thread:', err);
      await sendEventLog(guild, '❌ Create Ack Thread Error', 0xff0000, [
        { name: 'User ID', value: user.id, inline: false },
        { name: 'Action', value: actionType, inline: false },
        { name: 'Error', value: err.message?.substring(0, 1024) || 'No message', inline: false },
        { name: 'Stack', value: err.stack?.substring(0, 1024) || 'No stack', inline: false }
      ]).catch(console.error);
      return null;
    }
  }

  // Warning helpers
  /**
   * Adds a warning to a user.
   * @param {string} userId - The ID of the user to warn.
   * @param {string} moderatorId - The ID of the moderator who issued the warning.
   * @param {string} reason - The reason for the warning.
   * @returns {object} The created warning object.
   */
  function addWarning(userId, moderatorId, reason) {
    const id = infractions.length ? Math.max(...infractions.map(w => w.id)) + 1 : 1;
    const warning = { id, userId, moderatorId, reason: reason || 'No reason', timestamp: new Date().toISOString() };
    infractions.push(warning);
    saveJson(INFRACTIONS_FILE, infractions);
    return warning;
  }

  /**
   * Retrieves all warnings for a given user.
   * @param {string} userId - The ID of the user.
   * @returns {Array<object>} An array of warning objects.
   */
  function getWarningsFor(userId) {
    return infractions.filter(w => w.userId === userId);
  }

  /**
   * Clears all warnings for a given user.
   * @param {string} userId - The ID of the user whose warnings to clear.
   * @returns {number} The number of warnings removed.
   */
  function clearWarningsFor(userId) {
    const before = infractions.length;
    infractions = infractions.filter(w => w.userId !== userId);
    saveJson(INFRACTIONS_FILE, infractions);
    return before - infractions.length;
  }

  /**
   * Removes a specific warning for a given user by its ID.
   * @param {string} userId - The ID of the user whose warning to remove.
   * @param {number} warningId - The ID of the specific warning to remove.
   * @returns {boolean} True if the warning was found and removed, false otherwise.
   */
  function removeWarning(userId, warningId) {
    const initialLength = infractions.length;
    infractions = infractions.filter(w => !(w.userId === userId && w.id === warningId));
    saveJson(INFRACTIONS_FILE, infractions);
    return infractions.length < initialLength;
  }


  // ---------- Permission helpers (from Bot 3) ----------
  /**
   * Gets a numeric moderation level for a member based on their roles.
   * Higher number means higher privilege.
   * Updated to allow multiple role IDs per level.
   * @param {import('discord.js').GuildMember} member - The member to check.
   * @returns {number} The moderation level (0-5).
   */
  function getMemberLevel(member) {
    if (!member || !member.roles) return 0;
    const r = config;

    // Helper to check if a member has any of the roles in a given array
    const hasAnyRole = (roleIds) => {
      if (!Array.isArray(roleIds) || roleIds.length === 0) return false;
      return roleIds.some(roleId => member.roles.cache.has(roleId));
    };

    // Ordered from highest to lowest privilege level
    if (hasAnyRole(r.ROLE_EXECUTIVE_ASSISTANT_MOD)) return 5;
    if (hasAnyRole(r.ROLE_ASSISTANT_MANAGER)) return 4;
    if (hasAnyRole(r.ROLE_SUPERVISOR)) return 3;
    if (hasAnyRole(r.ROLE_ASSISTANT_SUPERVISOR)) return 2;
    if (hasAnyRole(r.ROLE_STAFF_ASSISTANT)) return 1;
    return 0;
  }

  /**
   * Checks if an issuer member can moderate a target member based on role hierarchy and minimum level.
   * @param {import('discord.js').GuildMember} issuerMember - The member initiating the moderation action.
   * @param {import('discord.js').GuildMember|null} targetMember - The member being moderated (can be null for commands like purge).
   * @param {number} minLevelRequired - The minimum `getMemberLevel` required for the issuer.
   * @returns {{ok: boolean, reason?: string}} Result of the permission check.
   */
  function checkCanModerate(issuerMember, targetMember, minLevelRequired) {
    if (!issuerMember) return { ok: false, reason: 'no_issuer' };
    // Guild owner can do anything
    if (issuerMember.guild && issuerMember.guild.ownerId === issuerMember.id) return { ok: true };

    const issuerLevel = getMemberLevel(issuerMember);
    if (issuerLevel < minLevelRequired) return { ok: false, reason: 'insufficient_level' };

    // Cannot moderate someone with equal or higher role hierarchy
    if (targetMember && issuerMember.roles.highest.position <= targetMember.roles.highest.position) {
      return { ok: false, reason: 'role_hierarchy' };
    }
    return { ok: true };
  }

  // ---------- Helper: mod log and event log (from Bot 3, consolidated for tickets) ----------
  /**
   * Sends a moderation action log to the configured log channel.
   * @param {import('discord.js').Guild} guild - The guild where the action occurred.
   * @param {object} record - The case record.
   */
  async function sendModLog(guild, record) {
    // Always console log as a primary fallback/source for critical errors
    console.error(`[MOD LOG] Action: ${record.action}, Target: ${record.targetUserId}, Reason: ${record.reason}`);

    if (!config.MOD_LOG_CHANNEL_ID || !client.isReady()) { // Ensure client is ready to prevent errors during startup/shutdown
      console.warn(`WARN: MOD_LOG_CHANNEL_ID not set or client not ready. Mod log "${record.action}" will only be consoled.`);
      return;
    }
    try {
      const ch = await guild?.channels.fetch(config.MOD_LOG_CHANNEL_ID).catch(() => null);
      if (!ch) {
        console.error(`ERROR: Mod log channel with ID ${config.MOD_LOG_CHANNEL_ID} not found or bot lacks access. Mod log "${record.action}" will only be consoled.`);
        return;
      }
      const embed = new EmbedBuilder()
        .setTitle(`🛡️ Mod Action: ${record.action}`)
        .addFields(
          { name: 'Case ID', value: `${record.caseId}`, inline: true },
          { name: 'Moderator', value: `<@${record.moderatorId}>`, inline: true },
          { name: 'Target', value: `<@${record.targetUserId}>`, inline: true },
          { name: 'Reason', value: record.reason, inline: false }
        )
        .setTimestamp(new Date(record.timestamp))
        .setColor(record.color || 0xff9900); // Default color for mod actions
      if (record.extra) {
        Object.entries(record.extra).forEach(([k, v]) => {
          // Ensure value is a string and truncate if necessary
          const valueString = String(v);
          embed.addFields({ name: String(k), value: valueString.substring(0, 1024), inline: true });
        });
      }
      await ch.send({ embeds: [embed] });
    } catch (err) {
      console.error('Failed to send mod log to Discord channel:', err);
    }
  }

  /**
   * Sends a general event log to the configured log channel.
   * This function is also used for critical error logging where a specific guild context might not be available.
   * @param {import('discord.js').Guild|null} guild - The guild where the event occurred, or null for global events.
   * @param {string} title - The title of the log entry.
   * @param {import('discord.js').ColorResolvable} color - The color for the embed.
   * @param {Array<object>} fields - An array of field objects for the embed.
   */
  async function sendEventLog(guild, title, color, fields) {
    // Always log to console as a primary fallback/source for critical errors
    console.error(`[EVENT LOG] ${title}: ${fields.map(f => `${f.name}: ${f.value}`).join(', ')}`);

    if (!config.MOD_LOG_CHANNEL_ID || !client.isReady()) { // Ensure client is ready to prevent errors during startup/shutdown
      console.warn(`WARN: MOD_LOG_CHANNEL_ID not set or client not ready. Event log "${title}" will only be consoled.`);
      return;
    }
    try {
      const ch = await client.channels.fetch(config.MOD_LOG_CHANNEL_ID).catch(() => null); // Fetch directly from client if guild is null
      if (!ch) {
        console.error(`ERROR: Event log channel with ID ${config.MOD_LOG_CHANNEL_ID} not found or bot lacks access. Event log "${title}" will only be consoled.`);
        return;
      }
      const embed = new EmbedBuilder()
        .setTitle(title)
        .setColor(color)
        .setTimestamp();
      if (fields && Array.isArray(fields)) {
        fields.forEach(f => {
          // Ensure value is a string and truncate if necessary
          const valueString = String(f.value);
          embed.addFields({ name: String(f.name), value: valueString.substring(0, 1024), inline: f.inline });
        });
      }
      await ch.send({ embeds: [embed] });
    } catch (err) {
      console.error('Failed to send event log to Discord channel:', err);
    }
  }


  // ---------- APPLICATION SYSTEM FUNCTIONS (from Bot 1) ----------

  /**
   * Clears messages sent by the bot in a specific channel.
   * This function handles bulk deletion for recent messages (under 14 days)
   * and individual deletion for older messages.
   * @param {string} channelId - The ID of the channel to clear messages from.
   */
  async function clearBotMessages(channelId) {
    if (!channelId) return;
    try {
      const channel = await client.channels.fetch(channelId).catch(() => null);
      if (channel && channel.isTextBased()) { // Ensure it's a text-based channel
        console.log(`Attempting to clear bot messages in channel ${channel.name} (${channel.id})...`);
        let messages;
        let deletedCount = 0;
        const twoWeeksAgo = Date.now() - 14 * 24 * 60 * 60 * 1000;

        // Fetch messages in batches until no more bot messages are found
        do {
          messages = await channel.messages.fetch({ limit: 100, cache: false });
          const botMessages = messages.filter(m => m.author.id === client.user.id);

          if (botMessages.size > 0) {
            const deletableMessages = botMessages.filter(m => m.createdTimestamp > twoWeeksAgo);
            const undeletableMessages = botMessages.filter(m => m.createdTimestamp <= twoWeeksAgo);

            if (deletableMessages.size > 0) {
              // Bulk delete messages younger than 14 days
              await channel.bulkDelete(deletableMessages, true);
              deletedCount += deletableMessages.size;
              console.log(`Bulk deleted ${deletableMessages.size} recent bot messages in ${channel.name}.`);
            }

            if (undeletableMessages.size > 0) {
              // Delete older messages one by one
              for (const msg of undeletableMessages.values()) {
                await msg.delete().catch(err => console.error(`Failed to delete old bot message ${msg.id} in ${channel.name}:`, err));
                deletedCount++;
              }
              console.log(`Deleted ${undeletableMessages.size} old bot messages individually in ${channel.name}.`);
            }
          } else {
            // No bot messages found in this batch, stop fetching
            break;
          }
        } while (messages.size > 0); // Continue if there might be more messages to fetch

        console.log(`Successfully cleared a total of ${deletedCount} bot messages from ${channel.name} (${channel.id}).`);
      } else if (channel) {
        console.warn(`Channel with ID ${channelId} is not a text-based channel or cannot be accessed; skipping message clearing.`);
      } else {
        console.warn(`Channel with ID ${channelId} not found for clearing messages.`);
      }
    } catch (error) {
      console.error(`ERROR clearing messages in channel ${channelId}:`, error);
      await sendEventLog(null, '❌ Clear Bot Messages Error', 0xffa500, [
        { name: 'Channel ID', value: channelId, inline: false },
        { name: 'Error', value: error.message?.substring(0, 1024) || 'No message', inline: false },
        { name: 'Stack', value: error.stack?.substring(0, 1024) || 'No stack', inline: false }
      ]).catch(console.error);
    }
  }


