  /**
   * Asks the current application question to the user in DMs.
   * @param {import('discord.js').DMChannel} channel - The DM channel with the user.
   * @param {object} session - The current application session.
   */
  async function askQuestion(channel, session) {
    const question = session.questions[session.currentQuestion];

    const questionEmbed = new EmbedBuilder()
      .setColor(session.type === 'as' ? '#FFC0CB' : '#FFD700')
      .setTitle(`Question ${session.currentQuestion + 1}/${session.questions.length}`)
      .setDescription(question.question);

    if (question.type === 'scale') {
      questionEmbed.setFooter({ text: `Please respond with a number between ${question.min} and ${question.max}` });
    } else if (question.type === 'choice') {
      questionEmbed.addFields({
        name: 'Options',
        value: question.choices.map((c, i) => `${i + 1}. ${c}`).join('\n')
      });
      questionEmbed.setFooter({ text: 'Please respond with the number of your choice' });
    } else if (question.type === 'confirm') {
      questionEmbed.setFooter({ text: 'Please respond with "yes" or "no"' });
    } else {
      questionEmbed.setFooter({ text: 'Please provide a detailed response (3+ sentences recommended)' });
    }

    await channel.send({ embeds: [questionEmbed] }).catch(err => {
      console.error(`Error sending question to DM for user ${session.userId}:`, err);
      sendEventLog(null, '❌ DM Question Error', 0xffa500, [
        { name: 'User ID', value: session.userId, inline: false },
        { name: 'Question Index', value: session.currentQuestion, inline: false },
        { name: 'Error', value: err.message?.substring(0, 1024) || 'No message', inline: false },
      ]).catch(console.error);
    });
  }

  /**
   * Submits the completed application to the designated review channel.
   * @param {import('discord.js').DMChannel} channel - The DM channel with the user.
   * @param {object} session - The completed application session.
   */
  async function submitApplication(channel, session) {
    const submitEmbed = new EmbedBuilder()
      .setColor('#00FF00')
      .setTitle('✅ Application Submitted!')
      .setDescription('Thank you for applying! Your application has been submitted for review. You will be notified of the results soon.\n\nGood luck! 🍀')
      .setFooter({ text: 'Sweetsiez Applications' });

    await channel.send({ embeds: [submitEmbed] }).catch(err => {
      console.error(`Error sending submission confirmation to DM for user ${session.userId}:`, err);
      sendEventLog(null, '❌ DM Confirmation Error', 0xffa500, [
        { name: 'User ID', value: session.userId, inline: false },
        { name: 'Error', value: err.message?.substring(0, 1024) || 'No message', inline: false },
      ]).catch(console.error);
    });

    // Send to appropriate review channel based on application type
    const reviewChannelId = session.type === 'as' ? config.AS_REVIEW_CHANNEL_ID : session.type === 'ea' ? config.EA_REVIEW_CHANNEL_ID : config.MOD_REVIEW_CHANNEL_ID;
    const reviewRoleId = session.type === 'as' ? config.AS_REVIEW_ROLE_ID : session.type === 'ea' ? config.EA_REVIEW_ROLE_ID : config.MOD_REVIEW_ROLE_ID;

    if (!reviewChannelId) {
      console.error(`ERROR: Review channel ID not set for ${session.type} applications. Application will not be forwarded to staff.`);
      await sendEventLog(null, '❌ Review Channel Missing', 0xffa500, [
        { name: 'Application Type', value: session.type, inline: false },
        { name: 'User ID', value: session.userId, inline: false },
        { name: 'Error', value: 'Review channel ID not configured', inline: false }
      ]).catch(console.error);
      return;
    }
    const reviewChannel = await client.channels.fetch(reviewChannelId).catch(() => null);

    if (!reviewChannel) {
      console.error(`ERROR: Review channel with ID ${reviewChannelId} not found or bot lacks access for ${session.type} applications. Application will not be forwarded to staff.`);
      await sendEventLog(null, '❌ Review Channel Access Error', 0xffa500, [
        { name: 'Application Type', value: session.type, inline: false },
        { name: 'Channel ID', value: reviewChannelId, inline: false },
        { name: 'User ID', value: session.userId, inline: false },
        { name: 'Error', value: 'Review channel not found or bot lacks access', inline: false }
      ]).catch(console.error);
      return;
    }

    const reviewEmbed = new EmbedBuilder()
      .setColor(session.type === 'as' ? '#FFC0CB' : '#FFD700')
      .setTitle(`${session.type === 'as' ? '🍰 Assistant Supervisor' : '⭐ Executive Intern'} Application`)
      .setDescription(`**Applicant:** ${session.username} (<@${session.userId}>)\n**User ID:** ${session.userId}`)
      .setTimestamp();

    for (const question of session.questions) {
      const answer = session.answers[question.id];
      let fieldName = question.question.substring(0, 100);
      if (fieldName.length === 100) fieldName += '...';

      reviewEmbed.addFields({
        name: fieldName,
        value: answer.toString().substring(0, 1024),
        inline: false
      });
    }

    // Add Approve/Fail buttons for review
    const reviewButtons = new ActionRowBuilder()
      .addComponents(
        new ButtonBuilder()
          .setCustomId(`approve_app_${session.userId}_${session.type}`)
          .setLabel('Approve')
          .setEmoji('✅')
          .setStyle(ButtonStyle.Success),
        new ButtonBuilder()
          .setCustomId(`fail_app_${session.userId}_${session.type}`)
          .setLabel('Fail')
          .setEmoji('❎')
          .setStyle(ButtonStyle.Danger)
      );

    await reviewChannel.send({
      content: reviewRoleId ? `<@&${reviewRoleId}> New application submitted!` : 'New application submitted!',
      embeds: [reviewEmbed],
      components: [reviewButtons] // Add the buttons here
    }).catch(err => {
      console.error(`Error sending application to review channel ${reviewChannelId}:`, err);
      sendEventLog(reviewChannel.guild, '❌ Send Application to Review Error', 0xffa500, [
        { name: 'Application Type', value: session.type, inline: false },
        { name: 'Channel ID', value: reviewChannelId, inline: false },
        { name: 'User ID', value: session.userId, inline: false },
        { name: 'Error', value: err.message?.substring(0, 1024) || 'No message', inline: false },
      ]).catch(console.error);
    });
  }

  /**
   * Handles the approval or failure of an application.
   * Updates the review message, DMs the applicant, and assigns roles if approved.
   * @param {import('discord.js').ButtonInteraction} interaction - The button interaction.
   * @param {boolean} isApproved - True if the application is approved, false if failed.
   */
  async function handleApplicationReview(interaction, isApproved) {
    // Parse applicant ID and application type from the customId
    // CustomId format: `(approve|fail)_app_${applicantId}_${applicationType}`
    const parts = interaction.customId.split('_');
    const applicantId = parts[2];
    const applicationType = parts[3]; // 'as' or 'ea'

    const guild = interaction.guild;
    const reviewer = interaction.member;

    // 1. Permission Check: Only staff with review roles or admin can approve/fail
    const requiredReviewRoleId = applicationType === 'as' ? config.AS_REVIEW_ROLE_ID : config.EA_REVIEW_ROLE_ID;
    const hasPermission = reviewer.permissions.has(PermissionFlagsBits.Administrator) ||
      reviewer.roles.cache.has(requiredReviewRoleId) ||
      reviewer.roles.cache.has(config.OVERSEER_ROLE_ID);

    if (!hasPermission) {
      await interaction.followUp({ content: '❌ You do not have permission to review applications.', ephemeral: true });
      return;
    }

    try {
      const applicantUser = await client.users.fetch(applicantId).catch(() => null);
      const applicantMember = await guild.members.fetch(applicantId).catch(() => null);

      // If applicant user is not found, cannot DM them.
      if (!applicantUser) {
        await interaction.followUp({ content: '❌ Could not find the applicant user (they might have left the server). Review action recorded, but DM could not be sent.', ephemeral: true });
        // Continue to update review message and log, but skip DM/role.
      }

      const statusText = isApproved ? 'Approved' : 'Denied'; // Changed 'Failed' to 'Denied' for consistency
      const color = isApproved ? 0x00FF00 : 0xFF0000;
      const emoji = isApproved ? '✅' : '❌';

      // 2. Update Review Message to reflect the decision and disable buttons
      const originalEmbed = interaction.message.embeds[0];
      const updatedEmbed = EmbedBuilder.from(originalEmbed)
        .setTitle(`${originalEmbed.title} (${statusText})`) // Title changes to include (Approved) or (Denied)
        .setColor(color)
        .addFields({ name: 'Review Status', value: `${emoji} ${statusText} by <@${reviewer.id}> at ${new Date().toLocaleString()}`, inline: false })
        .setFooter({ text: originalEmbed.footer?.text || 'Sweetsiez Applications' })
        .setTimestamp();

      // Edit the original message to update the embed and remove buttons
      await interaction.message.edit({ embeds: [updatedEmbed], components: [] }).catch(err => {
        console.error(`Failed to update review message ${interaction.message.id}:`, err);
        sendEventLog(guild, '❌ Update Review Message Error', 0xffa500, [
          { name: 'Review Message ID', value: interaction.message.id, inline: false },
          { name: 'Decision', value: statusText, inline: false },
          { name: 'Error', value: err.message?.substring(0, 1024) || 'No message', inline: false }
        ]).catch(console.error);
      });

      // 3. DM Applicant Notification
      if (applicantUser) {
        const applicationTitle = applicationType === 'as' ? 'Assistant Supervisor' : 'Executive Intern';

        const dmEmbed = new EmbedBuilder()
          .setTitle(`Your ${applicationTitle} Application`)
          .setColor(color)
          .setDescription(isApproved
            ? `Good news! Your application for ${applicationTitle} at Sweetsiez has been **Approved!** We're excited to have you join the team. Further instructions will be provided shortly.`
            : `We regret to inform you that your application for ${applicationTitle} at Sweetsiez has been **Denied.** You may re-apply for this position in 3 days.`
          )
          .setTimestamp();

        await applicantUser.send({ embeds: [dmEmbed] }).catch(err => {
          console.warn(`Failed to DM applicant ${applicantId} with ${statusText} notification:`, err);
          sendEventLog(guild, '❌ DM Applicant Notification Error', 0xffa500, [
            { name: 'Applicant ID', value: applicantId, inline: false },
            { name: 'Application Type', value: applicationType, inline: false },
            { name: 'Decision', value: statusText, inline: false },
            { name: 'Error', value: err.message?.substring(0, 1024) || 'No message', inline: false }
          ]).catch(console.error);
        });
      }

      // 4. Handle Denial Recording (removed cooldown feature)
      if (!isApproved) {
        // Cooldown feature removed - denial is simply logged
        await interaction.followUp({ content: `✅ Application denied for <@${applicantId}>.`, ephemeral: true }).catch(console.error);
      } else {
        await interaction.followUp({ content: `✅ Application for <@${applicantId}> approved. No role assigned per current configuration.`, ephemeral: true }).catch(console.error);
      }

      // 5. Log the action to Mod Log
      const caseRecord = nextCase(
        isApproved ? 'ApplicationApproved' : 'ApplicationDenied', // Changed action name for denial
        reviewer.id,
        applicantId,
        `${applicationType.toUpperCase()} Application ${statusText} by ${reviewer.user.tag}`
      );
      await sendModLog(guild, {
        ...caseRecord,
        color: color,
        extra: { ApplicationType: applicationType.toUpperCase() }
      });

      // Acknowledge the interaction to the user by sending an ephemeral followUp
      // This is important if `interaction.message.edit` doesn't implicitly acknowledge sufficiently
      // We moved the approval/denial message to the conditional blocks above.
      // So, this general acknowledgment is not strictly needed anymore, or can be a generic success.
      // await interaction.followUp({ content: `${emoji} Application for <@${applicantId}> ${statusText}.`, ephemeral: true }).catch(console.error);

    } catch (error) {
      console.error(`ERROR in handleApplicationReview for applicant ${applicantId}, type ${applicationType}:`, error);
      // Attempt to send a follow-up if interaction wasn't replied yet, to prevent 'Interaction Failed'
      if (!interaction.replied && !interaction.deferred) { // Check if no initial reply/deferral has happened
        await interaction.reply({ content: '❌ An unexpected error occurred while processing your request.', ephemeral: true }).catch(console.error);
      } else {
        await interaction.followUp({ content: '❌ An unexpected error occurred while processing your request.', ephemeral: true }).catch(console.error);
      }
      await sendEventLog(guild, '❌ Application Review Critical Error', 0xff0000, [
        { name: 'Applicant ID', value: applicantId, inline: false },
        { name: 'Application Type', value: applicationType, inline: false },
        { name: 'Decision Attempted', value: isApproved ? 'Approve' : 'Deny', inline: false }, // Changed
        { name: 'Error', value: error.message?.substring(0, 1024) || 'No message', inline: false },
        { name: 'Stack', value: error.stack?.substring(0, 1024) || 'No stack', inline: false }
      ]).catch(console.error);
    }
  }


