  /**
   * Creates a new ticket thread when a user clicks a ticket category button.
   * @param {import('discord.js').ButtonInteraction} interaction - The button interaction.
   * @param {string} categoryKey - The key of the selected ticket category.
   */
  async function createTicket(interaction, categoryKey) {
    const category = TICKET_CATEGORIES[categoryKey];
    if (!category) {
      await interaction.followUp({ content: '❌ Invalid ticket category selected.', ephemeral: true }).catch(console.error);
      return;
    }

    const guild = interaction.guild;
    const userId = interaction.user.id;
    const channel = interaction.channel;

    const blacklistStatus = getSupportBlacklistStatus(userId);
    if (blacklistStatus.isBlacklisted) {
      await interaction.followUp({
        content: `❌ You are currently blacklisted from using the Sweetsiez Support System. Case ${blacklistStatus.latest.caseId}.`,
        ephemeral: true
      }).catch(console.error);
      return;
    }

    // Check if user is verified (except for discord support)
    if (categoryKey !== 'discord') {
      const isVerified = verifiedUsers.has(userId);
      if (!isVerified) {
        await interaction.followUp({
          content: '❌ You must be verified to open this type of ticket. Please use `/verify` first, or open a General Support ticket if you need help with verification.',
          ephemeral: true
        }).catch(console.error);
        return;
      }
    }

    // Check if user already has an active ticket of this type
    const existingTicket = [...activeTickets.values()].find(
      t => t.userId === userId && t.category === categoryKey && !t.closed
    );

    if (existingTicket) {
      const existingThread = await guild.channels.fetch(existingTicket.threadId).catch(() => null);
      if (existingThread) {
        await interaction.followUp({
          content: `⚠️ You already have an active **${category.name}** ticket: ${existingThread.toString()}. Please use that one or close it before opening a new one.`,
          ephemeral: true
        }).catch(console.error);
        return;
      } else {
        // Clean up stale ticket record if thread doesn't exist
        activeTickets.delete(existingTicket.threadId);
        await Ticket.updateOne(
          { threadId: existingTicket.threadId },
          { $set: { closed: true } }
        ).catch(error => console.error('Error closing stale ticket record:', error.message));
      }
    }

    try {
      const threadName = `${category.emoji} ${category.name} - ${interaction.user.username}`;
      const thread = await channel.threads.create({
        name: threadName,
        type: ChannelType.PrivateThread,
        reason: `New ticket for ${interaction.user.tag} (${category.name})`,
        invitable: false
      }).catch(async (err) => {
        console.error('Failed to create private thread:', err);
        if (err.code === 50035 || err.code === 50013) {
          console.warn('Falling back to public thread creation due to permissions/restrictions.');
          return await channel.threads.create({
            name: threadName,
            type: ChannelType.PublicThread,
            reason: `New ticket for ${interaction.user.tag} (${category.name})`,
          });
        }
        throw err;
      });

      await thread.members.add(userId).catch(err => console.error(`Failed to add user ${userId} to thread ${thread.id}:`, err));

      // if (category.roleId) {
      //     await thread.members.add(category.roleId).catch(err => console.error(`Failed to add role ${category.roleId} to thread ${thread.id}:`, err));
      // }

      // if (config.OVERSEER_ROLE_ID) {
      //     await thread.members.add(config.OVERSEER_ROLE_ID).catch(err => console.error(`Failed to add overseer role ${config.OVERSEER_ROLE_ID} to thread ${thread.id}:`, err));
      // }

      const initialThreadEmbed = new EmbedBuilder()
        .setColor(category.color)
        .setTitle(`${category.emoji} ${category.name} Ticket`)
        .setDescription(`Welcome, <@${userId}>! Please describe your issue in detail. A staff member will be with you shortly.\n\n${category.description || ''}`)
        .setFooter({ text: `Ticket ID: ${thread.id}` })
        .setTimestamp();

      const claimButton = new ActionRowBuilder()
        .addComponents(
          new ButtonBuilder()
            .setCustomId(`claim_${thread.id}`)
            .setLabel('Claim Ticket')
            .setEmoji('🙋')
            .setStyle(ButtonStyle.Primary),
          new ButtonBuilder()
            .setCustomId(`close_${thread.id}`)
            .setLabel('Close Ticket')
            .setEmoji('🔒')
            .setStyle(ButtonStyle.Danger)
        );

      await thread.send({
        content: `${TICKET_ROLE_CONFIG[categoryKey]?.roles?.map(roleId => `<@&${roleId}>`).join(' ') || ''} <@${userId}>`,
        embeds: [initialThreadEmbed],
        components: [claimButton]
      });

      // Store active ticket info
      activeTickets.set(thread.id, {
        userId: userId,
        category: categoryKey,
        threadId: thread.id,
        createdAt: Date.now(),
        closed: false,
        claimedBy: null
      });

      // Save tickets to file
      await saveTickets();
        
      const ticketLogChannel = guild.channels.cache.get(config.TICKET_LOG_CHANNEL_ID);
      if (ticketLogChannel) {
        const openEmbed = new EmbedBuilder()
          .setTitle('🎫 Ticket Opened')
          .addFields(
            { name: 'Ticket ID', value: thread.id, inline: true },
            { name: 'Category', value: category.name, inline: true },
            { name: 'Opened By', value: `${interaction.user.tag} (${userId})`, inline: true }
          )
          .setColor(category.color || 0x00BFFF)
          .setTimestamp();
        ticketLogChannel.send({ embeds: [openEmbed] }).catch(console.error);
      }
      await interaction.followUp({
        content: `✅ Your **${category.name}** ticket has been created! Please check ${thread.toString()}.`,
        ephemeral: true
      }).catch(console.error);

    } catch (error) {
      console.error(`ERROR creating ticket for user ${userId} in category ${categoryKey}:`, error);
      await interaction.followUp({
        content: `❌ There was an error creating your ticket. Please try again later or contact an administrator.`,
        ephemeral: true
      }).catch(console.error);
      await sendEventLog(guild, '❌ Create Ticket Error', 0xff0000, [
        { name: 'User', value: `${interaction.user.tag} (${userId})`, inline: false },
        { name: 'Category', value: categoryKey, inline: false },
        { name: 'Error', value: error.message?.substring(0, 1024) || 'No message', inline: false },
        { name: 'Stack', value: error.stack?.substring(0, 1024) || 'No stack', inline: false }
      ]).catch(console.error);
    }
  }


  // createTicket function below
  async function createTicket(interaction, categoryKey) {
    const category = TICKET_CATEGORIES[categoryKey];
    if (!category) {
      await interaction.followUp({ content: '❌ Invalid ticket category selected.', ephemeral: true }).catch(console.error);
      return;
    }

    const guild = interaction.guild;
    const userId = interaction.user.id;
    const channel = interaction.channel;

    const blacklistStatus = getSupportBlacklistStatus(userId);
    if (blacklistStatus.isBlacklisted) {
      await interaction.followUp({
        content: `❌ You are currently blacklisted from using the Sweetsiez Support System. Case ${blacklistStatus.latest.caseId}.`,
        ephemeral: true
      }).catch(console.error);
      return;
    }

    // Check if user is verified (except for discord support)
    if (categoryKey !== 'discord') {
      const isVerified = verifiedUsers.has(userId);
      if (!isVerified) {
        await interaction.followUp({
          content: '❌ You must be verified to open this type of ticket. Please use `/verify` first, or open a General Support ticket if you need help with verification.',
          ephemeral: true
        }).catch(console.error);
        return;
      }
    }

    // Check if user already has an active ticket of this type
    const existingTicket = [...activeTickets.values()].find(
      t => t.userId === userId && t.category === categoryKey && !t.closed
    );

    if (existingTicket) {
      const existingThread = await guild.channels.fetch(existingTicket.threadId).catch(() => null);
      if (existingThread) {
        await interaction.followUp({
          content: `⚠️ You already have an active **${category.name}** ticket: ${existingThread.toString()}. Please use that one or close it before opening a new one.`,
          ephemeral: true
        }).catch(console.error);
        return;
      } else {
        // Clean up stale ticket record if thread doesn't exist
        activeTickets.delete(existingTicket.threadId);
        await Ticket.updateOne(
          { threadId: existingTicket.threadId },
          { $set: { closed: true } }
        ).catch(error => console.error('Error closing stale ticket record:', error.message));
      }
    }

    try {
      const threadName = `${category.emoji} ${category.name} - ${interaction.user.username}`;
      const thread = await channel.threads.create({
        name: threadName,
        type: ChannelType.PrivateThread,
        reason: `New ticket for ${interaction.user.tag} (${category.name})`,
        invitable: false
      }).catch(async (err) => {
        console.error('Failed to create private thread:', err);
        if (err.code === 50035 || err.code === 50013) {
          console.warn('Falling back to public thread creation due to permissions/restrictions.');
          return await channel.threads.create({
            name: threadName,
            type: ChannelType.PublicThread,
            reason: `New ticket for ${interaction.user.tag} (${category.name})`,
          });
        }
        throw err;
      });

      await thread.members.add(userId).catch(err => console.error(`Failed to add user ${userId} to thread ${thread.id}:`, err));

      // if (category.roleId) {
      //     await thread.members.add(category.roleId).catch(err => console.error(`Failed to add role ${category.roleId} to thread ${thread.id}:`, err));
      // }

      // if (config.OVERSEER_ROLE_ID) {
      //     await thread.members.add(config.OVERSEER_ROLE_ID).catch(err => console.error(`Failed to add overseer role ${config.OVERSEER_ROLE_ID} to thread ${thread.id}:`, err));
      // }

      const initialThreadEmbed = new EmbedBuilder()
        .setColor(category.color)
        .setTitle(`${category.emoji} ${category.name} Ticket`)
        .setDescription(`Welcome, <@${userId}>! Please describe your issue in detail. A staff member will be with you shortly.\n\n${category.description || ''}`)
        .setFooter({ text: `Ticket ID: ${thread.id}` })
        .setTimestamp();

      const claimButton = new ActionRowBuilder()
        .addComponents(
          new ButtonBuilder()
            .setCustomId(`claim_${thread.id}`)
            .setLabel('Claim Ticket')
            .setEmoji('🙋')
            .setStyle(ButtonStyle.Primary),
          new ButtonBuilder()
            .setCustomId(`close_${thread.id}`)
            .setLabel('Close Ticket')
            .setEmoji('🔒')
            .setStyle(ButtonStyle.Danger)
        );

      await thread.send({
        content: `${TICKET_ROLE_CONFIG[categoryKey]?.roles?.map(roleId => `<@&${roleId}>`).join(' ') || ''} <@${userId}>`,
        embeds: [initialThreadEmbed],
        components: [claimButton]
      });

      // Store active ticket info
      activeTickets.set(thread.id, {
        userId: userId,
        category: categoryKey,
        threadId: thread.id,
        createdAt: Date.now(),
        closed: false,
        claimedBy: null
      });

      // Save tickets to file
      await saveTickets();

      await interaction.followUp({
        content: `✅ Your **${category.name}** ticket has been created! Please check ${thread.toString()}.`,
        ephemeral: true
      }).catch(console.error);

    } catch (error) {
      console.error(`ERROR creating ticket for user ${userId} in category ${categoryKey}:`, error);
      await interaction.followUp({
        content: `❌ There was an error creating your ticket. Please try again later or contact an administrator.`,
        ephemeral: true
      }).catch(console.error);
      await sendEventLog(guild, '❌ Create Ticket Error', 0xff0000, [
        { name: 'User', value: `${interaction.user.tag} (${userId})`, inline: false },
        { name: 'Category', value: categoryKey, inline: false },
        { name: 'Error', value: error.message?.substring(0, 1024) || 'No message', inline: false },
        { name: 'Stack', value: error.stack?.substring(0, 1024) || 'No stack', inline: false }
      ]).catch(console.error);
    }
  }

  // Update handleClaim to save after updating ticket
  async function handleClaim(interaction, threadId) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(e => console.error(`Failed to defer reply for claim interaction: ${e.message}`));

    const ticket = await getActiveTicket(threadId);
    if (!ticket) {
      await interaction.editReply('❌ This ticket could not be found. It might have been closed.').catch(console.error);
      return;
    }

    // Permission check: Must have the appropriate role for this ticket category OR be an overseer
    const category = TICKET_CATEGORIES[ticket.category];
    const hasPermission = interaction.member.roles.cache.has(config.OVERSEER_ROLE_ID) ||
      (category && category.roleId && interaction.member.roles.cache.has(category.roleId)) ||
      interaction.member.permissions.has(PermissionFlagsBits.Administrator);

    if (!hasPermission) {
      await interaction.editReply('❌ You do not have permission to claim this ticket.').catch(console.error);
      return;
    }

    if (ticket.claimedBy) {
      await interaction.editReply(`⚠️ This ticket is already claimed by <@${ticket.claimedBy}>.`).catch(console.error);
      return;
    }

    ticket.claimedBy = interaction.user.id;
    activeTickets.set(threadId, ticket);
    await saveTickets(); // Save after update

    const threadChannel = await client.channels.fetch(threadId).catch(() => null);
    if (threadChannel && threadChannel.isThread()) {
      const originalMessage = await threadChannel.messages.fetch(interaction.message.id).catch(() => null);
      if (originalMessage) {
        const updatedEmbed = EmbedBuilder.from(originalMessage.embeds[0])
          .addFields({ name: 'Claimed By', value: `<@${interaction.user.id}>`, inline: true });

        const updatedButtons = new ActionRowBuilder()
          .addComponents(
            ButtonBuilder.from(originalMessage.components[0].components[0]).setDisabled(true),
            new ButtonBuilder()
              .setCustomId(`unclaim_${threadId}`)
              .setLabel('Unclaim Ticket')
              .setEmoji('🔓')
              .setStyle(ButtonStyle.Secondary),
            ButtonBuilder.from(originalMessage.components[0].components[1])
          );

        await originalMessage.edit({ embeds: [updatedEmbed], components: [updatedButtons] }).catch(console.error);
      }
    }

    await interaction.editReply(`✅ You have claimed ticket #${threadId}.`).catch(console.error);
    if (threadChannel) {
      await threadChannel.send(`Ticket claimed by <@${interaction.user.id}>.`).catch(console.error);
    }

    const caseRecord = nextCase('TicketClaimed', interaction.user.id, ticket.userId, `Ticket ${threadId} claimed`, {
      ticketThreadId: threadId,
      ticketCategory: ticket.category,
      claimedBy: interaction.user.id
    });
    await sendModLog(interaction.guild, { ...caseRecord, color: 0x00ccff });
  }

  // Update handleUnclaim to save after updating ticket
  async function handleUnclaim(interaction, threadId) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(e => console.error(`Failed to defer reply for unclaim interaction: ${e.message}`));

    const ticket = await getActiveTicket(threadId);
    if (!ticket) {
      await interaction.editReply('❌ This ticket could not be found. It might have been closed.').catch(console.error);
      return;
    }

    if (!ticket.claimedBy) {
      await interaction.editReply('⚠️ This ticket is not currently claimed.').catch(console.error);
      return;
    }

    // Permission check: Must be the claimer OR have overseer/admin permissions
    const hasPermission = interaction.user.id === ticket.claimedBy ||
      interaction.member.permissions.has(PermissionFlagsBits.Administrator) ||
      interaction.member.roles.cache.has(config.OVERSEER_ROLE_ID);

    if (!hasPermission) {
      await interaction.editReply('❌ You can only unclaim tickets that you have claimed, unless you have Overseer permissions.').catch(console.error);
      return;
    }

    const previousClaimerName = ticket.claimedBy === interaction.user.id ? 'yourself' : `<@${ticket.claimedBy}>`;

    ticket.claimedBy = null;
    activeTickets.set(threadId, ticket);
    await saveTickets(); // Save after update

    const threadChannel = await client.channels.fetch(threadId).catch(() => null);
    if (threadChannel && threadChannel.isThread()) {
      const originalMessage = await threadChannel.messages.fetch(interaction.message.id).catch(() => null);
      if (originalMessage) {
        const updatedEmbed = EmbedBuilder.from(originalMessage.embeds[0]);
        const fieldsWithoutClaimed = updatedEmbed.data.fields?.filter(f => f.name !== 'Claimed By') || [];
        updatedEmbed.data.fields = fieldsWithoutClaimed;

        const updatedButtons = new ActionRowBuilder()
          .addComponents(
            new ButtonBuilder()
              .setCustomId(`claim_${threadId}`)
              .setLabel('Claim Ticket')
              .setEmoji('🙋')
              .setStyle(ButtonStyle.Primary),
            ButtonBuilder.from(originalMessage.components[0].components[2])
          );

        await originalMessage.edit({ embeds: [updatedEmbed], components: [updatedButtons] }).catch(console.error);
      }
    }

    await interaction.editReply(`✅ Ticket #${threadId} has been unclaimed.`).catch(console.error);
    if (threadChannel) {
      await threadChannel.send(`Ticket unclaimed by <@${interaction.user.id}> (previously claimed by ${previousClaimerName}).`).catch(console.error);
    }

    const caseRecord = nextCase('TicketUnclaimed', interaction.user.id, ticket.userId, `Ticket ${threadId} unclaimed`, {
      ticketThreadId: threadId,
      ticketCategory: ticket.category,
      unclaimedBy: interaction.user.id
    });
    await sendModLog(interaction.guild, { ...caseRecord, color: 0xffa500 });
  }

  // Update handleClose to save after closing ticket
  async function handleClose(interaction, threadId) {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(e => console.error(`Failed to defer reply for close interaction: ${e.message}`));
    if (!interaction.deferred && !interaction.replied) {
      await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(e => {
        console.error(`Failed to defer close interaction: ${e.message}`);
        return; // Exit if we can't defer
      });
    }
    const ticket = await getActiveTicket(threadId);
    if (!ticket) {
      await interaction.editReply('❌ This ticket could not be found. It might already be closed.').catch(console.error);
      return;
    }

    const guild = interaction.guild;
    const threadChannel = await guild.channels.fetch(threadId).catch(() => null);
    

    // Permission check: Must have the appropriate role for this ticket category OR be an admin
    // Users can NO LONGER close their own tickets - only staff can
    const category = TICKET_CATEGORIES[ticket.category];
    const allowedRoles = TICKET_ROLE_CONFIG[ticket.category]?.roles || [];
    const hasPermission = interaction.member.permissions.has(PermissionFlagsBits.Administrator) ||
      allowedRoles.some(roleId => interaction.member.roles.cache.has(roleId));

    if (!hasPermission) {
      await interaction.editReply('❌ You do not have permission to close this ticket. Only staff members can close tickets.').catch(console.error);
      return;
    }

    try {
      ticket.closed = true;
      activeTickets.set(threadId, ticket);
      await saveTickets(); // Save after marking as closed
      activeTickets.delete(threadId);

      if (threadChannel && threadChannel.isThread()) {
        await threadChannel.send({
          embeds: [
            new EmbedBuilder()
              .setColor(0x808080)
              .setTitle('Ticket Closed')
              .setDescription(`This ticket has been closed by <@${interaction.user.id}>.`)
              .setTimestamp()
          ]
        }).catch(console.error);

        let allMessages = [];
        let lastId;

        while (true) {
          const options = { limit: 100 };
          if (lastId) options.before = lastId;

          const messages = await threadChannel.messages.fetch(options);
          if (messages.size === 0) break;

          allMessages.push(...messages.values());
          lastId = messages.last().id;

          if (messages.size < 100) break;
        }

        allMessages.sort((a, b) => a.createdTimestamp - b.createdTimestamp);

        let transcript = `Ticket Transcript\n`;
        transcript += `Ticket ID: ${threadId}\n`;
        transcript += `Category: ${ticket.category}\n`;
        transcript += `Opened by: ${ticket.userId}\n`;
        transcript += `Closed by: ${interaction.user.id} (${interaction.user.tag})\n`;
        transcript += `Opened at: ${new Date(ticket.createdAt).toLocaleString()}\n`;
        transcript += `Closed at: ${new Date().toLocaleString()}\n`;
        transcript += `Total Messages: ${allMessages.length}\n`;
        transcript += `${'='.repeat(80)}\n\n`;

        for (const msg of allMessages) {
          const timestamp = new Date(msg.createdTimestamp).toLocaleString();
          const author = `${msg.author.tag} (${msg.author.id})`;
          let content = msg.content || '[No text content]';

          if (msg.attachments.size > 0) {
            content += `\n[Attachments: ${msg.attachments.map(a => a.url).join(', ')}]`;
          }

          if (msg.embeds.length > 0) {
            content += `\n[Embeds: ${msg.embeds.length} embed(s)]`;
          }

          transcript += `[${timestamp}] ${author}:\n${content}\n\n`;
        }

        const transcriptBuffer = Buffer.from(transcript, 'utf-8');
        const transcriptAttachment = {
          attachment: transcriptBuffer,
          name: `ticket-${threadId}-transcript.txt`
        };

        const caseRecord = nextCase('TicketClosed', interaction.user.id, ticket.userId, `Ticket ${threadId} closed`, {
          ticketThreadId: threadId,
          ticketCategory: ticket.category,
          closedBy: interaction.user.id,
          messageCount: allMessages.length
        });

        if (config.TICKET_LOG_CHANNEL_ID) {
          const logChannel = await guild.channels.fetch(config.TICKET_LOG_CHANNEL_ID).catch(() => null);
          if (logChannel) {
            const logEmbed = new EmbedBuilder()
              .setTitle('🎫 Ticket Closed')
              .addFields(
                { name: 'Case ID', value: `${caseRecord.caseId}`, inline: true },
                { name: 'Ticket ID', value: threadId, inline: true },
                { name: 'Category', value: TICKET_CATEGORIES[ticket.category]?.name || ticket.category, inline: true },
                { name: 'Opened By', value: `<@${ticket.userId}>`, inline: true },
                { name: 'Closed By', value: `<@${interaction.user.id}>`, inline: true },
                { name: 'Duration', value: formatDuration(Date.now() - ticket.createdAt), inline: true },
                { name: 'Total Messages', value: `${allMessages.length}`, inline: true }
              )
              .setTimestamp(new Date(caseRecord.timestamp))
              .setColor(0x808080);

              
    const user = await client.users.fetch(ticket.userId).catch(() => null);
    
    if (user) {
        const farewellEmbed = new EmbedBuilder()
            .setTitle("👋 Thanks for contacting Sweetsiez Support!")
            .setDescription(`Your ticket (**${TICKET_CATEGORIES[ticket.category].name}**) has been closed. Attached is your message transcript.\n\n**Handled by:** <@${ticket.claimedBy || "System"}>`)
            .setColor(0x00FF00);

        const ratingRow = new ActionRowBuilder().addComponents(
            new ButtonBuilder().setCustomId(`rate_1_${threadId}`).setEmoji('⭐').setStyle(ButtonStyle.Secondary),
            new ButtonBuilder().setCustomId(`rate_2_${threadId}`).setEmoji('⭐').setStyle(ButtonStyle.Secondary),
            new ButtonBuilder().setCustomId(`rate_3_${threadId}`).setEmoji('⭐').setStyle(ButtonStyle.Secondary),
            new ButtonBuilder().setCustomId(`rate_4_${threadId}`).setEmoji('⭐').setStyle(ButtonStyle.Secondary),
            new ButtonBuilder().setCustomId(`rate_5_${threadId}`).setEmoji('⭐').setStyle(ButtonStyle.Secondary)
        );

        const feedbackRow = new ActionRowBuilder().addComponents(
            new ButtonBuilder().setCustomId(`feedback_${threadId}`).setLabel("Leave Feedback").setStyle(ButtonStyle.Primary)
        );

        await user.send({ 
            embeds: [farewellEmbed], 
            files: [transcriptAttachment],
            components: [ratingRow, feedbackRow]
        }).catch(() => console.log("Could not DM user transcript."));
    }
              
              
            await logChannel.send({
              embeds: [logEmbed],
              files: [transcriptAttachment]
            }).catch(err => {
              console.error('Failed to send ticket transcript to log channel:', err);
              sendEventLog(guild, '❌ Ticket Transcript Log Error', 0xffa500, [
                { name: 'Ticket ID', value: threadId, inline: false },
                { name: 'Error', value: err.message?.substring(0, 1024) || 'No message', inline: false }
              ]).catch(console.error);
            });
          }
        }

        // Archive AND lock the thread in a single operation
        await threadChannel.edit({
          archived: true,
          locked: true,
          reason: `Ticket closed by ${interaction.user.tag}`
        }).catch(err => {
          console.error(`Failed to archive/lock thread ${threadId}:`, err);
          sendEventLog(guild, '❌ Thread Archive/Lock Error', 0xffa500, [
            { name: 'Thread ID', value: threadId, inline: false },
            { name: 'Error', value: err.message?.substring(0, 1024) || 'No message', inline: false }
          ]).catch(console.error);
        });
      }

      await interaction.editReply(`✅ Ticket #${threadId} has been closed, locked, and archived. Transcript has been logged.`).catch(console.error);

    } catch (error) {
      console.error(`ERROR closing ticket ${threadId}:`, error);
      await interaction.editReply(`❌ An error occurred while trying to close the ticket.`).catch(console.error);
      await sendEventLog(guild, '❌ Close Ticket Error', 0xff0000, [
        { name: 'Ticket Thread ID', value: threadId, inline: false },
        { name: 'User', value: `${interaction.user.tag} (${interaction.user.id})`, inline: false },
        { name: 'Error', value: error.message?.substring(0, 1024) || 'No message', inline: false },
        { name: 'Stack', value: error.stack?.substring(0, 1024) || 'No stack', inline: false }
      ]).catch(console.error);
    }
  }

