  // FIXED safeDeferReply function - add proper options handling
 // FIXED safeDeferReply function - add proper options handling
async function safeDeferReply(interaction, options = {}) {
  if (!interaction) {
    console.error('safeDeferReply called without interaction object');
    return false;
  }

  // Handle both old-style boolean and new-style options object
  let ephemeral = true; // Default to ephemeral
  if (typeof options === 'boolean') {
    ephemeral = options;
  } else if (options.ephemeral !== undefined) {
    ephemeral = options.ephemeral;
  }

  // Create proper options using MessageFlags
  const opts = {
    flags: ephemeral ? MessageFlags.Ephemeral : undefined
  };

  // Don't defer if modal will be shown
  if (
    interaction.customId &&
    (interaction.customId.startsWith("rank_setrank_") ||
      // Approve opens the credentials modal, so it must not be deferred first.
      interaction.customId.startsWith("trial_approve_"))
  ) {
    return true; // Don't defer for modals, but return true so command continues
  }

  if (!interaction.deferred && !interaction.replied) {
    try {
      await interaction.deferReply(opts);
      console.log(`✅ Deferred reply for ${interaction.commandName || interaction.customId}`);
      return true;
    } catch (e) {
      if (e?.code === 10062 || String(e).includes("Unknown interaction")) {
        console.warn(`⏰ Interaction ${interaction.id} expired`);
        return false;
      }
      if (String(e).includes("already been acknowledged")) {
        console.warn(`⚠️ Interaction ${interaction.id} already acknowledged`);
        return true;
      }
      console.error(`❌ Defer failed for ${interaction.id}:`, e);
      return false;
    }
  }
  return true;
}

