async function legacyCheckDeadlineReminders(guild) {
  try {
    const now = new Date();
    const reminders = await DeadlineReminder.find({ status: "pending" });
    
    for (const reminder of reminders) {
      const timeUntilDeadline = new Date(reminder.deadline) - now;
      
      // Check each reminder time
      for (const reminderTime of reminder.reminderTimes) {
        const wasAlreadySent = reminder.sentReminders.some(sr => sr.time === reminderTime);
        if (!wasAlreadySent && timeUntilDeadline > 0 && timeUntilDeadline <= reminderTime) {
          // Send reminder
          try {
            const channel = await guild.channels.fetch(process.env.REQUEST_CHANNEL_ID);
            if (channel) {
              const timeStr = reminderTime === 86400000 ? "24 hours" : reminderTime === 3600000 ? "1 hour" : "soon";
              await channel.send(`⏰ Reminder: A request deadline is in **${timeStr}** (ID: ${reminder.requestId})`);
            }
            reminder.sentReminders.push({ time: reminderTime, sentAt: new Date() });
          } catch (err) {
            console.error("Failed to send deadline reminder:", err);
          }
        }
      }

      // Mark as overdue if deadline passed
      if (timeUntilDeadline <= 0 && reminder.status === "pending") {
        reminder.status = "overdue";
      }
      
      await reminder.save();
    }
  } catch (err) {
    console.error("❌ Deadline reminder check failed:", err);
  }
}

async function checkBurnoutFlags() {
  try {
    const staffProfiles = await StaffProfile.find({});
    
    for (const profile of staffProfiles) {
      let flag = await BurnoutFlag.findOne({ discordId: profile.discordId });
      if (!flag) {
        flag = new BurnoutFlag({
          flagId: `burnout_${profile.discordId}_${Date.now()}`,
          discordId: profile.discordId,
          robloxUsername: profile.robloxUsername,
          robloxUserId: profile.robloxUserId,
        });
      }

      // Check for inactivity
      const lastUpdate = profile.updatedAt || new Date(0);
      const daysSinceUpdate = (Date.now() - lastUpdate) / (1000 * 60 * 60 * 24);
      flag.flags.noActivityDays = Math.floor(daysSinceUpdate);

      // Check for quota misses
      const recentPerformance = await QuotaPerformance.findOne({
        discordId: profile.discordId,
        sort: { createdAt: -1 },
      });
      if (recentPerformance) {
        flag.flags.quotaMisses = (recentPerformance.missedWeeks || 0);
      }

      // Determine severity
      const inactivityScore = flag.flags.noActivityDays > 14 ? 2 : flag.flags.noActivityDays > 7 ? 1 : 0;
      const quotaScore = flag.flags.quotaMisses >= 2 ? 2 : flag.flags.quotaMisses === 1 ? 1 : 0;
      const totalScore = inactivityScore + quotaScore;

      if (totalScore >= 3) {
        flag.severity = "high";
        flag.suggestedActions = ["Schedule check-in", "Offer additional support", "Consider LOA"];
      } else if (totalScore >= 2) {
        flag.severity = "medium";
        flag.suggestedActions = ["Monitor activity", "Offer assistance"];
      } else {
        flag.severity = "low";
        flag.suggestedActions = [];
      }

      await flag.save();
    }
  } catch (err) {
    console.error("❌ Burnout check failed:", err);
  }
}

function legacyCalculateStringSimilarity(str1, str2) {
  const s1 = String(str1 || "").toLowerCase();
  const s2 = String(str2 || "").toLowerCase();
  
  if (s1 === s2) return 100;
  
  const longer = s1.length > s2.length ? s1 : s2;
  const shorter = s1.length > s2.length ? s2 : s1;
  
  if (longer.length === 0) return 100;
  
  const editDistance = legacyGetEditDistance(shorter, longer);
  return ((longer.length - editDistance) / longer.length) * 100;
}

function legacyGetEditDistance(s1, s2) {
  const costs = [];
  for (let i = 0; i <= s1.length; i++) {
    let lastValue = i;
    for (let j = 0; j <= s2.length; j++) {
      if (i === 0) {
        costs[j] = j;
      } else if (j > 0) {
        let newValue = costs[j - 1];
        if (s1.charAt(i - 1) !== s2.charAt(j - 1)) {
          newValue = Math.min(Math.min(newValue, lastValue), costs[j]) + 1;
        }
        costs[j - 1] = lastValue;
        lastValue = newValue;
      }
    }
    if (i > 0) costs[s2.length] = lastValue;
  }
  return costs[s2.length];
}

async function legacyCheckForDuplicateRequests(requestType, title, description, threshold = 75) {
  try {
    let model;
    if (requestType === "graphics") model = GraphicsRequest;
    else if (requestType === "announcement") model = AnnouncementRequest;
    else if (requestType === "filming") model = FilmingSession;
    else if (requestType === "event") model = MinorEventPlan;
    else return null;

    const recentRequests = await model.find({ createdAt: { $gte: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000) } }).limit(10);
    
    for (const req of recentRequests) {
      const titleSim = legacyCalculateStringSimilarity(title, req.title || req.purpose || req.name);
      const descSim = legacyCalculateStringSimilarity(description, req.description || req.shotList || "");
      const avgSim = (titleSim + descSim) / 2;
      
      if (avgSim >= threshold) {
        return {
          matchScore: Math.round(avgSim),
          similarId: req.requestId || req.graphicsId || req.sessionId || req.eventId,
        };
      }
    }
    return null;
  } catch (err) {
    console.error("❌ Duplicate check failed:", err);
    return null;
  }
}

async function legacyProcessApiFailureQueue() {
  try {
    const queued = await ApiFailureQueue.find({ status: { $in: ["queued", "retrying"] } });
    
    for (const item of queued) {
      if (item.retryCount >= item.maxRetries) {
        item.status = "failed";
        await item.save();
        continue;
      }

      try {
        // Attempt the operation
        if (item.operationType === "rank_change") {
          // Would actually call ROBLOX API here
          item.status = "completed";
        }
        await item.save();
      } catch (err) {
        item.retryCount += 1;
        item.lastError = err.message;
        item.status = item.retryCount < item.maxRetries ? "retrying" : "failed";
        await item.save();
      }
    }
  } catch (err) {
    console.error("❌ API failure queue processing failed:", err);
  }
}

async function autoArchiveOldRequests() {
  try {
    const configs = await AutoArchiveConfig.find({ enabled: true });
    
    for (const config of configs) {
      const cutoffDate = new Date(Date.now() - config.daysUntilArchive * 24 * 60 * 60 * 1000);
      let model;
      
      if (config.requestType === "graphics") model = GraphicsRequest;
      else if (config.requestType === "announcement") model = AnnouncementRequest;
      else if (config.requestType === "filming") model = FilmingSession;
      else if (config.requestType === "event") model = MinorEventPlan;
      else continue;

      const updated = await model.updateMany(
        { status: { $in: config.statusesToArchive }, updatedAt: { $lte: cutoffDate } },
        { status: "archived", updatedAt: new Date() }
      );

      if (updated.modifiedCount > 0) {
        console.log(`📦 Auto-archived ${updated.modifiedCount} ${config.requestType} requests`);
      }
      
      config.lastRun = new Date();
      await config.save();
    }
  } catch (err) {
    console.error("❌ Auto-archive failed:", err);
  }
}

