async function checkUserNotificationPreference(discordId, requestType) {
  try {
    const prefs = await NotificationPreference.findOne({ discordId });
    if (!prefs) return true; // Default to enabled
    
    // Check if muted globally
    if (prefs.mutedUntil && new Date() < new Date(prefs.mutedUntil)) return false;
    
    // Check type-specific preferences
    if (prefs.requestTypePings && typeof prefs.requestTypePings[requestType] !== "undefined") {
      return prefs.requestTypePings[requestType];
    }
    
    return true;
  } catch (err) {
    console.error("❌ Preference check failed:", err);
    return true;
  }
}

