function validateGraphicsDeadline(deadlineString) {
  const deadline = new Date(deadlineString);
  const now = new Date();
  
  if (isNaN(deadline)) {
    return { valid: false, error: "Invalid date format. Use MM/DD/YYYY or a valid date string." };
  }
  
  if (deadline < now) {
    return { valid: false, error: `❌ Deadline is in the past (${Math.abs(Math.floor((deadline - now) / (1000 * 60 * 60 * 24)))} days ago).` };
  }
  
  if (deadline > new Date(Date.now() + 90 * 24 * 60 * 60 * 1000)) {
    return { valid: false, error: "❌ Deadline is more than 90 days away. Please use a more realistic deadline." };
  }
  
  return { valid: true };
}

function validateGraphicsRequest(purpose, textNeeded, sizePlatform) {
  const errors = [];
  
  if (!purpose || purpose.trim().length === 0) {
    errors.push("Purpose cannot be empty");
  }
  if (purpose && purpose.length > 200) {
    errors.push("Purpose must be less than 200 characters");
  }
  
  if (!textNeeded || textNeeded.trim().length === 0) {
    errors.push("Text needed cannot be empty");
  }
  
  if (!sizePlatform || sizePlatform.trim().length === 0) {
    errors.push("Size/platform cannot be empty");
  }
  
  if (errors.length > 0) {
    return { valid: false, error: `❌ Validation failed:\n${errors.map(e => `• ${e}`).join('\n')}` };
  }
  
  return { valid: true };
}

function validateAnnouncementRequest(title, message, target) {
  const errors = [];
  
  if (!title || title.trim().length === 0) {
    errors.push("Title cannot be empty");
  }
  if (title && title.length > 256) {
    errors.push("Title must be less than 256 characters");
  }
  
  if (!message || message.trim().length === 0) {
    errors.push("Message cannot be empty");
  }
  if (message && message.length > 4000) {
    errors.push("Message must be less than 4000 characters (Discord limit)");
  }
  
  if (!target) {
    errors.push("Target channel must be specified");
  }
  
  if (errors.length > 0) {
    return { valid: false, error: `❌ Validation failed:\n${errors.map(e => `• ${e}`).join('\n')}` };
  }
  
  return { valid: true };
}

function validateFilmingSession(title, date, time, theme) {
  const errors = [];
  
  if (!title || title.trim().length === 0) {
    errors.push("Title cannot be empty");
  }
  
  const sessionDate = new Date(date);
  const now = new Date();
  if (isNaN(sessionDate) || sessionDate < now) {
    errors.push("Session date must be in the future");
  }
  
  if (!time || !time.match(/^\d{1,2}:\d{2}\s*(AM|PM|am|pm)$/)) {
    errors.push("Time must be in format HH:MM AM/PM");
  }
  
  if (!theme || theme.trim().length === 0) {
    errors.push("Theme cannot be empty");
  }
  
  if (errors.length > 0) {
    return { valid: false, error: `❌ Validation failed:\n${errors.map(e => `• ${e}`).join('\n')}` };
  }
  
  return { valid: true };
}

  // ── AutoMod alert actions: warn / timeout / ban straight from the alert ──
  const AUTOMOD_ACTION_LABELS = { warn: 'Warn', timeout: 'Timeout', ban: 'Ban' };

  function parseAutomodCustomId(customId, prefix) {
    const raw = String(customId || '');
    if (!raw.startsWith(prefix)) return null;
    const [action, ...rest] = raw.slice(prefix.length).split(':');
    return { action, targetId: rest.join(':') };
  }

  async function handleAutomodActionButton(interaction) {
    const parsed = parseAutomodCustomId(interaction.customId, 'automod_');
    if (!parsed?.targetId) return;
    const { action, targetId } = parsed;

    if (action === 'dismiss') {
      await interaction.update({ components: [] }).catch(() => {});
      await interaction.followUp({
        content: `Dismissed by <@${interaction.user.id}> — no action taken.`,
        flags: MessageFlags.Ephemeral,
      }).catch(() => {});
      return;
    }
    if (!AUTOMOD_ACTION_LABELS[action]) return;

    // Same gate as the slash commands: department membership plus rank for the action.
    const perm = await hasRobloxRankPermission(interaction.user.id, action === 'ban' ? 'ban' : 'warn');
    if (!perm.ok) {
      return interaction.reply({ content: `❌ ${perm.reason}`, flags: MessageFlags.Ephemeral });
    }

    const { ModalBuilder, TextInputBuilder, TextInputStyle } = require('discord.js');
    const modal = new ModalBuilder()
      .setCustomId(`automod_modal_${action}:${targetId}`)
      .setTitle(`${AUTOMOD_ACTION_LABELS[action]} — AutoMod flag`);

    const rows = [
      new ActionRowBuilder().addComponents(
        new TextInputBuilder()
          .setCustomId('automod_reason')
          .setLabel('Reason')
          .setStyle(TextInputStyle.Paragraph)
          .setRequired(true)
          .setMaxLength(500)
          .setValue('[AUTOMOD] '),
      ),
    ];

    if (action === 'timeout') {
      rows.push(new ActionRowBuilder().addComponents(
        new TextInputBuilder()
          .setCustomId('automod_minutes')
          .setLabel('Timeout length in minutes (max 40320)')
          .setStyle(TextInputStyle.Short)
          .setRequired(true)
          .setValue('10')
          .setMaxLength(5),
      ));
    }

    if (action === 'ban') {
      rows.push(new ActionRowBuilder().addComponents(
        new TextInputBuilder()
          .setCustomId('automod_days')
          .setLabel('Ban length in days (0 = permanent)')
          .setStyle(TextInputStyle.Short)
          .setRequired(true)
          .setValue('0')
          .setMaxLength(3),
      ));
      rows.push(new ActionRowBuilder().addComponents(
        new TextInputBuilder()
          .setCustomId('automod_delete')
          .setLabel('Delete their recent messages? (yes/no)')
          .setStyle(TextInputStyle.Short)
          .setRequired(true)
          .setValue('yes')
          .setMaxLength(3),
      ));
    }

    rows.push(new ActionRowBuilder().addComponents(
      new TextInputBuilder()
        .setCustomId('automod_note')
        .setLabel('Internal note (optional)')
        .setStyle(TextInputStyle.Short)
        .setRequired(false)
        .setMaxLength(200),
    ));

    modal.addComponents(rows);
    return interaction.showModal(modal);
  }

  async function handleAutomodActionModal(interaction) {
    const parsed = parseAutomodCustomId(interaction.customId, 'automod_modal_');
    if (!parsed?.targetId) return;
    const { action, targetId } = parsed;
    if (!AUTOMOD_ACTION_LABELS[action]) return;

    await interaction.deferReply({ flags: MessageFlags.Ephemeral }).catch(() => {});

    const guild = interaction.guild;
    const issuer = interaction.user;
    const issuerMember = interaction.member;
    if (!guild) return interaction.editReply('❌ This only works inside the server.');

    const perm = await hasRobloxRankPermission(issuer.id, action === 'ban' ? 'ban' : 'warn');
    if (!perm.ok) return interaction.editReply(`❌ ${perm.reason}`);

    const reasonInput = interaction.fields.getTextInputValue('automod_reason').trim() || 'No reason provided';
    const note = interaction.fields.getTextInputValue('automod_note')?.trim() || '';
    const reason = note ? `${reasonInput} (${note})` : reasonInput;

    const targetUser = await client.users.fetch(targetId).catch(() => null);
    if (!targetUser) return interaction.editReply('❌ I could not resolve that user any more.');
    if (targetUser.bot) return interaction.editReply('❌ That account is a bot.');
    const targetMember = await guild.members.fetch(targetId).catch(() => null);
    if (targetMember && issuerMember && issuerMember.roles.highest.position <= targetMember.roles.highest.position) {
      return interaction.editReply('❌ You cannot moderate a member with an equal or higher role.');
    }

    const lines = [];

    if (action === 'warn') {
      if (targetMember && !targetMember.permissions.has(PermissionFlagsBits.Administrator)) {
        await targetMember.timeout(10 * 60 * 1000, `Warn applied by ${issuer.id} - case pending acknowledgement`).catch(() => {});
      }
      const warning = addWarning(targetUser.id, issuer.id, reason);
      const caseRecord = nextCase('Warn', issuer.id, targetUser.id, reason, { warningId: warning.id, source: 'automod' });
      await Warning.create({
        discordId: targetUser.id,
        reason,
        evidence: 'AutoMod alert (deleted message)',
        date: new Date(),
        punisher: issuer.tag,
        expiresAt: new Date(Date.now() + 60 * 24 * 60 * 60 * 1000),
        expired: false,
      }).catch(() => {});
      const ackCode = generateAckCode(caseRecord.caseId);
      updateCaseExtra(caseRecord, { ackCode, ackRemovesTimeout: true, guildId: guild.id });
      sendModLog(guild, { ...caseRecord, color: 0xffcc00 }).catch(() => {});
      await postToDiscordModLog(client, 'WARNING', {
        robloxUsername: null,
        discordTag: targetUser.tag,
        discordId: targetUser.id,
        reason,
        date: new Date(),
        attachments: [],
        issuerTag: issuer.tag,
      }).catch(() => {});
      await createAcknowledgementThread({
        guild,
        user: targetUser,
        title: 'You have received a warning',
        description: `You were warned in **${guild.name}** for: ${reason}\n\n⏱️ You have been automatically muted for 10 minutes as a cooldown period.\n\n📋 **Moderation Policy**: We operate on a Warn → Ban system. This is your warning. Any further violations will result in a ban.\n\n⏳ This warning will automatically expire after 60 days.\n\n✅ Acknowledge this warning below.`,
        caseId: caseRecord.caseId,
        actionType: 'Warn',
        ackCode,
        ackRemovesTimeout: true,
      }).catch(() => {});
      lines.push(`✅ Warned <@${targetUser.id}> — case **${caseRecord.caseId}** (expires in 60 days).`);
    }

    if (action === 'timeout') {
      if (!targetMember) return interaction.editReply('❌ That user is no longer in the server, so they cannot be timed out.');
      const minutes = Math.min(Math.max(parseInt(interaction.fields.getTextInputValue('automod_minutes'), 10) || 10, 1), 40320);
      const applied = await targetMember.timeout(minutes * 60 * 1000, reason).catch(error => error);
      if (applied instanceof Error) return interaction.editReply(`❌ Could not timeout: ${applied.message}`);
      const caseRecord = nextCase('Timeout', issuer.id, targetUser.id, reason, { minutes, source: 'automod' });
      sendModLog(guild, { ...caseRecord, color: 0xffa500 }).catch(() => {});
      await postToDiscordModLog(client, 'TIMEOUT', {
        robloxUsername: null,
        discordTag: targetUser.tag,
        discordId: targetUser.id,
        reason,
        date: new Date(),
        attachments: [],
        issuerTag: issuer.tag,
      }).catch(() => {});
      lines.push(`✅ Timed out <@${targetUser.id}> for **${minutes} minute(s)** — case **${caseRecord.caseId}**.`);
    }

    if (action === 'ban') {
      const days = Math.max(parseInt(interaction.fields.getTextInputValue('automod_days'), 10) || 0, 0);
      const deleteMessages = /^(y|yes|true|1)$/i.test(interaction.fields.getTextInputValue('automod_delete').trim());
      if (!targetMember) return interaction.editReply('❌ That user is no longer in the server, so they cannot be banned.');
      const applied = await targetMember.ban({
        reason,
        deleteMessageSeconds: deleteMessages ? 3600 : 0,
      }).catch(error => error);
      if (applied instanceof Error) return interaction.editReply(`❌ Could not ban: ${applied.message}`);
      const caseRecord = nextCase('Ban', issuer.id, targetUser.id, reason, { days, source: 'automod' });
      sendModLog(guild, { ...caseRecord, color: 0xff0000 }).catch(() => {});
      await postToDiscordModLog(client, 'BAN', {
        robloxUsername: null,
        discordTag: targetUser.tag,
        discordId: targetUser.id,
        reason,
        date: new Date(),
        attachments: [],
        issuerTag: issuer.tag,
      }).catch(() => {});
      lines.push(`✅ Banned <@${targetUser.id}>${days ? ` for **${days} day(s)**` : ' permanently'} — case **${caseRecord.caseId}**.`);
    }

    if (!lines.length) return interaction.editReply('❌ Unsupported action.');

    // Close the alert out so two people cannot action the same flag.
    await interaction.message?.edit({ components: [] }).catch(() => {});
    lines.push(`Logged by <@${issuer.id}>.`);
    return interaction.editReply(lines.join('\n'));
  }
