    const safeWeekKey = interaction.customId.replace('quota_approve_', '');
    const weekLabel   = safeWeekKey.replace(/_/g, ' ');
    let pending = pendingQuotaConsequences.get(weekLabel);

    if (!pending) {
      // Recover from the persisted weekly run: the in-memory map is empty after
      // a restart, and the week's consequences must not be silently lost.
      const storedRun = await QuotaRun.findOne({ weekLabel }).lean().catch(error => {
        console.error('[QuotaRun] Could not load the stored weekly run:', error.message);
        return null;
      });
      pending = storedRun?.summary?.pendingConsequences || null;
      if (pending) {
        console.log(`♻️ Recovered pending quota consequences for ${weekLabel} from the stored weekly run.`);
        pendingQuotaConsequences.set(weekLabel, pending);
      }
    }

    if (!pending) {
      return interaction.editReply({ content: `⚠️ No pending quota data found for **${weekLabel}**. It may have already been approved, or the weekly report needs to be re-run (that week is not marked pending anymore).` });
    }

    const guild = interaction.guild;
    let issued = 0, skipped = 0;
