if (commandName === 'shiftcoverage') {
  const viewerRank = await getVerifiedMainRankForDiscord(interaction.user.id);
  if (!viewerRank || viewerRank.rank < 8) {
    return interaction.editReply('❌ You must be a verified Shift Lead or higher to view shift coverage.');
  }

  const targetUser = interaction.options.getUser('user');
  if (targetUser) {
    if (targetUser.id !== interaction.user.id && viewerRank.rank < 12) {
      return interaction.editReply('❌ Only Manager+ may view another staff member’s reliability record.');
    }
    const record = await ShiftReliability.findOne({ discordId: targetUser.id }).lean();
    if (!record) return interaction.editReply('No shift reliability record exists for that member yet.');

    const accountable = Math.max(
      0,
      Number(record.scheduled || 0) - Number(record.cancelled || 0) + Number(record.covered || 0),
    );
    const completionRate = accountable > 0
      ? Math.round((Number(record.completed || 0) / accountable) * 100)
      : 100;
    const embed = new EmbedBuilder()
      .setColor(completionRate >= 80 ? 0x57f287 : completionRate >= 60 ? 0xffc107 : 0xed4245)
      .setTitle('Shift Reliability Record')
      .setDescription(`${targetUser} • **${record.robloxUsername || 'Unknown Roblox account'}**`)
      .addFields(
        { name: 'Scheduled', value: String(record.scheduled || 0), inline: true },
        { name: 'Completed', value: String(record.completed || 0), inline: true },
        { name: 'Completion Rate', value: `${completionRate}%`, inline: true },
        { name: 'Cancelled', value: String(record.cancelled || 0), inline: true },
        { name: 'Missed / No-show', value: String(record.missed || 0), inline: true },
        { name: 'Standby Coverages', value: String(record.covered || 0), inline: true },
      )
      .setFooter({ text: 'This record is operational context, not an automatic consequence.' })
      .setTimestamp(record.updatedAt || new Date());
    return interaction.editReply({ embeds: [embed] });
  }

  const today = getESTDate();
  const postInfo = shiftPosts.get(today);
  if (!postInfo) return interaction.editReply('Today’s shift coverage post is not available yet.');
  const claims = postInfo.claims || [];
  const standbys = postInfo.standbys || [];
  const now = Date.now();
  const activeClaims = claims.filter(claim => claim.status !== 'cancelled');
  const upcoming = activeClaims
    .filter(claim => new Date(claim.scheduledAt).getTime() > now)
    .sort((a, b) => new Date(a.scheduledAt) - new Date(b.scheduledAt))
    .slice(0, 10);
  const completed = activeClaims.filter(claim => claim.status === 'completed').length;
  const atRisk = activeClaims.filter(claim => ['no_show', 'replacement_assigned', 'uncovered'].includes(claim.status)).length;
  const waitingStandbys = standbys.filter(entry => entry.status === 'waiting').length;

  const embed = new EmbedBuilder()
    .setColor(0x5bc0de)
    .setTitle(`Shift Coverage — ${formatDateForDisplay(today)}`)
    .addFields(
      { name: 'Claimed Slots', value: `${postInfo.claimCount}/${SHIFT_CLAIMING_CONFIG.MAX_SHIFTS_PER_DAY}`, inline: true },
      { name: 'Completed', value: String(completed), inline: true },
      { name: 'At Risk / Uncovered', value: String(atRisk), inline: true },
      { name: 'Waiting Standbys', value: String(waitingStandbys), inline: true },
      {
        name: 'Next Shifts',
        value: upcoming.length
          ? upcoming.map(claim =>
              `• **${formatShiftClaimTitle(claim)}** — <@${claim.replacementDiscordId || claim.discordId}> (${claim.status.replaceAll('_', ' ')})`,
            ).join('\n')
          : 'No upcoming claimed shifts.',
        inline: false,
      },
    )
    .setTimestamp();
  return interaction.editReply({ embeds: [embed] });
}

if (commandName === 'handbook') {
  const question = interaction.options.getString('question', true).trim();
  const result = await answerHandbookQuestion(interaction.user.id, question);

  if (result.type === 'confidential') {
    return interaction.editReply({
      embeds: [
        new EmbedBuilder()
          .setColor(0xed4245)
          .setTitle('Confidential Information')
          .setDescription(result.content)
          .setFooter({ text: `Required access: ${result.accessLabel}` }),
      ],
    });
  }

  if (result.type === 'unknown') {
    return interaction.editReply({
      embeds: [
        new EmbedBuilder()
          .setColor(0xffc107)
          .setTitle('No Approved Answer Found')
          .setDescription(result.content),
      ],
    });
  }

  return interaction.editReply({
    embeds: [
      new EmbedBuilder()
        .setColor(0x5bc0de)
        .setTitle(result.section.title)
        .setDescription(result.content)
        .addFields({
          name: 'Source',
          value:
            `${result.section.guide.label} • ${handbookAccessLabel(result.section.guide)}` +
            (result.section.slideNumber ? ` • Slide ${result.section.slideNumber}` : ""),
          inline: false,
        })
        .setFooter({
          text: 'Answers are limited to approved handbook material and inherit its confidentiality level.',
        }),
    ],
  });
}

if (commandName === 'supportblacklist') {
  const issuerRank = await getVerifiedMainRankForDiscord(interaction.user.id);
  if (!issuerRank || issuerRank.rank < SWEETSIEZ_STRUCTURE_CONFIG.EXECUTIVE_BOARD_RANK) {
    return interaction.editReply('❌ You must be verified as Executive+ (rank 13+) to manage support blacklists.');
  }

  const subcommand = interaction.options.getSubcommand();
  const targetUser = interaction.options.getUser('user');
  const status = getSupportBlacklistStatus(targetUser.id);

  if (subcommand === 'check') {
    const embed = new EmbedBuilder()
      .setTitle('Support Blacklist Check')
      .setColor(status.isBlacklisted ? 0xff0000 : 0x00cc66)
      .addFields(
        { name: 'User', value: `${targetUser.tag} (${targetUser.id})`, inline: false },
        { name: 'Status', value: status.isBlacklisted ? `Blacklisted - Case ${status.latest.caseId}` : 'Not blacklisted', inline: false }
      )
      .setTimestamp();

    return interaction.editReply({ embeds: [embed] });
  }

  if (subcommand === 'add') {
    if (status.isBlacklisted) {
      return interaction.editReply(`❌ ${targetUser.tag} is already support blacklisted. Case ${status.latest.caseId}.`);
    }

    const reason = interaction.options.getString('reason');
    const evidence = interaction.options.getString('evidence') || 'No evidence provided';
    const caseRecord = nextCase('SupportBlacklist', interaction.user.id, targetUser.id, reason, {
      evidence,
      targetTag: targetUser.tag,
      issuedByTag: interaction.user.tag,
    });

    await logSupportBlacklistAction(interaction.guild, 'Support Blacklist Added', 0x000000, [
      { name: 'Case ID', value: String(caseRecord.caseId), inline: true },
      { name: 'User', value: `${targetUser.tag} (${targetUser.id})`, inline: true },
      { name: 'Issued By', value: `${interaction.user.tag}`, inline: true },
      { name: 'Reason', value: reason.substring(0, 1024), inline: false },
      { name: 'Evidence', value: evidence.substring(0, 1024), inline: false },
    ]);

    await sendModLog(interaction.guild, { ...caseRecord, color: 0x000000 });
    return interaction.editReply(`✅ ${targetUser.tag} has been blacklisted from the Support System. Case ${caseRecord.caseId}.`);
  }

  if (subcommand === 'remove') {
    if (!status.isBlacklisted) {
      return interaction.editReply(`❌ ${targetUser.tag} is not currently support blacklisted.`);
    }

    const reason = interaction.options.getString('reason') || 'No reason provided';
    updateCaseExtra(status.latest, {
      revokedAt: new Date().toISOString(),
      revokedBy: interaction.user.id,
      revokedByTag: interaction.user.tag,
      revokeReason: reason,
    });

    const caseRecord = nextCase('SupportBlacklistRemove', interaction.user.id, targetUser.id, reason, {
      targetTag: targetUser.tag,
      issuedByTag: interaction.user.tag,
      removedCaseId: status.latest.caseId,
    });

    await logSupportBlacklistAction(interaction.guild, 'Support Blacklist Removed', 0x00cc66, [
      { name: 'Case ID', value: String(caseRecord.caseId), inline: true },
      { name: 'Original Case', value: String(status.latest.caseId), inline: true },
      { name: 'User', value: `${targetUser.tag} (${targetUser.id})`, inline: true },
      { name: 'Removed By', value: `${interaction.user.tag}`, inline: true },
      { name: 'Reason', value: reason.substring(0, 1024), inline: false },
    ]);

    await sendModLog(interaction.guild, { ...caseRecord, color: 0x00cc66 });
    return interaction.editReply(`✅ ${targetUser.tag} has been removed from the Support System blacklist. Case ${caseRecord.caseId}.`);
  }
}

