// 12. TRIVIA COMMAND
if (interaction.commandName === 'trivia') {
  const question = TRIVIA_QUESTIONS[Math.floor(Math.random() * TRIVIA_QUESTIONS.length)];
  await interaction.editReply(`🧩 **Trivia Time!**\n\n${question.q}\n*(Reply with the answer in the next 15 seconds)*`);

  const filter = m => m.author.id === interaction.user.id;
  const collector = interaction.channel.createMessageCollector({ filter, time: 15000, max: 1 });

  collector.on('collect', async m => {
    if (m.content.toLowerCase() === question.a.toLowerCase()) {
      const robloxUsername = verifiedUsers.get(interaction.user.id);
      if (!robloxUsername) {
        return m.reply("❌ You must be verified to earn credits.");
      }
      // Read live balance straight from the Roblox DataStore
      const currentBalance = await getDataStoreCredits(robloxUsername);
      if (currentBalance === null) {
        return m.reply("❌ Could not find your Roblox account.");
      }
      const newBalance = currentBalance + 50;
      // Write back to DataStore (source of truth) AND mirror to MongoDB
      await setDataStoreCredits(robloxUsername, newBalance);
      await mirrorBalanceToMongo(robloxUsername, newBalance);
      m.reply(`✅ Correct! You earned **50 credits**. New balance: **${newBalance.toLocaleString()} credits**`);
    } else {
      m.reply(`❌ Incorrect. The answer was **${question.a}**.`);
    }
  });
}

// 15. AUDIT SEARCH (Pagination)
if (interaction.commandName === 'auditsearch') {
  const query = interaction.options.getString('query')?.toLowerCase();
  const actionFilter = interaction.options.getString('action');
  
  let filtered = cases.records;
  if (query) {
    filtered = filtered.filter(r => r.targetUserId.includes(query) || r.reason.toLowerCase().includes(query));
  }
  if (actionFilter) {
    filtered = filtered.filter(r => r.action === actionFilter);
  }

  if (filtered.length === 0) return interaction.editReply("No cases found.");

  const generateAuditEmbed = (page) => {
    const start = page * 5;
    const items = filtered.slice(start, start + 5);
    const embed = new EmbedBuilder()
      .setTitle(`🔎 Audit Search Results (${filtered.length})`)
      .setFooter({ text: `Page ${page + 1} of ${Math.ceil(filtered.length / 5)}` });
    
    items.forEach(r => {
      embed.addFields({ name: `Case #${r.caseId} | ${r.action}`, value: `**Target:** <@${r.targetUserId}>\n**Reason:** ${r.reason}` });
    });
    return embed;
  };

  let currentPage = 0;
  const row = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId('prev_audit').setLabel('⬅️').setStyle(ButtonStyle.Secondary),
    new ButtonBuilder().setCustomId('next_audit').setLabel('➡️').setStyle(ButtonStyle.Secondary)
  );

  const msg = await interaction.editReply({ embeds: [generateAuditEmbed(0)], components: [row] });
  const collector = msg.createMessageComponentCollector({ time: 60000 });

// AFTER
  collector.on('collect', async i => {
    if (i.customId === 'next_audit' && (currentPage + 1) * 5 < filtered.length) currentPage++;
    if (i.customId === 'prev_audit' && currentPage > 0) currentPage--;
    await i.update({ embeds: [generateAuditEmbed(currentPage)], components: [row] }).catch(console.error);
  });
}

