// 18. ADMIN BULK OPERATIONS
if (interaction.commandName === 'admin' && interaction.options.getSubcommand() === 'bulk') {
  const context = await getBoardSystemContext(interaction);
  if (context.rank < SWEETSIEZ_STRUCTURE_CONFIG.MANAGER_RANK) {
    return interaction.editReply("You need Manager rank or higher for bulk operations.");
  }

  const operation = interaction.options.getSubcommandGroup();
  
  if (operation === 'archive') {
    const requestType = interaction.options.getString('type');
    const daysOld = interaction.options.getInteger('days_old') || 30;
    const cutoff = new Date(Date.now() - daysOld * 24 * 60 * 60 * 1000);
    
    let model;
    if (requestType === 'graphics') model = GraphicsRequest;
    else if (requestType === 'announcement') model = AnnouncementRequest;
    else if (requestType === 'filming') model = FilmingSession;
    else return interaction.editReply("Invalid request type.");

    const updateResult = await model.updateMany(
      { status: 'completed', updatedAt: { $lte: cutoff } },
      { status: 'archived', updatedAt: new Date() }
    );

    const operation = await createBulkOperation(
      'archive',
      interaction.user.id,
      interaction.user.tag,
      [{ type: requestType, archived: updateResult.modifiedCount }]
    );

    return interaction.editReply(`✅ **${updateResult.modifiedCount}** ${requestType} requests archived. Operation ID: ${operation.operationId}`);
  }
}

// 19. REQUEST SEARCH & FILTERING
if (interaction.commandName === 'search') {
  const requestType = interaction.options.getString('type');
  const status = interaction.options.getString('status');
  const handler = interaction.options.getUser('handler');
  const requester = interaction.options.getUser('requester');
  
  let model;
  if (requestType === 'graphics') model = GraphicsRequest;
  else if (requestType === 'announcement') model = AnnouncementRequest;
  else if (requestType === 'filming') model = FilmingSession;
  else return interaction.editReply("Invalid request type.");

  const query = {};
  if (status) query.status = status;
  if (handler) query.assignedToDiscordId = handler.id;
  if (requester) query.requestedByDiscordId = requester.id;

  const results = await model.find(query).sort({ createdAt: -1 }).limit(25);

  if (results.length === 0) {
    return interaction.editReply("No requests found matching those criteria.");
  }

  const embed = new EmbedBuilder()
    .setTitle(`🔍 ${requestType.charAt(0).toUpperCase() + requestType.slice(1)} Requests (${results.length})`)
    .setColor(0x5bc0de);

  results.slice(0, 10).forEach(r => {
    const requestId = r.requestId || r.sessionId;
    const title = r.purpose || r.title || r.name || "Untitled";
    embed.addFields({
      name: `${requestId} | ${r.status?.toUpperCase() || "PENDING"}`,
      value: `**${title}**\nHandler: ${r.assignedToDiscordId ? `<@${r.assignedToDiscordId}>` : "Unassigned"}\nRequester: <@${r.requestedByDiscordId || r.createdByDiscordId}>`,
      inline: false
    });
  });

  if (results.length > 10) {
    embed.setFooter({ text: `Showing 10 of ${results.length} results` });
  }

  return interaction.editReply({ embeds: [embed] });
}

