          if (commandName === 'reset') {
  // Double-check admin permission server-side (belt + braces on top of setDefaultMemberPermissions)
  if (!interaction.member.permissions.has(PermissionFlagsBits.Administrator)) {
    return interaction.editReply({ content: '❌ You need **Administrator** permission to use this command.', ephemeral: true });
  }

  const type       = interaction.options.getString('type');   // 'invites' | 'messages' | 'xp' | 'all'
  const targetUser = interaction.options.getUser('user');     // null = whole server

  // Build the MongoDB $set payload
  const resetFields = {};
  if (type === 'invites' || type === 'all') resetFields.invites  = 0;
  if (type === 'messages' || type === 'all') resetFields.messages = 0;
  if (type === 'xp'       || type === 'all') { resetFields.xp = 0; resetFields.level = 1; }

  const typeLabel = { invites: 'Invites', messages: 'Messages', xp: 'XP & Level', all: 'All Stats' }[type];

  if (targetUser) {
    // ── Single user reset ──────────────────────────────────────────────────
    await UserStats.findOneAndUpdate(
      { userId: targetUser.id },
      { $set: resetFields },
      { upsert: true }
    );

    // Bust the in-memory cache so the next read reflects the reset
    if (userStatsCache.has(targetUser.id)) {
      const cached = userStatsCache.get(targetUser.id);
      Object.assign(cached, resetFields);
    }

    const embed = new EmbedBuilder()
      .setTitle('🔄 Stats Reset')
      .setColor(0xff6b6b)
      .setDescription(`Successfully reset **${typeLabel}** for <@${targetUser.id}>.`)
      .addFields({ name: 'Reset by', value: `<@${interaction.user.id}>`, inline: true })
      .setTimestamp();

    console.log(`🔄 [Reset] ${interaction.user.tag} reset ${typeLabel} for ${targetUser.tag}`);
    return interaction.editReply({ embeds: [embed] });

  } else {
    // ── Whole server reset ─────────────────────────────────────────────────
    // Require a confirmation button before wiping everything
    const confirmRow = new ActionRowBuilder().addComponents(
      new ButtonBuilder()
        .setCustomId(`reset_confirm_${type}_${interaction.user.id}`)
        .setLabel(`Yes, reset ${typeLabel} for everyone`)
        .setStyle(ButtonStyle.Danger),
      new ButtonBuilder()
        .setCustomId(`reset_cancel_${interaction.user.id}`)
        .setLabel('Cancel')
        .setStyle(ButtonStyle.Secondary),
    );

    const confirmEmbed = new EmbedBuilder()
      .setTitle('⚠️ Confirm Server-Wide Reset')
      .setColor(0xff9900)
      .setDescription(`You are about to reset **${typeLabel}** for **every user** in the server.\n\nThis **cannot be undone.** Are you sure?`)
      .setTimestamp();

    const reply = await interaction.editReply({ embeds: [confirmEmbed], components: [confirmRow] });

    // Wait up to 30s for the confirmation click
    const collector = reply.createMessageComponentCollector({ time: 30_000 });

    collector.on('collect', async (btn) => {
      // Only the person who ran the command can confirm/cancel
      if (btn.user.id !== interaction.user.id) {
        return btn.reply({ content: '❌ Only the person who ran this command can confirm it.', ephemeral: true });
      }

      await btn.deferUpdate();

      if (btn.customId.startsWith('reset_confirm_')) {
        await UserStats.updateMany({}, { $set: resetFields });
        userStatsCache.clear(); // Wipe entire cache

        const doneEmbed = new EmbedBuilder()
          .setTitle('✅ Server-Wide Reset Complete')
          .setColor(0xff6b6b)
          .setDescription(`**${typeLabel}** has been reset to zero for all users.`)
          .addFields({ name: 'Reset by', value: `<@${interaction.user.id}>`, inline: true })
          .setTimestamp();

        console.log(`🔄 [Reset] ${interaction.user.tag} reset ${typeLabel} for the ENTIRE SERVER`);
        await interaction.editReply({ embeds: [doneEmbed], components: [] });

      } else {
        // Cancelled
        const cancelEmbed = new EmbedBuilder()
          .setTitle('❎ Reset Cancelled')
          .setColor(0xaaaaaa)
          .setDescription('No changes were made.')
          .setTimestamp();

        await interaction.editReply({ embeds: [cancelEmbed], components: [] });
      }

      collector.stop();
    });

    collector.on('end', (_, reason) => {
      if (reason === 'time') {
        interaction.editReply({
          embeds: [
            new EmbedBuilder()
              .setTitle('⏰ Reset Timed Out')
              .setColor(0xaaaaaa)
              .setDescription('Confirmation not received within 30 seconds. No changes were made.')
              .setTimestamp()
          ],
          components: []
        }).catch(() => {});
      }
    });

    return; // reply already sent above
  }
}

          if (commandName === 'leaderboard') {
  const subcommand = interaction.options.getSubcommand(); // 'messages', 'invites', or 'exp'
  
  let sortField, title, color, unit;
  switch (subcommand) {
    case 'messages':
      sortField = 'messages';
      title = 'Top Message Senders';
      color = 0x3498db;
      unit = 'messages';
      break;
    case 'invites':
      sortField = 'invites';
      title = 'Top Inviters';
      color = 0x9b59b6;
      unit = 'invites';
      break;
    case 'exp':
      sortField = 'xp';
      title = 'Top XP Earners';
      color = 0x00ff00;
      unit = 'XP';
      break;
    default:
      return interaction.editReply('Invalid leaderboard type.');
  }
  
  // Fetch top 10 from database, sorted descending
  const topUsers = await UserStats.find()
    .sort({ [sortField]: -1 })
    .limit(10)
    .lean();
  
  if (topUsers.length === 0) {
    return interaction.editReply('No data available yet. Start chatting in #community!');
  }
  
  // Build leaderboard text
  let description = '';
  for (let i = 0; i < topUsers.length; i++) {
    const user = topUsers[i];
    const discordUser = await client.users.fetch(user.userId).catch(() => null);
    const username = discordUser ? discordUser.username : `Unknown (${user.userId})`;
    const value = subcommand === 'exp' ? user.xp.toLocaleString() : user[sortField].toLocaleString();
    const medal = i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : `${i + 1}.`;
    description += `${medal} **${username}** — ${value} ${unit}\n`;
  }
  
  const embed = new EmbedBuilder()
    .setTitle(`🏆 ${title}`)
    .setDescription(description)
    .setColor(color)
    .setFooter({ text: 'Updated in real time' })
    .setTimestamp();
  
  return interaction.editReply({ embeds: [embed] });
}
          
