          let unverifiedCleaned = 0;
          let unverifiedNoRoles = 0;
          let staffDepartureTerminations = 0;
          let botsSkipped = 0;
          let failed = 0;
          const failures = [];

          let processed = 0;

          for (const [memberId, member] of allMembers) {
            // Skip bots
            if (member.user.bot) {
              botsSkipped++;
              continue;
            }

            try {
              const isVerified = verifiedUsers.has(memberId);

              if (isVerified) {
                // Verified user - sync their roles
                const robloxUsername = verifiedUsers.get(memberId);
                const userId = await getRobloxUserId(robloxUsername);

                if (userId) {
                  const membershipStatus = await getMainGroupMembershipStatus(userId);
                  if (!membershipStatus.ok) {
                    failed++;
                    failures.push({
                      username: robloxUsername,
                      discordTag: member.user.tag,
                      reason: 'Roblox membership lookup failed'
                    });
                    continue;
                  }

                  const rankInfo = membershipStatus.inGroup
                    ? { rank: membershipStatus.rank, name: membershipStatus.name }
                    : null;

                  if (!membershipStatus.inGroup) {
                    const departureContext = await getStaffDepartureContext(memberId, member);
                    const departureResult = await handleVerifiedStaffLeftRobloxGroup({
                      member,
                      discordId: memberId,
                      robloxUsername,
                      robloxUserId: userId,
                      departureContext,
                    });
                    if (departureResult.processed) staffDepartureTerminations++;
                  }

                  await updateDiscordRoles(member, rankInfo?.rank || 0, userId);
                  await updateDiscordNickname(member, robloxUsername);
                  verifiedUpdated++;
                } else {
                  failed++;
                  failures.push({
                    username: robloxUsername,
                    discordTag: member.user.tag,
                    reason: 'Could not find Roblox account'
                  });
                }
              } else {
                // Unverified user - remove ALL bound roles (including "Verified")
                const rolesToRemove = [];
                member.roles.cache.forEach((role) => {
                  if (allBoundRoleNames.has(role.name) || allManagedRoleIds.has(role.id)) {
                    rolesToRemove.push(role);
                  }
                });

                let unverifiedChanged = false;
                if (rolesToRemove.length > 0) {
                  await member.roles.remove(rolesToRemove, 'Unverified - removing bound roles');
                  unverifiedChanged = true;
                }
                const unverifiedRole = member.guild.roles.cache.get(VERIFICATION_THREAD_CONFIG.UNVERIFIED_ROLE_ID);
                if (unverifiedRole && !member.roles.cache.has(unverifiedRole.id)) {
                  await member.roles.add(unverifiedRole, 'Unverified member role');
                  unverifiedChanged = true;
                }
                if (unverifiedChanged) {
                  unverifiedCleaned++;
                } else {
                  unverifiedNoRoles++;
                }
              }

              processed++;

              // Update progress every 25 members
              if (processed % 25 === 0) {
                const progressEmbed = new EmbedBuilder()
                  .setTitle('🔄 Updating All Server Members')
                  .setDescription(`**Total Members:** ${allMembers.size}\n**Status:** Processing... ${processed}/${allMembers.size - botsSkipped}`)
                  .addFields(
                    { name: '✅ Verified Updated', value: `${verifiedUpdated}`, inline: true },
                    { name: '🧹 Unverified Cleaned', value: `${unverifiedCleaned}`, inline: true },
                    { name: 'Auto Staff Terminations', value: `${staffDepartureTerminations}`, inline: true },
                    { name: '⚪ No Roles to Remove', value: `${unverifiedNoRoles}`, inline: true },
                    { name: '🤖 Bots Skipped', value: `${botsSkipped}`, inline: true },
                    { name: '❌ Failed', value: `${failed}`, inline: true }
                  )
                  .setColor(0xffa500)
                  .setFooter({ text: `Started by ${interaction.user.tag}` })
                  .setTimestamp();

                await interaction.editReply({ embeds: [progressEmbed] }).catch(() => { });
              }

            } catch (error) {
              failed++;
              failures.push({
                username: member.user.tag,
                discordTag: member.user.tag,
                reason: error.message
              });

              console.error(`Failed to update ${member.user.tag}:`, error);
            }
          }

          // Final status embed
          const finalEmbed = new EmbedBuilder()
            .setTitle('✅ Server Update Complete')
            .setDescription(`**Total Members Processed:** ${processed}`)
            .addFields(
              { name: '📊 Summary', value: `**Verified Members Updated:** ${verifiedUpdated}\n**Unverified Members Cleaned:** ${unverifiedCleaned}\n**Auto Staff Terminations:** ${staffDepartureTerminations}\n**Unverified (No Roles):** ${unverifiedNoRoles}\n**Bots Skipped:** ${botsSkipped}\n**Failed:** ${failed}`, inline: false }
            )
            .setColor(failed === 0 ? 0x00ff00 : (verifiedUpdated + unverifiedCleaned > 0 ? 0xffa500 : 0xff0000))
            .setFooter({ text: `Completed by ${interaction.user.tag}` })
            .setTimestamp();

          // Add list of failures if any
          if (failures.length > 0) {
            const failureList = failures
              .slice(0, 10)
              .map(f => `• ${f.discordTag}\n  Reason: ${f.reason.substring(0, 50)}`)
              .join('\n');

            const failureText = failures.length > 10
              ? `${failureList}\n*...and ${failures.length - 10} more*`
              : failureList;

            finalEmbed.addFields({
              name: '❌ Failed Updates',
              value: failureText.substring(0, 1024),
              inline: false
            });
          }

          await interaction.editReply({ embeds: [finalEmbed] });

          // Log to mod log
          const caseRecord = nextCase(
            'BulkServerUpdate',
            interaction.user.id,
            interaction.user.id,
            `Updated ${verifiedUpdated} verified users, cleaned ${unverifiedCleaned} unverified users`,
            {
              totalProcessed: processed,
              verifiedUpdated: verifiedUpdated,
              unverifiedCleaned: unverifiedCleaned,
              unverifiedNoRoles: unverifiedNoRoles,
              botsSkipped: botsSkipped,
              failed: failed
            }
          );

          await sendModLog(guild, {
            ...caseRecord,
            color: 0x3498db
          });

          return;
