    if (!banList.size) {
      return interaction.editReply('❌ There are no banned users in this server.');
    }

    // Collect bans issued by the target moderator via audit logs
    const bannedByMod = new Set();
    let lastEntryId = undefined;

    // Audit logs only go back 90 days and are paginated (max 100 per request)
    let keepFetching = true;
    while (keepFetching) {
      const logs = await guild.fetchAuditLogs({
        type: 22, // AuditLogEvent.MemberBanAdd
        limit: 100,
        before: lastEntryId,
      });

      if (!logs.entries.size) break;

      for (const entry of logs.entries.values()) {
        if (entry.executor?.id === targetMod.id && banList.has(entry.target?.id)) {
          bannedByMod.add(entry.target.id);
        }
        lastEntryId = entry.id;
      }

      // Stop if we've fetched fewer than 100 entries (last page)
      if (logs.entries.size < 100) keepFetching = false;
    }

    if (!bannedByMod.size) {
      return interaction.editReply(`❌ No active bans found that were issued by **${targetMod.tag}**.\n> Note: Audit logs only go back 90 days.`);
    }

    // Process unbans with rate limit protection
    let successCount = 0;
    let failCount = 0;

    for (const userId of bannedByMod) {
      try {
        const bannedUser = banList.get(userId)?.user;
        await guild.members.unban(userId, reason);

        // Log each unban as its own case (matches your existing unban pattern)
        const caseRecord = nextCase('Unban', issuer.id, userId, reason);
        await sendModLog(guild, { ...caseRecord, color: 0x00aa00 });

        successCount++;

        // Rate limit protection: small delay every 5 unbans
        if (successCount % 5 === 0) {
          await new Promise(res => setTimeout(res, 1000));
        }
      } catch {
        failCount++;
      }
    }

    // Final summary
