// ========================================
// COUNTING SYSTEM
// ========================================

const COUNTING_CHANNEL_ID = '1172778155958865981';

// In-memory cache — loaded from MongoDB on startup, written back on every change
let countingCurrent = 0;
let countingLastUserId = null;
let countingStateLoaded = false;
let countingStateLoadPromise = null;
const countingMessageCache = new Map();

async function loadCountingState() {
  if (countingStateLoadPromise) return countingStateLoadPromise;

  countingStateLoadPromise = (async () => {
    try {
      const doc = await CountingState.findOne({ channelId: COUNTING_CHANNEL_ID });
      if (doc) {
        countingCurrent = Number(doc.current) || 0;
        countingLastUserId = doc.lastUserId || null;
      }
      countingStateLoaded = true;
      console.log(`✅ Loaded counting state from MongoDB (current: ${countingCurrent})`);
    } catch (err) {
      countingStateLoaded = false;
      console.error('Error loading counting state:', err.message);
    } finally {
      countingStateLoadPromise = null;
    }
  })();

  return countingStateLoadPromise;
}

async function ensureCountingStateLoaded() {
  if (countingStateLoaded) return true;
  if (mongoose.connection.readyState !== 1) {
    console.warn('Skipping counting message because MongoDB state has not loaded yet.');
    return false;
  }

  await loadCountingState();
  return countingStateLoaded;
}

async function saveCountingState() {
  try {
    await CountingState.findOneAndUpdate(
      { channelId: COUNTING_CHANNEL_ID },
      { channelId: COUNTING_CHANNEL_ID, current: countingCurrent, lastUserId: countingLastUserId, updatedAt: new Date() },
      { upsert: true }
    );
  } catch (err) {
    console.error('Error saving counting state:', err.message);
  }
}

// Special number reactions: number -> { reactions: [], message: string|null }
const COUNTING_SPECIAL = {
  69:   { reactions: ['😏', '🍆', '💦'], message: 'nice.' },
  420:  { reactions: ['🌿', '😮‍💨'],     message: '🌿 blaze it' },
  42:   { reactions: ['🌌', '🤔'],       message: "the answer to life, the universe, and everything" },
  67:   { reactions: ['😔'],             message: 'so close...' },
  100:  { reactions: ['💯'],             message: '💯 let\'s gooo!' },
  200:  { reactions: ['🔥', '💯'],       message: '200?? you guys are cooking 🔥' },
  300:  { reactions: ['🔥', '🔥'],       message: '300 — THIS IS SPARTA 🛡️' },
  404:  { reactions: ['❓', '💀'],       message: 'count not found' },
  500:  { reactions: ['🏆'],             message: '500!! halfway to a thousand 🏆' },
  666:  { reactions: ['😈', '🔥'],       message: 'uh oh 😈' },
  777:  { reactions: ['🎰', '🍀'],       message: 'lucky number 777 🎰' },
  1000: { reactions: ['🎉', '🏆', '🎊'], message: '**1000!!!!** LETS GOOOOO 🎉🏆🎊' },
};

// Every 100 gets a reaction too (handled dynamically)
function getCountingReactions(n) {
  if (COUNTING_SPECIAL[n]) return COUNTING_SPECIAL[n];
  if (n % 1000 === 0) return { reactions: ['🎉', '🏆', '🎊'], message: `**${n.toLocaleString()}!!** incredible 🏆` };
  if (n % 100 === 0)  return { reactions: ['💯', '🎉'],       message: `${n} — another hundred down! 🎉` };
  return null;
}

function parseCountingNumberContent(content) {
  if (typeof content !== 'string') return null;
  const trimmed = content.trim();
  if (!trimmed) return null;
  const num = parseInt(trimmed, 10);
  return !Number.isNaN(num) && String(num) === trimmed ? num : null;
}

function rememberCountingMessage(message) {
  const num = parseCountingNumberContent(message.content);
  if (num === null || message.channel.id !== COUNTING_CHANNEL_ID || message.author?.bot) return;

  countingMessageCache.set(message.id, {
    authorId: message.author.id,
    content: message.content.trim(),
    number: num,
  });

  while (countingMessageCache.size > 1000) {
    const oldestKey = countingMessageCache.keys().next().value;
    countingMessageCache.delete(oldestKey);
  }
}

function getCountingSnapshot(message) {
  if (message.channel?.id !== COUNTING_CHANNEL_ID) return null;
  const cached = countingMessageCache.get(message.id);
  const content = message.content || cached?.content;
  const authorId = message.author?.id || cached?.authorId;
  if (!content || !authorId || message.author?.bot) return null;

  const number = parseCountingNumberContent(content);
  if (number === null) return null;
  return { authorId, content: String(content).trim(), number };
}

async function sendCountingTamperNotice(channel, authorId, actionText) {
  if (!(await ensureCountingStateLoaded())) return;
  await channel.send(`👀 <@${authorId}> ${actionText}. The next number is **${countingCurrent + 1}**.`);
}

async function handleCountingMessageDelete(message) {
  const snapshot = getCountingSnapshot(message);
  countingMessageCache.delete(message.id);
  if (!snapshot) return;

  await sendCountingTamperNotice(
    message.channel,
    snapshot.authorId,
    `deleted **${snapshot.content}** in counting. Nice try`
  );
}

async function handleCountingBulkDelete(messages, channel) {
  if (channel?.id !== COUNTING_CHANNEL_ID) return;

  const deletedNumbers = [];
  for (const message of messages.values()) {
    const snapshot = getCountingSnapshot(message);
    countingMessageCache.delete(message.id);
    if (snapshot) deletedNumbers.push(snapshot);
  }
  if (deletedNumbers.length === 0) return;
  if (!(await ensureCountingStateLoaded())) return;

  const preview = deletedNumbers
    .slice(0, 5)
    .map(snapshot => `<@${snapshot.authorId}> deleted **${snapshot.content}**`)
    .join(', ');
  const extra = deletedNumbers.length > 5 ? `, and ${deletedNumbers.length - 5} more` : '';
  await channel.send(`👀 Counting cleanup noticed: ${preview}${extra}. The next number is **${countingCurrent + 1}**.`);
}

async function handleCountingMessageUpdate(oldMsg, newMsg) {
  const snapshot = getCountingSnapshot(oldMsg);
  if (!snapshot) return;

  const newContent = typeof newMsg.content === 'string' ? newMsg.content.trim() : '[unknown]';
  if (snapshot.content === newContent) return;

  await sendCountingTamperNotice(
    oldMsg.channel,
    snapshot.authorId,
    `edited **${snapshot.content}** to **${newContent || '[empty]'}** in counting. Nice try`
  );

  const newNumber = parseCountingNumberContent(newContent);
  if (newNumber === null) {
    countingMessageCache.delete(oldMsg.id);
  } else {
    countingMessageCache.set(oldMsg.id, {
      authorId: snapshot.authorId,
      content: newContent,
      number: newNumber,
    });
  }
}

  client.on('messageCreate', async (message) => {
    try {
      if (await handleAppealDeliveryProofMessage(message).catch(error => {
        console.error("Appeal delivery proof handler failed:", error);
        return false;
      })) return;
      // ── COUNTING SYSTEM ───────────────────────────────────────────────────
      if (message.channel.id === COUNTING_CHANNEL_ID && !message.author.bot) {
        if (!(await ensureCountingStateLoaded())) return;

        const num = parseInt(message.content.trim(), 10);
        const isValidNumber = !isNaN(num) && String(num) === message.content.trim();
        if (isValidNumber) rememberCountingMessage(message);

        if (!isValidNumber) {
          // Non-number message in counting channel — delete it silently
          await message.delete().catch(() => {});
        } else if (message.author.id === countingLastUserId) {
          // Same person counted twice in a row
          await message.react('🤡').catch(() => {});
          await message.channel.send(`🤡 <@${message.author.id}> you can't count twice in a row! back to **1**`);
          countingCurrent = 0;
          countingLastUserId = null;
          await saveCountingState();
        } else if (num !== countingCurrent + 1) {
          // Wrong number
          const expected = countingCurrent + 1;
          await message.react('🤡').catch(() => {});
          await message.channel.send(`🤡 <@${message.author.id}> ruined it at **${countingCurrent}**! the next number was **${expected}**. back to **1**`);
          countingCurrent = 0;
          countingLastUserId = null;
          await saveCountingState();
        } else {
          // Correct!
          countingCurrent = num;
          countingLastUserId = message.author.id;
          await saveCountingState();

          const special = getCountingReactions(num);
          if (special) {
            for (const emoji of special.reactions) {
              await message.react(emoji).catch(() => {});
            }
            if (special.message) {
              await message.channel.send(special.message);
            }
          } else {
            await message.react('✅').catch(() => {});
          }
        }
        return;
      }

      // Handle shift claiming messages
      await handleShiftMessage(message, client);

      // Handle trial question answers
      if (message.channel.isThread()) {
        const trialData = activeTrials.get(message.channel.id);
        if (trialData && (trialData.stage === "questions" || trialData.pendingEdit !== undefined) && message.author.id === trialData.userId) {
          trialData.lastActivity = new Date().toISOString();

          // Handle pending edit first
          if (trialData.pendingEdit !== undefined) {
            const editIndex = trialData.pendingEdit;
            const question = TRIAL_QUESTIONS[editIndex];
            if (!checkAnswer(message.content, question)) {
              await message.react('⚠️');
              await message.channel.send("⚠️ Please provide a more detailed answer (at least 10 characters).");
              return;
            }
            const existingIdx = trialData.answers.findIndex(a => a.questionIndex === editIndex);
            if (existingIdx !== -1) {
              trialData.answers[existingIdx].answer = message.content;
              trialData.answers[existingIdx].timestamp = new Date().toISOString();
            }
            delete trialData.pendingEdit;
            await saveTrials();
            await message.react('✅');

            const editAckEmbed = new EmbedBuilder()
              .setTitle("✅ Answer Updated")
              .setDescription(`Your revised answer for Question ${editIndex + 1} has been recorded.`)
              .setColor(0x3498db);

            const editAnswerRow = new ActionRowBuilder().addComponents(
              new ButtonBuilder()
                .setCustomId(`trial_edit_answer_${message.channel.id}_${editIndex}`)
                .setLabel("✏️ Edit This Answer")
                .setStyle(ButtonStyle.Secondary)
            );

            await message.channel.send({ embeds: [editAckEmbed], components: [editAnswerRow] });
            return;
          }

          trialData.answers = normalizeTrialAnswers(trialData.answers);
          trialData.currentQuestion = resolveSavedTrialQuestionIndex(trialData);
          const currentQuestionIndex = trialData.currentQuestion;

          // Guard: if all questions are already answered, move to evaluation and stop
          if (currentQuestionIndex >= TRIAL_QUESTIONS.length) {
            await evaluateTrial(message.channel, trialData);
            return;
          }

          const question = TRIAL_QUESTIONS[currentQuestionIndex];

          // Guard: question is undefined if currentQuestion index is somehow out of sync
          if (!question) {
            await evaluateTrial(message.channel, trialData);
            return;
          }
          
          const isValid = checkAnswer(message.content, question);
          
          if (!isValid) {
            await message.react('⚠️');
            await message.channel.send("⚠️ Please provide a more detailed answer (at least 10 characters).");
            return;
          }
          
          // Store the answer
          const answerEntry = {
            questionIndex: currentQuestionIndex,
            question: question.question,
            answer: message.content,
            timestamp: new Date().toISOString()
          };
          const existingAnswerIndex = trialData.answers.findIndex(
            answer => Number(answer.questionIndex) === Number(currentQuestionIndex),
          );
          if (existingAnswerIndex === -1) {
            trialData.answers.push(answerEntry);
          } else {
            trialData.answers[existingAnswerIndex] = {
              ...trialData.answers[existingAnswerIndex],
              ...answerEntry,
            };
          }

          // Acknowledge receipt
          await message.react('✅');

          // Update last activity timestamp (used for inactivity ping)
          trialData.lastActivity = new Date().toISOString();

          const ackEmbed = new EmbedBuilder()
            .setTitle("✅ Answer Recorded")
            .setDescription("Your answer has been recorded and will be reviewed.")
            .setColor(0x3498db);

          // Add an "Edit Answer" button so the trialer can revise their response
          const editAnswerRow = new ActionRowBuilder().addComponents(
            new ButtonBuilder()
              .setCustomId(`trial_edit_answer_${message.channel.id}_${currentQuestionIndex}`)
              .setLabel("✏️ Edit This Answer")
              .setStyle(ButtonStyle.Secondary)
          );

          await message.channel.send({ embeds: [ackEmbed], components: [editAnswerRow] });
          
          // Move to the next unanswered question. This survives bot restarts
          // because it derives from saved answers instead of trusting memory only.
          trialData.answers = normalizeTrialAnswers(trialData.answers);
          trialData.currentQuestion = getNextTrialQuestionIndex(trialData.answers);
          await saveTrials();
          
          // Small delay before next question
          setTimeout(async () => {
            await askTrialQuestion(message.channel, trialData, trialData.currentQuestion);
          }, 2000);
          
          return; // Don't process other handlers for trial messages
        }
      }
      
      // Ignore messages from bots
      if (message.author.bot && !message.webhookId && !APPEAL_CHANNELS.includes(message.channel.id) && !VOTES_CHANNELS.some(v => v.channelId === message.channel.id)) return;

      const normalizedMessageContent = (message.content || "").trim().toLowerCase();
      const reportCommand = `${config.PREFIX}report`.toLowerCase();
      const reportStatusMatch = (message.content || "").trim().match(/^!reportstatus\s+(RPT-[A-Z0-9-]+)$/i);
      const reportUpdateMatch = (message.content || "").trim().match(/^!reportupdate\s+(RPT-[A-Z0-9-]+)$/i);

      if (!message.author.bot && reportStatusMatch) {
        try {
          const destination = message.guild ? await message.author.createDM() : message.channel;
          await sendReportStatus(message.author, destination, reportStatusMatch[1]);
          if (message.guild) await message.delete().catch(() => {});
        } catch {
          await message.reply("I couldn't DM you. Please enable direct messages and try again.").catch(() => {});
        }
        return;
      }

      if (!message.author.bot && reportUpdateMatch) {
        try {
          const destination = message.guild ? await message.author.createDM() : message.channel;
          await startReportUpdateSession(message.author, destination, reportUpdateMatch[1]);
          if (message.guild) await message.delete().catch(() => {});
        } catch {
          await message.reply("I couldn't DM you. Please enable direct messages and try again.").catch(() => {});
        }
        return;
      }

      if (!message.author.bot && (normalizedMessageContent === reportCommand || normalizedMessageContent === "!report")) {
        if (message.guild) {
          try {
            const dmChannel = await message.author.createDM();
            await startReportSession(message.author, dmChannel);
            await message.delete().catch(() => {});
          } catch (error) {
            await message.reply(
              "I couldn't DM you. Please enable direct messages from server members, then try `!report` again."
            ).then(reply => setTimeout(() => reply.delete().catch(() => {}), 10000)).catch(() => {});
          }
        } else {
          await startReportSession(message.author, message.channel);
        }
        return;
      }

      if (!message.author.bot && (normalizedMessageContent === "!suggest" || normalizedMessageContent === "!bugreport")) {
        const type = normalizedMessageContent === "!bugreport" ? "bug" : "suggestion";
        if (message.guild) {
          try {
            const dmChannel = await message.author.createDM();
            await startDevelopmentSubmissionSession(message.author, dmChannel, type);
            await message.delete().catch(() => {});
          } catch (error) {
            await message.reply(
              `I couldn't DM you. Please enable direct messages from server members, then try \`${normalizedMessageContent}\` again.`
            ).then(reply => setTimeout(() => reply.delete().catch(() => {}), 10000)).catch(() => {});
          }
        } else {
          await startDevelopmentSubmissionSession(message.author, message.channel, type);
        }
        return;
      }

      if (!message.guild && (developmentSubmissionSessions.has(message.author.id) || normalizedMessageContent === "!devcancel")) {
        const handled = await handleDevelopmentSubmissionDM(message);
        if (handled) return;
      }

      if (!message.guild && reportUpdateSessions.has(message.author.id)) {
        await handleReportUpdateDM(message);
        return;
      }

      if (!message.guild && reportSessions.has(message.author.id)) {
        await handleReportDM(message);
        return;
      }

      if (message.channel.isThread?.() && activeTickets.has(message.channel.id)) {
        await touchTicketActivity(message.channel.id);
      }

      // ── DISCORD QUOTA MESSAGE TRACKING ───────────────────────────────────
      // Count messages from verified staff members toward their weekly Discord quota.
      if (message.guild && !message.author.bot && verifiedUsers.has(message.author.id)) {
        const today = getEasternDateString(); // YYYY-MM-DD in Eastern time
        const userMsgData = discordMessageCounts.get(message.author.id) || {};
        userMsgData[today] = (userMsgData[today] || 0) + 1;
        discordMessageCounts.set(message.author.id, userMsgData);
        await saveDiscordMessageCount(message.author.id, userMsgData);
      }

      // ── AUTOMOD: PHRASE & SPAM DETECTION ─────────────────────────────────
      if (message.guild && !message.author.bot) {
        const member = message.member || await message.guild.members.fetch(message.author.id).catch(() => null);

        if (member && !isAutomodExempt(member)) {
          const content = message.content || '';

          // ── Phrase check ──────────────────────────────────────────────────
          let triggeredRule = null;
          for (const rule of AUTOMOD_RULES) {
            if (rule.pattern.test(content)) {
              triggeredRule = rule;
              break;
            }
          }

          if (triggeredRule) {
            const deletedContent = content;

            // Delete the message first
            if (triggeredRule.action === 'delete' || triggeredRule.action === 'both') {
              await message.delete().catch(() => {});
            }

            // Warn + log
            if (triggeredRule.action === 'warn' || triggeredRule.action === 'both') {
              await handlePhraseViolation(client, message, triggeredRule, deletedContent);
            }

            return; // Don't process rest of messageCreate for this message
          }

          // ── Spam check ────────────────────────────────────────────────────
          const spamResult = checkSpam(message);
          if (spamResult.isSpam) {
            // Delete the triggering message
            await message.delete().catch(() => {});

            // Delete the last few messages from this user in this channel
            try {
              const msgs = await message.channel.messages.fetch({ limit: 20 });
              const userMsgs = msgs.filter(m => m.author.id === message.author.id).first(SPAM_CONFIG.MAX_MESSAGES);
              for (const m of userMsgs.values()) {
                await m.delete().catch(() => {});
              }
            } catch {}

            // Alert
            try {
              const alertCh = await client.channels.fetch(AUTOMOD_ALERT_CHANNEL_ID).catch(() => null);
              if (alertCh) {
                const { EmbedBuilder } = require('discord.js');
                const embed = new EmbedBuilder()
                  .setTitle('🤖 AutoMod — Spam Detected')
                  .setColor(0xff9900)
                  .addFields(
                    { name: '👤 User', value: message.author.tag + ' (<@' + message.author.id + '>)', inline: true },
                    { name: '📍 Channel', value: '<#' + message.channel.id + '>', inline: true },
                    { name: '📊 Reason', value: spamResult.reason, inline: false },
                  )
                  .setTimestamp();
                await alertCh.send({ embeds: [embed] });
              }
            } catch (err) {
              console.error('Spam alert error:', err.message);
            }

            // DM the user
            await message.author.send(
              '🤖 **AutoMod Notice**\n\nYour messages in **' + message.guild.name + '** were removed for spamming.\n' +
              '**Reason:** ' + spamResult.reason + '\n\nPlease slow down.'
            ).catch(() => {});

            return;
          }
        }
      }
      // ─────────────────────────────────────────────────────────────────────

        
        
        // XP & messages tracking (only in community channel)
      await trackGiveawayMessage(message);
      if (message.channel.id === config.COMMUNITY_CHANNEL_ID && !message.author.bot) {
  const userId = message.author.id;
  // Cooldown: avoid spam (e.g., 30 seconds between XP gains)
  const stats = userStatsCache.get(userId) || { lastMessageTimestamp: 0 };
  const now = Date.now();
  const cooldown = 30000; // 30 seconds
  if (now - (stats.lastMessageTimestamp || 0) >= cooldown) {
    const xpGain = Math.floor(Math.random() * 11) + 5; // 5–15 XP
    await addXP(userId, xpGain);
    // Update messages count
    let msgStats = userStatsCache.get(userId);
    if (!msgStats) {
      const doc = await UserStats.findOne({ userId });
      if (doc) msgStats = { xp: doc.xp, level: doc.level, messages: doc.messages, invites: doc.invites };
      else msgStats = { xp: 0, level: 0, messages: 0, invites: 0 };
      userStatsCache.set(userId, msgStats);
    }
    msgStats.messages++;
    msgStats.lastMessageTimestamp = now;
    // Save asynchronously
    UserStats.findOneAndUpdate(
      { userId },
      { $set: { messages: msgStats.messages, lastMessageTimestamp: new Date(now) } },
      { upsert: true }
    ).catch(err => console.error('Failed to update message count:', err));
  } else {
    // Still increment message count without XP (optional)
    let msgStats = userStatsCache.get(userId);
    if (msgStats) {
      msgStats.messages++;
      UserStats.findOneAndUpdate({ userId }, { $inc: { messages: 1 } }).catch(() => {});
    }
  }
}
      // --- APPEAL AUTO-THREAD & REACTION SYSTEM ---
      if (APPEAL_CHANNELS.includes(message.channel.id)) {
        // Only trigger if the message has an embed (typical for webhooks)
        if (message.embeds.length > 0 || message.webhookId) {
          try {
            await ensureAppealDecisionControls(message).catch(error => {
              console.error("Could not add appeal decision controls:", error.message);
            });
            await message.react('✅');
            await message.react('❎');

            const isDiscordAppealChannel = message.channel.id === SWEETSIEZ_STRUCTURE_CONFIG.CHANNELS.DMD_APPEAL_SUBMISSIONS;
            const thread = await message.startThread({
              name: isDiscordAppealChannel ? 'Discord Appeal Voting' : 'Appeal Voting',
              autoArchiveDuration: 1440,
              reason: isDiscordAppealChannel
                ? 'New Discord ban/warning appeal submission for review'
                : 'New appeal submission for review',
            });

            if (isDiscordAppealChannel) {
              await thread.send({
                content: `⚖️ **NEW DISCORD BAN / WARNING APPEAL**\n\nA new Discord ban or warning appeal has been submitted. Please review the submission above and discuss it here.\n\n**INSTRUCTIONS:**\n— Use the ✅ and ❎ reactions on the message above to cast your vote.\n— Review the user's Discord history and the original punishment details before voting.\n— Discuss any relevant context, previous warnings, or mitigating factors in this thread.\n— Ensure a final decision (approve/deny) is clearly recorded once a consensus is reached.\n\n_This appeal is handled by the Discord Moderation Department._`
              });
            } else {
              await thread.send({
                content: `⚖️ **NEW APPEAL SUBMISSION**\n\nPlease review the submission above and discuss it here.\n\n**INSTRUCTIONS:**\n- Use the ✅ and ❎ reactions on the message above to cast your vote.\n- Discuss the evidence and any previous history in this thread.\n- Ensure a final decision is logged once a consensus is reached.`
              });
            }

            console.log(`✅ Opened appeal voting thread for message ${message.id}`);
          } catch (error) {
            console.error('❌ Error creating appeal thread:', error);
            await sendEventLog(message.guild, '❌ Appeal Thread Error', 0xff0000, [
              { name: 'Channel', value: `<#${message.channel.id}>`, inline: true },
              { name: 'Error', value: error.message.substring(0, 1024), inline: false }
            ]).catch(console.error);
          }
        }
      }

      // --- VOTES CHANNELS: AUTO-REACT & THREAD ---
      const voteConfig = VOTES_CHANNELS.find(v => v.channelId === message.channel.id);
      const shouldOpenVoteThread =
        voteConfig &&
        !message.author.bot &&
        (!voteConfig.requiresVoteCommand || isVoteCommandTrigger(message.content));

      if (shouldOpenVoteThread) {
        try {
          if (voteConfig.requiresVoteCommand) {
            const rankData = await getVerifiedMainRankForDiscord(message.author.id).catch(() => null);
            const voteRoleIds = getVoteRoleIds(voteConfig);
            const hasVoteRole = hasAnyRoleId(message.member, voteRoleIds);
            const hasVoteRank = Number(rankData?.rank || 0) >= Number(voteConfig.voteCommandMinRank || 0);
            if (!hasVoteRole && !hasVoteRank) {
              const warning = await message.reply("Only Leadership Team members can start a Leadership vote here with `!vote`.")
                .catch(() => null);
              if (warning) setTimeout(() => warning.delete().catch(() => {}), 10000);
              return;
            }
          }

          await message.react('✅');
          await message.react('❎');

          const thread = await message.startThread({
            name: `${voteConfig.threadLabel} — Discussion`,
            autoArchiveDuration: 1440,
            reason: `New ${voteConfig.roleName} vote submission`,
          });

          const voteRoleIds = getVoteRoleIds(voteConfig);
          const voteRoleMentions = formatVoteRoleMentions(voteConfig);
          await thread.send({
            content: `${voteRoleMentions}\n\n` +
              `📋 **NEW VOTE SUBMISSION**\n\n` +
              `A new vote has been posted in <#${voteConfig.channelId}>. Please review the post above and cast your vote using the ✅ (approve) or ❎ (deny) reactions.\n\n` +
              `**Discussion Guidelines:**\n` +
              `— Keep all discussion respectful and professional.\n` +
              `— Share any relevant context, evidence, or reasoning here.\n` +
              `— A final decision should be noted in this thread once a clear consensus is reached.\n\n` +
              `_Only ${voteConfig.roleName} members should be voting on this submission._`,
            allowedMentions: { roles: voteRoleIds },
          });

          console.log(`✅ Opened vote thread in ${voteConfig.channelId} for message ${message.id}`);
        } catch (error) {
          console.error(`❌ Error creating vote thread in ${voteConfig.channelId}:`, error);
          await sendEventLog(message.guild, '❌ Vote Thread Error', 0xff0000, [
            { name: 'Channel', value: `<#${message.channel.id}>`, inline: true },
            { name: 'Error', value: error.message.substring(0, 1024), inline: false }
          ]).catch(console.error);
        }
      }

      // --- DM Application Responses (Bot 1) ---
      if (!message.guild) { // Message is a DM
        const session = activeSessions.get(message.author.id);
        if (session) { // This is an active application session
          if (message.content.toLowerCase() === 'cancel') {
            activeSessions.delete(message.author.id);
            await message.reply('❌ Your application has been cancelled.').catch(console.error);
            return;
          }

          const question = session.questions[session.currentQuestion];
          let answer = message.content.trim();

          // Validate answer based on question type
          if (question.type === 'scale') {
            const num = parseInt(answer);
            if (isNaN(num) || num < question.min || num > question.max) {
              await message.reply(`⚠️ Please provide a number between ${question.min} and ${question.max}.`).catch(console.error);
              return;
            }
            answer = num;
          } else if (question.type === 'choice') {
            const choice = parseInt(answer);
            if (isNaN(choice) || choice < 1 || choice > question.choices.length) {
              await message.reply(`⚠️ Please provide a number between 1 and ${question.choices.length}.`).catch(console.error);
              return;
            }
            answer = question.choices[choice - 1];
          } else if (question.type === 'confirm') {
            const response = answer.toLowerCase();
            if (!['yes', 'no', 'y', 'n'].includes(response)) {
              await message.reply('⚠️ Please respond with "yes" or "no".').catch(console.error);
              return;
            }
            answer = ['yes', 'y'].includes(response) ? 'Yes' : 'No';
          } else if (question.type === 'long' && answer.length < 20) {
            await message.reply('⚠️ Please provide a more detailed response (at least 20 characters).').catch(console.error);
            return;
          }

          session.answers[question.id] = answer;
          session.currentQuestion++;

          if (session.currentQuestion < session.questions.length) {
            await askQuestion(message.channel, session);
          } else {
            await submitApplication(message.channel, session);
            activeSessions.delete(message.author.id);
          }
          return;
        }

        // --- DM Acknowledgement Codes (Bot 3) ---
        const providedCode = message.content.trim().toUpperCase();
        const record = cases.records.find(r => r.extra?.ackCode?.toUpperCase() === providedCode && r.targetUserId === message.author.id);

        if (record) {
          const guild = client.guilds.cache.get(record.extra?.guildId);

          if (record.extra?.ackRemovesTimeout && guild) {
            try {
              const member = await guild.members.fetch(record.targetUserId).catch(() => null);
              if (member && member.isCommunicationDisabled()) {
                await member.timeout(null, `Acknowledged case ${record.caseId}`);
                await message.reply(`✅ Acknowledged case ${record.caseId}. Your timeout has been removed.`).catch(console.error);
              } else {
                await message.reply(`✅ Acknowledged case ${record.caseId}. Your timeout was not active or could not be removed.`).catch(console.error);
              }
            } catch (err) {
              console.error('Failed to remove timeout on ack:', err);
              await message.reply(`✅ Acknowledged case ${record.caseId}. Failed to remove timeout (check bot permissions).`).catch(console.error);
              await sendEventLog(guild, '❌ Ack Timeout Removal Failed', 0xffa500, [
                { name: 'User ID', value: record.targetUserId, inline: false },
                { name: 'Case ID', value: record.caseId, inline: false },
                { name: 'Error', value: err.message?.substring(0, 1024) || 'No message', inline: false }
              ]).catch(console.error);
            }
          } else {
            await message.reply(`✅ Acknowledged case ${record.caseId}.`).catch(console.error);
          }

          updateCaseExtra(record, { ackCode: null });
          const ackCase = nextCase('Acknowledge', client.user.id, record.targetUserId, `User acknowledged case ${record.caseId}`, { acknowledgedCase: record.caseId });
          if (guild) {
            await sendModLog(guild, { ...ackCase, color: 0x00cc66 });
            await closeAcknowledgementThread(guild, record.caseId);
          }
          return;
        }
      }

      // --- Guild Message Commands ---
      if (!message.guild) return;

      if (await handleEconomyPrefixCommand(message)) return;

      // Ban System Setup
      if (message.content === `${config.PREFIX}setupbans` && message.member.permissions.has(PermissionFlagsBits.Administrator)) {
        if (!config.BAN_SYSTEM_CHANNEL_ID) {
          await message.reply('❌ BAN_SYSTEM_CHANNEL_ID is not configured in environment variables.');
          return;
        }
        const banChannel = await message.guild.channels.fetch(config.BAN_SYSTEM_CHANNEL_ID).catch(() => null);
        if (!banChannel) {
          await message.reply(`❌ The configured BAN_SYSTEM_CHANNEL_ID could not be found.`);
          return;
        }
        await clearBotMessages(config.BAN_SYSTEM_CHANNEL_ID);
        await sendBanSystemPanel(banChannel);
        await message.delete().catch(() => { });
        await message.channel.send('✅ Ban system panel sent!').then(m => setTimeout(() => m.delete(), 5000));
      }

      // Formats System Setup
      if (message.content === `${config.PREFIX}setupformats` && message.member.permissions.has(PermissionFlagsBits.Administrator)) {
        const formatChannel = await message.guild.channels.fetch(config.FORMAT_CHANNEL_ID).catch(() => null);
        if (!formatChannel || !formatChannel.isTextBased()) {
          await message.reply(`❌ The configured FORMAT_CHANNEL_ID (${config.FORMAT_CHANNEL_ID}) could not be found or is not text-based.`).catch(console.error);
          return;
        }

        await clearBotMessages(config.FORMAT_CHANNEL_ID);
        await sendFormatsPanel(formatChannel);
        await message.delete().catch(() => { });
        await message.channel.send('✅ Resource Center panel sent to the configured channel!').then(m => setTimeout(() => m.delete(), 5000)).catch(console.error);
      }

      // Ticketing System Setup
      if (message.content === `${config.PREFIX}setuptickets` && message.member.permissions.has(PermissionFlagsBits.Administrator)) {
        if (!config.TICKET_CHANNEL_ID) {
          await message.reply('❌ TICKET_CHANNEL_ID is not configured in environment variables.').catch(console.error);
          return;
        }
        const ticketChannel = await message.guild.channels.fetch(config.TICKET_CHANNEL_ID).catch(() => null);
        if (!ticketChannel) {
          await message.reply(`❌ The configured TICKET_CHANNEL_ID (${config.TICKET_CHANNEL_ID}) could not be found or bot lacks access.`).catch(console.error);
          return;
        }
        await clearBotMessages(config.TICKET_CHANNEL_ID);
        await sendTicketPanel(ticketChannel);
        await message.delete().catch(() => { });
        await message.channel.send('✅ The questions and reports information panel was sent to the configured channel!').catch(console.error);
      }

      // Directory Contact Panel Refresh
      if (
        [`${config.PREFIX}setupcontacts`, `${config.PREFIX}refreshcontacts`].includes(message.content) &&
        message.member.permissions.has(PermissionFlagsBits.Administrator)
      ) {
        const directoryChannel = await message.guild.channels.fetch(config.TICKET_CHANNEL_ID).catch(() => null);
        if (!directoryChannel?.isTextBased?.()) {
          await message.reply(`❌ The configured directory channel (${config.TICKET_CHANNEL_ID}) could not be found or is not text-based.`).catch(console.error);
          return;
        }
        const recreatePanel = message.content === `${config.PREFIX}setupcontacts`;
        await syncDirectoryContactsPanel(message.guild, recreatePanel ? "manual setup" : "manual refresh", {
          channel: directoryChannel,
          forceNew: recreatePanel,
          replaceExisting: recreatePanel,
        });
        await message.delete().catch(() => { });
        await message.channel.send('✅ Department contacts panel refreshed!').then(m => setTimeout(() => m.delete(), 5000)).catch(console.error);
      }

    } catch (error) {
      console.error(`ERROR in messageCreate for message ${message.id}:`, error);
      await sendEventLog(message.guild, '❌ Message Create Handler Error', 0xff0000, [
        { name: 'Channel', value: message.channel?.name || 'DM', inline: true },
        { name: 'Author', value: `${message.author.tag} (${message.author.id})`, inline: true },
        { name: 'Content', value: message.content?.substring(0, 1024) || 'No content', inline: false },
        { name: 'Error', value: error.message?.substring(0, 1024) || 'No message', inline: false },
        { name: 'Stack', value: error.stack?.substring(0, 1024) || 'No stack', inline: false }
      ]).catch(console.error);
    }
  });


  // ========== MODERATION & EVENT LOGGING (from Bot 3) ==========
  const memberAuditSnapshots = new Map();
  const boosterMemberSnapshots = new Map();

  function memberSnapshotKey(memberOrGuildId, memberId = null) {
    if (typeof memberOrGuildId === "string") return `${memberOrGuildId}:${memberId}`;
    return `${memberOrGuildId.guild.id}:${memberOrGuildId.id}`;
  }

  function captureMemberAuditSnapshot(member) {
    return {
      roleIds: new Set(
        member.roles.cache
          .filter(role => role.id !== member.guild.id)
          .map(role => role.id),
      ),
      nickname: member.nickname ?? null,
      guildAvatar: member.avatar ?? null,
      guildAvatarUrl: member.avatar
        ? member.displayAvatarURL({ size: 1024 })
        : null,
      timeoutUntil: member.communicationDisabledUntil?.getTime() || null,
    };
  }

  function captureBoosterSnapshot(member) {
    const boosterRole = member.guild.roles.premiumSubscriberRole;
    return {
      boosting: Boolean(
        member.premiumSince ||
        (boosterRole && member.roles.cache.has(boosterRole.id))
      ),
      roleIds: new Set(member.roles.cache.keys()),
    };
  }

  async function seedMemberUpdateSnapshots(guild) {
    if (!guild) return;
    await fetchAllGuildMembersWithRetry(guild, {
      context: "MemberAudit snapshot seeding",
      maxAttempts: 2,
    }).catch(error => {
      console.warn(`[MemberAudit] Could not fetch all members for snapshot seeding: ${error.message}`);
    });

    for (const member of guild.members.cache.values()) {
      const key = memberSnapshotKey(member);
      memberAuditSnapshots.set(key, captureMemberAuditSnapshot(member));
      boosterMemberSnapshots.set(key, captureBoosterSnapshot(member));
    }
    console.log(`[MemberAudit] Seeded ${guild.members.cache.size} member snapshots.`);
  }

  function formatReactionEmoji(emoji) {
    if (emoji.id) {
      const rendered = `<${emoji.animated ? "a" : ""}:${emoji.name}:${emoji.id}>`;
      return `${rendered} (${emoji.name}, Custom${emoji.animated ? ", Animated" : ""})`;
    }
    return `${emoji.name || "Unknown"} (Unicode)`;
  }

  function getReactionMessagePreview(message) {
    if (message.content?.trim()) return message.content.trim().slice(0, 1024);

    const embed = message.embeds?.[0];
    if (embed) {
      const parts = [embed.title, embed.description].filter(Boolean);
      if (parts.length) return parts.join("\n").slice(0, 1024);
    }

    if (message.attachments?.size) {
      return message.attachments
        .map(attachment => attachment.name || attachment.url)
        .join(", ")
        .slice(0, 1024);
    }
    return "*No text content*";
  }

  async function logReactionEvent(reaction, user, added) {
    if (!user || user.bot) return;

    if (reaction.partial) {
      reaction = await reaction.fetch().catch(() => null);
      if (!reaction) return;
    }

    let message = reaction.message;
    if (message.partial) {
      message = await message.fetch().catch(() => null);
      if (!message) return;
    }
    if (!message.guild) return;

    const member = await message.guild.members.fetch(user.id).catch(() => null);
    const fields = [
      {
        name: "Member",
        value: `${member?.user?.tag || user.tag || user.username} (${user.id})`,
        inline: true,
      },
      {
        name: "Emoji",
        value: formatReactionEmoji(reaction.emoji),
        inline: true,
      },
      {
        name: "Channel",
        value: `${message.channel} (${message.channel.id})`,
        inline: true,
      },
      {
        name: "Message Author",
        value: message.author
          ? `${message.author.tag} (${message.author.id})`
          : "Unknown",
        inline: true,
      },
      {
        name: "Message",
        value: `[Jump to message](${message.url})`,
        inline: true,
      },
      {
        name: "Reaction Count",
        value: String(Math.max(0, reaction.count || 0)),
        inline: true,
      },
      {
        name: "Message Preview",
        value: getReactionMessagePreview(message),
        inline: false,
      },
    ];

    await sendEventLog(
      message.guild,
      added ? "➕ Reaction Added" : "➖ Reaction Removed",
      added ? 0x6bcf7f : 0xff9ff3,
      fields,
    );
  }

  client.on('messageDelete', async (message) => {
    try {
      // Handle shift claim cancellations
      await handleShiftCancellation(message, client);
      await handleCountingMessageDelete(message);
      
      // Ignore messages without guild (DMs), bot messages, or messages without authors
      if (!message.guild || !message.author || message.author.bot) return;

      // Skip logging if message had no content and no attachments (likely an embed)
      if (!message.content && (!message.attachments || message.attachments.size === 0)) return;

      // Try to find who deleted this message via audit log
      const { AuditLogEvent } = require('discord.js');
      const delExecutor = await getAuditExecutor(message.guild, AuditLogEvent.MessageDelete, message.author.id);

      const caseRecord = nextCase('MessageDelete', client.user.id, message.author.id, 'Message deleted', {
        channel: message.channel.name,
        channelId: message.channel.id,
        messageId: message.id,
        content: message.content || '[embed/attachment]'
      });
      const fields = [
        { name: 'Author', value: `${message.author.tag} (${message.author.id})`, inline: true },
        { name: 'Channel', value: `${message.channel}`, inline: true },
        { name: 'Message ID', value: message.id, inline: true },
      ];
      if (delExecutor && delExecutor.id !== message.author.id) {
        fields.push({ name: 'Deleted By', value: `${delExecutor.tag} (${delExecutor.id})`, inline: true });
      }
      if (message.content) {
        fields.push({ name: 'Content', value: message.content.substring(0, 1024), inline: false });
      }
      // Log any image/file attachments that were deleted
      if (message.attachments && message.attachments.size > 0) {
        const attachList = message.attachments.map(a => `[${a.name}](${a.url})`).join('\n').substring(0, 1024);
        fields.push({ name: `🖼️ Attachments (${message.attachments.size})`, value: attachList, inline: false });
      }
      await sendEventLog(message.guild, '🗑️ Message Deleted', 0xff6b6b, fields);
    } catch (err) {
      if (err.message && !err.message.includes('Cannot read properties of null')) {
        console.error('messageDelete log error:', err);
        if (message.guild) {
          await sendEventLog(message.guild, '❌ Message Delete Log Error', 0xffa500, [
            { name: 'Message ID', value: message.id || 'Unknown', inline: false },
            { name: 'Error', value: err.message?.substring(0, 1024) || 'No message', inline: false }
          ]).catch(console.error);
        }
      }
    }
  });

  client.on('messageDeleteBulk', async (messages, channel) => {
    try {
      if (!channel.guild) return;
      await handleCountingBulkDelete(messages, channel);
      // Try to find who triggered the bulk delete via audit log
      const { AuditLogEvent } = require('discord.js');
      const executor = await getAuditExecutor(channel.guild, AuditLogEvent.MessageBulkDelete, channel.id);
      const fields = [
        { name: 'Channel', value: `${channel} (${channel.id})`, inline: true },
        { name: 'Messages Deleted', value: String(messages.size), inline: true },
      ];
      if (executor) {
        fields.push({ name: 'Deleted By', value: `${executor.tag} (${executor.id})`, inline: true });
      }
      // Compile a short summary of authors whose messages were wiped
      const authorCounts = new Map();
      for (const msg of messages.values()) {
        if (msg.author) {
          authorCounts.set(msg.author.tag, (authorCounts.get(msg.author.tag) ?? 0) + 1);
        }
      }
      if (authorCounts.size > 0) {
        const summary = [...authorCounts.entries()].map(([tag, n]) => `${tag}: ${n}`).join('\n').substring(0, 1024);
        fields.push({ name: 'Affected Authors', value: summary, inline: false });
      }
      await sendEventLog(channel.guild, '🗑️ Bulk Message Delete', 0xff4444, fields);
    } catch (err) {
      console.error('messageDeleteBulk log error:', err);
    }
  }); // This closes the messageDeleteBulk handler

client.on('messageUpdate', async (oldMsg, newMsg) => {
  try {
    await handleCountingMessageUpdate(oldMsg, newMsg);

    // Ignore messages without guild, bot messages, partial messages, or no content change
    if (!oldMsg.guild || !oldMsg.author || oldMsg.author.bot || !oldMsg.content || oldMsg.content === newMsg.content) return;

    const caseRecord = nextCase('MessageEdit', client.user.id, oldMsg.author.id, 'Message edited', {
      channel: oldMsg.channel.name,
      channelId: oldMsg.channel.id,
      messageId: oldMsg.id,
      oldContent: oldMsg.content || '[embed/attachment]',
      newContent: newMsg.content || '[embed/attachment]'
    });
    const fields = [
      { name: 'Author', value: `${oldMsg.author.tag} (${oldMsg.author.id})`, inline: true },
      { name: 'Channel', value: `${oldMsg.channel}`, inline: true },
      { name: 'Message ID', value: oldMsg.id, inline: true },
      { name: 'Before', value: (oldMsg.content || '*embed/attachment*').substring(0, 1024), inline: false },
      { name: 'After', value: (newMsg.content || '*embed/attachment*').substring(0, 1024), inline: false }
    ];
    await sendEventLog(oldMsg.guild, '✏️ Message Edited', 0xffd93d, fields);
  } catch (err) {
    // Only log actual errors, not null reference errors from partial messages
    if (err.message && !err.message.includes('Cannot read properties of null')) {
      console.error('messageUpdate log error:', err);
      if (oldMsg.guild) {
        await sendEventLog(oldMsg.guild, '❌ Message Update Log Error', 0xffa500, [
          { name: 'Message ID', value: oldMsg.id || 'Unknown', inline: false },
          { name: 'Error', value: err.message?.substring(0, 1024) || 'No message', inline: false }
        ]).catch(console.error);
      }
    }
  }
});

  const pendingJoinWelcomeDms = new Map();
  const JOIN_WELCOME_DM_SETTLE_DELAY_MS = 12_000;
  const JOIN_WELCOME_DM_RETRY_DELAY_MS = 30_000;
  const JOIN_WELCOME_DM_MAX_ATTEMPTS = 20;

  function joinWelcomeDmKey(guildId, userId) {
    return `${guildId}:${userId}`;
  }

  function isRetryableJoinWelcomeDmError(error) {
    return /no mutual guilds/i.test(String(error?.message || ""));
  }

  function buildJoinWelcomeEmbed(member, context = {}) {
    const { verifiedRejoin = null, verificationThreadId = null } = context;
    const embed = new EmbedBuilder()
      .setColor(0xff86be)
      .setTitle(verifiedRejoin?.verified ? "Welcome back to Sweetsiez!" : "Welcome to Sweetsiez!")
      .setThumbnail("https://cdn.discordapp.com/attachments/1315179616595611700/1445700458504257646/Sweetsiez_Bakery_20251203_035630_0000.png?ex=6931f5b9&is=6930a439&hm=501f43de465d0ad7b9398d877f677411535c5b3a043dcbb3434687b10025be20&")
      .setFooter({ text: "As Sweet As Sugar" })
      .setTimestamp();

    if (verifiedRejoin?.verified) {
      embed.setDescription(
        `Welcome back to **Sweetsiez**, ${member}!\n\n` +
        `You are still verified as **${verifiedRejoin.robloxUsername || "your linked Roblox account"}**. ` +
        (verifiedRejoin.restored
          ? `I refreshed your roles from your current Roblox rank: **${verifiedRejoin.rankName || "Unknown"}** (${verifiedRejoin.rank ?? "?"}).`
          : "I recognized your verification, but I could not fully refresh your roles automatically. Please run **/getrole** in the server when you can.") +
        "\n\nThanks for coming back, and stay sweet!",
      );
      return embed;
    }

    const threadText = verificationThreadId ? `: <#${verificationThreadId}>.` : ".";
    embed.setDescription(
      `Welcome to **Sweetsiez**, ${member}!\n\n` +
      `A verification thread has been opened for you in Directory${threadText} ` +
      "Run **/verify [roblox-username]** there, then complete the bio check or join the main game and type **!verify**.\n\n" +
      "Once you verify, your roles will update and the thread will close automatically. " +
      "If you have trouble, press the **Need Help** button in your verification thread or ask a staff member for assistance. Thanks for being sweet!",
    );
    return embed;
  }

  async function sendJoinWelcomeDm(member, context = {}, trigger = "join") {
    try {
      await member.send({ embeds: [buildJoinWelcomeEmbed(member, context)] });
      console.log(`✅ Sent ${context.verifiedRejoin?.verified ? "welcome-back" : "welcome"} DM to ${member.user.tag} (${trigger})`);
      return { ok: true };
    } catch (dmError) {
      console.warn(`⚠️ Could not send welcome DM to ${member.user.tag}: ${dmError.message}`);
      await sendEventLog(member.guild, "⚠️ Welcome DM Failed", 0xffa500, [
        { name: "Member", value: `${member.user.tag} (${member.id})`, inline: false },
        { name: "Reason", value: dmError.message || "User likely has DMs disabled", inline: false },
        { name: "Trigger", value: trigger, inline: true },
      ]).catch(console.error);
      return {
        ok: false,
        retryable: isRetryableJoinWelcomeDmError(dmError),
        reason: dmError.message || "Unknown DM failure",
      };
    }
  }

  function schedulePendingJoinWelcomeDmRetry(guildId, userId, delayMs = JOIN_WELCOME_DM_RETRY_DELAY_MS, trigger = "queued retry") {
    const key = joinWelcomeDmKey(guildId, userId);
    const scheduledContext = pendingJoinWelcomeDms.get(key);
    if (!scheduledContext || scheduledContext.retryScheduled) return;
    const runAt = Date.now() + delayMs;
    scheduledContext.retryScheduled = true;
    scheduledContext.nextAttemptAt = runAt;
    pendingJoinWelcomeDms.set(key, scheduledContext);

    setTimeout(async () => {
      const context = pendingJoinWelcomeDms.get(key);
      if (!context) return;
      if (context.nextAttemptAt && Date.now() + 500 < context.nextAttemptAt) return;
      context.retryScheduled = false;

      const guild = client.guilds.cache.get(guildId);
      const member = guild ? await guild.members.fetch(userId).catch(() => null) : null;
      if (!member) {
        pendingJoinWelcomeDms.delete(key);
        return;
      }

      if (member.pending === false) {
        context.attempts = Number(context.attempts || 0) + 1;
        const result = await sendJoinWelcomeDm(member, context, trigger);
        if (result.ok) {
          pendingJoinWelcomeDms.delete(key);
          return;
        }
        if (!result.retryable || context.attempts >= JOIN_WELCOME_DM_MAX_ATTEMPTS) {
          pendingJoinWelcomeDms.delete(key);
          return;
        }
        pendingJoinWelcomeDms.set(key, context);
        schedulePendingJoinWelcomeDmRetry(guildId, userId, JOIN_WELCOME_DM_RETRY_DELAY_MS, "post-onboarding retry");
        return;
      }

      context.attempts = Number(context.attempts || 0) + 1;
      if (context.attempts >= JOIN_WELCOME_DM_MAX_ATTEMPTS) {
        pendingJoinWelcomeDms.delete(key);
        await sendEventLog(member.guild, "Welcome DM Deferred Too Long", 0xffa500, [
          { name: "Member", value: `${member.user.tag} (${member.id})`, inline: false },
          { name: "Reason", value: "Member stayed pending for too long, so the queued welcome DM was dropped.", inline: false },
        ]).catch(() => {});
        return;
      }

      pendingJoinWelcomeDms.set(key, context);
      schedulePendingJoinWelcomeDmRetry(guildId, userId, JOIN_WELCOME_DM_RETRY_DELAY_MS, "pending onboarding retry");
    }, delayMs);
  }

  async function sendOrQueueJoinWelcomeDm(member, context = {}) {
    if (member.pending === true) {
      const key = joinWelcomeDmKey(member.guild.id, member.id);
      pendingJoinWelcomeDms.set(key, {
        ...context,
        attempts: 0,
        queuedAt: Date.now(),
        retryScheduled: false,
      });
      schedulePendingJoinWelcomeDmRetry(member.guild.id, member.id, JOIN_WELCOME_DM_RETRY_DELAY_MS, "pending onboarding retry");
      await sendEventLog(member.guild, "Welcome DM Deferred", 0xfee75c, [
        { name: "Member", value: `${member.user.tag} (${member.id})`, inline: true },
        { name: "Reason", value: "Member is still pending onboarding/membership screening.", inline: false },
      ]).catch(() => {});
      return false;
    }

    const result = await sendJoinWelcomeDm(member, context, "join");
    if (!result.ok && result.retryable) {
      const key = joinWelcomeDmKey(member.guild.id, member.id);
      pendingJoinWelcomeDms.set(key, {
        ...context,
        attempts: 1,
        queuedAt: Date.now(),
        retryScheduled: false,
      });
      schedulePendingJoinWelcomeDmRetry(member.guild.id, member.id, JOIN_WELCOME_DM_RETRY_DELAY_MS, "post-join retry");
    }
    return result.ok;
  }

  async function flushPendingJoinWelcomeDm(member, trigger = "member update") {
    const key = joinWelcomeDmKey(member.guild.id, member.id);
    const context = pendingJoinWelcomeDms.get(key);
    if (!context || member.pending === true) return false;
    context.pendingClearedAt = context.pendingClearedAt || Date.now();
    context.retryScheduled = false;
    pendingJoinWelcomeDms.set(key, context);
    schedulePendingJoinWelcomeDmRetry(member.guild.id, member.id, JOIN_WELCOME_DM_SETTLE_DELAY_MS, trigger);
    return true;
  }

  client.on('guildMemberAdd', async (member) => {
    try {
      const snapshotKey = memberSnapshotKey(member);
      memberAuditSnapshots.set(snapshotKey, captureMemberAuditSnapshot(member));
      boosterMemberSnapshots.set(snapshotKey, captureBoosterSnapshot(member));

      // Log the member join event
      const accountAgeDays = Math.floor((Date.now() - member.user.createdAt.getTime()) / 86400000);
      const isNewAccount = accountAgeDays < 7;
      const fields = [
        { name: 'Member', value: `${member.user.tag} (${member.id})`, inline: true },
        { name: 'Account Created', value: `<t:${Math.floor(member.user.createdAt.getTime() / 1000)}:R>`, inline: true },
        { name: 'Account Age', value: `${accountAgeDays} day(s)${isNewAccount ? ' ⚠️ NEW ACCOUNT' : ''}`, inline: true },
        { name: 'Member Count', value: String(member.guild.memberCount), inline: true },
      ];
      await sendEventLog(member.guild, '📥 Member Joined', 0x6bcf7f, fields);

      let verificationThread = null;
      let verifiedRejoin = null;
      if (member.guild.id === config.IA_GUILD_ID) {
        verifiedRejoin = await refreshVerifiedMemberAccessOnJoin(member).catch(error => {
          console.warn(`Could not refresh verified rejoin access for ${member.user.tag}: ${error.message}`);
          return null;
        });

        if (verifiedRejoin?.verified) {
          const rejoinFields = [
            { name: "Member", value: `${member.user.tag} (${member.id})`, inline: true },
            { name: "Roblox", value: verifiedRejoin.robloxUsername || "Unknown", inline: true },
            { name: "Rank", value: `${verifiedRejoin.rankName || "Unknown"} (${verifiedRejoin.rank ?? "?"})`, inline: true },
            { name: "Role Sync", value: verifiedRejoin.restored ? "Restored automatically" : `Could not fully restore: ${verifiedRejoin.reason || "sync failed"}`, inline: false },
          ];
          await sendEventLog(member.guild, "Verified Member Rejoined", verifiedRejoin.restored ? 0x57f287 : 0xffa500, rejoinFields).catch(() => {});
        } else {
          await member.roles.add(
            VERIFICATION_THREAD_CONFIG.UNVERIFIED_ROLE_ID,
            "New member awaiting verification",
          ).catch(error => {
            console.warn(`Could not add Unverified role to ${member.user.tag}: ${error.message}`);
          });

          const threadResult = await createVerificationThreadForMember(member).catch(error => {
            console.warn(`Could not create verification thread for ${member.user.tag}: ${error.message}`);
            return null;
          });
          verificationThread = threadResult?.thread || null;
        }
      }

      await sendOrQueueJoinWelcomeDm(member, {
        verifiedRejoin,
        verificationThreadId: verificationThread?.id || null,
      });

      if (directoryContactRolesChanged([...member.roles.cache.keys()])) {
        scheduleDirectoryContactsSync(member.guild, "contact member joined");
      }
    } catch (err) {
      console.error('guildMemberAdd log error:', err);
      await sendEventLog(member.guild, '❌ Member Add Log Error', 0xffa500, [
        { name: 'Member ID', value: member.id, inline: false },
        { name: 'Error', value: err.message?.substring(0, 1024) || 'No message', inline: false }
      ]).catch(console.error);
    }
  });

  client.on('guildMemberRemove', async (member) => {
    try {
      const snapshotKey = memberSnapshotKey(member);
      memberAuditSnapshots.delete(snapshotKey);
      boosterMemberSnapshots.delete(snapshotKey);

      // Check if this was a kick via audit log
      const { AuditLogEvent } = require('discord.js');
      const executor = await getAuditExecutor(member.guild, AuditLogEvent.MemberKick, member.id);
      if (executor && executor.id !== client.user.id) {
        await trackAdminAction(client, member.guild, executor, 'kicks', {
          targetId: member.id,
          targetName: member.user?.tag || member.id,
          detail: "Member removed by audit-log kick action",
        });
      }
      const departedRoleIds = member.roles.cache
        .filter(r => r.id !== member.guild.id)
        .map(r => r.id);
      const roles = member.roles.cache
        .filter(r => r.id !== member.guild.id)
        .map(r => r.name)
        .join(', ') || 'None';
      const fields = [
        { name: 'Member', value: `${member.user.tag} (${member.id})`, inline: true },
        { name: 'Member Count', value: String(member.guild.memberCount), inline: true },
      ];
      if (executor && executor.id !== client.user.id) {
        fields.push({ name: '👟 Kicked By', value: `${executor.tag} (${executor.id})`, inline: true });
      }
      fields.push({ name: 'Roles Held', value: roles.substring(0, 1024), inline: false });
      if (directoryContactRolesChanged(departedRoleIds)) {
        scheduleDirectoryContactsSync(member.guild, "contact member left");
      }
      if (member.guild.id === config.IA_GUILD_ID) {
        await handleStaffLeftDiscord(member, executor).catch(error => {
          console.error(`Automatic staff departure cleanup failed for ${member.user.tag}:`, error.message);
          return sendEventLog(member.guild, "Automatic Staff Departure Error", 0xff0000, [
            { name: "Member", value: `${member.user.tag} (${member.id})`, inline: true },
            { name: "Error", value: truncateForDiscord(error.message), inline: false },
          ]).catch(() => {});
        });
      }
      await sendEventLog(member.guild, executor ? '👟 Member Kicked' : '📤 Member Left', executor ? 0xff6b00 : 0xff6b6b, fields);
    } catch (err) {
      console.error('guildMemberRemove log error:', err);
      await sendEventLog(member.guild, '❌ Member Remove Log Error', 0xffa500, [
        { name: 'Member ID', value: member.id, inline: false },
        { name: 'Error', value: err.message?.substring(0, 1024) || 'No message', inline: false }
      ]).catch(console.error);
    }
  });

  client.on('guildMemberUpdate', async (oldMember, newMember) => {
    const snapshotKey = memberSnapshotKey(newMember);
    const previousSnapshot = memberAuditSnapshots.get(snapshotKey);
    const currentSnapshot = captureMemberAuditSnapshot(newMember);
    memberAuditSnapshots.set(snapshotKey, currentSnapshot);

    if (pendingJoinWelcomeDms.has(joinWelcomeDmKey(newMember.guild.id, newMember.id)) && newMember.pending === false) {
      await flushPendingJoinWelcomeDm(newMember, "onboarding completed").catch(error => {
        console.warn(`Could not flush pending welcome DM for ${newMember.user.tag}: ${error.message}`);
      });
    }

    // Never infer changes from an unseeded or incomplete oldMember object.
    // The ready handler seeds reliable snapshots for every cached member.
    if (!previousSnapshot) return;

    try {
      const { AuditLogEvent } = require('discord.js');
      const addedRoles = [...currentSnapshot.roleIds].filter(
        roleId => !previousSnapshot.roleIds.has(roleId),
      );
      const removedRoles = [...previousSnapshot.roleIds].filter(
        roleId => !currentSnapshot.roleIds.has(roleId),
      );
      const roleExec = (addedRoles.length || removedRoles.length)
        ? await getAuditExecutor(newMember.guild, AuditLogEvent.MemberRoleUpdate, newMember.id)
        : null;

      if (directoryContactRolesChanged([...addedRoles, ...removedRoles])) {
        scheduleDirectoryContactsSync(newMember.guild, "contact role changed");
      }

      if (addedRoles.length > 0) {
        const roleNames = addedRoles
          .map(id => newMember.guild.roles.cache.get(id)?.name || id)
          .join(', ');
        const fields = [
          { name: 'Member', value: `${newMember.user.tag} (${newMember.id})`, inline: true },
          { name: 'Roles Added', value: roleNames.substring(0, 1024), inline: false },
        ];
        if (roleExec) fields.push({ name: 'Updated By', value: `${roleExec.tag} (${roleExec.id})`, inline: true });
        await sendEventLog(newMember.guild, '➕ Member Role Added', 0x6bcf7f, fields);
        nextCase('MemberRoleAdded', client.user.id, newMember.id, `Roles added: ${roleNames}`, { roleIds: addedRoles });
        if (roleExec && roleExec.id !== client.user.id) {
          await trackAdminAction(client, newMember.guild, roleExec, 'memberRoleAdds', {
            targetId: newMember.id,
            targetName: newMember.user.tag,
            detail: `Roles added: ${roleNames}`,
          });
          const dangerousRoles = addedRoles
            .map(id => newMember.guild.roles.cache.get(id))
            .filter(role => role && hasDangerousPermissions(role));
          if (dangerousRoles.length) {
            await trackAdminAction(client, newMember.guild, roleExec, 'dangerousRoleGrants', {
              targetId: newMember.id,
              targetName: newMember.user.tag,
              detail: `Dangerous roles granted: ${dangerousRoles.map(role => role.name).join(", ")}`,
            });
          }
        }
      }

      if (removedRoles.length > 0) {
        const roleNames = removedRoles
          .map(id => oldMember.guild.roles.cache.get(id)?.name || id)
          .join(', ');
        const fields = [
          { name: 'Member', value: `${newMember.user.tag} (${newMember.id})`, inline: true },
          { name: 'Roles Removed', value: roleNames.substring(0, 1024), inline: false },
        ];
        if (roleExec) fields.push({ name: 'Updated By', value: `${roleExec.tag} (${roleExec.id})`, inline: true });
        await sendEventLog(newMember.guild, '➖ Member Role Removed', 0xff9ff3, fields);
        nextCase('MemberRoleRemoved', client.user.id, newMember.id, `Roles removed: ${roleNames}`, { roleIds: removedRoles });
        if (roleExec && roleExec.id !== client.user.id) {
          await trackAdminAction(client, newMember.guild, roleExec, 'memberRoleRemoves', {
            targetId: newMember.id,
            targetName: newMember.user.tag,
            detail: `Roles removed: ${roleNames}`,
          });
        }
      }

      if (previousSnapshot.nickname !== currentSnapshot.nickname) {
        const nickExec = await getAuditExecutor(newMember.guild, AuditLogEvent.MemberUpdate, newMember.id);
        const fields = [
          { name: 'Member', value: `${newMember.user.tag} (${newMember.id})`, inline: true },
          { name: 'Old Nickname', value: previousSnapshot.nickname?.substring(0, 1024) || '*none*', inline: true },
          { name: 'New Nickname', value: currentSnapshot.nickname?.substring(0, 1024) || '*none*', inline: true },
        ];
        if (nickExec && nickExec.id !== newMember.id) {
          fields.push({ name: 'Changed By', value: `${nickExec.tag} (${nickExec.id})`, inline: true });
        }
        await sendEventLog(newMember.guild, '🏷️ Nickname Changed', 0xffd93d, fields);
      }

      if (previousSnapshot.guildAvatar !== currentSnapshot.guildAvatar) {
        const fields = [
          { name: 'Member', value: `${newMember.user.tag} (${newMember.id})`, inline: true },
          {
            name: 'Old Server Avatar',
            value: previousSnapshot.guildAvatarUrl
              ? `[View avatar](${previousSnapshot.guildAvatarUrl})`
              : '*none*',
            inline: true,
          },
          {
            name: 'New Server Avatar',
            value: currentSnapshot.guildAvatarUrl
              ? `[View avatar](${currentSnapshot.guildAvatarUrl})`
              : '*none*',
            inline: true,
          },
        ];
        await sendEventLog(newMember.guild, '🖼️ Server Profile Avatar Changed', 0x5bc0de, fields);
      }

      // ── Timeout detection ──────────────────────────────────────────────────
      const oldTimeoutMs = previousSnapshot.timeoutUntil;
      const newTimeoutMs = currentSnapshot.timeoutUntil;
      const nowMs = Date.now();

      // Timeout APPLIED: new timeout is in the future and either didn't exist or was in the past
      if (newTimeoutMs && newTimeoutMs > nowMs && (!oldTimeoutMs || oldTimeoutMs <= nowMs)) {
        const timeoutExec = await getAuditExecutor(newMember.guild, AuditLogEvent.MemberUpdate, newMember.id);
        const fields = [
          { name: 'Member', value: `${newMember.user.tag} (${newMember.id})`, inline: true },
          { name: 'Timeout Expires', value: `<t:${Math.floor(newTimeoutMs / 1000)}:R>`, inline: true },
        ];
        if (timeoutExec) fields.push({ name: 'Timed Out By', value: `${timeoutExec.tag} (${timeoutExec.id})`, inline: true });
        // Try to get reason from audit log
        try {
          const logs = await newMember.guild.fetchAuditLogs({ type: AuditLogEvent.MemberUpdate, limit: 5 });
          const entry = logs.entries.find(e => e.target?.id === newMember.id && Date.now() - e.createdTimestamp < 5000);
          if (entry?.reason) fields.push({ name: 'Reason', value: entry.reason.substring(0, 1024), inline: false });
        } catch {}
        await sendEventLog(newMember.guild, '🔇 Member Timed Out', 0xff8c00, fields);
      }

      // Timeout REMOVED: old timeout was in the future, new one is gone or in the past
      if (oldTimeoutMs && oldTimeoutMs > nowMs && (!newTimeoutMs || newTimeoutMs <= nowMs)) {
        const untimeoutExec = await getAuditExecutor(newMember.guild, AuditLogEvent.MemberUpdate, newMember.id);
        const fields = [
          { name: 'Member', value: `${newMember.user.tag} (${newMember.id})`, inline: true },
        ];
        if (untimeoutExec) fields.push({ name: 'Removed By', value: `${untimeoutExec.tag} (${untimeoutExec.id})`, inline: true });
        await sendEventLog(newMember.guild, '🔊 Timeout Removed', 0x6bcf7f, fields);
      }
    } catch (err) {
      console.error('guildMemberUpdate log error:', err);
      await sendEventLog(newMember.guild, '❌ Member Update Log Error', 0xffa500, [
        { name: 'Member ID', value: newMember.id, inline: false },
        { name: 'Error', value: err.message?.substring(0, 1024) || 'No message', inline: false }
      ]).catch(console.error);
    }
  });

  client.on('userUpdate', async (oldUser, newUser) => {
    try {
      const guild =
        client.guilds.cache.get(config.IA_GUILD_ID) ||
        client.guilds.cache.find(candidate => candidate.members.cache.has(newUser.id));
      if (!guild) return;

      const member = guild.members.cache.get(newUser.id) ||
        await guild.members.fetch(newUser.id).catch(() => null);
      if (!member) return;

      const fields = [
        { name: 'Member', value: `${newUser.tag} (${newUser.id})`, inline: true },
      ];

      if (oldUser.username !== newUser.username) {
        fields.push(
          { name: 'Old Username', value: oldUser.username || '*none*', inline: true },
          { name: 'New Username', value: newUser.username || '*none*', inline: true },
        );
      }
      if ((oldUser.globalName || null) !== (newUser.globalName || null)) {
        fields.push(
          { name: 'Old Display Name', value: oldUser.globalName || '*none*', inline: true },
          { name: 'New Display Name', value: newUser.globalName || '*none*', inline: true },
        );
      }
      if (oldUser.avatar !== newUser.avatar) {
        fields.push(
          {
            name: 'Old Avatar',
            value: oldUser.avatar
              ? `[View avatar](${oldUser.displayAvatarURL({ size: 1024 })})`
              : '*default avatar*',
            inline: true,
          },
          {
            name: 'New Avatar',
            value: newUser.avatar
              ? `[View avatar](${newUser.displayAvatarURL({ size: 1024 })})`
              : '*default avatar*',
            inline: true,
          },
        );
      }

      if (fields.length === 1) return;
      await sendEventLog(guild, '👤 User Profile Updated', 0x5bc0de, fields);
    } catch (err) {
      console.error('userUpdate log error:', err);
    }
  });

