  client.on('roleUpdate', async (oldRole, newRole) => {
    try {
      const { AuditLogEvent } = require('discord.js');
      const changes = [];
      let permissionAdded = [];
      let permissionRemoved = [];
      if (oldRole.name !== newRole.name) changes.push(`**Name:** ${oldRole.name} → ${newRole.name}`);
      if (oldRole.color !== newRole.color) {
        const oldColor = oldRole.color ? `#${oldRole.color.toString(16).toUpperCase().padStart(6, '0')}` : 'Default';
        const newColor = newRole.color ? `#${newRole.color.toString(16).toUpperCase().padStart(6, '0')}` : 'Default';
        changes.push(`**Color:** ${oldColor} → ${newColor}`);
      }
      if (oldRole.mentionable !== newRole.mentionable) changes.push(`**Mentionable:** ${oldRole.mentionable} → ${newRole.mentionable}`);
      if (oldRole.hoist !== newRole.hoist) changes.push(`**Hoisted:** ${oldRole.hoist} → ${newRole.hoist}`);
      if (oldRole.permissions.bitfield !== newRole.permissions.bitfield) {
        permissionAdded = newRole.permissions.toArray().filter(p => !oldRole.permissions.has(p));
        permissionRemoved = oldRole.permissions.toArray().filter(p => !newRole.permissions.has(p));
        if (permissionAdded.length)   changes.push(`**Perms Added:** ${permissionAdded.join(', ')}`);
        if (permissionRemoved.length) changes.push(`**Perms Removed:** ${permissionRemoved.join(', ')}`);
      }

      if (changes.length > 0) {
        const executor = await getAuditExecutor(newRole.guild, AuditLogEvent.RoleUpdate, newRole.id);
        const fields = [
          { name: 'Role', value: `<@&${newRole.id}> ${newRole.name} (${newRole.id})`, inline: true },
          { name: 'Changes', value: changes.join('\n').substring(0, 1024), inline: false },
        ];
        if (executor) fields.push({ name: 'Updated By', value: `${executor.tag} (${executor.id})`, inline: true });
        await sendEventLog(newRole.guild, '✏️ Role Updated', 0xffd93d, fields);
        if (executor && executor.id !== client.user.id) {
          await trackAdminAction(client, newRole.guild, executor, 'roleUpdates', {
            targetId: newRole.id,
            targetName: newRole.name,
            detail: changes.join("; ").slice(0, 800),
          });
          if (oldRole.name !== newRole.name) {
            await trackAdminAction(client, newRole.guild, executor, 'roleNameUpdates', {
              targetId: newRole.id,
              targetName: newRole.name,
              detail: `${oldRole.name} -> ${newRole.name}`,
            });
          }
          if (permissionAdded.length || permissionRemoved.length) {
            await trackAdminAction(client, newRole.guild, executor, 'rolePermissionUpdates', {
              targetId: newRole.id,
              targetName: newRole.name,
              detail: `Added: ${permissionAdded.join(", ") || "none"}; Removed: ${permissionRemoved.join(", ") || "none"}`,
            });
            const dangerousAdded = permissionAdded.filter(isDangerousPermission);
            if (dangerousAdded.length) {
              await trackAdminAction(client, newRole.guild, executor, 'dangerousRolePermissionUpdates', {
                targetId: newRole.id,
                targetName: newRole.name,
                detail: `Dangerous permissions added: ${dangerousAdded.join(", ")}`,
              });
            }
          }
        }
      }
    } catch (err) {
      console.error('roleUpdate log error:', err);
      await sendEventLog(newRole.guild, '❌ Role Update Log Error', 0xffa500, [
        { name: 'Role ID', value: newRole.id, inline: false },
        { name: 'Error', value: err.message?.substring(0, 1024) || 'No message', inline: false }
      ]).catch(console.error);
    }
  });

  function channelTypeLabel(type) {
    return Object.entries(ChannelType).find(([, value]) => value === type)?.[0] || String(type);
  }

  function formatPermissionList(bitfield) {
    const values = bitfield?.toArray?.() || [];
    return values.length ? values.join(", ") : "None";
  }

  function formatOverwriteTarget(guild, id, type) {
    if (id === guild.id) return `@everyone (${id})`;
    const role = guild.roles.cache.get(id);
    if (role) return `${role.name} (${id})`;
    const member = guild.members.cache.get(id);
    if (member) return `${member.user.tag} (${id})`;
    return `${type === 0 ? "Role" : type === 1 ? "Member" : "Target"} (${id})`;
  }

  function pushChunkedChangeFields(fields, label, lines) {
    if (!lines.length) return;
    let chunk = "";
    let index = 1;
    for (const line of lines) {
      const candidate = chunk ? `${chunk}\n${line}` : line;
      if (candidate.length > 1000 && chunk) {
        fields.push({ name: index === 1 ? label : `${label} (${index})`, value: chunk, inline: false });
        index += 1;
        chunk = line;
      } else {
        chunk = candidate;
      }
    }
    if (chunk) fields.push({ name: index === 1 ? label : `${label} (${index})`, value: chunk.slice(0, 1024), inline: false });
  }

  function collectPermissionOverwriteChanges(oldChannel, newChannel) {
    const oldOverwrites = oldChannel.permissionOverwrites?.cache;
    const newOverwrites = newChannel.permissionOverwrites?.cache;
    if (!oldOverwrites || !newOverwrites) return [];

    const lines = [];
    const overwriteIds = new Set([...oldOverwrites.keys(), ...newOverwrites.keys()]);
    for (const id of overwriteIds) {
      const before = oldOverwrites.get(id);
      const after = newOverwrites.get(id);
      const target = formatOverwriteTarget(newChannel.guild, id, after?.type ?? before?.type);

      if (!before && after) {
        lines.push(`Added overwrite for **${target}**`);
        lines.push(`- Allow: ${formatPermissionList(after.allow)}`);
        lines.push(`- Deny: ${formatPermissionList(after.deny)}`);
        continue;
      }
      if (before && !after) {
        lines.push(`Removed overwrite for **${target}**`);
        lines.push(`- Allowed: ${formatPermissionList(before.allow)}`);
        lines.push(`- Denied: ${formatPermissionList(before.deny)}`);
        continue;
      }

      const allowAdded = after.allow.toArray().filter(permission => !before.allow.has(permission));
      const allowRemoved = before.allow.toArray().filter(permission => !after.allow.has(permission));
      const denyAdded = after.deny.toArray().filter(permission => !before.deny.has(permission));
      const denyRemoved = before.deny.toArray().filter(permission => !after.deny.has(permission));

      if (allowAdded.length) lines.push(`**${target}** allow added: ${allowAdded.join(", ")}`);
      if (allowRemoved.length) lines.push(`**${target}** allow removed: ${allowRemoved.join(", ")}`);
      if (denyAdded.length) lines.push(`**${target}** deny added: ${denyAdded.join(", ")}`);
      if (denyRemoved.length) lines.push(`**${target}** deny removed: ${denyRemoved.join(", ")}`);
    }
    return lines;
  }

  function formatForumTag(tag) {
    const emoji = tag.emoji?.id
      ? `<${tag.emoji.animated ? "a" : ""}:${tag.emoji.name}:${tag.emoji.id}>`
      : tag.emoji?.name || "";
    return `${tag.name} (${tag.id})${tag.moderated ? " [moderated]" : ""}${emoji ? ` ${emoji}` : ""}`;
  }

  function collectForumTagChanges(oldChannel, newChannel) {
    if (!Array.isArray(oldChannel.availableTags) && !Array.isArray(newChannel.availableTags)) return [];
    const oldTags = new Map((oldChannel.availableTags || []).map(tag => [tag.id, tag]));
    const newTags = new Map((newChannel.availableTags || []).map(tag => [tag.id, tag]));
    const lines = [];

    for (const [id, tag] of newTags) {
      if (!oldTags.has(id)) lines.push(`Created tag: **${formatForumTag(tag)}**`);
    }
    for (const [id, tag] of oldTags) {
      if (!newTags.has(id)) lines.push(`Deleted tag: **${formatForumTag(tag)}**`);
    }
    for (const [id, oldTag] of oldTags) {
      const newTag = newTags.get(id);
      if (!newTag) continue;
      const edits = [];
      if (oldTag.name !== newTag.name) edits.push(`name: ${oldTag.name} -> ${newTag.name}`);
      if ((oldTag.moderated || false) !== (newTag.moderated || false)) edits.push(`moderated: ${oldTag.moderated ? "yes" : "no"} -> ${newTag.moderated ? "yes" : "no"}`);
      const oldEmoji = oldTag.emoji?.id || oldTag.emoji?.name || "";
      const newEmoji = newTag.emoji?.id || newTag.emoji?.name || "";
      if (oldEmoji !== newEmoji) edits.push(`emoji: ${oldEmoji || "none"} -> ${newEmoji || "none"}`);
      if (edits.length) lines.push(`Edited tag **${oldTag.name}** (${id}): ${edits.join("; ")}`);
    }
    return lines;
  }

  function chooseChannelUpdateTitle(oldChannel, newChannel, kinds) {
    if (oldChannel.type === ChannelType.GuildCategory && kinds.size === 1 && kinds.has("position")) return "Category Moved";
    if (newChannel.type === ChannelType.GuildForum && kinds.size === 1 && kinds.has("name")) return "Forum Title Edited";
    if (kinds.size === 1 && kinds.has("parent")) return "Channel Category Moved";
    if (kinds.size === 1 && kinds.has("position")) return "Channel Position Moved";
    if (kinds.size === 1 && kinds.has("permissions")) return "Channel Permissions Updated";
    if (kinds.size === 1 && kinds.has("forumTags")) return "Forum Tags Updated";
    return "Channel Updated";
  }

  async function getThreadParent(thread) {
    return thread.parent || (thread.parentId ? await thread.guild.channels.fetch(thread.parentId).catch(() => null) : null);
  }

  client.on('threadDelete', async (thread) => {
    try {
      if (!thread.guild) return;
      const { AuditLogEvent } = require('discord.js');
      const parent = await getThreadParent(thread);
      const isForumPost = parent?.type === ChannelType.GuildForum;
      const executor = await getAuditExecutor(
        thread.guild,
        AuditLogEvent.ThreadDelete ?? AuditLogEvent.ChannelDelete,
        thread.id,
      );
      const fields = [
        { name: isForumPost ? "Forum Post" : "Thread", value: `${thread.name} (${thread.id})`, inline: true },
        { name: "Parent Channel", value: parent ? `${parent} (${parent.id})` : thread.parentId || "Unknown", inline: true },
        { name: "Type", value: channelTypeLabel(thread.type), inline: true },
      ];
      if (executor) fields.push({ name: "Deleted By", value: `${executor.tag} (${executor.id})`, inline: true });
      await sendEventLog(thread.guild, isForumPost ? "Forum Post Deleted" : "Thread Deleted", 0xff6b6b, fields);
      if (executor && executor.id !== client.user.id) {
        await trackAdminAction(client, thread.guild, executor, 'threadDeletes', {
          targetId: thread.id,
          targetName: thread.name,
          detail: `${isForumPost ? "Forum post" : "Thread"} deleted from ${parent?.name || thread.parentId || "unknown parent"}`,
        });
      }
    } catch (err) {
      console.error('threadDelete log error:', err);
      await sendEventLog(thread.guild, 'Thread Delete Log Error', 0xffa500, [
        { name: 'Thread ID', value: thread.id, inline: false },
        { name: 'Error', value: err.message?.substring(0, 1024) || 'No message', inline: false },
      ]).catch(console.error);
    }
  });

  client.on('threadUpdate', async (oldThread, newThread) => {
    try {
      if (!newThread.guild) return;
      const parent = await getThreadParent(newThread);
      const isForumPost = parent?.type === ChannelType.GuildForum;
      const changes = [];
      const kinds = new Set();

      if (oldThread.name !== newThread.name) {
        changes.push(`**Title:** ${oldThread.name} -> ${newThread.name}`);
        kinds.add("name");
      }
      if (oldThread.archived !== newThread.archived) {
        changes.push(`**Archived:** ${oldThread.archived ? "yes" : "no"} -> ${newThread.archived ? "yes" : "no"}`);
        kinds.add("state");
      }
      if (oldThread.locked !== newThread.locked) {
        changes.push(`**Locked:** ${oldThread.locked ? "yes" : "no"} -> ${newThread.locked ? "yes" : "no"}`);
        kinds.add("state");
      }
      const oldTags = [...(oldThread.appliedTags || [])].sort();
      const newTags = [...(newThread.appliedTags || [])].sort();
      if (oldTags.join(",") !== newTags.join(",")) {
        const tagName = id => parent?.availableTags?.find(tag => tag.id === id)?.name || id;
        changes.push(`**Applied Tags:** ${oldTags.map(tagName).join(", ") || "None"} -> ${newTags.map(tagName).join(", ") || "None"}`);
        kinds.add("tags");
      }

      if (!changes.length) return;
      const { AuditLogEvent } = require('discord.js');
      const executor = await getAuditExecutor(
        newThread.guild,
        AuditLogEvent.ThreadUpdate ?? AuditLogEvent.ChannelUpdate,
        newThread.id,
      );
      const title = isForumPost && kinds.size === 1 && kinds.has("name")
        ? "Forum Post Title Edited"
        : isForumPost && kinds.size === 1 && kinds.has("tags")
          ? "Forum Post Tags Updated"
          : isForumPost
            ? "Forum Post Updated"
            : "Thread Updated";
      const fields = [
        { name: isForumPost ? "Forum Post" : "Thread", value: `${newThread} (${newThread.id})`, inline: true },
        { name: "Parent Channel", value: parent ? `${parent} (${parent.id})` : newThread.parentId || "Unknown", inline: true },
      ];
      pushChunkedChangeFields(fields, "Changes", changes);
      if (executor) fields.push({ name: "Updated By", value: `${executor.tag} (${executor.id})`, inline: true });
      await sendEventLog(newThread.guild, title, 0xffd93d, fields);
      if (executor && executor.id !== client.user.id) {
        await trackAdminAction(client, newThread.guild, executor, 'threadUpdates', {
          targetId: newThread.id,
          targetName: newThread.name,
          detail: changes.join("; ").slice(0, 800),
        });
      }
    } catch (err) {
      console.error('threadUpdate log error:', err);
      await sendEventLog(newThread.guild, 'Thread Update Log Error', 0xffa500, [
        { name: 'Thread ID', value: newThread.id, inline: false },
        { name: 'Error', value: err.message?.substring(0, 1024) || 'No message', inline: false },
      ]).catch(console.error);
    }
  });

