// SOCIAL MEDIA SUBMISSION SYSTEM
// ══════════════════════════════════════════════════════════════════════════════

const SM_SUBMISSIONS_CHANNEL_ID = '1477455503239020604'; // channel to post submissions
const SM_COMMS_ROLE_ID          = SWEETSIEZ_STRUCTURE_CONFIG.ROLES["Marketing Board"] || '1521611451679244492'; // role to ping on submission
const SM_VERIFIED_ROLE_ID       = '1308262804754661448'; // verified role required to submit
                                                          // ⚠️ Replace with your actual verified role ID

// Map of userId -> { step, answers: {}, startedAt }
const smSubmitSessions = new Map();

const SM_STEPS = [
  {
    key:    'platform',
    prompt: '**Step 1 of 4 — Platform**\nWhich platform is this submission for?\n\n`1` — YouTube Shorts\n`2` — X (Twitter)\n`3` — Instagram',
    validate(input) {
      const n = input.trim();
      if (n === '1') return 'YouTube Shorts';
      if (n === '2') return 'X (Twitter)';
      if (n === '3') return 'Instagram';
      return null;
    },
    error: '❌ Please reply with `1`, `2`, or `3`.',
  },
  {
    key:    'contentType',
    prompt: '**Step 2 of 4 — Content Type**\nWhat type of content are you submitting?\n\n`1` — Video\n`2` — Image\n`3` — GIF',
    validate(input) {
      const n = input.trim();
      if (n === '1') return 'Video';
      if (n === '2') return 'Image';
      if (n === '3') return 'GIF';
      return null;
    },
    error: '❌ Please reply with `1`, `2`, or `3`.',
  },
  {
    key:    'description',
    prompt: '**Step 3 of 4 — Description**\nProvide a brief description of your submission. What is it about?',
    validate(input) {
      const v = input.trim();
      if (v.length < 5)   return null;
      if (v.length > 500) return null;
      return v;
    },
    error: '❌ Description must be between 5 and 500 characters.',
  },
  {
    key:    'credit',
    prompt: '**Step 4 of 4 — Credit**\nHow would you like to be credited? Type your preferred credit name, or type `none` to skip.',
    validate(input) {
      const v = input.trim();
      if (!v) return null;
      return v.toLowerCase() === 'none' ? 'No credit' : v;
    },
    error: '❌ Please provide a credit name or type `none`.',
  },
  {
    key:    'content',
    prompt: '**Final Step — Content**\nNow send your actual content! You can:\n• Attach a **file** (video, image, GIF)\n• Paste a **link**\n• Send **text**\n\nThis will be included directly in the submission.',
    validate(input, message) {
      if (message.attachments.size > 0) {
        const urls  = [...message.attachments.values()].map(a => a.url).join('\n');
        const label = input.trim() ? `${input.trim()}\n${urls}` : urls;
        return label;
      }
      const v = input.trim();
      if (!v) return null;
      return v;
    },
    error: '❌ Please send a file, a link, or some text.',
  },
];

client.on('messageCreate', async (message) => {
  if (message.author.bot) return;
  if (message.channel.type !== ChannelType.DM) return;

  const userId  = message.author.id;
  const content = message.content.trim();

  // The primary DM listener owns the report command and report answers.
  if (content.toLowerCase() === '!report' || reportSessions.has(userId)) return;

  // !smsubmit — start a new session
  if (content.toLowerCase() === '!smsubmit') {
    console.log(`[SMSubmit] ${message.author.tag} (${userId}) triggered !smsubmit`);

    if (reportSessions.has(userId)) {
      return message.channel.send(
        '⚠️ You already have a report in progress. Finish it or type `cancel` before starting a social media submission.'
      );
    }

    if (smSubmitSessions.has(userId)) {
      console.log(`[SMSubmit] ${message.author.tag} (${userId}) already has an active session — blocked`);
      return message.channel.send(
        '⚠️ You already have an active submission in progress! Answer the current question, or type `!smcancel` to start over.'
      );
    }

    // Find the member across all guilds
    let member = null;
    for (const guild of client.guilds.cache.values()) {
      try {
        member = await guild.members.fetch(userId);
        if (member) break;
      } catch { /* not in this guild */ }
    }

    if (!member) {
      console.warn(`[SMSubmit] ${message.author.tag} (${userId}) not found in any guild — cannot start session`);
      return message.channel.send(
        "❌ I couldn't find you in the Sweetsiez server. Make sure you're still a member!"
      );
    }

    // Check verified status via DB
    let verifyDoc = null;
    try {
      verifyDoc = await VerifiedUser.findOne({ discordId: userId });
    } catch (dbErr) {
      console.warn(`[SMSubmit] DB verification check failed for ${message.author.tag} (${userId}):`, dbErr.message);
    }

    if (!verifyDoc) {
      console.log(`[SMSubmit] ${message.author.tag} (${userId}) blocked — not found in VerifiedUser DB`);
      return message.channel.send(
        '❌ You need to be **verified** in the Sweetsiez server before submitting content.\n\nHead to the server and complete verification first!'
      );
    }

    smSubmitSessions.set(userId, { step: 0, answers: {}, startedAt: Date.now(), robloxUsername: verifyDoc.robloxUsername });
    console.log(`[SMSubmit] Session started for ${message.author.tag} (${userId}) | Roblox: ${verifyDoc.robloxUsername}`);

    const introEmbed = new EmbedBuilder()
      .setColor(0xf47fff)
      .setTitle('📸 Social Media Submission')
      .setDescription(
        "Welcome to the Social Media Submission flow! I'll ask you a few quick questions.\n\n" +
        "• Type `!smcancel` at any time to cancel.\n" +
        "• All submissions are reviewed by the Public Relations Department - posting is not guaranteed.\n" +
        "• Submitting grants Sweetsiez permission to use and edit your content."
      )
      .setFooter({ text: 'Sweetsiez Public Relations Aspirant' });

    await message.channel.send({ embeds: [introEmbed] });
    await message.channel.send(SM_STEPS[0].prompt);
    return;
  }

  // !smcancel — cancel active session
  if (content.toLowerCase() === '!smcancel') {
    if (smSubmitSessions.has(userId)) {
      smSubmitSessions.delete(userId);
      console.log(`[SMSubmit] ${message.author.tag} (${userId}) cancelled their session`);
      return message.channel.send('🚫 Submission cancelled. Type `!smsubmit` anytime to start a new one.');
    }
    console.log(`[SMSubmit] ${message.author.tag} (${userId}) used !smcancel with no active session`);
    return message.channel.send("You don't have an active submission session.");
  }

  // Handle active session steps
  if (!smSubmitSessions.has(userId)) return;

  const session     = smSubmitSessions.get(userId);
  const stepIndex   = session.step;
  const currentStep = SM_STEPS[stepIndex];

  const validated = currentStep.validate(content, message);
  if (validated === null) {
    console.log(`[SMSubmit] ${message.author.tag} (${userId}) failed validation on step ${stepIndex} (${currentStep.key}) — input: "${content.substring(0, 50)}"`);
    return message.channel.send(currentStep.error);
  }

  session.answers[currentStep.key] = validated;
  session.step++;
  console.log(`[SMSubmit] ${message.author.tag} (${userId}) completed step ${stepIndex} (${currentStep.key}): "${String(validated).substring(0, 80)}"`);

  if (session.step < SM_STEPS.length) {
    await message.channel.send(SM_STEPS[session.step].prompt);
    return;
  }

  // All steps complete — post submission
  smSubmitSessions.delete(userId);
  console.log(`[SMSubmit] ${message.author.tag} (${userId}) completed all steps — building submission`);

  const { platform, contentType, description, credit, content: submittedContent } = session.answers;

  // Roblox username was stored in session at verification time — no second DB call needed
  const robloxUsername = session.robloxUsername || 'Not linked';
  console.log(`[SMSubmit] Using Roblox username from session for ${userId}: ${robloxUsername}`);

  const submissionEmbed = new EmbedBuilder()
    .setColor(0xf47fff)
    .setTitle('📬 New Social Media Submission')
    .addFields(
      { name: '👤 Roblox Username', value: robloxUsername,   inline: true },
      { name: '🏷️ Discord',         value: `<@${userId}>`,   inline: true },
      { name: '📱 Platform',        value: platform,         inline: true },
      { name: '🎞️ Content Type',    value: contentType,      inline: true },
      { name: '✏️ Credit As',       value: credit,           inline: true },
      { name: '📝 Description',     value: description,      inline: false },
      { name: '📎 Content',         value: submittedContent, inline: false },
    )
    .setTimestamp()
    .setFooter({ text: `User ID: ${userId}` });

  try {
    console.log(`[SMSubmit] Fetching submissions channel (${SM_SUBMISSIONS_CHANNEL_ID})...`);
    const submissionsChannel = await client.channels.fetch(SM_SUBMISSIONS_CHANNEL_ID);
    const submissionDoc = await SocialMediaSubmission.create({
      submissionId: createOperationalId("SMSUB"),
      submittedByDiscordId: userId,
      submittedByTag: message.author.tag,
      robloxUsername,
      platform,
      contentType,
      description,
      credit,
      content: submittedContent,
      history: [{ status: "pending", by: userId, byTag: message.author.tag, at: new Date(), source: "dm_submit" }],
    });
    const reviewMessage = await submissionsChannel.send({
      content: `<@&${SM_COMMS_ROLE_ID}>`,
      embeds:  [buildSocialMediaSubmissionEmbed(submissionDoc), submissionEmbed],
      components: [buildSocialMediaSubmissionRow(submissionDoc.submissionId)],
      allowedMentions: { roles: [SM_COMMS_ROLE_ID] },
    });
    submissionDoc.reviewChannelId = submissionsChannel.id;
    submissionDoc.reviewMessageId = reviewMessage.id;
    submissionDoc.updatedAt = new Date();
    await submissionDoc.save();
    console.log(`[SMSubmit] ✅ Submission posted successfully for ${message.author.tag} (${userId}) | Platform: ${platform} | Type: ${contentType} | Roblox: ${robloxUsername}`);

    const confirmEmbed = new EmbedBuilder()
      .setColor(0x6bcf7f)
      .setTitle('✅ Submission Received!')
      .setDescription(
        "Your submission has been sent to the Public Relations Department for review.\n\n" +
        "**What happens next?**\n" +
        "• The team will review your submission.\n" +
        "• If approved, it may be posted on our official socials.\n" +
        `• Submission ID: **${submissionDoc.submissionId}**\n` +
        `• You'll be credited as: **${credit}**\n\n` +
        "Thanks for contributing to Sweetsiez! 💗"
      )
      .setFooter({ text: 'Sweetsiez Public Relations Aspirant' });

    await message.channel.send({ embeds: [confirmEmbed] });

  } catch (err) {
    console.error(`[SMSubmit] ❌ Failed to post submission for ${message.author.tag} (${userId}):`, err.message);
    console.error(`[SMSubmit] Stack:`, err.stack);
    await message.channel.send('❌ Something went wrong posting your submission. Please try again later or contact a Public Relations Department member.');
  }
});

// Clean up stale sessions older than 30 minutes
setInterval(() => {
  const now = Date.now();
  for (const [userId, session] of reportSessions.entries()) {
    if (now - (session.lastActivity || session.startedAt) > 30 * 60 * 1000) {
      reportSessions.delete(userId);
      client.users.fetch(userId)
        .then(user => user.send("Your unfinished report expired after 30 minutes. DM `!report` to start again."))
        .catch(() => {});
    }
  }

  for (const [userId, session] of smSubmitSessions.entries()) {
    if (now - session.startedAt > 30 * 60 * 1000) {
      console.log(`[SMSubmit] Stale session cleaned up for user ${userId} (started ${Math.round((now - session.startedAt) / 60000)}min ago)`);
      smSubmitSessions.delete(userId);
    }
  }
}, 5 * 60 * 1000);

