// ─────────────────────────────────────────────────────────────
// !rankdiag [username|userId] — read-only ranking pipeline health report
// Shows whether the Open Cloud key is enabled/scoped, which group roles were
// fetched, which of the bot's rank numbers are missing, and (optionally) the
// membership + current roles of one member. Never changes a rank.
// ─────────────────────────────────────────────────────────────
client.on('messageCreate', async message => {
  if (!message.guild || !message.content) return;
  if (!message.content.toLowerCase().startsWith('!rankdiag')) return;

  const isAdmin = message.member?.permissions?.has(PermissionFlagsBits.Administrator);
  if (!isAdmin) {
    let verifiedRank = 0;
    try {
      verifiedRank = await getVerifiedMainRankForDiscord(message.author.id);
    } catch {
      verifiedRank = 0;
    }
    if (!(Number(verifiedRank) >= SWEETSIEZ_STRUCTURE_CONFIG.CEO_RANK)) {
      await message.reply('Only Administrators or leadership (rank 22+) can run the ranking diagnostic.').catch(() => {});
      return;
    }
  }

  await message.channel.sendTyping().catch(() => {});

  const args = message.content.split(/\s+/).slice(1).filter(Boolean);
  let targetUserId = null;
  if (args[0]) {
    targetUserId = /^\d+$/.test(args[0]) ? args[0] : await getRobloxUserId(args[0]).catch(() => null);
    if (!targetUserId) {
      await message.reply(`Could not resolve Roblox user \`${args[0]}\`.`).catch(() => {});
      return;
    }
  }

  try {
    const report = await runRankDiagnostics(targetUserId);
    const chunks = [];
    let current = '';
    for (const line of report.text.split('\n')) {
      if ((current + '\n' + line).length > 1900) {
        chunks.push(current);
        current = line;
      } else {
        current = current ? `${current}\n${line}` : line;
      }
    }
    if (current) chunks.push(current);

    for (const chunk of chunks) {
      await message.channel.send({ content: '```\n' + chunk + '\n```' }).catch(async () => {
        await message.channel.send({ content: chunk }).catch(() => {});
      });
    }
  } catch (error) {
    await message.reply(`Rank diagnostic failed: ${error.message}`).catch(() => {});
  }
});

// ─────────────────────────────────────────────────────────────
// !placementaudit [fix] — shows every stored department placement next to the member's
// LIVE rank, so a placement left behind by a resignation, termination or demotion is
// visible instead of quietly steering quotas. Read-only unless `fix` is passed.
// Administrator or rank 22+.
// ─────────────────────────────────────────────────────────────
client.on('messageCreate', async message => {
  if (!message.guild || !message.content) return;
  const auditCommand = message.content.trim();
  if (!auditCommand.toLowerCase().startsWith('!placementaudit')) return;

  const isAdmin = message.member?.permissions?.has(PermissionFlagsBits.Administrator);
  if (!isAdmin) {
    let verifiedRank = 0;
    try {
      verifiedRank = await getVerifiedMainRankForDiscord(message.author.id);
    } catch {
      verifiedRank = 0;
    }
    if (!(Number(verifiedRank) >= SWEETSIEZ_STRUCTURE_CONFIG.CEO_RANK)) {
      await message.reply('Only Administrators or leadership (rank 22+) can run the placement audit.').catch(() => {});
      return;
    }
  }

  const shouldFix = /\bfix\b/i.test(auditCommand);
  await message.channel.sendTyping().catch(() => {});

  try {
    if (shouldFix) {
      const result = await reconcileStaleStaffPlacements(`!placementaudit fix by ${message.author.tag}`);
      await message.reply(
        `Placement audit repaired **${result.cleared}** of **${result.checked}** stored placement(s). ` +
        'Suspended members are skipped so their department survives the restore.',
      ).catch(() => {});
      return;
    }

    const placements = await StaffPlacement.find({}).lean();
    if (!placements.length) {
      await message.reply('No department placements are stored.').catch(() => {});
      return;
    }

    const lines = ['Department placements vs live rank:', ''];
    for (const placement of placements) {
      let verdict = 'UNKNOWN (lookup failed)';
      if (suspensions.has(placement.discordId)) {
        verdict = 'SKIPPED (suspended — placement kept for restore)';
      } else {
        const robloxUserId = placement.robloxUserId ||
          await getRobloxUserId(placement.robloxUsername).catch(() => null);
        const membership = robloxUserId
          ? await getMainGroupMembershipStatus(robloxUserId).catch(() => null)
          : null;
        if (membership?.ok) {
          if (!membership.inGroup) {
            verdict = 'STALE (no longer in the group)';
          } else {
            const expectedType = getDepartmentPlacementTypeForRank(membership.rank);
            verdict = expectedType === placement.placementType
              ? `OK (rank ${membership.rank} ${membership.name || ''})`.trim()
              : `STALE (rank ${membership.rank} ${membership.name || ''} carries no ${placement.placementType} placement)`.trim();
          }
        }
      }
      lines.push(
        `<@${placement.discordId}> ${placement.robloxUsername} — ${placement.placementType}:${placement.placementKey} — ${verdict}`,
      );
    }
    lines.push('', 'Run `!placementaudit fix` to clear every STALE placement.');

    let current = '';
    const chunks = [];
    for (const line of lines) {
      if ((current ? current + '\n' + line : line).length > 1800) {
        chunks.push(current);
        current = line;
      } else {
        current = current ? `${current}\n${line}` : line;
      }
    }
    if (current) chunks.push(current);

    for (const chunk of chunks) {
      await message.channel.send({ content: chunk, allowedMentions: { parse: [] } }).catch(() => {});
    }
  } catch (error) {
    await message.reply(`Placement audit failed: ${error.message}`).catch(() => {});
  }
});

// ─────────────────────────────────────────────────────────────
// !channelcheck — resolves every configured channel/forum/role id against the live
// guild, so the department consolidation can be planned from real names.
// Read-only. Administrator or rank 22+.
// ─────────────────────────────────────────────────────────────
client.on('messageCreate', async message => {
  if (!message.guild || !message.content) return;
  if (message.content.trim().toLowerCase() !== '!channelcheck') return;

  const isAdmin = message.member?.permissions?.has(PermissionFlagsBits.Administrator);
  if (!isAdmin) {
    let verifiedRank = 0;
    try {
      verifiedRank = await getVerifiedMainRankForDiscord(message.author.id);
    } catch {
      verifiedRank = 0;
    }
    if (!(Number(verifiedRank) >= SWEETSIEZ_STRUCTURE_CONFIG.CEO_RANK)) {
      await message.reply('Only Administrators or leadership (rank 22+) can run the channel check.').catch(() => {});
      return;
    }
  }

  await message.channel.sendTyping().catch(() => {});

  const guild = message.guild;
  const lines = [];
  const missing = [];

  const channelLine = (label, id) => {
    if (!id) {
      lines.push(`  ${label}: —`);
      return;
    }
    const channel = guild.channels.cache.get(String(id));
    if (!channel) {
      lines.push(`  ${label}: ⚠️ MISSING (${id})`);
      missing.push(`${label} (${id})`);
      return;
    }
    const parent = channel.parent ? ` [${channel.parent.name}]` : '';
    lines.push(`  ${label}: ${channel.type === ChannelType.GuildForum ? 'forum ' : '#'}${channel.name}${parent}`);
  };

  const roleLine = (label, idOrName, byName = false) => {
    const role = byName ? resolveGuildRoleByName(guild, idOrName) : guild.roles.cache.get(String(idOrName));
    if (!idOrName) {
      lines.push(`  ${label}: —`);
      return;
    }
    lines.push(`  ${label}: ${role ? `@${role.name}` : `⚠️ MISSING (${idOrName})`}`);
  };

  lines.push('CHANNELS');
  for (const [key, id] of Object.entries(SWEETSIEZ_STRUCTURE_CONFIG.CHANNELS || {})) {
    channelLine(`CHANNELS.${key}`, id);
  }

  lines.push('');
  lines.push('DEPARTMENTS / BOARDS');
  for (const [key, board] of Object.entries(SWEETSIEZ_STRUCTURE_CONFIG.BOARDS || {})) {
    if (board.retired) continue; // merged away (e.g. relations -> engagement)
    lines.push(`  ${key} — ${board.label || key}`);
    channelLine(`    forum`, board.forumChannelId);
    channelLine(`    discussion`, board.discussionChannelId);
    roleLine(`    member role`, board.roleId);
    roleLine(`    head role`, board.headRoleId || board.headRoleName, !board.headRoleId);
    roleLine(`    co-lead role`, board.coHeadRoleId || board.coHeadRoleName, !board.coHeadRoleId);
  }

  lines.push('');
  lines.push('SUB-TEAMS');
  for (const [key, team] of Object.entries(SWEETSIEZ_STRUCTURE_CONFIG.TEAMS || {})) {
    if (team.retired) continue; // merged away (e.g. outreach -> engagement aspirant)
    lines.push(`  ${key} — ${team.label || key} (department: ${team.boardKey || '?'})`);
    channelLine(`    forum`, team.forumChannelId);
    roleLine(`    role`, team.roleId);
  }

  lines.push('');
  lines.push('FORUMS / LOGS / OTHER');
  for (const [key, id] of Object.entries(config.FORUMS || {})) channelLine(`FORUMS.${key}`, id);
  channelLine('STAFF_PROFILE.shift_lead', STAFF_PROFILE_CONFIG.SHIFT_LEAD_FORUM_ID);
  channelLine('STAFF_PROFILE.management', STAFF_PROFILE_CONFIG.MANAGEMENT_FORUM_ID);
  channelLine('SHIFT_CLAIM_FORUM', SHIFT_CLAIMING_CONFIG.FORUM_CHANNEL_ID);
  channelLine('ALLIANCE_FORUM', ALLIANCE_FORUM_CHANNEL_ID);
  channelLine('ALLIANCE_PRIVATE_CATEGORY', ALLIANCE_SYSTEM_CONFIG.PRIVATE_CATEGORY_ID);
  channelLine('ALLIANCE_TERMINATED_CATEGORY', ALLIANCE_SYSTEM_CONFIG.TERMINATED_CATEGORY_ID);
  channelLine('SECOND_APPROVAL', SECOND_APPROVAL_CHANNEL_ID);
  channelLine('ADMIN_ABUSE_LEADERSHIP', ADMIN_ABUSE_LEADERSHIP_CHANNEL_ID);
  channelLine('DISCORD_MOD_LOG_FORUM', DISCORD_MOD_LOG_FORUM_ID);
  channelLine('ROBLOX_BAN_LOG_FORUM', ROBLOX_BAN_LOG_FORUM_ID);
  channelLine('PUNISHMENT_LOG', config.PUNISHMENT_LOG_CHANNEL_ID);
  channelLine('LR_DEMOTION_LOG', config.LR_DEMOTION_LOG_CHANNEL_ID);
  channelLine('RANKING_LOG', config.RANKING_LOG_CHANNEL_ID);
  channelLine('COMMUNITY', config.COMMUNITY_CHANNEL_ID);
  channelLine('TICKET_LOG', config.TICKET_LOG_CHANNEL_ID);

  lines.push('');
  lines.push('VOTE / ROUTING CHANNELS (hardcoded literals, not CHANNELS keys)');
  for (const entry of VOTES_CHANNELS) {
    channelLine(`VOTES.${entry.key}`, entry.channelId);
    if (entry.roleId) roleLine(`    role`, entry.roleId);
    if (Array.isArray(entry.roleIds)) {
      entry.roleIds.forEach((roleId, index) => roleLine(`    role[${index}]`, roleId));
    }
  }

  lines.push('');
  lines.push('ROLES');
  roleLine('President', 'President', true);
  roleLine('Director', 'Director', true);
  roleLine('Executive', 'Executive', true);
  roleLine('Manager', 'Manager', true);
  roleLine('Supervisor', 'Supervisor', true);
  roleLine('Shift Lead', 'Shift Lead', true);
  roleLine('Soda Jerk', 'Soda Jerk', true);
  roleLine('Supporter', 'Supporter', true);
  roleLine('Honored', 'Honored', true);
  roleLine('Administration', ADMINISTRATION_ROLE_NAME, true);
  roleLine('Human Resources Aspirant', 'Human Resources Aspirant', true);
  roleLine('Public Relations Aspirant', 'Public Relations Aspirant', true);
  roleLine('SECOND_APPROVAL ping (Executive+)', SECOND_APPROVAL_PING_ROLE_ID);
  roleLine('SECOND_APPROVAL higher-tier ping (Director+)', SECOND_APPROVAL_ED_PING_ROLE_ID);
  roleLine('ADMIN_ABUSE leadership ping', ADMIN_ABUSE_LEADERSHIP_PING_ROLE_ID);

  if (missing.length > 0) {
    lines.push('');
    lines.push(`⚠️ ${missing.length} configured id(s) do not resolve in this guild:`);
    missing.forEach(entry => lines.push(`  ${entry}`));
  }

  const chunks = [];
  let current = '';
  for (const line of lines) {
    if ((current + '\n' + line).length > 1850) {
      chunks.push(current);
      current = line;
    } else {
      current = current ? `${current}\n${line}` : line;
    }
  }
  if (current) chunks.push(current);

  for (const chunk of chunks) {
    await message.channel.send({ content: '\`\`\`\n' + chunk + '\n\`\`\`' }).catch(async () => {
      await message.channel.send({ content: chunk }).catch(() => {});
    });
  }
});

// ─────────────────────────────────────────────────────────────
// !trellosync — Phase 1: create a card for every current Supervisor+ staff member.
// Creates only. Administrator or rank 22+.
// ─────────────────────────────────────────────────────────────
client.on('messageCreate', async message => {
  if (!message.guild || !message.content) return;
  if (message.content.trim().toLowerCase() !== '!trellosync') return;

  const isAdmin = message.member?.permissions?.has(PermissionFlagsBits.Administrator);
  if (!isAdmin) {
    let rank = 0;
    try {
      rank = await getVerifiedMainRankForDiscord(message.author.id);
    } catch {
      rank = 0;
    }
    if (!(Number(rank) >= SWEETSIEZ_STRUCTURE_CONFIG.CEO_RANK)) {
      await message.reply('Only Administrators or leadership (rank 22+) can run the Trello sync.').catch(() => {});
      return;
    }
  }

  if (!isTrelloConfigured()) {
    await message.reply('Trello is not configured. Set TRELLO_KEY, TRELLO_TOKEN and TRELLO_BOARD_ID on the host.').catch(() => {});
    return;
  }

  await message.channel.sendTyping().catch(() => {});
  const status = await message.reply('Trello sync starting — reading the board...').catch(() => null);

  try {
    const { lists, byRank } = await getTrelloListIdByRank();
    const { findLabel } = await getTrelloLabelIds();

    const missingLists = Object.entries(TRELLO_CONFIG.RANK_LIST_WORDS)
      .filter(([rankKey]) => !byRank.has(Number(rankKey)))
      .map(([, word]) => word);

    // The board already holds a card for every current staff member, so the sync ADOPTS those
    // rather than creating duplicates — matching anywhere on the board, not just the target list,
    // so a card left in the wrong list gets moved instead of duplicated.
    const boardCards = await trelloApi('get', `/boards/${TRELLO_CONFIG.BOARD_ID}/cards`, { fields: 'name,idList' }).catch(() => []);
    const cardByName = new Map();
    for (const card of boardCards || []) {
      const cardKey = String(card.name || '').trim().toLowerCase();
      if (cardKey && !cardByName.has(cardKey)) cardByName.set(cardKey, { id: card.id, idList: card.idList });
    }

    const listNameById = new Map((lists || []).map(list => [list.id, list.name]));
    const rankListIds = new Set(byRank.values());
    const matchedCardIds = new Set();

    const created = [];
    const moved = [];
    const already = [];   // card found, already in the correct list
    const noList = [];    // member's rank has no matching Trello list — never processed
    const failed = [];

    // Fetch everyone first: the member cache is partial, so iterating it silently misses most
    // staff (their cards then look unmatched, and Phase 2 could miss their promotions).
    const allMembers = await fetchAllGuildMembersWithRetry(message.guild, {
      context: 'Trello sync',
    }).catch(() => message.guild.members.cache);

    for (const member of allMembers.values()) {
      if (member.user?.bot) continue;
      const rankInfo = inferStaffRankFromDiscordRoles(member);
      if (!rankInfo || Number(rankInfo.rank) < 9) continue;

      const rank = Number(rankInfo.rank);
      const listId = byRank.get(rank);
      const word = TRELLO_CONFIG.RANK_LIST_WORDS[rank];
      if (!listId) { noList.push(`${member.user.username} (rank ${rank}, looking for "${word}")`); continue; }

      const cardName = member.displayName || member.user.username;
      // Existing cards may be titled with the display name, the Discord username, or the Roblox
      // username, so try all three.
      const robloxName = verifiedUsers.get(member.id);
      const existing = [cardName, member.user.username, robloxName]
        .filter(Boolean)
        .map(value => cardByName.get(String(value).trim().toLowerCase()))
        .find(Boolean);

      if (existing && existing.idList === listId) {
        matchedCardIds.add(existing.id);
        already.push(`${cardName} → ${word}`);
        continue;
      }

      if (existing) {
        // Card exists but in the wrong list — move it rather than create a second one.
        try {
          await trelloApi('put', `/cards/${existing.id}`, { idList: listId });
          existing.idList = listId;
          matchedCardIds.add(existing.id);
          moved.push(`${cardName} → ${word}`);
          await sleep(700);
        } catch (error) {
          failed.push(`${cardName} (move to ${word}): ${error.message}`);
        }
        continue;
      }

      const labelIds = [];
      if (word) {
        const rankLabel = findLabel(word);
        if (rankLabel) labelIds.push(rankLabel);
      }
      if (TRELLO_CONFIG.DEPARTMENT_LABEL_RANKS.has(rank)) {
        const placement = await getStaffPlacement(member.id).catch(() => null);
        const deptWord = TRELLO_CONFIG.DEPARTMENT_LABEL_WORDS[placement?.placementKey];
        if (deptWord) {
          const deptLabel = findLabel(deptWord);
          if (deptLabel) labelIds.push(deptLabel);
        }
      }

      const today = formatTrelloDate();
      try {
        const createdCard = await trelloApi('post', '/cards', {
          idList: listId,
          name: cardName,
          desc: `${word}: ${today}`,
          idLabels: labelIds.join(','),
        });
        if (createdCard?.id) matchedCardIds.add(createdCard.id);
        cardByName.set(cardName.trim().toLowerCase(), { id: createdCard?.id || 'created', idList: listId });
        created.push(`${cardName} → ${word}`);
        await sleep(700);
      } catch (error) {
        failed.push(`${cardName}: ${describeRobloxError(error) || error.message}`);
      }
    }

    const lines = [
      `**Trello sync complete** — ${created.length} created, ${moved.length} moved, ${already.length} already correct, ${noList.length} with no matching list, ${failed.length} failed.`,
      `Board: ${TRELLO_CONFIG.BOARD_ID} · lists seen: ${lists.length} · cards on board: ${cardByName.size}`,
    ];
    if (noList.length) {
      lines.push('', `⚠️ ${noList.length} staff member(s) could not be processed — no Trello list matched their rank:`);
      noList.slice(0, 15).forEach(entry => lines.push(`  ${entry}`));
    }
    if (missingLists.length) lines.push(`⚠️ No list found for: ${missingLists.join(', ')}`);
    if (created.length) lines.push('', 'Created:', ...created.slice(0, 20).map(entry => `  ${entry}`));
    if (moved.length) lines.push('', 'Moved to the correct list:', ...moved.slice(0, 20).map(entry => `  ${entry}`));

    // Cards sitting in a RANK list that no staff member matched. Cards on the information list
    // are out of scope by design.
    const unmatched = (boardCards || []).filter(card => rankListIds.has(card.idList) && !matchedCardIds.has(card.id));
    if (unmatched.length) {
      lines.push('', `⚠️ ${unmatched.length} card(s) in a rank list matched no staff member:`);
      unmatched.slice(0, 15).forEach(card =>
        lines.push(`  ${card.name} — ${listNameById.get(card.idList) || card.idList}`));
      lines.push('  (either their Discord rank roles are missing, or the card is stale)');
    } else {
      lines.push('', 'Every card in the rank lists matched a staff member.');
    }
    if (failed.length) lines.push('', 'Failed:', ...failed.slice(0, 10).map(entry => `  ${entry}`));
    if (already.length) lines.push('', `Already correct (${already.length}):`, ...already.slice(0, 20).map(entry => `  ${entry}`));

    const summary = lines.join('\n');
    if (status) await status.edit(summary.slice(0, 1900)).catch(() => {});
    else await message.channel.send(summary.slice(0, 1900)).catch(() => {});
  } catch (error) {
    const text = `Trello sync failed: ${error.message}`;
    if (status) await status.edit(text).catch(() => {});
    else await message.reply(text).catch(() => {});
  }
});

// ─────────────────────────────────────────────────────────────
// Trello Phase 2a — rank-change routine. Additive: not yet called by promotions.
// ─────────────────────────────────────────────────────────────

// One row per rank held, so tenure is derivable and you get a promotion history for free.
const rankHistorySchema = new mongoose.Schema({
  discordId: { type: String, required: true, index: true },
  robloxUserId: { type: String, default: null, index: true },
  rank: { type: Number, required: true },
  rankName: { type: String, default: null },
  startedAt: { type: Date, default: Date.now },
  endedAt: { type: Date, default: null },
  source: { type: String, default: "bot" },
  changedBy: { type: String, default: null },
  reason: { type: String, default: null },
  trelloCardId: { type: String, default: null },
}, { collection: "rankhistory" });

const RankHistory = mongoose.models.RankHistory ||
  mongoose.model("RankHistory", rankHistorySchema);

// Cards already handled, so both triggers seeing the same change cannot double-comment.
const trelloHandledEvents = new Set();

function trelloDepartmentLabelWord(discordId) {
  return getStaffPlacement(discordId)
    .then(placement => TRELLO_CONFIG.DEPARTMENT_LABEL_WORDS[placement?.placementKey] || null)
    .catch(() => null);
}

/** Find a member's card, or null. */
async function findTrelloCardForMember(member) {
  const stored = await RankHistory.findOne({ discordId: member.id, trelloCardId: { $ne: null } })
    .sort({ endedAt: -1 }).lean().catch(() => null);
  if (stored?.trelloCardId) {
    const card = await trelloApi("get", `/cards/${stored.trelloCardId}`, { fields: "name,idList,desc,closed" })
      .catch(() => null);
    if (card && !card.closed) return card;
  }

  const { findLabel } = await getTrelloLabelIds().catch(() => ({ findLabel: () => null }));
  void findLabel;
  const cards = await trelloApi("get", `/boards/${TRELLO_CONFIG.BOARD_ID}/cards`, { fields: "name,idList,desc" })
    .catch(() => []);
  const robloxName = verifiedUsers.get(member.id);
  const candidates = [member.displayName, member.user.username, robloxName]
    .filter(Boolean)
    .map(value => String(value).trim().toLowerCase());
  return (cards || []).find(card => candidates.includes(String(card.name || "").trim().toLowerCase())) || null;
}

/**
 * Apply a rank change to the board. Fire-and-forget: never throws into the caller.
 * fromRank may be null (unknown), in which case no tenure comment is posted.
 */
async function syncTrelloRankChange({ member, fromRank, toRank, fromRankName, actorTag, reason, source = "bot" }) {
  if (!isTrelloConfigured() || !member) return { ok: false, reason: "not-configured" };

  // Below Supervisor they are no longer staff, and no Trello list exists for those ranks: archive
  // the card rather than leaving it stranded in its old list.
  if (Number(toRank) < MANAGER_SYSTEM_CONFIG.SHIFT_LEAD_RANK) {
    const openRow = await RankHistory.findOne({ discordId: member.id, endedAt: null })
      .sort({ startedAt: -1 }).catch(() => null);
    if (openRow) {
      openRow.endedAt = new Date();
      await openRow.save().catch(() => null);
    }

    const archived = await archiveTrelloCard(member);
    console.log(
      archived.ok
        ? `[Trello] archived card for ${member.displayName} — now rank ${toRank}, no longer staff`
        : `[Trello] could not archive card for ${member.displayName}: ${archived.reason}`,
    );
    return archived;
  }

  const word = TRELLO_CONFIG.RANK_LIST_WORDS[Number(toRank)];
  if (!word) return { ok: false, reason: `no list word for rank ${toRank}` };

  const eventKey = `${member.id}:${toRank}:${new Date().toISOString().slice(0, 10)}`;
  if (trelloHandledEvents.has(eventKey)) return { ok: false, reason: "already-handled" };

  try {
    const { byRank } = await getTrelloListIdByRank();
    const listId = byRank.get(Number(toRank));
    if (!listId) return { ok: false, reason: `no Trello list matched "${word}"` };

    // Close the previous rank row so tenure is derivable.
    const openRow = await RankHistory.findOne({ discordId: member.id, endedAt: null })
      .sort({ startedAt: -1 }).catch(() => null);
    let tenureDays = null;
    if (openRow) {
      tenureDays = Math.max(0, Math.round((Date.now() - new Date(openRow.startedAt).getTime()) / 86400000));
      openRow.endedAt = new Date();
      await openRow.save().catch(() => null);
    }

    const card = await findTrelloCardForMember(member);
    if (!card) return { ok: false, reason: "no card found for this member" };

    // Labels: rank always, department only for Executive (13) and Director (22).
    const { findLabel } = await getTrelloLabelIds();
    const labelIds = [];
    const rankLabel = findLabel(word);
    if (rankLabel) labelIds.push(rankLabel);
    if (TRELLO_CONFIG.DEPARTMENT_LABEL_RANKS.has(Number(toRank))) {
      const deptWord = await trelloDepartmentLabelWord(member.id);
      if (deptWord) {
        const deptLabel = findLabel(deptWord);
        if (deptLabel) labelIds.push(deptLabel);
      }
    }

    // Append the rank line — never replace, so the timeline accumulates. Skip the append when the
    // last line already reads the same, so a repeated event cannot stack duplicate lines.
    const line = `${word}: ${formatTrelloDate()}`;
    const existingLines = String(card.desc || "").split("\n").map(entry => entry.trim()).filter(Boolean);
    const lastLine = existingLines[existingLines.length - 1] || "";
    const alreadyRecorded = lastLine === line;
    const desc = alreadyRecorded
      ? card.desc
      : (card.desc && card.desc.trim() ? `${card.desc.trimEnd()}\n${line}` : line);

    await trelloApi("put", `/cards/${card.id}`, {
      idList: listId,
      desc,
      idLabels: labelIds.join(","),
    });

    // Comment only on a promotion (a move up), per the public-board rule.
    const isPromotion = fromRank != null && Number(toRank) > Number(fromRank);
    if (isPromotion && tenureDays != null && fromRankName) {
      await sleep(500);
      await trelloApi("post", `/cards/${card.id}/actions/comments`, {
        text: `Time spent as ${fromRankName}: ${tenureDays} Days`,
      }).catch(() => null);
    }

    const newRow = await RankHistory.create({
      discordId: member.id,
      robloxUserId: null,
      rank: Number(toRank),
      rankName: word,
      startedAt: new Date(),
      source,
      changedBy: actorTag || null,
      reason: reason || null,
      trelloCardId: card.id,
    }).catch(() => null);
    void newRow;

    trelloHandledEvents.add(eventKey);
    return { ok: true, cardId: card.id, listId, tenureDays, commented: isPromotion && tenureDays != null };
  } catch (error) {
    console.warn("[Trello] rank change sync failed:", error.message);
    return { ok: false, reason: error.message };
  }
}

/** Termination / resignation: archive, never delete, never move. */
async function archiveTrelloCard(member) {
  if (!isTrelloConfigured() || !member) return { ok: false, reason: "not-configured" };
  try {
    const card = await findTrelloCardForMember(member);
    if (!card) return { ok: false, reason: "no card found" };
    await trelloApi("put", `/cards/${card.id}`, { closed: true });
    return { ok: true, cardId: card.id };
  } catch (error) {
    return { ok: false, reason: error.message };
  }
}

// !trellocard @member <rankNumber> [reason] — manually exercise the routine on one member.
// Administrator or rank 22+.
client.on('messageCreate', async message => {
  if (!message.guild || !message.content) return;
  const match = message.content.trim().match(/^!trellocard\s+<@!?(\d+)>\s+(\d{1,3})(?:\s+(.+))?$/i);
  if (!match) return;

  const isAdmin = message.member?.permissions?.has(PermissionFlagsBits.Administrator);
  if (!isAdmin) {
    let rank = 0;
    try { rank = await getVerifiedMainRankForDiscord(message.author.id); } catch { rank = 0; }
    if (!(Number(rank) >= SWEETSIEZ_STRUCTURE_CONFIG.CEO_RANK)) {
      await message.reply('Only Administrators or leadership (rank 22+) can run this.').catch(() => {});
      return;
    }
  }

  const targetMember = await message.guild.members.fetch(match[1]).catch(() => null);
  if (!targetMember) { await message.reply('Could not find that member.').catch(() => {}); return; }
  const toRank = Number(match[2]);
  const reason = match[3] || 'manual test';

  const current = inferStaffRankFromDiscordRoles(targetMember);
  const fromRank = current ? Number(current.rank) : null;
  const fromRankName = fromRank ? (TRELLO_CONFIG.RANK_LIST_WORDS[fromRank] || `rank ${fromRank}`) : null;

  const result = await syncTrelloRankChange({
    member: targetMember,
    fromRank,
    toRank,
    fromRankName,
    actorTag: message.author.tag,
    reason,
    source: 'manual',
  });

  const text = result.ok
    ? `✅ Card updated for ${targetMember.displayName}\n· list → ${TRELLO_CONFIG.RANK_LIST_WORDS[toRank]}\n· description line appended\n· tenure comment: ${result.commented ? `yes (${result.tenureDays} days as ${fromRankName})` : 'no'}`
    : `⚠️ No change made: ${result.reason}`;
  await message.reply(text).catch(() => {});
});

// ─────────────────────────────────────────────────────────────
// Automatic promotion announcements
// ─────────────────────────────────────────────────────────────
const PROMOTION_ANNOUNCE_CONFIG = {
  STAFF_CHANNEL_ID: "1515779963880734950",       // Supervisor, Manager, Executive
  // Director/President notices go to the public announcements channel — this is the id the bot
  // already uses for ANNOUNCEMENT_CHANNEL_ID / PUBLIC_ANNOUNCEMENTS.
  LEADERSHIP_CHANNEL_ID: "1472340217859145975",  // Director, President
  STAFF_PING_ROLE_ID: "1472318662215073858",
  TEMPLATES: {
    9: "🧁 **SUPERVISOR PROMOTION NOTICE**\n\nGreetings! The Human Resources Department is pleased to congratulate {user} on their promotion to **Supervisor**! We look forward to seeing them support our staff, host shifts, and contribute to the continued success of Sweetsiez. Please join us in congratulating them on this achievement!",
    12: "🧁 **MANAGER PROMOTION NOTICE**\n\nGreetings! The Human Resources Department is delighted to announce the promotion of {user} to **Manager**! In this role, they will help develop our staff, support management operations, and contribute to their assigned department. Please join us in congratulating them on this exciting milestone!",
    13: {
      operations: "🧁 **HUMAN RESOURCES EXECUTIVE PROMOTION NOTICE**\n\nGreetings! The Human Resources Department is thrilled to congratulate {user} on their promotion to **Executive** within Human Resources! They will help oversee staff development, internal operations, documentation, and policy implementation while supporting the growth of our department. Please join us in celebrating this achievement!",
      neutral: "🧁 **EXECUTIVE PROMOTION NOTICE**\n\nGreetings! The administration is delighted to announce {user}'s promotion to **Executive**! In this role they will help lead a department, support staff development, and contribute to the continued success of Sweetsiez. Please join us in congratulating them on this achievement!",
      moderation: "🧁 **DISCORD MODERATION EXECUTIVE PROMOTION NOTICE**\n\nGreetings! The Discord Moderation Department is delighted to congratulate {user} on their promotion to **Executive** within Discord Moderation! They will help issue and review Discord warnings and bans, decide ban and warning appeals, and keep our server safe through automod and incident response. Please join us in celebrating this achievement and welcoming them into their expanded responsibilities!",
      engagement: "🧁 **PUBLIC RELATIONS EXECUTIVE PROMOTION NOTICE**\n\nGreetings! The Public Relations Department is delighted to congratulate {user} on their promotion to **Executive** within Public Relations! They will help lead our content, branding, social media, community engagement, and outreach initiatives. Please join us in celebrating this achievement and welcoming them into their expanded responsibilities!",
    },
    22: {
      operations: "🧁 **HUMAN RESOURCES DIRECTOR PROMOTION NOTICE**\n\nGreetings! The administration is proud to announce {user}'s promotion to **Director**, serving as the **Human Resources Lead**! They will oversee departmental operations, staff development, documentation, and policy implementation while guiding our Human Resources team. Please join us in congratulating them on this distinguished achievement!",
      neutral: "🧁 **DIRECTOR PROMOTION NOTICE**\n\nGreetings! The administration is proud to announce {user}'s promotion to **Director**! They will lead a department, oversee its operations and development, and help guide Sweetsiez forward. Please join us in congratulating them on this distinguished achievement!",
      moderation: "🧁 **DISCORD MODERATION DIRECTOR PROMOTION NOTICE**\n\nGreetings! The administration is proud to announce {user}'s promotion to **Director**, serving as the **Discord Moderation Lead**! They will oversee the department's Discord warnings and bans, ban and warning appeals, and server safety while guiding our Discord Moderation team. Please join us in congratulating them on this distinguished achievement!",
      engagement: "🧁 **PUBLIC RELATIONS DIRECTOR PROMOTION NOTICE**\n\nGreetings! The administration is excited to announce {user}'s promotion to **Director**, serving as the **Public Relations Lead**! They will oversee our public image, content strategy, announcements, events, alliances, and outreach while guiding our Public Relations team. Please join us in congratulating them on this distinguished achievement!",
      // Second seat in the department: a Co-Lead is an APPOINTMENT, not a promotion
      // (departments may hire one from outside), so the wording never says "promoted".
      coLead: {
        operations: "🧁 **HUMAN RESOURCES CO-LEAD APPOINTMENT NOTICE**\n\nGreetings! The administration is proud to announce that {user} now serves as the **Human Resources Co-Lead**, working alongside the Human Resources Lead. Together they will oversee departmental operations, staff development, documentation, and policy implementation while guiding our Human Resources team. Please join us in congratulating them on this distinguished appointment!",
        neutral: "🧁 **CO-LEAD APPOINTMENT NOTICE**\n\nGreetings! The administration is proud to announce that {user} now serves as a **Co-Lead** within their department, working alongside the department Lead to oversee its operations and development. Please join us in congratulating them on this distinguished appointment!",
        moderation: "🧁 **DISCORD MODERATION CO-LEAD APPOINTMENT NOTICE**\n\nGreetings! The administration is proud to announce that {user} now serves as the **Discord Moderation Co-Lead**, working alongside the Discord Moderation Lead. Together they will oversee the department's Discord warnings and bans, ban and warning appeals, and server safety while guiding our Discord Moderation team. Please join us in congratulating them on this distinguished appointment!",
        engagement: "🧁 **PUBLIC RELATIONS CO-LEAD APPOINTMENT NOTICE**\n\nGreetings! The administration is excited to announce that {user} now serves as the **Public Relations Co-Lead**, working alongside the Public Relations Lead. Together they will oversee our public image, content strategy, announcements, events, alliances, and outreach while guiding our Public Relations team. Please join us in congratulating them on this distinguished appointment!",
      },
    },
    255: "🧁 **PRESIDENT PROMOTION NOTICE**\n\nGreetings, everyone! The administration is honored to announce {user}'s promotion to **President** of Sweetsiez! As the highest-ranking member of our organization, they will oversee all operations, guide our long-term development, and uphold the standards that define our community. Please join us in congratulating them on this outstanding accomplishment!",
  },
};

let promotionAnnounceQueue = Promise.resolve();

/**
 * Promotion notices are grouped by DEPARTMENT (operations / engagement), but a placement is
 * keyed by its board or team: operations, marketing, relations (boards) and recruitment,
 * social-media (teams). Looking the template up by the raw placement key meant only Human
 * Resources ever matched — a Public Relations Director was posted the neutral notice.
 */
function getPromotionNoticeDepartmentKey(placement) {
  if (!placement?.placementKey) return null;
  const boardKey = placement.placementType === "team"
    ? getPlacementConfig("team", placement.placementKey)?.boardKey || null
    : placement.placementKey;
  if (!boardKey) return null;
  if (boardKey === "operations") return "operations";
  // Marketing and Relations both resolve to the Public Relations department.
  if (boardKey === "marketing" || boardKey === "relations") return "engagement";
  if (boardKey === "moderation") return "moderation";
  return null;
}

/**
 * The notice text for a promotion, or null when the rank has no template.
 *
 * Deterministic and side-effect free so it can be tested: the department comes from the
 * placement, and for a Director the seat (Lead or Co-Lead) comes from
 * resolveBoardDirectorTier() — the same call the role sync makes — so the notice always
 * matches the role the member holds or is about to be given.
 */
function getPromotionNoticeTemplate({ rank, placement = null, member = null, earlierDirectorPresent = false } = {}) {
  const entry = PROMOTION_ANNOUNCE_CONFIG.TEMPLATES[Number(rank)];
  if (!entry) return null;
  if (typeof entry !== "object") return entry;
  const departmentKey = getPromotionNoticeDepartmentKey(placement);
  const tier = Number(rank) === 22 && placement?.placementType === "board"
    ? resolveBoardDirectorTier(placement.placementKey, member, { earlierDirectorPresent })
    : "lead";
  const tierTemplates = tier === "co-lead" ? (entry.coLead || {}) : entry;
  // Never name a department we cannot confirm: fall back to the neutral text.
  return (departmentKey && tierTemplates[departmentKey]) || tierTemplates.neutral || entry.neutral || null;
}

/** Post a promotion notice. Fire-and-forget; never throws into the caller. */
async function announcePromotion({ guild, member, toRank }) {
  const rank = Number(toRank);
  const entry = PROMOTION_ANNOUNCE_CONFIG.TEMPLATES[rank];
  if (!entry || !guild || !member) return { ok: false, reason: "no notice for this rank" };

  // Executives and Directors get a department-specific notice. Placement is normally written by
  // the same flow that changed the rank, so poll briefly for it rather than assuming a department.
  let template = entry;
  if (typeof entry === "object") {
    let placement = null;
    for (let attempt = 0; attempt < 4; attempt++) {
      placement = await getStaffPlacement(member.id).catch(() => null);
      if (placement?.placementKey) break;
      await sleep(15000);
    }

    if (!getPromotionNoticeDepartmentKey(placement)) {
      // Never name a department we cannot confirm.
      console.warn(
        `[Promotion] no department placement for ${member.displayName} at rank ${rank} ` +
        `(placement: ${placement ? `${placement.placementType}:${placement.placementKey}` : "none"}) — posting a neutral notice`,
      );
    }

    const earlierDirectorPresent = rank === 22 && placement?.placementType === "board"
      ? await hasEarlierBoardDirector(placement.placementKey, member.id)
      : false;
    template = getPromotionNoticeTemplate({ rank, placement, member, earlierDirectorPresent }) || entry.neutral;
  }

  const content = template.replace("{user}", `<@${member.id}>`);
  const leadership = rank >= 22;
  const channelId = leadership
    ? PROMOTION_ANNOUNCE_CONFIG.LEADERSHIP_CHANNEL_ID
    : PROMOTION_ANNOUNCE_CONFIG.STAFF_CHANNEL_ID;

  // Pings: Supervisor/Manager role only; Executive role + @here; Director/President @everyone.
  let ping = "";
  const allowedMentions = { parse: [] };
  if (rank === 255 || rank === 22) {
    ping = "@everyone ";
    allowedMentions.parse = ["everyone"];
  } else if (rank === 13) {
    ping = `<@&${PROMOTION_ANNOUNCE_CONFIG.STAFF_PING_ROLE_ID}> @here `;
    allowedMentions.parse = ["everyone"];
    allowedMentions.roles = [PROMOTION_ANNOUNCE_CONFIG.STAFF_PING_ROLE_ID];
  } else {
    ping = `<@&${PROMOTION_ANNOUNCE_CONFIG.STAFF_PING_ROLE_ID}> `;
    allowedMentions.roles = [PROMOTION_ANNOUNCE_CONFIG.STAFF_PING_ROLE_ID];
  }

  const channel = await guild.channels.fetch(channelId).catch(error => {
    console.warn(`[Promotion] could not fetch channel ${channelId}:`, error.message);
    return null;
  });
  if (!channel?.send) {
    console.warn(`[Promotion] channel ${channelId} is not posted to — check the id and the bot's access`);
    return { ok: false, reason: `channel ${channelId} unavailable` };
  }

  // Ping sits under the notice, on its own line.
  const contentWithPing = ping.trim() ? `${content}\n\n${ping.trim()}` : content;
  const sent = await channel.send({ content: contentWithPing, allowedMentions })
    .then(message => message)
    .catch(error => {
      console.warn("[Promotion] announcement send failed:", error.message);
      return null;
    });
  return sent ? { ok: true, channelId } : { ok: false, reason: "send failed" };
}

// !announcepromo @member <rank> — post a promotion notice on demand, for testing.
client.on('messageCreate', async message => {
  if (!message.guild || !message.content) return;
  const rawCommand = message.content.trim();
  if (!/^!announcepromo\b/i.test(rawCommand)) return;
  const match = rawCommand.match(/^!announcepromo\s+<@!?(\d+)>\s+(\d{1,3})$/i);
  if (!match) {
    await message.reply(
      'Usage: `!announcepromo @member <rank>` — rank must be 9, 12, 13, 22 or 255.\n' +
      'Mention the member (Discord must turn it into a blue mention) and include the rank number, e.g. `!announcepromo @Bob 9`.',
    ).catch(() => {});
    return;
  }

  const isAdmin = message.member?.permissions?.has(PermissionFlagsBits.Administrator);
  if (!isAdmin) {
    let rank = 0;
    try { rank = await getVerifiedMainRankForDiscord(message.author.id); } catch { rank = 0; }
    if (!(Number(rank) >= SWEETSIEZ_STRUCTURE_CONFIG.CEO_RANK)) {
      await message.reply('Only Administrators or leadership (rank 22+) can run this.').catch(() => {});
      return;
    }
  }

  const targetMember = await message.guild.members.fetch(match[1]).catch(() => null);
  if (!targetMember) { await message.reply('Could not find that member.').catch(() => {}); return; }
  const toRank = Number(match[2]);
  if (!PROMOTION_ANNOUNCE_CONFIG.TEMPLATES[toRank]) {
    await message.reply(`No notice template exists for rank ${toRank}. Use 9, 12, 13, 22 or 255.`).catch(() => {});
    return;
  }

  const result = await announcePromotion({ guild: message.guild, member: targetMember, toRank });
  await message.reply(result.ok
    ? `✅ Notice posted to <#${result.channelId}>`
    : `⚠️ Nothing posted: ${result.reason}`).catch(() => {});
});

// !resetshiftpost — rebuild today's shift claim post in the current embed format.
// Administrator or rank 22+.
client.on('messageCreate', async message => {
  if (!message.guild || !message.content) return;
  if (message.content.trim().toLowerCase() !== '!resetshiftpost') return;

  const isAdmin = message.member?.permissions?.has(PermissionFlagsBits.Administrator);
  if (!isAdmin) {
    let rank = 0;
    try { rank = await getVerifiedMainRankForDiscord(message.author.id); } catch { rank = 0; }
    if (!(Number(rank) >= SWEETSIEZ_STRUCTURE_CONFIG.CEO_RANK)) {
      await message.reply('Only Administrators or leadership (rank 22+) can run this.').catch(() => {});
      return;
    }
  }

  const today = getESTDate();
  const displayDate = formatDateForDisplay(today);
  const record = shiftPosts.get(today);
  const claimCount = record?.claimCount ?? 0;

  let thread = record?.threadId
    ? await message.guild.channels.fetch(record.threadId).catch(() => null)
    : null;

  // After a restart the in-memory map is empty even though the thread exists, so fall back to
  // finding today's post in the forum by name.
  if (!thread) {
    const forum = await message.guild.channels.fetch(SHIFT_CLAIMING_CONFIG.FORUM_CHANNEL_ID).catch(() => null);
    const active = forum?.threads ? await forum.threads.fetchActive().catch(() => null) : null;
    thread = active?.threads?.find(candidate => String(candidate.name || '').includes(displayDate)) || null;
  }

  if (!thread) {
    await message.reply(`No shift post for **${displayDate}** found. Create one first (or check the forum name format "Shifts - ${displayDate}").`).catch(() => {});
    return;
  }

  const starter = await thread.fetchStarterMessage().catch(() => null);
  if (!starter) {
    await message.reply('Found the post but could not fetch its starter message.').catch(() => {});
    return;
  }

  // content: "" is required — an embed-only edit leaves the old text in place.
  await starter.edit({ content: "", embeds: [buildShiftClaimEmbed(displayDate, claimCount)] }).catch(error => {
    console.warn('[ShiftPost] reset failed:', error.message);
  });
  await message.reply(
    `✅ Rebuilt the shift post for **${displayDate}** as an embed — ${claimCount}/${SHIFT_CLAIMING_CONFIG.MAX_SHIFTS_PER_DAY} claimed.`,
  ).catch(() => {});
});

// ─────────────────────────────────────────────────────────────
// Staff presence logging (opt-in via LOG_PRESENCE=true)
// ─────────────────────────────────────────────────────────────
const PRESENCE_LOG_CHANNEL_ID = process.env.PRESENCE_LOG_CHANNEL_ID || "";
const presenceLogDebounce = new Map();
const PRESENCE_DEBOUNCE_MS = 60 * 1000;

function presenceCustomText(presence) {
  const activity = presence?.activities?.find(entry => entry.type === 4); // Custom
  return activity?.state || null;
}

function presenceCategory(status) {
  return status === "offline" ? "offline" : "online";
}

client.on("presenceUpdate", async (oldPresence, newPresence) => {
  if (process.env.LOG_PRESENCE !== "true" || !PRESENCE_LOG_CHANNEL_ID) return;

  const member = newPresence?.member;
  if (!member || member.user?.bot) return;
  if (!newPresence.guild) return;

  try {
    // Staff only — resolve the rank and bail before doing anything expensive.
    const rank = await getVerifiedMainRankForDiscord(member.id).catch(() => 0);
    const staffRank = Number(rank) >= MANAGER_SYSTEM_CONFIG.SHIFT_LEAD_RANK;
    const inferred = staffRank ? null : inferStaffRankFromDiscordRoles(member);
    if (!staffRank && !inferred) return;

    const previousStatus = oldPresence?.status || "offline";
    const currentStatus = newPresence.status || "offline";
    const previousText = presenceCustomText(oldPresence);
    const currentText = presenceCustomText(newPresence);

    const categoryChanged = presenceCategory(previousStatus) !== presenceCategory(currentStatus);
    const textChanged = (previousText || "") !== (currentText || "");
    if (!categoryChanged && !textChanged) return;

    // Debounce: one entry per member per minute.
    const last = presenceLogDebounce.get(member.id) || 0;
    if (Date.now() - last < PRESENCE_DEBOUNCE_MS) return;
    presenceLogDebounce.set(member.id, Date.now());

    const channel = newPresence.guild.channels.cache.get(PRESENCE_LOG_CHANNEL_ID)
      || await newPresence.guild.channels.fetch(PRESENCE_LOG_CHANNEL_ID).catch(() => null);
    if (!channel?.send) return;

    const embed = new EmbedBuilder()
      .setColor(categoryChanged ? 0x2ecc71 : 0x5865f2)
      .setTitle(categoryChanged ? "📋 Presence Update" : "📋 Custom Status Changed")
      .addFields({ name: "👤 Member", value: `<@${member.id}>`, inline: true })
      .setTimestamp();

    if (categoryChanged) {
      embed.addFields({ name: "🔄 Status", value: `${previousStatus} → ${currentStatus}`, inline: true });
    } else {
      embed.addFields(
        { name: "💬 Before", value: previousText ? previousText.slice(0, 100) : "*(none)*", inline: true },
        { name: "💬 After", value: currentText ? currentText.slice(0, 100) : "*(none)*", inline: true },
      );
    }

    await channel.send({ embeds: [embed] }).catch(() => null);
  } catch (error) {
    console.warn("[Presence] log failed:", error.message);
  }
});

